INSERT INTO `all_items` VALUES (686, 'Chair', NULL, 'Стул', 'Chair0', 'etc_branch_blue_i00', 0);
INSERT INTO `all_items` VALUES (687, 'Darin\'s Letter', NULL, 'Любовное письмо, которое Дарин написал Рокси. Дарин просит Вас доставить это письмо Хранителю Врат Рокси.', 'The love letter that Darin has written to Roxxy. Darin has asked you to deliver this letter to Gatekeeper Roxxy.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (688, 'Roxxy\'s Kerchief', NULL, 'Платок Рокси - ответ на письмо Дарина. Отнесите его Дарину.', 'Roxxy\'s handkerchief. This is the reply that Roxxy has given to Darin\'s letter, and must be delivered to Darin.', 'etc_piece_of_cloth_white_i00', 0);
INSERT INTO `all_items` VALUES (689, 'Poetry Book', NULL, 'Сборник стихов Аруена, который содержит написанные им произведения. Отнесите его Гринис.', 'A poetry book treasured by Arujien. The book contains poems that he has written. Take this to Greenis.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (690, 'Lyrics Book', NULL, 'Сборник лирики Гербиэля.', 'The lyrics book of Herbien0', 'item_normal06', 0);
INSERT INTO `all_items` VALUES (691, 'Romance Novel', NULL, 'Роман о любви.', 'A romance novel0', 'item_normal07', 0);
INSERT INTO `all_items` VALUES (692, 'Arujien\'s Letter', NULL, 'Письмо Аруена.', 'Arujien\'s letter0', 'item_canuse37', 0);
INSERT INTO `all_items` VALUES (693, 'Greenis\'s Letter', NULL, 'Письмо Гринис, отвергающей любовь Аруена. Отнесите его Аруену.', 'Greenis\'s letter, refusing Arujien\'s love. Take this to Arujien.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (694, 'Ingredient List', NULL, 'Список ингредиентов: 3 пузырька Крови Зверя Знамения, 2 Скорлупы Пожирателя Энергии, 2 Рога Горгульи.', 'A list of ingredients: 3 omen beast bloods, 2 mana seeker husks, 2 gargoyle horns0', 'item_normal37', 0);
INSERT INTO `all_items` VALUES (695, 'Omen Beast\'s Blood', NULL, 'Кровь из тела Зверя Знамения.', 'The blood of an omen beast.', 'item_canuse48', 0);
INSERT INTO `all_items` VALUES (696, 'Mana Seeker\'s Husk', NULL, 'Скорлупа Пожирателя Энергии.', 'The husk of a mana seeker.', 'item_normal30', 0);
INSERT INTO `all_items` VALUES (697, 'Gargoyle\'s Horn', NULL, 'Рог Горгульи.', 'The horn of a gargoyle.', 'item_normal24', 0);
INSERT INTO `all_items` VALUES (698, 'Gilbert\'s List', NULL, 'Список тех, кого необходимо уничтожить: Орки, Хобгоблины, Ходячие Грибы.', 'A list of things to eliminate: orcs, hobgoblins, walking fungus0', 'item_normal37', 0);
INSERT INTO `all_items` VALUES (699, 'Orc\'s Nose', NULL, 'Нос Орка', 'The nose of an orc.', 'item_canuse05', 0);
INSERT INTO `all_items` VALUES (700, '_', NULL, 'Амулет Хобгоблина', 'The amulet of a hobgoblin.', 'item_normal05', 0);
INSERT INTO `all_items` VALUES (701, 'Fungus Juice', NULL, 'Сок Гриба', 'The juice of a fungus.', 'item_canuse28', 0);
INSERT INTO `all_items` VALUES (702, 'Wolf Pelt', NULL, 'Соберите 40 шкур волков и отнесите их Торговцу Лектору из Оружейной Лавки.', 'Gather forty wolf pelts and take them to Trader Lector of the weapons and armor shop.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (703, 'Giant Spider\'s Poison Sac', NULL, 'Ядовитая Железа, полученная с убитого Гигантского Паука. Отнесите ее Жрецу Йоханесу.', 'Poison sacs obtained from the dead giant spider. Take this to Priest Yohanes.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (704, 'Fever Medicine', NULL, 'Лекарство, приготовленное Жрецом Йоханесом для учеников, больных лихорадкой. Отнесите его Элиасу.', 'A medicine concocted by Priest Yohanes for the students who are ill with fever. Take this to Elias.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (705, '_', NULL, 'Орочий амулет из перьев.', 'An Orc feather amulet.', 'item_normal48', 0);
INSERT INTO `all_items` VALUES (706, 'Basilisk\'s Claw', NULL, 'Коготь Василиска.', 'A basilisk\'s claw.', 'item_normal141', 0);
INSERT INTO `all_items` VALUES (707, 'Spore Sac', NULL, 'Спора, добытая из Гриба. Соберите 10 штук и отнесите их Торговцу Воллодосу.', 'A sac obtained from the spore fungus. Gather 10 of these and take them to Trader Vollodos.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (708, 'Sylph Headband', NULL, 'Обруч Сильфа.', 'A Sylph Headband0', 'item_system03', 0);
