INSERT INTO `all_items` VALUES (725, 'Healing Drug', NULL, 'Магическое снадобье, восстанавливающее HP в течение некоторого времени.', 'A magical, liquid medicine that restores HP for a certain amount of time.', 'etc_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (726, 'Mana Drug', NULL, 'Магическое снадобье, восстанавливающее MP в течение некоторого времени.', 'A magical, liquid medicine that restores MP for a certain amount of time.', 'etc_potion_blue_i00', 3);
INSERT INTO `all_items` VALUES (727, 'Healing Potion', NULL, 'Магическое снадобье, восстанавливающее HP в течение некоторого времени.', 'A magical, liquid medicine that restores HP for a certain amount of time.', 'item_system03', 3);
INSERT INTO `all_items` VALUES (728, 'Mana Potion', NULL, 'Магическое снадобье, восстанавливающее MP в течение некоторого времени.', 'A magical, liquid medicine that restores MP for a certain amount of time.', 'etc_reagent_blue_i00', 3);
INSERT INTO `all_items` VALUES (729, 'Scroll: Enchant Weapon (A-Grade)', NULL, 'Для модификации оружия Ранга А. Одноручный меч, одноручное дробящее, кинжал, древковое: Ф. Атк. +4. Двуручный меч, двуручное дробящее, парные клинки, кастеты: Ф. Атк. +5. Луки: Ф. Атк +8. Все оружие: М. Атк. +3. При модификации на +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасная модификация: +3.', 'When enchanted, the P. Atk. of  A-Grade weapons such as sword/one-handed, blunt weapon/one-handed, dagger and spear etc. will increase by 4.  The P. Atk of  sword/two-handed, blunt weapon/two-handed, dualsword, and fist-fighting weapon/two-handed will increase by 5. The P. Atk. of bow weapons will increase by 8. The M. Atk. of all weapons will increase by 3. From +4, P. Atk. and M. Atk. bonus will double for all weapon types.  It can be safely enchanted up to +3.', 'etc_scroll_of_enchant_weapon_i04', 19);
INSERT INTO `all_items` VALUES (730, 'Scroll: Enchant Armor (A-Grade)', NULL, 'Для модификации доспехов и аксессуаров Ранга A. Дает Ф. Защ. +1. При модификации на +4 и выше дает Ф. Защ. +3. Безопасная модификация: обычный доспех +3, полный доспех +4.', 'Increases the P. Def. of an A-Grade armor or accessory by 1, and from +4, the P. Def will increase by 3. It can be safely enchanted up to +3. One-piece type armor can be safely enchanted up to +4.', 'etc_scroll_of_enchant_armor_i04', 20);
INSERT INTO `all_items` VALUES (731, 'Crystal Scroll: Enchant Weapon (A-Grade)', NULL, 'Свиток модификации оружия Ранга А.', 'A scroll of enchantment that empowers an A-Grade weapon.', 'etc_scroll_of_enchant_weapon_i01', 1);
INSERT INTO `all_items` VALUES (732, 'Crystal Scroll: Enchant Armor (A-Grade)', NULL, 'Свиток модификации брони Ранга А.', 'A scroll of enchantment that empowers an A-Grade armor.', 'etc_scroll_of_enchant_armor_i01', 1);
INSERT INTO `all_items` VALUES (733, 'Endeavor Potion', NULL, 'Магическое зелье, увеличивающее волю.', 'A magical, liquid medicine that increases willpower.', 'etc_lesser_potion_yellow_i00', 3);
INSERT INTO `all_items` VALUES (734, 'Haste Potion', NULL, 'Магическое зелье, увеличивающее скорость передвижения.', 'A magical potion that increases movement speed0', 'etc_potion_green_i00', 3);
INSERT INTO `all_items` VALUES (735, 'Alacrity Potion', NULL, 'Магическое зелье, увеличивающее Скор. Атк.', 'A magical potion that increases attack speed0', 'etc_reagent_green_i00', 3);
INSERT INTO `all_items` VALUES (736, 'Scroll of Escape', NULL, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение.', 'A scroll of enchantment that relocates you to the nearest village.', 'etc_scroll_of_return_i00', 1);
INSERT INTO `all_items` VALUES (737, 'Scroll of Resurrection', NULL, 'Свиток, воскрешающий умершего.', 'A scroll of enchantment that resuscitates a dead person.', 'etc_scroll_of_resurrection_i00', 1);
INSERT INTO `all_items` VALUES (738, 'Sword of Solidarity', NULL, 'Бронзовый меч, созданный много лет назад как символ единства Людей и Эльфов.', 'A bronze sword crafted long ago in memory of the union between the Humans and the Elves.', 'weapon_long_sword_i00', 0);
INSERT INTO `all_items` VALUES (739, 'Broken Sword Handle', NULL, 'Рукоять Меча Единства. Отнесите ее Кузнецу Альтрану.', 'The handle portion of the sword of solidarity. Take this to Blacksmith Alltran.', 'weapon_small_sword_i00', 0);
INSERT INTO `all_items` VALUES (740, 'Broken Blade Bottom', NULL, 'Отнесите эту часть меча вместе с верхней Кузнецу Альтрану.', 'Take this, and the upper portion of the blade to Blacksmith Alltran.', 'weapon_great_sword_i00', 0);
INSERT INTO `all_items` VALUES (741, 'Broken Blade Top', NULL, 'Отнесите эту часть меча вместе с нижней Кузнецу Альтрану.', 'Take this, and the lower portion of the blade to Blacksmith Alltran.', 'etc_sword_body_i00', 0);
INSERT INTO `all_items` VALUES (742, 'Altran\'s Note', NULL, 'Письмо с запросом о получении рукояти меча от Роена. Отнесите его Великому Мастеру Роену в Школу Седрика.', 'A letter requesting the handle of the sword from Roien. Take this to Grand Master Roien of Cedric\'s Training Hall.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (743, 'Sword of Sentinel', NULL, 'Стальной клинок, выдаваемый воинам, защищающим леса.', 'A steel blade issued to those fighters that have been acknowledged as protectors of the woods.', 'weapon_broad_sword_i00', 0);
INSERT INTO `all_items` VALUES (744, 'Staff of Sentinel', NULL, 'Посох, выдаваемый магам, защищающим леса.', 'A staff issued to those magicians that have been acknowledged as protectors of the woods.', 'weapon_cedar_staff_i00', 0);
INSERT INTO `all_items` VALUES (745, 'Cobendell Medicine', NULL, NULL, NULL, 'item_normal40', 0);
INSERT INTO `all_items` VALUES (746, 'Alberius\'s List', NULL, 'Отнесите лекарство Часовому Берросу, Часовому Вельтресу, Часовому Райену и Часовому Гартранделу.', 'Deliver the medicine to Sentinel Berros, Sentinel Veltress, Sentinel Rayen, and Sentinel Gartrandell.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (747, 'Wand of Adept', NULL, 'Скипетр, выдаваемый выпускникам Школы Магии.', 'The wand presented to those who have finished their studies at the school of magic.', 'weapon_apprentices_wand_i00', 0);
