INSERT INTO `all_items` VALUES (937, 'Directions to Ruins', NULL, 'Идите на северо-запад от деревни, затем сверните на запад к Обелиску Победы. Вход в руины находится у подножия горы.', 'Follow the northwestern path from the village, and head west when you meet the Obelisk of Victory. The entrance to the ruins lies at the slope of the mountain.', 'etc_piece_of_paper_gray_i00', 0);
