INSERT INTO `all_items` VALUES (945, 'Skeleton Buckler', NULL, 'Маленький деревянный щит, используемый созданиями магов.', 'A small wooden shield that perpetrators of mages use.', 'shield_skeleton_buckler_i00', 0);
INSERT INTO `all_items` VALUES (946, 'Skeleton Dagger', NULL, NULL, NULL, 'weapon_dagger_i00', 0);
INSERT INTO `all_items` VALUES (947, 'Scroll: Enchant Weapon (B-Grade)', NULL, 'Для модификации оружия Ранга B. Одноручный меч, одноручное дробящее, кинжал, древковое: Ф. Атк. +3. Двуручный меч, двуручное дробящее, парные клинки, кастеты: Ф. Атк. +4. Луки: Ф. Атк +6. Все оружие: М. Атк. +3. При модификации на +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасная модификация: +3.', 'When enchanted, the P. Atk. of B-Grade weapons such as one-handed swords and blunt weapons, daggers and spears increases by 3. The P. Atk of two-handed swords and blunt weapons, dualswords, and two-handed fist-fighting weapons increases by 4. The P. Atk. of bow weapons increases by 6. The M. Atk. of all weapons increases by 3. From +4, P. Atk. and M. Atk. bonus will double for all weapon types.  It can be safely enchanted up to +3.', 'etc_scroll_of_enchant_weapon_i03', 19);
INSERT INTO `all_items` VALUES (948, 'Scroll: Enchant Armor (B-Grade)', NULL, 'Для модификации доспехов и аксессуаров Ранга B. Дает Ф. Защ. +1. При модификации на +4 и выше дает Ф. Защ. +3. Безопасная модификация: обычный доспех +3, полный доспех +4.', 'Increases P. Def. of a B-Grade armor or accessory by 1, and from +4, the P. Def will increase by 3. It can be safely enchanted up to +3. One-piece type armor can be safely enchanted up to +4.', 'etc_scroll_of_enchant_armor_i03', 20);
INSERT INTO `all_items` VALUES (949, 'Crystal Scroll: Enchant Weapon (B-Grade)', NULL, 'Свиток модификации оружия Ранга B.', 'A scroll of enchantment that empowers a B-Grade weapon.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (950, 'Crystal Scroll: Enchant Armor (B-Grade)', NULL, 'Свиток модификации брони Ранга B.', 'A scroll of enchantment that empowers a B-Grade armor.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (951, 'Scroll: Enchant Weapon (C-Grade)', NULL, 'Для модификации оружия Ранга C. Одноручный меч, одноручное дробящее, кинжал, древковое: Ф. Атк. +3. Двуручный меч, двуручное дробящее, парные клинки, кастеты: Ф. Атк. +4. Луки: Ф. Атк +6. Все оружие: М. Атк. +3. При модификации на +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасная модификация: +3.', 'When enchanted, the P. Atk. of C-Grade weapons such as one-handed swords and blunt weapons, daggers and spears increases by 3. The P. Atk of two-handed swords and blunt weapons, dualswords, and two-handed fist-fighting weapons increases by 4. The P. Atk. of bow weapons increases by 6. The M. Atk. of all weapons increases by 3. From +4, P. Atk. and M. Atk. bonus will double for all weapon types.  It can be safely enchanted up to +3.', 'etc_scroll_of_enchant_weapon_i02', 19);
INSERT INTO `all_items` VALUES (952, 'Scroll: Enchant Armor (C-Grade)', NULL, 'Для модификации доспехов и аксессуаров Ранга C. Дает Ф. Защ. +1. При модификации на +4 и выше дает Ф. Защ. +3. Безопасная модификация: обычный доспех +3, полный доспех +4.', 'Increases P. Def. of a C-Grade armor or accessory by 1, and from +4, the P. Def will increase by 3. It can be safely enchanted up to +3. One-piece type armor can be safely enchanted up to +4.', 'etc_scroll_of_enchant_armor_i02', 20);
INSERT INTO `all_items` VALUES (953, 'Crystal Scroll: Enchant Weapon (C-Grade)', NULL, 'Свиток модификации оружия Ранга C.', 'A scroll of enchantment that empowers a C-Grade weapon.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (954, 'Crystal Scroll: Enchant Armor (C-Grade)', NULL, 'Свиток модификации брони Ранга C.', 'A scroll of enchantment that empowers a C-Grade armor.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (955, 'Scroll: Enchant Weapon (D-Grade)', NULL, 'Для модификации оружия Ранга D. Луки: Ф. Атк. +4. Остальные виды оружия: Ф. Атк. +2. Все оружие: М. Атк. +2. При модификации на +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасная модификация: +3.', 'When enchanted the P. Atk. of all D-Grade weapons will increase by 2 with the exception of bows, which will increase by 4. The M. Atk. of all weapons increases by 2. From +4, P. Atk. and M. Atk. bonus will double for all weapon types.  It can be safely enchanted up to +3.', 'etc_scroll_of_enchant_weapon_i01', 19);
INSERT INTO `all_items` VALUES (956, 'Scroll: Enchant Armor (D-Grade)', NULL, 'Для модификации доспехов и аксессуаров Ранга D. Дает Ф. Защ. +1. При модификации на +4 и выше дает Ф. Защ. +3. Безопасная модификация: обычный доспех +3, полный доспех +4.', 'Increases P. Def. of a D-Grade armor or accessory by 1, and from +4, the P. Def will increase by 3. It can be safely enchanted up to +3. One-piece type armor can be safely enchanted up to +4.', 'etc_scroll_of_enchant_armor_i01', 20);
INSERT INTO `all_items` VALUES (957, 'Crystal Scroll: Enchant Weapon (D-Grade)', NULL, 'Свиток модификации оружия Ранга D.', 'A scroll of enchantment that empowers a D-Grade weapon.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (958, 'Crystal Scroll: Enchant Armor (D-Grade)', NULL, 'Свиток модификации брони Ранга D.', 'A scroll of enchantment that empowers a D-Grade armor.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (959, 'Scroll: Enchant Weapon (S-Grade)', NULL, 'Для модификации оружия Ранга S. Одноручный меч, одноручное дробящее, кинжал, древковое: Физ. Атк. +5. Двуручный меч, двуручное дробящее, парные клинки, кастеты: Физ. Атк. +6. Луки: Физ. Атк +10. Все оружие: Маг. Атк. +4. При модификации на +4 и выше бонус к Физ. Атк. и Маг. Атк. удваивается.', 'When enchanted, the P. Atk. of S grade weapons such as one-handed swords and blunt weapons, daggers and spears increases by 5. The P. Atk of two-handed swords and blunt weapons, dualswords, and two-handed fist-fighting weapons increases by 6. The P. Atk. of bow weapons increases by 10. The M. Atk. of all weapons increases by 4. From +4, P. Atk. and M. Atk. bonus will double for all weapon types.  It can be safely enchanted up to +3.', 'etc_scroll_of_enchant_weapon_i05', 19);
INSERT INTO `all_items` VALUES (960, 'Scroll: Enchant Armor (S-Grade)', NULL, 'Для модификации доспехов и аксессуаров Ранга S. Дает Ф. Защ. +1. При модификации на +4 и выше дает Ф. Защ. +3. Безопасная модификация: обычный доспех +3, полный доспех +4.', 'When enchanted, increases P. Def. of S grade armor or accessory by 1, and from +4, the P. Def increases by 3. It can be safely enchanted up to +3. One-piece armor can be safely enchanted up to +4.', 'etc_scroll_of_enchant_armor_i05', 20);
INSERT INTO `all_items` VALUES (961, 'Crystal Scroll: Enchant Weapon (S-Grade)', NULL, 'Свиток модификации оружия Ранга S.', 'A scroll of enchantment that empowers a S Grade weapon.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (962, 'Crystal Scroll: Enchant Armor (S-Grade)', NULL, 'Свиток модификации брони Ранга S.', 'A scroll of enchantment that empowers a S Grade armor0', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (963, 'Orcish Arrowhead', NULL, 'Наконечник стрелы, которую используют Снайперы Орков Тунат на Говорящем Острове. Соберите эти наконечники и принесите их Мастеру Минии.', 'An arrowhead that Turath orc marksmen use on Talking Island. Collect these and take to Master Minia.', 'weapon_winged_spear_i00', 0);
INSERT INTO `all_items` VALUES (964, 'Alberius\'s Letter', NULL, 'Письмо Альберия для Мастера Кобенделлу.', 'A letter from Alberius. Take this to Master Cobendell.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (965, 'Evergreen Amulet', NULL, 'Ожерелье с зеленым камнем. Оно должно быть у Вас, чтобы Вы могли получить слезы убитых Дриад.', 'A necklace set with a green elemental stone. You must possess this to slay the dryad and obtain the dryad\'s tears.', 'accessary_near_forest_necklace_i00', 0);
INSERT INTO `all_items` VALUES (966, 'Dryad\'s Tears', NULL, 'Алмаз, содержащий в себе эссенцию души Дриады. Соберите 10 штук и отнесите их Мастеру Кобенделлу.', 'A jewel that contains the essence of a dryad\'s soul. Gather ten of these and take them to Master Cobendell.', 'etc_crystal_ball_green_i00', 0);
INSERT INTO `all_items` VALUES (967, 'Cobendell Medicine', NULL, 'Лекарство Мастера Кобенделла.', 'Cobendell\'s medicine0', 'item_canuse24', 0);
INSERT INTO `all_items` VALUES (968, 'Karrod\'s Letter', NULL, 'Письмо, написанное Кузнецом Кэрродом. Отнесите его Служителю Бездны Кектинону в Храме Шилен.', 'A letter written by Blacksmith Karrod. Take this to the Abyssal Celebrant Cecktinon in the Shilen Temple.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (969, 'Cecktinon\'s First Voucher', NULL, 'Письмо от Служителя Бездны Кектинона. Отнесите его Магистру Харн в деревню.', 'An introduction letter from the Abyssal Celebrant Cecktinon. Take this and seek Magister Harne in the village.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (970, 'Cecktinon\'s Second Voucher', NULL, 'Записка от Магистра Харн. Отправляйтесь в Школу Темной Магии и соберите 10 Обломков Костей Скелетов.', 'An introduction letter from the Abyssal Celebrant Cecktinon. Go to the School of Dark Arts, hunt skeletons, and gather 10 bone fragments.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (971, 'Soul Catcher', NULL, 'Предмет для ритуала вызова души умершего. Отнесите его Служителю Бездны Кектинону.', 'An item used during the exorcism ritual to call upon a spirit of the dead. Take this to the Abyssal Celebrant Cecktinon.', 'weapon_voodoo_doll_i00', 0);
INSERT INTO `all_items` VALUES (972, 'Preserving Oil', NULL, 'Масло, предотвращающее разложение трупа. Возьмите его на охоту на Зомби в Болотах.', 'An oil that when used, prevents the rotting of corpses. Take this and go hunt zombies in the swamps.', 'etc_potion_clear_i00', 0);
INSERT INTO `all_items` VALUES (973, 'Zombie Head', NULL, 'Голова Зомби, бывшего когда-то лесным эльфом. Отнесите ее Служителю Бездны Кектинону.', 'The head of tree Elf zombies that have been cut after they are defeated. Take this to the abyssal celebrant Cecktinon.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (974, 'Steelbender Head', NULL, 'Пожалуйста, не отдавайте меня этому жестокому кузнецу!', 'Please, I beg of you!  Don\'t take me to that brutal blacksmith!', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (975, 'Blood Saber', NULL, 'Орихаруконовый меч в стиле Авеллы, изготовленный где-то на востоке.', 'An Oriharukon sword crafted in the Abella style of the east.', 'weapon_broad_sword_i00', 0);
INSERT INTO `all_items` VALUES (976, '1st Mark of Sentinel', NULL, 'Знак принадлежности к Эльфийским Часовым. Уничтожьте Тануки Крушителя Черепов и отчитайтесь Часовому Кенделлу.', 'A mark that certifies that its bearer is an Elven Sentinel. Destroy an orc Tanuki skullcrusher and report to Sentinel Kendell.', 'item_system03', 0);
INSERT INTO `all_items` VALUES (977, '2nd Mark of Sentinel', NULL, 'Знак принадлежности к Эльфийским Часовым. Уничтожьте Бато Кровавое Копье и отчитайтесь Часовому Кенделлу.', 'A mark that certifies that its bearer is an Elven Sentinel. Destroy an orc Bhato bloodspear and report to Sentinel Kendell.', 'item_system03', 0);
INSERT INTO `all_items` VALUES (978, 'Skullcrusher Amulet', NULL, 'Амулет племени Орков Крушителей Черепов. Отнесите его Часовому Кенделлу.', 'The amulet that represents the Skullcrusher Orc tribe. Take this to Sentinel Kendell.', 'item_normal145', 0);
INSERT INTO `all_items` VALUES (979, 'Bloodspear Amulet', NULL, 'Амулет племени Орков Кровавого Копья. Отнесите его Часовому Кенделлу.', 'The amulet that represents the Bloodspear Orc tribe. Take this to Sentinel Kendell.', 'item_normal89', 0);
INSERT INTO `all_items` VALUES (981, 'Red Sunset Sword', NULL, 'Меч, использовавшийся воинами Клана Багрового Заката.', 'A sword used by warriors belonging to the Red Sunset clan.', 'weapon_brandish_i00', 0);
INSERT INTO `all_items` VALUES (982, 'Esrandell\'s Letter', NULL, 'Рекомендация Исрандела.', 'Esrandell\'s introduction0', 'item_normal20', 0);
INSERT INTO `all_items` VALUES (983, 'Kendell\'s Letter', NULL, 'Письмо Кенделла.', 'Kendell\'s letter0', 'item_normal20', 0);
INSERT INTO `all_items` VALUES (984, '1st Onyx Talisman', NULL, 'Ожерелье, изготовленное из оникса. Отнесите его Служителю Бездны Картии.', 'A necklace crafted of onyx. Take this to Abyssal Celebrant Kartia.', 'accessary_sages_necklace_i00', 0);
INSERT INTO `all_items` VALUES (985, '2nd Onyx Talisman', NULL, 'Ожерелье, изготовленное из оникса. Найдите свитки у Орков Тумран и отнесите их Служителю Бездны Картии.', 'A necklace crafted of onyx. Recover the original scrolls from the blackskull Orcs and bring them to Abyssal Celebrant Kartia.', 'accessary_sages_necklace_i00', 0);
INSERT INTO `all_items` VALUES (986, 'Ancient Scroll', NULL, 'Древний свиток, называемый \"Откровениями Кайши\". Отнесите его и Глиняную Табличку Служителю Бездны Картии.', 'An ancient scroll called Kaysha\'s Revelation. Take it along with the clay tablet to Abyssal Celebrant Kartia.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (987, 'Ancient Clay Tablet', NULL, 'Древняя глиняная табличка с текстом. Отнесите ее и Древний Свиток Служителю Бездны Картии.', 'An ancient clay tablet engraved with text. Take it along with the ancient scroll to Abyssal Celebrant Kartia.', 'etc_plate_glay_i00', 0);
INSERT INTO `all_items` VALUES (988, 'Kartia\'s Translation', NULL, '\"Откровения Кайши\" в переводе Картии. Отнесите его Тетрарху Тифиэлю.', 'Kartia\'s translation of Kaysha\'s Revelations. Take it to Tetrarch Thifiell.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (989, 'Eldritch Dagger', NULL, 'Стальной кинжал с вырезанными рунами Шилен и Гран Каина.', 'A steel dagger engraved with the runes of Shilen and Gran Kain.', 'weapon_knife_i00', 0);
