INSERT INTO `all_items` VALUES (1008, 'Harrys\'s 1st Receipt', NULL, 'Расписка, полученная Харрисом после заказа инструментов. Отнесите ее Кузнецу Альтрану.', 'A receipt Harrys received after ordering tools. Take this and go to Blacksmith Alltran.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1009, 'Harrys\'s 2nd Receipt', NULL, 'Расписка, полученная Харрисом после составления заказа на его инструменты. Соберите Осколки Голема, необходимые для создания инструмента.', 'The receipt that Harrys has received after placing an order for his tools. Go and gather golem shards needed for creating the tool.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1010, 'Golem Shard', NULL, 'Осколки камня, упавшие с тела Голема. Соберите 5 осколков и отнесите их Кузнецу Альтрану.', 'Shards of rock that have fallen from the golem\'s body. Gather five of these and take them to Blacksmith Alltran.', 'etc_lump_black_i00', 0);
INSERT INTO `all_items` VALUES (1011, 'Tool Box', NULL, 'Ящик, содержащий изготовленные Кузнецом Альтраном инструменты. Отнесите его Магистру Харрису.', 'A toolbox containing the tools that Blacksmith Alltran has forged. Take this to Magister Harrys at the temple.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1012, 'Delivery List', NULL, 'Отнесите Тяжелый Деревянный Ящик Торговцу Джексону, Моток Ткани - Торговцу Сильвии, а Глиняный Горшок - Смотрителю Склада Ранту.', 'Take the heavy wooden box to Trader Jackson. The bolts of cloth to Trader Silvia. Take the clay pot to the warehouse keeper Rant.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1013, 'Heavy Wood Box', NULL, 'Деревянный ящик, который необходимо отнести Торговцу Джексону, работающему в оружейном магазине.', 'The wooden box to be delivered to Trader Jackson of the weapons shop.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1014, 'Cloth Bundle', NULL, 'Моток ткани, который необходимо отнести Торговцу Сильвии в бакалейную лавку.', 'Bolts of cloth that need to be delivered to Trader Silvia of the grocery store.', 'etc_piece_of_cloth_blue_i00', 0);
INSERT INTO `all_items` VALUES (1015, 'Clay Pot', NULL, 'Глиняный горшок, который необходимо отнести Смотрителю Склада Ранту.', 'The clay pot that must be delivered to the warehouse keeper Rant.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (1016, 'Jackson\'s Receipt', NULL, 'Расписка Торговца Джексона о получении Деревянного Ящика. Отнесите ее Стражу Арнольду.', 'The receipt that Jackson has issued upon receiving his wooden box. Take this to Guard Arnold.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1017, 'Silvia\'s Receipt', NULL, 'Расписка Торговца Сильвии о получении Мотка Ткани. Отнесите ее Стражу Арнольду.', 'The receipt that Silvia has issued upon receiving her bolts of cloth. Take this to Guard Arnold.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1018, 'Rant\'s Receipt', NULL, 'Расписка Смотрителя Склада Ранта о получении Глиняного Горшка. Отнесите ее Стражу Арнольду.', 'The receipt issued by Rant upon his receiving of the clay pot. Take this to Guard Arnold.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1019, 'Official Letter', NULL, 'Официальное письмо с просьбой о встрече, которую Лорд Глудио послал сэру Коллину Виндавуду. Отнесите его сэру Виндавуду.', 'An official letter that the Lord of Gludio has sent to Sir Colin Windawood, calling a meeting. Deliver this to Sir Windawood.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1020, 'Flame Shard', NULL, 'Осколок огненной руды, полученный от Огненной Саламандры. Отдайте его Торговцу Катерине.', 'A fragment of soul ore of fire. Can be taken from the fire spirit salamander. Give it to Trader Katerina.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (1021, 'Ice Shard', NULL, 'Осколок Камня Воды, полученный от Водяной Ундины. Отдайте его Торговцу Катерине.', 'A fragment of elemental stone of water. Can be taken from the water spirit undine. Give to Trader Katerina.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (1022, 'Lilith\'s Letter', NULL, 'Письмо Лилит, написанное возлюбленному, пропавшему тысячу лет назад. Узнайте для нее новости о ее возлюбленном.', 'A letter written by Lilith in longing for her lover, separated a thousand years ago. Find out news about her lover for her.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1023, 'Theon\'s Diary', NULL, 'Дневник Теона со строками о его возлюбленной. Отнесите его Лилит.', 'A diary written by Theon in longing for his lover, separated a thousand years ago. Take this to Lilith.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1024, 'Adamantite Ore', NULL, 'Адамантитовая руда, привезенная из Грации. Соберите 20 штук этой руды и отнесите Смотрителю Склада Вильфорду.', 'Adamantite ore. All of it is imported from Gracia. Gather 20 of these and take them to Warehouse Keeper Wilford.', 'etc_plate_blue_i00', 0);
INSERT INTO `all_items` VALUES (1025, 'Clay Tablet', NULL, 'Табличка демона Неркаса, прославляющая Белефа. Отнесите ее Верховному Жрецу Биотину.', 'A tablet praising Beleth that the devil Nerkas possessed. Deliver this to High Priest Biotin.', 'etc_plate_glay_i00', 0);
INSERT INTO `all_items` VALUES (1026, 'Silvery Spidersilk', NULL, 'Шелк паука. Отнесите его Торговцу Унорену в оружейный магазин.', 'The spider silk of the silver spider. Take this to Trader Unoren of the weapons shop.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (1027, 'Unoren\'s Receipt', NULL, 'Расписка Унорена. Отнесите ее Торговцу Кримису.', 'The receipt issued by the magic shop. Take this and go to Trader Creamees.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1028, 'Creamees\'s Ticket', NULL, 'Билет, выданный Складом. Отнесите его Смотрителю Склада Джулии.', 'A ticket issued by the warehouse. Take this and go to Warehouse Keeper Julia.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (1029, 'Nightshade Leaf', NULL, 'Лист белладонны. Отнесите его Нерупе.', 'The leaf of the nightshade plant. Take this to Nerupa.', 'etc_herb_blue_i00', 0);
INSERT INTO `all_items` VALUES (1030, 'Cracked Skull', NULL, 'Треснувший череп Темного Ужаса. Отнесите его Магистру Влэсти.', 'The cracked skull of the Dark Horror. Take this to Magister Vlasty.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1031, 'Perfect Skull', NULL, 'Череп Темного Ужаса. Отнесите его Магистру Влэсти.', 'Skull of the dark horror. Take this to Magister Vlasty.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (1032, 'Fox Fur', NULL, 'Мягкий мех, идеально подходит для создания нитей и пряжи. Отнесите его Кристел.', 'A mane of keltirs. It is soft and luxurious, and used to spin thread and yarn. Take this to Cristel.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (1033, 'Fox Fur Yarn', NULL, 'Пряжа из меха. Отнесите ее Смотрителю Склада Ролфе, чтобы он смог сделать волосы для куклы.', 'Yarn spun out of the fur of keltirs. Take this to the former tailor Warehouse Keeper Rolfe, and he will make it into the doll\'s hair.', 'etc_skein_gray_i00', 0);
INSERT INTO `all_items` VALUES (1034, 'Maiden Doll', NULL, 'Кукла, напоминающая человеческую девушку. Отнесите ее Смотрителю Маяка Роксвеллу.', 'A doll resembling a Human maiden. Take this to Lighthouse Keeper Rockswell.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (1035, 'Plague Dust', NULL, 'Пыль, полученная с останков Чумного Зомби. Отнесите ее Иерарху Астериосу.', 'A powder obtained from the plague zombie. Take this to Hierarch Asterios.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (1036, 'Andellia\'s Letter', NULL, 'Письмо Анделии к ее сестре Талии с просьбой прислать ей плод Древа Жизни.', 'A letter from Andellia asking her sister Thalia to send her the fruit of the Mother Tree.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1037, 'Fruit of the Mother Tree', NULL, 'Плод, который Древо Жизни приносит раз в несколько лет. Отнесите его Анделии.', 'Fruit that the Mother Tree bears once every few years. Take this to Andellia.', 'etc_fruit_green_i00', 0);
INSERT INTO `all_items` VALUES (1038, 'Rumiel\'s 1st Poem', NULL, 'Свиток с первой поэмой Румиэля Лунный Свет. Соберите все четыре поэмы и отнесите их Часовому Стардену.', 'The scroll containing Rumiel Moonshine\'s first poem. Gather all four and take them to Sentinel Starden.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1039, 'Rumiel\'s 2nd Poem', NULL, 'Свиток со второй поэмой Румиэля Лунный Свет. Соберите все четыре поэмы и отнесите их Часовому Стардену.', 'The scroll containing Rumiel Moonshine\'s second poem. Gather all four and take them to Sentinel Starden.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1040, 'Rumiel\'s 3rd Poem', NULL, 'Свиток с третьей поэмой Румиэля Лунный Свет. Соберите все четыре поэмы и отнесите их Часовому Стардену.', 'The scroll containing Rumiel Moonshine\'s third poem. Gather all four and take them to Sentinel Starden.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1041, 'Rumiel\'s 4th Poem', NULL, 'Свиток с четвертой поэмой Румиэля Лунный Свет. Соберите все четыре поэмы и отнесите их Часовому Стардену.', 'The scroll containing Rumiel Moonshine\'s fourth poem. Gather all four and take them to Sentinel Starden.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1042, 'Wererat\'s Fang', NULL, 'Клык мертвого Крысолюда. Соберите их и отнесите Мастеру Элинии.', 'The fang of a dead ratman. Collect these to take to Master Ellenia.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1043, 'Varool Foulclaw\'s Fang', NULL, 'Клык Варула Грязного Когтя, вожака Крысолюдов. Отнесите его Мастеру Элинии.', 'The fang of Varool Foulclaw, leader of the ratmen. Take this to Master Ellenia.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1044, 'Kirunak Skull', NULL, 'Череп Кирунака, полученный после его смерти. Отнесите его Торговцу Кримису.', 'Kirunak\'s skull obtained after killing Kirunak, the leader of the drevanuls. Take this to Trader Creamees.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (1045, 'Zombie\'s Skin', NULL, 'Кожа Болотного Зомби. Соберите 5 штук и отнесите Торговцу Миналесу.', 'A skin obtained from marshland zombies. Collect five and go to Trader Minaless.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (1046, 'Nightmare Crystal', NULL, 'Кристалл, использованный Суккубом Меркенис для призыва кошмаров. Отнесите его Тетрарху Велиору.', 'A crystal used by the succubus Merkenis to cast nightmares. Take this to Tetrarch Vellior.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (1047, 'Spellbook: Light', NULL, 'Книга, необходимая для изучения умения \"Легкость\".', 'Spellbook needed to learn Light.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1048, 'Spellbook: Might', NULL, 'Книга, необходимая для изучения умения \"Могущество\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Might. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1049, 'Spellbook: Ice Bolt', NULL, 'Книга, необходимая для изучения умения \"Ледяной Шип\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Ice Bolt. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (1050, 'Spellbook: Battle Heal', NULL, 'Книга, необходимая для изучения умения \"Боевое Лечение\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 14.', 'Spellbook needed to learn Battle Heal. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (1051, 'Spellbook: Vampiric Touch', NULL, 'Книга, необходимая для изучения умения \"Прикосновение Вампира\". Профессии: Мистик, Темный Мистик.Необходимый уровень: 14.', 'Spellbook needed to learn Vampiric Touch. Used by Human Mystics and Dark Mystics.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1052, 'Spellbook: Flame Strike', NULL, 'Книга, необходимая для изучения умения \"Удар Пламени\". Профессии: Маг, Светлый Маг, Темный Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Flame Strike. Used by Human Wizards, Elven Wizards and Dark Wizards.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (1053, 'Spellbook: Cure Poison', NULL, 'Книга, необходимая для изучения умения \"Излечить Отравление\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Cure Poison. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (1054, 'Spellbook: Group Heal', NULL, 'Книга, необходимая для изучения умения \"Групповое Лечение\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 14.', 'Spellbook needed to learn Group Heal. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (1055, 'Spellbook: Curse: Poison', NULL, 'Книга, необходимая для изучения умения \"Проклятие: Яд\". Профессии: Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Curse: Poison. Used by Human Mystics and Dark Mystics.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1056, 'Spellbook: Curse: Weakness', NULL, 'Книга, необходимая для изучения умения \"Проклятие: Слабость\". Профессии: Мистик, Светлый Мистик.Необходимый уровень: 14.', 'Spellbook needed to learn Curse: Weakness. Used by Human Mystics and Elven Mystics.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1057, 'Spellbook: Summon Meal', NULL, 'Книга, необходимая для изучения умения \"Создание Еды\". Профессии: Мистик, Светлый Мистик.', 'Spellbook needed to learn Summon Meal. Used by Human Mystics and Elven Mystics.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1058, 'Spellbook: Shield', NULL, 'Книга, необходимая для изучения умения \"Щит\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Shield. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1059, 'Spellbook: Know Enemy', NULL, 'Книга, необходимая для изучения умения \"Познание Врага\".', 'Spellbook needed to learn Know Enemy.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1060, 'Lesser Healing Potion', NULL, 'Магическое зелье, медленно восстанавливающее HP. Время действия - 15 секунд.', 'A magical potion that slowly restores HP. Low endurance.', 'etc_lesser_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (1061, 'Greater Healing Potion', NULL, 'Магическое зелье, медленно восстанавливающее HP. Время действия - 15 секунд.', 'A magical potion that slowly restores HP. High endurance.', 'etc_potion_scarlet_i00', 3);
INSERT INTO `all_items` VALUES (1062, 'Haste Potion', NULL, 'Магическое зелье, увеличивающее скорость передвижения.', 'A magical potion that increases speed.', 'etc_reagent_green_i00', 3);
INSERT INTO `all_items` VALUES (1063, 'Tutorial Parchment', NULL, 'Пергамент, который необходимо отнести Великому Мастеру Роену.', 'Take the tutorial parchment to Grand Master Roien.', 'item_canuse15', 0);
INSERT INTO `all_items` VALUES (1064, 'Tutorial Parchment', NULL, 'Пергамент, который необходимо отнести Великому Мастеру Роену.', 'Take the tutorial parchment to Grand Master Roien.', 'item_canuse15', 0);
INSERT INTO `all_items` VALUES (1065, 'Tutorial Parchment', NULL, 'Пергамент, который необходимо отнести Нерупе.', 'Take the tutorial parchment to Nerupa.', 'item_canuse15', 0);
INSERT INTO `all_items` VALUES (1066, 'Tutorial Parchment', NULL, 'Пергамент, который необходимо отнести Митраэлю, главе Темных Эльфов.', 'Take the tutorial parchment to Mitraell, the chief of Dark Elves.', 'item_canuse15', 0);
INSERT INTO `all_items` VALUES (1067, 'Recommendation', NULL, 'Рекомендация, которую необходимо отнести Великому Мастеру Роену.', 'Take the recommendation to Grand Master Roien.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1068, 'Recommendation', NULL, 'Рекомендация, которую необходимо отнести Великому Магистру Галлинту.', 'Take the recommendation to Grand Magister Gallint.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1069, 'Leaf of the Mother Tree', NULL, 'Лист Древа Жизни, который необходимо отнести Нерупе.', 'Take the leaf of the Mother Tree to Nerupa.', 'etc_leaf_green_i00', 0);
INSERT INTO `all_items` VALUES (1070, 'Blood of Mitraell', NULL, 'Кровь, которую необходимо отнести Иерарху Митраэлю.', 'Take the blood of Mitraell to Hierarch Mitraell.', 'etc_spirit_bullet_red_i00', 0);
INSERT INTO `all_items` VALUES (1071, 'Hyacinth Charm', NULL, 'Оберег, выданный Иерархом Астериосом. Отправляйтесь к источнику, чтобы найти тех, кто его загрязняет.', 'A charm given by Hierarch Asterios. Go to the water source to seek those who pollute the waters of the elven village.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1072, 'Hyacinth Charm', NULL, 'Оберег, выданный Иерархом Астериосом. Отправляйтесь к источнику и соберите 5 пригоршней праха Чумных Зомби.', 'A charm given by Hierarch Asterios. Go to the water source and obtain five handfuls of plague dust from the zombies.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1073, 'Beginner\'s Potion', NULL, 'Слабое магическое зелье, медленно восстанавливающее HP.', 'A magical potion that slowly restores HP. Low endurance.', 'etc_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (1074, 'Boat Ticket: Talking Island to Gludin', NULL, 'Билет на корабль, идущий с Говорящего Острова в гавань Глудина.', 'Boat Ticket: Depart Talking Island - Arrive Gludin Harbor0', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (1075, 'Boat Ticket: Gludin to Talking Island', NULL, 'Билет на корабль, идущий из гавани Глудина на Говорящий Остров.', 'Boat Ticket: Depart Gludin Harbor - Arrive Talking Island0', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (1076, 'Carlon\'s Letter', NULL, 'Финансовый отчет Гильдии Железных Врат за первое полугодие: баланс и отчет о прибылях и убытках филиала гильдии в Деревне Темных Эльфов.', 'First half year financial summary of the Iron Gate Guild: balance sheet and profit and loss statement of the Dark Elf Village guild.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1077, 'Venom Sac', NULL, 'Мешочек паука, наполненный ядом. Соберите 10 штук и отнесите Астарону.', 'A poison sac of poisonous spider. Gather ten of these and take to Astaron.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (1078, 'Wind Shard', NULL, 'Осколок Камня Ветра, полученный от Лирейн, духа Ветра. Соберите осколки и отнесите Ризраэлю.', 'A fragment of the elemental stone of wind. You can get them from lirein, the wind spirits. Collect these to take to Rizraell.', 'etc_crystal_white_i00', 0);
INSERT INTO `all_items` VALUES (1079, 'Darin\'s Receipt', NULL, 'Расписка Дарина о получении магического зелья. Отнесите ее Баулро.', 'A receipt for a magical potion Darin received after paying Baulro. This must be handed to Baulro.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1080, 'Baulro\'s Potion', NULL, 'Зелье смелости, которое Баулро создал специально для застенчивого Дарина. Эффект этого зелья неизвестен. Отнесите его Дарину.', 'A potion of courage that Baulro has created for the shy Darin, but its effects are unknown. This must be delivered to Darin.', 'etc_lesser_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (1081, 'Omen Beast\'s Eye', NULL, 'Первый материал из трех запрошенных Тетрархом Таллотом.', 'The first of three materials Tetrarch Talloth asked you to collect.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (1082, 'Taint Stone', NULL, 'Второй материал из трех запрошенных Тетрархом Таллотом.', 'The second of three materials Tetrarch Talloth asked you to collect.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (1083, 'Succubus Blood', NULL, 'Третий материал из трех запрошенных Тетрархом Таллотом.', 'The third of three materials Tetrarch Talloth asked you to collect.', 'etc_lesser_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (1084, 'Gludio Lord\'s Mark', NULL, 'Знак, указывающий на то, что его владелец действует от имени Лорда Глудио. Держите его при себе во время охоты на Орков и Оборотней.', 'A mark indicating that the bearer is carrying out the orders of the lord. Keep this in your possession and hunt Orcs or werewolves.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (1085, 'Orc\'s Necklace', NULL, 'Костяное ожерелье, используемое Орками-воинами для магических ритуалов. Отнесите его Капитану Гилберту.', 'A bone necklace that Orc fighters possess on their bodies for magic purposes. Take this to Captain Gilbert.', 'accessary_necklace_of_anguish_i00', 0);
INSERT INTO `all_items` VALUES (1086, 'Werewolf\'s Fang', NULL, 'Клык Оборотня. Отнесите его Капитану Гилберту.', 'Fangs from a dead werewolf. Take this to Captain Gilbert.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1087, 'Giant Spider\'s Leg', NULL, 'Лапка, отрезанная у Гигантского Паука. Соберите 8 штук и отнесите их Алшупесу.', 'The legs cut off from a giant spider. Collect 8 of these and take them to Alshupes.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1088, 'Undrias\'s Letter', NULL, 'Письмо Служителя Бездны Андриаса. Отнесите его Торговцу Ирине, Смотрителю Склада Доранкусу и Мастеру Тради.', 'Abyssal Celebrant Undrias\'s letter. Take this letter to Trader Iria, Warehouse Keeper Dorankus, and Master Trudy.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1089, 'Ceremonial Dagger', NULL, 'Церемониальный кинжал, использующийся в темной мессе. Отнесите его Служителю Бездны Андриасу.', 'A ceremonial dagger used during the mass of darkness. Take this to Abyssal Celebrant Undrias.', 'weapon_mystic_knife_i00', 0);
INSERT INTO `all_items` VALUES (1090, 'Dreviant Wine', NULL, 'Вино, использующееся в темной мессе. Отнесите его Служителю Бездны Андриасу.', 'Holy wine used in the mass of darkness. Take this to Abyssal Celebrant Undrias.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (1091, 'Garmiel\'s Scripture', NULL, 'Писание, использующееся в темной мессе. Отнесите его Служителю Бездны Андриасу.', 'The scripture used during the mass of darkness. Take this to Abyssal Celebrant Undrias.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1092, 'Arujien\'s Letter', NULL, 'Письмо Аруена для Гринис. Отнесите его Хранителю Портала Мирабель.', 'The letter that Arujien has written in longing for Greenis. Show this to Gatekeeper Mirabel.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1093, 'Arujien\'s Letter', NULL, 'Письмо Аруена для Гринис. Отнесите его Торговцу Гербиэлю.', 'The letter that Arujien has written in longing for Greenis. Show this to Trader Herbiel.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1094, 'Arujien\'s Letter', NULL, 'Любовное послание Аруена. Поскольку Вы уже показали его Мирабель и Гербиэлю, возвращайтесь к Аруену.', 'Arujien\'s love letter. Since you have shown this to Mirabel and Herbiel, you must go back to Arujien.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1095, 'Spellbook: Attack Aura', NULL, 'Книга, необходимая для изучения умения \"Аура Атаки\". Профессии: Светлый Воин, Темный Воин.Необходимый уровень: 10.', 'Spellbook needed to learn Attack Aura. Used by Elven Fighters and Dark Fighters.', 'etc_spell_books_defighter_i00', 0);
INSERT INTO `all_items` VALUES (1096, 'Spellbook: Elemental Heal', NULL, 'Книга, необходимая для изучения умения \"Природное Лечение\". Профессия: Светлый Воин.Необходимый уровень: 15.', 'Spellbook needed to learn Elemental Heal. Used by Elven Fighters.', 'etc_spell_books_efighter_i00', 0);
INSERT INTO `all_items` VALUES (1097, 'Spellbook: Drain Health', NULL, 'Книга, необходимая для изучения умения \"Кража Жизни\". Профессии: Рыцарь, Темный Воин.Необходимый уровень: Темный Воин - 15, Рыцарь - 20.', 'Spellbook needed to learn Drain Health. Used by Human Knights and Dark Fighters.', 'etc_spell_books_defighter_i00', 0);
INSERT INTO `all_items` VALUES (1098, 'Spellbook: Wind Walk', NULL, 'Книга, необходимая для изучения умения \"Легкая Походка\". Профессии: Клерик, Оракул Евы, Оракул Шилен.Необходимый уровень: 20.', 'Spellbook needed to learn Wind Walk. Used by Clerics, Elven Oracles and Shillien Oracles.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1099, 'Spellbook: Wind Shackle', NULL, 'Книга, необходимая для изучения умения \"Оковы Ветра\". Профессии: Светлый Мистик, Темный Мистик.Необходимый уровень: 14.', 'Spellbook needed to learn Wind Shackle. Used by Elven Mystics and Dark Mystics.', 'etc_spell_books_black_i00', 0);
