INSERT INTO `all_items` VALUES (1135, 'Spiritbound Wand', NULL, 'Посох, в котором заперт Дух Зеркал. Поймайте с его помощью всех трех Духов и отнесите Великому Магистру Галлинту.', 'The wand where the spirit of mirrors is bound to. Trap all three spirits of mirrors into the wand and take it to Grand Magister Gallint.', 'weapon_club_i01', 0);
INSERT INTO `all_items` VALUES (1136, 'Spiritbound Wand', NULL, 'Посох, в котором заперт Дух Зеркал. Поймайте с его помощью всех трех Духов и отнесите Великому Магистру Галлинту.', 'The wand where the spirit of mirrors is bound to. Trap all three spirits of mirrors into the wand and take it to Grand Magister Gallint.', 'weapon_club_i01', 0);
INSERT INTO `all_items` VALUES (1137, 'Spiritbound Wand', NULL, 'Посох, в котором заперт Дух Зеркал. Поймайте с его помощью всех трех Духов и отнесите Великому Магистру Галлинту.', 'The wand where the spirit of mirrors is bound to. Trap all three spirits of mirrors into the wand and take it to Grand Magister Gallint.', 'weapon_club_i01', 0);
INSERT INTO `all_items` VALUES (1138, 'Auron\'s Letter', NULL, 'Письмо, написанное Мастером Ауроном. Отнесите его Торговцу Симплону в Глудио.', 'A letter written by Master Auron. Take this to Trader Simplon in the Town of Gludio.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1139, 'Warrior Guild Mark', NULL, 'Знак, указывающий на принадлежность к Гильдии Воителей. Держите его при себе во время охоты на Скелетов Следопытов в Руинах Страданий.', 'A mark that shows that player is a member of the Warrior Guild. Take this to the Ruins of Agony and kill tracker skeletons.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (1140, 'Rusted Bronze Sword', NULL, 'Старый бронзовый меч, используемый Скелетами Следопытами. Соберите 10 штук и отнесите Торговцу Симплону.', 'An old bronze sword used by tracker skeletons. Collect ten and give them to Trader Simplon.', 'weapon_broad_sword_i00', 0);
INSERT INTO `all_items` VALUES (1141, 'Rusted Bronze Sword', NULL, 'Ржавый бронзовый меч, который, по словам Торговца Симплона, является Мечом Испытаний. Отнесите его Мастеру Аурону.', 'An old and rusted bronze sword given by Trader Simplon, who said it was a \'Sword of Trial\'.Take this to Master Auron.', 'weapon_broad_sword_i00', 0);
INSERT INTO `all_items` VALUES (1142, 'Rusted Bronze Sword', NULL, 'Старый бронзовый меч, известный также как \"Меч Испытаний\". Используйте его для охоты на Ядовитых Пауков и Арахнидов Охотников.', 'An old and rusty bronze sword called the \'Sword of Trial\'. Use this to hunt poison spiders and arachnid trackers.', 'weapon_broad_sword_i00', 0);
INSERT INTO `all_items` VALUES (1143, 'Simplon\'s Letter', NULL, 'Письмо Торговца Симплона. Отнесите его Мастеру Аурону.', 'A letter written by Trader Simplon. Take this to Master Auron.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1144, 'Venomous Spider\'s Leg', NULL, 'Отрезанная паучья лапка. Соберите 20 штук и отнесите Мастеру Аурону.', 'A cut leg of a dead poison spider or an arachnid tracker. Collect twenty of these and take to Master Auron.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1145, 'Medallion of Warrior', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Воителей.', 'Take this medallion and go to the Grand Master of the Warrior\'s Guild to change your occupation to a Warrior.', 'accessary_earing_of_protection_i00', 0);
