INSERT INTO `all_items` VALUES (1150, 'Spellbook: Wind Strike', NULL, 'Книга, необходимая для изучения умения \"Удар Ветра\".', 'Spellbook needed to learn Wind Strike.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1151, 'Spellbook: Self Heal', NULL, 'Книга, необходимая для изучения умения \"Самолечение\".', 'Spellbook needed to learn Self Heal.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1152, 'Spellbook: Heal', NULL, 'Книга, необходимая для изучения умения \"Лечение\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'Spellbook needed to learn Heal. Used by Human Mystics, Elven Mystics and Dark Mystics.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (1153, 'Jenna\'s Letter', NULL, 'Письмо Часового Дженны Мастеру Харанту.', 'A letter from Sentry Jenna to Master Harant.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1154, 'Sentry Blade', NULL, 'Меч из адамантита, недавно выданный всем Часовым.', 'An adamantite sword newly issued to sentries.', 'weapon_bastard_sword_i00', 0);
INSERT INTO `all_items` VALUES (1155, 'Sentry Blade', NULL, 'Меч из адамантита, недавно выданный всем Часовым.', 'An adamantite sword newly issued to sentries.', 'weapon_bastard_sword_i00', 0);
INSERT INTO `all_items` VALUES (1156, 'Sentry Blade', NULL, 'Меч из адамантита, недавно выданный всем Часовым.', 'An adamantite sword newly issued to sentries.', 'weapon_bastard_sword_i00', 0);
INSERT INTO `all_items` VALUES (1157, 'Old Bronze Sword', NULL, 'Бронзовый меч, который раньше использовали Часовые. Отнесите его Часовому Дженне.', 'A bronze sword used in the past by sentries. Recover this and take it to Sentry Jenna.', 'weapon_crimson_sword_i00', 0);
INSERT INTO `all_items` VALUES (1158, 'Bone Fragment', NULL, 'Обломок кости скелета. Соберите 10 Обломков Костей и 3 Черепа Эльфа и отнесите их Унорену.', 'A bone fragment obtained from the undead skeletons. Gather 10 bone fragments and 3 Elf skulls, and take them to Unoren.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (1159, 'Elf Skull', NULL, 'Череп Эльфа. Соберите 10 Обломков Костей и 3 Черепа Эльфа и отнесите их Унорену.', 'The skull of an undead Elf. Gather 10 bone fragments and 3 Elf skulls, and take them to Unoren.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1160, 'Dark Bezoar', NULL, 'Соберите 13 Темных Безоаров и отнесите их Часовому Нельсии.', 'Gather 13 dark bezoars and take them to Sentry Nelsya.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (1161, 'Sword of Ritual', NULL, 'Предмет для смены профессии. Чтобы стать Рыцарем, отдайте его Великому Мастеру в Гильдии Воинов.', 'Take this sword to the Grand Master of the Fighter Guild to change your occupation to a Knight.', 'weapon_flamberge_i00', 0);
INSERT INTO `all_items` VALUES (1162, 'Coin of Lords', NULL, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'A gold coin engraved with the mark of the lord of Gludio. Gather three or more of these to end the Trial of the Esquire.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (1163, 'Coin of Lords', NULL, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'A gold coin engraved with the mark of the lord of Gludio. Gather three or more of these to end the Trial of the Esquire.', 'etc_coins_silver_i00', 0);
