INSERT INTO `all_items` VALUES (1165, 'Coin of Lords', NULL, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'A gold coin engraved with the mark of the lord of Gludio. Gather three or more of these to end the Trial of the Esquire.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (1166, 'Coin of Lords', NULL, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'A gold coin engraved with the mark of the lord of Gludio. Gather three or more of these to end Trial of the Esquire.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (1167, 'Coin of Lords', NULL, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'A gold coin engraved with the mark of the lord of Gludio. Gather three or more of these to end the Trial of the Esquire.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (1168, 'Gludio Guard\'s 1st Badge', NULL, 'Знак принадлежности к Стражам. Согласно приказу Капитана Батиса, Вы должны охотиться на Людоедов Налетчиков.', 'A mark that proves guard membership. As Captain Bathia requested, hunt bugbear raiders.', 'etc_badge_silver_i00', 0);
INSERT INTO `all_items` VALUES (1169, 'Bugbear Necklace', NULL, 'Ожерелье, носимое Людоедами для использования заклинаний. Соберите 10 штук и принесите их Капитану Батису.', 'A necklace worn by bugbears for incantation purposes. Collect ten of these and visit Captain Bathia.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (1170, 'Einhasad\'s 1st Temple Badge', NULL, 'По просьбе Верховного Жреца Раймонда, отправляйтесь в Руины Отчаяния. Там Вы должны победить Духов Жрецов и собрать 12 Распятий Эйнхасад.', 'As High Priest Raimund requested, go to the Ruins of Despair, defeat the departed spirits of priests, and collect 12 Einhasad crucifixes.', 'accessary_earing_of_holy_spirit_i00', 0);
INSERT INTO `all_items` VALUES (1171, 'Einhasad\'s Crucifix', NULL, 'Святой символ Эйнхасад, богини Света. Соберите 12 штук и отнесите Верховному Жрецу Раймонду.', 'A holy symbol of Einhasad, the goddess of light. Collect 12 of these and go to High Priest Raimund.', 'accessary_necklace_of_knowledge_i00', 0);
INSERT INTO `all_items` VALUES (1172, 'Gludio Guard\'s 2nd Badge', NULL, 'Знак принадлежности к Стражам. По приказу Капитана Безика, Вы должны охотиться на гигантских пауков.', 'The mark that distinguishes guard membership. As Captain Bezique requested, hunt giant spiders.', 'etc_badge_silver_i00', 0);
INSERT INTO `all_items` VALUES (1173, 'Venomous Spider\'s Leg', NULL, 'Отрезанная лапка Ядовитого Паука. Соберите 20 штук и отнесите их Капитану Безику.', 'A severed leg of a dead poison spider. Collect twenty of these and go to Captain Bezique.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1174, 'Einhasad\'s 2nd Temple Badge', NULL, 'По просьбе Верховной Жрицы Левиан, отправляйтесь на охоту на Ящеров Лангк. Убейте их и принесите доказательства этого.', 'As High Priest Levian requested, kill Langk lizardmen and collect the proof.', 'accessary_earing_of_holy_spirit_i00', 0);
INSERT INTO `all_items` VALUES (1175, 'Lizardman\'s Totem', NULL, 'Маленькая скульптура, которую Ящеры Лангк носят с собой. Соберите 20 штук и отнесите их Верховной Жрице Левиан.', 'A small sculpture Langk lizardmen carry with them. Collect twenty of these and take them to High Priestess Levian.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (1176, 'Gludio Guard\'s 3rd Badge', NULL, 'Знак принадлежности к Стражам. По приказу Капитана Гилберта, Вы должны охотиться на Гигантских Пауков.', 'A mark that proves guard membership. As Captain Gilbert requested, hunt giant spiders.', 'etc_badge_silver_i00', 0);
INSERT INTO `all_items` VALUES (1177, 'Giant Spider\'s Husk', NULL, 'Кожа Гигантского Паука. Соберите 20 штук и отнесите Капитану Гилберту.', 'The husk of a giant spider that you peeled off. Collect twenty of these and take them to Captain Gilbert.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (1178, 'Einhasad\'s 3rd Temple Badge', NULL, 'По просьбе Верховного Жреца Биотина, отправляйтесь на охоту на Безмолвных Ужасов в Эльфийские Руины.', 'As High Priest Biotin requested, hunt silent horrors in the Elven Ruins.', 'accessary_earing_of_holy_spirit_i00', 0);
INSERT INTO `all_items` VALUES (1179, 'Skull of Silent Horror', NULL, 'Череп давно умершего Эльфа. Соберите 10 штук и отнесите их Верховному Жрецу Биотину.', 'The skull of a long-dead Elf. Collect 10 and take them to High Priest Biotin.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1180, 'Bezique\'s Letter', NULL, 'Письмо Капитана Безика, адресованное Нети. Найдите Нети в Глудине и отдайте ей это письмо.', 'Captain Bezique\'s letter to Neti. Find Neti in the Village of Gludin and give her the letter.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1181, 'Neti\'s Bow', NULL, 'Любимый лук Нети, который она носила во время своих путешествий. Используйте его для охоты на скелетов в Руинах Страданий.', 'A favorite bow used by Neti, who was once a Treasure Hunter. Use it when hunting the skeletons and spartoi of the Ruins of Agony to gather bone pieces.', 'weapon_bow_i00', 0);
INSERT INTO `all_items` VALUES (1182, 'Neti\'s Dagger', NULL, 'Кинжал Нети, который она использовала во время своих путешествий. Используйте его для охоты на скелетов в Руинах Страданий.', 'Neti used this dagger when she was a Treasure Hunter. Use it when hunting the skeletons and spartoi of the Ruins of Agony to gather bone pieces.', 'weapon_knife_i00', 0);
INSERT INTO `all_items` VALUES (1183, 'Spartoi\'s Bones', NULL, 'Кости нежити. Соберите 10 штук и отнесите их Нети.', 'Undead bone pieces. Collect 10 and take them to Neti.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (1184, 'Horseshoe of Light', NULL, 'Доказательство прохождения испытания Нети. Отнесите эту подкову Капитану Безику.', 'A proof you received after passing Neti\'s test. You must take it to Captain Bezique.', 'accessary_red_cresent_earing_i00', 0);
INSERT INTO `all_items` VALUES (1185, 'Most Wanted List', NULL, 'Здесь написано, что тот, кто покончит с Бандой Кошачьего Глаза и вернет украденные товары, будет вознагражден.', 'It is written that whoever does away with the Cat\'s Eye bandits and recovers the stolen goods will be rewarded.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1186, 'Stolen Jewelry', NULL, 'Ювелирное украшение, украденное бандитами. Отнесите его Капитану Безику.', 'A fair amount of jewelry the Cat\'s Eye bandits stole. You must take them to Captain Bezique.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (1187, 'Stolen Tomes', NULL, 'Очень редкая книга, украденная бандитами. Отнесите ее Капитану Безику.', 'A rare tome the Cat\'s Eye bandits stole. You must take it to Captain Bezique.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1188, 'Stolen Ring', NULL, 'Очень дорогое кольцо, украденное бандитами. Отнесите его Капитану Безику.', 'An expensive necklace that the Cat\'s Eye bandits have stolen. You must take it back to Captain Bezique.', 'accessary_ring_of_grace_i00', 0);
INSERT INTO `all_items` VALUES (1189, 'Stolen Necklace', NULL, 'Очень дорогое ожерелье, украденное бандитами. Отнесите его Капитану Безику.', 'An expensive necklace the Cat\'s Eye bandits stole. You must take it to Captain Bezique.', 'accessary_necklace_of_blessing_i00', 0);
INSERT INTO `all_items` VALUES (1190, 'Bezique\'s Recommendation', NULL, 'Предмет для смены профессии. Чтобы стать Разбойником, отдайте это Великому Мастеру в Гильдии Воинов.', 'Take this medallion to the Grand Masters of the Fighter Guild to change your occupation to a Rogue.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1191, '1st Letter of Order', NULL, 'Свидетельство, выданное Жрецом Зигонтом, разрешающее Вам собирать запретные книги. Держите его при себе, когда отправитесь на поиски этих книг.', 'A certificate of forbidden book collection given by Priest Zigaunt. Carry this around and collect all the forbidden books.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1192, '2nd Letter of Order', NULL, 'Свидетельство, выданное Жрецом Зигонтом, указывающее, что его предъявитель относится к Храму. Отнесите его Лионелю для получения договора.', 'A certificate that proves that you represent the religious body. This certificate is given by Priest Zigaunt. Take this to Lionel for covenant.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1193, 'Lionel\'s Book', NULL, 'Последняя книга Лионеля. Отнесите эту книгу Великому Магистру Галлинту в Школу Магов Айнховант.', 'The last book of Lioniel. Hand this book to Grand Magister Gallint in the Einhovant School of Magic.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1194, 'Book of Vivyan', NULL, 'Запрещенная книга, которую Симплон продал Вивиан. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'A forbidden book Simplon sold to Vivyan. Collect five forbidden books and take them to Priest Zigaunt.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1195, 'Book of Simplon', NULL, 'Запрещенная книга, найденная у Симплона. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'The rest of Simplon\'s forbidden books. Collect 5 forbidden books and take them to Priest Zigaunt.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1196, 'Book of Praga', NULL, 'Запрещенная книга, которую Симплон продал Прагу. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'A forbidden book Simplon sold to Praga. Collect 5 forbidden books and take them to Priest Zigaunt.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1197, 'Certificate of Gallint', NULL, 'Свидетельство, выданное Галлинтом за хранение запрещенных книг. Отнесите его Лионелю для получения договора.', 'A certificate that Gallint gives for safekeeping of forbidden books. Give to Lionel and receive covenant.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1198, 'Pendant of Mother', NULL, 'Подвеска матери Стража Прага, которую он потерял в Руинах. Отнесите ее Прагу и получите запрещенную книгу.', 'The pendant of his mother that Guard Praga lost in the ruins. Take this to Guard Praga and receive a forbidden book.', 'accessary_blessed_earing_i00', 0);
INSERT INTO `all_items` VALUES (1199, 'Necklace of Mother', NULL, 'Ожерелье, использовавшееся для ношения подвески. Найдите его у зомби в Руинах Страданий и соберите целое ожерелье.', 'A necklace chain where a pendant used to hang. Recover the pendant from the zombies in the Ruins of Agony to make it complete.', 'accessary_blessed_necklace_i00', 0);
INSERT INTO `all_items` VALUES (1200, 'Lionel\'s Covenant', NULL, 'Лионель поклялся, что больше не будет писать запрещенных книг. Отдайте договор Жрецу Зигонту и получите Знак Доверия.', 'Lionel\'s pledge not to use the forbidden book again. Give it to Priest Zigaunt and receive the mark of faith.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1201, 'Mark of Faith', NULL, 'Предмет для смены профессии. Отдайте его Верховному Жрецу в Храме, чтобы стать Клериком.', 'Take this token to the high priest of the temple to change your occupation to a Cleric.', 'accessary_earing_of_wisdom_i00', 0);
INSERT INTO `all_items` VALUES (1202, 'Sorius\'s Letter', NULL, 'Письмо Мастера Сориуса, которое необходимо передать Кузнецу Клуто в Глудине.', 'A letter received from Master Sorius to be given to Blacksmith Kluto in the Village of Gludin.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1203, 'Kluto Box', NULL, 'Коробка, которую Клуто просил передать Мастеру Сориусу.', 'A box that Kluto asked to give to Master Sorius.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1204, 'Elven Knight Brooch', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру в гильдии Воинов, чтобы стать Рыцарем.', 'Take this brooch to the Grand Master of the Fighter Guild and he will change your occupation to a Knight.', 'accessary_elven_earing_i00', 0);
INSERT INTO `all_items` VALUES (1205, 'Topaz Piece', NULL, 'Осколок топаза, полученный при убийстве нежити в Руинах. Соберите 20 штук и отнесите их Мастеру Сориусу.', 'A piece of topaz obtained from the undead in the ruins. Collect 20 to take to Master Sorius.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (1206, 'Emerald Piece', NULL, 'Осколок изумруда, полученный при убийстве Новичков Гноллов. Соберите 20 штук и отнесите их Кузнецу Клуто.', 'A piece of emerald obtained from the Ol Mahum Novices. Collect 20 of these to take to Blacksmith Kluto.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1207, 'Reisa\'s Letter', NULL, 'Письмо Мастера Рейсы, адресованное Стражу Моретти.', 'Master Reisa\'s letter to Guard Moretti. Find Guard Moretti and give him the letter.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1208, 'Prias\'s 1st Torn Letter', NULL, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'A torn piece of letter written by Prias and is not legible. Collect all four torn pieces and take them to Guard Moretti.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1209, 'Prias\'s 2nd Torn Letter', NULL, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'A torn piece of letter written by Prias and is not legible Collect all four torn pieces and take them to Guard Moretti.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1210, 'Prias\'s 3rd Torn Letter', NULL, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'A torn piece of letter written by Prias and is not legible. Collect all four torn pieces and take them to Guard Moretti.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1211, 'Prias\'s 4th Torn Letter', NULL, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'A torn piece of letter written by Prias and is not legible. Collect all four torn pieces and take them to Guard Moretti.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1212, 'Moretti\'s Herb', NULL, 'Растение, которое Страж Моретти попросил отдать Приасу.', 'An herb that Guard Moretti asked to give to Prias.', 'etc_herb_green_i00', 0);
INSERT INTO `all_items` VALUES (1213, 'Guard\'s Bow', NULL, 'Лук, отданный Стражем Моретти. Возможно, у него есть важное назначение.', 'A bow given by Guard Moretti. May be efficiently used for some purpose.', 'weapon_bow_i00', 0);
INSERT INTO `all_items` VALUES (1214, 'Moretti\'s Letter', NULL, 'Срочное послание Стража Моретти Приасу.', 'An urgent letter from Guard Moretti to Prias.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1215, 'Prias\'s Letter', NULL, 'Ответ Приаса на письмо Стража Моретти. Отнесите его Моретти.', 'A reply of Prias to the letter from Guard Moretti. Hand this to Moretti.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1216, 'Honorary Guard', NULL, 'Письмо Мастеру Рейсе, написанное Стражем Моретти. Отнесите его Мастеру Рейсе.', 'A letter written by Guard Moretti to Master Reisa. Take it to Master Reisa.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1217, 'Reisa\'s Recommendation', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Воинов, чтобы стать Разведчиком.', 'Take this recommendation to the Grand Master of the Fighter Guild to change your occupation to an Elven Scout.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1218, 'Rosella\'s Letter', NULL, 'Письмо Розеллы Эльфийскому Магистру Гринис, в котором говорится о рубине, символе Огня.', 'A letter from Rosella to Elven Magister Greenis. Related to ruby, the symbol of fire.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1219, 'Red Down', NULL, 'Материал, необходимый для создания рубина с магическими свойствами. Соберите 5 штук и отнесите их Магистру Гринис для получения магического рубина.', 'Material needed to make ruby of magical powers. Collect 5 and take them to Magister Greenis for the magical power ruby.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (1220, 'Magical Powers Ruby', NULL, 'Рубин, символизирующий Огонь. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'Ruby that symbolizes fire. Gather 4 jewels that symbolize nature and take them to Rosella for a token to change occupations.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (1221, 'Pure Aquamarine', NULL, 'Аквамарин, символизирующий Воду. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'Aquamarine that symbolizes water. Gather the 4 jewels that symbolize nature and take them to Rosella for a token to change occupations.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (1222, 'Appetizing Apple', NULL, 'Красивое спелое яблоко. Отдайте его Талии, и она расскажет Вам про аквамарин.', 'A very ripe apple. Give it to Thalia for information on the aquamarine of water.', 'etc_fruit_red_i00', 0);
INSERT INTO `all_items` VALUES (1223, 'Gold Leaves', NULL, 'Листья, используемые как удобрение для Древа Жизни. Соберите 5 таких листьев, отдайте их Талии и получите аквамарин.', 'Leaves used as fertilizer for the Mother Tree. Collect five leaves and give them to Thalia for an aquamarine.', 'etc_leaf_gold_i00', 0);
INSERT INTO `all_items` VALUES (1224, 'Immortal Love', NULL, 'Книга, которую очень хочет получить Нортвинд. Если Вы отдадите ему эту книгу, он расскажет про аметист.', 'A book Northwind wanted to borrow. If you give this book to Northwind, you can obtain information on the amethyst.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1225, 'Amethyst', NULL, 'Аметист, найденный у Трусливого Крысолюда. Отдайте 2 таких аметиста Нортвинду, чтобы получить Благородный Аметист.', 'An amethyst obtained by killing sukar wererat. Give two to Northwind for nobility amethyst.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (1226, 'Nobility Amethyst', NULL, 'Аметист, символизирующий Ветер. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'Amethyst that symbolizes wind. Gather 4 jewels that symbolize nature and take them to Rosella for a token to change occupations.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (1227, 'Rosella\'s Recommendation', NULL, 'Рекомендация Розеллы. Покажите ее Варсаку, чтобы получить информацию о Благородном Хризолите.', 'Rosella\'s recommendation. If you show this to Varsak, you can get information on the fertility peridot.', 'item_normal131', 0);
INSERT INTO `all_items` VALUES (1228, 'Peridot', NULL, 'Хризолит, который можно получить при убийстве Скелета Снайпера. Соберите 3 штуки и отнесите их Варсаку. Взамен он даст Вам Благородный Хризолит.', 'A peridot you can get if you kill a sniper skeleton. If you collect 3 and show them to Varsak, you can get the fertility peridot.', 'item_normal16', 0);
INSERT INTO `all_items` VALUES (1229, 'Fertility Peridot', NULL, 'Хризолит, символизирующий Землю. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'A peridot that symbolizes the earth. Gather 4 jewels that symbolize nature and take them to Rosella for a token to change occupations.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1230, 'Eternity Diamond', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Магов, чтобы стать Светлым Магом.', 'Take this token to the Grand Master of the Magician Guild to change your occupation to an Elven Wizard.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (1231, 'Crystal Medallion', NULL, 'Ожерелье, выданное Жрецом Мануэлем. Отправляйтесь с ним в Гавань Глудина и найдите там девушку, творящую чудеса.', 'A necklace given by Priest Manuel. Take this and go to the port Gludin to find the girl who works miracles.', 'accessary_blue_diamond_necklace_i00', 0);
INSERT INTO `all_items` VALUES (1232, 'Swindler\'s Money', NULL, 'Деньги Перрина, полученные при помощи мошенничества. Отдайте их Аллане.', 'Money from Perrin\'s swindling. Give it to Allana.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (1233, 'Allana\'s Diary', NULL, 'Дневник с описанием фальшивых чудес. Покажите его Жрецу Мануэлю в качестве доказательства того, что Вы выполнили задание.', 'A diary with records of fraud miracle. Show this to Priest Manuel as proof.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1234, 'Lizard Captain Order', NULL, 'Приказ Капитана Ящеров о похищении святой из пророчества.', 'An order of lizard captain to kidnap the sacred flame of prophecy.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1235, 'Leaf of Oracle', NULL, 'Предмет для смены профессии. Отдайте его Верховному Жрецу, чтобы стать Оракулом.', 'Take this to the high priest to change your occupation to an Oracle.', 'etc_leaf_green_i00', 0);
INSERT INTO `all_items` VALUES (1236, 'Half of Diary', NULL, 'Половина дневника Алланы. Вы должны забрать деньги у Перрина и найти вторую часть этого дневника.', 'Half of the diary given by Allana. You must get money from Perrin and find the other half of the diary.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1237, 'Palus Talisman', NULL, 'Талисман с рунами, символизирующими озеро. Держите его при себе, пока будете охотиться на Ликантропов в Нейтральной Зоне.', 'A talisman inscribed with palus runes that symbolize a deep lake. Carry this and hunt lycanthrope in the Neutral Zone.', 'accessary_earing_of_grace_i00', 0);
INSERT INTO `all_items` VALUES (1238, 'Lycanthrope Skull', NULL, 'Череп, добытый с мертвого Ликантропа. Соберите 13 штук и отнесите их Мастеру Вирджилу.', 'A skull obtained after killing lycanthrope. Collect thirteen and take them to Master Virgil.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1239, 'Virgil\'s Letter', NULL, 'Письмо Мастера Вирджила. Отнесите его Служителю Бездны Калинте в Глудин.', 'A letter written by Master Virgil. Take this to Abyssal Celebrant Kalinta of the village of Gludin.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1240, 'Morte Talisman', NULL, 'Талисман с руной Морте, символом смерти. Возьмите его с собой на поиски гроба.', 'A talisman with inscription of rune of Morte, symbol of death. Carry this and find materials needed for coffin.', 'accessary_necklace_of_binding_i00', 0);
INSERT INTO `all_items` VALUES (1241, 'Venomous Spider\'s Carapace', NULL, 'Твердый панцирь Ядовитого Паука. Отнесите его и 5 кусков Шелка Арахнида Охотника Служителю Бездны Калинте.', 'The hard carapace of a poison spider. Take this and five arachnid tracker silk threads to Abyssal Celebrant Kalinta.', 'etc_bark_blue_i00', 0);
INSERT INTO `all_items` VALUES (1242, 'Arachnid Tracker Silk', NULL, 'Куски паутины Арахнида Охотника. Соберите 5 штук и отнесите их Служителю Бездны Калинте вместе с Панцирем Ядовитого Паука.', 'Arachnid tracker web threads. Take five of these and a giant poison spider carapace to Abyssal Celebrant Kalinta.', 'etc_skein_gray_i00', 0);
INSERT INTO `all_items` VALUES (1243, 'Coffin of Eternal Rest', NULL, 'Гроб для похорон Темных Рыцарей Отнесите его Мастеру Вирджилу.', 'A coffin used in funeral of Dark Elven Knight. Take this to Master Virgil.', 'shield_tower_shield_i00', 0);
INSERT INTO `all_items` VALUES (1244, 'Gaze of Abyss', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Воинов, чтобы стать Темным Рыцарем.', 'Take this token to the Grand Master of the Fighter Guild to change your occupation to a Knight.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (1245, 'Shilen\'s Call', NULL, 'Письмо Трискела. Отнесите его Ведьме Аркении к Церемониальному Алтарю.', 'A letter received from Triskel. Go to Witch Arkenia of the Altar of Rites.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1246, 'Arkenia\'s Letter', NULL, 'Письмо Аркении. Отнесите его Стражу Лейкану, чтобы узнать информацию о воре.', 'A letter received from Arkenia. Take this to Guard Leikan to obtain information about the thief.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1247, 'Leikan\'s Note', NULL, 'Контракт, выданный Стражем Лейканом. Отправляйтесь на охоту на Зверей Лунного Камня и соберите их зубы.', 'A simple contract given by Guard Leikan. Must hunt moonstone beasts and collect their molars.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1248, 'Moonstone Beast\'s Molar', NULL, 'Зуб, добытый у убитого Зверя Лунного Камня. Соберите 10 штук и отнесите их Стражу Лейкану.', 'A molar obtained after killing a moonstone beast. Collect 10 of these to take to Guard Leikan.', 'etc_molar_white_i00', 0);
INSERT INTO `all_items` VALUES (1249, 'Leikan\'s Knife', NULL, 'Нож, подаренный Лейканом в качестве благодарности. Говорят, он отлично действует против Кальпико.', 'A knife received as present from Leikan. They say it works well against the Calpicos.', 'weapon_ss09', 0);
INSERT INTO `all_items` VALUES (1250, 'Shilen\'s Tears', NULL, 'Магическая жидкость, украденная с Церемониального Алтаря. Отдайте ее Ведьме Аркении.', 'Magic liquid stolen from the Altar of Rites. Give this to Witch Arkenia.', 'etc_lesser_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (1251, 'Arkenia\'s Recommendation', NULL, 'Знак благодарности от Аркении. Отнесите эту рекомендацию Трискелу.', 'A token of thanks received from Arkenia. Take this to Triskel.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1252, 'Iron Heart', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Ассасином.', 'Take this to the Grand Master of the Dark Elf Guild to change your occupation to an Assassin.', 'accessary_earing_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (1253, 'Seed of Anger', NULL, 'Семя, полученное от Чаркерена. Отнесите его Ведьме Варике.', 'A seed obtained from Charkeren, who is full of anger. Take this to Witch Varika.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (1254, 'Seed of Despair', NULL, 'Семя, полученное от Ведьмы Варики. Вы должны достать все четыре семени, чтобы получить Украшение Тьмы.', 'A seed obtained from Witch Varika. You must obtain all four seeds to earn the Jewel of Darkness.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (1255, 'Seed of Horror', NULL, 'Семя, полученное от Анники. Отнесите его Ведьме Варике.', 'A seed obtained from Annika, who is full of horror. Take this to Witch Varika.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (1256, 'Seed of Lunacy', NULL, 'Семя, полученное от безумца. Отнесите его Ведьме Варике.', 'A seed obtained from a lunatic. Take this to Witch Varika.', 'etc_bead_green_i00', 0);
INSERT INTO `all_items` VALUES (1257, 'Family\'s Remains', NULL, 'Останки семьи Чаркерена. Соберите 3 части и верните их Чаркерену.', 'Remains of Charkeren\'s slain family. Find 3 and return to Charkeren.', 'etc_ashes_black_i00', 0);
INSERT INTO `all_items` VALUES (1258, 'Varika\'s Liquor', NULL, 'Лекарство, которое Варика изготовила для сына герцогини. Отнесите его герцогине, чтобы получить Семя Отчаяния.', 'A medicine Varika made for the son of Duchess Dwell. If you give it to Duchess, you can obtain the Seed of Despair.', 'item_canuse47', 0);
INSERT INTO `all_items` VALUES (1259, 'Knee Bone', NULL, 'Коленная кость нежити, которую так долго искала Анника. Отдайте ее Аннике, чтобы получить Семя Ужаса.', 'The knee bone of undead that Annika was looking for. Give this to Annika to obtain the Seed of Horror.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (1260, 'Heart of Lunacy', NULL, 'Сердце превращенного в скелет. Соберите 3 штуки и отнесите их Аркении.', 'The hearts of those who have been turned into skeletons by a sorcerer of lunacy. Collect 3 Hearts of Lunacy and take them to Arkenia.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (1261, 'Dark Jewel', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Темным Магом.', 'Take this token to the Grand Master of the Dark Elf guild to change your occupation to a Dark Wizard.', 'accessary_necklace_of_phantom_i00', 0);
INSERT INTO `all_items` VALUES (1262, 'Sidra\'s Letter', NULL, 'Письмо, написанное Магистром Сидрой. Отнесите его Магистру Талботу.', 'The letter of introduction written by Magister Sidra. Take this to Magister Talbot.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1263, 'Blank Sheet', NULL, 'Пустой свиток. Возьмите его с собой во время охоты на Темных Суккубов, чтобы нанести на него кровавые руны.', 'A blank scroll. Take this and hunt dark succubus to obtain bloody runes.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1264, 'Bloody Rune', NULL, 'Руны, написанные кровью Темных Суккубов. Соберите 5 штук и отнесите Магистру Талботу.', 'Runes written with the blood of dark succubus. Collect 5 and take to Magister Talbot.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1265, 'Garmiel\'s Book', NULL, 'Священная книга Гран Каина, бога Тьмы, написанная на эльфийском языке. Одна из тех двух книг, которые Вам нужно найти для Сидры.', 'The sacred book of Gran Kain, god of darkness, written in elven language. One of two books Sidra told you to find.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1266, 'Prayer of Adonius', NULL, 'Молитвенник, который необходимо отнести Жрецу Адониусу в Глудин.', 'The widely beloved prayer book. Take this to Priest Adonius in the village of Gludin.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1267, 'Penitent\'s Mark', NULL, 'Знак искупления грехов своего обладателя. Держите его при себе во время охоты на Скелетов и Зомби в Руинах Отчаяния.', 'The mark that shows one is in the course of repenting one\'s sins. Carry this and hunt skeletons and zombies in the Ruins of Despair.', 'accessary_earing_of_holy_spirit_i00', 0);
INSERT INTO `all_items` VALUES (1268, 'Ashen Bones', NULL, 'Кости Скелетов и Зомби из Руин Отчаяния. Соберите 10 штук и отнесите Жрецу Адониусу.', 'Bones from the skeletons and zombies in the Ruins of Despair. Gather 10 and take them to Priest Adonius.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (1269, 'Andariel Book', NULL, 'Священная книга Эйнхасад, богини света, написанная на эльфийском языке. Одна из тех двух книг, которые Вам нужно найти для Сидры.', 'The sacred book of Einhasad, goddess of light, written in the Elven language. One of two books Sidra told you to find.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1270, 'Orb of Abyss', NULL, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Оракулом Шилен.', 'Take this token to a Grand Master of a Dark Elf Guild in any major city to change your occupation to a Shillien Oracle.', 'etc_bead_blue_i00', 0);
INSERT INTO `all_items` VALUES (1271, 'Squire\'s Mark', NULL, 'Знак оруженосца. Вам надлежит встретиться с Капитанами Стражи и Верховными Жрецами в Глудио.', 'A mark that indicates an esquire. Wander around the villages in Gludio and meet with guard captains and high priests.', 'accessary_earing_of_wisdom_i00', 0);
INSERT INTO `all_items` VALUES (1272, 'Greenis\'s Charm', NULL, 'Талисман на удачу, принадлежащий Гринис. Добудьте 5 трофеев с Пауков Хелицера и отнесите их Гринис.', 'Greenis\'s good luck charm. Kill pincer spiders and give 5 red down to Greenis.', 'accessary_aquastone_necklace_i00', 0);
INSERT INTO `all_items` VALUES (1273, 'Sap of the Mother Tree', NULL, 'Сок Древа Жизни, который так любят Старшие Дриады. Соберите с них 5 золотых листьев и отнесите их Талии.', 'Sap of Mother Tree that dryad elders like. Find 5 gold leaves and give them to Thalia.', 'etc_potion_green_i00', 0);
INSERT INTO `all_items` VALUES (1274, 'Lucky Potpourri', NULL, 'Счастливая смесь, принадлежащая Нортвинду. Отнесите ему 2 аметиста, добытых у Трусливых Крысолюдов.', 'Northwind\'s lucky potpourri. Give Northwind 2 amethysts obtained from killing sukar wererats.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (1275, 'Tamil\'s Necklace', NULL, 'Ожерелье Тамил, которое необходимо показать Перрину.', 'Tamil\'s necklace. Show it to Perrin.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (1276, 'Kluto\'s Memo', NULL, 'Записка от Кузнеца Клуто с просьбой убить Новичков Гноллов.', 'A memo from Blacksmith Kluto asking to defeat the Ol Mahum Novices.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1277, 'Lucky Key', NULL, 'Бронзовый ключ. Держите его при себе, когда отправитесь на охоту на Зомби в районе болот. Соберите 3 комплекта останков и отнесите их Чаркерену.', 'A bronze key. Hunt zombies in the swamp area, collect 3 remains, and take them to Charkeren.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (1278, 'Candle', NULL, 'Свеча, освещающая дорогу во тьме. Соберите 2 Коленных Кости с нежити и отнесите их Аннике, чтобы получить Семя Ужаса.', 'A candle that lights up the dark. Collect 2 knee bones from the undead and give them to Annika for the Seed of Horror.', 'etc_spirit_bullet_white_i00', 0);
INSERT INTO `all_items` VALUES (1279, 'Hub Scent', NULL, 'Смесь из пряных трав. Соберите 3 Сердца Безумия со Скелетов Разведчиков и отнесите их Аркении.', 'Fragrant herb potpourri. Obtain 3 Hearts of Lunacy from a skeleton scout and take them to Arkenia.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (1280, 'Map of Luster', NULL, 'Карта, полученная от Огненной Саламандры. Убивайте Крысолюдов, пока не получите Ключ Пламени. Отнесите его Саламандре в обмен на знак Огня.', 'A map given by the Flame Salamander. Kill ratman fighters and give the key of flame to the salamander in exchange for the token of fire.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1281, 'Key of Flame', NULL, 'Ключ, полученный с убитого Крысолюда. Отдайте его Саламандре в обмен на знак Огня.', 'The key that can be obtained by killing a ratman fighter. When you give it to a salamander, he will give you the token of fire.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (1282, 'Flame Earring', NULL, 'Знак Огня, полученный от Огненной Саламандры. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'The token of fire given by fire spirit salamander. Collect four tokens and give them to Parina to receive the token that enables changing occupations.', 'accessary_earing_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (1283, 'Broken Bronze Mirror', NULL, 'Зеркало Воздушного Сильфа. Отправляйтесь к Ящерам в Пустошь, заберите Перо Воздушного Сильфа и верните его владельцу.', 'The mirror given by the Wind Sylph. Go to the lizardmen of the Wastelands and obtain the Wind Feather and return it to the Wind Sylph.', 'etc_mirror_i00', 0);
INSERT INTO `all_items` VALUES (1284, 'Wind Feather', NULL, 'Перо, принадлежащее Воздушному Сильфу, живущему у Пустоши. Верните его и получите Знак Ветра.', 'The feather hidden by the Wind Sylph near the Wastelands. Return this to the Wind Sylph to receive a Wind Token.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (1285, 'Wind Bangle', NULL, 'Знак Ветра, полученный от Воздушного Сильфа. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'The Wind Token given to you by the Wind Spirit Sylph. Collect all four tokens and give them to Parina to receive a special token that will enable you to change occupations.', 'accessary_blue_coral_ring_i00', 0);
INSERT INTO `all_items` VALUES (1286, 'Rama\'s Diary', NULL, 'Убивайте Водных Пророков, пока не найдете 2 Сверкающих Камня. Отнесите их Водяной Ундине, чтобы получить знак Воды.', 'Kill water seer and take two sparkle pebbles to water Undine for the token of water.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1287, 'Sparkle Pebble', NULL, 'Камень Водного Пророка. Отдайте его Водяной Ундине, чтобы получить знак Воды.', 'Kill water seer in Lake Fellmere for stones. If you give this to Water Undine, she will give you the token of water.', 'etc_crystal_ball_white_i00', 0);
INSERT INTO `all_items` VALUES (1288, 'Water Necklace', NULL, 'Знак Воды, полученный от Водяной Ундины. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'The token of water given by water spirit Undine. Collect four tokens and give them to Parina to receive the token that enables changing occupations.', 'accessary_necklace_of_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1289, 'Rusty Coin', NULL, 'Монета, полученная от Земляной Змеи. Соберите Красную Глину во время охоты на Рыжих Медведей и отдайте ее Земляной Змее в обмен на знак Земли.', 'The coin given by earth snake. Kill red bear and give red soil to earth snake for Token of Earth.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (1290, 'Red Soil', NULL, 'Глина, полученная во время охоты на Рыжих Медведей. Отдайте его Земляной Змее в обмен на знак Земли.', 'The soil obtained from killing red bear. Give to the earth snake for the token of earth.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (1291, 'Earth Ring', NULL, 'Знак Земли, полученный от Земляной Змеи. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'Token of Earth given by earth snake. Collect 4 tokens and give them to Parina to receive the token that enables changing occupations.', 'accessary_ring_of_firefly_i00', 0);
INSERT INTO `all_items` VALUES (1292, 'Bead of Season', NULL, 'Предмет для смены профессии. Отдайте его Верховному Жрецу в Храме, чтобы стать Магом.', 'Take this bead to the high priest of the temple to change your occupation to a Wizard.', 'etc_crystal_ball_green_i00', 0);
INSERT INTO `all_items` VALUES (1293, 'Rusted Key', NULL, 'Ключ, открывающий замок на оковах Приаса. Отнесите его Приасу.', 'The key that unlocks Prias\'s shackles. Take this and go to Prias.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (1294, 'Spellbook: Defense Aura', NULL, 'Книга, необходимая для изучения умения \"Аура Защиты\". Профессии: Светлый Воин, Темный Воин.Необходимый уровень: 5.', 'Spellbook needed to learn Defense Aura. Used by Elven Fighters and Dark Fighters.', 'etc_spell_books_efighter_i00', 0);
INSERT INTO `all_items` VALUES (1295, 'Long Sword', NULL, 'Временный предмет для Камекса.', 'A temporary item for Kamex0', 'weapon_long_sword_i00', 0);
