INSERT INTO `all_items` VALUES (1332, 'Knight\'s Shield', NULL, 'Временный предмет для Камекса.', 'A temporary item for Kamex0', 'shield_tower_shield_i00', 0);
INSERT INTO `all_items` VALUES (1333, 'Brandish', NULL, 'Двуручный меч для новичков.', 'A two-handed sword for beginners.', 'weapon_brandish_i00', 0);
INSERT INTO `all_items` VALUES (1334, 'Predator\'s Fang', NULL, 'Соберите 100 клыков хищников и отнесите их Фее Мурике.', 'Collect 100 predator\'s fangs and take them to Pixy Murika.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1335, 'Goblin Club', NULL, 'Тяжелая дубина, сделанная гоблинами из толстых ветвей. Отнесите ее Древню Бремецу.', 'A sturdy club made from thick tree branches and carried by goblins. Take this to Treant Bremac.', 'weapon_club_i00', 0);
INSERT INTO `all_items` VALUES (1336, 'Glass Shard', NULL, 'Осколок разбитого стекла. Можно продать в магазин за небольшую цену.', 'A broken glass piece. Can be sold in any shop for a low price.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (1337, 'Emerald', NULL, 'Можно продать в любой лавке по высокой цене.', 'Can be sold in any shop for a high price.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1338, 'Blue Onyx', NULL, 'Синий драгоценный камень. Можно продать в любой лавке.', 'A blue jewel. Can be sold in any shop.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (1339, 'Onyx', NULL, 'Черный драгоценный камень. Можно продать в любой лавке.', 'A black jewel. Can be sold in any shop.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (1340, 'Silvery Leaf', NULL, 'Лист серебристой омелы. Можно продать в любой лавке.', 'The leaf of a silvery mistletoe. Can be sold in any shop.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (1341, 'Bone Arrow', NULL, 'Стрела, сделанная из заостренной кости. Подходит для стрельбы из лука Ранга D.', 'An arrow made from a piece of sharpened bone. It is used as an arrow for a D-Grade bow.', 'etc_bone_quiver_i00', 2);
INSERT INTO `all_items` VALUES (1342, 'Steel Arrow', NULL, 'Мощная стрела, выплавленная из стали. Подходит для стрельбы из лука Ранга C.', 'A powerful arrow made of steel. It is used as an arrow for a C-Grade bow.', 'etc_fine_steel_quiver_i00', 2);
INSERT INTO `all_items` VALUES (1343, 'Silver Arrow', NULL, 'Стальная стрела, покрытая серебром.', 'A steel arrow plated with silver.', 'etc_silver_quiver_i00', 2);
INSERT INTO `all_items` VALUES (1344, 'Mithril Arrow', NULL, 'Стальная стрела, покрытая мифрилом.', 'A steel arrow plated with mithril.', 'etc_mithril_quiver_i00', 2);
INSERT INTO `all_items` VALUES (1345, 'Shining Arrow', NULL, 'Очень мощная стрела, сделанная из неизвестного материала.', 'The most powerful arrow. Unknown material.', 'etc_shining_quiver_i00', 2);
INSERT INTO `all_items` VALUES (1346, 'Golem\'s Stoneheart', NULL, 'Камень, найденный в останках разрушенного голема. Отнесите его Торговцу Роленто.', 'A stone found within the remains of a destroyed golem. Take this to Trader Rorento.', 'etc_squares_gray_i00', 0);
INSERT INTO `all_items` VALUES (1347, 'Monster Eye Meat', NULL, 'Останки монстроглаза. Отнесите их Торговцу Сариену.', 'The carcass of monster eye. Take this to Trader Sarien.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (1348, 'Basilisk\'s Gizzard', NULL, 'Часть тела василиска. Отнесите ее Торговцу Сариену.', 'The digestive organ of a basilisk. Take this to Trader Sarien.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1349, 'Anatomy Diagram', NULL, 'Учебник по анатомии, написанный учеными Авеллы. Используйте его для выполнения просьбы Самеда.', 'A diagram designed by Avella physicians for human anatomy. Use this to perform Samed\'s request.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1350, 'Zombie Head', NULL, 'Голова зомби, обитающего в Руинах. Отнесите ее Самеду в Глудио.', 'A head of zombie from ruins. Take this to Samed of the town of Gludio.', 'etc_skull_red_i00', 0);
