INSERT INTO `all_items` VALUES (1365, 'Broken Stoneheart', NULL, 'Мелкие камни, найденные в останках разрушенного голема. Отнесите их Торговцу Роленто.', 'A small pieces of stone found within the remains of a destroyed golem. Take this to Trader Rorento.', 'etc_plate_glay_i00', 0);
