INSERT INTO `all_items` VALUES (1410, 'Spellbook: Poisonous Cloud', NULL, 'Книга, необходимая для изучения умения \"Ядовитое Облако\". Профессии: Маг, Темный Маг.Необходимый уровень: 25.', 'Spellbook needed to learn Poisonous Cloud. Used by Human Wizards and Dark Wizards.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1411, 'Spellbook: Aura Burn', NULL, 'Книга, необходимая для изучения умения \"Сжигающая Аура\". Профессии: Маг, Светлый Маг, Темный Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Aura Burn. Used by Human Wizards, Elven Wizards and Dark Wizards.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (1412, 'Spellbook: Resist Aqua', NULL, 'Книга, необходимая для изучения умения \"Сопротивление Воде\". Профессии: Светлый Маг, Проповедник.Необходимый уровень: Светлый Маг - 20, Проповедник - 58.', 'Spellbook needed to learn Resist Aqua. Used by Prophets and Elven Wizards.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1413, 'Spellbook: Resist Wind', NULL, 'Книга, необходимая для изучения умения \"Сопротивление Ветру\". Профессии: Оракул Шилен, Проповедник.Необходимый уровень: Оракул Шилен - 35, Проповедник - 58.', 'Spellbook needed to learn Resist Wind. Used by Prophets and Shillien Oracles.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1414, 'Spellbook: Resist Fire', NULL, 'Книга, необходимая для изучения умения \"Сопротивление Огню\". Профессия: Клерик.Необходимый уровень: 30.', 'Spellbook needed to learn Resist Fire. Used by Clerics.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1415, 'Spellbook: Dryad Root', NULL, 'Книга, необходимая для изучения умения \"Корень Дриады\". Профессии: Клерик, Оракул Евы, Оракул Шилен.Необходимый уровень: 25.', 'Spellbook needed to learn Dryad Root. Used by Clerics, Elven Oracles and Shillien Oracles.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1416, 'Spellbook: Curse of Chaos', NULL, 'Книга, необходимая для изучения умения \"Проклятие Хаоса\". Профессии: Маг, Темный Маг.Необходимый уровень: 35.', 'Spellbook needed to learn Curse of Chaos. Used by Human Wizards and Dark Wizards.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1417, 'Spellbook: Surrender To Earth', NULL, 'Книга, необходимая для изучения умения \"Предать Земле\". Профессия: Светлый Маг.Необходимый уровень: 35.', 'Spellbook needed to learn Surrender To Earth. Used by Elven Wizards.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (1418, 'Spellbook: Surrender To Poison', NULL, 'Книга, необходимая для изучения умения \"Предать Яду\". Профессия: Темный Маг.Необходимый уровень: 25.', 'Spellbook needed to learn Surrender To Poison. Used by Dark Wizards.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1419, 'Blood Mark', NULL, 'Предмет, необходимый для получения 3-го уровня клана.', 'An item needed to upgrade a clan to level three.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (1420, 'Ingredient List', NULL, 'Список ингредиентов Джонаса: Сок Мандрагоры, Дионский Картофель, Болотный Мох, Мясо Монстроглаза.', 'A list of cooking ingredients from Jonas. Mandragora essence. Honey. Dionian potato. Marsh moss. Floating eye meat.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1421, 'Sonia\'s Botany Book', NULL, 'Книга о Мандрагорах. Она потребуется Вам для сбора корней Мандрагоры.', 'A picture that shows what a mandragora looks like. You need this to get mandragora roots.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1422, 'Red Mandragora Root', NULL, 'Красный корень Мандрагоры. Соберите эти корни и отнесите их Торговцу Соне.', 'Red mandragora root. Collect these to take them to Trader Sonia.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1423, 'White Mandragora Root', NULL, 'Редкий белый корень Мандрагоры. Соберите эти корни и отнесите их Торговцу Соне.', 'Rare white mandragora root. Collect these to take them to Trader Sonia.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1424, 'Red Mandragora Sap', NULL, 'Красный сок Мандрагоры. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'Red mandragora sap. One of the five ingredients needed for Jonas\'s cooking.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (1425, 'White Mandragora Sap', NULL, 'Белый сок Мандрагоры. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'Transparent mandragora sap. One of the ingredients needed for Jonas\'s cooking.', 'etc_potion_clear_i00', 0);
INSERT INTO `all_items` VALUES (1426, 'Jacob\'s Insect Book', NULL, 'Книга о пчелах. Вы должны взять ее с собой, чтобы собрать Нектар и Королевское Желе с Кровавых Пчел или Жалящих Ос.', 'A diagram that depicts the drawing of a bee. You must possess this in order to obtain nectar and royal jelly from the bloody bee or the stinger wasp.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1427, 'Nectar', NULL, 'Сладкая жидкость, полученная из гигантской пчелы. Соберите 20 штук и отнесите Стражу Якобу.', 'Honey water taken from a giant bee. Collect 20 of these to take them to Guard Jaycub.', 'etc_reagent_gold_i00', 0);
INSERT INTO `all_items` VALUES (1428, 'Royal Jelly', NULL, 'Редкий ингредиент, получаемый из молодых пчел. Соберите его и отнесите Стражу Якобу.', 'A rare ingredient that can be taken only from newborn working bees. Collect these and take them to Guard Jaycub.', 'etc_reagent_white_i00', 0);
INSERT INTO `all_items` VALUES (1429, 'Honey', NULL, 'Мед, сделанный из нектара, который Вы собрали. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'Honey made from the nectar you collected from bees. One of the five ingredients needed for Jonas\'s cooking.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1430, 'Golden Honey', NULL, 'Золотой мед, сделанный из Нектара и Королевского Желе, которое Вы собрали. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'Golden honey made from the nectar and the royal jelly you collected from bees. One of the five ingredients needed for Jonas\'s cooking.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (1431, 'Pano\'s Contract', NULL, 'Контракт, выданный Бакалейщиком Пано. В нем говорится, что Вы обязаны убить Хобгоблинов и принести 30 доказательств этого, чтобы получить в награду Бататы.', 'A contract Grocer Pano gave you. It says, if you kill Hobgoblins and bring 30 pieces of proof, he will give you potatoes as a reward.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1432, 'Hobgoblin Amulet', NULL, 'Амулет из перьев, который Хобгоблины носят с собой. Соберите 30 штук и отнесите их Бакалейщику Пано.', 'An amulet made of a feather that Hobgoblins carry on their bodies. Collect 30 of these and take them to Grocer Pano.', 'etc_feather_black_i00', 0);
INSERT INTO `all_items` VALUES (1433, 'Dionian Potato', NULL, 'Картофель высокого качества, выращенный на плодородных землях южного Диона. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'The highest-quality potatoes grown in the rich soil of southern Dion. One of the five ingredients needed for Jonas\'s cooking.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (1434, 'Glyvka\'s Botany Book', NULL, 'Книга сборщика мха. В ней объясняется, как лучше всего собирать болотный мох. Она Вам понадобится для сбора Болотного Мха с Серых и Багровых Муравьев.', 'A picture that explains how to collect moss. You need this to collect marsh moss from grey ants or crimson ants.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (1435, 'Green Marsh Moss', NULL, 'Зеленый болотный мох, используемый в приготовлении еды. Соберите его и отнесите Жрице Гливке.', 'Green marsh moss is sometimes used in cooking. Collect this and take it to Priestess Glyvka.', 'etc_branch_green_i00', 0);
INSERT INTO `all_items` VALUES (1436, 'Brown Marsh Moss', NULL, 'Редкий коричневый болотный мох, используемый в приготовлении еды. Соберите его и отнесите Жрице Гливке.', 'Rare brown marsh moss, its flavors are superior to the green ones. Collect this and take it to Priestess Glyvka.', 'etc_branch_gold_i00', 0);
INSERT INTO `all_items` VALUES (1437, 'Green Moss Bundle', NULL, 'Пучок хорошего мха, собранного на болотах. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'A bundle of well-cared-for moss, collected from a marshy place for cooking. One of the five ingredients needed for Jonas\'s cooking.', 'etc_bark_green_i00', 0);
INSERT INTO `all_items` VALUES (1438, 'Brown Moss Bundle', NULL, 'Пучок хорошего мха, собранного на болотах. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'A bundle of well-cared-for moss, collected from a marshy place for cooking. One of the five ingredients needed for Jonas\'s cooking.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (1439, 'Rollant\'s Creature Book', NULL, 'Книга о Монстроглазах. Она потребуется Вам для сбора частей Монстроглазов Искателей и Ока Монстроглаза.', 'A picture that shows what a monster eye looks like. You need this to collect the right monster eye searcher or the monster eye gazer.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (1440, 'Body of Monster Eye', NULL, 'Туша Монстроглаза. Отнесите ее Магистру Ролланту.', 'Severed flesh of the dead body of monster eye. Take this to Magister Rollant.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (1441, 'Monster Eye Meat', NULL, 'Мясо Монстроглаза, подходящее для готовки. Один из пяти ингредиентов, необходимых Джонасу для приготовления еды.', 'The dead body of a monster eye, ready to cook. One of the five ingredients needed for Jonas\'s cooking.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1442, 'Jonas\'s 1st Steak Dish', NULL, 'Приготовленный Джонасом стейк из мяса Монстроглаза. Отнесите его Магистру Мириен.', 'A plate that contains Jonas\'s monster eye steak. Take this to Magister Mirien.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1443, 'Jonas\'s 2nd Steak Dish', NULL, 'Приготовленный Джонасом стейк из мяса Монстроглаза. Отнесите его Магистру Мириен.', 'A plate that contains Jonas\'s monster eye steak. Take this to Magister Mirien.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1444, 'Jonas\'s 3rd Steak Dish', NULL, 'Приготовленный Джонасом стейк из мяса Монстроглаза. Отнесите его Магистру Мириен.', 'A plate that contains Jonas\'s monster eye steak. Take this to Magister Mirien.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1445, 'Jonas\'s 4th Steak Dish', NULL, 'Приготовленный Джонасом стейк из мяса Монстроглаза. Отнесите его Магистру Мириен.', 'A plate that contains Jonas\'s monster eye steak. Take this to Magister Mirien.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1446, 'Jonas\'s 5th Steak Dish', NULL, 'Приготовленный Джонасом стейк из мяса Монстроглаза. Отнесите его Магистру Мириен.', 'A plate that contains Jonas\'s monster eye steak. Take this to Magister Mirien.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1447, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен о приготовленном Джонасом блюде. Отнесите его Джонасу.', 'A letter from Magister Mirien about the taste of Jonas\'s dish. Take this to Jonas.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1448, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен о приготовленном Джонасом блюде. Отнесите его Джонасу.', 'A letter from Magister Mirien about the taste of Jonas\'s dish. Take this to Jonas.', 'item_normal129', 0);
INSERT INTO `all_items` VALUES (1449, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен о приготовленном Джонасом блюде. Отнесите его Джонасу.', 'A letter from Magister Mirien about the taste of Jonas\'s dish. Take this to Jonas.', 'item_normal129', 0);
INSERT INTO `all_items` VALUES (1450, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен о приготовленном Джонасом блюде. Отнесите его Джонасу.', 'A letter from Magister Mirien about the taste of Jonas\'s dish. Take this to Jonas.', 'item_normal129', 0);
INSERT INTO `all_items` VALUES (1451, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен о приготовленном Джонасом блюде. Отнесите его Джонасу.', 'A letter from Magister Mirien about the taste of Jonas\'s dish. Take this to Jonas.', 'item_normal129', 0);
INSERT INTO `all_items` VALUES (1452, 'Harpy Feather', NULL, 'Перо, отобранное у Гарпии. Соберите перья и отнесите их Стражу Белтону.', 'A feather taken from a harpy. Collect these and take them to Guard Belton.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (1453, 'Medusa Venom', NULL, 'Яд, взятый из волос Медузы. Соберите его и отнесите Стражу Белтону.', 'Poison extracted from the snake hair of a medusa. Collect these and take them to Guard Belton.', 'etc_potion_green_i00', 0);
INSERT INTO `all_items` VALUES (1454, 'Wyrm\'s Tooth', NULL, 'Острый зуб змея. Соберите их и отнесите Стражу Белтону.', 'A sharp fang of a wyrm. Collect these and take them to Guard Belton.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1455, 'Jonas\'s Salad Recipe', NULL, 'Рецепт приготовления салата из болотного мха.', 'Jonas\'s recipe for making marsh moss salad.', 'item_canuse39', 0);
INSERT INTO `all_items` VALUES (1456, 'Jonas\'s Sauce Recipe', NULL, 'Рецепт приготовления соуса Мандрагоры.', 'Jonas\'s recipe for making mandragora sauce.', 'item_canuse39', 0);
INSERT INTO `all_items` VALUES (1457, 'Jonas\'s Steak Recipe', NULL, 'Рецепт приготовления стейка из мяса Монстроглаза.', 'Jonas\'s recipe for making monster eye meat steak.', 'item_canuse39', 0);
INSERT INTO `all_items` VALUES (1458, 'Crystal (D-Grade)', NULL, 'Кристалл Ранга D.', 'A crystal of D-Grade.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (1459, 'Crystal (C-Grade)', NULL, 'Кристалл Ранга C.', 'A crystal of C-Grade.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (1460, 'Crystal (B-Grade)', NULL, 'Кристалл Ранга B.', 'A crystal of B-Grade.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (1461, 'Crystal (A-Grade)', NULL, 'Кристалл Ранга A.', 'A crystal of A-Grade.', 'etc_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (1462, 'Crystal (S-Grade)', NULL, 'Кристалл Ранга S.', 'A crystal of S Grade.', 'etc_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (1463, 'Soulshot (D-Grade)', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Ранга D.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with a D-grade weapon.', 'etc_spirit_bullet_blue_i00', 0);
INSERT INTO `all_items` VALUES (1464, 'Soulshot (C-Grade)', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Ранга C.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with a C-grade weapon.', 'etc_spirit_bullet_green_i00', 0);
INSERT INTO `all_items` VALUES (1465, 'Soulshot (B-Grade)', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Ранга B.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with a B-grade weapon.', 'etc_spirit_bullet_red_i00', 0);
INSERT INTO `all_items` VALUES (1466, 'Soulshot (A-Grade)', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Ранга A.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with an A-grade weapon.', 'etc_spirit_bullet_silver_i00', 0);
INSERT INTO `all_items` VALUES (1467, 'Soulshot (S-Grade)', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Ранга S.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with an S-grade weapon.', 'etc_spirit_bullet_gold_i00', 0);
INSERT INTO `all_items` VALUES (1468, 'Gludin Panacen', NULL, 'Лечебные травы из Глудио. Можно купить в замке Глудио.', 'A medicated herb from Gludio. Purchase at the Castle Gludio.', 'etc_reagent_gold_i00', 0);
INSERT INTO `all_items` VALUES (1469, 'Gludin Vermouth', NULL, 'Целебное вино из Глудио. Можно купить в замке Глудио.', 'Medicated wine from Gludio. Purchase at the Castle Gludio.', 'etc_fruit_green_i00', 0);
INSERT INTO `all_items` VALUES (1470, 'Artemeter', NULL, 'Лечебная трава из Глудио. Можно купить в замке Глудио.', 'A medicated herb from Gludio. Purchase at the Castle Gludio.', 'etc_leaf_green_i00', 0);
INSERT INTO `all_items` VALUES (1471, 'Silenos Blowgun', NULL, NULL, NULL, 'weapon_monster_i00', 1);
INSERT INTO `all_items` VALUES (1472, 'Dreadbane', NULL, NULL, NULL, 'weapon_monster_i00', 1);
INSERT INTO `all_items` VALUES (1473, 'Kasha Wolf Fang', NULL, 'Клык, полученный при убийстве Волка Кхаши. Соберите 50 штук и отнесите их Преторианцу Рукайну.', 'A fang that is obtained by killing a kasha wolf. Collect fifty and take these to Praetorian Rukain.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1474, 'Grave Robber\'s Head', NULL, 'Голова гоблина, грабившего могилы Орков. Соберите 50 штук и отнесите их Провидцу Ливине.', 'The head of goblin robbers, who damaged the graves of Orc ancestors. Collect 50 to take to Seer Livina.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1475, 'Black Soulstone', NULL, 'Черный камень, вырванный из сердца Когтистого Беса. Соберите их и отнесите Главарю Атуба Варкису.', 'A black soulstone pulled out of the heart of a rakeclaw imp. Collect these to take to Atuba Chief Varkees.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (1476, 'Red Soulstone', NULL, 'Красный камень, вырванный из сердца Когтистого Беса. Соберите их и отнесите Главарю Атуба Варкису.', 'A red soulstone pulled out of the heart of a rakeclaw imp. Collect these to take to Atuba Chief Varkees.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (1477, 'Maraku Werewolf Head', NULL, 'Голова Оборотня Мараку, отрезанная после его убийства. Соберите 40 штук и отнесите их Префекту Брукерсу.', 'The head of a Maraku werewolf that has been cut off after they were defeated. Collect 40 of these and take them to Prefect Brukurse.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (1478, 'Darkwing Bat Fang', NULL, 'Коготь летучей мыши. Соберите 70 штук и отнесите их Главарю Неруга Тантусу.', 'A fang of a darkwing bat. Collect 70 of these and take them to Neruga Chief Tantus.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1479, 'Varangka\'s Parasite', NULL, 'Темный паразит, призывающий Охотников Фаранги.', 'An evil parasite that summons Varangka\'s trackers.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (1480, 'Kasha Parasite', NULL, 'Паразитирующий злой дух, живущий в теле серого медведя, зараженного духом Кхаши. Это ключ к Тотемному Духу Кхаши.', 'A parasite-type evil spirit that comes out of the gray bear polluted by kasha\'s evil spirit. This is the key calling forth the kasha totem spirit.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (1481, 'Kasha Crystal', NULL, 'Кристалл, полученный с убитого серого медведя, зараженного духом Кхаши. Отнесите его Провидцу Танапи.', 'A crystal obtained by killing the gray bear totem polluted by kasha\'s evil spirit. Take this to Seer Tanapi.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (1482, 'Black Wolf Pelt', NULL, 'Шкура черного волка. Соберите 40 штук и отнесите их Марис Редбоннет.', 'Pelt of a black wolf. Collect 40 to take to Maryse Redbonnet.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (1483, 'Goblin Necklace', NULL, 'Ожерелье младшего гоблина. Соберите их и отнесите Спирону из Гильдии Золотого Колеса.', 'A necklace obtained by killing a low-level goblin. Collect these and take them to Golden Wheel\'s Spiron.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (1484, 'Goblin Pendant', NULL, 'Ожерелье старшего гоблина. Соберите их и отнесите Спирону из Гильдии Золотого Колеса.', 'A necklace obtained by killing a high-level goblin. Collect these and take them to Golden Wheel\'s Spiron.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (1485, 'Goblin Lord Pendant', NULL, 'Ожерелье вожака гоблинов. Соберите их и отнесите Спирону из Гильдии Золотого Колеса.', 'A necklace obtained by killing the goblin lord. Collect these and take them to Golden Wheel\'s Spiron.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (1486, 'Suspicious Memo', NULL, 'Подозрительная записка, найденная на теле командира гоблинов. Отнесите ее Спирону из Гильдии Золотого Колеса.', 'A suspicious memo obtained by killing a goblin brigand leader. Take this to Golden Wheel\'s Spiron.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1487, 'Suspicious Contract', NULL, 'Контракт, собранный из подозрительных записок. В контракте написано, что Гильдия Серебряных Весов наняла бандитов для атаки каравана.', 'A suspicious contract completed by collecting suspicious memos. This contract reveals that the Silver Scale Guild requested the brigands to attack the freight wagons.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1488, 'Chrysolite Ore', NULL, 'Хризолитовая руда, найденная у Орка Утуку. Соберите ее и отнесите Филару из Гильдии Серой Колонны.', 'Chrysolite Ore received from defeating Utuku Orcs. Collect these and take them to Filaur of the Gray Pillar.', 'etc_plate_blue_i00', 0);
INSERT INTO `all_items` VALUES (1489, 'Torn Map Fragment', NULL, 'Обрывок карты, показывающей скрытое месторождение хризолитовой жилы. Соберите 4 части карты, чтобы просмотреть ее целиком.', 'A part of the map that reveals the hidden vein of Chrysolite. Collect 4 of these pieces to complete the map.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1490, 'Hidden Ore Map', NULL, 'Карта, показывающая скрытое месторождение хризолитовой жилы. Отнесите ее Филару из Гильдии Серой Колонны.', 'A map that reveals a hidden vein of Chrysolite. Take this to Filaur of the Gray Pillar.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1491, 'Bat Fang', NULL, 'Клык летучей мыши. Соберите 100 штук и отнесите их Кифу из Гильдии Бронзового Ключа.', 'A fang taken by killing a blade bat or a barb bat. Collect 100 and take them to Bronze Key\'s Keef0', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1492, 'Floating Stone', NULL, 'Камень легче воздуха, который можно найти у Магического Ткача. Соберите 50 штук и отнесите их Арину из Гильдии Черной Наковальни.', 'A stone that floats on water. Obtain it from a magical weaver. Collect 50 and take them to Black Anvil\'s Arin.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (1493, 'Tarantula Spider Silk', NULL, 'Шелк тарантула, из которого они делают гнезда. Соберите его и отнесите Торговцу Мион.', 'The spider silk that makes when making their nests. Collect these and take them to Trader Mion.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (1494, 'Tarantula Spinnerette', NULL, 'Орган тарантула, отвечающий за создание нитей. Отнесите его Защитнику Натану.', 'A pocket shaped organ that makes spider silk. Take this to Defender Nathan.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1495, 'Giant Spider\'s Skin', NULL, 'Шкура, снятая с гигантского паука. Соберите их и отнесите Эдмонду.', 'The husk of a giant spider that you peel off. Collect them and take them to Edmond.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (1496, 'Voucher of Flame', NULL, 'Знак Орков-Воинов. Отнесите его Хранителю Огня Вулькусу.', 'This token represents the qualification of Orc fighters. Take this and go to the Flame Guardian Vulkus.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (1497, 'Necklace of Flame', NULL, 'Ожерелье Пламени, данное Вам Вулькусом. Отнесите его Лорду Кекеи, Предводителю Орков.', 'The necklace of flame given by Vulkus. Hand this to Kakai, the Lord of Flame, king of the Orcs.', 'item_normal142', 0);
INSERT INTO `all_items` VALUES (1498, 'License of Miner', NULL, 'Лицензия на право работать в шахтах, выдаваемая Гномам. Отнесите ее Бригадиру Лаферону.', 'A license given to Dwarves to allow them to mine. Take this and go to Foreman Laferon.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1499, 'Laferon\'s Recommendation', NULL, 'Рекомендательное письмо Бригадира Лаферона. Отнесите его Старейшине Локрину.', 'The recommendation of Foreman Laferon. Take this and go to First Elder Lockirin.', 'item_canuse15', 0);
INSERT INTO `all_items` VALUES (1500, 'Totem of Hestui', NULL, 'Тотем Хестуи. Можно продать в магазин по высокой цене.', 'The totem of the Hestui. Can be sold in any shop for a high price.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (1501, 'Maraku Werewolf Totem', NULL, 'Тотем Оборотня Мараку. Можно продать в Торговой Лавке.', 'Maraku Wolfmen Totem. Can be sold in any shop.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (1502, 'Grandma\'s Pearl', NULL, 'Вещь, когда-то принадлежавшая бабушке Марис Редбоннет. Можно продать в магазин по высокой цене.', 'An article left by the grandmother of Redbonnet. Can be sold in any shop for a high price.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (1503, 'Grandma\'s Mirror', NULL, 'Вещь, когда-то принадлежавшая бабушке Марис Редбоннет. Можно продать в магазин по высокой цене.', 'An article left by the grandmother of Redbonnet. Can be sold in any shop.', 'etc_mirror_i00', 0);
INSERT INTO `all_items` VALUES (1504, 'Grandma\'s Necklace', NULL, 'Вещь, когда-то принадлежавшая бабушке Марис Редбоннет. Можно продать в магазин по высокой цене.', 'An article left by the grandmother of Redbonnet. Can be sold in any shop.', 'accessary_aquastone_necklace_i00', 0);
INSERT INTO `all_items` VALUES (1505, 'Grandma\'s Hairpin', NULL, 'Вещь, когда-то принадлежавшая бабушке Марис Редбоннет. Можно продать в магазин по высокой цене.', 'An article left by the grandmother of Redbonnet. Can be sold in any shop.', 'etc_jewel_white_i00', 0);
INSERT INTO `all_items` VALUES (1506, 'Necklace of Courage', NULL, 'Ожерелье, которое может носить только Орк, доказавший свою храбрость.', 'A necklace that is given to young Orcs who have proven their courage.', 'accessary_necklace_of_courage_i00', 0);
INSERT INTO `all_items` VALUES (1507, 'Necklace of Valor', NULL, 'Ожерелье, которое может носить только Орк, доказавший свою доблесть.', 'A necklace that is given to young Orcs who have proven their valor.', 'accessary_necklace_of_valor_i00', 0);
INSERT INTO `all_items` VALUES (1508, 'Ring of Raccoon', NULL, 'Кольцо учеников Гильдии Бронзового Ключа.', 'A ring given to apprentices of the Bronze Key Guild.', 'accessary_ring_of_raccoon_i00', 0);
INSERT INTO `all_items` VALUES (1509, 'Ring of Firefly', NULL, 'Кольцо учеников Гильдии Черной Наковальни.', 'A ring given to apprentices of the Black Anvil Guild.', 'accessary_ring_of_firefly_i00', 0);
INSERT INTO `all_items` VALUES (1510, 'Butcher\'s Sword', NULL, 'Меч, вручаемый молодым Оркам-Воинам, отличившимся в битве.', 'A sword granted to young Orc Fighters who distinguished themselves at war.', 'weapon_orcish_sword_i00', 0);
INSERT INTO `all_items` VALUES (1511, 'Silversmith Hammer', NULL, 'Молот, который когда-то использовали кузнецы Эльморедена.', 'A hammer silversmiths of the ancient Elmoreden used.', 'weapon_iron_hammer_i00', 0);
INSERT INTO `all_items` VALUES (1512, 'Spellbook: Confusion', NULL, 'Книга, необходимая для изучения умения \"Замешательство\". Профессии: Темный Рыцарь, Ассасин.Необходимый уровень: 24.', 'Spellbook needed to learn Confusion. Used by Palus Knights and Assassins.', 'etc_spell_books_defighter_i00', 0);
INSERT INTO `all_items` VALUES (1513, 'Spellbook: Charm', NULL, 'Книга, необходимая для изучения умения \"Очарование\". Профессии: Светлый Рыцарь, Разведчик.Необходимый уровень: 20.', 'Spellbook needed to learn Charm. Used by Elven Knights and Elven Scouts.', 'etc_spell_books_efighter_i00', 0);
INSERT INTO `all_items` VALUES (1514, 'Spellbook: Resurrection', NULL, 'Книга, необходимая для изучения умения \"Воскрешение\". Профессии: Клерик, Оракул Евы, Оракул Шилен.Необходимый уровень: 20.', 'Spellbook needed to learn Resurrection. Used by Clerics, Elven Oracles, and Shillien Oracles.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (1515, 'Spellbook: Kiss of Eva', NULL, 'Книга, необходимая для изучения умения \"Поцелуй Евы\". Профессии: Клерик, Оракул Евы, Оракул Шилен.Необходимый уровень: 20.', 'Spellbook needed to learn Kiss of Eva. Used by Clerics, Elven Oracles and Shillien Oracles.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1516, 'Spellbook: Corpse Life Drain', NULL, 'Книга, необходимая для изучения умения \"Подпитка от Трупа\". Профессии: Маг, Темный Маг.Необходимый уровень: 30.', 'Spellbook needed to learn Corpse Life Drain. Used by Human Wizards and Dark Wizards.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1517, 'Spellbook: Body To Mind', NULL, 'Книга, необходимая для изучения умения \"Самобичевание\". Профессии: Маг, Темный Маг.Необходимый уровень: 25.', 'Spellbook needed to learn Body To Mind. Used by Human Wizards and Dark Wizards.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (1518, 'Amulet: Flame Chant', NULL, 'Амулет, необходимый для изучения умения \"Напев Пламени\". Профессия: Шаман.Необходимый уровень: 30.', 'Amulet required for the Flame Chant spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1519, 'Amulet: Pa\'agrio\'s Gift', NULL, 'Амулет, необходимый для изучения умения \"Дар Паагрио\". Профессия: Шаман.Необходимый уровень: 30.', 'Amulet required for the Pa\'agrio\'s Gift spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1520, 'Amulet: Pa\'agrio\'s Blessing', NULL, 'Амулет, необходимый для изучения умения \"Благословение Паагрио\". Профессия: Шаман.Необходимый уровень: 35.', 'Amulet required for the Pa\'agrio\'s Blessing spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1521, 'Amulet: Chant of Fire', NULL, 'Амулет, необходимый для изучения умения \"Напев Огня\". Профессия: Шаман.Необходимый уровень: 20.', 'Amulet required for the Chant of Fire spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1522, 'Amulet: Chant of Battle', NULL, 'Амулет, необходимый для изучения умения \"Напев Битвы\". Профессия: Адепт.Необходимый уровень: 14.', 'Amulet required for the Chant of Battle spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1523, 'Amulet: Chant of Shielding', NULL, 'Амулет, необходимый для изучения умения \"Напев Защиты\". Профессия: Шаман.Необходимый уровень: 20.', 'Amulet required for the Chant of Shielding spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1524, 'Amulet: Soul Shield', NULL, 'Амулет, необходимый для изучения умения \"Щит Души\". Профессия: Адепт.Необходимый уровень: 7.', 'Amulet required for the Soul Shield spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1525, 'Amulet: Life Drain', NULL, 'Амулет, необходимый для изучения умения \"Кража Жизни\". Профессия: Адепт.Необходимый уровень: 7.', 'Amulet required for the Life Drain spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1526, 'Amulet: Fear', NULL, 'Амулет, необходимый для изучения умения \"Страх\". Профессия: Адепт.Необходимый уровень: 14.', 'Amulet required for the Fear spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1527, 'Amulet: Venom', NULL, 'Амулет, необходимый для изучения умения \"Отрава\". Профессия: Адепт.Необходимый уровень: 7.', 'Amulet required for the Venom spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1528, 'Amulet: Seal of Chaos', NULL, 'Амулет, необходимый для изучения умения \"Печать Хаоса\". Профессия: Шаман.Необходимый уровень: 30.', 'Amulet required for the Seal of Chaos spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1529, 'Amulet: Dreaming Spirit', NULL, 'Амулет, необходимый для изучения умения \"Сонный Дух\". Профессия: Адепт.Необходимый уровень: 7.', 'Amulet required for the Spirit Dream spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1530, 'Amulet: Seal of Slow', NULL, 'Амулет, необходимый для изучения умения \"Печать Замедления\". Профессия: Шаман.Необходимый уровень: 35.', 'Amulet required for the Seal of Slow spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1531, 'Amulet: Chill Flame', NULL, 'Амулет, необходимый для изучения умения \"Остужающее Пламя\". Профессия: Адепт.Необходимый уровень: 7.', 'Amulet required for the Chill Flame spell. Used by Orc Mystics.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1532, 'Amulet: Blaze Quake', NULL, 'Амулет, необходимый для изучения умения \"Дрожь Огня\". Профессия: Шаман.Необходимый уровень: 25.', 'Amulet required for the Blaze Quake spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1533, 'Amulet: Aura Sink', NULL, 'Амулет, необходимый для изучения умения \"Ослабление Ауры\". Профессия: Шаман.Необходимый уровень: 25.', 'Amulet required for the Aura Sink spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1534, 'Amulet: Madness', NULL, 'Амулет, необходимый для изучения умения \"Сумасшествие\". Профессия: Шаман.Необходимый уровень: 20.', 'Amulet required for the Madness spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1535, 'Amulet: Frost Flame', NULL, 'Амулет, необходимый для изучения умения \"Морозное Пламя\". Профессия: Шаман.Необходимый уровень: 20.', 'An amulet that is needed for the Frost Flame spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1536, 'Amulet: Seal of Binding', NULL, 'Амулет, необходимый для изучения умения \"Печать Привязи\". Профессия: Шаман.Необходимый уровень: 25.', 'Amulet required for the Seal of Binding spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1537, 'Amulet: Seal of Poison', NULL, 'Амулет, необходимый для изучения умения \"Печать Яда\". Профессия: Шаман.Необходимый уровень: 20.', 'Amulet required for the Seal of Poison spell. Used by Orc Shamans.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1538, 'Blessed Scroll of Escape', NULL, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение.', 'A magical scroll that relocates you to the nearest village0', 'etc_scroll_of_return_i01', 1);
INSERT INTO `all_items` VALUES (1539, 'Greater Healing Potion', NULL, 'Магическое зелье быстрого восстановления НР. Эффект длится 15 секунд.', 'A magical potion that quickly restores HP. Its effect lasts for 15 seconds.', 'etc_reagent_white_i00', 3);
INSERT INTO `all_items` VALUES (1540, 'Quick Healing Potion', NULL, 'Магическое зелье быстрого восстановления НР.', 'A magical potion that quickly restores HP.', 'etc_potion_gold_i00', 3);
INSERT INTO `all_items` VALUES (1541, 'Honey Khandar', NULL, 'Удивительный препарат, созданный из меда и экстракта хандара. Отнесите его Центуриону Накушину.', 'A miraculous medicine made of the mixture of honey and khandar extract. Take this to Centurion Nakusin.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (1542, 'Bear Fur Cloak', NULL, 'Плащ, сделанный из меха гризли. Отнесите его Центуриону Накушину.', 'A cloak made of grizzly bear\'s fur. Excellent for keeping warm. Take this to Centurion Nakusin.', 'etc_piece_of_cloth_black_i00', 0);
INSERT INTO `all_items` VALUES (1543, 'Bloody Axe', NULL, 'Топор, покрытый кровью диких животных. Говорят, он придает жизненные силы своему владельцу. Отнесите его Центуриону Накушину.', 'An axe that holds the blood of wild animals. It is said to strengthen its owner\'s life force. Take this to Centurion Nakusin.', 'weapon_tomahawk_i00', 0);
INSERT INTO `all_items` VALUES (1544, 'Ancestor Skull', NULL, 'Череп предка Урутуса. Говорят, он придает силы своему хозяину. Отнесите его Центуриону Накушину.', 'A skull of an ancestor of Urutus. It is said to strengthen its owner\'s life force. Take this to Centurion Nakusin.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (1545, 'Spider Dust', NULL, 'Порошок из сушеных лапок ядовитого паука. Как ни странно, обладает очень освежающим запахом. Отнесите его Центуриону Накушину.', 'A grain of powder made of dried legs of poisonous spiders. Smelling it will make you feel refreshed. Take this to Centurion Nakusin.', 'etc_powder_white_i00', 0);
INSERT INTO `all_items` VALUES (1546, 'Deep Sea Orb', NULL, 'Жемчужина, найденная глубоко в море. Говорят, она помогает предсказывать будущее. Отнесите ее Центуриону Накушину.', 'A pearl brought out of a deep sea. It is said to help predict the future. Take this to Centurion Nakusin.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (1547, 'Bolter\'s List', NULL, 'Список вещей, которые надо принести Больтеру из деревни.', 'The list of things that Bolter wants you to bring from the village.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1548, 'Mining Boots', NULL, 'Пара шахтерских сапог, полученных от Торговца Гариты. Отдайте их Шахтеру Больтеру.', 'A pair of mining boots you got from Trader Garita. Take this to Miner Bolter.', 'armor_apprentices_shoes_i00', 0);
INSERT INTO `all_items` VALUES (1549, 'Miner\'s Pick', NULL, 'Кирка Шахтера, полученная у Кузнеца Брюнона. Отдайте ее Шахтеру Больтеру.', 'A miner\'s pick you got from Blacksmith Brunon. Take this to Miner Bolter.', 'weapon_guard_spear_i00', 0);
INSERT INTO `all_items` VALUES (1550, 'Boomboom Powder', NULL, 'Мешочек со взрывным порошком, полученный у Торговца Шари. Отнесите его Шахтеру Больтеру.', 'A sack of boomboom powder you got from Trader Shari. Take this to Miner Bolter.', 'etc_powder_black_i00', 0);
INSERT INTO `all_items` VALUES (1551, 'Redstone Beer', NULL, 'Восхитительное пиво, полученное у Начальника Склада Рида. Отнесите его Шахтеру Больтеру.', 'Delicious beer you got from Warehouse Chief Reed. Take this to Miner Bolter.', 'etc_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (1552, 'Bolter\'s Smelly Socks', NULL, 'Пара носков, которые Вам дал Шахтер Больтер. Интересно, зачем?..', 'A pair of socks that Miner Bolter gave you. For what...?', 'armor_cotton_shoes_i00', 0);
INSERT INTO `all_items` VALUES (1553, 'Hatos\'s 1st Order', NULL, 'Заказ на убийство Посланника Фаранги. Вам нужно забрать у него письмо и отдать его Главарю Уруту Хатосу.', 'The order to kill Baranka\'s messenger. After killing him, recover the letter and take it to Urutu Chief Hatos.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1554, 'Hatos\'s 2nd Order', NULL, 'Заказ на убийство Посланника Фаранги. Вам нужно забрать у него письмо и отдать его Главарю Уруту Хатосу.', 'The order states that you must kill Baranka\'s messenger. After killing him, recover the letter and take it to Urutu Chief Hatos.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1555, 'Hatos\'s 3rd Order', NULL, 'Заказ на убийство Посланника Фаранги. Вам нужно забрать у него письмо и отдать его Главарю Уруту Хатосу.', 'The order states that you must kill Baranka\'s messenger. After killing him, recover the letter and take it to Urutu Chief Hatos.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (1556, 'Letter to Dark Elf', NULL, 'Секретное письмо Фаранги, адресованное Магистру Темных Эльфов. Отнесите его Главарю Уруту Хатосу.', 'The secret letter that Baranka is sending to Dark Elven Magister Kaland. Take the letter to Urutu Chief Hatos.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1557, 'Letter to Human', NULL, 'Секретное письмо Фаранги, адресованное герцогу Ван Холтеру. Отнесите его Главарю Уруту Хатосу.', 'The secret letter that Baranka is sending to Duke Van Halter. Take the letter to Urutu Chief Hatos.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1558, 'Letter to Elf', NULL, 'Секретное письмо Фаранги, адресованное Мастеру Эльфов Ларии. Отнесите его Главарю Уруту Хатосу.', 'The secret letter that Baranka is sending to Elven Master Laria. Take the letter to Urutu Chief Hatos.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1559, 'Gouph\'s Contract', NULL, 'Контракт, заключенный Коллекционером Гуфом при покупке Звездного Алмаза у Торговца Рипа. Отнесите его Торговцу Рипу.', 'Collector Gouph drew up this contract when buying the star diamond from Trader Reep. Take this to Trader Reep.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1560, 'Reep\'s Contract', NULL, 'Контракт на доставку Звездного Алмаза. Отнесите его Посыльному Торокко.', 'Trader Reep drew up this contract when he requested the delivery of the star diamond. Take this to Carrier Torocco.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1561, 'Elven Wine', NULL, 'Вино, купленное Посыльным Торокко для его старого друга Марона. Отнесите его Шахтеру Марону.', 'Carrier Torocco bought this high quality wine to give it to his old friend, Maron, as a present. Take this to Miner Maron.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (1562, 'Brunon\'s Dice', NULL, 'Особые игральные кости. Отнесите их Кузнецу Брюнону.', 'These dice were specially made for gambling. Take these to Blacksmith Brunon.', 'etc_squares_silver_i00', 0);
INSERT INTO `all_items` VALUES (1563, 'Brunon\'s Contract', NULL, 'Расписка, в которой Брюнон обещает вернуть Звездный Алмаз, если получит назад 20 камней, украденных гоблинами.', 'This contract says if Brunon gets the 20 stolen jewels back from goblins, he can get the star diamond back.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1564, 'Aquamarine', NULL, 'Драгоценный камень, найденный на теле Лейтенанта Банды Гоблинов. Отнесите 10 Аквамаринов и 10 Хризобериллов Кузнецу Брюнону.', 'This jewel is obtained by the goblin brigand leader. Take 10 aquamarines and 10 chrysoberyls to Blacksmith Brunon.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (1565, 'Chrysoberyl', NULL, 'Драгоценный камень, найденный на теле Лейтенанта Банды Гоблинов. Отнесите 10 Аквамаринов и 10 Хризобериллов Кузнецу Брюнону.', 'This jewel is obtained by the goblin brigand leader. Take 10 aquamarines and 10 chrysoberyls to Blacksmith Brunon.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (1566, 'Gem Box', NULL, 'Шкатулка, полученная от Кузнеца Брюнона. Отнесите ее Коллекционеру Гуфу.', 'Blacksmith Brunon gives this gem box. Take it to Collector Gouph.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1567, 'Coal Piece', NULL, 'Кусок угля, найденный в шкатулке с самоцветами. Верните его Кузнецу Брюнону.', 'This coal piece is in the gem box. Take this to Blacksmith Brunon.', 'etc_plate_black_i00', 0);
INSERT INTO `all_items` VALUES (1568, 'Brunon\'s Letter', NULL, 'Письмо Кузнеца Брюнона Рабочему Склада Мердоку с просьбой вернуть шкатулку со Звездным Алмазом.', 'Blacksmith Brunon sends this letter to Warehouse Keeper Murdoc asking for the right box.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (1569, 'Berry Tart', NULL, 'Сладкий клубничный пирог, подарок от Мердока Смотрителю Склада Эйри.', 'Sweet strawberry-flavored tart. Warehouse Keeper Murdoc sends this to Warehouse Keeper Airy as a present of apology.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (1570, 'Bat Diagram', NULL, 'Рисунок, изображающий Опасную Летучую Мышь. Пригодится для охоты за Звездным Алмазом.', 'This diagram shows the blade bat in details. Take this and go hunt blade bats to obtain the star diamond.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1571, 'Star Diamond', NULL, 'Прекрасный алмаз. Вы должны вернуть его владельцу.', 'Everyone is looking for this diamond. Take this to the real owner.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (1572, 'Starstone', NULL, 'Минерал, из которого состоит тело Серого Голема. Соберите 20 таких камней и отнесите их Хранителю Портала Тамил.', 'A mineral collected from the destroyed greystone golem. Collect 20 of these and take them to Gatekeeper Tamil.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (1573, 'Starstone', NULL, 'Минерал, из которого состоит тело Базальтового Голема. Соберите 20 таких камней и отнесите их Хранителю Портала Вирфи.', 'A mineral obtained by defeated whinstone golems. Collect twenty and take them to Gatekeeper Wirphy.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (1574, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен по поводу блюд Джонаса. Отнесите его Джонасу.', 'A letter Magister Mirien wrote after tasting Jonas\'s dish. Take this and go to Jonas.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1575, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен по поводу блюд Джонаса. Отнесите его Джонасу.', 'A letter Magister Mirien wrote after tasting Jonas\'s dish. Take this to Jonas.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1576, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен по поводу блюд Джонаса. Отнесите его Джонасу.', 'A letter Magister Mirien wrote after tasting Jonas\'s dish. Take this to Jonas.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1577, 'Mirien\'s Review', NULL, 'Письмо Магистра Мириен по поводу блюд Джонаса. Отнесите его Джонасу.', 'A letter Magister Mirien wrote after tasting Jonas\'s dish. Take this to Jonas.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1578, 'Green Blood', NULL, 'Кровь Гоблина. Когда у Вас будет достаточно крови, появится Главарь Крысолюдов Курука.', 'Goblin\'s blood. If you have enough of this item, the Kuruka ratman leader appears.', 'etc_reagent_green_i00', 0);
INSERT INTO `all_items` VALUES (1579, 'Goblin Dwelling Map', NULL, 'Карта мест обитания гоблинов.', 'A map showing goblins\' dwelling. Take this and find the goblin tribes and destroy them.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1580, 'Kuruka Ratman Tooth', NULL, 'Зуб, полученный после убийства Главаря Крысолюдов Курука. Соберите 10 таких и отдайте их Префекту Карукии.', 'A tooth obtained after killing Kuruka ratman leader. Collect ten of these to take to Prefect Karukia.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1581, 'Betrayer\'s Report', NULL, 'Подробный отчет о предателе, который присоединился к племени Умбар и поселился в предгорье к западу от Гнезда Пауков.', 'A detailed account of a betrayer who recently joined the Umbar tribe and settled on the outskirts of a mountain west of the Spider Nest.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1582, 'Betrayer\'s Report', NULL, 'Подробный отчет о предателе, который присоединился к племени Умбар и поселился в предгорье к западу от Гнезда Пауков.', 'A detailed account of a betrayer who recently joined the Umbar tribe and settled on the outskirts of a mountain west of the Spider Nest.', 'etc_piece_of_paper_white_i00', 0);
