INSERT INTO `all_items` VALUES (1589, 'Betrayer\'s Report', NULL, 'Подробный отчет о предателе, который присоединился к племени Умбар и поселился в предгорье к западу от Гнезда Пауков.', 'A detailed account of a betrayer who recently joined the Umbar tribe and settled on the outskirts of a mountain west of the Spider Nest.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1590, 'Betrayer\'s Report', NULL, 'Подробный отчет о предателе, который присоединился к племени Умбар и поселился в предгорье к западу от Гнезда Пауков.', 'A detailed account of a betrayer who recently joined the Umbar tribe and settled on the outskirts of a mountain west of the Spider Nest.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (1591, 'Head of Betrayer', NULL, 'Голова Орка предателя. Соберите 2 такие и отдайте Префекту Касману из Глудина.', 'The head of a traitor orc. Collect 2 and take them to Prefect Kasman in Gludin Village.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (1592, 'Mark of Raider', NULL, 'Ожерелье, вручаемое Оркам, готовым стать Налетчиками. Отдайте его Понтифику для смены профессии.', 'A necklace given to an Orc who has earned the qualification to become an Orc Raider. Take this to the high prefect to change your occupation to an Orc Raider.', 'accessary_earing_of_black_ore_i00', 0);
INSERT INTO `all_items` VALUES (1593, 'Pomegranate', NULL, 'Спелый гранат, полученный от Гентаки. Отнесите его Аватару Рошику.', 'A red pomegranate fruit given by Gantaki. Take this and go to Khavatari Rosheek.', 'etc_fruit_red_i00', 0);
INSERT INTO `all_items` VALUES (1594, '1st Leather Pouch', NULL, 'Кожаный мешочек, полученный от Аватара Рошика. Вам необходимо наполнить его когтями Медведей Кхаши.', 'A leather pouch given by Khavatari Rosheek. Take this and hunt kasha bears and collect 5 of their claws.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1595, '2nd Leather Pouch', NULL, 'Кожаный мешочек, полученный от Аватара Рошика. Вам необходимо наполнить его когтями Опасных Пауков Кхаши.', 'A leather pouch given by Khavatari Rosheek. Hunt kasha blade spiders with this and collect 5 talons.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1596, '3rd Leather Pouch', NULL, 'Кожаный мешочек, полученный от Аватара Рошика. Вам необходимо наполнить его чешуйками Алых Саламандр.', 'A leather pouch Khavatari Rosheek gave you. Take this while hunting scarlet salamanders to obtain 5 of their scales.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1597, '1st Leather Pouch (Full)', NULL, 'Мешочек, в котором лежат 5 когтей Медведей Кхаши. Отдайте его Аватару Рошику.', 'A pouch that contains 5 kasha bear claws. Take this to Khavatari Rosheek.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1598, '2nd Leather Pouch (Full)', NULL, 'Мешочек, в котором лежат 5 когтей Опасных Пауков Кхаши. Отдайте его Аватару Рошику.', 'A pouch that contains 5 pincers of kasha blade spider talon. Take this to Khavatari Rosheek.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1599, '3rd Leather Pouch (Full)', NULL, 'Мешочек, в котором лежат 5 чешуек Алых Саламандр. Отдайте его Аватару Рошику.', 'A pouch that contains 5 scales from the scarlet salamander. Take this to Khavatari Rosheek.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1600, 'Kasha Bear Claw', NULL, 'Коготь убитого Медведя Кхаши. Вам необходимо собрать 5 таких.', 'A claw pulled out from a kasha bear after killing it. Collect 5 of these.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1601, 'Kasha Blade Spider Talon', NULL, 'Коготь убитого Опасного Паука Кхаши. Вам необходимо собрать 5 таких.', 'A talon pulled out from a kasha blade spider after killing it. Collect 5 of these.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1602, 'Scarlet Salamander Scale', NULL, 'Чешуйка Алой Саламандры. Вам необходимо собрать 5 таких.', 'A scale of a scarlet salamander. Collect 5 of these.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (1603, 'Fiery Spirit Scroll', NULL, 'Первый свиток, содержащий тайну традиционного воинского искусства Орков, Кабарта.', 'The first scroll containing secret of kabart, the Orcs\' traditional martial arts.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1604, 'Rosheek\'s Letter', NULL, 'Письмо, написанное Аватаром Рошиком. Отдайте его Гентаки Зу Уруту.', 'A letter written by Khavatari Rosheek. Take this to Gantaki Zu Urutu.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1605, 'Gantaki\'s Letter of Recommendation', NULL, 'Рекомендательное письмо Гентаки. Обратитесь к Хранителю Портала Тамил и отнесите эту рекомендацию Префекту Касману в Глудин.', 'Gantaki\'s letter of recommendation. Receive the help of Gatekeeper Tamil and take this recommendation to Prefect Kasman in the Village of Gludin.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1606, 'Fig', NULL, 'Инжир, полученный от Префекта Касмана. Отдайте его Аватару Торуку.', 'A fig given by Prefect Kasman. Take this to Khavatari Toruku.', 'etc_fruit_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1607, '4th Leather Pouch', NULL, 'Мешочек, полученный от Аватара Торуку. Убивайте воинов различных племен и соберите 12 их клыков.', 'A leather pouch given by Khavatari Toruku. Take this, kill fighters of various races and collect 12 tokens.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (1608, '4th Leather Pouch (Full)', NULL, 'Мешочек, наполненный клыками убитых воинов. Отдайте его Аватару Торуку.', 'A full pouch of 12 tokens after killing fighters of various races. Take this to Khavatari Toruku.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (1609, 'Vuku Orc Tusk', NULL, 'Клык, полученный при убийстве Орка Вуку. Необходимо собрать 3 штуки.', 'A tusk obtained after killing a vuku Orc. Gather 3 of these.', 'etc_molar_white_i00', 0);
INSERT INTO `all_items` VALUES (1610, 'Ratman Fang', NULL, 'Коготь, полученный при убийстве Крысолюда Воина. Необходимо собрать 3 штуки.', 'A fang from a dead ratman fighter. Gather 3 of these.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1611, 'Langk Lizardman Tooth', NULL, 'Зуб, полученный при убийстве Ящера Лангк. Необходимо собрать 3 штуки.', 'A tooth obtained after killing a Langk lizardman. Gather 3 of these.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1612, 'Felim Lizardman Tooth', NULL, 'Зуб, полученный при убийстве Ящера Фелим. Необходимо собрать 3 штуки.', 'A tooth obtained after killing the Felim lizardman. Gather 3 of these.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1613, 'Iron Will Scroll', NULL, 'Второй свиток, содержащий тайну традиционного воинского искусства Орков, Кабарта.', 'The second scroll that contains secret of the Orcs\' traditional martial arts, Kabart.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1614, 'Toruku\'s Letter', NULL, 'Письмо Аватара Торуку. Отдайте его Префекту Касману.', 'A letter from Khavatari Toruku. Take this to Prefect Kasman.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (1615, 'Khavatari Totem', NULL, 'Тотем того, кто достоин стать Монахом. Отдайте его Понтифику для смены профессии.', 'A token given to one who has qualifications to change occupations to Orc Monk. Take this to the high prefect to change your occupation to an Orc Monk.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1616, 'Fire Charm', NULL, 'Оберег с описанием молитвы огня. Возьмите его и найдите 3 предмета, о которых говорил Татару.', 'A charm with inscription of fire mantra. Take this and find the 3 items that Tataru spoke of.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1617, 'Kasha Bear Pelt', NULL, 'Шкура Медведя Кхаши. Отнесите ее Татару вместе с Кожей Опасного Паука Кхаши и Огненным Яйцом.', 'A pelt of kasha bear. Take to Tataru along with kasha bladespider husk and fiery egg.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (1618, 'Kasha Blade Spider Husk', NULL, 'Кожа Опасного Паука Кхаши. Отнесите ее Татару вместе со Шкурой Медведя Кхаши и Огненным Яйцом.', 'The husk of a kasha blade spider. Take it to Tataru, along with a kasha bear pelt and a fiery egg.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (1619, '1st Fiery Egg', NULL, 'Яйцо, полученное от Алой Саламандры. Отдайте его Татару вместе со Шкурой Медведя Кхаши и Кожей Опасного Паука Кхаши.', 'A spirit egg obtained from a scarlet salamander. Take it to Tataru along with a kasha bear pelt and a kasha bladespider husk.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (1620, 'Hestui Mask', NULL, 'Маска медведя. Отнесите ее тотемному духу Хестуи.', 'A mask in shape of bear. Take this and go to Hestui totem spirit.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (1621, '2nd Fiery Egg', NULL, 'Яйцо, полученное от Алой Саламандры. Отдайте его Татару вместе со Шкурой Медведя Кхаши и Кожей Опасного Паука Кхаши.', 'A spirit egg received from a scarlet salamander. Take this to the Hestui totem spirit.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (1622, 'Totem Spirit Claw', NULL, 'Коготь, полученный у тотемного духа Хестуи. Возьмите его и идите к Татару.', 'A claw received from Hestui totem spirit. Take this and go to Tataru.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1623, 'Tataru\'s Letter of Recommendation', NULL, 'Письмо, написанное Татару. Отдайте его Провидцу Умосу в Глудине.', 'A letter written by Tataru. Take this to Seer Umos in the town of Gludin.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1624, 'Flame Charm', NULL, 'Оберег с описанием молитвы огня. Возьмите его, соберите кровь гризли и отдайте Провидцу Умосу.', 'A charm with inscription of flame mantra. Take this and gather grizzly blood and take to Seer Umos.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1625, 'Grizzly Blood', NULL, 'Стеклянная бутылка, наполненная кровью гризли. Соберите 3 таких и отнесите Провидцу Умосу.', 'A glass bottle filled with grizzly blood. Gather 3 and take to Seer Umos.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (1626, 'Blood Cauldron', NULL, 'Кувшин, наполненный кровью гризли. Отдайте его духу Дуда-Мара.', 'A cauldron filled with grizzly blood. Take this to the Duda-Mara totem spirit.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (1627, 'Spirit Net', NULL, 'Сеть, сплетенная из паучьего шелка. Используйте ее для поимки Духа Дарки, прячущегося внутри Ядовитых Пауков.', 'A net made with spirit\'s spider silk. Use this to capture durka spirit hidden inside poison spiders.', 'etc_piece_of_cloth_white_i00', 0);
INSERT INTO `all_items` VALUES (1628, 'Bound Durka Spirit', NULL, 'Дух Дарки, пойманный призрачной сетью. Отдайте его духу Дуда-Мара.', 'Durka spirit bound inside spirit net. Take this to the Duda-Mara totem spirit.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (1629, 'Durka Parasite', NULL, 'Злой дух, который исходит из пауков, зараженных духом Дарки. Необходим для призыва духа Дарки.', 'An evil parasite spirit that comes out from spiders contaminated with the evil durka spirit. It is the key for calling upon the evil durka spirit.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (1630, 'Totem Spirit Blood', NULL, 'Кровь тотема Дуда-Мара. Отнесите ее Провидцу Умосу.', 'Blood spilt by the Duda-Mara totem spirit. Take this and go to Seer Umos.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (1631, 'Mask of Medium', NULL, 'Маска, вручаемая только Оркам, достойным стать Шаманами. Отнесите ее Понтифику для смены профессии.', 'A token that shows one has the qualifications to become an Orc Shaman. Take this to the high prefect, to change your occupation to an Orc Shaman.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (1632, 'Silvera\'s Ring', NULL, 'Кольцо, сделанное для кандидатов в ремесленники Кузнецом Сильверой. Убейте Крысолюдов Бугл и соберите их зубы.', 'A ring given to artisan aspirants by Blacksmith Silvera. Strike down the boogle ratman gang and collect their front teeth.', 'accessary_ring_of_assistance_i00', 0);
INSERT INTO `all_items` VALUES (1633, '1st Pass Certificate', NULL, 'Свидетельство об успешном прохождении I испытания Ремесленника. Далее Вы должны поговорить с Клуто из Глудина.', 'The certificate for passing the 1st artisan test. To take the next test, you must go to Blacksmith Kluto of the village Gludin.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1634, '2nd Pass Certificate', NULL, 'Свидетельство об успешном прохождении II испытания Ремесленника. Отнесите его Кузнецу Клуто в Глудин.', 'The certificate for passing the 2nd artisan test. Take this and go to Blacksmith Kluto in Gludin.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1635, 'Final Pass Certificate', NULL, 'Свидетельство об успешном прохождении последнего испытания Ремесленника. Отдайте его Главному Кузнецу для смены профессии.', 'The certificate for passing the final Artisan test. Take this to the head blacksmith to change occupations to an Artisan.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (1636, 'Boogle Ratman Tooth', NULL, 'Уродливый зуб Крысолюда Бугл. Один его вид вызывает тошноту. Соберите 10 таких зубов и отдайте их Кузнецу Сильвере.', 'The ugly front bucktooth of a boogle ratman. Just looking at it will make you nauseous. Collect 10 of these and take them to Blacksmith Silvera.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (1637, 'Boogle Ratman Leader\'s Tooth', NULL, 'Очень вонючий зуб Главаря Крысолюдов Бугл. Найдите 2 штуки и отдайте их Кузнецу Сильвере.', 'The boogle ratman leader\'s big tooth. Before its stink makes you pass out, collect 2 of them and take them to Blacksmith Silvera.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (1638, 'Kluto\'s Letter', NULL, 'Письмо Кузнеца Клуто. Отнесите его Кузнецу Пинтеру в Глудио.', 'Blacksmith Kluto\'s letter. Take to Blacksmith Pinter in the Town of Gludio.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1639, 'Footprint of Thief', NULL, 'След, оставленный ворами. Убейте Бойцов Орков Вуку, верните украденные вещи и отнесите их Кузнецу Пинтеру.', 'Trace left by thieves. Kill Vuku Orc fighters, recover stolen items and take them to Blacksmith Pinter.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (1640, 'Stolen Secret Box', NULL, 'Ящик, украденный Бойцами Орков Вуку. Содержимое его неизвестно, но в любом случае отдайте его Кузнецу Пинтеру.', 'A secret box stolen by Vuku orc fighters. The contents of the box are unknown, but anyway, take it to Blacksmith Pinter.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1641, 'Secret Box', NULL, 'Ящик, полученный от Пинтера. Содержимое его неизвестно, но Вас оно и не должно волновать - просто отнесите сундук Кузнецу Клуто в Глудин.', 'A secret box received from Pinter. The contents are unknown, but do not worry and take it to Blacksmith Kluto in the Village of Gludin.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (1642, 'Ring of Raven', NULL, 'Знак, необходимый для того, чтобы стать Собирателем. Если Вы отдадите его Начальнику Склада, то сможете сменить профессию.', 'A mark certifying that one has earned the right to become a Scavenger. If you take it to a Warehouse Chief, you can transfer your class to Scavenger.', 'accessary_ring_of_raccoon_i00', 0);
INSERT INTO `all_items` VALUES (1643, 'Pippi\'s Letter of Recommendation', NULL, 'Рекомендация, написанная Коллекционером Пепи. Отдайте ее Торговцу Мион.', 'A letter of introduction written by Collector Pipi. Take this to Trader Mion.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (1644, 'Raut\'s Teleport Scroll', NULL, 'Заказ Раута. Отнесите его Тораю в южную часть Долины Смерти.', 'An order sheet given by Warehouse Freightman Raut. Give it to Torai, in the south of Death Pass.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (1645, 'Succubus Undies', NULL, 'Белье Суккуба, полученное от Торая. Отнесите его Рабочему Склада Рауту в Глудин.', 'The underwear of Succubus received from Torai. Take this to Warehouse Freightman Raut of Gludin.', 'etc_piece_of_cloth_black_i00', 0);
INSERT INTO `all_items` VALUES (1646, 'Mion\'s Letter', NULL, 'Письмо от Торговца Мион своему брату. Отнесите его Мастеру Томе.', 'A letter sent from Trader Mion to her brother. Take this letter and go to Master Toma.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (1647, 'Bronk\'s Ingot', NULL, 'Слиток, который надо отдать Главному Кузнецу Бронку.', 'An ingot to be given to Chief Blacksmith Bronk.', 'etc_plate_glay_i00', 0);
INSERT INTO `all_items` VALUES (1648, 'Shari\'s Axe', NULL, 'Топор, который надо отдать Торговцу Шари.', 'An axe to be given to Trader Shari.', 'weapon_tomahawk_i00', 0);
INSERT INTO `all_items` VALUES (1649, 'Zimenf\'s Potion', NULL, 'Зелье, которое нужно отдать Жрецу Земли Зименфу.', 'A potion to give to Priest of the Earth Zimenf.', 'etc_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (1650, 'Bronk\'s Pay', NULL, 'Плата Главного Кузнеца Бронка. Отдайте ее Торговцу Мион.', 'Product cost given by Chief Blacksmith Bronk. Take this to Trader Mion.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (1651, 'Shari\'s Pay', NULL, 'Плата Шари. Отдайте ее Торговцу Мион.', 'Product cost given by Shari. Take this to Trader Mion.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (1652, 'Zimenf\'s Pay', NULL, 'Плата Зименфа. Отдайте ее Торговцу Мион.', 'Product cost given by Zimenf. Take this to Trader Mion.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (1653, 'Bear Picture', NULL, 'Рисунок медведя, полученный от Мастера Томы. Убивайте Медведей Охотников до тех пор, пока не появится Медовый Медведь.', 'A picture of a bear received by Master Toma. Take this to hunt hunter bears, then the honey bear will appear.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1654, 'Tarantula Picture', NULL, 'Рисунок паука, полученный от Мастера Томы. Используйте его при охоте на Тарантулов.', 'A picture of spider received by Master Toma. Use this to hunt tarantulas.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1655, 'Honey Jar', NULL, 'Банка с медом, полученная от Медового Медведя. Соберите 5 таких банок и отдайте их Мастеру Томе.', 'A honey jar taken from a honey bear. Collect 5 and take them to Master Toma.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (1656, 'Bead', NULL, 'Бусинка, полученная из Тарантула. Соберите 20 таких и отдайте их Мастеру Томе.', 'A bead obtained from tarantula. Gather 20 of these and give to Master Toma.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (1657, 'Bead Parcel', NULL, 'Связка из бусинок. Отнесите ее Рабочему Склада Рауту в Глудин.', 'A parcel made of beads. Give this to Warehouse Freightman Raut of Gludin.', 'accessary_mage_earing_i00', 0);
INSERT INTO `all_items` VALUES (1658, 'Gatekeeper Charm', NULL, 'Оберег, используемый для перемещения из Деревни Орков в Глудин.', 'Used to teleport from the Orc Village to Gludin.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (1659, 'Gatekeeper Token', NULL, 'Знак, используемый для перемещения из Деревни Гномов в Глудин.', 'Used to teleport from the Dwarven Village to Gludin.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (1660, 'Cursed Maingauche', NULL, 'Проклятая Дага. Имеет маленькую Ф. Атк., однако с некоторой вероятностью вызывает у противника кровотечение при нанесении критического урона.', 'Cursed Maingauche. Although its attack power is weak, it gives bleeding effect with a certain rate during critical attacks.', 'weapon_maingauche_i01', 1);
INSERT INTO `all_items` VALUES (1661, 'Thief Key', NULL, NULL, NULL, 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (1662, 'Wood', NULL, 'Материал, используемый Гномами для создания предметов. Можно продать в Торговой Лавке.', 'A material used to make Dwarven items. Can be sold in any shop.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (1663, '(Not In Use) Trunk', NULL, 'Материал, используемый Гномами для создания предметов. Можно продать в Торговой Лавке.', 'A material used to make Dwarven items. Can be sold in any shop.', 'etc_branch_gold_i00', 0);
INSERT INTO `all_items` VALUES (1664, 'Steel Powder', NULL, 'Материал, используемый Гномами для создания предметов. Можно продать в Торговой Лавке.', 'A material used to make Dwarven items. Can be sold in any shop.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (1665, 'World Map', NULL, 'Древняя карта. Можно продать в Торговой Лавке.', 'An ancient, obsolete map. Can be purchased at any shop.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (1666, 'Recipe: Wooden Arrow', NULL, 'Только для Гномов. Рецепт создания Деревянных Стрел. Требуется умение \"Создать Вещь\" 1-го уровня. Шанс создания: 100%.', 'For Dwarves only. The recipe for a Wooden Arrow. Requires Create Item Level 1. The success rate is 100%.', 'etc_recipe_white_i00', 5);
INSERT INTO `all_items` VALUES (1667, 'Spellbook: Summon Shadow', NULL, 'Книга, необходимая для изучения умения \"Призвать Тень\". Профессия: Темный Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Summon Shadow. Used by Dark Wizards.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (1668, 'Spellbook: Summon Mew the Cat', NULL, 'Книга, необходимая для изучения умения \"Призвать Мяу\". Класс: Маги.Необходимый уровень: 20.', 'Spellbook needed to learn Summon Mew the Cat. Used by Human Wizards.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (1669, 'Spellbook: Summon Boxer the Unicorn', NULL, 'Книга, необходимая для изучения умения \"Призвать Бекара\". Профессия: Светлый Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Summon Boxer the Unicorn. Used by Elven Wizards.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (1670, 'Spellbook: Summon Mirage the Unicorn', NULL, 'Книга, необходимая для изучения умения \"Призвать Миража\". Профессия: Светлый Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Summon Mirage the Unicorn. Used by Elven Wizards.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (1671, 'Spellbook: Summon Silhouette', NULL, 'Книга, необходимая для изучения умения \"Призвать Гекату\". Профессия: Темный Маг.Необходимый уровень: 20.', 'Spellbook needed to learn Summon Silhouette. Used by Dark Wizards.', 'etc_spell_books_summon_i00', 0);
