INSERT INTO `all_items` VALUES (1829, 'Scroll of Escape: Clan Hall', NULL, 'Магический свиток, с помощью которого можно переместиться в холл клана. Если у Вас нет холла клана, Вы телепортируетесь в ближайшее поселение.', 'A scroll that relocates you to your clan hall. If you don\'t have a clan hall, it will relocate you to the nearest village.', 'etc_scroll_of_return_agit_i00', 1);
INSERT INTO `all_items` VALUES (1830, 'Scroll of Escape: Castle', NULL, 'Магический свиток, с помощью которого можно переместиться в замок. Если у Вас нет замка, Вы телепортируетесь в ближайшее поселение.', 'A scroll that relocates you to your castle. If you don\'t have a castle, it will relocate you to the nearest village.', 'etc_scroll_of_return_castle_i00', 1);
INSERT INTO `all_items` VALUES (1831, 'Antidote', NULL, 'Зелье, с помощью которого можно нейтрализовать действие яда.', 'A reagent that neutralizes poison.', 'etc_herb_green_i00', 3);
INSERT INTO `all_items` VALUES (1832, 'Greater Antidote', NULL, 'Зелье, с помощью которого можно нейтрализовать действие сильного яда.', 'A high-quality reagent that neutralizes powerful poison.', 'etc_reagent_green_i00', 3);
INSERT INTO `all_items` VALUES (1833, 'Bandage', NULL, 'Повязка, с помощью которой можно остановить кровотечение.', 'A medical bandage that stops bleeding when injured.', 'etc_piece_of_cloth_white_i00', 3);
INSERT INTO `all_items` VALUES (1834, 'Emergency Dressing', NULL, 'Повязка, с помощью которой можно остановить сильное кровотечение.', 'A medical bandage that stops bleeding fast when severely injured.', 'etc_piece_of_cloth_white_i00', 3);
INSERT INTO `all_items` VALUES (1835, 'Soulshot: No Grade', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с оружием Без Ранга.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing power of attack. Used with a No grade weapon.', 'etc_spirit_bullet_white_i00', 0);
INSERT INTO `all_items` VALUES (1836, 'Kendell\'s 1st Order', NULL, 'Приказ об убийстве Вождя Кабу Уфа. Вы можете найти его где-то в районе руин к западу от Эльфийской Деревни.', 'Punish Kaboo Chief Uoph. He should be somewhere around the ruins over the hill, west of the Elven Village.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1837, 'Kendell\'s 2nd Order', NULL, 'Приказ об убийстве Вождя Кабу Крачи. Вы можете найти его где-то рядом с обелиском к юго-западу от Эльфийской Деревни.', 'Punish Kaboo Chief Kracha. He should be somewhere around the Nine obelisk, southwest of the Elven Village.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1838, 'Kendell\'s 3rd Order', NULL, 'Приказ об убийстве Вождя Кабу Батоха. Вы можете найти его где-то рядом с входом в подземную крепость.', 'Punish Kaboo Chief Batoh. He should be somewhere around the entrance of the underground fortress of the Elves.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1839, 'Kendell\'s 4th Order', NULL, 'Приказ об убийстве Вождя Кабу Танукия. Вы можете найти его где-то рядом с руинами к юго-западу от Эльфийской Деревни.', 'Punish Kaboo Chief Tanukia. He should be somewhere around the open-air theatre ruins, southwest of the Elven Village.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (1840, 'Kendell\'s 5th Order', NULL, 'Приказ об убийстве Вождя Кабу Турела. Вы можете найти его где-то рядом с руинами к северо-западу от Радужного Озера.', 'Punish Kaboo Chief Turel. He should be somewhere around the seashore ruins, northwest of Lake Iris.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1841, 'Kendell\'s 6th Order', NULL, 'Приказ об убийстве Вождя Кабу Роко. Вы можете найти его где-то рядом с руинами к западу от Радужного Озера.', 'Punish Kaboo Chief Roko. He should be somewhere around the seashore ruins, west of Lake Iris.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1842, 'Kendell\'s 7th Order', NULL, 'Приказ об убийстве Вождя Кабу Камута. Вы можете найти его где-то рядом с руинами к югу от Радужного Озера.', 'Punish Kaboo Chief Kamut. He should be somewhere around the seashore ruins, south of Lake Iris.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1843, 'Kendell\'s 8th Order', NULL, 'Приказ об убийстве Вождя Кабу Муртики. Вы можете найти его где-то рядом с руинами к востоку от Радужного Озера.', 'Punish Kaboo Chief Murtika. He should be somewhere around the seashore ruins, east of Lake Iris.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (1844, 'Kaboo Chief\'s 1st Torque', NULL, 'Ожерелье, взятое у убитого Вождя Орков Кабу. Отдайте его Часовому Кенделлу.', 'A necklace taken by killing the chief of Kaboo orcs. Take this to Sentinel Kendell.', 'accessary_necklace_of_black_ore_i00', 0);
INSERT INTO `all_items` VALUES (1845, 'Kaboo Chief\'s 2nd Torque', NULL, 'Ожерелье, взятое у убитого Вождя Орков Кабу. Отдайте его Часовому Кенделлу.', 'A necklace taken by killing the chief of Kaboo orcs. Take this to Sentinel Kendell.', 'accessary_necklace_of_black_ore_i00', 0);
INSERT INTO `all_items` VALUES (1846, 'Turek Dog Tag', NULL, 'Знак отличия воинов Орков племени Турек. Соберите их и отдайте Пиотуру для получения награды.', 'A military identification necklace of Turek orc fighters. Collect these and take them to Piotur for a reward.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (1847, 'Turek Medallion', NULL, 'Знак отличия офицеров Орков племени Турек. Соберите их и отдайте Пиотуру для получения награды.', 'A military identification necklace of Turek orc officers. Collect these and take them to Piotur for a reward.', 'etc_totem_necklace_green_i00', 0);
