INSERT INTO `all_items` VALUES (2627, 'Mark of Challenger', NULL, 'Знак, выдаваемый тем, кто прошел Испытание храбрости. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Challenger. An item for occupational change.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (2628, 'Letter of Kash', NULL, 'Письмо Кэша. Отнесите его Мартиену в Гиран.', 'Kash\'s introduction letter. Take this letter to Martien in Giran Castle Town.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2629, 'Watcher\'s 1st Eye', NULL, 'Предмет, полученный от монстра Горра. Отнесите его Мартиену в Гиран.', 'An item obtained from the monster, Gorr. Take this to Martien in Giran Castle Town.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (2630, 'Watcher\'s 2nd Eye', NULL, 'Предмет, полученный от монстра Барахама. Покажите его Ральдо и…', 'An item obtained from the monster, Baraham. Show this to Raldo and...', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (2631, 'Scroll of Shyslassys', NULL, 'Древний свиток, полученный после убийства Шисласис. Отнесите его Кэшу в Дион.', 'An ancient scroll obtained by slaying Shyslassys. Take this to Kash in the Town of Dion.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (2632, 'Broken Key', NULL, 'Ключ, полученный после убийства Шисласис. Он нужен для открытия Сундука Шисласис.', 'A key obtained by slaying Shyslassys. This key is needed in order to open the Chest of Shyslassys.', 'etc_mold_i00', 0);
INSERT INTO `all_items` VALUES (2633, 'Mark of Duty', NULL, 'Знак, выдаваемый тем, кто прошел Испытание верности. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of Duty. An item for occupational change.', 'accessary_necklace_of_holy_spirit_i00', 0);
INSERT INTO `all_items` VALUES (2634, 'Letter of Dustin', NULL, 'Письмо Дастина. Отдайте его Великому Мастеру Ханнавальту в Гиране.', 'A letter given by Dustin. Deliver the letter to Grand Master Hannavalt in Giran Castle Town.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2635, 'Knight\'s Tear', NULL, 'Слезы, полученные от духа сэра Херода. Отнесите их сэру Арону Танфорду.', 'Obtained from the spirit of Sir Herod. Take this to Sir Aaron Tanford.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (2636, 'Mirror of Orpic', NULL, 'Предмет, необходимый для разговора с духом сэра Талиануса. Используйте его для победы над Висельным Деревом.', 'This is needed in order to speak with the ghost of Sir Talianus. Use this to defeat the hangman tree.', 'etc_mirror_i00', 0);
INSERT INTO `all_items` VALUES (2637, 'Tear of Confession', NULL, 'Слеза, полученная от духа сэра Талиануса. Отнесите ее сэру Кайлю Ночному Ястребу.', 'Obtained from the ghost of Sir Talianus. Take this to Sir Kiel Nighthawk.', 'etc_crystal_ball_white_i00', 0);
INSERT INTO `all_items` VALUES (2638, 'Report Piece', NULL, 'Предмет, который можно получить при убийстве Рабов и Вурдалаков. Соберите 10 штук и составьте их в единый отчет Талиануса.', 'You may obtain this by hunting strains and ghouls. Gather 10 pieces and put them together to create Talianus\'s report.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (2639, 'Report Piece', NULL, 'Собранный отчет. После разговора с сэром Кайлем Ночным Ястребом отнесите его сэру Талианусу.', 'The completed report. After speaking with Sir Kiel Nighthawk, deliver the report to the ghost of Sir Talianus.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2640, 'Tear of Loyalty', NULL, 'Слеза, полученная от Изаэль Серебряной Тени. Отнесите ее Жрецу Дастину.', 'This item can be obtained from Isael Silvershadow. Take it to Priest Dustin.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (2641, 'Militas Article', NULL, 'Предмет, который можно получить при убийстве Ящеров Лито. Соберите 20 штук и отнесите их Изаэль Серебряной Тени.', 'You can receive this item when you catch a Leto lizardman. Collect 20 of them and take them to Isael Silvershadow.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (2642, 'Saints Ashes Urn', NULL, 'Предмет, полученный от Жреца Дастина. Отнесите его сэру Виндавуду.', 'An object received from Priest Dustin. Deliver this to Sir Windawood.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (2643, 'Athebaldt\'s Skull', NULL, 'Предмет с тела Владыки Орков Брека. Отнесите его Жрецу Дастину вместе с Ребрами Атебальта и Голенью Атебальта.', 'You can obtain this item from a Breka orc overlord. Take it to Priest Dustin along with Athebaldt\'s ribs and Athebaldt\'s shin.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (2644, 'Athebaldt\'s Ribs', NULL, 'Предмет с тела Владыки Орков Брека. Отнесите его Жрецу Дастину вместе с Черепом Атебальта и Голенью Атебальта.', 'You can obtain this item from a Breka orc overlord. Take it to Priest Dustin along with Athebaldt\'s skull and Athebaldt\'s shin.', 'etc_rib_white_i00', 0);
INSERT INTO `all_items` VALUES (2645, 'Athebaldt\'s Shin', NULL, 'Предмет с тела Владыки Орков Брека. Отнесите его Жрецу Дастину вместе с Ребрами Атебальта и Черепом Атебальта.', 'You can obtain this item from a Breka orc overlord. Take it to Priest Dustin along with Athebaldt\'s ribs and Athebaldt\'s skull.', 'etc_piece_bone_white_i00', 0);
INSERT INTO `all_items` VALUES (2646, 'Letter of Windawood', NULL, 'Письмо от сэра Виндавуда. Покажите его Жрецу Дастину.', 'A letter received from Sir Colin Windawood. Show this to Priest Dustin.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2647, 'Dufners Letter', NULL, 'Письмо Мастера Дафнера для Мастера Терри из Диона.', 'A letter sent from Master Dufner to Master Terry in the Town of Dion.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2648, 'Terry\'s 1st Order', NULL, 'Убейте Вурдалаков Берсеркеров в Земле Казненных.', 'Investigate the neer ghoul berserkers of the Execution Grounds.', 'etc_scroll_of_resurrection_i01', 0);
INSERT INTO `all_items` VALUES (2649, 'Terry\'s 2nd Order', NULL, 'Убейте Вожаков Гноллов, Полководцев Орков Турек, Вожаков Муравьев и Воинов Людоедов Турак.', 'Investigate the ol mahum captain, Turek orc warlord, ant captain and Turak bugbear warrior.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (2650, 'Terry\'s Letter', NULL, 'Письмо Мастера Терри для Торговца Виктора из Деревни Охотников.', 'A letter sent by Master Terry to Trader Viktor of Hunters Village.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2651, 'Viktor\'s Letter', NULL, 'Письмо Торговца Виктора для Мастера Терри из Диона. На письме стоит печать Терри.', 'A letter sent by Trader Viktor to Master Terry in the Town of Dion. The letter has Terry\'s seal.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2652, 'Hawkeye\'s Letter', NULL, 'Письмо Стрелка Торговцу Виктору из Деревни Охотников.', 'A letter sent by Hawkeye to Trader Viktor of the Hunters Village.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2653, 'Mysterious Spirit Ore', NULL, 'Таинственный рунный камень, полученный после убийства Вурдалаков Берсеркеров. Отнесите его Мастеру Терри.', 'A mysterious runestone obtained after slaying neer ghoul berserkers. Take this to Master Terry.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (2654, 'Ol Mahum Spirit Ore', NULL, 'Таинственный рунный камень, полученный после убийства Вожаков Гноллов. Отнесите его Мастеру Терри.', 'A mysterious runestone obtained after slaying the ol mahum captain. Take this to Master Terry.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (2655, 'Turek Spirit Ore', NULL, 'Таинственный рунный камень, полученный после убийства Полководцев Орков Турек. Отнесите его Мастеру Терри.', 'A mysterious runestone obtained after slaying the Turek orc overlord. Take this to Master Terry.', 'etc_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (2656, 'Ant Spirit Ore', NULL, 'Таинственный рунный камень, полученный после убийства Вожака Муравьев. Отнесите его Мастеру Терри.', 'A mysterious runestone obtained after slaying the ant captain. Take this to Master Terry.', 'etc_crystal_white_i00', 0);
INSERT INTO `all_items` VALUES (2657, 'Turak Bugbear Spirit Ore', NULL, 'Таинственный рунный камень, полученный после убийства Воинов Людоедов Турак. Отнесите его Мастеру Терри.', 'A mysterious runestone obtained after slaying the Turak bugbear warrior. Take this to Master Terry.', 'etc_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (2658, 'Terry\'s Box', NULL, 'Сундук с таинственными рунными камнями. Отнесите его Торговцу Виктору в Деревню Охотников.', 'A chest containing the mysterious runestones. Take this to Trader Viktor of the Hunters Village.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (2659, 'Viktor\'s Request', NULL, 'Запрос от Торговца Виктора на сбор 10 Чешуек Медузы.', 'A request issued by Trader Viktor. \"Please gather 10 medusa scales.\"', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (2660, 'Medusa Scales', NULL, 'Чешуя Медузы. Соберите 10 штук и отнесите их Торговцу Виктору.', 'The scales of the medusa. Gather 10 of these and take them to Trader Viktor.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (2661, 'Shilen\'s Spirit Ore', NULL, 'Странные рунные камни, полученные с тел мутантов. Возможна связь камней с Шилен, богиней смерти.', 'Strange runestones obtained from the bodies of mutant species. They seem to be related to Shilen, the goddess of death.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (2662, 'Analysis Request', NULL, 'Запрос Торговца Виктора, направленный Магистру Марине в Башню Слоновой Кости на исследование Темного Безоара.', 'A request letter sent to Magister Marina of the Ivory Tower from Trader Viktor. The letter asks Marina to analyze the dark bezoar.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (2663, 'Marina\'s Letter', NULL, 'Письмо Магистра Марины Кузнецу Брюнону в Деревню Гномов.', 'A letter sent by Magister Marina to Blacksmith Brunon of the Dwarven Village.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2664, 'Experiment Tools', NULL, 'Инструменты для опытов, сделанные Кузнецом Брюноном. Отнесите их Магистру Марине в Башню Слоновой Кости.', 'Experimental tools crafted by Blacksmith Brunon. Deliver these to Magister Marina of the Ivory Tower.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (2665, 'Analysis Result', NULL, 'Документ с результатами анализа Темного Безоара. Отнесите его Мастеру Терри в Дион.', 'A document where Magister Marina has organized the analyzed results of the Dark Bezoar. Deliver this to Master Terry in the Town of Dion.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (2666, 'Terry\'s 3rd Order', NULL, 'Приказ Мастера Терри прийти за следующим заданием после получения 36-го уровня.', 'Master Terry\'s orders. The orders give instructions to come back for the next task after reaching level 36.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (2667, 'List of Host', NULL, 'Список существ, из которых можно добыть Безоары: Трутень Болотных Стакато, Владыка Орков Брека, Вожак Муравьев Воинов, Воин Ящеров Лито.', 'A list of the bezoar hosts.\"Marsh stakato drone, Breka orc overlord, ant warrior captain, Leto lizardman warrior\"', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (2668, 'Abyss Spirit Ore', NULL, 'Темный безоар с тела Трутня Болотных Стакато. Отнесите его Мастеру Терри.', 'The dark bezoar retrieved from the body of a marsh stakato drone. Take this to Master Terry.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (2669, 'Abyss Spirit Ore', NULL, 'Темный безоар с тела Владыки Орков Брека. Отнесите его Мастеру Терри.', 'The runestone retrieved from the body of the Breka orc overlord. Take this to Master Terry.', 'etc_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (2670, 'Abyss Spirit Ore', NULL, 'Темный безоар с тела Вожака Муравьев Воинов. Отнесите его Мастеру Терри.', 'The runestone retrieved from the body of the ant captain. Take this to Master Terry.', 'etc_crystal_white_i00', 0);
INSERT INTO `all_items` VALUES (2671, 'Abyss Spirit Ore', NULL, 'Темный безоар с тела Воина Ящеров Лито. Отнесите его Мастеру Терри.', 'The runestone retrieved from the body of the Leto lizardman warrior. Take this to Master Terry.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (2672, 'Terry\'s Report', NULL, 'Подробный отчет о происшествии с рунными камнями. Отнесите его Мастеру Дафнеру в Гиран.', 'A report detailing information about the runestone incident. Take this to Master Dufner of Giran Castle Town.', 'etc_scroll_of_enchant_weapon_i00', 0);
INSERT INTO `all_items` VALUES (2673, 'Mark of Seeker', NULL, 'Знак, выдаваемый прошедшим Испытание искателя. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Seeker. An occupation change related item.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (2674, 'Mark of Scholar', NULL, 'Знак, выдаваемый прошедшим Испытание мудрости. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Scholar. An occupation change related item.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (2675, 'Mirien\'s 1st Sigil', NULL, 'Знак, выданный Магистром Мириен для выполнения просьбы Верховного Жреца Сильвиана.', 'A mark given by Magister Mirien while giving orders to complete High Priest Sylvain\'s request.', 'shield_shield_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (2676, 'Mirien\'s 2nd Sigil', NULL, 'Знак, выданный Магистром Мириен для выполнения просьбы Великого Магистра Юрека.', 'A mark given by Magister Mirien while giving orders to complete Grand Magister Jurek\'s request.', 'shield_shield_of_pledge_i00', 0);
INSERT INTO `all_items` VALUES (2677, 'Mirien\'s 3rd Sigil', NULL, 'Знак, выданный Магистром Мириен для выполнения просьбы Старейшины Кроноса.', 'A mark given by Magister Mirien when giving orders to complete Elder Cronos\'s request.', 'shield_round_shield_i00', 0);
INSERT INTO `all_items` VALUES (2678, 'Mirien\'s Instruction', NULL, 'Записка Магистра Мириен о том, что необходимо снова прийти к ней по достижении 36-го уровня.', 'A note that contains Magister Mirien\'s instructions. The note gives instructions to come back for the next task after reaching level 36.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2679, 'Maria\'s 1st Letter', NULL, 'Письмо Марии Капитану Лукасу из Диона.', 'A letter sent by Maria to Captain Lucas in the Town of Dion.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2680, 'Maria\'s 2nd Letter', NULL, 'Письмо Марии Ворожее Крете из Флорана.', 'A letter sent by Maria to Astrologer Creta of the village of Floran.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2681, 'Lucas\'s Letter', NULL, 'Письмо Капитана Лукаса из Диона, адресованное Марии.', 'A letter sent by Captain Lucas in the Town of Dion to Maria.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2682, 'Lucilla\'s Handbag', NULL, 'Сумочка подруги Марии, Люсиллы, потерянная в ночь похищения. Отнесите ее Ворожее Крете.', 'The handbag left by Maria\'s friend Lucillas on the night of the theft. Take this to Astrologer Creta.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2683, 'Creta\'s 1st Letter', NULL, 'Письмо Ворожеи Креты Марии из Диона.', 'A letter sent by the Astrologer Creta to Maria in the Town of Dion.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2684, 'Creta\'s Painting1', NULL, 'Рисунок Ворожеи Креты, на котором видно что-то похожее на тень похитителя. Отнесите его Марии.', 'A painting by Astrologer Creta. It contains a shadow presumed to be that of the thief. Take this to Maria.', 'etc_scroll_of_enchant_armor_i00', 0);
INSERT INTO `all_items` VALUES (2685, 'Creta\'s Painting2', NULL, 'Рисунок Ворожеи Креты, на котором видно что-то похожее на тень похитителя. Отнесите его Капитану Лукасу.', 'A painting by Astrologer Creta. It contains a shadow presumed to be that of the thief. Take this to Captain Lucas.', 'etc_scroll_of_resurrection_i00', 0);
INSERT INTO `all_items` VALUES (2686, 'Creta\'s Painting3', NULL, 'Рисунок Ворожеи Креты, на котором видно, что тень похитителя похожа на Воина Ящеров Лито.', 'A painting painted by Astrologer Creta. The shadow in the painting is that of a Leto lizardman warrior.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (2687, 'Brown Scroll Scrap', NULL, 'Обрывок свитка, в котором описывается процесс создания Кристалла Очищения. Соберите 5 штук и отнесите их Марии.', 'A scrap of a scroll that contains directions on how to create the crystal of purity. Gather 5 of these and take them to Maria.', 'etc_map_piece_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2688, 'Crystal of Purity', NULL, 'Кристалл, служащий для очищения земли. Отнесите его Верховному Жрецу Сильвиану.', 'A crystal used to purify the earth. Take this to High Priest Sylvain in the Town of Dion.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (2689, 'High Priest\'s Sigil', NULL, 'Знак, полученный от Верховного Жреца Сильвиана. Доказательство того, что владелец исполняет волю Верховного Жреца.', 'A mark received from High Priest Sylvain. A proof given to those who are carrying out the orders of the High Priest.', 'shield_sages_shield_i01', 0);
INSERT INTO `all_items` VALUES (2690, 'Grand Magister\'s Sigil', NULL, 'Знак, полученный от Великого Магистра Юрека. Доказательство того, что владелец исполняет волю Великого Магистра.', 'A mark received from Grand Magister Jurek. A proof given to those who are carrying out the orders of the Grand Magister.', 'shield_doom_shield_i00', 0);
INSERT INTO `all_items` VALUES (2691, 'Crono\'s Sigil', NULL, 'Знак, полученный от Старейшины Кроноса. Доказательство того, что владелец исполняет волю Старейшины.', 'A mark received from Elder Cronos. This signifies proof that someone is carrying out orders from Elder Cronos.', 'shield_another_worlds_shield_i01', 0);
INSERT INTO `all_items` VALUES (2692, 'Sylvain\'s Letter', NULL, 'Письмо Верховного Жреца Сильвиана. Отнесите его Марии в Дион.', 'High Priest Sylvain\'s letter. Take this to Maria in the Town of Dion.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (2693, 'Symbol of Sylvain', NULL, 'Символ прохождения испытания Верховного Жреца Сильвиана. Отнесите его Магистру Мириен в Дион.', 'A symbol given to those who have passed High Priest Sylvain\'s test. Take this to Magister Mirien in the Town of Dion.', 'etc_coins_blue_i00', 0);
INSERT INTO `all_items` VALUES (2694, 'Jurek\'s List', NULL, 'Список существ, которых просит проверить Великий Магистр Юрек: Монстроглаз Разрушитель, Шаман Орков Брека, Каторжник.', 'The list of evil creatures that Grand Magister Jurek asked you to investigate: Monster eye destroyer, Breka orc shaman, and shackle.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (2695, 'Monster Eye Destroyer\'s Skin', NULL, 'Кожа монстроглаза. Соберите 5 таких и отнесите их Великому Магистру Юреку в Гиран.', 'A beamer\'s skin. Gather 5 of these and take them to Grand Magister Jurek of Giran Castle Town.', 'etc_leather_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2696, 'Shaman\'s Necklace', NULL, 'Ожерелье Шамана Орков Брека. Соберите 5 таких и отнесите их Великому Магистру Юреку в Гиран.', 'A Breka orc shaman\'s necklace. Gather 5 of these and take them to Grand Magister Jurek in Giran Castle Town.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (2697, 'Shackle\'s Scalp', NULL, 'Скальп с головы Каторжника. Соберите 2 таких и отнесите их Великому Магистру Юреку в Гиран.', 'Skin of the shackle\'s head. Gather 2 of these and take them to Grand Magister Jurek of Giran Castle Town.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (2698, 'Symbol of Jurek', NULL, 'Символ прохождения испытания Великого Магистра Юрека. Отнесите его Магистру Мириен в Дион.', 'A symbol given to those who have passed Grand Magister Jurek\'s test. Take this to Magister Mirien in the Town of Dion.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (2699, 'Cronos Letter', NULL, 'Письмо Старейшины Кроноса Магистру Дитеру в Гиран.', 'A letter sent by Elder Cronos to Magister Dieter in the Town of Giran.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2700, 'Dieter\'s Key', NULL, 'Ключ от сундука, в котором Дитер спрятал Рукопись Знаний. Отнесите его Ворожее Крете в Флоран.', 'A key to the chest where Dieter has hidden the Scriptures of Knowledge. Take this to Astrologer Creta in Floran Village.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (2701, 'Creta\'s 2nd Letter', NULL, 'Письмо Креты с описанием кражи Рукописи Знаний. Отнесите его Магистру Дитеру в Гиран.', 'Creta\'s letter describing the theft of the Scriptures of Knowledge. Take this to Magister Dieter in the Town of Giran.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2702, 'Dieter\'s Letter', NULL, 'Письмо Магистра Дитера Торговцу Эдроку из оружейной лавки Деревни Охотников.', 'A letter from Magister Dieter to Trader Edroc of the weapons shop of Hunters Village.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2703, 'Dieter\'s Diary', NULL, 'Дневник Магистра Дитера. Возможно, в нем есть полезная информация для поиска похитителей Рукописи Знаний.', 'Magister Dieter\'s Diary, given by him in hopes that it may be of aid in recovering the Scriptures of Knowledge.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (2704, 'Raut\'s Letter Envelope', NULL, 'Пустой конверт, адресованный Смотрителю Склада Рауту.', 'A plain letter envelope with no contents. The envelope is addressed \"To Warehouse Keeper Raut\".', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (2705, 'Triff\'s Ring', NULL, 'Кольцо пьяницы Трифа. Покажите его тому, кому Триф отдал части Рукописи Знаний.', 'A ring given by Drunkard Triff. Show this ring to those whom Triff has entrusted with the Scriptures of Knowledge.', 'accessary_aquastone_ring_i00', 0);
INSERT INTO `all_items` VALUES (2706, 'Scripture Chapter 1', NULL, 'Первая часть Рукописи Знаний. Соберите все четыре части.', 'The 1st book of the Scriptures of Knowledge. Gather all 4 books.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (2707, 'Scripture Chapter 2', NULL, 'Вторая часть Рукописи Знаний. Соберите все четыре части.', 'The 2nd book of the Scriptures of Knowledge. Gather all 4 books.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (2708, 'Scripture Chapter 3', NULL, 'Третья часть Рукописи Знаний. Соберите все четыре части.', 'The 3rd book of the Scriptures of Knowledge. Gather all 4 books.', 'weapon_apprentices_spellbook_i00', 0);
INSERT INTO `all_items` VALUES (2709, 'Scripture Chapter 4', NULL, 'Четвертая часть Рукописи Знаний. Соберите все четыре части.', 'The 4th book of the Scriptures of Knowledge. Gather all 4 books.', 'weapon_apprentices_spellbook_i01', 0);
INSERT INTO `all_items` VALUES (2710, 'Valkon\'s Request', NULL, 'Запрос Смотрителя Склада Валькона. В нем содержится просьба принести Кристалл Очищения.', 'Warehouse Keeper Valkon\'s request. The instructions are to bring back the crystal of purity.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2711, 'Poitan\'s Notes', NULL, 'Бухгалтерские записи Кузнеца Пойтана. Отнесите их Старейшине Казиану в Пустошь.', 'Blacksmith Poitan\'s accounting books. Take this to Elder Casian of the Wastelands.', 'weapon_apprentices_spellbook_i01', 0);
INSERT INTO `all_items` VALUES (2712, 'Scriptures of Knowledge', NULL, 'Рукопись Старейшины Кроноса. Говорят, в ней содержатся ценные знания.', 'A scripture edited by Elder Cronos. It is said to contain a vast knowledge of the past. It is part of a 4-scripture set.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (2713, 'Strong Liquor', NULL, 'Содержимое соответствует этикетке - крепкий ликер. Отдайте его пьянице Трифу в порту.', 'As its name indicates, a strong liquor. Take this to Drunkard Triff at the harbor.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (2714, 'Crystal of Purity', NULL, 'Предмет, который Смотритель Склада Валькон согласился обменять на вторую часть Рукописи.', 'An item that Warehouse Keeper Valkon in Giran Castle Town agreed to trade with you for scripture chapter 2.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (2715, 'Casian\'s List', NULL, '10 кусков Кожи Вурдалаков, 12 порций Крови Медузы, 5 порций Ихора Пленной Души и 5 Ногтей Зачарованной Горгульи.', '10 ghoul\'s skins, 12 units of medusa\'s blood, 5 units of fettered soul\'s ichor, and 5 enchanted gargoyle\'s nails.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2716, 'Ghoul\'s Skin', NULL, 'Кожа, полученная при убийстве Вурдалака. Соберите 10 кусков и отнесите их Старейшине Казиану.', 'The skin of a ghoul. Gather 10 of these and take them to Elder Casian.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (2717, 'Medusa\'s Blood', NULL, 'Кровь, полученная при убийстве Медузы. Соберите 12 порций и отнесите их Старейшине Казиану.', 'Medusa\'s Blood. Gather 12 bottles and take them to Elder Casian.', 'etc_lesser_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (2718, 'Fettered Soul\'s Ichor', NULL, 'Ихор, полученная при убийстве Пленной Души. Соберите 5 порций и отнесите их Старейшине Казиану.', 'The ichor of a fettered soul. Gather 5 units and take them to Elder Casian.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (2719, 'Enchanted Gargoyle\'s Nail', NULL, 'Коготь, полученная при убийстве Горгульи. Соберите 5 штук и отнесите их Старейшине Казиану.', 'The enchanted nails of a gargoyle. Gather 5 of these and take them to Elder Casian.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (2720, 'Symbol of Cronos', NULL, 'Знак Кроноса, самого сильного мага на континенте. Отнесите его Магистру Мириен в Дион.', 'The mark of Cronos, the top sage of the continent. Take this to Magister Mirien in the Town of Dion.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (2721, 'Mark of Pilgrim', NULL, 'Знак, выдаваемый прошедшим Испытание упорства. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Pilgrim. An occupation change related item.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (2722, 'Book of Sage', NULL, 'Книга, полученная от Старейшины Казиана. Отнесите ее Отшельнику Сантьяго.', 'A book received from Elder Casian. Take this book to Hermit Santiago.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (2723, 'Voucher of Trial', NULL, 'Знак Отшельника Сантьяго. Покажите его Провидцу Танапи в Деревне Орков.', 'A mark given by Hermit Santiago. Show this to Seer Tanapi of the Orc Village.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (2724, 'Spirit of Flame', NULL, 'Доказательство познания Духа Огня. Для получения следующего задания отнесите его Гаури Мерцающей Скале в Деревню Гномов.', 'Proof that you have an understanding of the spirit of flame. In order to carry out the next stage of this trial, go see Gauri Twinklerock of Dwarven Village.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (2725, 'Essence of Flame', NULL, 'Драгоценный камень, полученный от Лавовой Саламандры. Отнесите его Прародителю Мартанкусу.', 'A jewel obtained from the lava salamander. Take this to the Ancestor Martankus.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (2726, 'Book of Gerald', NULL, 'Книга Жреца Геральда. На вид очень дешевая.', 'A book given by Priest Gerald. The book looks very cheap.', 'weapon_apprentices_spellbook_i00', 0);
INSERT INTO `all_items` VALUES (2727, 'Gray Badge', NULL, 'Эмблема Скитальца Дорфа. Отнесите ее Жрецу Примосу в Гиран.', 'A badge given by Wanderer Dorf. Take this to Priest Primos at Giran Castle Town.', 'etc_badge_black_i00', 0);
INSERT INTO `all_items` VALUES (2728, 'Picture of Nahir', NULL, 'Рисунок, изображающий монстра Нахира, обитающего в глубинах Эльфийских Руин Говорящего Острова. Найдите его и убейте.', 'A picture of the monster, Nahir. Defeat Nahir, who lurks in the depths of the Elven Ruins on Talking Island.', 'etc_plate_black_i00', 0);
INSERT INTO `all_items` VALUES (2729, 'Hair of Nahir', NULL, 'Волосы Нахира. Отнесите их Жрецу Петрону.', 'The hair of the monster, Nahir. Take this to Priest Petron.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (2730, 'Statue of Einhasad', NULL, 'Статуя Эйнхасад, отданная Вам Жрецом Петроном. Отнесите ее Анделии, живущей недалеко от Древа Жизни в Деревне Эльфов.', 'A statue of Einhasad given by Priest Petron. Take this to Andellia, who lives near the Mother Tree Glade in the Elven Village.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (2731, 'Book of Darkness', NULL, 'Книга Урухи, написанная кровью.', 'A book given by Uruha. The book contains unrecognizable letters written in blood.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (2732, 'Debris of Willow', NULL, 'Обломки черной ивы. Возьмите их с собой на поиски Урухи.', 'Debris obtained from the black willow. Go and seek Uruha while in possession of this.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (2733, 'Tag of Rumor', NULL, 'Содержит слухи о Скитальце Дорфе и Жреце Геральде.', 'This contains rumors regarding Wanderer Dorf and Priest Gerald.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (2734, 'Mark of Trust', NULL, 'Знак, выдаваемый прошедшим Испытание доверия. Предмет для смены профессии.', 'A mark given to those who have passed the Testimony of Trust. An occupation change related item.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (2735, 'Letter to Elf', NULL, 'Письмо к Эльфам с просьбой о доверии. Доставьте его Иерарху Астериосу в Деревню Эльфов.', 'A letter requesting the trust of the Elves. Deliver this to Hierarch Asterios of the Elven Village.', 'etc_scroll_of_enchant_armor_i00', 0);
INSERT INTO `all_items` VALUES (2736, 'Letter to Dark Elf', NULL, 'Письмо к Темным Эльфам с просьбой о доверии. Доставьте его Тетрарху Тифиэлю в Деревню Темных Эльфов.', 'A letter requesting the trust of the Dark Elves. Deliver this to Tetrarch Thifiell of the Dark Elf Village.', 'etc_scroll_of_enchant_weapon_i00', 0);
INSERT INTO `all_items` VALUES (2737, 'Letter to Dwarf', NULL, 'Письмо к Гномам с просьбой о доверии. Доставьте его Локрину в Деревню Гномов.', 'A letter requesting the trust of the Dwarves. Deliver this to Lockirin of the Dwarven Village.', 'etc_scroll_of_resurrection_i00', 0);
INSERT INTO `all_items` VALUES (2738, 'Letter to Orc', NULL, 'Письмо к Оркам с просьбой о доверии. Доставьте его Лорду Кекеи в Деревню Орков.', 'A letter requesting the trust of the Orcs. Deliver this to the Pa\'agrio Lord Kakai at the Orc Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (2739, 'Letter to Seresin', NULL, 'Письмо Верховного Жреца Холлинта. Доставьте его Кардиналу Сересин в Орен.', 'A letter given by High Priest Hollint. Deliver this to Cardinal Seresin at the Town of Oren.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2740, 'Scroll of Dark Elf Trust', NULL, 'Свиток Тетрарха Тифиэля. Доставьте его вместе с Письмом Эльфов Верховному Жрецу Холлинту.', 'A scroll given by Tetrarch Thifiell. Deliver this, along with the scroll of the Elf trust, to High Priest Hollint.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (2741, 'Scroll of Elf Trust', NULL, 'Свиток Иерарха Астериоса. Доставьте его и Письмо Темных Эльфов Верховному Жрецу Холлинту.', 'This item can be obtained from Hierarch Asterios. Give this item along with scroll of Dark Elf trust to High Priest Hollint.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (2742, 'Scroll of Dwarf Trust', NULL, 'Свиток Локрина из Гильдии Железных Врат. Доставьте его и Письмо Орков Кардиналу Сересин.', 'A scroll given by Lockrin of the Iron Gate. Deliver this, along with the scroll of Orc trust, to Cardinal Seresin.', 'etc_scroll_of_resurrection_i01', 0);
INSERT INTO `all_items` VALUES (2743, 'Scroll of Orc Trust', NULL, 'Свиток Кекеи, Лорда Пламени. Доставьте его и Письмо Гномов Кардиналу Сересин.', 'A scroll given by Kakai, Lord of Flame. Deliver this, along with the scroll of Dwarf trust, to Cardinal Seresin.', 'etc_scroll_of_return_i01', 0);
INSERT INTO `all_items` VALUES (2744, 'Recommendation of Hollint', NULL, 'Письмо для Верховного Жреца Биотина, который находится в Храме Эйнхасад на Говорящем Острове.', 'Deliver this to High Priest Biotin at the Temple of Einhasad on Talking Island.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2745, 'Order of Asterios', NULL, 'Приказ убить Луэль Западных Ветров и Актею Зеленых Лесов и принести доказательство их смерти.', 'Slay Luell of Zephyr Winds and Actea of Verdant Wilds and bring back proof of their deaths.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2746, 'Breath of Winds', NULL, 'Предмет, полученный с тела Луэли Западных Ветров. Отнесите его и Семя Зелени Иерарху Астериосу.', 'Obtained from Luell of Zephyr Winds. Deliver this, along with the seed of verdure to Hierarch Asterios.', 'etc_potion_green_i00', 0);
INSERT INTO `all_items` VALUES (2747, 'Seed of Verdure', NULL, 'Предмет, полученный с тела Актеи Зеленых Лесов. Отнесите его и Дыхание Ветров Иерарху Астериосу.', 'A proof obtained from Actea of Verdant Wilds. Deliver this, along with the breath of winds, to Hierarch Asterios.', 'etc_broken_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (2748, 'Letter from Thifiell', NULL, 'Письмо, предназначенное для Магистра Клейтона, члена Гильдии Темных Эльфов в Дионе.', 'Deliver this to Magister Clayton, member of the Dark Elf Guild, in the Town of Dion.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2749, 'Guardian Basilisk Blood', NULL, 'Кровь, добытая у Василиска Стражника. Соберите 5 бутылочек, чтобы получить Плазму Василиска.', 'This item can be obtained from a guardian basilisk. Collect 10 of them and create basilisk Plasma.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (2750, 'Giant Aphid', NULL, 'Предмет, полученный при убийстве Муравьев Солдат. Соберите 5 штук, чтобы получить Медовую Росу.', 'This may be obtained from various soldier ants. Gather 10 to create the honey dew.', 'etc_reagent_green_i00', 0);
INSERT INTO `all_items` VALUES (2751, 'Stakatos Fluids', NULL, 'Жидкость, полученная с различных Болотных Стакато. Соберите 5 штук, чтобы получить Сукровицу Стакато.', 'This may be obtained from various marsh stakatos. Gather 10 to create stakato ichor.', 'etc_reagent_blue_i00', 0);
INSERT INTO `all_items` VALUES (2752, 'Basilisk Plasma', NULL, 'Жидкость, которую необходимо отнести Магистру Клейтону вместе с Медовой Росой и Сукровицей Стакато.', 'Take this, along with the honey dew and stakato ichor, to Magister Clayton.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (2753, 'Honey Dew', NULL, 'Жидкость, которую необходимо отнести Магистру Клейтону вместе с Плазмой Василиска и Сукровицей Стакато.', 'Take this, along with the basilisk plasma and stakato ichor, to Magister Clayton.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (2754, 'Stakato Ichor', NULL, 'Жидкость, которую необходимо отнести Магистру Клейтону вместе с Плазмой Василиска и Медовой Росой.', 'Take this, along with the honey dew and basilisk plasma, to Magister Clayton.', 'etc_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (2755, 'Order of Clayton', NULL, 'Получите Плазму Василиска с Василиска Стражника, Сукровицу Стакато с Болотных Стакато и Медовую Росу с Муравьев Солдат и принесите все Магистру Клейтону.', 'Obtain basilisk plasma of a guardian basilisk, stakato ichor of a marsh stakato and honey dew of an ant guard and take them to Magister Clayton.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2756, 'Parasite of Lota', NULL, 'Предмет, который можно получить при убийстве Вепрей. Соберите 10 таких и отнесите их Провидцу Манакии.', 'This may be obtained from the windsus. Gather 10 of these and take them to Seer Manakia.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (2757, 'Letter to Manakia', NULL, 'Письмо Лорда Кекеи. Доставьте его Провидцу Манакии в Гиран.', 'A letter received from Pa\'agrio Lord Kakai. Deliver this to Seer Manakia in the Town of Giran.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (2758, 'Letter of Manakia', NULL, 'Письмо Провидца Манакии. Доставьте его Лорду Кекеи.', 'A letter received from Seer Manakia. Deliver this to Pa\'agrio Lord Kakai.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (2759, 'Letter to Nikola', NULL, 'Письмо от Локрина из Гильдии Железных Врат. Доставьте его Мастеру Николя к Башне Крумы.', 'A letter received from Lockrin of the Iron Gate. Deliver this to Maestro Nikola of the Cruma Tower.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2760, 'Order of Nikola', NULL, 'Найдите Осколок Сердца Порты и отнесите его Мастеру Николя.', 'Obtain 10 porta heartstones and take them to Maestro Nikola.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2761, 'Heartstone of Porta', NULL, 'Осколок каменного сердца Порты. Отнесите его Мастеру Николя.', 'This may be obtained from a porta. Gather 10 of these and take them to Maestro Nikola.', 'etc_poison_pouch_i00', 0);
INSERT INTO `all_items` VALUES (2762, 'Mark of Duelist', NULL, 'Знак, выдаваемый прошедшим Испытание силы. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Duelist. An item for occupational change.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (2763, 'Order Gludio', NULL, 'Убейте не менее 10 Громил и 10 Вожаков Элитных Муравьев, обитающих на землях Глудио.', 'Kill at least 10 punchers and 10 noble ant leaders in Gludio.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (2764, 'Order Dion', NULL, 'Убейте не менее 10 Трутней Болотных Стакато и 10 Поедателей Мертвечины, обитающих на землях Диона.', 'Kill at least 10 marsh stakato drones and 10 dead seekers in Dion.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (2765, 'Order Giran', NULL, 'Убейте не менее 10 Владык Орков Брека и 10 Пленных Душ, обитающих на землях Гирана.', 'Kill at least 10 Breka orc overlords and 10 fettered souls in Giran.', 'etc_scroll_of_resurrection_i01', 0);
INSERT INTO `all_items` VALUES (2766, 'Order Oren', NULL, 'Убейте не менее 10 Владык Ящеров Лито и 10 Зачарованных Монстроглазов, обитающих на землях Орена.', 'Kill at least 10 Leto lizardman overlords and 10 enchanted monster eyes in Oren.', 'etc_scroll_of_return_i01', 0);
INSERT INTO `all_items` VALUES (2767, 'Order Aden', NULL, 'Убейте не менее 10 Орков Тамлин и 10 Стрелков Орков Тамлин, обитающих в окрестностях Деревни Охотников.', 'Kill at least 10 Tamlin orcs and 10 Tamlin orc archers in Aden.', 'etc_scroll_of_enchant_armor_i00', 0);
INSERT INTO `all_items` VALUES (2768, 'Puncher\'s Shard', NULL, 'Часть Громилы. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'A shard of the broken puncher. Collect 10 of these to take to Duelist Kaien.', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (2769, 'Noble Ant\'s Feeler', NULL, 'Усики Элитного Муравья. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The feelers of the noble ant leader. Collect 10 of these to take to Duelist Kaien.', 'etc_insect_leg_i00', 0);
INSERT INTO `all_items` VALUES (2770, 'Drone\'s Chitin', NULL, 'Хитин Трутня Болотных Стакато. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The chitin of the marsh stakato drone. Collect 10 of these to take to Duelist Kaien.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (2771, 'Dead Seeker Fang', NULL, 'Клык Поедателя Мертвечины. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The fangs of the dead seeker bat. Collect 10 of these to take to Duelist Kaien.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (2772, 'Overlord Necklace', NULL, 'Ожерелье Владыки Орков Брека. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'Collect ten Breka orc overlord\'s necklaces and take them to Duelist Kaien.', 'accessary_necklace_of_anguish_i00', 0);
INSERT INTO `all_items` VALUES (2773, 'Fettered Soul\'s Chain', NULL, 'Цепь, висящая на шее у Пленных Душ. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The chains that surround a fettered soul\'s body. Collect 10 of these to take to Duelist Kaien.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (2774, 'Chief\'s Amulet', NULL, 'Амулет Владыки Ящеров Лито. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The amulet of a Leto lizardman overlord. Collect 10 of these to take to Duelist Kaien.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (2775, 'Enchanted Monster Eye Meat', NULL, 'Мясо Зачарованного Монстроглаза. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The flesh of an enchanted eye. Collect 10 of these to take to Duelist Kaien.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (2776, 'Tamlin Orc\'s Ring', NULL, 'Кольцо Орка Тамлин. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The ring of a Tamrin orc. Collect 10 of these to take to Duelist Kaien.', 'accessary_cerberuss_ring_i00', 0);
INSERT INTO `all_items` VALUES (2777, 'Tamlin Orc\'s Arrow', NULL, 'Стрела Орков Тамлин. Соберите 10 таких и отнесите их Дуэлисту Каену.', 'The arrows of a Tamrin orc archer. Collect 10 of these to take to Duelist Kaien.', 'weapon_wooden_arrow_i01', 0);
INSERT INTO `all_items` VALUES (2778, 'Final Order', NULL, 'Победите 3 раза Экскуро и Кратора в Башне Крумы, Грандиса под Гираном, Владыку Орков Тимак под Ореном и Лакина под Аденом.', 'Defeat the Excuro and Krator of the Cruma Tower, the Grandis of Giran, the Timak Orc Overlord of Oren, and the Lakin of Aden 3 times.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2779, 'Excuro\'s Skin', NULL, 'Кожа Экскуро. Соберите 3 таких и отнесите их Дуэлисту Каену.', 'The skin of the excuro. Collect 3 of these to take to Duelist Kaien.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (2780, 'Krator\'s Shard', NULL, 'Осколок Кратора. Соберите 3 таких и отнесите их Дуэлисту Каену.', 'The shard of a broken krator. Collect 3 of these to take to Duelist Kaien.', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (2781, 'Grandis\' Skin', NULL, 'Кожа Грандиса. Соберите 3 таких и отнесите их Дуэлисту Каену.', 'The skin of a grandis. Collect 3 of these to take to Duelist Kaien.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (2782, 'Timak Orc\'s Belt', NULL, 'Пояс Владыки Орков Тимак. Соберите 3 таких и отнесите их Дуэлисту Каену.', 'The belt of a Timak orc overlord. Collect 3 of these to take to Duelist Kaien.', 'etc_piece_of_cloth_black_i00', 0);
INSERT INTO `all_items` VALUES (2783, 'Lakin\'s Mace', NULL, 'Булава Лакина. Соберите 3 таких и отнесите их Дуэлисту Каену.', 'Mace used by a lakin. Collect 3 of these to take to Duelist Kaien.', 'weapon_spike_club_i00', 0);
INSERT INTO `all_items` VALUES (2784, 'Luther\'s Letter', NULL, 'Письмо Мастера Лютера. Отнесите его Алексу в Флоран.', 'A letter given by Master Luther. Take this to Alex of the village of Floran.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2785, 'Alex\'s Warrant', NULL, 'Приказ, выданный Алексом. Отнесите его Лейрин.', 'A warrant written by Alex. Take this to Leirynn.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2786, 'Leirynn\'s 1st Order', NULL, 'Приказ Лейрин о том, что необходимо убить 10 Шаманов Ящеров Делу и принести их тотемы.', 'A list of orders given by Leirynn. \"Slay 10 Delu Shamans and bring back their tokens.\"', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (2787, 'Delu Totem', NULL, 'Тотем Шамана Делу. Соберите 10 таких и отнесите их Лейрин.', 'The totem of Shaman Saska. Take this, along with the rest of the Delu Shaman totems, to Leirynn.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (2788, 'Leirynn\'s 2nd Order', NULL, 'Приказ Лейрин о том, что необходимо убить Главу Ящеров Делу Калкиса и принести доказательство его смерти.', 'A list of orders given by Leirynn. Slay Delu chief Kalkis and bring back proof.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (2789, 'Chief Kalki\'s Fang', NULL, 'Доказательство гибели Калкиса. Отнесите его Лейрин.', 'Proof that the Delu chief Kalkis has been slain. Take this to Leirynn.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (2790, 'Leirynn\'s Report', NULL, 'Отчет Лейрин. Отнесите его Алексу.', 'A report issued by Leirynn. Take this to Alex.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2791, 'Strange Map', NULL, 'Странная карта, добытая у Главы Делу Калкиса.', 'A strange map obtained from the Delu chief Kalkis.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2792, 'Lambert\'s Map', NULL, 'Карта, на которой написано имя Ламберта, бывшего стража повелителя.', 'A map where the name of Lambert, the former lord\'s guard, is written.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2793, 'Alex\'s Letter', NULL, 'Письмо Алекса. Отнесите его пьянице Борису в Глудио.', 'A letter given by Alex. Take this and go to drunkard Borys at the Town of Gludio.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2794, 'Alex\'s Order', NULL, 'Приказ Алекса найти и забрать пропавшее золото герцога Эштона.', 'Alex\'s orders. The orders give instructions to find and recover Duke Ashton\'s missing gold.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2795, 'Wine Catalog', NULL, 'Список лучших вин Гирана, опубликованный Гильдией Торговцев. Отнесите его Торговцу Тире.', 'A list of premium wine published by the Giran Traders\' Guild. Show this to Trader Tyra.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (2796, 'Tyra\'s Contract', NULL, 'Контракт, написанный Торговцем Тирой. В нем сказано, что Тира отдаст Малрукианское Вино за 10 щепоток Красной Пыли.', 'The contract that Trader Tyra has drawn up. The contract states that Tyra will trade 10 pouches of red spore dust for a Malrukian wine.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2797, 'Red Spore Dust', NULL, 'Красная пыль, полученная после убийства Гигантского Гриба. Соберите 10 штук и отнесите Торговцу Тире.', 'Red spore dust obtained by slaying the giant fungus. Gather 10 pouches and bring them to Trader Tyra.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (2798, 'Malrukian Wine', NULL, 'Отличное вино, сделанное по рецептам племени Малрук. Отнесите его пьянице Борису.', 'Premium wine crafted following the methods of the Malruk tribe. Take this to drunkard Borys.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (2799, 'Old Order', NULL, 'Старый приказ, взятый у пьяницы Бориса. Отнесите его Телохранителю Джаксу.', 'An old order received from drunkard Borys. Take this and go to bodyguard Jax.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (2800, 'Jax\'s Diary', NULL, 'Дневник Телохранителя Джакса. По словам Джакса, он может помочь в поиске карт Солта и Макела.', 'A diary that bodyguard Jax has given, saying that it will aid in the search for Solt\'s and Makel\'s maps.', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (2801, '1st Torn Map Piece', NULL, 'Часть карты, принадлежавшей бывшему стражу лорда Солту. Соберите все 4 обрывка.', 'A piece of the map that belonged to the former lord\'s guard Solt. Gather 4 of these.', 'etc_map_piece_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2802, '2nd Torn Map Piece', NULL, 'Часть карты, принадлежавшей бывшему стражу лорда Макелу. Соберите все 4 обрывка.', 'A piece of the map that belonged to the former lord\'s guard Makel. Gather 4 of these.', 'etc_map_piece_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2803, 'Solt\'s Map', NULL, 'Карта, на которой написано имя Солта, бывшего стража лорда.', 'A map where the name of the former lord\'s guard Solt is written.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2804, 'Makel\'s Map', NULL, 'Карта, на которой написано имя Макела, бывшего стража лорда.', 'A map where the name of the former lord\'s guard Makel is written.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2805, 'Combined Map', NULL, 'Используйте карту (Alt+M) и найдите место, где спрятано золото лорда.', 'Using the map (alt-m), find the hiding place of the lord\'s gold bar.', 'etc_map_ivory_i00', 0);
INSERT INTO `all_items` VALUES (2806, 'Rusted Key', NULL, 'Ржавый ключ, найденный под деревом, указанном на карте.', 'A rusty copper key discovered while digging under the tree indicated on the map.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (2807, 'Gold Bar', NULL, 'Золотой слиток с печатью лорда Эштона. Отнесите его Алексу.', 'A gold bar stamped with Duke Ashton\'s seal. Take this to Alex.', 'etc_lump_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2808, 'Alex\'s Recommend', NULL, 'Рекомендательное письмо от Алекса. Отнесите его Мастеру Лютеру.', 'A recommendation written by Alex. Take this to Master Luther.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2809, 'Mark of Searcher', NULL, 'Знак, выдаваемый прошедшим Испытание ищущего. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Searcher. An occupation change related item.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (2810, 'Report of Perrin', NULL, 'Отчет, предназначенный для Перрина из Гавани Глудина.', 'Take this report and go seek Perrin in Gludin Harbor.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2811, 'Kristina\'s Letter', NULL, 'Письмо Святой Кристины. Отнесите его Мастеру Сориусу.', 'A letter given by Saint Kristina. Deliver this to Master Sorius.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (2812, 'Picture of Windy', NULL, 'Картина Винди. Отнесите ее Винди.', 'A picture of Windy. Take this drawing to Windy.', 'etc_plate_white_i00', 0);
INSERT INTO `all_items` VALUES (2813, 'Golden Statue', NULL, 'Награда, врученная главой приюта. Неужели от нее есть какая-то польза?..', 'The reward given by the head of the orphanage. Something good happens if this is in possession?', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (2814, 'Windy\'s Pebbles', NULL, 'Галька, которую Винди подобрала в Пустоши. Отнесите ее Гупу, главе приюта недалеко от Глудио.', 'A pebble that Windy has picked up from the Wastelands. Take this to Gupu, the head of the orphanage near Gludio.', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (2815, 'Order of Sorius', NULL, 'Приказ, предписывающий Вам отправиться к Дорину, который находится к западу от Лагеря Орков.', 'Take these orders and show them to Daurin, who is located west of the Orc Barracks.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2816, '1st Secret Letter', NULL, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'The documents of Leto lizardmen. Gather all of the letters and deliver them to Saint Kristina.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2817, '2nd Secret Letter', NULL, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'The documents of Leto lizardmen. Gather all of the letters and deliver them to Saint Kristina.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2818, '3rd Secret Letter', NULL, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'The documents of Leto lizardmen. Gather all of the letters and deliver them to Saint Kristina.', 'weapon_scroll_of_wisdom_i00', 0);
INSERT INTO `all_items` VALUES (2819, '4th Secret Letter', NULL, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'The documents of Leto lizardmen. Gather all of the letters and deliver them to Saint Kristina.', 'weapon_scroll_of_wisdom_i01', 0);
INSERT INTO `all_items` VALUES (2820, 'Mark of Healer', NULL, 'Знак, выдаваемый прошедшим Испытание целителя. Предмет для смены профессии.', 'A mark given to those who have passed the Test of the Healer. An occupation change related item.', 'etc_jewel_white_i00', 0);
INSERT INTO `all_items` VALUES (2821, 'Mark of Reformer', NULL, 'Знак, выдаваемый прошедшим Испытание жреца. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Reformer. An occupation change related item.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (2822, 'Book of Reform', NULL, 'Книга, полученная от Жрицы Пупины. Отправляйтесь в Землю Казненных и убейте нежить при помощи силы света.', 'A book received from Priestess Pupina. Go to the Execution Grounds and slay the nameless undeads with the power of light.', 'weapon_apprentices_spellbook_i01', 0);
INSERT INTO `all_items` VALUES (2823, 'Letter of Introduction', NULL, 'Письмо Жрицы Пупины. Возьмите его и отдайте Проповеднице Сла в Пустоши.', 'A letter introducing Priestess Pupina. Take this and meet with to Preacher Sla of the Wastelands.', 'etc_scroll_of_enchant_armor_i00', 0);
INSERT INTO `all_items` VALUES (2824, 'Sla\'s Letter', NULL, 'Письмо Сла. Отнесите его Катари, которая находится недалеко от водопада в Нейтральной Зоне.', 'A letter given by Sla. Take this to Katari, who is near the waterfalls of the Neutral Zone.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (2825, 'Greetings', NULL, 'Письмо, отправленное Сла ее ученикам. Отнесите его в Деревню Орков, Деревню Гномов и на Говорящий Остров. Только не перепутайте!', 'A letter sent by Sla to her disciples. Go to the Orc Village, Dwarven Village, and Talking Island in this order.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (2826, 'Ol Mahum\'s Money', NULL, 'Деньги Гноллов, которые они дают вместо награды. Для чего они нужны? Этого не знает никто.', 'Ol Mahum currency given by the themselves as a reward. For what...? Nobody knows.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (2827, 'Katari\'s Letter', NULL, 'Ответное письмо Катари для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'Katari\'s reply letter to Sla. Collect 3 reply letters from Sla\'s disciples and deliver them to Sla.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2828, 'Nyakuri\'s Letter', NULL, 'Ответное письмо Ниакури для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'Nyakuri\'s reply letter to Sla. Collect 3 reply letters from Sla\'s disciples and deliver them to Sla.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2829, 'Undead List', NULL, 'Скелет Стрелок, Лорд Скелетов, Скелет Снайпер, Скелет Каторжник, Безмолвный Ужас.', 'Skeleton archer, skeleton lord, skeleton marksman, misery skeleton, silent horror.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (2830, 'Ramus\'s Letter', NULL, 'Ответное письмо Рамуса для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'A reply letter sent by Ramus to Sla. Deliver this to Sla after meeting all of Sla\'s disciples.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2831, 'Ripped Diary', NULL, 'Обрывок дневника, содержащего последние слова молодой женщины, убитой во время охоты на ведьм герцога Байрона Эштона. Соберите 7 таких.', 'Diaries containing the final words of young women unfairly killed during the witch hunts of Duke Byron Ashton. Collect 7 of them.', 'etc_map_piece_ivory_i00', 0);
INSERT INTO `all_items` VALUES (2832, 'Huge Nail', NULL, 'Огромный ноготь, вросший в череп Арурона. Отнесите его Жрице Пупине в Гиран.', 'The large nail that was embedded in Aruraune\'s skull. Take this to Priestess Pupina at Giran Castle Town.', 'weapon_heavy_chisel_i00', 0);
INSERT INTO `all_items` VALUES (2833, 'Letter of Betrayer', NULL, 'Письмо Гнолла Предателя. Отнесите его Катари, находящейся в районе болот Темного Леса.', 'A letter given by an Ol Mahum Betrayer. Take it to Katari in the swamp area of the Dark Forest.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2834, 'Bone Fragment', NULL, 'Обломок кости Безмолвного Ужаса. Отнесите его вместе с остальными костями нежити Рамусу.', 'Bone pieces of a silent horror. Take this, along with the rest of the undead bone fragments, to Ramus.', 'etc_rib_black_i00', 0);
INSERT INTO `all_items` VALUES (2835, 'Bone Fragment', NULL, 'Обломок кости Лорда Скелетов. Отнесите его вместе с остальными костями нежити Рамусу.', 'A bone fragment of a skeleton lord. Take this, along with the rest of the undead bone fragments, to Ramus.', 'etc_piece_bone_white_i00', 0);
INSERT INTO `all_items` VALUES (2836, 'Bone Fragment', NULL, 'Обломок кости Скелета Снайпера. Отнесите его вместе с остальными костями нежити Рамусу.', 'A bone fragment of a skeleton marksman. Take this, along with the rest of the undead bone fragments, to Ramus.', 'etc_molar_black_i00', 0);
INSERT INTO `all_items` VALUES (2837, 'Bone Fragment', NULL, 'Обломок кости Скелета Каторжника. Отнесите его вместе с остальными костями нежити Рамусу.', 'A bone fragment from a misery skeleton. Take it along with other bone fragments of the undead to Ramus.', 'etc_molar_white_i00', 0);
INSERT INTO `all_items` VALUES (2838, 'Bone Fragment', NULL, 'Обломок кости Скелета Стрелка. Отнесите его вместе с остальными костями нежити Рамусу.', 'A bone fragment of a skeleton archer. Take this, along with the rest of the undead bone fragments, to Ramus.', 'etc_rib_white_i00', 0);
INSERT INTO `all_items` VALUES (2839, 'Bone Fragment', NULL, 'Обломок кости Скелета. Отнесите его вместе с остальными костями нежити Рамусу.', 'A bone fragment of a skeleton. Take this, along with the rest of the undead bone fragments, to Ramus.', 'etc_rib_black_i00', 0);
INSERT INTO `all_items` VALUES (2840, 'Mark of Magus', NULL, 'Знак, выдаваемый прошедшим Испытание магии. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Magus. An item for occupational change.', 'etc_mark_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2841, 'Rukal\'s Letter', NULL, 'Письмо Барда Рукала Парине из Глудина.', 'A letter sent by Bard Rukal to Parina of the Village of Gludin.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2842, 'Parina\'s Letter', NULL, 'Письмо Парины Старейшине Казиану с вопросом по поводу Поющего цветка.', 'A letter sent by Parina to Elder Casian. The letter makes inquiries regarding the singing flower.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2843, 'Lilac Charm', NULL, 'Защитный оберег, созданный Старейшиной Казианом. Возьмите его на поиски трех типов Поющего цветка.', 'A protection charm created by Elder Casian. Take this and seek out the 3 types of singing flowers.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (2844, '1st Golden Seed', NULL, 'Семя Поющего цветка, питающегося кровью. Соберите все 3 семени и отнесите их Барду Рукалу.', 'The seed of the singing flower, which absorbs blood in order to bloom. Gather 3 of these and take them to Bard Rukal.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2845, '2nd Golden Seed', NULL, 'Семя Поющего цветка, питающегося кровью. Соберите все 3 семени и отнесите их Барду Рукалу.', 'The seed of the singing flower, which absorbs blood in order to bloom. Gather 3 of these and take them to Bard Rukal.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (2846, '3rd Golden Seed', NULL, 'Семя Поющего цветка, питающегося кровью. Соберите все 3 семени и отнесите их Барду Рукалу.', 'The seed of the singing flower, which absorbs blood in order to bloom. Gather 3 of these and take them to Bard Rukal.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (2847, 'Score of Elements', NULL, 'Ноты, полученные от Барда Рукала. Возьмите их на поиски звуков стихий.', 'A music score sheet given by Bard Rukal. Take this and find the 4 elemental tones.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (2848, 'Dazzling Drop', NULL, 'Ослепительный драгоценный камень в форме слезы. Соберите 20 таких и отнесите их Водной Ундине.', 'A dazzling, tear-shaped jewel. Gather 20 of these and take them to the Water Undine.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (2849, 'Flame Crystal', NULL, 'Кристалл, добытый из призрачного огня. Соберите 5 таких и отнесите их Огненной Саламандре.', 'A crystal obtained from the ghost fire. Gather 5 of these and take them to the Flame Salamander.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (2850, 'Harpy\'s Feather', NULL, 'Перо убитой гарпии. Соберите 20 таких и отнесите их Воздушному Сильфу.', 'The feather of a slain harpy. Gather 20 of these and take them to the Wind Sylph.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (2851, 'Wyrm\'s Wingbone', NULL, 'Кость из крыла змея. Соберите 10 таких и отнесите их Воздушному Сильфу.', 'The wingbone of a slain wyrm. Gather 10 of these and take them to the Wind Sylph.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (2852, 'Windsus Mane', NULL, 'Грива вепря. Соберите 10 таких и отнесите их Воздушному Сильфу.', 'The mane of a slain windsus. Gather 10 of these and take them to the Wind Sylph.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (2853, 'Enchanted Monster Eye Shell', NULL, 'Оболочка зачарованного монстроглаза. Соберите 10 таких и отнесите их Земляной Змее.', 'The skin of a slain enchanted eye. Gather 10 of these and take them to the Earth Snake.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (2854, 'Enchanted Golem Powder', NULL, 'Каменная пыль с убитого зачарованного голема. Соберите 10 таких и отнесите их Земляной Змее.', 'Stone powder obtained after slaying an enchanted stone golem. Gather 10 of these and take them to the Earth Snake.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (2855, 'Enchanted Iron Golem Shard', NULL, 'Осколок зачарованного железного голема. Соберите 10 таких и отнесите их Земляной Змее.', 'A fragment of a destroyed enchanted iron golem. Gather 10 of these and take them to the Earth Snake.', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (2856, 'Tone of Water', NULL, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'One that comprises the beautiful harmony of the 4 elemental tones. Take this to Bard Rukal in the Town of Dion.', 'etc_scroll_of_enchant_armor_i01', 0);
INSERT INTO `all_items` VALUES (2857, 'Tone of Fire', NULL, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'One that comprises the beautiful harmony of the four elemental tones. Take this to Bard Rukal in the Town of Dion.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (2858, 'Tone of Wind', NULL, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'One that comprise the beautiful harmony of the four elemental tones. Take this to Bard Rukal in the Town of Dion.', 'etc_scroll_of_return_i01', 0);
INSERT INTO `all_items` VALUES (2859, 'Tone of Earth', NULL, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'One that comprise the beautiful harmony of the four elemental tones. Take this to Bard Rukal in the Town of Dion.', 'etc_scroll_of_resurrection_i01', 0);
INSERT INTO `all_items` VALUES (2860, 'Salamander Charm', NULL, 'Оберег, данный Огненной Саламандрой. Она согласна отдать Звук Огня за 5 Кристаллов Пламени.', 'A charm of agreement given by the Flame Salamander. It promises to give the tone of fire in return for 5 flame crystals.', 'etc_piece_of_cloth_red_i00', 0);
INSERT INTO `all_items` VALUES (2861, 'Sylph Charm', NULL, 'Оберег, данный Воздушным Сильфом. Он согласен отдать Звук Ветра за материалы, собранные с Гарпий, Змеев и Вепрей.', 'A charm of agreement given by the Wind Sylph. It promises to give the tone of wind in return for materials gathered from the harpy, wyrm, and windsus.', 'etc_piece_of_cloth_white_i00', 0);
INSERT INTO `all_items` VALUES (2862, 'Undine Charm', NULL, 'Оберег, данный Водной Ундиной. Она согласна отдать Звук Воды за 20 Ослепительных Камней.', 'A charm of agreement given by the Water Undine. It promises to give the tone of water in return for 20 dazzling drops.', 'etc_piece_of_cloth_blue_i00', 0);
INSERT INTO `all_items` VALUES (2863, 'Serpent Charm', NULL, 'Оберег, данный Земляной Змеей. Она согласна отдать Звук Земли за уничтожение Зачарованных Монстров вокруг Башни Слоновой Кости.', 'A charm of agreement given by the Earth Snake. It promises to give the tone of earth in return for slaying the enchanted monsters in the surroundings of the Ivory Tower.', 'etc_piece_of_cloth_green_i00', 0);
INSERT INTO `all_items` VALUES (2864, 'Recommendation of Balanki', NULL, 'Рекомендательное письмо от Баланки из Гильдии Серебряных Весов. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'A recommendation given by Silver Scale\'s Balanki. Gather all 3 recommendations and visit Lockrin of the Iron Gate.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (2865, 'Recommendation of Filaur', NULL, 'Рекомендательное письмо от Филара из Гильдии Серой Колонны. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'A recommendation given by Filaur of the Gray Pillar. Gather all 3 recommendations and seek out Lockirin of the Iron Gate.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (2866, 'Recommendation of Arin', NULL, 'Рекомендательное письмо от Арина из Гильдии Черной Наковальни. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'A recommendation given by Black Anvil\'s Arin. Gather all 3 recommendations and go to Lockrin of the Iron Gate.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2867, 'Mark of Maestro', NULL, 'Знак, выдаваемый прошедшим Испытание мастера. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Maestro. An occupation change related item.', 'etc_badge_silver_i00', 0);
INSERT INTO `all_items` VALUES (2868, 'Letter of Solder Detachment', NULL, 'Письмо Капитана Крото, в котором говорится о скором прибытии подкреплений. Доставьте его Локрину.', 'A letter from Captain Croto that promises to send soldiers. Deliver this to Lockrin of the Iron Gate.', 'etc_scroll_of_return_i01', 0);
INSERT INTO `all_items` VALUES (2869, 'Paint of Kamuru', NULL, 'Портрет Камуру. Отправляйтесь в Пещеру Испытаний во владениях Орков и выясните, что с ним случилось.', 'A painting of Kamuru. Go to the Cave of Trials in the orc kingdom to seek him out.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2870, 'Necklace of Kamuru', NULL, 'Ожерелье, которое носил Камуру. Отнесите его Капитану Крото.', 'A necklace worn by Kamuru. Deliver this to Captain Croto.', 'accessary_necklace_of_darkness_i00', 0);
INSERT INTO `all_items` VALUES (2871, 'Paint of Teleport Device', NULL, 'Рисунок устройства для телепортации. Заберите этот прибор у Мастера Томы.', 'A drawing of a teleport device. Recover this device from Master Toma.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (2872, 'Teleport Device', NULL, 'Устройство для телепортации, разработанное Мастером Томой. Отнесите его Арину.', 'A teleport device given by Master Toma. Deliver this to Black Anvil\'s Arin.', 'etc_squares_gray_i00', 0);
INSERT INTO `all_items` VALUES (2873, 'Architecture of Cruma', NULL, 'Простое объяснение архитектуры Башни Крумы. Отнесите его команде, находящейся у входа в Башню Крумы.', 'A simple explanation of Cruman architecture. Take this to the research team stationed at the entrance of the Cruma Tower.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (2874, 'Report of Cruma', NULL, 'Отчет о результатах исследований Башни Крумы. Отнесите его Филару.', 'A report recording the results of investigations made by the Cruma reasearch team. Deliver this to Eldar Filaur.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2875, 'Ingredients of Antidote', NULL, 'Соберите 10 Осиных Жал, 10 Паутин Болотного Паука и 10 порций Крови Пиявки и отнесите их Исследователю Лорейн.', 'Gather 10 stinger wasp needles, 10 marsh spider webs, and 10 leech bloods and deliver them to Researcher Lorain.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (2876, 'Stinger Wasp Needle', NULL, 'Жало осы. Соберите 10 таких и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'Gather 10 of these and deliver them along with the other ingredients to Researcher Lorain.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (2877, 'Marsh Spider\'s Web', NULL, 'Тонкая паутина. Соберите 10 таких и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'Gather 10 of these and deliver them along with the other ingredients to Researcher Lorain.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (2878, 'Leech Blood', NULL, 'Кровь, добытая при убийстве пиявки. Соберите 10 порций и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'Gather 10 of these and deliver them along with the other ingredients to Researcher Lorain.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (2879, 'Mark of Warspirit', NULL, 'Знак, выдаваемый прошедшим Испытание вестника. Предмет для смены профессии.', 'A mark given to those who have passed the Test of the War Spirit. An item for occupational change.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (2880, 'Vendetta Totem', NULL, 'Тотем, выдаваемый Оркам, готовым наказать предателей расы. Возьмите его и убейте Орков Тамлин.', 'A totem given to the Orcs who seek to punish betrayers of their race. Take this and hunt the Tamlin Orcs.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (2881, 'Tamlin Orc Head', NULL, 'Голова убитого Орка Тамлин. Соберите 13 таких и отнесите их Провидцу Сомаку.', 'The head of a slain Tamlin Orc. Gather 13 of these and take them to Seer Somak.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (2882, 'Warspirit Totem', NULL, 'Тотем, используемый в ритуале Духа Войны. Отнесите его Прародителю Мартанкусу в Пещеру Испытаний.', 'A totem used in the Ritual of the War Spirit. Take this to Ancestor Martankus in the Cave of Trials.', 'accessary_another_worlds_necklace_i00', 0);
INSERT INTO `all_items` VALUES (2883, 'Orim\'s Contract', NULL, '\"Я согласен отдать тебе Останки Браки за 10 Глаз Порты, 10 Чешуй Экскуро и 10 Когтей Мордео.\"', 'I will give you Braki\'s remains in return for 10 porta eyes, 10 excuro scales and 10 mordeo talons.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (2884, 'Porta\'s Eye', NULL, 'Драгоценный камень из Глаза Порты. Соберите 10 таких и отнесите их Ориму Тени.', 'A jewel pried from the porta\'s eye. Gather 10 of these and take them to Orim of the Shadow.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (2885, 'Excuro\'s Scale', NULL, 'Чешуя Экскуро. Соберите 10 таких и отнесите их Ориму Тени.', 'The scales of an excuro. Gather 10 of these and take them to Orim of the Shadow.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (2886, 'Mordeos Talon', NULL, 'Коготь Мордео. Соберите 10 таких и отнесите их Ориму Тени.', 'The talons of a mordeo. Gather 10 of these and take them to Orim of the Shadow.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (2887, 'Braki\'s Remains', NULL, 'Останки Браки, древнего героя Орков. Отнесите их и останки трех других героев Провидцу Сомаку.', 'The remains of Braki, an ancient Orc hero. Take this, along with the additional 3 remains, to Seer Somak.', 'etc_ashes_black_i00', 0);
INSERT INTO `all_items` VALUES (2888, 'Pekiron\'s Totem', NULL, 'Охранный тотем, полученный от Провидца Пекирона. Возьмите его с собой, убейте Шаманов и Владык Ящеров Лито и соберите останки Тонара.', 'A guardian totem received from Seer Pekiron. Take this and go to the Leto lizardman shamans and chiefs to recover Tonar\'s remains.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (2889, 'Tonar\'s Skull', NULL, 'Череп Тонара, древнего героя Орков. Отнесите его и остальные останки Провидцу Пекирону.', 'The skull of Tonar, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Pekiron.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (2890, 'Tonar\'s Rib Bone', NULL, 'Ребро Тонара, древнего героя Орков. Отнесите его и остальные останки Провидцу Пекирону.', 'The rib bones of Tonar, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Pekiron.', 'etc_rib_black_i00', 0);
INSERT INTO `all_items` VALUES (2891, 'Tonar\'s Spine', NULL, 'Хребет Тонара, древнего героя Орков. Отнесите его и остальные останки Провидцу Пекирону.', 'The spine bones of Tonar, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Pekiron.', 'etc_ginseng_gray_i00', 0);
INSERT INTO `all_items` VALUES (2892, 'Tonar\'s Arm Bone', NULL, 'Предплечье Тонара, древнего героя Орков. Отнесите его и остальные останки Провидцу Пекирону.', 'The arm bones of Tonar, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Pekiron.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (2893, 'Tonar\'s Thigh Bone', NULL, 'Бедро Тонара, древнего героя Орков. Отнесите его и остальные останки Провидцу Пекирону.', 'The thigh bones of Tonar, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Pekiron.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (2894, 'Tonar\'s Remains', NULL, 'Останки Тонара, древнего героя Орков. Отнесите их и останки трех других героев Провидцу Сомаку.', 'The remains of Tonar, an ancient Orc hero. Take this, along with the other 3 heros\' remains, to Seer Somak.', 'etc_ashes_black_i00', 0);
INSERT INTO `all_items` VALUES (2895, 'Manakia\'s Totem', NULL, 'Тотем, полученный от Провидца Манакии. Возьмите его, убейте Медуз и Королеву Горгон Стеноа, чтобы забрать останки Гермодта.', 'A totem received from Seer Manakia. Take this and go to the medusas and Stenoa, the gorgon queen, to recover Hermodt\'s remains.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (2896, 'Hermodt\'s Skull', NULL, 'Череп Гермодта, древнего героя Орков. Отнесите его и остальные останки Провидцу Манакии.', 'The skull of Hermodt, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Manakia.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (2897, 'Hermodt\'s Rib Bone', NULL, 'Ребро Гермодта, древнего героя Орков. Отнесите его и остальные останки Провидцу Манакии.', 'The rib bones of Hermodt, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Manakia.', 'etc_rib_red_i00', 0);
INSERT INTO `all_items` VALUES (2898, 'Hermodt\'s Spine', NULL, 'Хребет Гермодта, древнего героя Орков. Отнесите его и остальные останки Провидцу Манакии.', 'The spine bones of Hermodt, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Manakia.', 'etc_ginseng_red_i00', 0);
INSERT INTO `all_items` VALUES (2899, 'Hermodt\'s Arm Bone', NULL, 'Предплечье Гермодта, древнего героя Орков. Отнесите его и остальные останки Провидцу Манакии.', 'The arm bones of Hermodt, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Manakia.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (2900, 'Hermodt\'s Thigh Bone', NULL, 'Бедро Гермодта, древнего героя Орков. Отнесите его и остальные останки Провидцу Манакии.', 'The thigh bones of Hermodt, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Manakia.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (2901, 'Hermodt\'s Remains', NULL, 'Останки Гермодта, древнего героя Орков. Отнесите их и останки трех других героев Провидцу Сомаку.', 'The remains of Hermodt, an ancient Orc hero. Take this, along with the other three heros\' remains, to Seer Somak.', 'etc_ashes_red_i00', 0);
INSERT INTO `all_items` VALUES (2902, 'Racoy\'s Totem', NULL, 'Тотем, полученный от Провидца Ракоя. Отправляйтесь в Храм Эйнхасад в Глудио, чтобы узнать насчет Кируны.', 'A totem given by Seer Racoy. Take this and go to the Temple of Einhasad in the Town of Gludio to ask about Kiruna.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (2903, 'Vivyan\'s Letter', NULL, 'Письмо Жрицы Вивиан. Отнесите его Торговцу Сариену в южную часть Пустоши.', 'A letter from Priestess Vivyan. Take this to Trader Sarien of the Southern Wastelands.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (2904, 'Insect Diagram Book', NULL, 'Энциклопедия насекомых, которую Торговец Сариен отдал Вам в помощь. Возьмите ее с собой на охоту на Элитных Муравьев, чтобы найти останки Кируны.', 'An insect encyclopedia that Trader Sarien has given as aid. Take this and hunt noble ants to recover Kiruna\'s remains.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (2905, 'Kiruna\'s Skull', NULL, 'Череп Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'The skull of Kiruna, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Racoy.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (2906, 'Kiruna\'s Rib Bone', NULL, 'Ребро Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'The rib bones of Kiruna, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Racoy.', 'etc_rib_white_i00', 0);
INSERT INTO `all_items` VALUES (2907, 'Kiruna\'s Spine', NULL, 'Хребет Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'The spine bones of Kiruna, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Racoy.', 'etc_ginseng_yellow_i00', 0);
INSERT INTO `all_items` VALUES (2908, 'Kiruna\'s Arm Bone', NULL, 'Предплечье Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'The arm bones of Kiruna, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Racoy.', 'etc_piece_bone_white_i00', 0);
INSERT INTO `all_items` VALUES (2909, 'Kiruna\'s Thigh Bone', NULL, 'Бедро Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'The thigh bones of Kiruna, an ancient Orc hero. Take this, along with the additional 4 remains, to Seer Racoy.', 'etc_piece_bone_white_i00', 0);
INSERT INTO `all_items` VALUES (2910, 'Kiruna\'s Remains', NULL, 'Останки Кируны, древнего героя Орков. Отнесите их и останки трех других героев Провидцу Сомаку.', 'The remains of Kiruna, an ancient Orc hero. Take this, along with the other 3 heros\' remains, to Seer Somak.', 'etc_ashes_white_i00', 0);
INSERT INTO `all_items` VALUES (2911, 'Braki\'s Remains', NULL, 'Останки героя Браки, заключенные в урну. Отнесите их Прародителю Мартанкусу в Пещеру Испытаний', 'The remains of the hero, Braki, encased in an urn. Take this to the Ancestor Martankus in the Cave of Trials.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (2912, 'Tonar\'s Remains', NULL, 'Останки героя Тонара, заключенные в урну. Отнесите их Прародителю Мартанкусу в Пещеру Испытаний', 'The remains of the hero, Tonar, encased in an urn. Take this to the Ancestor Martankus in the Cave of Trials.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (2913, 'Hermodt\'s Remains', NULL, 'Останки героя Гермодта, заключенные в урну. Отнесите их Прародителю Мартанкусу в Пещеру Испытаний', 'The remains of the hero, Hermodt, encased in an urn. Take this to the Ancestor Martankus in the Cave of Trials.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (2914, 'Kiruna\'s Remains', NULL, 'Останки героя Кируны, заключенные в урну. Отнесите их Прародителю Мартанкусу в Пещеру Испытаний', 'The remains of the hero, Kiruna, encased in an urn. Take this to the Ancestor Martankus in the Cave of Trials.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (2915, 'Old Knight Sword', NULL, 'Меч, который необходимо использовать, чтобы нанести смертельный удар Духу Сэра Херода.', 'Use this sword to deliver the final blow to the spirit of Sir Herod.', 'weapon_long_sword_i00', 0);
INSERT INTO `all_items` VALUES (2916, 'Broken Teleport Device', NULL, 'Устройство для телепортации, разработанное Мастером Томой. Верните его Мастеру Томе.', 'The teleport device given by Master Toma. Take this back to Master Toma.', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (2917, 'Ring of Seal Gemstone', NULL, 'Основной материал, используемый Гномами для создания Кольца Печати. Можно продать в Торговой Лавке.', 'A key material for Dwarves to make a Ring of Binding. Can be sold in any shop.', 'etc_bead_silver_i00', 6);
INSERT INTO `all_items` VALUES (2918, 'Mithril Scale Gaiters Material', NULL, 'Основной материал, используемый Гномами для создания Мифриловых Чешуйчатых Набедренников. Можно продать в Торговой Лавке.', 'A key material for Dwarves to make Mithril Scale Gaiters. Can be sold in any shop.', 'etc_plate_silver_i00', 6);
INSERT INTO `all_items` VALUES (2919, 'Brigandine Gaiters Material', NULL, 'Основной материал, используемый Гномами для создания Панцирных Набедренников. Можно продать в Торговой Лавке.', 'A key material for Dwarves to make Brigandine Gaiters. Can be sold in any shop.', 'etc_plate_silver_i00', 6);
INSERT INTO `all_items` VALUES (2920, 'Elven Mithril Tunic Pattern', NULL, 'Основной материал, используемый Гномами для создания Мифриловой Туники Эльфов. Можно продать в Торговой Лавке.', 'A key material for Dwarves to make an Elven Mithril Tunic. Can be sold in any shop.', 'etc_piece_of_cloth_white_i00', 6);
