INSERT INTO `all_items` VALUES (3108, 'Amulet: Seal of Mirage', NULL, 'Амулет, необходимый для изучения умения \"Печать Миражей\". Профессия: Верховный Шаман.Необходимый уровень: 44.', 'Amulet required for the Seal of Mirage spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3109, 'Amulet: Seal of Silence', NULL, 'Амулет, необходимый для изучения умения \"Печать Безмолвия\". Профессия: Верховный Шаман.Необходимый уровень: 48.', 'Amulet required for the Seal of Silence spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3110, 'Amulet: Seal of Scourge', NULL, 'Амулет, необходимый для изучения умения \"Печать Наказания\". Профессия: Верховный Шаман.Необходимый уровень: 40.', 'Amulet required for the Seal of Scourge spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3111, 'Amulet: Seal of Suspension', NULL, 'Амулет, необходимый для изучения умения \"Печать Отставания\". Профессия: Верховный Шаман.Необходимый уровень: 48.', 'Amulet required for the Seal of Suspension spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3112, 'Amulet: Pa\'agrio\'s Vision', NULL, 'Амулет, необходимый для изучения умения \"Взгляд Паагрио\". Профессия: Верховный Шаман.Необходимый уровень: 44.', 'Amulet required for the Pa\'agrio\'s Vision spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3113, 'Amulet: Pa\'agrio\'s Protection', NULL, 'Амулет, необходимый для изучения умения \"Защита Паагрио\". Профессия: Верховный Шаман.Необходимый уровень: 40.', 'Amulet required for the Pa\'agrio\'s Protection spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3114, 'Amulet: Steal Essence', NULL, 'Амулет, необходимый для изучения умения \"Кража Сущности\". Профессии: Вестник Войны, Верховный Шаман.Необходимый уровень: 40.', 'Amulet required for the Steal Essence spell. Used by Warcryers and Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3115, 'Amulet: Freezing Flame', NULL, 'Амулет, необходимый для изучения умения \"Замораживающее Пламя\". Профессия: Вестник Войны.Необходимый уровень: 40.', 'Amulet required for the Freezing Flame spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3116, 'Amulet: Chant of Fury', NULL, 'Амулет, необходимый для изучения умения \"Напев Ярости\". Профессия: Вестник Войны.Необходимый уровень: 48.', 'Amulet required for the Chant of Fury spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3117, 'Amulet: Chant of Evasion', NULL, 'Амулет, необходимый для изучения умения \"Напев Уклонения\". Профессия: Вестник Войны.Необходимый уровень: 40.', 'Amulet required for the Chant of Evasion spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3118, 'Amulet: Chant of Rage', NULL, 'Амулет, необходимый для изучения умения \"Напев Гнева\". Профессия: Вестник Войны.Необходимый уровень: 44.', 'Amulet required for the Chant of Rage spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3119, 'Mark of Guildsman', NULL, 'Знак прошедшего Испытание умения. Предмет для смены профессии.', 'A mark given to those who have passed the Trial of the Guildsman. An occupation change related item.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (3120, 'Valkon\'s Recommendation', NULL, 'Рекомендация, написанная Смотрителем Склада Вальконом. Отнесите ее Кузнецу Альтрану на Говорящий Остров.', 'A recommendation letter written by Warehouse Keeper Valkon. Take this and go to Blacksmith Altran of Talking Island.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3121, 'Mandragora Berry', NULL, 'Ягода мандрагоры, широко применяемая при лечении болезней.', 'The fruit of mandragoras, known for their uses in treating ailments.', 'etc_fruit_red_i00', 0);
INSERT INTO `all_items` VALUES (3122, 'Altran\'s Instructions', NULL, 'Распоряжение Кузнеца Альтрана. Необходимо собрать материалы и создать 7 Колец Мастера.', 'Blacksmith Altran\'s instructions. The instructions are to gather materials and create 7 journeyman\'s rings.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3123, 'Altran\'s 1st Recommendation', NULL, 'Записка, написанная Кузнецом Альтраном. Отнесите ее Смотрителю Склада Норману в Глудин.', 'A recommendation letter written by Blacksmith Altran. Take this and go to Warehouse Keeper Norman of the Village of Gludin.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3124, 'Altran\'s 2nd Recommendation', NULL, 'Записка, написанная Кузнецом Альтраном. Отнесите ее Кузнецу Пинтеру в Глудио.', 'A recommendation letter written by Blacksmith Altran. Take this and go to Blacksmith Pinter of the Town of Gludio.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3125, 'Norman\'s Instructions', NULL, 'Распоряжение Смотрителя Склада Нормана. Необходимо сходить к Кузнецу Данингу в Деревню Охотников и вернуть ключ.', 'Warehouse Keeper Norman\'s instructions. The instructions are to go to Blacksmith Duning of Hunters Village and bring back the key.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3126, 'Norman\'s Receipt', NULL, 'Расписка Смотрителя Склада Нормана. Отнесите ее Кузнецу Данингу в Деревню Охотников.', 'Warehouse Keeper Norman\'s receipt. Take this and go to Blacksmith Duning of the Hunters Village.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3127, 'Duning\'s Instructions', NULL, 'Распоряжение Кузнеца Данинга. Вам необходимо отобрать 30 ключей у Орков Брека.', 'Blacksmith Duning\'s instructions. It gives an order to recover 30 keys from Breka orcs.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3128, 'Duning\'s Key', NULL, 'Мифриловый ключ Орка Брека. Соберите 30 ключей и отнесите их Кузнецу Данингу.', 'Mithril key recovered from Breka orcs. Collect 30 and take them to Blacksmith Duning.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (3129, 'Norman\'s List', NULL, 'Список Смотрителя склада Нормана: 70 щепоток Серого Порошка, 70 Гранитных Точильных Камней, 70 пузырьков Красного Пигмента и 70 мотков Сплетенной Бечевки.', 'Ingredient list of Warehouse Keeper Norman: 70 units of gray bone powder, 70 granite whetstones, 70 units of red pigment, and 70 units of braided yarn.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3130, 'Gray Bone Powder', NULL, 'Порошок, получаемый из костей Вурдалаков и Рабов. Соберите 70 его щепоток и отнесите Смотрителю Склада Норману.', 'The powder collected from the bones of ghouls and strains. Gather 70 of these and take them to Warehouse Keeper Norman.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (3131, 'Granite Whetstone', NULL, 'Точильный камень, добываемый из фрагментов Гранитных Големов. Соберите 70 штук и отнесите их Смотрителю Склада Норману.', 'A whetstone made from the fragments of the granite golem. Gather 70 of these and take them to Warehouse Keeper Norman.', 'etc_plate_black_i00', 0);
INSERT INTO `all_items` VALUES (3132, 'Red Pigment', NULL, 'Красный пигмент, получаемый после убийства Поедателя Мертвечины. Соберите 70 пузырьков с ним и отнесите Смотрителю Склада Норману.', 'Red pigment obtained by slaying the dead seeker bat. Gather 70 of these and take them to Warehouse Keeper Norman.', 'etc_lesser_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (3133, 'Braided Yarn', NULL, 'Плетеная бечевка, получаемая после убийства Фавнов. Соберите 70 ее мотков и отнесите Смотрителю Склада Норману.', 'Braided yarn obtained by slaying the silenos. Gather 70 of these and take them to Warehouse Keeper Norman.', 'etc_skein_gray_i00', 0);
INSERT INTO `all_items` VALUES (3134, 'Journeyman Gem', NULL, 'Материал, используемый для создания Кольца Мастера.', 'A material used to make the journeyman\'s ring.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (3135, 'Pinter\'s Instructions', NULL, 'Распоряжение Кузнеца Пинтера - необходимо вернуть 70 Янтарных Бусинок.', 'Instructions of Blacksmith Pinter: Find and bring back 70 amber beads.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3136, 'Amber Bead', NULL, 'Янтарная бусинка. Соберите 70 таких и отнесите Кузнецу Пинтеру.', 'A bead-shaped piece of amber. Collect 70 of these and take them to Blacksmith Pinter.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (3137, 'Amber Lump', NULL, 'Необработанный кусок янтаря. Материал, используемый при создании Янтарной Бусинки.', 'An unrefined lump of amber. The material used in creating the Amber Bead.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (3138, 'Journeyman Deco Beads', NULL, 'Материал, используемый для создания Кольца Мастера.', 'Ingredient item used to make a journeyman\'s ring.', 'BranchSys2.etc_Journeyman_deco_beads_i00', 0);
INSERT INTO `all_items` VALUES (3139, 'Journeyman Ring', NULL, 'Кольцо, необходимое для прохождения Испытания умения. Изготовьте 7 таких колец и отнесите их Смотрителю Склада Валькону.', 'To pass the Trial of the Guildsman, you must create 7 of these rings. Take the completed rings to Warehouse Keeper Valkon.', 'accessary_ring_of_blessing_i00', 0);
INSERT INTO `all_items` VALUES (3140, 'Mark of Life', NULL, 'Знак, полученный за прохождение Испытания жизни. Предмет, необходимый для смены профессии.', 'A mark given to those who have passed the Testimony of Life. An occupation change related item.', 'etc_herb_green_i00', 0);
INSERT INTO `all_items` VALUES (3141, 'Cardien\'s Letter', NULL, 'Письмо от Мастера Кардиена. Отнесите его Иерарху Астериосу в Эльфийскую Деревню.', 'Letter by Master Cardien. Take this and go to Hierarch Asterios of the Elven Village.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3142, 'Camomile Charm', NULL, 'Талисман, полученный от Иерарха Астериоса. Отнесите его Мастеру Кардиену в Дион.', 'A talisman given by Hierarch Asterios. Take this and return to Master Cardien in the Town of Dion.', 'accessary_near_forest_necklace_i00', 0);
INSERT INTO `all_items` VALUES (3143, 'Hierarch\'s Letter', NULL, 'Письмо от Иерарха Астериоса. Отнесите его Талии, которая живет на восточном берегу Радужного Озера.', 'A letter given by Hierarch Asterios. Take this and go to Thalia, who lives on the eastern shores of Iris Lake.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3144, 'Moonflower Charm', NULL, 'Оберег, данный Иерархом Астериосом. Держите при себе при поиске Живой воды.', 'The charm given by Hierarch Asterios to keep in possession while searching for the water of life.', 'accessary_paradia_ring_i00', 0);
INSERT INTO `all_items` VALUES (3145, 'Grail Diagram', NULL, 'Чертеж Чаши Грааля, полученный от Талии. Отнесите его Кузнецу Пушкону в Гиран.', 'A diagram of the grail, given by Thalia. Take this and go to Blacksmith Pushkin of Giran Castle Town.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (3146, 'Thalia\'s 1st Letter', NULL, 'Письмо Талии. Отнесите его Аркении, которая находится возле Церемониального Алтаря.', 'Thalia\'s letter. Take this and go to Arkenia, who is at the Altar of Rites.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3147, 'Thalia\'s 2nd Letter', NULL, 'Письмо Талии. Отнесите его Изаэль Серебряной Тени в Деревню Охотников.', 'Thalia\'s letter. Take this and go to Isael Silvershadow of the Hunters Village.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3148, 'Thalia\'s Instructions', NULL, 'Письмо с распоряжением Талии. Необходимо вернуться после получения 38-го уровня.', 'A letter containing Thalia\'s instructions. The instructions are to come back after reaching level 38.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3149, 'Pushkin\'s List', NULL, 'Список Кузнеца Пушкона: 10 кусков Чистой Мифриловой Руды, 20 пузырьков Муравьиной Кислоты, 20 Клыков Змея.', 'A list given by Blacksmith Pushkin. \"10 pure Mithril Ore, 20 ant soldier acid, 20 Wyrm talons\"', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3150, 'Pure Mithril Cup', NULL, 'Кубок из мифрила, изготовленный Кузнецом Пушконом. Отнесите его Талии.', 'A cup crafted by Blacksmith Pushkin that is made of pure mithril. Take this back to Thalia.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (3151, 'Arkenia\'s Contract', NULL, 'Договор, составленный Аркенией. Согласно ему, Аркения отдаст Звездную Пыль в обмен на Рукопись Андариэль, которую можно найти в Глудине.', 'A contract written by Arkenia. The contract states that she will give stardust in return for Andariel\'s book from the Village of Gludin.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3152, 'Arkenia\'s Instructions', NULL, 'Распоряжение Аркении. Необходимо вернуть Рукопись Андариэль из Храма Эйнхасад в Глудине.', 'Arkenia\'s instructions. The instructions are to bring back Andariel\'s book from the Temple of Einhasad in the Village of Gludin.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3153, 'Adonius\'s list', NULL, 'Список, полученный от Адониуса: 20 пузырьков Сукровицы Паука и 20 Перьев Гарпии.', 'A list given by Priest Adonius: 20 spider ichor and 20 harpy\'s down.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3154, 'Andariel Scripture Copy', NULL, 'Копия Рукописи Андариэль, полученная у Жреца Адониуса. Отнесите ее Аркении.', 'A copy of Andariel\'s book given by Priest Adonius. Take this back to Arkenia.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (3155, 'Stardust', NULL, 'Серебряная пыль, полученная от Аркении. Отнесите ее Талии.', 'The silver dust received from Arkenia of the Dark Elves. Take this back to Thalia.', 'etc_powder_orange_i00', 0);
INSERT INTO `all_items` VALUES (3156, 'Isael\'s Instructions', NULL, 'Приказ Изаэль Серебряной Тени. Необходимо отобрать 6 частей Копья Талина у Шаманов Ящеров Лито.', 'A document containing Isael Silvershadow\'s instructions. It asks you to recover 6 pieces of talins spear from Leto lizardman shamans.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3157, 'Isael\'s Letter', NULL, 'Письмо Изаэль Серебряной Тени. Отнесите его Талии вместе с Копьем Талина.', 'A letter given by Isael Silvershadow. Take this back to Thalia along with Talin\'s spear.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3158, 'Grail of Purity', NULL, 'Чаша Грааля из чистого мифрила. Соберите в нее Слезы Единорога и отнесите их Талии.', 'A grail crafted of pure mithril. Catch the tears of the unicorn with the grail and take it back to Thalia.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (3159, 'Tears of Unicorn', NULL, 'Слезы единорога, убитого Копьем Талина. Отнесите их Талии.', 'The tears shed by Eva\'s unicorn when it is killed with Talin\'s spear. Take this back to Thalia.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (3160, 'Water of Life', NULL, 'Живая вода, способная омолодить Древо Жизни. Отнесите ее Иерарху Астериосу.', 'The holy water that contains the powers of life to rejuvenate the Mother Tree. Take this and go to Hierarch Asterios.', 'etc_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (3161, 'Pure Mithril Ore', NULL, 'Руда чистого мифрила. Соберите 10 ее кусков и отнесите вместе с остальными компонентами Кузнецу Пушкону.', 'The ore of pure mithril. Gather 10 of these, along with the rest of the ingredients, and take them back to Blacksmith Pushkin.', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (3162, 'Ant Soldier Acid', NULL, 'Яд, полученный после убийства Муравьев Солдат. Соберите 20 пузырьков и отнесите их Кузнецу Пушкону вместе с остальными ингредиентами.', 'The acid collected from ant soldiers after slaying them. Gather 20 bottles of this, along with the rest of the ingredients, and take them back to Blacksmith Pushkin.', 'etc_reagent_silver_i00', 0);
INSERT INTO `all_items` VALUES (3163, 'Wyrm\'s Talon', NULL, 'Коготь, полученный после убийства Змея. Соберите 20 когтей и отнесите их Кузнецу Пушкону вместе с остальными ингредиентами.', 'The talon of a wyrm obtained after slaying it. Gather 20 of these, along with the rest of the ingredients, and take them back to Blacksmith Pushkin.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3164, 'Spider Ichor', NULL, 'Сукровица Болотного Паука. Соберите 20 пузырьков и отнесите их Жрецу Адониусу.', 'The ichor of a marsh spider. Gather 20 units of this and take them back to Priest Adonius.', 'etc_reagent_green_i00', 0);
INSERT INTO `all_items` VALUES (3165, 'Harpy\'s Down', NULL, 'Перо убитой Гарпии. Соберите 20 штук и отнесите их Жрецу Адониусу.', 'The down feathers obtained after slaying a harpy. Gather 20 of these and take them back to Priest Adonius.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (3166, 'Talin\'s Spear Blade', NULL, 'Лезвие Копья Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'The blade portion of Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'etc_sword_body_i00', 0);
INSERT INTO `all_items` VALUES (3167, 'Talin\'s Spear Shaft', NULL, 'Древко Копья Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'The shaft portion of Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'weapon_club_i00', 0);
INSERT INTO `all_items` VALUES (3168, 'Talin\'s Ruby', NULL, 'Драгоценный камень, украшающий Копье Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'A decorative jewel that adorned Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3169, 'Talin\'s Aquamarine', NULL, 'Драгоценный камень, украшающий Копье Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'A decorative jewel that adorned Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3170, 'Talin\'s Amethyst', NULL, 'Драгоценный камень, украшающий Копье Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'A decorative jewel that adorned Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3171, 'Talin\'s Peridot', NULL, 'Драгоценный камень, украшающий Копье Талина. Отнесите его вместе с остальными частями Копья Изаэль Серебряной Тени.', 'A decorative jewel that adorned Talin\'s spear. Take this, along with the remaining portions of the spear, back to Isael Silvershadow.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (3172, 'Mark of Fate', NULL, 'Знак, полученный за прохождение Испытания судьбы. Предмет, необходимый для смены профессии.', 'A mark given to those who have passed the Testimony of Fate. An item for occupational change.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (3173, 'Kaira\'s Letter', NULL, 'Тайное письмо Магистра Кайры Монаху Метеусу в Храм Эйнхасад.', 'A letter sent by Magister Kaira to Brother Metheus of the Temple of Einhasad. This must be delivered secretly.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3174, 'Metheus\'s Funeral Jar', NULL, 'Урна для хранения останков умерших. Добудьте в Земле Казненных останки мертвой сестры Метеуса и соберите их в урну.', 'A jar for storing the remains of the dead. Take this to the Execution Grounds and search for the remains of Metheus\'s sister.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (3175, 'Kasandra\'s Remains', NULL, 'Останки Кассандры, сестры Метеуса. Отнесите их Метеусу.', 'The remains of Kasandra, Metheus\'s sister. Take this back to Brother Metheus.', 'etc_ashes_white_i00', 0);
INSERT INTO `all_items` VALUES (3176, 'Herbalism Textbook', NULL, 'Травник, содержащий информацию о сильном яде белладонны.', 'A textbook of various herbs and their usages. It also contains information about the deadly poison belladonna.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (3177, 'Ixia\'s List', NULL, 'Список предметов. Необходимо собрать по 10 штук каждого из них: Сукровица Медузы, Вытяжка из Паука, Корень Белладонны, Кровь Тирана, Прах Поедателя Мертвечины.', '10 units each of medusa\'s blood, marsh spider fluids, dead seeker\'s dung, tyrant\'s blood and nightshade root.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3178, 'Medusa\'s Ichor', NULL, 'Пузырек с сукровицей Медузы. Соберите 10 таких и отнесите их Мастеру Иксии.', 'The bottled blood of a medusa. Collect 10 of these and take them back to Master Ixia0', 'etc_reagent_blue_i00', 0);
INSERT INTO `all_items` VALUES (3179, 'Marsh Spider\'s Fluids', NULL, 'Пузырек с вытяжкой из паука. Соберите 10 таких и отнесите их Мастеру Иксии.', 'The bottled fluids of a marsh spider. Collect 10 of these and take them back to Master Ixia.', 'etc_lesser_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (3180, 'Dead Seeker Dung', NULL, 'Прах Поедателя Мертвечины. Соберите 10 щепоток и отнесите их Мастеру Иксии.', 'The dung of dead seeker bats. Collect 10 of these and take them back to Master Ixia.', 'etc_powder_black_i00', 0);
INSERT INTO `all_items` VALUES (3181, 'Tyrant\'s Blood', NULL, 'Пузырек с кровью Тирана. Соберите 10 таких и отнесите их Мастеру Иксии.', 'The bottled blood of tyrant. Collect 10 of these and take them back to Master Ixia.', 'etc_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (3182, 'Nightshade Root', NULL, 'Корень редкого растения белладонны. Соберите 10 таких и отнесите их Мастеру Иксии.', 'The roots of the rare nightshade herb. Collect 10 of these and take them back to Master Ixia.', 'etc_ginseng_gray_i00', 0);
INSERT INTO `all_items` VALUES (3183, 'Belladonna', NULL, 'Легендарный яд, капля которого может убить быка. Передайте его Монаху Метеусу.', 'A legendary poison that can kill a bull with a single drop. Take this to Brother Metheus.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (3184, 'Alder\'s Skull', NULL, 'Череп Алдера, автора копии \"Откровений Кайши\". Необходимо отнести его Магистру Кайре.', 'The skull of Alders, who drafted the copy of Kaysha\'s Revelations. Take this to Magister Kaira.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3185, 'Alders Skull', NULL, 'Череп Жреца Алдера. Отнесите его Магистру Роа, дальнему потомку жреца.', 'Skull of Priest Alders. Take it to Magister Roa, a distant descendant of the priest.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3186, 'Alder\'s Receipt', NULL, 'Расписка Алдера о том, что он поместил что-то в хранилище. Отправляйтесь на склад в Глудине.', 'The receipt for the item that Alder entrusted to the warehouse. Take this and go to the warehouse in the Village of Gludin.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3187, 'Revelations Manuscript', NULL, 'Копия книги \"Откровения Кайши\". Отнесите ее Магистру Кайре.', 'A copy of Kaysha\'s Revelations. Take this to Magister Kaira.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (3188, 'Kaira\'s Instructions', NULL, 'Приказ Магистра Кайры о том, что Вам необходимо вернуться к ней после получения 38-го уровня.', 'A note where Magister Kaira\'s instructions are written. The instructions are to come back after reaching level 38.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3189, 'Kaira\'s Recommendation', NULL, 'Рекомендация, написанная Магистром Кайрой. Покажите ее Тетрарху Тифиэлю в Деревне Темных Эльфов.', 'A recommendation letter written by Magister Kaira. Take this and go to Tetrarch Thifiell of the Dark Elf Village.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3190, 'Palus Charm', NULL, 'Оберег Тетрарха Тифиэля, данный на время участия в ритуале Шилен.', 'A charm given by Tetrarch Thifiell to keep in possession until the Initiation Ceremony of the Shilien Circle is complete.', 'accessary_onyxbeastseye_earing_i00', 0);
INSERT INTO `all_items` VALUES (3191, 'Thifiell\'s Letter', NULL, 'Письмо от Тетрарха Тифиэля к Аркении, которая находится возле Церемониального Алтаря Темных Эльфов.', 'A letter from Tetrarch Thifiell to Arkenia. Arkenia is at the Dark Elven Initiation Altar.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3192, 'Arkenia\'s Note', NULL, 'Записка Аркении о том, что ей нужны Пыль Кровавой Феи и Сок Древня.', 'A note written by Arkenia. It contains instructions to bring back red fairy dust and blight treant sap.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3193, 'Pixy Garnet', NULL, 'Гранат, данный Кровавой Феей в знак ее обещания. Принесите ей по черепу представителя каждого из 4 племен (Грандисы, Людоеды Карул, Орки Брека, Ящеры Лито).', 'A garnet given by the bloody pixy as a mark of promise. Bring back 10 skulls each from four different races.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3194, 'Grandis\' Skull', NULL, 'Череп Грандиса. Отнесите его Кровавой Фее.', 'The skull of a Grandis. Collect ten of these and take them back to the bloody pixy.', 'etc_ashes_red_i00', 0);
INSERT INTO `all_items` VALUES (3195, 'Karul Bugbear Skull', NULL, 'Череп Людоеда Карул. Отнесите его Кровавой Фее.', 'The skull of a Karul Bugbear. Collect 10 of these and take them back to the bloody pixy.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3196, 'Breka Overlord Skull', NULL, 'Череп Владыки Брека. Отнесите его Кровавой Фее.', 'Skull of a Breka orc overlord. Collect 10 of them and take them to Bloody Pixy.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3197, 'Leto Overlord Skull', NULL, 'Череп Владыки Лито. Отнесите его Кровавой Фее.', 'The skull of a Leto lizardman chief. Collect 10 of these and take them back to the bloody pixy.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3198, 'Red Fairy Dust', NULL, 'Пыль, полученная от Кровавой Феи. Отнесите ее Аркении.', 'Red fairy dust given by the bloody pixy. Take this to Arkenia.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (3199, 'Blight Treant Seed', NULL, 'Семя Тлетворного Древня, данное в знак обещания. Убейте Черную Иву Наблюдателя и возвращайтесь назад.', 'A seed given by a blight treant as a mark of promise. Slay the black willow lurker and bring back its leaf.', 'etc_fruit_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3200, 'Black Willow Leaf', NULL, 'Лист Черной Ивы Наблюдателя. Отнесите его Аркении.', 'A leaf obtained by slaying the black willow lurker. Take this to the Blight Treant.', 'etc_leaf_gold_i00', 0);
INSERT INTO `all_items` VALUES (3201, 'Blight Treant Sap', NULL, 'Сок Тлетворного Древня. Отнесите его Аркении.', 'The sap of a blight treant. Take this to Arkenia.', 'etc_reagent_gold_i00', 0);
INSERT INTO `all_items` VALUES (3202, 'Arkenia\'s Letter', NULL, 'Письмо Аркении о том, что ритуал Шилен завершен. Покажите его Тетрарху Тифиэлю.', 'A letter written by Arkenia. It states that the Initiation Ceremony of the Shilien Circle is complete. Take this to Tetrarch Thifiell.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3203, 'Mark of Glory', NULL, 'Знак прошедшего Испытание славы. Предмет для смены профессии.', 'A mark given to those who have passed the Testimony of Glory. An item for occupational change.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (3204, 'Vokian\'s Order', NULL, 'Приказ принести 10 Осколков Манашен, 10 Когтей Тирана и 10 Клыков Василиска Стражника.', 'Collect and return with 10 manashen shards, 10 tyrant talons and 10 guardian basilisk fangs.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3205, 'Manashen Shard', NULL, 'Осколок Манашен Горгульи. Соберите 10 таких и отнесите их Префекту Вокиану.', 'A shard of the broken manashen. Collect 10 and take them back to Prefect Vokian.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (3206, 'Tyrant Talon', NULL, 'Коготь убитого Тирана. Соберите 10 таких и отнесите их Префекту Вокиану.', 'The talons plucked from a slain Tyrant. Collect 10 and take them back to Prefect Vokian.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (3207, 'Guardian Basilisk Fang', NULL, 'Клык убитого Василиска Стражника. Соберите 10 таких и отнесите их Префекту Вокиану.', 'The fangs of a slain guardian basilisk. Collect 10 and take them back to Prefect Vokian.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3208, 'Vokian\'s Order', NULL, 'Приказ Вокиана о том, что необходимо найти Главу Ганди Чианту в Дионе.', 'Prefect Vokian\'s orders. The instructions are to go and seek out the Gandi Chief Chianta in the Town of Dion.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3209, 'Necklace of Authority', NULL, 'Символ представителя Лорда Пламени Кекеи.', 'A symbol given to those representing Pa\'agrio Lord Kakai.', 'accessary_necklace_of_binding_i00', 0);
INSERT INTO `all_items` VALUES (3210, 'Chianta\'s 1st Order', NULL, 'Приказ от Главы Ганди Чианты. Требуется добыть 5 Скипетров Огня у главарей низших племен орков.', 'Orders of Gandi Chief Chianta. The instructions are to go and recover the flame scepter from the lower orc tribes.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3211, 'Scepter of Breka', NULL, 'Скипетр Огня, отобранный у Главаря Орков Брека. Соберите 5 Скипетров Огня у низших племен орков и отнесите их Главе Ганди Чианте.', 'Scepter of flame which can be obtained from a Breka orc chief. Take it along with 4 other tribes\' scepters and go see Gandi Chief Chianta.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3212, 'Scepter of Enku', NULL, 'Скипетр Огня, отобранный у Главаря Орков Энку. Соберите 5 Скипетров Огня у низших племен орков и отнесите их Главе Ганди Чианте.', 'The flame scepter received from the Enku orc chief. Take this, along with the remaining 4 scepters, to Gandi Chief Chianta.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3213, 'Scepter of Vuku', NULL, 'Скипетр Огня, отобранный у Главаря Орков Вуку. Соберите 5 Скипетров Огня у низших племен орков и отнесите их Главе Ганди Чианте.', 'The flame scepter received from the Vuku orc chief. Take this, along with the remaining 4 scepters, to Gandi Chief Chianta.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3214, 'Scepter of Turek', NULL, 'Скипетр Огня, отобранный у Главаря Орков Турек. Соберите 5 Скипетров Огня у низших племен орков и отнесите их Главе Ганди Чианте.', 'The flame scepter received from the Turek orc chief. Take this, along with the remaining 4 scepters, to Gandi Chief Chianta.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3215, 'Scepter of Tunath', NULL, 'Скипетр Огня, отобранный у Главаря Орков Тунат. Соберите 5 Скипетров Огня у низших племен орков и отнесите их Главе Ганди Чианте.', 'The flame scepter received from the Lennunt orc chief. Take this, along with the remaining 4 scepters, to Gandi Chief Chianta.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3216, 'Chianta\'s 2nd Order', NULL, 'Записка от Главы Ганди Чианты о том, что Вы должны вернуться к нему после получения 38-го уровня.', 'Gandi Chief Chianta\'s orders. The instructions are to come back for further orders after reaching level 38.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3217, 'Chianta\'s 3rd Order', NULL, 'Приказ Главы Ганди Чианты о том, что Вам необходимо принести ему по 20 голов орков Тимак и Тамлин.', 'Gandi Chief Chianta\'s orders. The instructions are to bring back 20 each of Timak and Tamlin orc heads.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3218, 'Tamlin Orc Skull', NULL, 'Отрубленная голова Орка Тамлин. Соберите 20 таких и отнесите Главе Ганди Чианте.', 'The head of a Tamlin orc cut off after being slain. Collect 20 of these and take them to Gandi Chief Chianta.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3219, 'Timak Orc Head', NULL, 'Отрубленная голова Орка Тимак. Соберите 20 таких и отнесите Главе Ганди Чианте.', 'The head of a Timak orc, cut off after being slain. Collect 20 of these and take them to Gandi Chief Chianta.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3220, 'Scepter Box', NULL, 'Ящик с 5 Скипетрами Огня. Отнесите его в Деревню Орков и передайте Провидцу Танапи.', 'A box containing the 5 flame scepters recovered from the lesser orc tribes. Take this to Seer Tanapi of the Orc Village.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3221, 'Pashika\'s Head', NULL, 'Голова Пашики, сына Волтара. Отнесите ее Волтару, Главарю Орков Брека.', 'Kill Pashika, son of Voltar, cut his head off and show it to Breka Chief Voltar.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3222, 'Vultus\' Head', NULL, 'Голова Вултуса, сына Волтара. Отнесите ее Волтару, Главарю Орков Брека.', 'Kill Vultus, son of Voltar, cut his head off and show it to Breka Chief Voltar.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3223, 'Glove of Voltar', NULL, 'Перчатка, брошенная Главарем Орков Брека Волтаром. Убейте Пашику и Вултуса - сыновей Волтара.', 'Glove that was thrown out by Breka Chief Voltar. Slay Pashika and Vultus, sons of Voltar.', 'armor_short_leather_gloves_i00', 0);
INSERT INTO `all_items` VALUES (3224, 'Enku Overlord Head', NULL, 'Отрубленная голова Владыки Орков Энку. Покажите ее Главарю Орков Энку Кепре.', 'The head of an Enku overlord, cut off after being slain. Show this to Enku Chief Kepra.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3225, 'Glove of Kepra', NULL, 'Перчатка, брошенная Главарем Орков Энку Кепрой. Убейте Владыку Орков Энку.', 'The glove thrown down by Enku Chief Kepra. Go and slay the Enku overlords.', 'armor_short_leather_gloves_i00', 0);
INSERT INTO `all_items` VALUES (3226, 'Makum Bugbear Head', NULL, 'Голова убитого Людоеда Макум. Отнесите ее Главарю Орков Турек Бураю.', 'The head of a Makum bugbear warrior, cut off after being slain. Show this to Turek Chief Burai.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3227, 'Glove of Burai', NULL, 'Перчатка, брошенная Главарем Орков Турек Бураем. Убейте Людоедов Макум.', 'The glove thrown down by Turek Chief Burai. Go and slay the Makum bugbear warriors.', 'armor_short_leather_gloves_i00', 0);
INSERT INTO `all_items` VALUES (3228, 'Manakia\'s 1st Letter', NULL, 'Письмо Провидца Манакии. Отнесите его Главарю Орков Брека.', 'Letter of Seer Manakia. Take it to Breka orc chief.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (3229, 'Manakia\'s 2nd Letter', NULL, 'Письмо Провидца Манакии. Отнесите его Главарю Орков Энку.', 'Seer Manakia\'s letter. Take this and go to the Enku Orc Chief.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (3230, 'Kasman\'s 1st Letter', NULL, 'Письмо Префекта Касмана. Отнесите его вождю Орков Вуку.', 'Prefect Kasman\'s letter. Take this and go to the Vuku Orc Chief.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3231, 'Kasman\'s 2nd Letter', NULL, 'Письмо Префекта Касмана. Отнесите его вождю Орков Турек.', 'Prefect Kasman\'s letter. Take this and go to the Turek Orc Chief.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3232, 'Kasman\'s 3rd Letter', NULL, 'Письмо Префекта Касмана. Отнесите его вождю Орков Тунат.', 'Prefect Kasman\'s letter. Take this and go to the Lennunt Orc Chief.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3233, 'Driko\'s Contract', NULL, 'Контракт Дрико, Главаря Орков Вуку. Охотьтесь на Трутней Болотных Стакато в Топях Крумы.', 'Vuku Chief Driko\'s contract. The contract contains instructions to hunt the marsh stakato drones in the Cruma Marshlands.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3234, 'Stakato Drone Husk', NULL, 'Скорлупа Трутней Болотных Стакато. Соберите 30 таких и отнесите Главарю Орков Вуку Дрико.', 'The husks of a marsh stakato drone. Collect 30 of these and take them to Vuku Chief Driko.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3235, 'Tanapi\'s Order', NULL, 'Приказ Провидца Танапи о том, что Вы должны охотиться на Орков Тунат.', 'Seer Tanapi\'s orders. Hunt the Lennunt Orc Chief and seers and recover the dcepter of Tantos.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3236, 'Scepter of Tantos', NULL, 'Скипетр Огня погибшего племени Тантос. Отнесите его Провидцу Танапи.', 'The flame scepter of the now-perished Tantos tribe. Take this to Seer Tanapi.', 'weapon_buzdygan_i01', 0);
INSERT INTO `all_items` VALUES (3237, 'Ritual Box', NULL, 'Ящик со скипетрами, полученными от орков племени Тантос. Передайте его Лорду Пламени Кекеи.', 'A box containing the scepters recovered from the Orcs of the Tantos tribe. Take this to Pa\'agrio Lord Kakai.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3238, 'Mark of Prosperity', NULL, 'Знак прошедшего Испытание успеха. Предмет, необходимый для смены профессии.', 'A mark given to those who have passed the Testimony of Prosperity. An occupation change related item.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (3239, '1st Ring of Testimony', NULL, 'Кольцо Гнома, проходящего Испытание успеха. Найдите 4 доказательства успеха.', 'A ring given to those Dwarves attempting the Testimony of Prosperity. Find the 4 proofs of prosperity.', 'accessary_ring_of_assistance_i00', 0);
INSERT INTO `all_items` VALUES (3240, '2nd Ring of Testimony', NULL, 'Кольцо Гнома, проходящего Испытание успеха. Найдите Скрижали Мафр, хранящие давно забытые секреты.', 'A ring given to those Dwarves attempting the Testimony of Prosperity. Find Maphr\'s tablet, which contains the ultimate secrets of geometry.', 'accessary_aquastone_ring_i00', 0);
INSERT INTO `all_items` VALUES (3241, 'Old Account Book', NULL, 'Старая счетная книга Локрина, главы Гильдии Железных Врат. Может послужить доказательством богатства. Отнесите ее Смотрителю Склада Парману в Гиран.', 'Iron Gate Lockirin\'s account book. The proof of wealth. Take this to Warehouse Keeper Parman of Giran Castle Town.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (3242, 'Blessed Seed', NULL, 'Благословенное семя, символ плодородия. Отнесите его Смотрителю Склада Парману в Гиран.', 'A seed containing the blessings of Maphr. The proof of fertile lands. Take this to Warehouse Keeper Parman of Giran Castle Town.', 'etc_fruit_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3243, 'Emily\'s Recipe', NULL, 'Прекрасный рецепт, символ изобилия. Отнесите его Смотрителю Склада Парману в Гиран.', 'A recipe good for childbirth and childbirth recovery. The proof of fertility. Take this to Warehouse Keeper Parman of Giran Castle Town.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3244, 'Lilith\'s Elven Wafer', NULL, 'Еда, благодаря которой Эльфы живут так долго. Может послужить доказательством здоровья. Отнесите его Смотрителю Склада Парману в Гиран.', 'Food regarded as the secret to the Elves\' longevity. The proof of health. Take this to Warehouse Keeper Parman of Giran Castle Town.', 'etc_lump_white_i00', 0);
INSERT INTO `all_items` VALUES (3245, 'Maphr Tablet Fragment', NULL, 'Часть Скрижалей Марф, хранящих древние тайны геометрии. Передайте это Смотрителю Склада Парману в Гиране.', 'A fragment of Maphr\'s tablet, which contains the ultimate secrets of geometry. Take this to Warehouse Keeper Parman of Giran Castle Town.', 'etc_plate_blue_i00', 0);
INSERT INTO `all_items` VALUES (3246, 'Collection License', NULL, 'Лицензия, позволяющая своему обладателю собирать взносы для гильдий. Поищите тех, кто не сдал их, и соберите недостающие.', 'A license that allows the bearer to collect guild contributions. Seek out those who still owe contributions and collect the funds from them.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3247, 'Lockirin\'s 1st Notice', NULL, 'Записка о сделанных взносах. Передайте ее Спирону из Гильдии Золотого Колеса.', 'A notice that guild contributions are due. Take this to Golden Wheel\'s Spiron.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3248, 'Lockirin\'s 2nd Notice', NULL, 'Записка о сделанных взносах. Передайте ее Баланки из Гильдии Серебряных Весов.', 'A notice that guild contributions are due. Take this to Silver Scale\'s Balanki.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3249, 'Lockirin\'s 3rd Notice', NULL, 'Записка о сделанных взносах. Передайте ее Кифу из Гильдии Бронзового Ключа.', 'A notice that guild contributions are due. Take this to Bronze Key\'s Keef.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3250, 'Lockirin\'s 4th Notice', NULL, 'Записка о сделанных взносах. Передайте ее Филару из Гильдии Серой Колонны.', 'A notice that guild contributions are due. Take this to Filaur of the Gray Pillar.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3251, 'Lockirin\'s 5th Notice', NULL, 'Записка о сделанных взносах. Передайте ее Арину из Гильдии Черной Наковальни.', 'A notice that guild contributions are due. Take this to Black Anvil\'s Arin.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (3252, 'Contribution of Shari', NULL, 'Взнос Торговца Шари. Отнесите его Спирону из Гильдии Золотого Колеса.', 'Trader Shari\'s guild contribution. Take this to Golden Wheel\'s Spiron.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3253, 'Contribution of Mion', NULL, 'Взнос Торговца Мион. Отнесите его Баланки из Гильдии Серебряных Весов.', 'Trader Mion\'s guild contribution. Take this to Silver Scale\'s Balanki.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3254, 'Contribution of Maryse', NULL, 'Взнос Марис Редбоннет. Отнесите его Баланки из Гильдии Серебряных Весов.', 'Maryse Redbonnet\'s guild contribution. Take this to Silver Scale\'s Balanki.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3255, 'Maryse\'s Request', NULL, 'Записка с просьбой Марис Редбоннет. Вы должны принести ей 10 Шкур Животных (материал, используемый для создания предметов).', 'The note containing Maryse Redbonnet\'s request. The instructions are to bring back 100 animal skins. Animal skins are a manufacturing ingredient item.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3256, 'Contribution of Toma', NULL, 'Взнос Мастера Томы. Отнесите его Арину из Гильдии Черной Наковальни.', 'Master Toma\'s guild contribution. Take this to Black Anvil\'s Arin.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3257, 'Receipt of Bolter', NULL, 'Квитанция Шахтера Больтера. Отнесите ее Арину из Гильдии Черной Наковальни.', 'Miner Bolter\'s contribution receipt. Take this to Black Anvil\'s Arin to confirm if Miner Bolter has already submitted his contribution.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (3258, '1st Receipt of Contribution', NULL, 'Квитанция, полученная от Спирона из Гильдии Золотого Колеса. Соберите 5 квитанций от разных гильдий и отнесите их Локрину из Гильдии Железных Врат.', 'The contribution receipt received from Golden Wheel\'s Spiron. Collect 5 receipts and take them to Lockrin of the Iron Gate.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3259, '2nd Receipt of Contribution', NULL, 'Квитанция, полученная от Баланки из Гильдии Серебряных Весов. Соберите 5 квитанций от разных гильдий и отнесите их Локрину из Гильдии Железных Врат.', 'The contribution receipt received from Silver Scale\'s Balanki. Collect 5 receipts and take them to Lockrin of the Iron Gate.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3260, '3rd Receipt of Contribution', NULL, 'Квитанция, полученная от Кифа из Гильдии Бронзового Ключа. Соберите 5 квитанций от разных гильдий и отнесите их Локрину из Гильдии Железных Врат.', 'The contribution receipt received from Bronze Key\'s Keef. Collect 5 receipts and take them to Lockrin of the Iron Gate.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3261, '4th Receipt of Contribution', NULL, 'Квитанция, полученная от Филара из Гильдии Серой Колонны. Соберите 5 квитанций от разных гильдий и отнесите их Локрину из Гильдии Железных Врат.', 'A contribution receipt received from Filaur of the Gray Pillar. Collect 5 receipts and take them to Lockrin of the Iron Gate.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3262, '5th Receipt of Contribution', NULL, 'Квитанция, полученная от Арина из Гильдии Черной Наковальни. Соберите 5 квитанций от разных гильдий и отнесите их Локрину из Гильдии Железных Врат.', 'The contribution receipt received from Black Anvil\'s Arin. Collect 5 receipts and take them to Lockrin of the Iron Gate.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3263, 'Procuration of Torocco', NULL, 'Доверенность, обладатель которой может делать взносы от имени Торокко. Отнесите это Кифу, старейшине Гильдии Бронзового Ключа.', 'The bearer of this procuration hereby agrees to make contributions on behalf of Torocco. Take this to Bronze Key\'s Keef.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3264, 'Bright\'s List', NULL, 'Список компонентов, необходимых Стражу Брайту: 20 Лепестков Мандрагоры, 10 связок Красного Мха.', 'A list of ingredients that Guard Bright has written. \"20 mandragora petals, 10 bunches of crimson moss\"', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3265, 'Mandragora Petal', NULL, 'Лепесток цветка мандрагоры. Соберите 20 таких и отнесите Стражу Брайту.', 'The petals of a mandragora flower. Collect 20 of these and take them to Guard Bright.', 'etc_herb_red_i00', 0);
INSERT INTO `all_items` VALUES (3266, 'Crimson Moss', NULL, 'Темно-красный мох, полученный из гигантских муравьев. Соберите 10 его связок и отнесите Стражу Брайту.', 'Crimson Moss obtained from giant red ants. Collect 10 of these and take them to Guard Bright.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (3267, 'Mandragora Bouquet', NULL, 'Букет, собранный из Лепестков Мандрагоры и Красного Мха. Отнесите его Эмили в Дион.', 'A flower bouquet made of mandragora petals and crimson moss. Take this to Emily in the Town of Dion.', 'etc_branch_gold_i00', 0);
INSERT INTO `all_items` VALUES (3268, 'Parman\'s Instructions', NULL, 'Записка Рабочего Склада Пармана, согласно которой Вы должны вернуться к нему после получения 38-го уровня.', 'A note containing Warehouse Keeper Parman\'s instructions. The instructions are to come back after reaching level 38.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3269, 'Parman\'s Letter', NULL, 'Письмо Рабочего Склада Пармана. Отнесите его Мастеру Николя к Башне Крумы.', 'Warehouse Keeper Parman\'s letter. Take this to Maestro Nikola of the Cruma Tower.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3270, 'Clay Dough', NULL, 'Глина, которую Вам дал Мастер Николя. Используйте ее, чтобы сделать слепок замочной скважины Ящика Гигантов.', 'A piece of clay that Maestro Nikola has given. Use this to make a copy of the keyhole from the titan\'s box.', 'etc_powder_black_i00', 0);
INSERT INTO `all_items` VALUES (3271, 'Pattern of Keyhole', NULL, 'Глиняный слепок замочной скважины. Отнесите его Мастеру Николя.', 'The keyhole pattern made from clay dough. Take this to Maestro Nikola.', 'etc_plate_black_i00', 0);
INSERT INTO `all_items` VALUES (3272, 'Nikola\'s List', NULL, '20 Панцирей Стакато, 10 Желез Повелителя Жаб, 10 Шипов Паука и 10 Кристаллов: Ранг D.', '20 stakato shells, 10 toad lord sacs, 10 spider thorns and 10 D-grade crystals.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3273, 'Stakato Shell', NULL, 'Панцирь Болотного Стакато. Материал, используемый для создания Ключа Гигантов.', 'The shell of a marsh stakato. A key ingredient in making the titan\'s key.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3274, 'Toad Lord Sac', NULL, 'Ядовитая железа из шеи Повелителя Жаб. Материал, используемый для создания Ключа Гигантов.', 'The poison sac removed from the neck of a toad lord. A key ingredient in making the titan\'s key.', 'etc_poison_pouch_i00', 0);
INSERT INTO `all_items` VALUES (3275, 'Marsh Spider\'s Thorn', NULL, 'Шип, срезанный с тела Болотного Паука. Материал, используемый для создания Ключа Гигантов.', 'A thorn removed from the shell of a swamp spider. A key ingredient in making the titan\'s key.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3276, 'Mark of Champion', NULL, 'Знак прошедшего Испытание мастерства. Необходим для смены профессии.', 'A mark given to those who have passed the Test of the Champion. An item for occupational change.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (3277, 'Ascalon\'s 1st Letter', NULL, 'Письмо Ветерана Аскалона. Отдайте его Мэйсону из Диона.', 'Veteran Ascalon\'s letter. Take this to Mason in the Town of Dion.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3278, 'Mason\'s Letter', NULL, 'Письмо Мэйсона, адресованное Аскалону, ветерану из Гирана.', 'A letter from Mason to Veteran Ascalon of Giran Castle Town.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3279, 'Iron Rose Ring', NULL, 'Кольцо Мэйсона. На нем выгравировано изображение железной розы. Вам необходимо отомстить за Мэйсона.', 'A ring given by Mason. The ring is engraved with the symbol of the iron rose. Complete the revenge in place of Mason.', 'accessary_magic_ring_i00', 0);
INSERT INTO `all_items` VALUES (3280, 'Ascalon\'s 2nd Letter', NULL, 'Письмо Ветерана Аскалона. Отдайте его торговцу Груту из Гирана.', 'Veteran Ascalon\'s letter. Take this to Trader Groot of Giran Castle Town.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3281, 'White Rose Insignia', NULL, 'Знак отличия, данный Торговцем Грутом. Его прежде носили целители из Ордена Железной Розы. Помогите Торговцу Груту собрать все необходимые материалы.', 'An insignia given by Trader Groot. It was formerly worn by the medics of the iron rose. Aid Trader Groot in his material gathering.', 'shield_knight_shield_i01', 0);
INSERT INTO `all_items` VALUES (3282, 'Groot\'s Letter', NULL, 'Письмо Торговца Грута Ветерану Аскалону из Гирана.', 'A letter from Trader Groot to Veteran Ascalon in Giran Castle Town.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3283, 'Ascalon\'s 3rd Letter', NULL, 'Письмо Ветерана Аскалона. Отнесите его в Орен Капитану Моену.', 'Veteran Ascalon\'s letter. Take this to Captain Mouen of the Town of Oren.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3284, 'Mouen\'s 1st Order', NULL, 'Приказ о том, что Вам необходимо собрать 10 голов Придорожных Падальщиков или Дорожных Сборщиков.', 'Cut off and bring back the heads of 100 road scavengers or road collectors.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3285, 'Mouen\'s 2nd Order', NULL, 'Приказ о том, что Вам необходимо собрать 10 клыков Ящеров Лито.', 'Destroy the Leto lizardmen and bring back 100 of their fangs.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3286, 'Mouen\'s Letter', NULL, 'Письмо от Капитана Моэна Ветерану Аскалону в Гиран.', 'A letter from Captain Mouen to Veteran Ascalon of Giran Castle Town.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3287, 'Harpy\'s Egg', NULL, 'Яйцо, полученное после убийства Гарпии. Соберите 30 таких и отдайте Торговцу Груту из Гирана.', 'An egg obtained after slaying a harpy. Collect 30 of these and take them to Trader Groot of Giran Castle Town.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (3288, 'Medusa\'s Venom', NULL, 'Яд, полученный после убийства Медузы. Соберите 30 пузырьков с ним и отдайте Торговцу Груту из Гирана.', 'The venom obtained after slaying a medusa. Collect 30 of these and take them to Trader Groot of Giran Castle Town.', 'etc_reagent_green_i00', 0);
INSERT INTO `all_items` VALUES (3289, 'Windsus Bile', NULL, 'Желчь, полученная после убийства Вепря. Соберите 30 пузырьков с ней и отдайте Торговцу Груту из Гирана.', 'The bile obtained after slaying a windsus. Collect 30 of these and take them to Trader Groot of Giran Castle Town.', 'etc_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (3290, 'Bloody Axe Head', NULL, 'Голова Кровавого Топора. Соберите 10 таких и отнесите их Мэйсону в Дион.', 'The head of a Bloody Axe Elite. Collect 100 of these and return to Mason in the Town of Dion.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3291, 'Road Ratman Head', NULL, 'Отрубленная голова Придорожного Падальщика или Дорожного Сборщика. Соберите 10 таких и отдайте Капитану Моэну.', 'The severed head of a road scavenger or road collector. Collect 100 of them and take them to Captain Mouen.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3292, 'Leto Lizardman Fang', NULL, 'Клык убитого Ящера Лито. Соберите 10 таких и отдайте Капитану Моэну.', 'The fangs of a slain Leto lizardman. Collect 100 of these and take them to Captain Mouen.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (3293, 'Mark of Sagittarius', NULL, 'Знак, вручаемый тем, кто прошел Испытание меткости. Необходим для смены профессии.', 'A mark given to those who have passed the Test of the Sagittarius. An occupation change related item.', 'weapon_wooden_arrow_i01', 0);
INSERT INTO `all_items` VALUES (3294, 'Bernard\'s Introduction', NULL, 'Письмо для Снайпера Хамиля из Флорана.', 'Take this letter and go to Sagittarius Hamil of the Village of Floran.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3295, 'Hamil\'s 1st Letter', NULL, 'Письмо Снайпера Хамиля, адресованное сэру Арону Танфорду в южной части Пустоши.', 'Take this letter and meet with Sir Aron Tanford of the Southern Wastelands.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3296, 'Hamil\'s 2nd Letter', NULL, 'Письмо Снайпера Хамиля, адресованное Префекту Вокиану из Гирана.', 'Take this letter and go to Prefect Vokian of Giran Castle Town.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3297, 'Hamil\'s 3rd Letter', NULL, 'Письмо Снайпера Хамиля, адресованное Магистру Гейну из Башни Слоновой Кости.', 'Take this letter and go to Gauen of the Ivory Tower.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3298, 'Hunter\'s 1st Rune', NULL, 'Камень с выгравированной на нем руной охотника. Соберите 10 таких и отнесите Хамилю в Флоран.', 'A stone engraved with a hunter\'s rune. Collect 10 of these and take them to Hamil of the Village of Floran.', 'etc_mold_i00', 0);
INSERT INTO `all_items` VALUES (3299, 'Hunter\'s 2nd Rune', NULL, 'Руна, полученная при убийстве Орка Брека. Соберите 10 таких и отнесите Префекту Вокиану вместе со Змеиным Талисманом.', 'A rune obtained from Breka orc overlords or Shamans. Collect 10 of these and take them, along with the snake talisman, to Prefect Vokian.', 'etc_mold_i00', 0);
INSERT INTO `all_items` VALUES (3300, 'Talisman of Kadesh', NULL, 'Странный талисман, полученный после убийства Кадеша. Отнесите его к Снайперу Хамилю в Флоран.', 'A strange talisman obtained after slaying Kadesh. Take this to Sagittarius Hamil of the Village of Floran.', 'accessary_red_cresent_earing_i00', 0);
INSERT INTO `all_items` VALUES (3301, 'Talisman of Snake', NULL, 'Талисман, связанный с духом тотема змеи, которому поклоняются Орки Брека. Отнесите его Префекту Вокиану в Гиран.', 'Talisman that is related to a serpent totem spirit worshipped by Breka orcs. Take it to Prefect Vokian of Giran Castle Town.', 'accessary_dragon_necklace_i00', 0);
INSERT INTO `all_items` VALUES (3302, 'Mithril Clip', NULL, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'A key ingredient in restoring the Crescent Bow. Take this, along with the rest of the ingredients, to Magister Gauen of the Ivory Tower.', 'accessary_ring_of_knowledge_i00', 0);
INSERT INTO `all_items` VALUES (3303, 'Stakato Chitin', NULL, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'A key ingredient in restoring the Crescent Bow. Take this, along with the rest of the ingredients, to Magister Gauen of the Ivory Tower.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3304, 'Reinforced Bowstring', NULL, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'A key ingredient in restoring the Crescent Bow. Take this, along with the rest of the ingredients, to Magister Gauen of the Ivory Tower.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (3305, 'Manashen\'s Horn', NULL, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'A key ingredient in restoring the Crescent Bow. Take this, along with the rest of the ingredients, to Magister Gauen of the Ivory Tower.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3306, 'Blood of Lizardman', NULL, 'Кровь, пролитая Ящером Лито. Когда соберете достаточное ее количество, появится Кадеш.', 'The blood shed by Leto Lizardmen. Kadesh appears when enough of this is gathered.', 'etc_reagent_green_i00', 0);
INSERT INTO `all_items` VALUES (3307, 'Mark of Witchcraft', NULL, 'Знак, вручаемый тем, кто прошел Испытание колдуна. Необходим для смены профессии.', 'A mark given to those who have passed the Test of Witchcraft. An occupation change related item.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3308, 'Orim\'s Diagram', NULL, 'Схема реликвий, которую дал Вам Орим Тень. Здесь изображены 6 драгоценных камней, необходимых для открытия Куба Аклантота.', 'A diagram of relics, given by Orim of the Shadow. The 6 jewels needed for opening the Cube of Aklantoth are depicted here.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (3309, 'Alexandria\'s Book', NULL, 'Книга, которая содержит записи о том, кто купил Камни Аклантота: Магистр Айкер, Магистр Кайра, Торговец Лара.', 'A book that contains records on who purchased Aklantoth\'s Gems. \"Magister Iker, Magister Kaira, Trader Lara\"', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (3310, 'Iker\'s List', NULL, 'Список материалов, необходимых Магистру Айкеру: 20 клыков Жуткого Змея, 20 Оберегов Ящеров Лито и 20 Сердец Зачарованного Голема.', 'Collect and bring back 20 dire wyrm fangs, 20 Leto lizardman charms, and 20 enchanted stone golem heartstones.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3311, 'Dire Wyrm Fang', NULL, 'Клык Жуткого Змея. Соберите 20 таких и отнесите Магистру Айкеру.', 'The fangs of a slain Dire Wyrm. Collect 20 of these and take them to Magister Iker.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (3312, 'Leto Lizardman Charm', NULL, 'Оберег, полученный при убийстве Ящера Лито. Соберите 20 таких и отнесите Магистру Айкеру.', 'A totem obtained after slaying the Leto Lizardman. Collect 20 of these and take them to Magister Iker.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (3313, 'Enchanted Stone Golem Heartstone', NULL, 'Кристалл, найденный среди останков Зачарованного Каменного Голема. Соберите 20 таких и отнесите магистру Айкеру.', 'A crystal found amongst the shattered fragments of an enchanted stone golem. Collect 20 of these and take them to Magister Iker.', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (3314, 'Lara\'s Memo', NULL, 'Отчет о продажах Торговца Лары. Здесь написано, что Камень Аклантота был куплен человеком по имени Исмел.', 'Trader Lara\'s sales records. It is recorded that a man named Ismel bought the jewel from Lara.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3315, 'Nestle\'s Memo', NULL, 'Отчет о покупках Торговца Лары. Здесь написано, что Камень Аклантота был принесен Леопольдом из отряда Черного Льва.', 'Trader Lara\'s purchase records. It is recorded that Leopold of the Black Lion brought the jewel.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3316, 'Leopold\'s Journal', NULL, 'Отрывок из дневника Леопольда. Здесь написано о 3 дезертирах, погибших в Пустоши и превратившихся в нежить.', 'A portion of Leopold\'s Diary. It is recorded that 3 deserters died and became undead while escaping to the Wastelands.', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (3317, 'Aklantoth 1st Gem', NULL, 'Драгоценный камень, полученный от Магистра Айкера. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'Gem that can be obtained from Magister Iker. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (3318, 'Aklantoth 2nd Gem', NULL, 'Драгоценный камень, полученный от Магистра Кайры. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'The gem given by Magister Kaira. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (3319, 'Aklantoth 3rd Gem', NULL, 'Драгоценный камень, полученный при убийстве Безымянного Призрака. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'The gem that can be obtained by killing a nameless revenant. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_bead_green_i00', 0);
INSERT INTO `all_items` VALUES (3320, 'Aklantoth 4th Gem', NULL, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'The gem that can be obtained by slaying a skeletal mercenary. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (3321, 'Aklantoth 5th Gem', NULL, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'The gem that can be obtained by slaying a skeletal mercenary. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_bead_blue_i00', 0);
INSERT INTO `all_items` VALUES (3322, 'Aklantoth 6th Gem', NULL, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'The gem that can be obtained by slaying a skeletal mercenary. Find all 6 of Aklantoth gems and take them to Orim the Shadow.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (3323, '1st Brimstone', NULL, 'Знак, оставленный Принцем Дре Ванул Зеруэлем при его побеге.', 'A mark left behind by the Drevanul Prince Zeruel when escaping from his binds.', 'etc_powder_orange_i00', 0);
INSERT INTO `all_items` VALUES (3324, 'Orim\'s Instructions', NULL, 'Приказ Орима Тени. Вы должны найти Меч Оков и Кристалл Ловушку.', 'A set of instructions written by Orim of the Shadow. The instructions are to bring back the Sword of Binding and Soul Trap Crystal.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3325, 'Orim\'s 1st Letter', NULL, 'Письмо Орима Тени сэру Клаусу Васперу в Глудин с просьбой взять на время Меч Оков.', 'A letter from Orim of the Shadow to Sir Karol Vasper of the Town of Gludin. The letter asks for the loan of the Sword of the Seal.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3326, 'Orim\'s 2nd Letter', NULL, 'Письмо Орима Тени Магистру Айкеру в Гиран с просьбой взять на время Кристалл Ловушку.', 'A letter from Orim of the Shadows to Magister Iker of Giran Castle Town. The letter asks for the loan of the Soul-trap Crystal.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3327, 'Sir Vasper\'s Letter', NULL, 'Письмо сэра Клауса Васпера Вадину в Орен, в котором он дает разрешение использовать Меч Оков.', 'A letter from Sir Klaus Vasper to Vadin of the Town of Oren. The letter gives permission for the use of the Sword of Binding.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3328, 'Vadin\'s Crucifix', NULL, 'Святое распятие, данное Вадином. Идите с ним на охоту на Орков Тамлин.', 'A holy crucifix of the order, given by Vadin. Take this and go hunt Tamlin Orcs.', 'accessary_earing_of_wisdom_i00', 0);
INSERT INTO `all_items` VALUES (3329, 'Tamlin Orc Amulet', NULL, 'Амулеты, которые Орки Тамлин используют в своем колдовстве. Соберите 20 таких и отнесите Вадину.', 'Amulets that the Tamlin Orcs carry for sorcery purposes. Gather 20 of these and take them to Vadin.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (3330, 'Vadin\'s Sanctions', NULL, 'Письмо Вадина, разрешающее использовать Меч Оков. Отнесите его сэру Клаусу Васперу в Глудин.', 'A sanctions letter from Vadin allowing for the use of the Sword of Binding. Take this to Sir Klaus Vasper of the Town of Gludin.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3331, 'Iker\'s Amulet', NULL, 'Амулет, данный Магистром Айкером. Говорят, он оберегает от сил зла.', 'An amulet given by Magister Iker. It is said to have powers of protection against evil...', 'accessary_necklace_of_grace_i00', 0);
INSERT INTO `all_items` VALUES (3332, 'Soultrap Crystal', NULL, 'Кристалл, способный заманить в ловушку и запечатать душу монстра. Используйте его, чтобы поймать дух Принца Дре Ванул Зеруэля.', 'A crystal with the power to trap and seal the soul of a monster. Use this to seal the spirit of the Drevanul Zeruel.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3333, 'Purgatory Key', NULL, 'Ключ, которым нужно закрыть сундук Аклантота. Отнесите его Ориму Тени.', 'A key needed to close Aklantoth\'s Chest. Take this to Orim of the Shadow.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (3334, 'Zeruel Bind Crystal', NULL, 'Кристалл, который содержит пойманную в ловушку душу Принца Дре Ванул Зеруэля. Отнесите его Ориму Тени.', 'A crystal that contains the trapped soul of the Drevanul Zeruel. Take this to Orim of the Shadow.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3335, '2nd Brimstone', NULL, 'Знак, оставленный Принцем Дре Ванул Зеруэлем при его побеге из тела Рыбака Эверта.', 'A mark left behind by the Drevanul Prince Zeruel while escaping from the body of Fisher Evert.', 'etc_powder_orange_i00', 0);
INSERT INTO `all_items` VALUES (3336, 'Mark of Summoner', NULL, 'Знак, вручаемый за прохождение Испытания призывателя. Необходим для смены профессии.', 'A mark given to those who have passed the Test of the Summoner. An occupation change related item.', 'weapon_apprentices_rod_i01', 0);
INSERT INTO `all_items` VALUES (3337, 'Leto Lizardman Amulet', NULL, 'Амулет, полученный после убийства Ящера Лито. Соберите 30 таких и отнесите их Торговцу Ларе.', 'An amulet obtained after slaying a Leto Lizardman. Gather 30 of these and take them back to Trader Lara.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (3338, 'Sac of Redspores', NULL, 'Красные споры, полученные из гигантских грибов. Соберите 30 таких и отнесите Торговцу Ларе.', 'Red spores obtained from the bodies of the giant fungus. Gather 30 of these and take them back to Trader Lara.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (3339, 'Karul Bugbear Totem', NULL, 'Тотем, полученный после убийства Людоеда Карул. Соберите 30 таких и отнесите Торговцу Ларе.', 'A totem obtained after slaying the Karul Bugbear. Gather 30 of these and take them back to Trader Lara.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (3340, 'Shards of Manashen', NULL, 'Осколок Манашен Горгульи. Соберите 30 таких и отнесите Торговцу Ларе.', 'A shard of the shattered Manashen. Gather 30 of these and take them back to Trader Lara.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (3341, 'Breka Orc Totem', NULL, 'Тотем, который можно получить после убийства Орка Брека. Соберите 30 таких и отнесите Торговцу Ларе.', 'A totem that can be obtained after slaying a Breka orc. Collect 30 of them and take them to Trader Lara.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (3342, 'Crimson Bloodstone', NULL, 'Камень, вложенный в Пленную Душу. Соберите 30 таких и отнесите Торговцу Ларе.', 'A spirit stone embedded in the body of a fettered soul. Gather 30 of these and take them back to Trader Lara.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3343, 'Talons of Tyrant', NULL, 'Коготь убитого Тирана. Соберите 30 таких и отнесите Торговцу Ларе.', 'The talon of a slain tyrant. Gather 30 of these and take them back to Trader Lara.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (3344, 'Wings of Droneant', NULL, 'Крылья, полученные после убийства Элитного Муравья из Муравейника. Соберите 30 таких и отнесите Торговцу Ларе.', 'Wings obtained after slaying Noble Ants at the Ant\'s Nest. Gather 30 of these and take them back to Trader Lara.', 'etc_feather_black_i00', 0);
INSERT INTO `all_items` VALUES (3345, 'Tusk of Windsus', NULL, 'Клык убитого Вепря. Соберите 30 таких и отнесите их Торговцу Ларе.', 'The tusks of a slain windsus. Gather 30 of these and take them back to Trader Lara.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3346, 'Fangs of Wyrm', NULL, 'Клык убитого Змея. Соберите 30 таких и отнесите Торговцу Ларе.', 'The fangs of a slain wyrm. Gather 30 of these and take them back to Trader Lara.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3347, 'Lara\'s 1st List', NULL, 'Соберите 30 Амулетов Ящеров Лито в Долине Ящеров и 30 Мешочков с Красными Спорами из Гигантских Грибов в Море Спор.', 'Collect 30 Leto lizardman amulets from the Plains of the Lizardmen and 30 units of red spore dust from the giant fungus in the Sea of Spores.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3348, 'Lara\'s 2nd List', NULL, 'Соберите 30 Тотемов Людоедов Карул в Долине Охотников и 30 Осколков Манашен в Кратере Башни Слоновой Кости.', 'Collect 30 Karul bugbear totems from Hunters Valley and 30 shards of manashen from the Crater of the Ivory Tower.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3349, 'Lara\'s 3rd List', NULL, 'Соберите 30 Тотемов Орков Брека в Укреплении Бреки и 30 Камней Крови Пленных Душ в Долине Смерти.', 'Collect 30 Breka orc totems from Breka\'s Stronghold and 30 crimson bloodstones of fettered soul from Death Pass.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3350, 'Lara\'s 4th List', NULL, 'Соберите 30 Когтей Тирана в Пустоши и 30 Клыков Вепря в Долине Смерти.', 'Collect 30 Tyrant Talons from the Wastelands and 30 Windsus Tusks from Death Pass.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3351, 'Lara\'s 5th List', NULL, 'Соберите 30 Крыльев Элитных Муравьев в Муравейнике и 30 Клыков Змеев в Саду Цветов Горгон.', 'Collect 30 noble ant wings from the Ant Nest and 30 wyrm fangs from Gorgon\'s Flower Garden.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3352, 'Galatea\'s Letter', NULL, 'Письмо Великого Призывателя Галатеи для Торговца Лары из Диона.', 'A letter from Head Summoner Galatea to Trader Lara in the Town of Dion.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3353, 'Beginner\'s Arcana', NULL, 'Карточка, используемая учениками призывателей. Нужна, чтобы участвовать в сражениях призывателей.', 'An Arcana card used by apprentice Summoners. You must have this in order to participate in Summoner battles.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (3354, 'Almors\'s Arcana', NULL, 'Карточка Призывателя Алморса. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Almors\'s Arcana. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3355, 'Camoniell\'s Arcana', NULL, 'Карточка Призывателя Камониэль. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Camoniell\'s. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3356, 'Belthus\'s Arcana', NULL, 'Карточка Призывателя Бельтуса. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Belthus\'s Arcana. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3357, 'Basillia\'s Arcana', NULL, 'Карточка Призывателя Базиллы. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Basillia\'s Arcana. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3358, 'Celestiel\'s Arcana', NULL, 'Карточка Призывателя Селестии. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Celestiel\'s Arcana. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3359, 'Brynthea\'s Arcana', NULL, 'Карточка Призывателя Бринтии. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'Summoner Brynthea\'s Arcana. The proof of victory from a battle. Take this to Head Summoner Galatea.', 'shield_dark_dragon_shield_i01', 0);
INSERT INTO `all_items` VALUES (3360, '1st Crystal of Starting', NULL, 'Знак того, что сражение призывателей началось.', 'An indication that a Summoner battle has begun.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3361, '1st Crystal of Inprogress', NULL, 'Знак того, что сражение призывателей в самом разгаре.', 'An indication that a Summoner battle is in progress.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3362, '1st Crystal of Foul', NULL, 'Знак того, что в битве призывателей были нарушены правила. Отнесите это Призывателю Алморсу.', 'An indication that foul play was involved in a Summoner battle. Take this to Summoner Almors.', 'etc_gem_black_i00', 0);
INSERT INTO `all_items` VALUES (3363, '1st Crystal of Defeat', NULL, 'Знак того, что призыватель потерпел поражение. Отнесите это Призывателю Алморсу.', 'An indication that the Summoner has been defeated in battle. Take this to Summoner Almors.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3364, '1st Crystal of Victory', NULL, 'Знак того, что призыватель одержал победу. Отнесите это Призывателю Алморсу.', 'An indication that the Summoner has been victorious in a battle. Take this to Summoner Almors.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (3365, '2nd Crystal of Starting', NULL, 'Знак того, что сражение призывателей началось.', 'An indication that a Summoner battle has begun.', 'etc_gem_blue_i00', 0);
