INSERT INTO `all_items` VALUES (3385, '6th Crystal of Starting', NULL, 'Знак того, что сражение призывателей началось.', 'An indication that a Summoner battle has begun.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3386, '6th Crystal of Inprogress', NULL, 'Знак того, что сражение призывателей в самом разгаре.', 'An indication that a Summoner battle is in progress.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3387, '6th Crystal of Foul', NULL, 'Знак того, что в битве призывателей были нарушены правила. Отнесите это Призывателю Бринтии.', 'An indication that foul play was involved in a Summoner battle. Take this to Summoner Brynthea.', 'etc_gem_black_i00', 0);
INSERT INTO `all_items` VALUES (3388, '6th Crystal of Defeat', NULL, 'Знак того, что призыватель потерпел поражение. Отнесите это Призывателю Бринтии.', 'An indication that the Summoner has been defeated in a Summoner battle. Take this to Summoner Brynthea.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3389, '6th Crystal of Victory', NULL, 'Знак того, что призыватель одержал победу. Отнесите это Призывателю Бринтии.', 'An indication that the Summoner has been victorious in a Summoner battle. Take this to Summoner Brynthea.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (3390, 'Mark of Lord', NULL, 'Знак, вручаемый тем, кто прошел Испытание Верховного Шамана. Необходим для смены профессии.', 'A mark given to those who have passed the Test of the Lord. An item for occupational change.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (3391, 'Ordeal Necklace', NULL, 'Ожерелье, вручаемое тем, кто пытается пройти Испытание Верховного Шамана. Найдите 5 главарей различных племен и получите их одобрение.', 'A necklace given to those who are attempting the Test of the Lord. Go seek 5 Chiefs of different tribes and return with their approvals.', 'accessary_another_worlds_necklace_i00', 0);
INSERT INTO `all_items` VALUES (3392, 'Varkee\'s Charm', NULL, 'Оберег Главы Атубы Варкиса. Возвращайтесь к нему после выполнения приказа.', 'The Atuba chief Varkee\'s charm. Go back to him after completing this task.', 'accessary_earing_of_black_ore_i00', 0);
INSERT INTO `all_items` VALUES (3393, 'Tantus\'s Charm', NULL, 'Оберег Главы Неруги Тантуса. Возвращайтесь к нему после выполнения приказа.', 'The Neruga chief Tantus\'s charm. Go back to him after completing this task.', 'accessary_earing_of_blessing_i00', 0);
INSERT INTO `all_items` VALUES (3394, 'Hatos\'s Charm', NULL, 'Оберег Главы Уруту Хатоса. Возвращайтесь к нему после выполнения приказа.', 'The Urutu Chief Hatos\'s charm. Go back to him after completing this task.', 'accessary_coral_earing_i00', 0);
INSERT INTO `all_items` VALUES (3395, 'Takuna\'s Charm', NULL, 'Оберег Главы Дуда-Мара Такуны. Возвращайтесь к нему после выполнения приказа.', 'The Duda-Mara Chief Takuna\'s charm. Go back to him after completing this task.', 'accessary_another_worlds_earing_i00', 0);
INSERT INTO `all_items` VALUES (3396, 'Chianta\'s Charm', NULL, 'Оберег Главы Ганди Чианты. Возвращайтесь к нему после выполнения приказа.', 'Gandi Chief Chianta\'s charm. Go back to him after completing this task.', 'accessary_cerberuss_earing_i00', 0);
INSERT INTO `all_items` VALUES (3397, 'Manakia\'s Orders', NULL, 'Документ, содержащий указания Провидца Манакии. Вам необходимо охотиться на Шаманов и Владык Орков Брека и собрать у них 20 Клыков Орков Брека.', 'A document containing Seer Manakia\'s orders. It tells you to kill Breka orc shamans and Breka orc overlords and bring back 20 Breka orc fangs.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3398, 'Breka Orc Fang', NULL, 'Клык Орка Брека. Соберите 20 таких и отнесите Провидцу Манакии.', 'A Breka orc\'s fang. Collect 20 of them and take them to Seer Manakia.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (3399, 'Manakia\'s Amulet', NULL, 'Амулет, полученный после прохождения испытания Манакии. Отнесите его Главе Атуба Варкису.', 'A mark received after passing Manakia\'s test. Take this to Atuba Chief Varkees.', 'accessary_paradia_earing_i00', 0);
INSERT INTO `all_items` VALUES (3400, 'Huge Orc Fang', NULL, 'Тотем племени Атуба. Соберите 5 тотемов у 5 племен и отнесите их Лорду Пламени Кекеи.', 'The totem of the Atuba tribe. Gather the totems of the 5 tribes and take them to Pa\'agrio Lord Kakai.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3401, 'Sumari\'s Letter', NULL, 'Письмо Кузнеца Сумари, адресованное Провидцу Сомаку в Дион.', 'A letter from Blacksmith Sumari to Seer Somak in the Town of Dion.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3402, 'Urutu Blade', NULL, 'Клинок, сделанный Кузнецом Сумари. Отнесите его Главе Уруту Хатосу.', 'A blade crafted by Blacksmith Sumari. Take this to Urutu Chief Hatos.', 'etc_sword_body_i00', 0);
INSERT INTO `all_items` VALUES (3403, 'Timak Orc Skull', NULL, 'Череп убитого Орка Тимак. Соберите 10 таких и отнесите их Главе Уруту Хатосу.', 'The skull of a slain Timak Orc. Gather 10 of these and take them to Urutu chief Hatos.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3404, 'Sword Into Skull', NULL, 'Тотем племени Уруту. Соберите 5 тотемов у 5 племен и отнесите их Лорду Пламени Кекеи.', 'The totem of the Urutu tribe. Gather the totems of the 5 tribes and take them to Pa\'agrio Lord Kakai.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3405, 'Neruga Axe Blade', NULL, 'Часть лезвия церемониального топора. Отнесите ее Главе Неруги Тантусу.', 'The blade portion of a ceremonial axe. Take this to Neruga Chief Tantus.', 'weapon_heavy_bone_club_i00', 0);
INSERT INTO `all_items` VALUES (3406, 'Axe of Ceremony', NULL, 'Тотем племени Неруга. Соберите 5 тотемов у 5 племен и отнесите их Лорду Пламени Кекеи.', 'The totem of the Neruga tribe. Gather the totems of the 5 tribes and take them to Pa\'agrio Lord Kakai.', 'weapon_battle_axe_i00', 0);
INSERT INTO `all_items` VALUES (3407, 'Marsh Spider\'s Feeler', NULL, 'Материал, необходимый для изготовления тотема племени Дуда-Мара. Соберите 10 таких и отнесите Главе Дуда-Мара Такуне.', 'A key ingredient in making the Duda-Mara tribe totem. Gather 10 of these and take them to Duda-Mara Chief Takuna.', 'etc_ginseng_gray_i00', 0);
INSERT INTO `all_items` VALUES (3408, 'Marsh Spider\'s Feet', NULL, 'Материал, необходимый для изготовления тотема племени Дуда-Мара. Соберите 10 таких и отнесите Главе Дуда-Мара Такуне.', 'A key ingredient in making the Duda-Mara tribe totem. Gather 10 of these and take them to Duda-Mara Chief Takuna.', 'etc_insect_leg_i00', 0);
INSERT INTO `all_items` VALUES (3409, 'Handiwork Spider Brooch', NULL, 'Тотем племени Дуда-Мара. Соберите 5 тотемов у 5 племен и отнесите их Лорду Пламени Кекеи.', 'The totem of the Duda-Mara tribe. Gather the totems of the 5 tribes and take them to Pa\'agrio Lord Kakai.', 'shield_doom_shield_i01', 0);
INSERT INTO `all_items` VALUES (3410, 'Enchanted Monster Cornea', NULL, 'Основной материал, необходимый для изготовления тотема племени Ганди. Соберите 20 таких и отнесите Главе Ганди Чианте.', 'A key ingredient in making the Gandi tribe totem. Gather 20 of these and take them to Gandi Chief Chianta.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (3411, 'Monster Eye Woodcarving', NULL, 'Тотем племени Ганди. Соберите 5 тотемов у 5 племен и отнесите их Лорду Пламени Кекеи.', 'The totem of the Gandi tribe. Gather the totems of the 5 tribes and take them to Pa\'agrio Lord Kakai.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3412, 'Bear Fang Necklace', NULL, 'Тотем племени Хестуи. Отправляйтесь с ним в Пещеру Испытаний к Прародителю Мартанкусу.', 'The totem of the Hestui tribe. Take this and go to the Ancestor Martankus in the Cave of Trials.', 'accessary_necklace_of_binding_i00', 0);
INSERT INTO `all_items` VALUES (3413, 'Martankus\'s Charm', NULL, 'Талисман Прародителя Мартанкуса. Возвращайтесь к Мартанкусу после завершения задания.', 'The talisman of the Ancestor Martankus. Go back to him after completing this task.', 'accessary_inferno_necklace_i00', 0);
INSERT INTO `all_items` VALUES (3414, 'Ragna Orc Head', NULL, 'Голова убитого Орка Рагна. Отнесите ее Прародителю Мартанкусу.', 'The head of a slain Ragna Orc. Take this to the Ancestor Martankus.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3415, 'Ragna Chief Notice', NULL, '\"Убийца Лорда Пламени, да будет править!\" Отнесите это Прародителю Мартанкусу.', 'He who destroys the Lord of Flame shall be appointed Chief. Take this to the ancestral spirit Martankus.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3416, 'Immortal Flame', NULL, 'Знак, полученный после прохождения испытания Прародителя Мартанкуса. Отнесите его Лорду Пламени Кекеи.', 'The mark received after passing the Ancestor Martankus\' test. Take this to Pa\'agrio Lord Kakai.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (3417, 'Animal Lover\'s List', NULL, 'Найдите Хранителя Портала Беллу в Глудио, Стража Метти в Дионе и ювелира Элли в Гиране.', 'Go and seek Gatekeeper Bella in the Town of Gludio, Guard Metty in the Town of Dion, and Accessory Jeweler Ellie in the Town of Giran.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (3418, 'Animal Slayer\'s 1st List', NULL, 'Список монстров, обитающих на Говорящем Острове: Гигантский Паук, Когтистый Паук, Опасный Паук.', 'Destroy the animal slayers of Talking Island: giant spiders, talon spiders, and bladers.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3419, 'Animal Slayer\'s 2nd List', NULL, 'Список монстров, обитающих в Эльфийском Лесу: Багровый Паук, Цепкий Паук, Паук Хелицера.', 'Destroy the animal slayers of the Elven Forest: crimson spiders, hook spiders, and the pincer spiders.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3420, 'Animal Slayer\'s 3rd List', NULL, 'Список монстров, обитающих в Лесу Темных Эльфов: Младший Темный Ужас, Темный Ужас, Паук Скиталец.', 'Destroy the animal slayers of the Dark Elven Forest: lesser dark horrors, dark horrors, and prowlers.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3421, 'Animal Slayer\'s 4th List', NULL, 'Список монстров, обитающих у Замерзшего Водопада: Паук Кхаши, Клыкастый Паук Кхаши, Опасный Паук Кхаши.', 'Destroy the animal slayers of the Indomitable Plateau: kasha spiders, kasha poker spiders, and kasha blade spiders.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3422, 'Animal Slayer\'s 5th List', NULL, 'Список монстров, обитающих в шахтах Горного Хребта: Тарантул Охотник, Тарантул Грабитель.', 'Destroy the animal slayers of the Spine Mountains Mining Zone: hunter tarantulas and plunder tarantulas.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3423, 'Bloody Fang', NULL, 'Окровавленный клык. Соберите 50 таких и отнесите Мартину, специалисту по питомцам из Глудина.', 'A fang dripping with animal blood. Collect 50 of these and take them to Martin, the Pet Manager of the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3424, 'Bloody Claw', NULL, 'Окровавленный коготь. Соберите 50 таких и отнесите Мартину, специалисту по питомцам из Глудина.', 'A claw dripping with animal blood. Collect 50 of these and take them to Martin, the Pet Manager of the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3425, 'Bloody Nail', NULL, 'Кровавый ноготь. Соберите 50 таких и отнесите Мартину, специалисту по питомцам из Глудина.', 'A nail dripping with animal blood. Collect 50 of these and take them to Martin, the Pet Manager of the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3426, 'Bloody Kasha Fang', NULL, 'Кровавый клык Кхаши. Соберите 50 таких и отнесите Мартину, специалисту по питомцам из Глудина.', 'A fang of a kasha dripping with animal blood. Collect 50 of these and take them to Martin, the Pet Manager of the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3427, 'Bloody Tarantula Nail', NULL, 'Кровавый коготь тарантула. Соберите 50 таких и отнесите Мартину, специалисту по питомцам из Глудина.', 'A nail of a tarantula dripping with animal blood. Collect 50 of these and take them to Martin, the Pet Manager of the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3428, 'Crystal Brooch', NULL, 'Брошь, полученная от Смотрителя Склада Вильфорда. Отнесите ее Лилит, которая находится в храме Деревни Говорящего Острова.', 'A brooch received from Warehouse Keeper Wilfred. Present this to Lilith of the temple at the Village of Talking Island.', 'accessary_elven_necklace_i00', 0);
INSERT INTO `all_items` VALUES (3429, 'Spellbook: Greater Heal', NULL, 'Книга, необходимая для изучения умения \"Великое Лечение\". Профессии: Епископ, Мудрец Евы, Мудрец Шилен.Необходимый уровень: Епископ - 40, Мудрец Евы, Мудрец Шилен - 48.', 'Spellbook needed to learn the Greater Heal spell. Used by Bishops, Elven Elders, and Shillien Elders.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (3430, 'Spellbook: Greater Battle Heal', NULL, 'Книга, необходимая для изучения умения \"Великое Боевое Лечение\". Профессия: Епископ.Необходимый уровень: 40.', 'Amulet required for the Greater Battle Heal spell. Used by Bishops.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (3431, 'Spellbook: Greater Group Heal', NULL, 'Книга, необходимая для изучения умения \"Великое Групповое Лечение\". Профессии: Епископ, Мудрец Евы, Мудрец Шилен.Необходимый уровень: Епископ - 40, Мудрец Евы, Мудрец Шилен - 48.', 'Amulet required for the Greater Group Heal spell. Used by Bishops and Shillien Elders.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (3432, 'Spellbook: Remedy', NULL, 'Книга, необходимая для изучения умения \"Лекарство\". Профессия: Паладин.Необходимый уровень: 40.', 'Amulet required for the Remedy spell. Used by Paladins.', 'etc_spell_books_hfighter_i00', 0);
INSERT INTO `all_items` VALUES (3433, 'Elf Figure', NULL, NULL, NULL, 'etc_figure_FElf_i00', 0);
INSERT INTO `all_items` VALUES (3434, 'Coke', NULL, NULL, NULL, 'etc_coke_i00', 0);
INSERT INTO `all_items` VALUES (3435, 'Nvidia', NULL, NULL, NULL, 'etc_nvidia_i00', 0);
INSERT INTO `all_items` VALUES (3436, 'Mouse', NULL, NULL, NULL, 'etc_mouse_i00', 0);
INSERT INTO `all_items` VALUES (3437, 'Trade Book of Merchant', NULL, NULL, NULL, 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (3438, 'Trade Book of Great Merchant', NULL, NULL, NULL, 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (3439, 'Shining Canine', NULL, 'Снаряжение для волков. Чтобы экипировать его, щелкните на нем два раза левой кнопкой мыши.', 'Double-click to wear.  Only for wolves.', 'etc_pet_arms_i00', 0);
INSERT INTO `all_items` VALUES (3440, 'Cargo Box', NULL, 'Ящик с грузом, на котором стоит метка торговой гильдии Адена.', 'Freight box on which the mark of Aden Commercial Guild is stamped.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3441, 'Cargo Box', NULL, 'Ящик с грузом, на котором стоит метка торговой гильдии Адена.', 'Freight box on which the mark of Aden Commercial Guild is stamped.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3442, 'Cargo Box', NULL, 'Ящик с грузом, на котором стоит метка торговой гильдии Адена.', 'Freight box on which the mark of Aden Commercial Guild is stamped.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3443, 'Cargo Box', NULL, 'Ящик с грузом, на котором стоит метка торговой гильдии Адена.', 'Freight box on which the mark of Aden Commercial Guild is stamped.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3444, 'Gludio Apples', NULL, 'Яблоко, выращенное в окрестностях Глудио. Можно продать в Торговой Лавке.', 'Apple cultivated in the Gludio region. Can be sold at shops.', 'etc_fruit_green_i00', 0);
INSERT INTO `all_items` VALUES (3445, 'Dion Corn Meal', NULL, 'Мука из кукурузы, выращенной в окрестностях Диона. Можно продать в Торговой Лавке.', 'Powder made from corn cultivated in Dion. Can be sold at shops.', 'etc_powder_orange_i00', 0);
INSERT INTO `all_items` VALUES (3446, 'Dire Wolf Pelts', NULL, 'Выделанная шкура Жуткого Волка. Можно продать в Торговой Лавке.', 'Tanned Dire Wolf pelts. Can be sold at shops.', 'etc_crafted_leather_i00', 0);
INSERT INTO `all_items` VALUES (3447, 'Moonstone', NULL, 'Драгоценный камень белого цвета, называемый Камнем Мунджанг или Лунным камнем. Можно продать в Торговой Лавке.', 'Jewel of blue and white light called Moonjang Stone or Moonstone. Can be sold at shops.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3448, 'Gludio Wheat Flour', NULL, 'Мука из пшеницы, выращенной в окрестностях Глудио. Можно продать в Торговой Лавке.', 'Powder made from wheat cultivated in the Gludio region. Can be sold at shops.', 'etc_powder_white_i00', 0);
INSERT INTO `all_items` VALUES (3449, 'Spidersilk Rope', NULL, 'Прочная веревка, сделанная из шелка тарантула. Можно продать в Торговой Лавке.', 'Strong rope made of weaving tarantula spider silk. Can be sold at shops.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (3450, 'Alexandrite', NULL, 'Драгоценный камень, кажущийся зеленым в солнечном свете и красным в лунном. Можно продать в Торговой Лавке.', 'Precious jewel that shines green in the sunlight and red in the moonlight. Can be sold at shops.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (3451, 'Silver Tea Service', NULL, 'Чайная чашка и блюдце из серебра. Можно продать в Торговой Лавке.', 'High-quality teacup and dish set crafted of silver. Can be sold at shops.', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (3452, 'Mechanic Golem Spare Parts', NULL, 'Детали механических големов. Можно продать в Торговой Лавке.', 'A component of mechanic golems. Useless for anything else, it is best sold.', 'etc_instrument_i00', 0);
INSERT INTO `all_items` VALUES (3453, 'Fire Emerald', NULL, 'Драгоценный камень, который сияет интенсивным красным светом. Можно продать в Торговой Лавке.', 'Precious jewel that shines with an intense red light. Can be sold at shops.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (3454, 'Avellan Silk Frock', NULL, 'Высококачественный шелк, привезенный из Авеллы. Можно продать в Торговой Лавке.', 'High-quality silk dress imported from Avellan of the east. Can be sold at shops.', 'etc_piece_of_cloth_red_i00', 0);
INSERT INTO `all_items` VALUES (3455, 'Feriotic Porcelain Urn', NULL, 'Древний ферритовый сосуд, когда-то использовавшийся для ритуалов. Можно продать в Торговой Лавке.', 'As a water cup made for their rituals, it is a relic of the ancient Ferios empire. Can be sold at shops.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (3456, 'Imperial Diamond', NULL, 'Драгоценный камень, когда-то сиявший в короне императора Эльморедена. Можно продать в Торговой Лавке.', 'Jewel of brilliant light used in decorating the crown of the Elmoreden emperor. Can be sold at shops.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (3457, 'Statue of Shilen - Head', NULL, 'Часть сломанной статуи. Можно продать в Торговой Лавке. А может, собрать все части статуи?..', 'Part of a broken statue. Can be sold at shops. If you collect the remaining pieces of the statue...?', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (3458, 'Statue of Shilen - Torso', NULL, 'Часть сломанной статуи. Можно продать в Торговой Лавке. А может, собрать все части статуи?..', 'Part of a broken statue. Can be sold at shops. If you collect the remaining pieces of the statue...?', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (3459, 'Statue of Shilen - Arm', NULL, 'Часть сломанной статуи. Можно продать в Торговой Лавке. А может, собрать все части статуи?..', 'Part of a broken statue. Can be sold at shops. If you collect the remaining pieces of the statue...?', 'etc_gargoyle_claw_i00', 0);
INSERT INTO `all_items` VALUES (3460, 'Statue of Shilen - Leg', NULL, 'Часть сломанной статуи. Можно продать в Торговой Лавке. А может, собрать все части статуи?..', 'Part of a broken statue. Can be sold at shops. If you collect the remaining pieces of the statue...?', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (3461, 'Complete Statue of Shilen', NULL, 'Статуя Шилен, сделанная во времена древней империи Эльмореден. Можно продать в магазин по высокой цене.', 'Statue of Shilen made in the time of the ancient Elmoreden empire. Can be sold at shops for a high price.', 'etc_statue_of_einhasad_bronze_i00', 0);
INSERT INTO `all_items` VALUES (3462, 'Fragment of Ancient Tablet: 1st Piece', NULL, 'Кусок древней каменной скрижали. А может, собрать все ее части?..', 'Fragment of ancient clay tablet. If you collect the remaining pieces of the tablet...?', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (3463, 'Fragment of Ancient Tablet: 2nd Piece', NULL, 'Кусок древней каменной скрижали. А может, собрать все ее части?..', 'Fragment of ancient clay tablet. If you collect the remaining pieces of the tablet...?', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (3464, 'Fragment of Ancient Tablet: 3rd Piece', NULL, 'Кусок древней каменной скрижали. А может, собрать все ее части?..', 'Fragment of ancient clay tablet. If you collect the remaining pieces of the tablet...?', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (3465, 'Fragment of Ancient Tablet: 4th Piece', NULL, 'Кусок древней каменной скрижали. А может, собрать все ее части?..', 'Fragment of ancient clay tablet. If you collect the remaining pieces of the tablet...?', 'etc_plate_silver_i00', 0);
INSERT INTO `all_items` VALUES (3466, 'Complete Ancient Tablet', NULL, 'Большая скрижаль, на которой выгравированы древние тексты. Можно продать в магазин по высокой цене.', 'A large clay tablet upon which ancient texts are engraved. You can sell it to a store at a high price.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (3467, 'Wish Potion', NULL, 'Волшебное зелье, которое, как говорят, исполняет желания.', 'Magic potion that is said to make wishes come true.', 'etc_lesser_potion_blue_i00', 0);
INSERT INTO `all_items` VALUES (3468, 'Ancient Crown', NULL, 'Корона, украшенная огромным количеством драгоценных камней. Слишком тяжелая, чтобы носить на голове. Можно продать в Торговой Лавке.', 'Crown that is full of jewels but is too big to wear on the head. Let\'s sell it.', 'etc_mark_blue_i00', 0);
INSERT INTO `all_items` VALUES (3469, 'Certificate of Royalty', NULL, 'Грамота, подписанная самим королем, однако никто не знает, кому она принадлежит.', 'Certificate of royalty but nobody knows who made it.', 'etc_crest_red_i00', 0);
INSERT INTO `all_items` VALUES (3470, 'Gold Bar', NULL, 'Тяжелый слиток чистого золота.', 'Heavy lump of pure gold.', 'etc_lump_yellow_i00', 0);
