INSERT INTO `all_items` VALUES (3500, 'Dragonflute of Wind', NULL, 'Флейта, используемая для призыва Дракончика Ветра. Питомец забирает часть опыта, заработанного хозяином.', 'Flute used to call up hatchling of wind.', 'etc_flute_i00', 7);
INSERT INTO `all_items` VALUES (3501, 'Dragonflute of Star', NULL, 'Флейта, используемая для призыва Дракончика Звезд. Питомец забирает часть опыта, заработанного хозяином.', 'Flute used to call up hatchling of star.', 'etc_flute_i00', 7);
INSERT INTO `all_items` VALUES (3502, 'Dragonflute of Twilight', NULL, 'Флейта, используемая для призыва Дракончика Сумерек. Питомец забирает часть опыта, заработанного хозяином.', 'Flute used to call up hatchling of twilight.', 'etc_flute_i00', 7);
INSERT INTO `all_items` VALUES (3503, 'Deliverymen Decertificate', NULL, 'Грамота, разрешающая доставлять посылки. Подписана Локрином, Главой Гильдии Железных Врат.', 'Official certification for making deliveries. Issued by the Iron Gate Guild. Seal of Lockrin of the Iron Gate is affixed.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3504, 'Kirunas Horn', NULL, 'Посылка от Начальника Склада Гесто, которую необходимо как можно скорее доставить Понтифику Пенатусу.', 'Item that Warehouse Chief Gesto entrusted saying to take it to High Prefect Penatus. You must deliver it quickly.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3505, 'Mithril Mold', NULL, 'Посылка от Начальника Склада Гесто, которую необходимо как можно скорее доставить Кузнецу Рупио.', 'Item that Warehouse Chief Gesto entrusted saying to take it to Blacksmith Rupio. You must deliver it quickly.', 'etc_silver_mold_i00', 0);
INSERT INTO `all_items` VALUES (3506, 'Bloody Letter', NULL, 'Посылка от Начальника Склада Гесто, которую необходимо как можно скорее доставить Мартину.', 'Item that Warehouse Chief Gesto entrusted saying to take it to Martin. You must deliver it quickly.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (3507, 'Supplies to Alex', NULL, 'Тяжелый ящик с припасами для Алекса из Флорана.', 'Supply item. It\'s really heavy. Let\'s take it to Alex in Florin Village.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (3508, 'Supplies to Endrigo', NULL, 'Тяжелый ящик с припасами для Смотрителя Эндриго с Земли Казненных.', 'Supply item. It\'s really heavy. Let\'s take it to Warden Endrigo at the Execution Grounds.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (3509, 'Alex\'s Coins', NULL, 'Плата за припасы, доставленные Алексу.', 'Return gift given by Alex as expression of thanks for having brought enough of the supply item.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (3510, 'Wardens Appreciation', NULL, 'Письмо Смотрителя Эндриго, в котором он благодарит за доставленные припасы.', 'Letter of thanks given by Warden Endrigo of the Execution Grounds as expression of thanks for having brought enough of the supplied items.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (3511, 'Blackbox to Orim', NULL, 'Ящик, который Начальник Склада Гесто поручил доставить Ориму Тени. Что может быть внутри?..', 'Item that Warehouse Chief Gesto entrusted saying to take it to Orim the Shadow. What could be inside...?', 'etc_squares_gray_i00', 0);
INSERT INTO `all_items` VALUES (3512, 'Deluxe Windsus Ham', NULL, 'Посылка от Начальника Склада Гесто, которую необходимо как можно скорее доставить Ориму Тени.', 'Item that Warehouse Chief Gesto entrusted saying to take it to Orim the Shadow. What could be inside...?', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (3513, 'Heart of Silenos', NULL, 'Сердце, полученное за убийство Фавна по поручению Орима Тени.', 'Heart obtained by killing silenos. Item specially ordered by Orim the Shadow.', 'etc_heart_i00', 0);
INSERT INTO `all_items` VALUES (3514, 'Request Giran', NULL, 'Заказ из Гирана. По нему Вы можете получить плату за доставку.', 'Order received from the warehouse of Giran Castle Town. You can receive the delivery fee by taking this and the receipt confirmation document.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3515, 'Request Gludin', NULL, 'Заказ из Глудио. По нему Вы можете получить плату за доставку.', 'Order received from the warehouse of the Town of Gludio. You can receive the delivery fee by taking this and the receipt confirmation document.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3516, 'Request Hunters', NULL, 'Заказ из Деревни Охотников. По нему Вы можете получить плату за доставку.', 'Order received from the warehouse of Hunter Village. You can receive the delivery fee by taking this and the receipt confirmation document.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3517, 'Delivery Score Red', NULL, 'Квитанция о доставке. 50 таких квитанций можно обменять на Синюю Грамоту.', 'Certificate received each time a delivery is completed successfully. If you collect 50 certificates, you can exchange it for a blue delivery statement.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (3518, 'Delivery Score Blue', NULL, 'Свидетельство, которое можно получить за 50 доставок. Увеличивает на 4% плату за доставку.', 'Certificate that you can receive if you successfully complete 50 deliveries. The delivery fee increases by 4% for each certificate.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (3519, 'Deliverymen Advanced Certificate Super', NULL, 'Грамота, вручаемая за 1000 доставок. Увеличивает плату за доставку на 120%!', 'Certificate of master deliveryman received for having successfully completed 1000 deliveries. 120% delivery fee added!', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3520, '1st Confirmation Document', NULL, 'Квитанция о получении посылки. Соберите 3 таких и отнесите Начальнику Склада Гесто.', 'Confirmation form the person receiving delivery of an item signs. Collect three sheets and take it to Warehouse Chief Gesto.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3521, '2nd Confirmation Document', NULL, 'Квитанция о получении посылки. Соберите 2 таких и отнесите Начальнику Склада Гесто.', 'Confirmation form the person receiving delivery of an item signs. Collect two sheets and take it to Warehouse Chief Gesto.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3522, 'Delivery Goods 01', NULL, 'Свиток, которое необходимо доставить Магистру Баулро в Храм Эйнхасад на Говорящем Острове.', 'Scroll to be taken to Magister Baulro of Einhasad Temple on Talking Island.', 'etc_roll_of_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (3523, 'Delivery Goods 02', NULL, 'Письмо, которое необходимо доставить Смотрителю Маяка Роксвеллу с Говорящего Острова.', 'Letter to be taken to Lighthouse Keeper Rockswell of Talking Island.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (3524, 'Delivery Goods 03', NULL, 'Книга, которую необходимо доставить Мариусу, живущему в домике на северном побережье Говорящего Острова.', 'Book to be taken to Marius at the private beach house on the north side of Talking Island.', 'etc_spellbook_red_i00', 0);
