INSERT INTO `all_items` VALUES (3542, 'Delivery Goods 21', NULL, 'Шкатулка, которую необходимо доставить Мастеру Стапину из Гильдии Темных эльфов Гирана.', 'Jewelry box to be taken to Master Stapin of Dark Elf Guild in Giran Castle Town.', 'etc_jewel_box_i00', 0);
