INSERT INTO `all_items` VALUES (3547, 'Delivery Goods 26', NULL, 'Книга, которую необходимо доставить Кардиналу Сересин в Храм Эйнхасад Орена.', 'Book to be taken to Cardinal Seresin of Einhasad Temple in the Town of Oren.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (3548, 'Delivery Goods 27', NULL, 'Свиток, который необходимо доставить Главе Дуда-Мара Такуне к Гильдии Орков Орена.', 'Scroll to be taken to Duda-Mara Chief Takuna near the Orc Guild in the Town of Oren.', 'etc_roll_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3549, 'Delivery Goods 28', NULL, 'Картина, которую необходимо доставить Колину в Деревню Охотников.', 'Picture to be taken to Hunter Guild Member Colin in Hunter Village.', 'etc_painting_i00', 0);
