INSERT INTO `all_items` VALUES (3656, 'Eye of Seer', NULL, 'Глаз, полученный после убийства Всевидящего Ока Зла. Заказ Самеда.', 'Eye obtained from killing a floating eye seer. Item specially ordered by Samed.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (3657, 'Pincher Claw', NULL, 'Коготь, полученный после убийства Паука Хелицера. Заказ Кузнеца Пинтера.', 'Claw obtained from killing pincher spider. Item specially ordered by Blacksmith Pinter.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (3658, 'Ol Mahum Uniform', NULL, 'Камни, полученные от Капитана и Повелителя Гноллов. Заказ сэра Орто Лансера.', 'Ol mahum uniform received from ol mahum captain and ol mahum lord. Item specially ordered by Sir Ortho Lancer.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (3659, 'Enku Orc Champion\'s Head', NULL, 'Череп Чемпиона Орков Энку. Заказ Префекта Клогга.', 'Head of Enku orc champion. Item specially ordered by High Prefect Clogg.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3660, 'Bloody Bee Stinger', NULL, 'Жало, полученное при убийстве Кровавой Пчелы. Заказ Бакалейщика Пано.', 'Poison stinger from a bloody bee. Item specially ordered by Grocer Pano.', 'etc_sting_a_i00', 0);
INSERT INTO `all_items` VALUES (3661, 'Ignition of Ghost Fire', NULL, 'Специальный предмет, полученный после убийства Призрачного Огня. Заказ Магистра Каены.', 'Special item obtained by killing ghost fire. Item specially ordered by Sorceress Kaiena.', 'etc_oriharukon_ore_i00', 0);
INSERT INTO `all_items` VALUES (3662, 'Ethereal Blood', NULL, 'Призрачная кровь, полученная после убийства Туманного Потрошителя. Заказ Мастера Николя.', 'Ethereal blood received from killing a horror mist ripper. Item specially ordered by Maestro Nikola.', 'etc_potion_clear_i00', 0);
INSERT INTO `all_items` VALUES (3663, 'Returned Delivery Goods 10', NULL, 'Коробка, возвращенная Самедом. Отнесите ее в ближайшее хранилище.', 'Box returned by Samed. Let\'s take this to a nearby warehouse.', 'etc_squares_gray_i00', 0);
INSERT INTO `all_items` VALUES (3664, 'Returned Delivery Goods 15', NULL, 'Шкатулка, возращенная Феей Мурика. Отнесите ее в ближайшее хранилище.', 'Jewelry box returned by Pixy Murika. Let\'s take this to a nearby warehouse.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (3665, 'Returned Delivery Goods 30', NULL, 'Сосуд, возвращенный Старейшиной Кроносом. Отнесите его в ближайшее хранилище.', 'Jar returned by Elder Cronos. Let\'s take this to a nearby warehouse.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (3666, 'Returned Delivery Goods 33', NULL, 'Золотой слиток, возращенный Алексом. Отнесите его в ближайшее хранилище.', 'Gold nugget returned by Alex. Let\'s take this to a nearby warehouse.', 'etc_lump_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3667, 'Returned Delivery Goods 37', NULL, 'Книга, возвращенная Магистром Каеной. Отнесите ее в ближайшее хранилище.', 'Book returned by Sorceress Kaiena. Let\'s take this to a nearby warehouse.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (3668, 'Returned Delivery Goods 45', NULL, 'Мешочек, возвращенный Телохранителем Джаксом. Отнесите его в ближайшее хранилище.', 'Shaft returned by Bodyguard Jax. Let\'s take this to a nearby warehouse.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (3669, 'Returned Delivery Goods 55', NULL, 'Сосуд, возвращенный Проповедницей Сла. Отнесите его в ближайшее хранилище.', 'Jar returned by Preacher Sla. Let\'s take this to a nearby warehouse.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (3670, 'Returned Delivery Goods 60', NULL, 'Ящички, возвращенные Ведьмой Варикой. Отнесите их в ближайшее хранилище.', 'Small boxes returned by Shaman Varika. Let\'s take this to a nearby warehouse.', 'etc_silver_i00', 0);
INSERT INTO `all_items` VALUES (3671, 'Sophya\'s 1st Order', NULL, 'Приказ Капитана Наемников Софии, согласно которому необходимо уничтожить нежить в Земле Казненных.', 'Order from Chief Mercenary Sophya. Says to destroy the undead at the Execution Grounds.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (3672, 'Sophya\'s 2nd Order', NULL, 'Приказ Капитана Наемников Софии, согласно которому необходимо уничтожить Гноллов в Укреплении Партизан.', 'Order from Chief Mercenary Sophya. It says to destroy Ol Mahums in the Fortress of Resistance.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (3673, 'Sophya\'s 3rd Order', NULL, 'Приказ Капитана Наемников Софии, согласно которому необходимо уничтожить Ящеров Делу, обитающих в южных землях Диона и Гирана.', 'Order from Chief Mercenary Sophya. Says to destroy Delu lizardmen of the southern areas of the Dion and Giran regions.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (3674, 'Sophya\'s 4th Order', NULL, 'Приказ Капитана Наемников Софии, согласно которому необходимо уничтожить Болотных Стакато в Топях Крумы.', 'Order from Chief Mercenary Sophya. Says to destroy marsh stakatos of the Cruma Marshland.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (3675, 'Lion\'s Claw', NULL, 'Знак, вручаемый наемнику, достигшему больших успехов в Отряде Черного Льва.', 'Mark given to the person that achieves distinguished merits in the Black Lion Mercenaries.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (3676, 'Lion\'s Eye', NULL, 'Знак, вручаемый наемнику, достигшему выдающихся успехов в Отряде Черного Льва.', 'Mark given to the person that achieves very distinguished merits in the Black Lion Mercenaries.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (3677, 'Guild Coin', NULL, 'Монеты, врученные в знак благодарности членами Торговой Гильдии Адена.', 'Commemorative coin given as thanks by the members of the Aden Commercial Guild.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (3678, 'Alchemy Text', NULL, 'Книга Алхимика Матильды. Следуя ее указаниям, найдите в Топях Крумы Дерево Тайник и заберите оттуда спрятанную книгу.', 'A book that can be obtained from Alchemist Matild. According to the instructions written in the book, go find the secret keeper tree located in the Cruma Marshlands and obtain the secret book.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (3679, 'Secret Book of Potion', NULL, 'Древняя алхимическая книга. Отнесите ее Алхимику Матильде.', 'Ancient book received from the guardian trees of the secret. Take this to Alchemist Matild.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (3680, '1st Potion Recipe', NULL, 'Янтарная Чешуйка, Камень Душ Ветра, Стеклянный Глаз, Кровь Людоеда.', 'Scale of amber basilisk, wind soulstone of whispering wind, glass eye of glass jaguar, blood of Turak bugbear0', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (3681, '2nd Potion Recipe', NULL, 'Рог Фавна, Тля Муравья Солдата, Хитин Тирана, Жуткая Эктоплазма.', 'Silenos\'s horn, ant soldier aphid, tyrant\'s chitin, and horror ectoplasm of horror mist ripper.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3682, 'Matild\'s Orb', NULL, 'Знак признательности, врученный Алхимиком Матильдой.', 'Certificate of friendship from Alchemist Matild.', 'etc_crystal_ball_gold_i00', 0);
INSERT INTO `all_items` VALUES (3683, 'Forbidden Love Scroll', NULL, 'Свиток, содержащий информацию о том, как добиться страстной любви. Наверняка найдется много желающих его купить...', 'The secrets of depraved but rapturous love are written. May be sold at a high price to an interested person...', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (3684, 'Amber Scale', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_scale_of_medusa_red_i00', 0);
INSERT INTO `all_items` VALUES (3685, 'Wind Soulstone', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3686, 'Glass Eye', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_eyeball_i00', 0);
