INSERT INTO `all_items` VALUES (3688, 'Silenos Horn', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3689, 'Ant Soldier Aphid', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3690, 'Tyrant\'s Chitin', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (3691, 'Bugbear Blood', NULL, 'Ингредиент для создания Зелья Желаний. Отнесите это вместе с другими материалами Алхимику Матильде.', 'Necessary ingredient for making wish potion. Take it with the other ingredients to Alchemist Matild.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (3692, '1st Circle Hunter License', NULL, 'Лицензия Охотника I Круга. Необходима для получения заданий в Гильдии Охотников.', 'Certificate that proves eligibility as a 1st circle hunter. You must have this to be able to carry out orders given by the Hunter Guild.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (3693, '2nd Circle Hunter License', NULL, 'Лицензия Охотника II Круга. Необходима для получения заданий в Гильдии Охотников.', 'Certificate that proves eligibility as a 2nd circle hunter. You must have this to be able to carry out orders given by the Hunter Guild.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (3694, 'Laurel Leaf Pin', NULL, 'Знак, вручаемый охотникам за выполнение заданий гильдии. Чем больше заданий выполнил охотник, тем больше у него этих Листов.', 'Mark given to hunters that successfully carry out requests of the guild. The more experienced a hunter is, the more of these he or she has.', 'etc_herb_blue_i00', 0);
INSERT INTO `all_items` VALUES (3695, '1st Test Instructions', NULL, 'Инструкция к испытанию для получения Лицензии Охотника I Круга. Необходимо выполнить, как минимум, 3 из 6 заданий Грея.', 'Instructions of the test for the 1st circle hunter certificate. Says to complete at least three of the six tasks presented by Grey.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3696, '2nd Test Instructions', NULL, 'Инструкция к испытанию для получения Лицензии Охотника II Круга. Необходимо выполнить, как минимум, 3 из 6 заданий Грея.', 'Instructions of the test for the 2nd circle hunter certificate. Says to complete at least three of the six tasks presented by Grey.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3697, 'Cybellin\'s Request', NULL, 'Записка, согласно которой Вы должны полностью очистить Кристалл Крови, убивая Ящеров Лито и Ящеров Харит Кинжалом Сибелин.', 'Asks you to raise the purity of blood crystal by killing Leto lizardmen or Harit lizardmen with cybellin dagger.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3698, 'Blood Crystal: Purity 1', NULL, 'Красный кристалл, хранящий в себе магическую силу. Очищен 1 раз. Чем больше он очищен, тем выше его ценность.', 'Bloody jewel that contains dreary magical power. Purity 1. The higher the purity of the crystal is, the higher the value.', 'etc_jewel_red_i00', 0);
