INSERT INTO `all_items` VALUES (3708, 'Broken Blood Crystal', NULL, 'Красный магический кристалл, разбитый на мелкие осколки.', 'Blood crystal broken by magical inequality.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (3709, 'Guardian Basilisk Scale', NULL, 'Чешуя, полученная при убийстве Василиска Стражника. Соберите 40 чешуек и отнесите их Грею из Гильдии Охотников.', 'Scale that was peeled off the corpse of guardian basilisk. Collect 40 and take them to Hunter Guild Member Grey.', 'etc_scale_of_medusa_red_i00', 0);
INSERT INTO `all_items` VALUES (3710, 'Karut Weed', NULL, 'Трава, которую Шаманы Ящеров Лито используют для лечения. Соберите 20 побегов и отнесите их Грею из Гильдии Охотников.', 'Blade of grass that Leto lizardman shamans use for medication. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_branch_green_i00', 0);
INSERT INTO `all_items` VALUES (3711, 'Haka\'s Head', NULL, 'Доказательство убийства Владыки Брека Хаки. Отнесите его вместе с Головами Яки и Марки Грею из Гильдии Охотников.', 'Certificate proving that Breka overlord Haka was killed. Take it together with heads of Jaka and Marka to Hunter Guild Member Grey.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3712, 'Jakas\' Head', NULL, 'Доказательство убийства Владыки Брека Яки. Отнесите его вместе с Головами Хаки и Марки Грею из Гильдии Охотников.', 'Certificate proving that breka overlord jaka was killed. Take it together with heads of haka and marka to Hunter Guild Member Grey.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3713, 'Marka\'s Head', NULL, 'Доказательство убийства Владыки Брека Марки. Отнесите его вместе с Головами Хаки и Яки Грею из Гильдии Охотников.', 'Certificate demonstrating that breka overlord marka was killed. Take it together with heads of haka and jaka to Hunter Guild Member Grey.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3714, 'Windsus Aleph Skin', NULL, 'Шкура Вепря Алефа. Отнесите ее Грею из Гильдии Охотников.', 'Skin peeled off after killing windsus aleph. Take it to Hunter Guild Member Grey.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (3715, 'Indigo Spirit Ore', NULL, 'Рунный камень, полученный после убийства Манашен Горгульи или Зачарованного Каменного Голема. Соберите 20 камней и отнесите их Грею из Гильдии Охотников.', 'Runestone obtained from killing manashen or enchanted stone golem. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (3716, 'Sporesea Seed', NULL, 'Семя, полученное при убийстве Гигантского Гриба. Соберите 30 штук и отнесите их Грею из Гильдии Охотников.', 'Spore that comes out of the body of giant fungus. Collect 30 and take them to Hunter Guild Member Grey.', 'etc_seed_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3717, 'Timak Orc Totem', NULL, 'Маленькая статуэтка, полученная при убийстве Бойца Орков Тимак. Соберите 20 штук и отнесите их Грею из Гильдии Охотников.', 'Small statue that Timak orc fighters carry on their bodies. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (3718, 'Trisalim Silk', NULL, 'Прочная паутина, полученная при убийстве Трисалима. Соберите 20 штук и отнесите их Грею из Гильдии Охотников.', 'Strong spider web that comes out of the body of trisalim. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_cobweb_i00', 0);
INSERT INTO `all_items` VALUES (3719, 'Ambrosius Fruit', NULL, 'Фрукт, полученный при убийстве Древня Долины. Соберите 30 штук и отнесите их Грею из Гильдии Охотников.', 'Tree fruit obtained from killing valley treants. Collect 30 and take them to Hunter Guild Member Grey.', 'etc_fruit_red_i00', 0);
INSERT INTO `all_items` VALUES (3720, 'Balefire Crystal', NULL, 'Кристалл, полученный при убийстве Тайрима. Соберите 20 штук и отнесите их Грею из Гильдии Охотников.', 'Crystal of ill will obtained from killing tairim. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (3721, 'Imperial Arrowhead', NULL, 'Наконечник стрелы, использовавшийся лучниками в древней империи Эльмореден. Соберите 20 штук и отнесите их Грею из Гильдии Охотников.', 'Arrowhead used by archers of the ancient Elmoreden empire. Collect 20 and take them to Hunter Guild Member Grey.', 'etc_arrowhead_i02', 0);
