INSERT INTO `all_items` VALUES (3724, 'Triska\'s Head', NULL, 'Доказательство убийства Налетчика Тарлк Триски. Соберите головы 5 налетчиков и отнесите их Грею из Гильдии Охотников.', 'Certificate proving that talk raider Triska was killed. Collect heads of five raiders and take them to Hunter Guild Member Grey.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3725, 'Motura\'s Head', NULL, 'Доказательство убийства Налетчика Тарлк Мотуры. Соберите головы 5 налетчиков и отнесите их Грею из Гильдии Охотников.', 'Certificate proving that talk raider Motura was killed. Collect heads of five raiders and take them to Hunter Guild Member Grey.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3726, 'Kalath\'s Head', NULL, 'Доказательство убийства Налетчика Тарлк Калафа. Соберите головы 5 налетчиков и отнесите их Грею из Гильдии Охотников.', 'Certificate proving that talk raider Kalath was killed. Collect heads of five raiders and take them to Hunter Guild Member Greay.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3727, '1st Circle Request: 1C', NULL, 'Необходимо убить Стрелков или Солдат Ящеров Лито и собрать 40 Оберегов Кадеша.', 'Kill Leto lizardman archer or soldier and get 40 totems of War Hero Kadesh.', 'etc_letter_white_i00', 0);
