INSERT INTO `all_items` VALUES (3730, '1st Circle Request: 4C', NULL, 'Добудьте 30 кусков Мяса Гигантского Монстроглаза.', 'Get 30 pieces of giant floating eye.', 'etc_letter_white_i00', 0);
