INSERT INTO `all_items` VALUES (3778, 'Taik Obsidian Amulet', NULL, 'Амулет, полученный при убийстве Воина или Стрелка Орков Тайк. Соберите 50 таких и отдайте Тору из Гильдии Охотников.', 'Amulet obtained from killing Taik orc archers or warriors. Collect 50 and take them to Guild Member Tor.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (3779, 'Karul Bugbear Head', NULL, 'Голова Людоеда Карул. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Head cut off after killing Karul bugbears. Collect 30 and take them to Guild Member Tor.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3780, 'Tamlin Ivory Charm', NULL, 'Оберег, полученный при убийстве Орка Тамлин или Стрелка Орков Тамлин. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Charm obtained from killing Tamlin orcs or Tamlin orc archers. Collect 40 and take them to Guild Member Tor.', 'etc_stick_i00', 0);
INSERT INTO `all_items` VALUES (3781, 'Fang of Narak', NULL, 'Доказательство убийства Главы Лито Нарака. Отнесите его Тору из Гильдии Охотников.', 'Certificate of having killed Leto elder Narak. Take it to Guild Member Tor.', 'etc_skull_black_i00', 0);
