INSERT INTO `all_items` VALUES (3786, 'Kronbe Venom Sac', NULL, 'Ядовитая железа, полученная при убийстве Паука Кронбе. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Venom sac obtained from killing kronbe. Collect 30 and take them to Guild Member Tor.', 'etc_poison_pouch_i00', 0);
INSERT INTO `all_items` VALUES (3787, 'Eva\'s Charm', NULL, 'Оберег, полученный при убийстве Споровых Зомби. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Charm carried on the bodies of ancient Elven warriors. Collect 30 and take them to Guild Member Tor.', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (3788, 'Titan\'s Tablet', NULL, 'Древняя каменная плитка, добытая у Главаря Грандисов Гока Магока. Отдайте ее Тору из Гильдии Охотников.', 'Ancient stone tablet recovered from grandis chief Gok Magok. Take it to Guild Member Tor.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (3789, 'Book of Shunaiman', NULL, 'Древний документ, добытый у Главы Карул Оруто. Отдайте его Тору из Гильдии Охотников.', 'Ancient document recovered from Karul Chief Orooto. Take it to Guild Member Tor.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (3790, 'Rotting Tree Spores', NULL, 'Спора, полученная при убийстве Трухлявых Деревьев. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Seed collected from rot tree trunks. Collect 40 and take them to Guild Member Tor.', 'etc_seed_red_i00', 0);
INSERT INTO `all_items` VALUES (3791, 'Trisalim Venom Sac', NULL, 'Ядовитая железа, полученная при убийстве Трисалима. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Venom sac removed from trisalim corpse. Collect 40 and take them to Guild Member Tor.', 'etc_poison_pouch_i00', 0);
INSERT INTO `all_items` VALUES (3792, 'Taik Orc Totem', NULL, 'Тотем, полученный при убийстве Шамана или Капитана Орков Тайк. Соберите 50 таких и отнесите Тору из Гильдии Охотников.', 'Statue obtained from killing Taik orc shamen or captains. Collect 50 and take them to Guild Member Tor.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (3793, 'Harit Barbed Necklace', NULL, 'Ожерелье, полученное при убийстве Солдата, Стрелка или Воина Ящеров Харит. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Necklace obtained from killing Harit lizardman soldiers, archers or warriors. Collect 40 and take them to Guild Member Tor.', 'etc_leash_i00', 0);
INSERT INTO `all_items` VALUES (3794, 'Coin of Old Empire', NULL, 'Монета древней империи Эльмореден. Соберите 20 таких и отдайте Тору из Гильдии Охотников.', 'Coin used during the time of the ancient Elmoreden Empire. Collect 20 and take them to Guild Member Tor.', 'etc_coins_blue_i00', 0);
INSERT INTO `all_items` VALUES (3795, 'Skin of Farcran', NULL, 'Шкура, снятая с убитого Гниющего Медведя Зомби. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Skin removed after killing farcran. Collect 30 and take them to Guild Member Tor.', 'etc_leather_i00', 0);
INSERT INTO `all_items` VALUES (3796, 'Tempest Shard', NULL, 'Кристалл, полученный при убийстве Мары. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Spirit ore obtained by killing a fline. Collect 40 and take them to Guild Member Tor.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3797, 'Tsunami Shard', NULL, 'Кристалл, полученный при убийстве Утопленницы. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Spirit ore obtained by killing a liele. Collect 40 and take them to Guild Member Tor.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (3798, 'Satyr Mane', NULL, 'Грива, срезанная с убитого Сатира. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Mane obtained from killing satyr or satyr elders. Collect 40 and take them to Guild Member Tor.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (3799, 'Hamadryad Shard', NULL, 'Рунный камень, полученный при убийстве Хранительницы Леса. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Runestone obtained from killing forest runner. Collect 40 and take them to Guild Member Tor.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (3800, 'Vanor Silenos Mane', NULL, 'Грива Солдата, Разведчика или Воина Фавнов Ванор. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Mane of vanor silenos soldiers, scouts or warriors. Collect 30 and take them to Guild Member Tor.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (3801, 'Talk Bugbear Totem', NULL, 'Маленькая статуэтка, которую Людоеды носят с собой. Соберите 30 таких и отдайте Тору из Гильдии Охотников.', 'Small statue that talk bugbear warriors carry around on their bodies. Collect 30 and take them to Guild Member Tor.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (3802, 'Okun\'s Head', NULL, 'Доказательство убийства Владыки Тимак Окуна. Отдайте Тору из Гильдии Охотников.', 'Certificate of having killed timak overlord okun. Take it to Guild Member Tor.', 'etc_skull_black_i00', 0);
INSERT INTO `all_items` VALUES (3803, 'Kakran\'s Head', NULL, 'Доказательство убийства Владыки Тайк Какрана. Отдайте Тору из Гильдии Охотников.', 'Certificate of having killed taik overlord kakran. Take it to Guild Member Tor.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3804, 'Narcissus\'s Soulstone', NULL, 'Осколок разбитого зеркала. Соберите 40 таких и отдайте Тору из Гильдии Охотников.', 'Fragment of destroyed mirror. Collect 40 and take them to Guild Member Tor.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (3805, 'Deprive Eye', NULL, 'Кусок, вырезанный из Ока Ярости. Соберите 20 таких и отдайте Тору из Гильдии Охотников.', 'Eye obtained from deprive corpse. Collect 20 and take them to Guild Member Tor.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (3806, 'Unicorn\'s Horn', NULL, 'Рог убитого Единорога. Соберите 20 таких и отдайте Тору из Гильдии Охотников.', 'Horn obtained from killing unicorn or unicorn elder. Collect 20 and take them to Guild Member Tor.', 'etc_unicorn_horn_i00', 0);
INSERT INTO `all_items` VALUES (3807, 'Kerunos\'s Gold Mane', NULL, 'Грива, срезанная у Главы Ванор Керуноса. Отдайте Тору из Гильдии Охотников.', 'Mane removed after killing vanor chief kerunos. Take it to Guild Member Tor.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (3808, 'Skull of Executed', NULL, 'Череп, полученный при убийстве Обходчика Могил. Соберите 20 таких и отдайте Тору из Гильдии Охотников.', 'Skull obtained from killing grave wanderer. Collect 20 and take them to Guild Member Tor.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (3809, 'Bust of Travis', NULL, 'Бюст короля Трэвиса, отобранный у Вождя Хатар Кубела. Отдайте Тору из Гильдии Охотников.', 'Bust of King Travis recovered from hatar chieftain kubel. Take it to Guild Member Tor.', 'etc_holy_statue_silver_i00', 0);
INSERT INTO `all_items` VALUES (3810, 'Sword of Cadmus', NULL, 'Меч телохранителя короля Кадмуса, добытый у Болотного Судьи. Соберите 10 таких и отдайте Тору из Гильдии Охотников.', 'Sword of bodyguard of King Cadmus recovered from judge of marsh. Collect 10 and take them to Guild Member Tor.', 'weapon_sword_of_watershadow_i00', 0);
INSERT INTO `all_items` VALUES (3811, 'Coin Diagram', NULL, 'Книга о монетах, которую нужно отдать Смотрителю Склада Соринту. Поговорите с Главой Гильдии Охотников Бернардом, и он расскажет Вам, что делать дальше.', 'An illustration of the coin that Warehouse Keeper Sorint wants you to retrieve.  Meet with Hunter Guild President Bernard who will instruct you on what to do next.', 'etc_spell_books_blue_i00', 0);
INSERT INTO `all_items` VALUES (3812, 'Kaldis Gold Dragon', NULL, 'Монета, аналогичная той, что хранится у Главы Гильдии Охотников Бернарда. Отнесите ее Смотрителю Склада Соринту.', 'Coin that is the same as that which Hunter Guild President Bernard has. Take this to Warehouse Keeper Sorint.', 'etc_magic_coin_gold_i00', 0);
INSERT INTO `all_items` VALUES (3813, 'Coin Collector Membership 1', NULL, 'Грамота, вручаемая Нумизматам, достигшим I степени. Нужна для обмена монетами с другими членами клуба.', 'Level 1 coin collector club membership card. You must have this to exchange coins with members of other places.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (3814, 'Coin Collector Membership 2', NULL, 'Грамота, вручаемая Нумизматам, достигшим II степени. Нужна для обмена монетами с другими Нумизматами II или III степени.', 'Level 2 coin collector club membership card. You must have this to exchange coins with level 2 or level 3 members of other places.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3815, 'Coin Collector Membership 3', NULL, 'Грамота, вручаемая Нумизматам, достигшим III степени. Нужна для обмена монетами с другими Нумизматами III степени.', 'Level 3 coin collector club membership card. You must have this to exchange coins with level 3 members of other places.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (3816, 'Fairy Stone', NULL, 'Драгоценность, необходимая для того, чтобы встретиться и поговорить с Феей Мимю.', 'Jewel required to meet and talk with fairy Mimyu.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (3817, 'Deluxe Fairy Stone', NULL, 'Драгоценность, необходимая для того, чтобы встретиться и поговорить с Феей Мимю. Будьте внимательны – создания, живущие в Волшебной Долине, исчезают сразу же после своей смерти.', 'Jewel required to meet and talk with fairy Mimyu. Be careful because creatures living in Fairy Valley disappear when killed.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (3818, 'Fairy Stone List', NULL, '10 кусков Угля, 10 кусков Древесного Угля, 1 Самоцвет: Ранг D, 3 Серебряных Слитка и 10 кусков Кожи Повелителя Жаб.', '10 pieces of coal, 10 pieces of charcoal, 1 D-grade gemstone, 3 silver nuggets and 10 pieces of toad lord back skin.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3819, 'Deluxe Fairy Stone List', NULL, '10 кусков Угля, 10 кусков Древесного Угля, 1 Самоцвет: Ранг C, 1 Камень Чистоты, 5 Серебряных Слитков и 20 кусков Кожи Повелителя Жаб.', '10 pieces of coal, 10 pieces of charcoal, 1 C-grade gemstone, 1 stone of purity, 5 nuggets of silver and 20 pieces of toad lord back skin.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3820, 'Toad Lord Back Skin', NULL, 'Кожа Повелителя Жаб. Ингредиент для очищения Камня Феи.', 'Haggard backskin of a toad lord. Ingredient used for removing impurities from fairy stone.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (3821, 'Juice of Monkshood', NULL, 'Лекарство, нужное для разговора с дрейками и змеями.', 'Medicine needed to talk with drakes or wyrms.', 'etc_potion_green_i00', 0);
INSERT INTO `all_items` VALUES (3822, 'Scale of Drake Exarion', NULL, 'Чешуя Дрейка Эскариона. Возьмите ее и отберите 20 яиц у Воинов Ящеров Лито возле Замка Орен.', 'Scale of drake exarion. Take this and recover 20 eggs from leto lizardman warriors near Oren Castle.', 'etc_scale_of_medusa_blue_i00', 0);
INSERT INTO `all_items` VALUES (3823, 'Egg of Drake Exarion', NULL, 'Яйцо Дрейка Эскариона, полученное при убийстве Воина Ящеров Лито.', 'Egg of drake exarion recovered from leto lizardman warriors.', 'etc_dragon_egg_i02', 0);
INSERT INTO `all_items` VALUES (3824, 'Scale of Drake Zwov', NULL, 'Чешуя Дрейка Зуова. Возьмите ее и отберите 20 яиц у Болотных Пауков в Топях Крумы.', 'Scale of drake zwov. Take this and recover 20 eggs from marsh spiders of Cruma Marshlands.', 'etc_scale_of_medusa_green_i00', 0);
INSERT INTO `all_items` VALUES (3825, 'Egg of Drake Zwov', NULL, 'Яйцо Дрейка Зуова, полученное при убийстве Болотного Паука.', 'Egg of drake zwov recovered from marsh spiders.', 'etc_dragon_egg_i04', 0);
INSERT INTO `all_items` VALUES (3826, 'Scale of Drake Kalibran', NULL, 'Чешуя Дрейка Калибрана. Возьмите ее и отберите 20 яиц у Придорожных Падальщиков возле Долины Смерти.', 'Scale of drake kalibran. Take this and recover 20 eggs from road scavengers near Corridor of Death.', 'etc_scale_of_medusa_red_i00', 0);
INSERT INTO `all_items` VALUES (3827, 'Egg of Drake Kalibran', NULL, 'Яйцо Дрейка Калибрана, полученное при убийстве Придорожного Падальщика.', 'Egg of drake kalibran recovered from road scavengers.', 'etc_dragon_egg_i01', 0);
INSERT INTO `all_items` VALUES (3828, 'Scale of Wyvern Suzet', NULL, 'Чешуя Виверны Сюзет. Возьмите ее и отберите 20 яиц у Владык Орков Брека к северу от Гирана.', 'Scale of wyvern suzet. Take this and recover 20 eggs from breka orc overlords in northern Giran.', 'etc_seed_yellow_i00', 0);
INSERT INTO `all_items` VALUES (3829, 'Egg of Wyvern Suzet', NULL, 'Яйцо Виверны Сюзет, полученное при убийстве Владыки Орков Брека.', 'Egg of wyvern suzet recovered from breka orc overlords.', 'etc_dragon_egg_i03', 0);
INSERT INTO `all_items` VALUES (3830, 'Scale of Wyvern Shamhai', NULL, 'Чешуя Виверны Шамхай. Возьмите ее и отберите 20 яиц у Поедателей Мертвечины в Земле Казненных.', 'Scale of wyvern shamhai. Take this and recover 20 eggs from deadseekers of the Execution Grounds.', 'etc_seed_red_i00', 0);
INSERT INTO `all_items` VALUES (3831, 'Egg of Wyvern Shamhai', NULL, 'Яйцо Виверны Шамхай, полученное при убийстве Поедателя Мертвечины.', 'Egg of wyvern shamhai recovered from deadseekers.', 'etc_dragon_egg_i00', 0);
INSERT INTO `all_items` VALUES (3832, 'Herb of Harit', NULL, 'Ингредиент противоядия. Соберите вовремя все ингредиенты для главы клана.', 'One ingredient of antidote. Take all four antidote ingredients to the clan leader within the time.', 'etc_herb_red_i00', 0);
INSERT INTO `all_items` VALUES (3833, 'Herb of Vanor', NULL, 'Ингредиент противоядия. Соберите вовремя все ингредиенты для главы клана.', 'One ingredient of antidote. Take all four antidote ingredients to the clan leader within the time.', 'etc_herb_green_i00', 0);
INSERT INTO `all_items` VALUES (3834, 'Herb of Oel Mahum', NULL, 'Ингредиент противоядия. Соберите вовремя все ингредиенты для главы клана.', 'One ingredient of antidote. Take all four antidote ingredients to the clan leader within the time.', 'etc_herb_blue_i00', 0);
INSERT INTO `all_items` VALUES (3835, 'Blood of Eva', NULL, 'Ингредиент противоядия. Соберите вовремя все ингредиенты для главы клана.', 'One ingredient of antidote. Take all four antidote ingredients to the clan leader within the time.', 'etc_dragon_blood_i00', 0);
INSERT INTO `all_items` VALUES (3836, 'Athrea\'s Coin', NULL, 'Если Вы соберете три такие монеты и отдадите их Ведьме Атрее, то получите Кровь Евы.', 'If you collect three Athrea\'s coins and take them to Witch Athrea, you will be able to obtain Eva\'s Blood.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (3837, 'Symbol of Loyalty', NULL, 'Знак, полученный в обмен на жизнь члена клана. Отнесите это главе клана.', 'Certificate exchanged for life of clan member. Take this to clan leader.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (3838, 'Recipe: Titan\'s Powerstone', NULL, 'Только для Гномов. Квестовый предмет. Рецепт создания Машины Гигантов. Требуется умение \"Создать Вещь\" 2-го уровня. Шанс создания: 25%.', 'For Dwarves only. Recipe for Quest. Required to make a Titan\'s Powerstone. Requires Create Item - Skill Level 2. The success rate is 25%.', 'etc_recipe_blue_i00', 5);
INSERT INTO `all_items` VALUES (3839, 'Mist Drake\'s Egg', NULL, 'Яйцо Туманного Дрейка. Глава клана должен собрать по 10 яиц каждого из 4 типов и отдать их Мартиену.', 'Egg of mist drake. The clan leader must collect ten of each of four kinds of eggs and take them to Martien.', 'etc_dragon_egg_i02', 0);
INSERT INTO `all_items` VALUES (3840, 'Blitz Wyrm Egg', NULL, 'Яйцо Стремительного Змея. Глава клана должен собрать по 10 яиц каждого из 4 типов и отдать их Мартиену.', 'Egg of blitz wyrm. The clan leader must collect ten of each of four kinds of eggs and take them to Martien.', 'etc_dragon_egg_i01', 0);
INSERT INTO `all_items` VALUES (3841, 'Drake\'s Egg', NULL, 'Яйцо Дрейка. Глава клана должен собрать по 10 яиц каждого из 4 типов и отдать их Мартиену.', 'Egg of drake. The clan leader must collect ten of each of four kinds of eggs and take them to Martien.', 'etc_dragon_egg_i00', 0);
INSERT INTO `all_items` VALUES (3842, 'Thunder Wyrm Egg', NULL, 'Яйцо Громового Змея. Глава клана должен собрать по 10 яиц каждого из 4 типов и отдать их Мартиену.', 'Egg of thunder wyrm. The clan leader must collect ten of each of four kinds of eggs and take them to Martien.', 'etc_dragon_egg_i03', 0);
INSERT INTO `all_items` VALUES (3843, 'Brooch of the Magpie', NULL, 'Перо, оставленное умирающим Гномом. Необходимо доставить его Кузнецу Кусто в Гиран.', 'This brooch that was left by a dying Dwarf to be delivered to Head Blacksmith Kusto, his younger brother in Giran Castle Town.', 'etc_feather_black_i00', 0);
INSERT INTO `all_items` VALUES (3844, 'Nebulite Crystals', NULL, 'Таинственный кристалл. Глава клана должен собрать 10 таких, а также Машины Гигантов, и отдать все это Бальтазару.', 'Soulshot of unknown identity. The clan leader must collect ten each of this and Titan\'s powerstones and take it all to Balthazar.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (3845, 'Broken Titan\'s Powerstone', NULL, 'Машина, когда-то изобретенная Гигантами. Сейчас ее невозможно использовать, потому что она сломана.', 'Titan\'s Powerstone. It is broken and useless.', 'etc_instrument_i00', 0);
INSERT INTO `all_items` VALUES (3846, 'Titan\'s Powerstone', NULL, 'Машина, когда-то изобретенная Гигантами. Глава клана должен собрать 10 таких, а также 10 Кристаллов Небулита, и отдать все это Бальтазару.', 'Titan\'s Powerstone. The clan leader must collect ten of these and also, ten Nebulite Crystals and take them all to Balthazar.', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (3847, 'Imperial Key', NULL, 'Ключ от имперского гроба. Чтобы открыть гроб, нужно 6 таких ключей.', 'Key used when opening imperial coffer. Must have all six to open the coffer.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (3848, 'Undead Ash', NULL, 'Прах, оставшийся от уничтоженной нежити Земли Казненных. Собирайте их, а затем отдайте Капитану Наемников Софии.', 'Ash dust remaining after an undead of the Execution Grounds is destroyed. Collect this and take it to Mercenary Sophya.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (3849, 'Bloody Axe Insignia', NULL, 'Эмблема, полученная при убийстве Гноллов в Укреплении Партизан. Собирайте их, а затем отдайте Капитану Наемников Софии.', 'Insignia obtained from killing Ol Mahums in the Fortress of Resistance. Collect these and take them to Mercenary Sophya.', 'etc_badge_black_i00', 0);
INSERT INTO `all_items` VALUES (3850, 'Delu Lizardman Fang', NULL, 'Клык, вырванный у мертвого Ящера Делу. Собирайте их, а затем отдайте Капитану Наемников Софии.', 'Tooth removed after killing a Delu Lizardman. Collect these and take them to Mercenary Sophya.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (3851, 'Stakato Talon', NULL, 'Коготь, вырезанный у Болотного Стакато в Топях Крумы. Собирайте их, а затем отдайте Капитану Наемников Софии.', 'Claw cut off after killing marsh stakatos of the Cruma Marshlands. Collect this and take it to Mercenary Sophya.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (3852, 'Feather of Gabrielle', NULL, 'Метка, полученная у Габриэль. Получите признание Вашего мастерства, встретившись с другими стражниками.', 'Mark given by Seal Guardian Gabrielle. Receive recognition for your abilities after taking this and meeting the other guardians.', 'etc_feather_gold_i00', 0);
INSERT INTO `all_items` VALUES (3853, 'Marsh Stalker Horn', NULL, 'Рог, отрезанный у мертвого Болотного Сталкера. Отдайте его Магистру Каене, Смотрителю Печати.', 'The horn that was cut off of a marsh stalker after it was killed. Take it to Magister Kaiena, the Watchman of the Seal.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (3854, 'Marsh Drake Talons', NULL, 'Коготь, вырезанный у мертвого Болотного Дрейка. Отдайте его Магистру Каене, Смотрителю Печати.', 'The talons that were removed from a marsh drake after it was killed. Take them to Magister Kaiena, the Watchman of the Seal.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (3855, 'Kranrot Skin', NULL, 'Шкура Медведя Зомби. Отдайте ее Префекту Чакирису, Смотрителю Печати.', 'The skin that was removed from a Kranrot after it was killed. Take it to Prefect Chakiris, the Watchman of the Seal.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (3856, 'Hamrut Leg', NULL, 'Лапка, отрезанная у Паука Зомби. Отдайте ее Префекту Чакирису, Смотрителю Печати.', 'The leg that was removed from a Hamrut and skinned after it was killed. Take it to Prefect Chakiris, the Watchman of the Seal.', 'etc_insect_leg_i00', 0);
INSERT INTO `all_items` VALUES (3857, 'Remains of Sacrifice', NULL, 'Останки распятого. Отдайте их Верховному Жрецу Орвену, Смотрителю Печати.', 'The remains of a sacrified soul. Take them to High Priest Orven, the Watchman of the Seal.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (3858, 'Totem of Land Dragon', NULL, 'Тотем, созданный Ящерами Харит, подданными Антараса. Отдайте его Мастеру Кендре, Смотрителю Печати.', 'The totem created by Harit lizardmen who worship Antharas. Take it to Master Kendra the Watchman of the Seal.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (3859, '1st Fragment of Abyss Jewel', NULL, 'Осколок разбитого Камня Бездны Глудио. Отдайте его Начальнику Склада Моку, Смотрителю Печати.', 'A fragment obtained by destroying an abyss jewel in Gludio. Take it to Warehouse Chief Moke, the Watchman of the Seal.', 'etc_broken_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (3860, '2nd Fragment of Abyss Jewel', NULL, 'Осколок разбитого Камня Бездны Орена Отдайте его Кузнецу Хельтону, Смотрителю Печати.', 'A fragment obtained by destroying an abyss jewel in Oren. Take it to Blacksmith Helton, the Watchman of the Seal.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (3861, '3rd Fragment of Abyss Jewel', NULL, 'Осколок разбитого Камня Бездны. Отдайте его Смотрителю Антараса Теодрику у входа в Логово Антараса.', 'Fragment obtained from destroying abyss jewel. Take this to Antharas Watchman Theodric at the entrance to Antharas\' Lair.', 'etc_broken_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (3862, 'Mara Fang', NULL, 'Доказательство убийства Стражника Камня Мары. Отдайте его Начальнику Склада Моку, Смотрителю Печати.', 'The proof obtained after killing jewel guardian Mara. Take it to Warehouse Chief Moke, the Watchman of the Seal.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (3863, 'Musfel Fang', NULL, 'Доказательство убийства Стражника Камня Мусфела. Отдайте его Кузнецу Хельтону, Смотрителю Печати.', 'The proof obtained after killing jewel guardian Musfel. Take it to Blacksmith Helton, the Watchman of the Seal.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (3864, 'Mark of Watchman', NULL, 'Сертификат признания Хранителя Печати. Возвращайтесь к Габриэль после получения таких знаков от Хранителей в каждой области.', 'Certificate of having been recognized by seal guardian. Return to Gabrielle after receiving certificates from guardians of each region.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (3865, 'Portal Stone', NULL, 'Предмет, необходимый для активации Кристалла Телепортации, переносящего в Логово Антараса.', 'Item needed to activate the teleport crystal that teleports to Antharas\' Lair.', 'etc_plate_blue_i00', 0);
INSERT INTO `all_items` VALUES (3866, 'Gustav\'s 1st Letter', NULL, 'Тайное письмо от сэра Густава Атебальта, адресованное его помощникам. Отдайте его Мартиену из Гирана.', 'A secret letter sent by Sir Gustav Athebaldt to his aides. Get a hold of it and take it to Martien of the Town of Giran.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3867, 'Gustav\'s 2nd Letter', NULL, 'Тайное письмо от сэра Густава Атебальта, адресованное его помощникам. Отдайте его Бальтазару из Деревни Охотников.', 'A letter sent by Sir Gustav Athebaldt to those supporting him. Take it to Balthazar of Hunter Village.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3868, 'Gustav\'s 3rd Letter', NULL, 'Тайное письмо от сэра Густава Атебальта, адресованное его помощникам. Отдайте его сэру Эрику Родемаи из Адена.', 'A letter sent by Sir Gustav Athebaldt to those supporting him. Take it to Sir Eric Rodemai of the Town of Aden.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (3869, 'Scepter of Judgment', NULL, 'Статуэтка, дарованная Императору древней империи Эльмореден Шунайману богиней света. Символ императорской власти.', 'Scepter bestowed on Founding Emperor Shunaiman of the ancient Elmoreden Empire by the god of light. Certificate representing the emperor\'s authority.', 'etc_royal_seal_of_lord_i04', 0);
INSERT INTO `all_items` VALUES (3870, 'Seal of Aspiration', NULL, 'Предмет, необходимый для развития клана до 5-го уровня.', 'Item needed for a clan leader to raise the clan to level 5.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (3871, 'Black Anvil Coin', NULL, 'Подарочная монета, даруемая в знак благодарности Гильдией Черной Наковальни.', 'Commemorative coin given as an expression of gratitude by the Black Anvil Guild.', 'etc_coins_blue_i00', 0);
INSERT INTO `all_items` VALUES (3872, 'Antidote Recipe List', NULL, 'Растение Ванор, Растение Сфинксов, Растение Харит и Кровь Евы.', 'Herb of Vanor, herb of oel mahum, herb of harit and blood of Eva.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3873, 'Voucher of Faith', NULL, 'Документ, позволяющий получить Манифест Альянса у сэра Кристофа Родемаи.', 'If you take this document to Sir Kristof Rodemai, you will receive the Alliance Manifesto.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (3874, 'Alliance Manifesto', NULL, 'Предмет, необходимый для развития клана до 4-го уровня.', 'Item needed for a clan leader to raise the clan to level 4.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (3875, 'L2Day - A', NULL, 'Предмет для ивента \"День L2\". Составьте определенное слово, отдайте его Коллекционеру Письмен \"Кошка-Ангел\" и получите подарок!', 'L2 Day event item. Create the special word and take it to the event coordinator for a surprise gift!', 'etc_alphabet_a_i00', 0);
