INSERT INTO `all_items` VALUES (3889, 'Potion of Recovery', NULL, 'Лекарство, нейтрализующее яд Ведьмы Калис. Необходимо главе клана для исцеления.', 'Remedy that can neutralize the poison of Witch Kalis. If the clan leader uses this, the poisoning is healed.', 'etc_herb_green_i00', 3);
INSERT INTO `all_items` VALUES (3890, 'Herald of Slayer', NULL, 'Предмет, дающий право на участие в битве с Антарасом. Отнесите его Стражу Антараса Гильмору.', 'Certificate showing eligibility to participate in the group to conquer Antharas. Take this and go meet Antharas Watchman Gilmore.', 'etc_badge_silver_i00', 0);
