INSERT INTO `all_items` VALUES (3947, 'Blessed Spiritshot: No Grade', NULL, 'Капсула, в которой заключена сила древнего духа. Значительно увеличивает Маг. Атк. Используется с оружием без ранга.', 'The power of a higher-level spirit is bestowed upon a weapon, temporarily increasing its magic significantly. Used with No Grade weapons.', 'etc_spell_shot_white_i01', 0);
