INSERT INTO `all_items` VALUES (3996, 'Mercenary Posting Ticket (Teleporter1)', NULL, 'Позволяет телепортироваться во внутренний двор замка или к стражам. Размещается в Гиране внутри замка.', 'Placed in Giran, at the Teleporter or inside the castle, this ticket allows teleportation to the inner castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
