INSERT INTO `all_items` VALUES (4022, 'Mercenary Posting Ticket (Teleporter1)', NULL, 'Позволяет телепортироваться к восточным или западным воротам внутренней части замка, в залы или к стражам. Размещается в Адене внутри замка.', 'Placed in Aden, at the Teleporter or inside the castle, this ticket allows teleportation to the East or West Gate of the inner castle, the halls or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (4023, 'Mercenary Posting Ticket (Teleporter2)', NULL, 'Позволяет телепортироваться во внешний двор замка, к восточным воротам внутренней части замка, в залы или к стражам. Размещается в Адене внутри замка.', 'Placed in Aden, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the East Gate of the inner castle, the halls or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (4024, 'Mercenary Posting Ticket (Teleporter3)', NULL, 'Позволяет телепортироваться во внешний двор замка, к западным воротам внутренней части замка, в залы или к стражам. Размещается в Адене внутри замка.', 'Placed in Aden, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the West Gate of the inner castle, the halls or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (4025, 'Mercenary Posting Ticket (Teleporter4)', NULL, 'Позволяет телепортироваться во внешний двор замка, к западным или восточным воротам внутренней части замка или к стражам. Размещается в Адене внутри замка.', 'Placed in Aden, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the East or West Gate of the inner castle, or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (4026, 'Mercenary Posting Ticket (Teleporter5)', NULL, 'Позволяет телепортироваться во внешний двор замка, к западным или восточным воротам внутренней части замка или в залы. Размещается в Адене внутри замка.', 'Placed in Aden, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the East or West Gate of the inner castle, or the halls.', 'mticket_teleporter_fix_i00', 8);
