INSERT INTO `all_items` VALUES (4039, 'Mold Glue', NULL, 'Материал для создания различных вещей. Можно продать в Торговой Лавке.', 'Ingredient for making upper garment tools. Can also be sold at ordinary shops.', 'etc_reagent_red_i00', 6);
INSERT INTO `all_items` VALUES (4040, 'Mold Lubricant', NULL, 'Материал для создания различных вещей. Можно продать в Торговой Лавке.', 'Ingredient for making upper garment tools. Can also be sold at ordinary shops.', 'etc_reagent_gold_i00', 6);
