INSERT INTO `all_items` VALUES (4044, 'Thons', NULL, 'Кристалл, символизирующий выбор и понимание. Используется для создания предметов Ранга B или выше. Можно продать в Торговой Лавке.', 'Crystal representing choice and consciousness. Used for making items of B-Grade and above and can also be sold at ordinary shops.', 'etc_gem_clear_i00', 6);
