INSERT INTO `all_items` VALUES (4200, 'Spellbook: Restore Life', NULL, 'Книга, необходимая для изучения умения \"Пробудить Жизнь\". Профессия: Епископ.Необходимый уровень: 44.', 'Spellbook needed to learn Restore Life. Used by Bishops.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (4201, 'Spellbook: Resist Shock', NULL, 'Книга, необходимая для изучения умения \"Сопротивление Оглушению\". Профессия: Мудрец Евы.Необходимый уровень: 40.', 'Spellbook needed to learn Resist Shock. Used by Elven Elders.', 'etc_spell_books_white_i00', 0);
