INSERT INTO `all_items` VALUES (4204, 'Amulet: Pa\'agrio\'s Tact', NULL, 'Амулет, необходимый для изучения умения \"Ритм Паагрио\". Профессия: Верховный Шаман.Необходимый уровень: 40.', 'Amulet required for the Pa\'agrio\'s Tact spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
