INSERT INTO `all_items` VALUES (4206, 'Spellbook: Transfer Pain', NULL, 'Книга, необходимая для изучения умения \"Поделиться Болью\". Профессии: Некромант, Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 40.', 'Spellbook needed to learn Transfer Pain. Used by Necromancers, Warlocks, Elemental Summoners and Phantom Summoners.', 'etc_spell_books_summon_i00', 0);
