INSERT INTO `all_items` VALUES (4239, 'Blade Mold', NULL, 'Груз, который Торговец Ародин должен послать к Темным Эльфам. Найдите 20 таких и отнесите их Торговцу Тире.', 'Cargo that Trader Arodin needs to send to the Dark Elves. Find all 20 of them and take them to Trader Tyra.', 'etc_artisans_frame_i00', 0);
INSERT INTO `all_items` VALUES (4240, 'Tyra\'s Bill', NULL, 'Записка Тиры. Отнесите ее Торговцу Ародину в Глудин.', 'A note from Trader Tyra. Take it to Trader Arodin in Gludin Village.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (4241, 'Ranger\'s Report - Part 1', NULL, 'Первая часть доклада Рейнджера. Найдите все 4 части и отнесите их Стражу Альве.', 'First piece of a ranger\'s report. Find all 4 pieces and take them to Guard Alvah.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (4242, 'Ranger\'s Report - Part 2', NULL, 'Вторая часть доклада Рейнджера. Найдите все 4 части и отнесите их Стражу Альве.', 'Second piece of a ranger\'s report. Find all 4 pieces and take them to Guard Alvah.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (4243, 'Ranger\'s Report - Part 3', NULL, 'Третья часть доклада Рейнджера. Найдите все 4 части и отнесите их Стражу Альве.', 'Third piece of a ranger\'s report. Find all 4 pieces and take them to Guard Alvah.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (4244, 'Ranger\'s Report - Part 4', NULL, 'Четвертая часть доклада Рейнджера. Найдите все 4 части и отнесите их Стражу Альве.', 'Fourth piece of a ranger\'s report. Find all 4 pieces and take them to Guard Alvah.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (4245, 'Weapons Trade Contract', NULL, 'Контракт, полученный при убийстве Генерала Гноллов. На нем стоит печать Гномов. Отнесите его Стражу Альве.', 'The contract that was carried by an Ol Mahum General. It is stamped with the Mark of the Dwarves. Take it to Guard Alvah.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (4246, 'Attack Directives', NULL, 'Приказ, полученный при убийстве Генерала Гноллов. Отнесите его Стражу Альве.', 'An operation order that was carried by an Ol Mahum General. Take it to Guard Alvah.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (4247, 'Certificate of the Silver Scale Guild', NULL, 'Сертификат, который подтверждает членство в Гильдии Серебряных Весов.', 'Certificate that verifies one\'s membership to the Silver Scale Guild.', 'etc_crest_yellow_i00', 0);
INSERT INTO `all_items` VALUES (4248, 'Rolento\'s Cargobox', NULL, 'Снаряжение, которое Роленто обещал послать Оркам Турек. Сначала покажите его Стражу Альве.', 'The war supplies that the Dwarven trader Rolento promised to send to Turek orcs. First, show it to Guard Alvah.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (4249, 'Ol Mahum Captain\'s Head', NULL, 'Отрубленная голова Капитана Гноллов. Соберите 30 таких и отнесите Бураю.', 'A severed head of an ol mahum captain. Collect 30 of them and take them to Turek Chief Burai.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (4250, 'Jade Crystal', NULL, 'Нефрит из Волшебной Долины. Соберите их и отнесите Бентли в Деревню Охотников.', 'Jade gemstone from the Enchanted Valley. Collect them and take them to Bentley of Hunters Village.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (4251, 'Ancient Statue of Goddess', NULL, 'Статуя богини старой империи, которая была обнаружена в кладбище. Отнесите это Жрице Флавнии в Аден.', 'A statue of a goddess from an old empire that has been discovered in the cemetery. Take it to Priestess Flownia of Aden Castle Town.', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4252, 'GalfRedo Romer\'s Bust', NULL, 'Статуя, созданная древним скульптором Бероной. Отнесите ее Торговцу Галибредо в Орен.', 'A statue created by the ancient sculptor Berona. Take it to Trader Galibredo of the Town of Oren.', 'etc_holy_statue_silver_i00', 0);
INSERT INTO `all_items` VALUES (4253, 'Eye of the Shadow', NULL, 'Глаз, полученный при убийстве Тени. Соберите 50 таких и отнесите их Смотрителю Склада Соринту.', 'Collect 50 eyes of the Shadow and take them to Warehouse Keeper Sorint.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (4254, 'Certificate of Participation: Battle Royal', NULL, 'Свидетельство, которое позволяет участвовать в Королевской Битве (игра для Нумизматов I Степени).', 'The certificate that allows one to participate in a Battle Royal. This game is played by grade 1 members of the Coin Collectors Club.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (4255, 'Trade Cargo', NULL, 'Груз, который был украден из фургонов Торговой Гильдии. Соберите 30 ящиков и отнесите их Стражу Вейсу.', 'The cargo boxes that have been robbed from the wagon of the Trade Guild. Collect 30 of them and take them to Guard Weisz.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (4256, 'Agnes\'s Holy Symbol', NULL, 'Распятие богини Эйнхасад. Эту статуэтку оставила жрица Агнес после своей смерти. Отнесите ее вместе с Амулетом Агнес Жрецу Адониусу.', 'The Crucifix of the goddess of Einhasad. This article was left by Priestess Agnes after her death. Take it along with Agnes\'s Rosary to Priest Adonius.', 'etc_statue_of_einhasad_bronze_i00', 0);
INSERT INTO `all_items` VALUES (4257, 'Agnes\'s Rosary', NULL, 'Амулет Жрицы Агнес, оставшийся после ее смерти. Отнесите это вместе со Святым Знаком Агнес Жрецу Адонису.', 'A rosary used while praying. It was left by Priestess Agnes after her death. Take it along with the Crucifix of the goddess of Einhasad to Priest Adonius.', 'etc_evil_necklace_i00', 0);
INSERT INTO `all_items` VALUES (4258, 'Sinister Totem', NULL, 'Черный тотем, источающий злую ауру. Отнесите его Верховной Жрице Левиан.', 'A black colored totem that exudes an evil aura. Take it to High Priestess Levian.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (4259, 'Bear Skin', NULL, 'Шкура медведя. Соберите 20 таких и отнесите их Бакалейщику Пано в Флоран.', 'The pelts obtained by hunting bears. Collect 20 of them and take them to Grocer Pano of Floran Village.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (4260, 'Enku Orc\'s Head', NULL, 'Отрубленная голова Орка Энку. Соберите 100 таких и отнесите их Дженнифер.', 'Beheaded head of an Enku Orc. Collect 100 of them and take them to Orc Lady Jennifer.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (4261, 'Orc Heads Bouquet -1', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Понтифику Дрикусу от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to High Prefect Drikus.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4262, 'Orc Heads Bouquet -2', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Жрецу Мануэлю от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Priest Manuel.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4263, 'Orc Heads Bouquet -3', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Главе Вуку Дрико от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Vuku Chief Driko.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4264, 'Orc Heads Bouquet -4', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Пророку Сомаку от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Seer Somak.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4265, 'Orc Heads Bouquet -5', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Префекту Доки от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Prefect Dowki.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4266, 'Orc Heads Bouquet -6', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Смотрителю Эндриго от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Warden Endrigo.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4267, 'Orc Heads Bouquet -7', NULL, 'Букет, сделанный из 100 голов Орков. Доставьте это Капитану Лукасу от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'A bouquet made by tying 100 orc heads together. On behalf of Jennifer who is shy, deliver it to Captain Lucas.', 'etc_flower_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (4268, 'Jennifer\'s Box', NULL, 'Коробка, которую кто-то попросил доставить Леди Орку Дженнифер. Интересно, что там внутри?..', 'The box that a man who is smitten by Orc Lady Jennifer asked this to be delivered to her. What do you think is in the box...?', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (4269, 'Articles of Dead Heroes', NULL, 'Вещи солдат, погибших во время экспедиции тысячу лет назад. Они были собраны во время охоты на Пещерных Слуг. Отнесите их Смотрителю Антараса Гильмору.', 'The articles of dead soldiers who were sent as an expeditionary force 1,000 years ago. These articles have been collected by hunting cave servants. Take them to Antharas Watchman Gilmore.', 'etc_squares_gray_i00', 0);
INSERT INTO `all_items` VALUES (4270, 'Old Key', NULL, 'Вещь мертвого солдата. Его потомок, сэр Кристоф Родемаи, живет в Гиране. Отнесите это ему.', 'An article left by a dead soldier. His descendent Sir Kristof Rodemai is living in Giran Castle Town. Take it to him.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (4271, 'Old Hilt', NULL, 'Вещь мертвого солдата. Его потомок, Дуэлист Каен, живет в Орене. Отнесите это ему.', 'An article left by a dead soldier. His descendant Duelist Kaien is living in the Town of Oren. Take it to him.', 'etc_hilt_i00', 0);
INSERT INTO `all_items` VALUES (4272, 'Totem Necklace', NULL, 'Вещь мертвого солдата. Его потомок, Понтифик Гарварентс, живет в Деревне Охотников. Отнесите это ему.', 'An article left by a dead soldier. His descendent, High Prefect Garvarentz, is living in Hunters Village. Take it to him.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (4273, 'Einhasad Crucifix', NULL, 'Вещь мертвого солдата. Отнесите это Верховному Жрецу Храма Эйнхасад Орвену в Аден.', 'An article left by a dead soldier. Take it to High Priest Orven of Einhasad Temple in Aden Castle Town where the dead soldier used to be stationed.', 'etc_magic_coin_silver_i01', 0);
INSERT INTO `all_items` VALUES (4274, 'Victim\'s Arm Bone', NULL, 'Кость руки жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'The arm bone of a victim who has been eaten by a Crokian. Collect the five types of bones and take them to Xenovia.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (4275, 'Victim\'s Thigh Bone', NULL, 'Кость бедра жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'The thigh bone of a victim who has been eaten by a Crokian. Collect the five types of bones and take them to Xenovia.', 'etc_piece_bone_white_i00', 0);
INSERT INTO `all_items` VALUES (4276, 'Victim\'s Skull', NULL, 'Череп жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'The skull of a victim who has been eaten alive by a Crokian. Collect the five types of bones and take them to Xenovia.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (4277, 'Victim\'s Rib Bone', NULL, 'Кость ребра жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'The rib bone of a victim who has been eaten by a Crokian. Collect the five types of bones and take them to Xenovia.', 'etc_rib_white_i00', 0);
INSERT INTO `all_items` VALUES (4278, 'Victim\'s Spine', NULL, 'Позвоночник жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'The spine of a victim who has been eaten by a Crokian. Collect the five types of bones and take them to Xenovia.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (4279, 'Jar of Bones', NULL, 'Урна, в которой лежат кости всех жертв. Попросите Сумасшедшего Доктора Орфеуса воскресить их.', 'An urn that contains the bones of all the victims. Ask Mad Doctor Orpheus to resurrect the victims.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (4280, 'Useless Bone Pieces', NULL, 'Бесполезные части костей, полученные после охоты на Кроков. Если Вы отнесете их к Орфеусу, возможно, Вы получите что-нибудь в награду...', 'Useless bone pieces obtained after hunting Crokians. If you take them to Orpheus, perhaps something good will happen...?', 'etc_mithril_ore_i00', 0);
INSERT INTO `all_items` VALUES (4281, 'Powder to Summon Dead Souls', NULL, 'Волшебный порошок, купленный у Магистра Ксеновии. Бросьте это вместе с костями жертв в урну сумасшедшего доктора.', 'The magic powder bought from Magister Xenovia. Throw it along with the victims\' bones into the Psychic Medium\'s Urn.', 'etc_powder_black_i00', 0);
INSERT INTO `all_items` VALUES (4282, 'Sack of the Dead', NULL, 'Мешок, содержащий душу жертвы. Добавляется в урну. Отнесите это Кузнецу Дороти.', 'A sack containing a victim\'s soul. An urn was possessed by the victim\'s soul. Take it to Locksmith Dorothy.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (4283, 'Frog Prince', NULL, 'Чего же Вы ждете? Вы обещали помочь мне! Освободите меня от этого проклятия немедленно! Я должен стать прежним как можно скорее!', 'What are you waiting for? You promised to help me! Release me from this curse immediately! I must regain my appearance as soon as possible!!!', 'etc_q_frog_green_i00', 0);
INSERT INTO `all_items` VALUES (4284, 'Fly Powder', NULL, 'Порошок из сушеных мух. Используйте его, если потерпите неудачу в своей попытке вернуть лягушке прежний вид.', 'Powder made by grinding dried flies. Use it when you fail in your attempt to transform a frog.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (4285, 'Calculator', NULL, 'Последняя модель вычислительной машины. Отнесите это Кузнецу Брюнону.', 'The latest model of calculator. Take it to Blacksmith Brunon.', 'etc_calculator_i00', 0);
INSERT INTO `all_items` VALUES (4286, 'Gemstone Beast\'s Crystal', NULL, 'Кристалл, полученный при убийстве Самоцветного Зверя. Соберите 10 таких и отнесите Кузнецу Сильвере.', 'Crystal obtained by slaying a gemstone beast. Collect 10 of these and take them to Blacksmith Silvera.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (4287, 'Titan\'s Powerstone', NULL, 'Необычный камень, который был извлечен из трупа Гиганта. Отнесите его Магистру Ханелин.', 'The Titan\'s Powerstone that has been extracted from the corpse of a Giant. Take it to Magister Hanellin.', 'etc_instrument_i00', 0);
INSERT INTO `all_items` VALUES (4288, 'Hanellin\'s 1st Letter', NULL, 'Письмо, врученное Вам Ханелин. Отнесите его Магистру Харн в Деревню Темных Эльфов и получите у нее следующее задание.', 'A letter that Hanellin entrusted you with. Take it to Magister Harne of the Dark Elven Villlage and receive your next assignment from her.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (4289, 'Hanellin\'s 2nd Letter', NULL, 'Письмо, врученное Вам Ханелин. Отнесите его Клаудии Атебальт в Аден и получите у нее следующее задание.', 'A letter that Hanellin entrusted you with. Take it to Claudia Athebaldt of Aden Castle Town and receive your next assignment from her.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (4290, 'Hanellin\'s 3rd Letter', NULL, 'Письмо, врученное Вам Ханелин. Отнесите его Мартиену в Гиран и получите у него следующее задание.', 'A letter that Hanellin entrusted you with. Take it to Martien of the Giran Castle Town and receive your next assignment from him.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (4291, '1st Key of Ark', NULL, 'Ключ, найденный на теле Стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'The key that was found upon the corpse of the guardian of the sacred ark. Use this key to open the sacred ark and retrieve the sacred object.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (4292, '2nd Key of Ark', NULL, 'Ключ, полученный при убийстве Элберота, стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'The key that was taken after killing Elberos, the guardian of the sacred ark. Use the key to open the sacred ark and retrieve the sacred object.', 'etc_old_key_i00', 0);
INSERT INTO `all_items` VALUES (4293, '3rd Key of Ark', NULL, 'Ключ, полученный при убийстве Клыка Теней, стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'The key that was taken after killing Shadowfang, the guardian of the sacred ark. Use the key to open the sacred ark and retrieve the sacred object.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (4294, 'White Fabric', NULL, 'Большое полотно белой ткани, полученный от Магистра Ханелин. Убейте Шаманов и Повелителей Платинового Клана и пропитайте ткань их кровью.', 'A large piece of white cloth given by Magister Hanellin. Kill the Platinum Tribe Shamans and Overlords and soak the cloth with their blood.', 'etc_piece_of_cloth_white_i00', 0);
INSERT INTO `all_items` VALUES (4295, 'Blooded Fabric', NULL, 'Ткань, впитавшая в себя кровь Ангелов и Платинового Клана. По словам Ханелин, чтобы бросить вызов Баюму, Вы должны обернуть ее вокруг своего тела.', 'A piece of cloth soaked in the blood of angels and the Platinum race. Hanellin has told you that in order to challenge Baium, you must wrap this blood-soaked cloth around your body.', 'etc_piece_of_cloth_red_i00', 0);
INSERT INTO `all_items` VALUES (4296, 'Order of Gosta', NULL, 'Приказ, предписывающий охотиться на Ящеров Тасаба и Шаманов Ящеров Тасаба.', 'The order states that you should hunt Tasaba Lizardmen and Tasaba Lizardman Shaman and bring back their fangs as proof.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (4297, 'Lizard Fang', NULL, 'Клык, полученный при убийстве Ящеров Тасаба и Шаманов Ящеров Тасаба', 'The fangs that have been collected as proofs that Tasaba Lizardmen and Tasaba Lizardman Shaman have been hunted.', 'etc_molar_white_i00', 0);
INSERT INTO `all_items` VALUES (4298, 'Barrel of League', NULL, 'Груз, который, по-видимому, был украден из фургона Ясона Хейна Ящерами Тасаба.', 'This seems to be the cargo that was stolen from Iason Heine\'s wagon by Tasaba Lizardmen.', 'etc_wine_barrel_i00', 0);
INSERT INTO `all_items` VALUES (4299, 'Operation Document - 1/10', NULL, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'This document was found in the cargo of the Trade Guild. The document contains various information regarding Innadril. How could this have happened...?', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (4300, 'Operation Document - 2/10', NULL, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'This document was found in the cargo of the Trade Guild. The document contains various information regarding Innadril. How could this have happened...?', 'etc_piece_of_paper_white_i00', 0);
