INSERT INTO `all_items` VALUES (4308, 'Operation Document - 10/10', NULL, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'This document was found in the cargo of the Trade Guild. The document contains various information regarding Innadril. How could this have happened...?', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (4309, 'Completed Operation Order', NULL, 'Книга из 10 страниц заказов. Кому это отдать?..', 'A book consisting of 10 pages of operation orders bound together. Who should we take it to...?', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (4310, 'Iason Heine\'s Bill', NULL, 'Чек, на котором указана сумма в 1000 аден. Если Вы отнесете его Кузнецу Роману в Иннадрил, то сможете купить различные ингредиенты.', 'The bill\'s face value is 1,000 adena. If you take it to Roman of the Blacksmith Guild in Innadril, you can use it to purchase various ingredients.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (4311, 'Gillian\'s Diary', NULL, 'Дневник Джиллиана. Последняя запись была сделана год назад.', 'Gillian\'s diary. The last entry was made one year ago.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (4312, 'Gillian\'s Notes', NULL, 'Часть текста песни Джиллиана.', 'Partial lyrics of a song Gillian was jotting down.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (4313, 'Unfinished Music', NULL, 'Незаконченный текст песни, которую Джиллиан написал для своей возлюбленной.', 'An unfinished music score of a song that Gilian composed for a former lover.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4314, 'Gillian\'s Heart', NULL, 'Сердце, которое Джиллиан выбросил, чтобы забыть свою любовь. Верните его Призраку Джиллиана.', 'The heart that Gillian threw out to forget his feelings of love. Return it to the Revenant of Gillian.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (4315, 'Gandi Tribe\'s Relic', NULL, 'Священный предмет племени Ганди, отобранный у Людоедов. Отнесите его Вождю Ганди Чианте в Дион.', 'The sacred object of the Gandi Tribe that has been recovered from Bugbears. Take it to Gandi Chief Chianta in the Town of Dion.', 'etc_royal_seal_of_lord_i00', 0);
INSERT INTO `all_items` VALUES (4316, 'Swan\'s Flute', NULL, 'Флейта, которую Бард Свен хочет подарить Музыканту Нанарин.', 'A flute that Troubadour Swan had obtained as a gift for Musician Nanarin.', 'etc_dragon_flute_i00', 0);
INSERT INTO `all_items` VALUES (4317, 'Swan\'s Letter', NULL, 'Любовное письмо, которое Свен хочет послать Нанарин вместе с флейтой. Отнесите его Музыканту Нанарин.', 'A love letter that Troubadour Swan wants to send to Musician Nanarin along with the flute. Take them to Musician Nanarin.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (4318, 'Event Clothes', NULL, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'A gift that Musician Nanarin is sending to Musician Barbado. Take it to Barbado.', 'etc_ladys_dress_i00', 0);
INSERT INTO `all_items` VALUES (4319, 'Nanarin\'s Flute', NULL, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'A gift that Musician Nanarin is sending to Musician Barbado. Take it to Barbado.', 'etc_dragon_flute_i00', 0);
INSERT INTO `all_items` VALUES (4320, 'Sabrin\'s Black Beer', NULL, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'A gift that Musician Nanarin is sending to Musician Barbado. Take it to Barbado.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (4321, 'Stolen Black Beer', NULL, 'Темное пиво, украденное у Джонаса. Отнесите его Торговцу Сабрину.', 'Black beer that was stolen from Jonas. Take it to Trader Sabrin.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (4322, 'Stolen Event Clothes', NULL, 'Парадная одежда, украденная у Торговца Сони. Отдайте ее Стражу Ксаберу.', 'Event clothes that were stolen from Trader Sonia. Take them to Guard Xaber.', 'etc_ladys_dress_i00', 0);
INSERT INTO `all_items` VALUES (4323, 'Clothes Chest Key', NULL, 'Ключ Барда Свена. Используйте его, чтобы открыть сундук с одеждой и вернуть украденное.', 'The key given by Bard Swan. Use this key to open the clothes chest and retrieve the event clothes.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (4324, 'Beer Chest Key', NULL, 'Ключ Барда Свена. Используйте этот ключ, чтобы открыть пивное хранилище и забрать черное пиво.', 'The key given by Bard Swan. Use this key to open the beer chest and get the black beer out of it.', 'etc_old_key_i02', 0);
INSERT INTO `all_items` VALUES (4325, 'Fairy Leaf', NULL, 'Лист Феи Мимю. Нужно положить его на шею феи, чтобы излечить рану, нанесенную дракончиком.', 'A leaf given by Fairy Mimyu to put on the fairy\'s neck wound that was inflicted by a hatchling.', 'etc_leaf_green_i00', 0);
INSERT INTO `all_items` VALUES (4326, 'Ratman Scavenger\'s Skull', NULL, 'Голова Крысолюда Падальщика, добытая по приказу Катари Соберите 10 таких и отнесите их Катари.', 'Heads of Ratman Scavengers that you hunted after receiving a request from Katari. Collect 10 of them and take them to Katari.', 'etc_pet_arms_i04', 0);
INSERT INTO `all_items` VALUES (4327, 'Turek War Hound\'s Tail', NULL, 'Хвост Гончей Турек, пойманной по приказу Пиотура. Соберите 10 таких и отнесите их Пиотуру.', 'The tails of Turek war Hounds that Piotur asks you to catch. Collect 10 of them and take them to Piotur.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (4328, 'Tyrant Kingpin\'s Heart', NULL, 'Сердце Главного Тирана. Отнесите его Старейшине Казиану.', 'Tyrant Kingpin\'s Heart. Take it to Elder Casian.', 'etc_heart_i00', 0);
INSERT INTO `all_items` VALUES (4329, 'Trisalim Tarantula\'s Venom Sac', NULL, 'Ядовитая железа Тарантула Трисалим, убитого по приказу Магистра Джоан. Соберите 3 таких и отнесите их Магистру Джоан.', 'The venom sacs of Trisalim Tarantulas that Magister Joan asked you to hunt. Collect three and take them to Magister Joan.', 'etc_poison_pouch_i00', 0);
INSERT INTO `all_items` VALUES (4330, 'Penitent\'s Manacles', NULL, 'Тяжелый набор оков, сделанных по приказу Черного Судьи. Отнесите их Черному Судье.', 'A heavy set of manacles forged at the Black Judge\'s behest.  Take them to the Black Judge.', 'etc_leash_i00', 0);
INSERT INTO `all_items` VALUES (4331, 'Manual of Manacles', NULL, 'Заготовка Кузнеца - 1 шт., Сталь - 5 шт., Адамантитовый Слиток - 2 шт., Серебряный Слиток - 10 шт., Кокс - 10 шт.', 'Blacksmith\'s Frame x 1, Steel x 5, Adamantite Nugget x 2, Silver Nugget x 10, Cokes x 100', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (4332, 'Tarlk Amulet', NULL, 'Знак, который можно получить при убийстве Людоеда или Василиска Тарлк. Соберите 30 таких и отнесите их Глашатаю Холла Клана.', 'A mark that can be obtained by catching a Tarlk Bugbear or a Tarlk Basilisk. Collect 30 and take them to a Clan Hall Herald.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (4333, 'Contest Certificate', NULL, 'Свидетельство, дающее право охотиться на Василисков Тарлк в предварительном испытании Осады Холла Кланов.', 'A certificate that one can present to participate in the hunt for Tarlk Basilisks, a preliminary contest for a Clan Hall Siege War.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (4334, 'Ant\'s Ichor', NULL, 'Жидкость, извлеченная из Муравьев или Капитанов Муравьев. Соберите 20 порций и отнесите их Старейшине Казиану.', 'Bodily fluids extracted from ants or ant captains. Collect 20 and take them to Elder Casian.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (4335, 'Noble Ant\'s Nerve Tissue', NULL, 'Нервная ткань из головы Элитного Муравья. Отнесите ее Старейшине Казиану вместе с Сукровицей Муравья.', 'The nerve tissue harvested from a Noble Ant\'s head. Take it to Elder Casian along with the Ant\'s Ichor.', 'etc_bodypart_brain_i00', 0);
INSERT INTO `all_items` VALUES (4336, 'Casian\'s Enzyme', NULL, 'Фермент, созданный Старейшиной Казианом. Найдите Личинок Муравьев, спящих в Муравейнике, и управляйте ими с помощью фермента.', 'Enzyme created by Elder Casian. Find the Ant Larvae sleeping within the the Ant Nest Dungeon and administer the enzyme to them.', 'etc_spell_shot_silver_i00', 0);
INSERT INTO `all_items` VALUES (4337, 'Alligator Leather', NULL, 'Кожа Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'Pelts obtained from alligators caught on Alligator island. You can sell it to Enverun.', 'etc_scale_of_medusa_green_i00', 0);
INSERT INTO `all_items` VALUES (4338, 'Blue Back Alligator Leather', NULL, 'Кожа Синего Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'Leather from Blue Back Alligators caught on Alligator Island. You can sell it to Enberun at a high price.', 'etc_scale_of_medusa_blue_i00', 0);
INSERT INTO `all_items` VALUES (4339, 'Jewel Studded Alligator Leather', NULL, 'Кожа Драгоценного Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'A piece of Jewel Studded Alligator Leather caught on Alligator Island. You can sell it to Enberun at a high price.', 'etc_scale_of_medusa_red_i00', 0);
INSERT INTO `all_items` VALUES (4340, 'Certificate of Approval to Create a Belt', NULL, 'Если Вы соберете достаточное количество Шкур Аллигаторов и отдадите их Кожевнику Версу, он сделает для Вас пояс из кожи аллигатора.', 'If you take a sufficient amount of Alligator Leather and show it to Gabana, a master leather craftsman, you can have an Alligator Leather Belt made.', 'etc_recipe_red_i00', 0);
INSERT INTO `all_items` VALUES (4341, 'Certificate of Approval to Create a Purse', NULL, 'Если Вы соберете достаточное количество Шкур Аллигаторов и отдадите их Кожевнику Версу, он сделает для Вас сумочку из кожи аллигатора.', 'If you take a sufficient amount of Alligator Leather and show it to Gabana, a master leather craftsman, you can have an Alligator Leather Purse made.', 'etc_recipe_blue_i00', 0);
INSERT INTO `all_items` VALUES (4342, 'Water Crystal', NULL, 'Большой кристалл, который содержит энергию Воды. Возьмите его и найдите Сундук Воды.', 'A lump of crystal that contains the energy of water. You should find the Stone Statue of Water and dedicate it to the statue.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (4343, 'Fire Crystal', NULL, 'Большой кристалл, который содержит энергию Огня. Возьмите его и найдите Сундук Огня.', 'A lump of crystal that contains the energy of fire. You should find the Stone Statue of Fire and dedicate it to the statue.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (4344, 'Wind Crystal', NULL, 'Большой кристалл, который содержит энергию Ветра. Возьмите его и найдите Сундук Ветра.', 'A lump of crystal that contains the energy of wind. You should find the Stone Statue of Wind and dedicate it to the statue.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (4345, 'Earth Crystal', NULL, 'Большой кристалл, который содержит энергию Земли. Возьмите его и найдите Сундук Земли.', 'A lump of crystal that contains the energy of earth. You should find the Stone Statue of Earth and dedicate it to the statue.', 'etc_gem_yellow_i00', 0);
INSERT INTO `all_items` VALUES (4346, 'Dark Crystal', NULL, 'Большой кристалл, который содержит энергию Тьмы. Возьмите его и найдите Сундук Тьмы.', 'A lump of crystal that contains the energy of darkness You should find the Stone Statue of Darkness and dedicate it to the statue.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (4347, 'Crystal of Light', NULL, 'Большой кристалл, который содержит энергию Света. Возьмите его и найдите Сундук Света.', 'A lump of crystal that contains the energy of light. You should find the Stone Statue of Light and dedicate it to the statue.', 'etc_gem_black_i00', 0);
INSERT INTO `all_items` VALUES (4348, 'Jade Crystal', NULL, 'Нефритовый кристалл, найденный в Волшебной Долине. Соберите их и отнесите Бентли в Деревню Охотников.', 'Jade crystals that had been gathered from the Enchanted Valley. Collect them and take them to Bentley of Hunters Village.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (4349, 'Bust of Ancient Goddess', NULL, 'Статуя богини, которая была создана древним скульптором Бероной в древние времена.', 'A statue of a goddess that was created by the ancient sculptor Berona in ancient times.', 'etc_holy_statue_silver_i00', 0);
INSERT INTO `all_items` VALUES (4350, 'The Work of the ancient sculptor Berona', NULL, 'Статуя, созданная древним скульптором Бероной. Еще не оценена антикварами.', 'A statue created by the ancient sculptor Berona. It has not been evaluated by antique experts yet.', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4351, 'Ancient Statue of Goddess: Prototype', NULL, 'Статуя, созданная Бероной, древним скульптором, - опытный образец', 'A statue created by Berona, an ancient sculptor. - Prototype0', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4352, 'Ancient Statue of Goddess: Original', NULL, 'Статуя, созданная Бероной, древним скульптором, - оригинал.', 'A statue created by Berona, a sculptor in ancient times. - Original0', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4353, 'Ancient Statue of Goddess: Replica', NULL, 'Статуя, созданная современным скульптором, пытавшимся подражать Бероне.', 'Replicated statues that have been created by present day sculptors who imitated Berona\'s works.', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4354, 'Ancient Statue of Goddess: Forgery', NULL, 'Подделка, созданная современным скульптором.', 'Forgeries that have been created in imitation of the ancient sculptor Berona\'s works.', 'etc_statue_of_einhasad_gold_i00', 0);
INSERT INTO `all_items` VALUES (4355, 'Blue Eva', NULL, 'Особая монета.', 'Special Coin0', 'etc_magic_coin_blue_i01', 0);
INSERT INTO `all_items` VALUES (4356, 'Gold Einhasad', NULL, 'Особая монета.', 'Special Coin0', 'etc_magic_coin_gold_i02', 0);
INSERT INTO `all_items` VALUES (4357, 'Silver Shilen', NULL, 'Особая монета.', 'Special Coin0', 'etc_magic_coin_silver_i02', 0);
INSERT INTO `all_items` VALUES (4358, 'Bloody Pa\'agrio', NULL, 'Особая монета.', 'Special Coin0', 'etc_magic_coin_blood_i02', 0);
INSERT INTO `all_items` VALUES (4359, 'Barrel of Liquor', NULL, 'Очень тяжелая бочка, до краев наполненная восхитительным и ароматным ликером.', 'A barrel that is filled to the brim with delicious and fragrant liquor. The barrel is very heavy.', 'etc_wine_barrel_i00', 0);
INSERT INTO `all_items` VALUES (4360, 'Precious Scarab', NULL, 'Прозрачный и сияющий скарабей. Можно продать по высокой цене.', 'A scarab that is transparent and shines like a precious stone. Among hustlers it is traded at a high price.', 'etc_beetle_i00', 0);
INSERT INTO `all_items` VALUES (4361, 'Simbelmyne', NULL, 'Любимый цветок Эльфов, который, как полагают, может лечить болезни.', 'A type of flower that is believed to have the power to heal sickness. It is a favorite of elves.', 'etc_flower_i00', 0);
INSERT INTO `all_items` VALUES (4362, 'Odd (looking) Doll', NULL, 'Странная статуя живого существа, похожего на беса. Любимый предмет Орков.', 'It is a strange looking statue of a living creature that looks like an imp. It is an orc\'s favorite item.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (4363, 'Scarlet Dress', NULL, 'Очень красивое красное платье аденского стиля, сшитое для благородных леди.', 'A very attractive scarlet Aden-style dress designed for a virtuous lady.', 'etc_ladys_dress_i00', 0);
INSERT INTO `all_items` VALUES (4364, 'Nebulite Orb', NULL, 'Кусок небулита сферической формы. Отнесите его Магическому Торговцу Семе в Академию Хардина.', 'It is made by cutting Nebulite into a spherical shape. Take this to Magic Trader Cema in Hardin\'s Academy.', 'etc_crystal_ball_red_i00', 0);
INSERT INTO `all_items` VALUES (4365, 'Ectoplasm Liqueur', NULL, 'Экзотический ликер, приготовленный из эктоплазмы. Очень популярен среди ценителей.', 'An exotic tasting liqueur made from ectoplasm. Very popular among connoisseurs.', 'etc_dragon_blood_i00', 0);
INSERT INTO `all_items` VALUES (4366, 'Prince\'s Trophy', NULL, 'Трофей, который принц Мальком выиграл на танцевальном турнире. Вы можете продать его в магазин или сохранить как сувенир.', 'The winning trophy that Prince Malcom won in a dance competition. You can sell it at a store or keep it as a souvenir.', 'etc_trophy_i00', 0);
INSERT INTO `all_items` VALUES (4367, 'Prince\'s Autobiography', NULL, 'Автобиография принца Малькома с его личной подписью. Можно продать в Торговой Лавке.', 'The autobiography of Prince Malcom that bears his hand-written signature. Sell it at a store.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (4368, 'Prince\'s Bust', NULL, 'Статуя принца Малькома, сделанная из чистого золота. Весьма уродливая, но дорогая.', 'A statue of Prince Malcom made of pure gold. Although quite ugly, it will fetch a handsome price.', 'etc_holy_statue_gold_i00', 0);
INSERT INTO `all_items` VALUES (4369, 'Silk Handkerchief', NULL, 'Красивый носовой платок, украшенный цветочным узором и кружевами.', 'A beautiful and elaborate handkerchief decorated with a flower pattern and lace. Its design could attract the attention of princes and princesses.', 'etc_kerchief_i00', 0);
INSERT INTO `all_items` VALUES (4370, 'Luxurious Goblet', NULL, 'Роскошный кубок, созданный в период Империи Эльмореден.', 'A luxuriously designed goblet. It seems to be an object made during the period of the Elmo Aden Empire.', 'etc_holy_grail_i01', 0);
INSERT INTO `all_items` VALUES (4371, 'Scepter of Darkness', NULL, 'Скипетр, который излучает темную силу. На его ручке выгравировано: \"Великий Король Демонов\".', 'A staff that gives off dark magic power. On its handle, the words \"Great Demon King\" are engraved.', 'etc_imperial_scepter_i02', 0);
INSERT INTO `all_items` VALUES (4372, 'Succubus Perfume', NULL, 'Духи, используемые дворянками Суккубов. Имеют очень сильный аромат, неприятный для Эльфов и Людей.', 'Perfume used by Succubus noblewomen. A very strong fragrance, not popular among Elves and Humans.', 'etc_dragons_blood_i02', 0);
INSERT INTO `all_items` VALUES (4373, 'Succubus Mirror', NULL, 'Зеркало, используемое дворянками Суккубов, когда они наносят косметику.', 'A mirror used by Succubus noblewomen when they put on cosmetics. It is also said to be used occasionally by blood queens.', 'etc_mirror_i00', 0);
INSERT INTO `all_items` VALUES (4374, 'Heart of Darkness', NULL, 'Сердцевидный камень, который излучает темную силу. На нем выгравировано: \"Я люблю тебя, Меркенис!\".', 'A heart-shaped stone piece that gives off the aura of dark magic power. On its reverse, the words \"I love you Merkenis!\" are engraved.', 'etc_heart_i00', 0);
INSERT INTO `all_items` VALUES (4375, 'Royal Orc Totem', NULL, 'Тотем, сделанный из цельного куска красного гранита.', 'A totem made by carving out a whole lump of red granite.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (4376, 'Pearl Trodden/Trampled By A Wild Hog', NULL, 'Бусинка размером с грецкий орех, заляпанная грязью. Возможно, это жемчуг.', 'A walnut sized bead that is smeared with dirt. Perhaps, it is a pearl.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (4377, 'Boar\'s Tusk', NULL, 'Клык борова, похожий на бивень слона.', 'The tusk of a boar that looks somewhat similar to the ivory of an elephant.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (4378, 'Sweet Potato', NULL, 'Большая картошка, которую только что вытащили из земли. Поджарьте ее, и она станет очень вкусной.', 'A large sized sweet potato that was just plucked out of the soil. You s it or roast it. It will make a delicious treat.', 'etc_seed_yellow_i00', 0);
INSERT INTO `all_items` VALUES (4379, 'Beast\'s Claws', NULL, 'Острые когти белого льва. По слухам, высоко ценятся среди коллекционеров.', 'White lion\'s sharp claws. It is rumored that it is being traded among collectors at a high price.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (4380, 'Beast\'s Mane', NULL, 'Грива белого льва. По слухам, высоко ценится среди коллекционеров.', 'A white lion\'s luxuriant mane. It is rumored to be sold at a high price among collectors.', 'etc_metallic_fiber_i00', 0);
INSERT INTO `all_items` VALUES (4381, 'Ginseng Root', NULL, 'Редкий медицинский препарат, изготавливаемый где-то далеко на востоке.', 'Rare medicine imported from the Orient.', 'etc_ginseng_red_i00', 0);
INSERT INTO `all_items` VALUES (4382, 'Honey Jar', NULL, 'Банка, содержащая сладкий мед.', 'A jar containing sweet honey.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (4383, 'Bear\'s Gall', NULL, 'Желчь медведя, которая, как известно, очень эффективна для поддержания здоровья и хорошего самочувствия, так как обладает мистическими лечебными свойствами.', 'The gall of a bear that is known to be highly effective in promoting one\'s health and well-being as well as having mysterious healing properties.', 'etc_bodypart_liver_i00', 0);
INSERT INTO `all_items` VALUES (4384, 'Fresh Samon', NULL, 'Свежепойманный лосось.', 'A fresh salmon that seems to have been just caught from a river.', 'etc_fish_seawater_i01', 0);
INSERT INTO `all_items` VALUES (4385, 'Sushi Riceball', NULL, 'Суши из Шутгарта. Обладает восхитительным вкусом.', 'The Schuttgart type sushi rice ball. The delicious seasoning of well minced meat gets absorbed into the rice and produces a wonderful taste.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (4386, 'Avellan Spice', NULL, 'Экзотическая специя, которую привезли из Авеллы на востоке.', 'Exotic spice that has been imported from Avella of the Orient.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (4387, 'Lucky Rabbit Weed', NULL, 'Сорняк, который, как говорят, приносит удачу. Излюбленная пища кроликов.', 'Rabbit weed that is supposed to bring luck. It is the favorite food of rabbits and elpys.', 'etc_herb_green_i00', 0);
INSERT INTO `all_items` VALUES (4388, 'Malcom\'s Check', NULL, 'Чек на большую сумму, подписанный принцем Малькомом. Может быть обналичен в хранилище Гирана.', 'A check of tremendous face value signed by Prince Malcom. It can be cashed at a warehouse in Giran Castle Town.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (4389, 'Deposit Box Key', NULL, 'Ключ от частного сейфа в хранилище Гирана.', 'A key for a private deposit box located in a warehouse in Giran Castle Town.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (4390, 'Dwarven Royal Seal', NULL, 'Королевская печать, сделанная из нефрита. На ней выгравирована эмблема королевской семьи Гномов.', 'A royal seal made of carved jade. It is engraved with the seal of the Dwarven royal family.', 'etc_royal_seal_of_lord_i04', 0);
INSERT INTO `all_items` VALUES (4391, 'Dwarven Royal Crown', NULL, 'Золотая королевская корона. На ней выгравирована эмблема королевской семьи Гномов.', 'A king\'s crown made of gold. It is engraved with the seal of the Dwarven royal family.', 'etc_ancient_crown_i02', 0);
INSERT INTO `all_items` VALUES (4392, 'Dwarven Dance Manual', NULL, 'Учебник по танцам. С его помощью Вы легко сможете достичь вершин танцевального искусства!', 'A dance manual that details ballroom dancing techniques. This book will make you a dancing hero!', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (4393, 'Calculator', NULL, 'Позволяет выполнять простые вычисления.', 'Allows one to perform a simple calculation.', 'etc_calculator_i00', 0);
INSERT INTO `all_items` VALUES (4394, 'Hanellin\'s White Flower', NULL, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Желтый и Красный Цветки Ханелин.', 'A mark of Hannelin. Along with your companions each carrying a red flower and yellow flower respectively, go to Aden Castle Town to see her.', 'etc_flower_i00', 0);
INSERT INTO `all_items` VALUES (4395, 'Hanellin\'s Red Flower', NULL, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Белый и Желтый Цветки Ханелин.', 'A mark of Hannelin. Along with your companions each carrying a white flower and yellow flower respectively, go to Aden Castle Town to see her.', 'etc_flower_i01', 0);
INSERT INTO `all_items` VALUES (4396, 'Hanellin\'s Yellow Flower', NULL, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Белый и Красный Цветки Ханелин.', 'A mark of Hannelin. Along with your companions each carrying a white flower and red flower respectively, go to Aden Castle Town to see her.', 'etc_flower_i02', 0);
INSERT INTO `all_items` VALUES (4397, 'Book of Saint', NULL, 'Книга Святого Солина. Отнесите это Магистру Ханелин вместе с Кровью Святого и Ветвью Святого.', 'The book of Saint Solina. Take it along with the blood of a Saint and the bough of a Saint to Magister Hanellin.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (4398, 'Blood of Saint', NULL, 'Кровь Святого Солина в стеклянной бутылке. Отнесите это Магистру Ханелин вместе с Книгой Святого и Ветвью Святого.', 'The blood of Saint Solina, hardened into a dark-colored substance contained in a glass bottle. Take it, along with the Book of Saint and the Bough of Saint to Magister Hanellin.', 'etc_dragons_blood_i00', 0);
INSERT INTO `all_items` VALUES (4399, 'Bough of Saint', NULL, 'Скипетр Святого Солина. Выглядит как обычная сухая ветка дерева. Отнесите это Магистру Ханелин вместе с Книгой Святого и Кровью Святого.', 'The Scepter of Saint Solina. It appears to be just a dead dry tree branch. Take it along with the book of a Saint and the blood of a Saint and take it to Magister Hanellin.', 'etc_branch_gold_i00', 0);
INSERT INTO `all_items` VALUES (4400, 'White Fabric', NULL, 'Большое полотно белой ткани, полученное у Магистра Ханелин. Она расскажет Вам, что делать дальше.', 'A large piece of white cloth given by Magister Hanellin. Hanellin will tell you its purpose.', 'etc_piece_of_cloth_white_i00', 0);
INSERT INTO `all_items` VALUES (4401, 'Green Dimensional Stone', NULL, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 1~3 этажи Башни Дерзости.', 'Activates a Dimensional Vortex. Allows you to move to the first floor of the Tower of Insolence.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (4402, 'Blue Dimensional Stone', NULL, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 4~6 этажи Башни Дерзости.', 'Activates a Dimensional Vortex. Allows you to move to the fifth floor of the Tower of Insolence.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (4403, 'Red Dimensional Stone', NULL, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 7~10 этажи Башни Дерзости.', 'Activates a Dimensional Vortex. Allows you to move to the 10th floor of the Tower of Insolence.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (4404, 'Green Dimensional Stone - Shard', NULL, 'Осколок Зеленого Камня Иных Миров. Соберите их и отнесите Исследователю Каплану.', 'A broken shard of the green Dimensional Stone. Collect these and take them to Researcher Kaplan.', 'etc_broken_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (4405, 'Blue Dimensional Stone - Shard', NULL, 'Осколок Синего Камня Иных Миров. Соберите их и отнесите Исследователю Окли.', 'A broken shard of the blue Dimensional Stone. Collect these and take them to Researcher Euclie.', 'etc_broken_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (4406, 'Red Dimensional Stone - Shard', NULL, 'Осколок Красного Камня Иных Миров. Соберите их и отнесите Исследователю Питгону.', 'A broken shard of the red Dimensional Stone. Collect these and take them to Researcher Pitagon.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (4407, 'Bill of Iason Heine', NULL, 'Счет, который можно обменять на 1000 аден у Кузнеца Романа из Иннадрила. Также на него можно купить разные материалы.', 'Its value is 1000 adena, redeemable by Roman of the Blacksmith Guild in Innadril. You can use it to buy various ingredients.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (4408, 'Musical Score - Theme of Love', NULL, 'Посмертно выпущенная музыкальная композиция Джиллиана. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'Posthumously released musical score of Gillian. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4409, 'Musical Score - Theme of Battle', NULL, 'Музыкальная композиция военного марша пламени. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'The musical score for the Battle March of Flames. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4410, 'Musical Score - Theme of Journey', NULL, 'Музыкальная композиция Барда Свена. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'A musical score composed by Troubadour Swan. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4411, 'Echo Crystal - Theme of Journey', NULL, 'Музыкальный кристалл, который играет музыку на тему путешествий. Исчезает после использования.', 'An echo crystal that plays the theme music of a journey. May only be used once.', 'etc_echo_crystal_i00', 0);
INSERT INTO `all_items` VALUES (4412, 'Echo Crystal - Theme of Battle', NULL, 'Музыкальный кристалл, который играет музыку на тему сражений.', 'An echo crystal that plays the theme music of a battle.', 'etc_echo_crystal_i01', 0);
INSERT INTO `all_items` VALUES (4413, 'Echo Crystal - Theme of Love', NULL, 'Музыкальный кристалл, который играет музыку на тему любви. Исчезает после использования.', 'An echo crystal that plays the theme music of love. May only be used once.', 'etc_echo_crystal_i02', 0);
INSERT INTO `all_items` VALUES (4414, 'Echo Crystal - Theme of Solitude', NULL, 'Музыкальный кристалл, который играет музыку на тему одиночества. Исчезает после использования.', 'An echo crystal that plays the theme music of solitude. May only be used once.', 'etc_echo_crystal_i03', 0);
INSERT INTO `all_items` VALUES (4415, 'Echo Crystal - Theme of the Feast', NULL, 'Музыкальный кристалл, который играет музыку на тему фестиваля. Исчезает после использования.', 'An echo crystal that plays the theme music of a feast. May only be used once.', 'etc_echo_crystal_i04', 0);
INSERT INTO `all_items` VALUES (4416, 'Echo Crystal - Theme of Celebration', NULL, 'Музыкальный кристалл, который играет музыку на тему праздника. Исчезает после использования.', 'An echo crystal that plays the theme music of a celebration. May only be used once.', 'etc_echo_crystal_i00', 0);
INSERT INTO `all_items` VALUES (4417, 'Echo Crystal - Theme of Comedy', NULL, 'Музыкальный кристалл, который играет музыку на тему комедии. Исчезает после использования.', 'An echo crystal that plays the theme music of a comedy. May only be used once.', 'etc_echo_crystal_i01', 0);
INSERT INTO `all_items` VALUES (4418, 'Musical Score - Theme of Celebration', NULL, 'Праздничная музыкальная композиция. Если отнести это композитору, то можно получить музыкальный кристалл.', 'A musical score containing the theme music of a celebration. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4419, 'Musical Score - Theme of Comedy', NULL, 'Веселая музыкальная композиция. Если отнести это композитору, то можно получить музыкальный кристалл.', 'A musical score containing the theme music of a comedy. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4420, 'Musical Score - Theme of Solitude', NULL, 'Музыкальная композиция, составленная Нанарин. Если отнести это композитору, то можно получить музыкальный кристалл.', 'A musical score composed by Musician Nanarin. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i01', 0);
INSERT INTO `all_items` VALUES (4421, 'Musical Score - Theme of the Feast', NULL, 'Музыкальная композиция, составленная Барбадо. Если отнести это композитору, то можно получить музыкальный кристалл.', 'A musical score composed by Musician Barbado. If you take it to Maestro Melody, you can have an echo crystal made.', 'etc_musical_note_i02', 0);
INSERT INTO `all_items` VALUES (4422, 'Dragon Bugle of Wind', NULL, 'Горн для призыва Дракона Ветра. Питомец забирает часть опыта, заработанного хозяином.', 'A bugle used to play the strider of the Wind.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (4423, 'Dragon Bugle of Star', NULL, 'Горн для призыва Дракона Звезд. Питомец забирает часть опыта, заработанного хозяином.', 'A bugle used to play the strider of a Star.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (4424, 'Dragon Bugle of Twilight', NULL, 'Горн для призыва Дракона Сумерек. Питомец забирает часть опыта, заработанного хозяином.', 'A bugle used to play the strider of the Dusk.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (4425, 'Penitent\'s Manacles', NULL, 'Тяжелые наручники для призыва Чревоугодника. Чревоугодник поглощает весь опыт призывателя. Питается пищей для волков.', 'The heavy manacles used to summon a Sin Eater. Summoning the Sin Eater consumes all the summoner\'s Exp. The Sin Eater must be fed Food for Wolves.', 'etc_leash_i00', 7);
INSERT INTO `all_items` VALUES (4426, 'Manacles of Penitent', NULL, 'Кандалы, оставшиеся после исчезновения Чревоугодника. Для повторения квеста отнесите их Черному Судье.', 'Having consumed your sins, the Sin Eater has disappeared, leaving you with this ordinary pair of manacles.  To repeat this quest, take them back to the Black Judge.', 'etc_leash_i00', 0);
INSERT INTO `all_items` VALUES (4427, 'Alligator Leather Belt', NULL, 'Ремень из кожи Аллигатора, сделанный Кожевником Версом.', 'An Alligator Leather Belt designed and created by Verche, a master leather craftsman.', 'etc_prefect_belt_i00', 0);
INSERT INTO `all_items` VALUES (4428, 'Blue Alligator Leather Belt', NULL, 'Ремень, сделанный Кожевником Версом. Изготовлен из кожи редкого Синего Аллигатора.', 'An Alligator Leather Belt designed and created by Verche, a master leather craftsman. It is made from a rare blue type of Leather.', 'etc_prefect_belt_i00', 0);
INSERT INTO `all_items` VALUES (4429, 'Bejeweled Leather Belt', NULL, 'Ремень, сделанный Кожевником Версом. Изготовлен из кожи Драгоценного Аллигатора.', 'An Alligator Leather Belt designed and created by Verche, a master leather craftsman. It is made from a Leather that is studded with rare jewels.', 'etc_prefect_belt_i00', 0);
INSERT INTO `all_items` VALUES (4430, 'Alligator Leather Purse', NULL, 'Сумочка из кожи Аллигатора, сделанная Кожевником Версом.', 'An Alligator Leather Purse designed and created by Verche, a master leather craftsman.', 'etc_handbag_i00', 0);
INSERT INTO `all_items` VALUES (4431, 'Blue Alligator Leather Purse', NULL, 'Сумочка из кожи Синего Аллигатора, сделанная Кожевником Версом.', 'An Alligator Leather Purse designed and created by Verche, a master leather craftsman. It is made from a rare blue type of Leather.', 'etc_handbag_i00', 0);
INSERT INTO `all_items` VALUES (4432, 'Bejeweled Purse', NULL, 'Сумочка из кожи Драгоценного Аллигатора, сделанная Кожевником Версом.', 'An Alligator Leather Purse designed and created by Verche, a master leather craftsman. It is made of Leather studded with rare jewels.', 'etc_handbag_i00', 0);
INSERT INTO `all_items` VALUES (4433, 'Elemental Stone Powder', NULL, 'Порошок из Камня Стихии, полученный из каменной статуи в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'Elemental stone powder obtained from a stone statue in the Forgotten Temple. Can be sold at any store or taken to Magister Nell.', 'etc_powder_white_i00', 0);
INSERT INTO `all_items` VALUES (4434, 'Elemental Stone Shards', NULL, 'Осколки Камня Стихии, полученные из каменных статуй в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'The shards of elemental stones obtained from stone statues in the Forgotten Temple. Can be sold at any store or taken to Magister Nell.', 'etc_broken_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (4435, 'Elemental Stone Lump', NULL, 'Кусок Камня стихии, полученный из каменных статуй в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'The lumps of elemental stone obtained from stone statues in the Forgotten Temple. Can be sold at any store or taken to Magister Nell.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (4436, 'Bentley\'s Request', NULL, 'Просьба найти и вернуть нефритовые кристаллы от обитателей Волшебной Долины, таких, как Мара, Утопленница, Сатир и др..', 'A request to find and bring back jade crystals from creatures such as Fline, Liele, Satyr etc. that inhabit the Enchanted Valley.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (4437, 'Carson\'s Request', NULL, 'Просьба отобрать работы древнего скульптора Бероны у Крысолюдов Хатар и Фавнов Ванор, обитающих около Кладбища.', 'A request to recover the works of the ancient sculptor Berona from Hatar Ratmen and Vanor Silenos in the area near the Cemetery.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (4438, 'Knuckle Duster Edge', NULL, 'Основной материал, используемый Гномами для создания Кастета. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make a Knuckle Duster. It can be bought from a regular store.', 'etc_sword_body_i00', 6);
INSERT INTO `all_items` VALUES (4439, 'Avadon Shield Fragment', NULL, 'Основной материал, используемый Гномами для создания Щита Авадона. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make an Avadon Shield. It can be bought from a regular store.', 'etc_plate_silver_i00', 6);
INSERT INTO `all_items` VALUES (4440, 'Recipe: Knuckle Duster', NULL, 'Только для Гномов. Рецепт создания Кастета. Требуется умение \"Создать Вещь\" 5-го уровня. Шанс создания: 100%.', 'For Dwarves only. The recipe for a Knuckle Duster. Requires Create Item - Skill Level 5. The success rate is 100%.', 'etc_recipe_yellow_i00', 5);
INSERT INTO `all_items` VALUES (4441, 'Recipe: Avadon Shield', NULL, 'Только для Гномов. Рецепт создания Щита Авадона. Требуется умение \"Создать Вещь\" 6-го уровня. Шанс создания: 100%.', 'For Dwarves only. The recipe for an Avadon Shield. Requires Create Item - Skill Level 6. The success rate is 100%.', 'etc_recipe_red_i00', 5);
INSERT INTO `all_items` VALUES (4442, 'Lottery Ticket', NULL, 'Лотерейный билет из Адена, который можно обналичить в любом месте продажи лотерейных билетов. Выигрышные номера объявляются каждую субботу в 19:00. Кто не играет, тот не выигрывает! Удачи!', 'A lottery ticket from Aden, redeemable at any lottery sales location. Winning numbers are posted every Saturday at 7 p.m. You can\'t win if you don\'t play! Good luck!', 'etc_lottery_card_i00', 13);
INSERT INTO `all_items` VALUES (4443, 'Monster Race Ticket - Single', NULL, 'Выигрышный билет в одиночном забеге Ипподрома Монстров. Обналичивается в кассе ипподрома.', 'A winning ticket from the monster race. Redeemable at the cashier of the race.', 'etc_ticket_i00', 14);
INSERT INTO `all_items` VALUES (4444, 'Monster Race Ticket - Double', NULL, 'Выигрышный билет в двойном забеге Ипподрома Монстров. Обналичивается в кассе гонок.', 'A winning daily double ticket from the monster race. Redeemable at the cashier of the race.', 'etc_ticket_i00', 14);
INSERT INTO `all_items` VALUES (4445, 'Dye of STR <Str+1 Con-3>', NULL, 'Краска СИЛ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of STR <Str+1 Con-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_str_hena_i00', 9);
INSERT INTO `all_items` VALUES (4446, 'Dye of STR <Str+1 Dex-3>', NULL, 'Краска СИЛ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of STR <Str+1 Dex-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_str_hena_i00', 9);
INSERT INTO `all_items` VALUES (4447, 'Dye of CON <Con+1 Str-3>', NULL, 'Краска ВЫН. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of CON <Con+1 Str-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_con_hena_i00', 9);
INSERT INTO `all_items` VALUES (4448, 'Dye of CON <Con+1 Dex-3>', NULL, 'Краска ВЫН. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of CON <Con+1 Dex-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_con_hena_i00', 9);
INSERT INTO `all_items` VALUES (4449, 'Dye of DEX <Dex+1 Str-3>', NULL, 'Краска ЛВК. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of DEX <Dex+1 Str-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_dex_hena_i00', 9);
INSERT INTO `all_items` VALUES (4450, 'Dye of DEX <Dex+1 Con-3>', NULL, 'Краска ЛВК. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of DEX <Dex+1 Con-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by all classes.', 'etc_dex_hena_i00', 9);
INSERT INTO `all_items` VALUES (4451, 'Dye of INT <Int+1 Men-3>', NULL, 'Краска ИНТ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of INT <Int+1 Men-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by Non-Healer Mystic classes.', 'etc_int_hena_i00', 9);
INSERT INTO `all_items` VALUES (4452, 'Dye of INT <Int+1 Wit-3>', NULL, 'Краска ИНТ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Доступно после первой и перед второй сменой профессии. Для воинов и магов, кроме целителей.', 'Dye of INT <Int+1 Wit-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by the Fighter and Non-Healer Mystic classes.', 'etc_int_hena_i00', 9);
INSERT INTO `all_items` VALUES (4453, 'Dye of MEN <Men+1 Int-3>', NULL, 'Краска ДУХ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Не лечащие магические классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'Dye of MEN <Men+1 Int-3> - Collect and take 10 units of this magical dye to the symbol maker in town and you will receive a symbol that boosts your abilities. Can be used after completion of first class transfer and prior to completion of second class transfer by Non-Healer Mystic classes.', 'etc_men_hena_i00', 9);
