INSERT INTO `all_items` VALUES (4660, 'Blue Soul Crystal - Stage 9', NULL, 'Синий кристалл, поглощающий души. Уровень 9. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании.', 'A blue crystal that absorbs souls, stage 9. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (4661, 'Blue Soul Crystal - Stage 10', NULL, 'Синий кристалл, поглощающий души. Уровень 10. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'A blue crystal that absorbs souls, stage 10. Once saturated, it bestows special abilities to a weapon. Each use consumes 26 MP. Once a soul stone reaches this stage, it automatically absorbs souls. Therefore, no targeting is necessary.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (4662, 'Broken Red Soul Crystal', NULL, 'Кристалл красного цвета, поглощающий души. Внутренний дисбаланс поглощенных душ разрушил его.', 'A red-colored crystal that absorbs souls. An internal inbalance between absorbed souls has rendered it useless.', 'etc_broken_crystal_red_i00', 1);
INSERT INTO `all_items` VALUES (4663, 'Broken Green Soul Crystal', NULL, 'Кристалл зеленого цвета, поглощающий души. Внутренний дисбаланс поглощенных душ разрушил его.', 'A green-colored crystal that absorbs souls. An internal inbalance between absorbed souls has rendered it useless.', 'etc_broken_crystal_green_i00', 1);
INSERT INTO `all_items` VALUES (4664, 'Broken Blue Soul Crystal', NULL, 'Кристалл синего цвета, поглощающий души. Внутренний дисбаланс поглощенных душ разрушил его.', 'A blue-colored crystal that absorbs souls. An internal inbalance between absorbed souls has rendered it useless.', 'etc_broken_crystal_blue_i00', 1);
INSERT INTO `all_items` VALUES (4665, 'Pipette Knife', NULL, 'Инструмент для сбора крови живых существ. Используйте его для сбора крови Баюма.', 'An instrument used to collect the blood of living creatures. Use it to cut Baium and obtain a blood sample.', 'weapon_knife_i00', 0);
INSERT INTO `all_items` VALUES (4666, 'Reiria\'s Soul Orb', NULL, 'Сфера с душой Рейрии. Отдайте ее Мастеру Реорину.', 'A sphere containing Reiria\'s Soul. Take it to Maestro Reorin.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (4667, 'Kernon\'s Infernium Scepter', NULL, 'Скипетр, созданный из инферниума, который был получен от демона Кернона. Отдайте его Мастеру Реорину.', 'A scepter made of infernium that was recovered from the demon Kernon. Take it to Maestro Reorin.', 'etc_imperial_scepter_i02', 0);
INSERT INTO `all_items` VALUES (4668, 'Golkonda\'s Infernium Scepter', NULL, 'Скипетр, созданный из инферниума, который был получен от Длиннорогого Генерала Голконды. Отдайте его Мастеру Реорину.', 'A scepter made of infernium that was recovered from Golkonda, the Longhorn General. Take it to Maestro Reorin.', 'etc_imperial_scepter_i01', 0);
INSERT INTO `all_items` VALUES (4669, 'Hallate\'s Infernium Scepter', NULL, 'Скипетр созданный из инферниума, который был получен от Лорда Смерти Халлета. Отдайте его Мастеру Реорину.', 'A scepter made of infernium that was recovered from the Death Lord Hallate. Take it to Maestro Reorin.', 'etc_imperial_scepter_i00', 0);
INSERT INTO `all_items` VALUES (4670, 'Maestro Reorin\'s Hammer', NULL, 'Молот кузнеца, сделанный из адамантитового слитка высокой пробы. Отдайте его Мастеру Реорину.', 'A hammer used by a blacksmith. It is made by processing an adamantite nugget of high purity. Take it to Maestro Reorin.', 'weapon_iron_hammer_i01', 0);
INSERT INTO `all_items` VALUES (4671, 'Maestro Reorin\'s Mold', NULL, 'Заготовка, используемая Гномами для изготовления высококачественного снаряжения. Отдайте ее Мастеру Реорину.', 'A mold used by Dwarven Artisans to manufacture top grade equipment. Take it to Maestro Reorin.', 'etc_artisans_frame_i00', 0);
INSERT INTO `all_items` VALUES (4672, 'Infernium Varnish', NULL, 'Полировка, используемая для производства оружия из инферниума. Отдайте ее Мастеру Реорину.', 'Varnish used when manufacturing an infernium weapon. Take it to Maestro Reorin.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (4673, 'Red Pipette Knife', NULL, 'Нож, окропленный кровью Баюма. Отдайте его Мастеру Каспару в Академии Хардина.', 'The Pipette knife that holds the blood of Baium. Take it to Master Kaspar in Hardin\'s Academy.', 'weapon_knife_i01', 0);
INSERT INTO `all_items` VALUES (4674, 'Medal of Honor', NULL, NULL, NULL, 'etc_magic_coin_gold_i00', 0);
