INSERT INTO `all_items` VALUES (4677, 'Potion of Critical Escape', NULL, 'Позволяет уклоняться от атак врага, но снижает скорость.', 'Misdirects enemy attack, inhibits speed of user.', 'etc_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (4678, 'Decrease Haste Potion', NULL, 'Снижает уровень агрессии на 1.', 'Decreases one\'s level of Aggression.', 'etc_scroll_white_i00', 3);
INSERT INTO `all_items` VALUES (4679, 'Bless of Eva', NULL, 'Увеличивает время нахождения под водой.', 'Allows one to breathe under water for extended periods.', 'etc_bless_of_eva_i00', 3);
INSERT INTO `all_items` VALUES (4680, 'Potion of Revenge', NULL, 'Снижает Физ. Защ. и отражает урон на врага.', 'Reduces P. Def. and reflects damage back upon enemy.', 'etc_potion_blue_i00', 3);
