INSERT INTO `all_items` VALUES (5010, 'Echo Crystal - Theme of Victory', NULL, 'Кристалл с победной музыкой. Исчезает после использования.', 'An echo crystal that plays the theme music of victory. Will work once and then disappear.', 'etc_echo_crystal_i02', 0);
INSERT INTO `all_items` VALUES (5011, 'Star of Destiny', NULL, 'Аксессуар, созданный Мастером Реорином по просьбе неизвестной женщины.', 'Accessory that Maestro Reorin created after receiving a request from a woman of unknown identity.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (5012, 'Leikan\'s Letter', NULL, 'Письмо, полученное от Стража Лейкана. Отнесите его Пиотуру на ферму к востоку от Лагеря Орков.', 'A letter received from Guard Leikan. Take it to Piotur at the farm east of the Orc Barracks.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5013, 'Spellbook: Elemental Assault', NULL, 'Книга, необходимая для изучения умения \"Стихийное Нападение\". Профессия: Властитель Огня.Необходимый уровень: 72.', 'Spellbook needed to learn Elemental Assault. Used by Sorcerers and Sorceresses.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (5014, 'Spellbook: Elemental Symphony', NULL, 'Книга, необходимая для изучения умения \"Стихийная Симфония\". Профессия: Певец Заклинаний.Необходимый уровень: 72.', 'Spellbook needed to learn Elemental Symphony.  Used by Spellsingers.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (5015, 'Spellbook: Elemental Storm', NULL, 'Книга, необходимая для изучения умения \"Стихийный Шторм\". Профессия: Заклинатель Ветра.Необходимый уровень: 72.', 'Spellbook needed to learn Elemental Storm. Used by Spellhowlers.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (5016, 'Seed: Dark Coda', NULL, 'Семя Темной Коды. Для получения плода вживите его в монстра в районе Глудио. Наилучшего результата можно достичь, если персонаж и монстр 5-15 уровней.', 'Plant this seed onto a monster in the Gludio area and it will bear the fruit of the dark coda. For best results, a level 5-15 character should plant it on a monster within the same level range.', 'etc_coda_seed_i00', 10);
