INSERT INTO `all_items` VALUES (5060, 'Seed: Great Codran', NULL, 'Семя Большого Кодрана. Для получения плода вживите его в монстра в районе Адена Наилучшего результата можно достичь, если персонаж и монстр 56-66 уровней.', 'Plant this seed onto a monster in the Aden area and it will bear the fruit of the Great Codran. For best results, a level 56-66 character must plant it on a level 56-66 monster.', 'etc_codran_seed_i00', 10);
INSERT INTO `all_items` VALUES (5061, 'Seed: Desert Codran', NULL, 'Семя Пустынного Кодрана. Для получения плода вживите его в монстра в районе Адена Наилучшего результата можно достичь, если персонаж и монстр 59-69 уровней.', 'Plant this seed onto a monster in the Aden area and it will bear the fruit of the Desert Codran. For best results, a level 59-69 character must plant it on a level 59-69 monster.', 'etc_codran_seed_i00', 10);
