INSERT INTO `all_items` VALUES (5125, 'Harvester', NULL, 'Инструмент для сбора плодов с тел монстров, в которых вживлялось семя. Для получения наилучшего результата уровни персонажа и цели не должны различаться более, чем на 5.', 'Used to harvest the crop from the corpse of the monster on which a seed was sown. Most successful when character and target are not more than 5 levels apart.', 'etc_reaper_i00', 12);
