INSERT INTO `all_items` VALUES (5168, 'Food for Strider', NULL, 'Еда для драконов. При индикаторе голода 55% или ниже потребляется автоматически.', 'When the hunger gauge of a strider reaches 55% or below, its food will be consumed automatically.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (5169, 'Deluxe Food for Strider', NULL, 'Еда для драконов. При индикаторе голода 55% или ниже потребляется автоматически. Действует лучше при езде на драконе.', 'When the hunger gauge of a strider reaches 55% or below, its food will be consumed automatically. Food consumption efficiency improves while riding a strider.', 'etc_pouch_yellow_i00', 0);
