INSERT INTO `all_items` VALUES (5197, 'Chest Key - Grade 8', NULL, 'Используется для открытия сундуков. Уровень сундука: 1. Шанс: 60%. Шанс снижается при попытке открыть сундук более высокого уровня.', 'Opens a level 1 treasure chest with a success rate of 60%. When opening a higher level treasure chest, the success rate will decrease.', 'etc_key_i00', 0);
