INSERT INTO `all_items` VALUES (5220, 'Metal Hardener', NULL, 'Материал, используемый Гномами для создания предметов Ранга C. Можно продать в Торговой Лавке.', 'Ingredient used by Dwarves. It is specifically designed to be used to create C-grade items. Available in general stores.', 'etc_plate_blue_i00', 6);
INSERT INTO `all_items` VALUES (5221, 'Seed: Chilly Cobol', NULL, 'Семя Холодного Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 29-39 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Chilly Cobol. For best results, a level 29-39 character must plant it on a level 29-39 monster.', 'etc_cobol_seed_i00', 10);
INSERT INTO `all_items` VALUES (5222, 'Seed: Blue Cobol', NULL, 'Семя Синего Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 32-42 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Blue Cobol. For best results, a level 32-42 character must plant it on a level 32-42 monster.', 'etc_cobol_seed_i00', 10);
INSERT INTO `all_items` VALUES (5223, 'Seed: Thorn Cobol', NULL, 'Семя Колючего Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 35-45 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Thorn Cobol. For best results, a level 35-45 character must plant it on a level 35-45 monster.', 'etc_cobol_seed_i00', 10);
INSERT INTO `all_items` VALUES (5224, 'Seed: Golden Cobol', NULL, 'Семя Золотого Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 38-48 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Golden Cobol. For best results, a level 38-48 character must plant it on a level 38-48 monster.', 'etc_cobol_seed_i00', 10);
INSERT INTO `all_items` VALUES (5225, 'Seed: Great Cobol', NULL, 'Семя Большого Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 41-51 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Great Cobol. For best results, a level 41-51 character must plant it on a level 41-51 monster.', 'etc_cobol_seed_i00', 10);
INSERT INTO `all_items` VALUES (5226, 'Seed: Red Codran', NULL, 'Семя Красного Кодрана. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 44-54 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Red Codran. For best results, a level 44-54 character must plant it on a level 44-54 monster.', 'etc_codran_seed_i00', 10);
INSERT INTO `all_items` VALUES (5227, 'Seed: Sea Codran', NULL, 'Семя Морского Кодрана. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 45-55 уровней.', 'Plant this seed onto a monster in the Innadril area and it will bear the fruit of the Sea Codran. For best results, a level 45-55 character must plant it on a level 45-55 monster.', 'etc_codran_seed_i00', 10);
