INSERT INTO `all_items` VALUES (5555, 'Token of Love', NULL, 'Предмет, использовавшийся во время ивента \"Новый год-2004\".', 'A commemorative item for Christmas, 2004.', 'etc_x_mas_2004_i00', 0);
INSERT INTO `all_items` VALUES (5556, 'Star Ornament', NULL, 'Материал, используемый для создания Новогодней Елки. Чтобы получить ее, поговорите с Учеником Деда Мороза.', 'An essential ingredient needed to make a Christmas Tree. Take it to a Santa trainee, and he will create a Christmas Tree for you.', 'etc_deco_star_i00', 6);
INSERT INTO `all_items` VALUES (5557, 'Bead Ornament', NULL, 'Материал, используемый для создания Новогодней Елки. Чтобы получить ее, поговорите с Учеником Деда Мороза.', 'An ingredient of a Christmas Tree. Take it to a Santa trainee, along with the other necessary ingredients, and he will create a Christmas Tree for you.', 'etc_deco_bead_i00', 6);
INSERT INTO `all_items` VALUES (5558, 'Fir Tree Branch', NULL, 'Материал, используемый для создания Новогодней Елки. Чтобы получить ее, поговорите с Учеником Деда Мороза.', 'An ingredient of a Christmas Tree. Take it to a Santa trainee, along with the other necessary ingredients, and he will create a Christmas Tree for you.', 'etc_fir_spring_i00', 6);
