INSERT INTO `all_items` VALUES (5560, 'Christmas Tree', NULL, 'Используется для призыва Новогодней Елки.', 'Summons a Christmas Tree.', 'etc_x_mas_tree_i00', 3);
INSERT INTO `all_items` VALUES (5561, 'Special Christmas Tree', NULL, 'Используется для призыва Новогодней Елки, которая увеличивает восстановление HP и MP (действует только за пределами поселений).', 'Summons a Christmas tree that will increase HP and MP regeneration.  This effect is only produced if the Special Christmas Tree is summoned outside of a village.', 'etc_x_mas_tree_i00', 3);
INSERT INTO `all_items` VALUES (5562, 'Echo Crystal - 1st Carol', NULL, 'Музыкальный кристалл, исполняющий I хорал. Исчезает после использования.', 'An echo crystal that plays the 1st carol. It disappears after one use.', 'etc_echo_crystal_i00', 0);
