INSERT INTO `all_items` VALUES (5577, 'Red Soul Crystal - Stage 11', NULL, 'Красный кристалл, поглощающий души. Уровень: 11. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'A red crystal that absorbs souls, stage 11. Once saturated, it bestows special abilities to a weapon. Consumes 26 MP. Once a soul stone reaches this stage, it can absorb souls independently. No targeting is necessary.', 'etc_soul_stone_i00', 1);
INSERT INTO `all_items` VALUES (5578, 'Green Soul Crystal - Stage 11', NULL, 'Зеленый кристалл, поглощающий души. Уровень: 11. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'A green crystal that absorbs souls, stage 11. Once saturated, it bestows special abilities to a weapon. Consumes 26 MP. Once a soul stone reaches this stage, it can absorb souls independently. No targeting is necessary.', 'etc_soul_stone_i02', 1);
INSERT INTO `all_items` VALUES (5579, 'Blue Soul Crystal - Stage 11', NULL, 'Синий кристалл, поглощающий души. Уровень: 11. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'A blue crystal that absorbs souls, stage 11. Once saturated, it bestows special abilities to a weapon. Consumes 26 MP. Once a soul stone reaches this stage, it can absorb souls independently. No targeting is necessary.', 'etc_soul_stone_i01', 1);
