INSERT INTO `all_items` VALUES (5588, 'Tutorial Guide', NULL, 'Учебник, содержащий общую информацию для нового игрока.', 'A booklet containing general information for the new player.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (5589, 'Energy Stone', NULL, 'Камень, необходимый Гладиаторам и Отшельникам для перезарядки энергии. Можно зарядить на 1 уровень за раз. Максимальный заряд: 2 уровня.', 'Recharges the energy of a Gladiator or a Tyrant 1 stage at a time. Can be recharged up to 2 stages.', 'etc_energy_stone_i00', 3);
INSERT INTO `all_items` VALUES (5590, 'Squeaking Shoes', NULL, 'Ботинки, скрипящие при ходьбе.', 'Makes a unique sound when walking in them.', 'armor_t02_b_i00', 0);
