INSERT INTO `all_items` VALUES (5596, 'Dasparion\'s Staff', 'Mana Up', '<Свойство Кристалла Души> Макс. MP +30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Enhances damage to a target during PvP.', 'weapon_dasparions_staff_i01', 4);
INSERT INTO `all_items` VALUES (5597, 'Dasparion\'s Staff', 'Conversion', '<Свойство Кристалла Души> Макс. MP +60%; Макс. HP -40%. Наносит дополнительный урон в PvP.', 'Conversion	a,<Soul Crystal Enhancement>n Increases maximum MP by 60% and decreases maximum HP by 40%. Enhances damage to a target during PvP.', 'weapon_dasparions_staff_i01', 4);
INSERT INTO `all_items` VALUES (5598, 'Dasparion\'s Staff', 'Acumen', '<Свойство Кристалла Души> Скор. Магии +15%. Наносит дополнительный урон в PvP.', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd. by 15%. Enhances damage to a target during PvP.', 'weapon_dasparions_staff_i01', 4);
INSERT INTO `all_items` VALUES (5599, 'Meteor Shower', 'Focus', '<Свойство Кристалла Души> Шанс Крит. Атк. +61. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement>n Increases Critical Attack by 61. Enhances damage to a target during PvP.', 'weapon_meteor_shower_i01', 4);
INSERT INTO `all_items` VALUES (5600, 'Meteor Shower', 'Critical Bleed', '<Свойство Кристалла Души> Шанс 42% вызвать у противника кровотечение при критической атаке. Наносит дополнительный урон в PvP.', 'Critical Bleed	a,<Soul Crystal Enhancement>n During a critical attack, increases probability of drawing target\'s blood by 42%. Effect 7. Enhances damage to a target during PvP.', 'weapon_meteor_shower_i01', 4);
