INSERT INTO `all_items` VALUES (5606, 'Branch of the Mother Tree', 'Magic Damage', '<Свойство Кристалла Души> Дает 30% шанс нанесения дополнительного магического урона мощностью 8 при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Damage	a,<Soul Crystal Enhancement>n Grants a 30% chance to boost damage to Power 8 when using bad magic. Enhances damage to a target during PvP.', 'weapon_worldtrees_branch_i01', 4);
