INSERT INTO `all_items` VALUES (5703, 'Lucky Charm', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем ниже 20-го уровня.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self by a character whose level is 19 or below.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5704, 'Keshanberk*Keshanberk', NULL, NULL, NULL, 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (5705, 'Keshanberk*Damascus', NULL, 'При модификации парных мечей их Ф. Атк. увеличивается в большей степени, нежели у одноручного оружия или кастетов. При модификации на +4 и выше: Макс. HP +25%. Наносит дополнительный урон в PvP.', 'When enchanted, the P.Atk of a dualsword will increase more significantly than that of one-handed or fist weapon. When enchanted by 4 or more, maximum HP will increase by 25% as well. Enhances damage to target during PvP.', 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (5706, 'Damascus*Damascus', NULL, 'При модификации парных мечей их Ф. Атк. увеличивается в большей степени, нежели у одноручного оружия или кастетов. При модификации на +4 и выше: Точность +6. Наносит дополнительный урон в PvP.', 'When enchanted, the P.Atk of a dualsword will increase more significantly than that of one-handed or fist weapon. When enchanted by 4 or more, Accuracy will increase by 6. Enhances damage to target during PvP.', 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (5707, 'Record of Seven Signs', NULL, 'Документ, используемый для изучения текущей ситуации о ходе борьбы за Семь Печатей.', 'An item used for studying the current situation of the Seven Signs system.', 'etc_ssq_scroll_i00', 0);
INSERT INTO `all_items` VALUES (5708, 'Lord of the Manor\'s Certificate of Approval', NULL, 'Документ, позволяющий своему владельцу вступить в ряды Лордов Рассвета.', 'When one possesses this item, although one does not belong to a castle owning clan, one can join the Lords of Dawn.', 'etc_permit_card_i00', 15);
