INSERT INTO `all_items` VALUES (5803, 'Lucky Charm (D-Grade)', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 20-39-го уровней.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self, by a character whose level is between 20 and 39.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5804, 'Lucky Charm (C-Grade)', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 40-51-го уровней.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self by a character whose level is between 40 and 51.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5805, 'Lucky Charm (B-Grade)', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 52-60-го уровней.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self by a character whose level is between 52 and 60.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5806, 'Lucky Charm (A-Grade)', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 61-75-го уровней.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self by a character whose level is between 61 and 75.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5807, 'Lucky Charm (S-Grade)', NULL, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 76-го уровня или выше.', 'Bestows blessing on its owner such that when the owner dies during a boss/raid war, his/her abilities will not be diminished.  This item can only be used on self by a character whose level is 76 or higher.', 'etc_charm_of_luck_i00', 1);
INSERT INTO `all_items` VALUES (5808, 'Party Mask', NULL, 'Модный аксессуар, с помощью которого можно подчеркнуть свою индивидуальность.', 'A fashion item used to display a unique appearance.', 'etc_party_mask_i00', 0);
INSERT INTO `all_items` VALUES (5809, 'Spellbook: Aqua Splash', NULL, 'Книга, необходимая для изучения умения \"Всплеск Воды\". Профессия: Певец Заклинаний.Необходимый уровень: 58.', 'Spellbook needed to learn Aqua Splash. Used by Spellsingers.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (5810, 'Spellbook: Rain of Fire', NULL, 'Книга, необходимая для изучения умения \"Огненный Дождь\". Профессия: Властитель Огня.Необходимый уровень: 58.', 'Spellbook needed to learn Rain of Fire. Used by Sorcerers/sses.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (5811, 'Spellbook: Mass Slow', NULL, 'Книга, необходимая для изучения умения \"Массовое Замедление\". Профессия: Некромант.Необходимый уровень: 62.', 'Spellbook needed to learn Mass Slow. Used by Necromancers.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (5812, 'Spellbook: Servitor Empowerment', NULL, 'Книга, необходимая для изучения умения \"Помощь Слуге\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 52.', 'Spellbook needed to learn Servitor Empowerment. Used by Warlocks, Elemental Summoners and Phantom Summoners.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5813, 'Spellbook: Servitor Cure', NULL, 'Книга, необходимая для изучения умения \"Излечить Слугу\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 40.', 'Spellbook needed to learn Servitor Cure. Used by Warlocks, Elemental Summoners and Phantom Summoners.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5814, 'Spellbook: Servitor Blessing', NULL, 'Книга, необходимая для изучения умения \"Благословение Слуги\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 62.', 'Spellbook needed to learn Servitor Blessing. Used by Warlocks, Elemental Summoners and Phantom Summoners.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5815, 'Spellbook: Wild Magic', NULL, 'Книга, необходимая для изучения умения \"Дикая Магия\". Профессии: Мудрец Евы, Мудрец Шилен.Необходимый уровень: 62.', 'Spellbook needed to learn Wild. Used by Elven Elders and Shillien Elders.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (5816, 'Spellbook: Advanced Block', NULL, 'Книга, необходимая для изучения умения \"Усиленная Блокировка\". Профессия: Мудрец Евы.Необходимый уровень: 58.', 'Spellbook needed to learn Advanced Block. Used by Elven Elders.', 'etc_spell_books_assistance_i00', 0);
