INSERT INTO `all_items` VALUES (5858, 'Blessed Scroll of Escape: Clan Hall', NULL, 'Магический свиток, с помощью которого можно переместиться в холл клана. Если у Вас нет холла клана, эффекта не будет.', 'A magical scroll that transports you to your clan hall.  If you don\'t belong to a clan that possesses a clan hall, this scroll will have no effect.', 'etc_scroll_of_return_agit_i01', 1);
INSERT INTO `all_items` VALUES (5859, 'Blessed Scroll of Escape: Castle', NULL, 'Магический свиток, с помощью которого можно переместиться в замок. Если у Вас нет замка, эффекта не будет.', 'A magical scroll that transports you to your castle.  If you don\'t belong to a clan that controls a castle, this scroll will have no effect.', 'etc_scroll_of_return_castle_i01', 1);
INSERT INTO `all_items` VALUES (5860, 'Lienrik Egg', NULL, 'Яйцо Аспида, которое запросил Руд, продавец Товаров для Питомцев.', 'Lienrik\'s egg. It\'s the item that Pet Manager Rood of Heine asked you to find for him.', 'etc_dragon_egg_i02', 0);
INSERT INTO `all_items` VALUES (5861, 'Lienrik Egg', NULL, 'Блестящее красное яйцо Аспида. Похоже на то, что просил продавец Товаров для Питомцев Руд. Но что-то тут не так…', 'Lienrik\'s shiny red egg. Pet Manager Rood of Heine asked you to find it for him, but...?', 'etc_dragon_egg_i01', 0);
INSERT INTO `all_items` VALUES (5862, 'Stone of Contract', NULL, 'Чтобы завладеть силой Тьмы, необходимо получить право владения этим предметом. Отнесите его Торговцу Галману в Долину Драконов.', 'In order to obtain the power of darkness, you will first need to secure this item. Take it to Trader Galman in Dragon Valley.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (5863, 'Alligator Tooth', NULL, 'Острый зуб аллигатора. Отнесите его Рабочему Склада Клаку в Хейн.', 'A sharp tooth from an alligator. Take it to Warehouse Freightman Kluck of Heine.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (5864, 'Mysterious Map Piece', NULL, 'Потемневший кусок бумаги. Возможно, это часть карты.', 'A faded piece of paper. Possibly part of a map.', 'etc_map_piece_ivory_i00', 0);
INSERT INTO `all_items` VALUES (5865, 'Carnivore Spore', NULL, 'Кусок кожи, собранный со Споровых Зомби в Море Спор. Используется Магистром Гейном в Башне Слоновой Кости.', 'A tissue sample collected from a spore zombie from the Sea of Spores. It is used as research material by Magister Gauen of the Ivory Tower.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (5866, 'Herbivorous Spore', NULL, 'Образец спор, собранный с Трухлявого Дерева в Море Спор. Используется Магистром Гейном в Башне Слоновой Кости.', 'A spore sample collected from a rotting tree from the Sea of Spores. It is used as research material by Magister Gauen of the Ivory Tower.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (5867, 'Jade Crystal', NULL, 'Нефритовый кристалл, собранный в Волшебной Долине. Отнесите его Рабочему Склада Сильве в Деревню Охотников.', 'A jade crystal collected from the Enchanted Valley. Take it to Warehouse Freightman Silva of Hunters Village.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (5868, 'Snake Scale', NULL, 'Чешуя змеи с тел Фалибати и Змеев Кочевников. Отнесите ее Великому Мастеру Олтлину в Аден.', 'A snake scale from the bodies of Falibati and Trives. Take it to Grand Master Oltlin of Aden Castle Town.', 'etc_scale_of_medusa_blue_i00', 0);
INSERT INTO `all_items` VALUES (5869, 'Remains of Aden Residents', NULL, 'Останки жителей Адена, убитых в период войны Адена и Эльмора. Соберите 60 штук и отнесите их Верховному Жрецу Орвену.', 'Remains of residents of Aden Castle who were killed during the Aden-Elmore war. Collect 60 of them and take them to High Priest Orven.', 'etc_ashes_white_i00', 0);
INSERT INTO `all_items` VALUES (5870, 'Receipt of Supply', NULL, 'Документ, собранный из обрывков. Отнесите его Стражу Колману.', 'A document made from collected mysterious document pieces. Take it to Guard Coleman.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5871, 'Suspicious Document Piece', NULL, 'Часть документа, содержащая подозрительную информацию. Если собрать 5 частей, можно расшифровать документ.', 'A piece of document that seems to contain some suspicious contents. If you collect 5 of them, you may be able to decipher the information the document conveys.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (5872, 'Supply Items', NULL, 'Припасы, полученные при убийстве поставщиков Орков Тайк. Отнесите их Стражу Колману за вознаграждение.', 'Supply items for Taik Orcs. Take it to Guard Coleman and he will give you a reward.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (5873, 'Pirate\'s Treasure Chest', NULL, 'Сундук с сокровищами, добытый у последователей Закена. Отнесите его Смотрителю Склада Рандольфу в Гиран.', 'A treasure chest that was obtained by slaying Zaken\'s followers. Take it to Warehouse Keeper Randolf of Giran Castle Town.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (5874, 'Sairon\'s Silver Hair', NULL, 'Волосы Сайрона. Отнесите их Магистру Диетеру в Гиран.', 'Sairon\'s hair. Take it to Magister Dieter of Giran Castle Town.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (5875, 'Titan Lamp', NULL, 'Лампа, изобретенная Гигантами. Не горит.', 'It is called a Titan lamp. It is not lit.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (5876, 'Titan Lamp', NULL, 'Лампа, изобретенная Гигантами. В ней теплится огонь.', 'It is called a Titan lamp. It is burning dimly.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (5877, 'Titan Lamp', NULL, 'Лампа, изобретенная Гигантами. Горит.', 'It is called a Titan lamp. It is lit.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (5878, 'Titan Lamp', NULL, 'Лампа, изобретенная Гигантами. Горит.', 'It is called a Titan lamp. It is lit.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (5879, 'Titan Lamp', NULL, 'Лампа, изобретенная Гигантами. Горит ярким пламенем.', 'It is called a Titan lamp. It is shining brightly.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (5880, 'Broken Titan Lamp', NULL, 'Сломанная лампа Гигантов. Отнесите ее Лорейн.', 'A broken Titan lamp. Take it to Lorain.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (5881, 'Blade Stakato Fang', NULL, 'Клык, отрезанный у Опасного Стакато. Отнесите его Жрице Евы Рестине в Хейн.', 'A fang that was obtained from killing a blade stakato. Take it to Eva\'s Priestess Restina in Heine.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (5882, 'Flare Shard', NULL, 'Пламенные осколки из Забытого Храма. Отнесите их Магистру Неллу в Деревню Глудин.', 'A flare shard obtained from the Forgotten Temple. Take it to Magister Nell of Gludin Village.', 'etc_echo_crystal_i00', 0);
INSERT INTO `all_items` VALUES (5883, 'Freezing Shard', NULL, 'Осколки льда из Забытого Храма. Отнесите их Магистру Неллу в Деревню Глудин.', 'A water shard obtained from the Forgotten Temple. Take it to Magister Nell of Gludin Village.', 'etc_echo_crystal_i01', 0);
INSERT INTO `all_items` VALUES (5884, 'Cave Beast Tooth', NULL, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'An ingredient used by Orc Shamans during a ritual. Take it to Seer Manakia.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (5885, 'Death Wave Light', NULL, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'An ingredient used by Orc Shamans during their ritual. Take it to Seer Manakia.', 'etc_crystal_ball_green_i00', 0);
INSERT INTO `all_items` VALUES (5886, 'Sealed Mysterious Stone', NULL, 'Галька, светящаяся странной аурой. Дает слабое свечение.', 'A pebble that radiates a strange aura. It sends out a dim light.', 'etc_dragon_egg_i02', 0);
INSERT INTO `all_items` VALUES (5887, 'Mysterious Stone', NULL, 'Галька, светящаяся странной аурой. Дает сильное свечение.', 'A pebble that radiates a strange aura. It is shining brightly.', 'etc_dragon_egg_i00', 0);
INSERT INTO `all_items` VALUES (5888, 'Karik Horn', NULL, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'An ingredient used by Orc Shamans during a ritual. Take it to Seer Manakia.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (5889, 'Cave Howler Skull', NULL, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'An ingredient used by Orc Shamans during a ritual. Take it to Seer Manakia.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (5890, 'Mysterious Book', NULL, 'Книга, добытая в Пещере Гигантов. Она написана на древнем языке, который невозможно прочитать.', 'A book obtained from The Giant\'s Cave. Written in an ancient language, its contents cannot be deciphered.', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (5891, 'Ancient Language Dictionary: Basic Level', NULL, 'Простой словарь ученых древних времен. С его помощью можно прочитать некоторые тексты Гигантов.', 'A simple dictionary published by scholars of ancient times. By using this, you can interpret some of the texts of the Titans.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (5892, 'Ancient Language Dictionary: Intermediate Level', NULL, 'Словарь ученых древних времен. С его помощью можно прочитать некоторые тексты Гигантов.', 'A dictionary published by scholars of ancient times. By using this, you can interpret the entire texts of the Titans.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (5893, 'Leaf of Eucalyptus', NULL, 'Один из ингредиентов для производства вина. Соберите 80 штук и отнесите Стражу Харлану в Дион.', 'One of the ingredients used to make wine. Collect 80 of them and take them to Guard Harlan located in the Town of Dion.', 'etc_herb_red_i00', 0);
INSERT INTO `all_items` VALUES (5894, 'Stone of Chill', NULL, 'Магический камень, используемый Шаманами Орков Энку для заклинаний льда. Соберите 100 штук и отнесите Стражу Харлану в Дион.', 'A magical stone used by Enku Orc Shamans when they cast ice magic. Collect 100 of these and take them to Guard Harlan located in the Town of Dion.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (5895, 'Ritron\'s Fruit', NULL, 'Фрукт с жесткой кожурой и приятным запахом. Соберите 4 штуки и отнесите Магистру Ролланту в Дион.', 'A fruit with a tough, hard outer skin and a fragrant smell. Collect 4 of these and take them to Magister Rollant in the Town of Dion.', 'etc_cobol_i05', 0);
INSERT INTO `all_items` VALUES (5896, 'Moon Face Flower', NULL, 'Говорят, этот цветок распускается только в лунном свете. Соберите 20 штук и отнесите Магистру Ролланту в Дион.', 'A flower that is said to bloom only under moonlight. Collect 20 of these and take them to Magister Rollant in the Town of Dion.', 'etc_flower_i00', 0);
INSERT INTO `all_items` VALUES (5897, 'Leech Fluids', NULL, 'Флюиды личинок, обитающих в Топи Крума. Соберите 10 штук и отнесите Магистру Ролланту в Дион.', 'The bodily fluids of a Leech that can be obtained from the Cruma Marshlands. Collect 10 of these and take them to Magister Rollant in the Town of Dion.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (5898, 'Royal Membership', NULL, 'Мечта всех нумизматов! Отнесите ее Главному Кузнецу Вергара.', 'It\'s a coin collectors\' dream! Take it to Head Blacksmith Vergara.', 'etc_royal_membership_i00', 0);
INSERT INTO `all_items` VALUES (5899, 'Kail\'s Coin', NULL, 'Монета, которой владел Волшебник Кайл, помогавший Белефу. Отнесите ее Смотрителю Склада Соринту.', 'A coin owned by Sorcerer Kail who used to be an aid of Beleth. Take it to Warehouse Keeper Sorint.', 'etc_magic_coin_blood_i00', 0);
INSERT INTO `all_items` VALUES (5900, 'Coin Collecting Album', NULL, 'Альбом для монет высокого качества, сделан из кожи.', 'A high quality coin collecting album made of leather.', 'etc_magic_book_black_i00', 0);
INSERT INTO `all_items` VALUES (5901, 'Blood Offering', NULL, 'Кровь Монстра Подношения. Количество этих предметов определит Ваш счет.', 'Blood that can be obtained by killing a Monster of Offering. The number of this item will determine your score.', 'etc_dragon_blood_i00', 0);
INSERT INTO `all_items` VALUES (5902, 'Scroll of Ancient Magic', NULL, 'Свиток, содержащий древнюю магию. Отнесите его Хранителю Портала Зиккурату.', 'A scroll that contains ancient magic. Take it to Gatekeeper Ziggurat.', 'etc_scroll_of_enchant_weapon_i01', 0);
INSERT INTO `all_items` VALUES (5903, 'Ancient Ash Urn', NULL, 'Древняя урна, найденная в Башне Дерзости. Отнесите ее Провидцу Реве в Аден.', 'An ancient urn that was found in the Tower of Insolence. Take it to Seer Reva of Aden Castle Town.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (5904, 'Wesley\'s Mixing Stone', NULL, 'Драгоценный камень, отданный Уэсли. Этот предмет нужен для использования смесительной урны.', 'A small gemstone that is given by Wesley. This item is required to use a mixing urn.', 'etc_gem_green_i00', 0);
INSERT INTO `all_items` VALUES (5905, 'Magister\'s Mixing Stone', NULL, 'Камень, активирующий смесительную урну в подвале Башни Слоновой Кости.', 'A gemstone that activates the mixing urn in the basement of the Ivory Tower.', 'etc_gem_blue_i00', 0);
INSERT INTO `all_items` VALUES (5906, '5th Anniversary Gift Box (10 Honey Rice Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 10 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A red crystal that absorbs souls. Grade 11. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5907, '5th Anniversary Gift Box (9 Honey Rice Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 9 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A red crystal that absorbs souls. Grade 12. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5908, 'Red Soul Crystal: Stage 13', NULL, 'Красный кристалл, поглощающий души. Уровень 13. Наполнившись, дарует особые свойства оружию. 26 MP будет затрачено при каждом его применении. Кристалл этого уровня может самостоятельно поглощать души.', 'A red crystal that absorbs souls. Grade 13. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_soul_stone_i00', 1);
INSERT INTO `all_items` VALUES (5909, '5th Anniversary Gift Box (8 Honey Rice Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 8 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A green crystal that absorbs souls. Grade 11. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5910, '5th Anniversary Gift Box (7 Honey Rice Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 7 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A green crystal that absorbs souls. Grade 12. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5911, 'Green Soul Crystal: Stage 13', NULL, 'Зеленый кристалл, поглощающий души. Уровень 13. Наполнившись, дарует особые свойства оружию. 26 MP будет затрачено при каждом его применении. Кристалл этого уровня может самостоятельно поглощать души.', 'A green crystal that absorbs souls. Grade 13. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_soul_stone_i02', 1);
INSERT INTO `all_items` VALUES (5912, '5th Anniversary Gift Box (6 Honey Rice Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 6 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A blue crystal that absorbs souls. Grade 11. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5913, '5th Anniversary Gift Box (3 Honey Wheat Cake Set)', NULL, 'Подарок в честь 5 годовщины L2. Содержит 3 Пирога и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'A blue crystal that absorbs souls. Grade 12. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (5914, 'Blue Soul Crystal: Stage 13', NULL, 'Синий кристалл, поглощающий души. Уровень 13. Наполнившись, дарует особые свойства оружию. 26 MP будет затрачено при каждом его применении. Кристалл этого уровня может самостоятельно поглощать души.', 'A blue crystal that absorbs souls. Grade 13. Once saturated, it bestows special abilities to a weapon. 26 MP is consumed each time it is used.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (5915, 'Pirate\'s Treasure Map', NULL, 'Карта, составленная из обрывков, найденных на Острове Аллигаторов. На ней указано место, где спрятаны сокровища!', 'A map that was created after putting together the map pieces found on Alligator Island. It appears to have a mark showing the location of treasure!', 'etc_map_ivory_i00', 0);
INSERT INTO `all_items` VALUES (5916, 'Spellbook Page', NULL, 'Кусок бумаги, который был когда-то страницей книги заклинаний. Двойной щелчок позволит посмотреть его поближе.', 'A torn piece of paper that seems to have been ripped out of a spellbook. If you double-click it, you can examine it closely.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5917, 'Kranvel\'s Spellbook: Chapter of Fire', NULL, 'Глава Книги Заклинаний Великого Мага Кранвела. Соберите все Главы - Огня, Воды, Ветра и Земли и отнесите их Старейшине Казиану.', 'Great Magus Kranvel\'s Spellbook: Chapter of Fire. Collect the Chapters on Fire, Water, Wind and Earth and take all of them to Elder Casian.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (5918, 'Kranvel\'s Spellbook: Chapter of Water', NULL, 'Глава Книги Заклинаний Великого Мага Кранвела. Соберите все Главы - Огня, Воды, Ветра и Земли и отнесите их Старейшине Казиану.', 'Great Magus Kranvel\'s Spellbook: Chapter of Water. Collect the Chapters on Fire, Water, Wind and Earth and take all of them to Elder Casian.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (5919, 'Kranvel\'s Spellbook: Chapter of Wind', NULL, 'Глава Книги Заклинаний Великого Мага Кранвела. Соберите все Главы - Огня, Воды, Ветра и Земли и отнесите их Старейшине Казиану.', 'Great Magus Kranvel\'s Spellbook: Chapter of Wind. Collect the Chapters on Fire, Water, Wind and Earth and take all of them to Elder Casian.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5920, 'Kranvel\'s Spellbook: Chapter of Earth', NULL, 'Глава Книги Заклинаний Великого Мага Кранвела. Соберите все Главы - Огня, Воды, Ветра и Земли и отнесите их Старейшине Казиану.', 'Great Magus Kranvel\'s Spellbook: Chapter of Earth. Collect the Chapters on Fire, Water, Wind and Earth and take all of them to Elder Casian.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5921, 'Worthless Piece of Paper', NULL, 'Кусок бумаги с ненужными записями.', 'A paper piece that has useless scribbles written on it.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5922, 'Blueprint: Giants Golem 1', NULL, 'Часть плана голема из эпохи Гигантов. Первая страница из пяти.', 'Part of the golem blueprints from the Titan era. The first page out of five pages.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5923, 'Blueprint: Giants Golem 2', NULL, 'Часть плана голема из эпохи Гигантов. Вторая страница из пяти.', 'Part of the golem blueprints from the Titan era. The second page out of five pages.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5924, 'Blueprint: Giants Golem 3', NULL, 'Часть плана голема из эпохи Гигантов. Третья страница из пяти.', 'Part of the golem blueprints from the Titan era. The third page out of five pages.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5925, 'Blueprint: Giants Golem 4', NULL, 'Часть плана голема из эпохи Гигантов. Четвертая страница из пяти.', 'Part of the golem blueprints from the Titan era. The fourth page out of five pages.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5926, 'Blueprint: Giants Golem 5', NULL, 'Часть плана голема из эпохи Гигантов. Пятая страница из пяти.', 'Part of the golem blueprints from the Titan era. The fifth page out of five pages.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5927, 'Book: Basics of Giants Magic, Chapter 1', NULL, 'Книга магии Гигантов, первая глава.', 'A book on the magic of the giants from the era of Titans, 1st chapter.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (5928, 'Book: Basics of Giants Magic, Chapter 2', NULL, 'Книга магии Гигантов, вторая глава.', 'A book on the magic of the giants from the era of Titans, 2nd chapter.', 'etc_paper_blue_i00', 0);
