INSERT INTO `all_items` VALUES (5932, 'Handbook: Giants Architecture, Chapter 1', NULL, 'Записи по архитектуре гигантов, первая глава.', 'An architectural handbook of the giants from the era of Titans, 1st chapter.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (5933, 'Handbook: Giants Architecture, Chapter 2', NULL, 'Записи по архитектуре гигантов, вторая глава.', 'An architectural handbook of the giants from the era of Titans, 2nd chapter.', 'etc_paper_red_i00', 0);
