INSERT INTO `all_items` VALUES (5937, 'Book: Giants Medical Science, Chapter 1', NULL, 'Книга по медицине Гигантов, первая глава.', 'A medical book of the giants from the era of Titans, 1st chapter.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5938, 'Book: Giants Medical Science, Chapter 2', NULL, 'Книга по медицине Гигантов, вторая глава.', 'A medical book of the giants from the era of Titans, 2nd chapter.', 'etc_paper_white_i00', 0);
