INSERT INTO `all_items` VALUES (5940, 'Book: Giants Medical Science, Chapter 4', NULL, 'Книга по медицине Гигантов, четвертая глава.', 'A medical book of the giants from the era of Titans, 4th chapter.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5941, 'Book: Giants Medical Science, Chapter 5', NULL, 'Книга по медицине Гигантов, пятая глава.', 'A medical book of the giants from the era of Titans, 5th chapter.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5942, 'Giant\'s Love Letter', NULL, 'Похоже, у Гигантов было все в порядке с любовью.', 'It seems like even the giants used to have a love life.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (5943, 'Giants\' Doodle', NULL, 'Плохая картина, нарисованная неизвестным \"художником\" из расы Гигантов.', 'A crude picture drawn by a would-be painter giant.', 'etc_painting_i00', 0);
INSERT INTO `all_items` VALUES (5944, 'Ancient Parchment', NULL, 'Кусок манускрипта из эпохи Гигантов. Чтобы прочитать его, щелкните на нем два раза левой кнопкой мыши.', 'A piece of parchment from the Titan era. If you double-click it, you can read the contents.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5945, 'Book: Giants Science & Technology, Chapter 1', NULL, 'Часть книги, описывающей науку и технологию эпохи Гигантов, первая глава.', 'A part of the theory book that describes the science and technology of the Titan era. The 1st of five chapters.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (5946, 'Book: Giants Science & Technology, Chapter 2', NULL, 'Часть книги, описывающей науку и технологию эпохи Гигантов, вторая глава.', 'A part of the theory book that describes the science and technology of the Titan era. The 2nd of five chapters.', 'etc_spell_books_white_i00', 0);
