INSERT INTO `all_items` VALUES (5950, 'Almanac: Titan Culture, Chapter 1', NULL, 'Часть альманаха по культуре эпохи Гигантов, первая глава.', 'Part of the almanac that contains information about the culture of the Titan era. The 1st of five chapters.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5951, 'Almanac: Titan Culture, Chapter 2', NULL, 'Часть альманаха по культуре эпохи Гигантов, вторая глава.', 'Part of the almanac that contains information about the culture of the Titan era. The 2nd of five chapters.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5952, 'Almanac: Titan Culture, Chapter 3', NULL, 'Часть альманаха по культуре эпохи Гигантов, третья глава.', 'Part of the almanac that contains information about the culture of the Titan era. The 3rd of five chapters.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5953, 'Almanac: Titan Culture, Chapter 4', NULL, 'Часть альманаха по культуре эпохи Гигантов, четвертая глава.', 'Part of the almanac that contains information about the culture of the Titan era. The 4th of five chapters.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5954, 'Almanac: Titan Culture, Chapter 5', NULL, 'Часть альманаха по культуре эпохи Гигантов, пятая глава.', 'Part of the almanac that contains information about the culture of the Titan era. The 5th of five chapters.', 'etc_spell_books_summon_i00', 0);
INSERT INTO `all_items` VALUES (5955, 'Ancient Titan Book', NULL, 'Книга, написанная в эпоху Гигантов. Чтобы прочитать ее, щелкните на ней два раза левой кнопкой мыши.', 'A book from the Titan era. If you double-click it, you can examine its contents.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (5956, '15 Year Old Wine', NULL, 'Подарок от Харлана в знак благодарности. Вино среднего качества 15-летней выдержки.', 'A gift from Harlan as a token of gratitude. It is aged 15 years. Average quality wine.', 'etc_luxury_wine_a_i00', 0);
INSERT INTO `all_items` VALUES (5957, '30 Year Old Wine', NULL, 'Подарок от Харлана в знак благодарности. Вино высокого качества 30-летней выдержки.', 'A gift from Harlan as a token of gratitude. It is aged 30 years. High quality wine.', 'etc_luxury_wine_b_i00', 0);
INSERT INTO `all_items` VALUES (5958, '60 Year Old Wine', NULL, 'Подарок от Харлана в знак благодарности. Вино отличного качества 60-летней выдержки.', 'A gift from Harlan as a token of gratitude. It is aged 60 years. Excellent quality wine.', 'etc_luxury_wine_c_i00', 0);
INSERT INTO `all_items` VALUES (5959, 'Ritron\'s Dessert Recipe', NULL, 'Секретный рецепт изготовления десерта из фрукта Рилтона. Можно продать в лавке.', 'A secret recipe for making dessert by using ritron fruit as its ingredient. It can to sold at a store.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (5960, 'Ritron Jelly', NULL, 'Вкусное фруктовое желе. Можно продать в лавке.', 'Delicious jelly made from ritron fruit. It can be sold at a store.', 'etc_cobol_i04', 0);
INSERT INTO `all_items` VALUES (5961, 'Kail\'s Silver Basilisk', NULL, 'Королевская монета.', 'Coins that were obtained during demon hunting0', 'etc_kyles_silver_basilisk_i00', 0);
INSERT INTO `all_items` VALUES (5962, 'Kail\'s Gold Golem', NULL, 'Королевская монета.', 'Royal-grade coin0', 'etc_kyles_gold_golem_i00', 0);
INSERT INTO `all_items` VALUES (5963, 'Kail\'s Blood Dragon', NULL, 'Королевская монета.', 'Royal-grade coin0', 'etc_kyles_blood_dragon_i00', 0);
INSERT INTO `all_items` VALUES (5964, 'Warehouse Keeper\'s Medal', NULL, 'Медаль, выдаваемая Гильдией Железных Врат Смотрителям Складов по результатам их работы. Собрав их, можно поиграть в лото.', 'A medal that is issued by the Iron Gate Guild to Warehouse Keepers according to their productivity. If you collect them, you can use them to play bingo.', 'etc_irongate_medal_i00', 0);
INSERT INTO `all_items` VALUES (5965, 'Blank Scroll', NULL, 'Книга заклинаний, в которой нет заклинаний. Возможно она пригодится Торговцу Маммона?', 'A spellbook that does not contain any magical power. Perhaps it can be helpful if you deal with Mammon\'s Trader?', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (5966, 'Ancient Red Papyrus', NULL, 'Свиток папируса, найденный в Башне Дерзости. Двойное нажатие позволит посмотреть его поближе.', 'A papyrus scroll found in the Tower of Insolence. If you double-click it, you can read its contents.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (5967, 'Ancient Blue Papyrus', NULL, 'Свиток папируса, найденный в Башне Дерзости. Двойное нажатие позволит посмотреть его поближе.', 'A papyrus scroll found in the Tower of Insolence. If you double-click it, you can read its contents.', 'etc_paper_blue_i00', 0);
