INSERT INTO `all_items` VALUES (5970, 'Ancient Chain Letter', NULL, 'Странное письмо, найденное в Башне Дерзости. В нем написано \"Отправьте это письмо 10 людям, и будет вам счастье!\"', 'A mysterious letter found in the Tower of Insolence. Its text reads \"if you send this letter to 10 other people, you will have good luck!\"', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (5971, 'Ancient Joke Book', NULL, 'Коллекция шуток Гальфредо Ромера, королевского шута.', 'A collection of jokes of Galfredo Romer, a Royal Clown.', 'etc_piece_of_paper_black_i00', 0);
