INSERT INTO `all_items` VALUES (6002, 'Ancient Porcelain', NULL, 'Фарфор, принадлежащий эпохе древней империи, найденный в Башне Дерзости. Еще не был оценен экспертами-антикварами.', 'A porcelain from the era of an ancient empire found in the Tower of Insolence. It has not been evaluated by antique experts yet.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (6003, 'Ancient Porcelain: Excellent', NULL, 'Фарфор, принадлежащий эпохе древней империи. Оценен как фарфор высшего качества.', 'A porcelain from the era of an ancient empire. Judged to be of the highest grade \"excellent\" porcelain.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (6004, 'Ancient Porcelain: High Quality', NULL, 'Фарфор, принадлежащий эпохе древней империи. Оценен как фарфор высокого качества.', 'A porcelain from the era of an ancient empire. Judged to be of \"high grade\" porcelain.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (6005, 'Ancient Porcelain: Low Quality', NULL, 'Фарфор, принадлежащий эпохе древней империи. Оценен как фарфор низкого качества качества.', 'A porcelain from the era of an ancient empire. Judged to be of \"low grade\" porcelain.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (6006, 'Ancient Porcelain: Lowest Quality', NULL, 'Фарфор, принадлежащий эпохе древней империи. Оценен как фарфор самого низкого качества.', 'A porcelain from the era of an ancient empire. Judged to be of the \"lowest grade\" porcelain.', 'etc_oil_pot_white_i00', 0);
