INSERT INTO `all_items` VALUES (6307, 'Sword of Limit', 'Guidance', '<Свойство Кристалла Души> Увеличивает Точность на 5', 'Guidance	a,<Soul Crystal Enhancement>n Increases the accuracy rate to 5.', 'weapon_sword_of_limit_i01', 2);
INSERT INTO `all_items` VALUES (6308, 'Sword of Limit', 'Critical Drain', '<Свойство Кристалла Души> Поглощает 9 НР цели при критической атаке', 'Critical Drain	a,<Soul Crystal Enhancement>n Absorbs HP +9 from target during a critical attack.', 'weapon_sword_of_limit_i01', 2);
INSERT INTO `all_items` VALUES (6309, 'Sword of Limit', 'Health', '<Свойство Кристалла Души> Увеличивает Максимальное НР на 25%', 'Health	a,<Soul Crystal Enhancement>n Increases maximum HP by 25%.', 'weapon_sword_of_limit_i01', 2);
INSERT INTO `all_items` VALUES (6310, 'Sword of Whispering Death', 'Empower', '<Свойство Кристалла Души> Увеличивает Маг. Атк. на 24', 'Empower	a,<Soul Crystal Enhancement>n Increases M. Atk. by 24.', 'weapon_deathbreath_sword_i01', 2);
INSERT INTO `all_items` VALUES (6311, 'Sword of Whispering Death', 'M. Atk.', '<Свойство Кристалла Души> Увеличивает потребление МР на 15% и увеличивает Маг. Атк. на 99 во время использования магии', 'Magic Power	a,<Soul Crystal Enhancement>n Increases MP consumption by 15% and increases M. Atk. by 99 during magic use.', 'weapon_deathbreath_sword_i01', 2);
INSERT INTO `all_items` VALUES (6312, 'Sword of Whispering Death', 'Magic Silence', '<Свойство Кристалла Души> Дает 10% шанс наложить Безмолвие, используя навык, который имеет плохой эффект на цель.', 'Magic Silence	a,<Soul Crystal Enhancement>n Increases the chances of causing Silence by 10% when using Dark Magic. Effect 1.', 'weapon_deathbreath_sword_i01', 2);
INSERT INTO `all_items` VALUES (6313, 'Homunkulus\'s Sword', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Магии на 15%', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd. by 15%.', 'weapon_homunkuluss_sword_i01', 2);
INSERT INTO `all_items` VALUES (6314, 'Homunkulus\'s Sword', 'Conversion', '<Свойство Кристалла Души> Увеличивает Максимальное МР на 60% и уменьшает Макс. НР на 40%', 'Conversion	a,<Soul Crystal Enhancement>n Increases maximum MP by 60% and decreases maximum HP by 40%.', 'weapon_homunkuluss_sword_i01', 2);
INSERT INTO `all_items` VALUES (6315, 'Homunkulus\'s Sword', 'Magic Paralyze', '<Свойство Кристалла Души> Дает 5% шанс наложить Паралич, используя вредоносное умение.', 'Magic Paralyze	a,<Soul Crystal Enhancement>n Increases the chances of causing paralysis by 5% when using Dark Magic upon a target. Effect 1.', 'weapon_homunkuluss_sword_i01', 2);
INSERT INTO `all_items` VALUES (6316, 'Food for Wyvern', NULL, 'Когда уровень голода крылатого дракона упадет до 55 % или ниже, его пища будет потребляться автоматически.', 'When the hunger gauge of a wyvern drops to 55% or below, its food will be consumed automatically.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (6317, 'Mixing Manual', NULL, 'Руководство с инструкциями, полученное от Торговца Уэсли, для того, чтобы использовать смесительную урну, расположенную в основании Башни Слоновой Кости.', 'A manual received from Magic Trader Wesley, with instructions for using the material mixing urn located in the basement of  the Ivory Tower.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (6318, 'Blood Fire', NULL, 'Темный огонь от Чистилища. Единственный способ расплавить истинное золото.', 'Dark flames from Purgatory. The only way to melt true gold.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (6319, 'Mimir\'s Elixir', NULL, 'Легендарный эликсир, дарующий безграничную мудрость. Отнесите это Магистру Ладду.', 'A legendary elixir said to bestow ultimate wisdom. Take it to Magister Ladd.', 'etc_lesser_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (6320, 'Pure Silver', NULL, 'Неотъемлемый ингредиент Эликсира Мимира. Отнесите это Магистру Ладду.', 'An essential ingredient of Mimir\'s Elixir. Take it to Magister Ladd.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (6321, 'True Gold', NULL, 'Неотъемлемый ингредиент Эликсира Мимира. Отнесите это Магистру Ладду.', 'An essential ingredient of Mimir\'s Elixir. Take it to Magister Ladd.', 'etc_broken_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (6322, 'Sage\'s Stone', NULL, 'Неотъемлемый ингредиент Эликсира Мимира. Отнесите это Магистру Джоан.', 'An essential ingredient of Mimir\'s Elixir. Take it to Magister Joan.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (6323, 'Sealed Phoenix Necklace', NULL, 'Печать можно снять у кузнеца в любой деревне. Когда печать снята, даются эффекты Маг. Защ.+4 и МР+26.', 'The seal can be broken with the help of the Blacksmith of Mammon. When the seal is broken, the effects of M. Def+4 and MP+26 are given.', 'accessary_phoenixs_necklace_i02', 0);
