INSERT INTO `all_items` VALUES (6338, 'Recipe: Sealed Majestic Earring(100%)', NULL, 'Могут использовать только Гномы. Рецепт изготовления Запечатанной Серьги Величия. Требуется Умение 8 уровня - Создать Предмет. 100% шанс успеха.', 'For Dwarves only. The recipe for the Sealed Majestic Earrings. Requires Create Item - Skill Level 8. The success rate is 100%.', 'etc_recipe_violet_i00', 5);
INSERT INTO `all_items` VALUES (6339, 'Recipe: Sealed Majestic Ring(70%)', NULL, 'Могут использовать только Гномы. Рецепт изготовления Запечатанного Кольца Величия. Требуется Умение 8 уровня - Создать Предмет. 70% шанс успеха.', 'For Dwarves only. The recipe for the Sealed Majestic Ring. Requires Create Item - Skill Level 8. The success rate is 70%.', 'etc_recipe_violet_i00', 5);
INSERT INTO `all_items` VALUES (6340, 'Recipe: Sealed Majestic Ring(100%)', NULL, 'Могут использовать только Гномы. Рецепт изготовления Запечатанного Кольца Величия. Требуется Умение 8 уровня - Создать Предмет. 100% шанс успеха.', 'For Dwarves only. The recipe for the Sealed Majestic Ring. Requires Create Item - Skill Level 8. The success rate is 100%.', 'etc_recipe_violet_i00', 5);
INSERT INTO `all_items` VALUES (6341, 'Sealed Phoenix Earring Gemstone', NULL, 'Неотъемлемый ингредиент для изготовления Запечатанной Серьги Феникса. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make a Sealed Phoenix Earring.  It can be sold at any store.', 'etc_gem_blue_i00', 6);
