INSERT INTO `all_items` VALUES (6343, 'Sealed Phoenix Necklace Beads', NULL, 'Неотъемлемый ингредиент для изготовления Запечатанной Серьги Феникса. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make a Sealed Phoenix Necklace.  It can be sold at any store.', 'BranchSys2.etc_sealed_phoenixbeads_i00', 6);
INSERT INTO `all_items` VALUES (6344, 'Sealed Majestic Necklace Beads', NULL, 'Неотъемлемый ингредиент для изготовления Запечатанного Ожерелья Величия. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make a Sealed Majestic Necklace.  It can be sold at any store.', 'BranchSys2.etc_sealed_majesticbeads_i00', 6);
INSERT INTO `all_items` VALUES (6345, 'Sealed Phoenix Ring Gemstone', NULL, 'Неотъемлемый ингредиент для изготовления Запечатанного Кольца Феникса. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make a Sealed Phoenix Ring.  It can be sold at any store.', 'etc_gem_blue_i00', 6);
