INSERT INTO `all_items` VALUES (6350, 'Amulet: Pa\'agrio\'s Honor', NULL, 'Амулет, необходимый для изучения умения \"Честь Паагрио\". Профессия: Верховный Шаман.Необходимый уровень: 66.', 'Amulet required for the Pa\'agrio\'s Honor spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (6351, 'Amulet: Ritual of Life', NULL, 'Амулет, необходимый для изучения умения \"Ритуал Жизни\". Профессия: Верховный Шаман.Необходимый уровень: 64.', 'Amulet required for the Ritual of Life spell. Used by Overlords.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (6352, 'Spellbook: Prayer', NULL, 'Книга, необходимая для изучения умения \"Молитва\". Профессия: Епископ.Необходимый уровень: 66.', 'Spellbook needed to learn Prayer. Used by Bishops.', 'etc_spell_books_white_i00', 0);
