INSERT INTO `all_items` VALUES (6360, 'Blue Seal Stone', NULL, 'Часть древней печати. Соберите их все. Стоят 3 Древних Адены.', 'A fragment of an ancient seal. Collect them all. Valued at 3 Ancient Adena.', 'etc_water_rune_i00', 0);
INSERT INTO `all_items` VALUES (6361, 'Green Seal Stone', NULL, 'Часть древней печати. Соберите их все, чтобы разбить печать. Стоят 5 Древних Аден.', 'A fragment of an ancient seal. Collect them all to break the seal. Valued at 5 Ancient Adena.', 'etc_wind_rune_i00', 0);
INSERT INTO `all_items` VALUES (6362, 'Red Seal Stone', NULL, 'Часть древней печати. Соберите их все, чтобы разбить печать. Стоят 10 Древних Аден.', 'A fragment of an ancient seal. Collect them all to break the seal. Valued at 10 Ancient Adena.', 'etc_fire_rune_i00', 0);
INSERT INTO `all_items` VALUES (6363, 'Stolen Infernium Ore', NULL, 'Инферниумовая руда, украденная у Гильдии Железных Врат. Отнесите ее Смотрителю Склада Ромпу из Адена, чтобы сыграть в лото.', 'Infernium ore once owned by the Iron Gate Guild. Take it to Warehouse Keeper Romp of Aden Castle Town to play bingo.', 'etc_inf_ore_high_i00', 0);
INSERT INTO `all_items` VALUES (6364, 'Forgotten Blade', NULL, 'Дает возможность получить одно из следующих особых свойств: Ускорение, Здоровье или Фокусировка.', 'Bestows one of the following functions: Haste, Health or Focus.', 'weapon_forgotten_blade_i00', 5);
INSERT INTO `all_items` VALUES (6365, 'Basalt Battlehammer', NULL, 'Дает возможность получить одно из следующих особых свойств: Поглощение HP, Здоровье или Регенерация НР.', 'Bestows one of the following functions: HP Drain, Health or HP Regeneration.', 'weapon_basalt_battlehammer_i00', 5);
INSERT INTO `all_items` VALUES (6366, 'Imperial Staff', NULL, 'Дает возможность получить одно из следующих особых свойств: Воодушевление, Регенерация МР или Магические Оковы.', 'Bestows one of the following functions: Empower, MP Regeneration or Magic Hold.', 'weapon_imperial_staff_i00', 5);
INSERT INTO `all_items` VALUES (6367, 'Angel Slayer', NULL, 'Дает возможность получить одно из следующих особых свойств: Крит. Урон, Поглощение HP или Ускорение.', 'Bestows one of the following functions: Crt. Damage, HP Drain or Haste.', 'weapon_angel_slayer_i00', 5);
