INSERT INTO `all_items` VALUES (6370, 'Saint Spear', NULL, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Наведение или Ускорение.', 'Bestows one of the following functions: Health, Guidance or Haste.', 'weapon_saint_spear_i00', 5);
INSERT INTO `all_items` VALUES (6371, 'Demon Splinter', NULL, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Крит. Оглушение.', 'Bestows one of the following functions: Focus, Health or Crt. Stun.', 'weapon_demon_splinter_i00', 5);
