INSERT INTO `all_items` VALUES (6387, 'Blessed Scroll of Resurrection for Pets', NULL, 'Волшебный свиток, который воскрешает мертвого питомца и полностью восстанавливает его опыт.', 'A magic scroll that resurrects a dead pet and restores its Exp. completely.', 'etc_scroll_of_resurrection_pet_i01', 1);
INSERT INTO `all_items` VALUES (6388, 'Lord of the Manor\'s Certificate of Approval', NULL, 'Это свидетельство позволяет предъявителю присоединяться к Лордам Рассвета, не принадлежа к клану, имеющему замок.', 'This certificate allows the bearer to join the Lords of Dawn without belonging to a castle-owning clan.', 'etc_permit_card_i00', 0);
INSERT INTO `all_items` VALUES (6389, 'Squash Seed', NULL, 'Ивент Осеннего Урожая - Два раза щелкните по нему, и появится молодая тыква.', 'Fall Harvest Event - Double click it and a young squash will appear.', 'etc_gourd_i00', 0);
INSERT INTO `all_items` VALUES (6390, 'Large Squash Seed', NULL, 'Ивент Осеннего Урожая - Два раза щелкните по нему, и появится большая молодая тыква', 'Fall Harvest Event - Double click it and a large young squash will appear.', 'etc_gourd_i01', 0);
INSERT INTO `all_items` VALUES (6391, 'Nectar', NULL, 'Ивент Осеннего Урожая и Арбузов - Вы можете обменять у Кота База на семена тыквы или абруза. Используется для выращивания тыкв и арбузов.', 'Fall Harvest Event - Buzz the Cat will give you a squash seed for it, or it may be used to grow a squash.', 'etc_nectar_i00', 0);
INSERT INTO `all_items` VALUES (6392, 'Event - Medal', NULL, 'Ивентовая медаль.', 'L2 Medal Collection Event - If you take it to an Event Manager, he will trade it for a prize item of your choice.', 'etc_event_medal_i00', 0);
INSERT INTO `all_items` VALUES (6393, 'Event - Glittering Medal', NULL, 'Ивентовая медаль.', 'L2 Medal Collection Event - It is used to raise the grade of a collector during the event.', 'etc_event_glitter_medal_i00', 0);
INSERT INTO `all_items` VALUES (6394, 'Red Party Mask', NULL, 'Модный аксессуар, с помощью которого можно подчеркнуть свою индивидуальность.', 'A fashion accessory item that allows you to show a unique appearance.', 'etc_party_mask_i01', 0);
INSERT INTO `all_items` VALUES (6395, 'Amulet: Chant of Predator', NULL, 'Амулет, необходимый для изучения умения \"Напев Хищника\". Профессия: Вестник Войны.Необходимый уровень: 48.', 'Amulet required for the Chant of Predator spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (6396, 'Amulet: Chant of Eagle', NULL, 'Амулет, необходимый для изучения умения \"Напев Орла\". Профессия: Вестник Войны.Необходимый уровень: 48.', 'Amulet required for the Chant of Eagle spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (6397, 'Amulet: Chant of Vampire', NULL, 'Амулет, необходимый для изучения умения \"Напев Вампира\". Профессия: Вестник Войны.Необходимый уровень: 44.', 'Amulet required for the Chant of Vampire spell. Used by Warcryers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (6398, 'Spellbook: Body of Avatar', NULL, 'Книга, необходимая для изучения умения \"Инкарнация Тела\". Профессия: Епископ.Необходимый уровень: 48.', 'Spellbook needed to learn Body of Avatar. Used by Bishops.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (6399, 'Badge of Rabbit', NULL, 'Значок, который указывает, что ранг его обладателя - \"кролик\". Без этого значка нельзя доказать ранг.', 'The badge that indicates that its bearer\'s event collector grade is \"rabbit.\"  Without this badge, one cannot prove one\'s grade.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (6400, 'Badge of Hyena', NULL, 'Значок, который указывает, что ранг его обладателя - \"гиена\". Без этого значка нельзя доказать ранг.', 'The badge that indicates that its bearer\'s event collector grade is \"hyena.\"  Without this badge, one cannot prove one\'s grade.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (6401, 'Badge of Fox', NULL, 'Значок, который указывает, что ранг его обладателя - \"лиса\". Без этого значка нельзя доказать ранг.', 'The badge that indicates that its bearer\'s event collector grade is \"fox.\"  Without this badge, one cannot prove one\'s grade.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (6402, 'Badge of Wolf', NULL, 'Значок, который указывает, что ранг его обладателя - \"волк\". Без этого значка нельзя доказать ранг.', 'The badge that indicates that its bearer\'s event collector grade is \"wolf.\"  Without this badge, one cannot prove one\'s grade.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (6403, 'Star Shard', NULL, 'Фестиваль Звездного Света Ивент – подарок с неба. Если выбросить, он образует маленький взрыв. Может использоваться как компонент для создания других видов фейерверка.', 'Starlight Festival Event - A gift from the sky.  When it is thrown, it creates a small explosion. Can be used as an ingredient to make other types of fireworks.', 'etc_fairy_fire_i00', 0);
INSERT INTO `all_items` VALUES (6404, 'Gunpowder', NULL, 'Фестиваль Звездного Света Ивент – Черный порошок. Компонент, использующийся для создания большего фейерверка.', 'Starlight Festival Event - Black powder. An ingredient used to make larger fireworks.', 'etc_powder_black_i00', 0);
INSERT INTO `all_items` VALUES (6405, 'Magnesium', NULL, 'Фестиваль Звездного Света Ивент – химический состав, который производит сильную вспышку. Необходим для создания большого фейерверка.', 'Starlight Festival Event - A chemical compound that generates a powerful flash when ignited. It is needed to make large fireworks.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (6406, 'Firework', NULL, 'Фестиваль Звездного Света Ивент – Взрывчатое устройство, которое блестяще освещает небо.', 'Starlight Festival Event - An explosive device that brilliantly lights up the sky.', 'etc_small_ultra_bomb_i00', 0);
INSERT INTO `all_items` VALUES (6407, 'Large Firework', NULL, 'Фестиваль Звездного Света Ивент – Большое взрывчатое устройство, которое загорается, чтобы осветить небо.', 'Starlight Festival Event - A large explosive device that ignites to light up the sky.', 'etc_ultra_bomb_i00', 0);
INSERT INTO `all_items` VALUES (6408, 'Formal Wear', NULL, 'Одежда для свадеб. Выглядит как подвенечное платье для персонажей женского пола и как смокинг для персонажей мужского пола.', 'Formal wear appears as a wedding dress for female characters and as a tuxedo for male characters.', 'armor_t2000_ul_i00', 0);
INSERT INTO `all_items` VALUES (6409, '2006 Battle Tournament - CP Potion', NULL, 'Восстанавливает СР на 200.', 'Restores CP by 200.', 'etc_cp_potion_i01', 3);
INSERT INTO `all_items` VALUES (6410, '2006 Battle Tournament - Quick Healing Potion', NULL, 'Магическое зелье, которое быстро восстанавливает НР. Однако его эффект не длителен.', 'A magical potion that quickly restores HP. However, its effects do not last.', 'etc_potion_gold_i00', 3);
INSERT INTO `all_items` VALUES (6411, 'Small Nimble Green Fish', NULL, 'Двойной щелчок меняет это в случайный предмет. Измененный предмет может использоваться в основном производстве.', 'Double-click to randomly change into another item. The changed item can be used as an ingredient for general manufacture.', 'etc_tuna_i07', 0);
