INSERT INTO `all_items` VALUES (6519, 'Green Colored Lure - Low Grade', NULL, 'Наживка для рыбалки. Чем выше ранг, тем меньше времени нужно для привлечения рыбы. Это приманка для быстрой рыбы.', 'A lure used for fishing. The higher the grade of the lure, the less time it will take for a fish to take the bait. This bait is preferred by fast fish.', 'etc_bait_i00', 16);
