INSERT INTO `all_items` VALUES (6589, 'Imperial Staff', 'Magic Hold', '<Свойство Кристалла Души>Дает шанс 20% колдовства Корней Дриад при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Hold	a,<Soul Crystal Enhancement>n Increases the chances of causing Dryad Root by 20% when using dark magic upon a target. Increases damage inflicted during PvP.', 'weapon_imperial_staff_i01', 5);
