INSERT INTO `all_items` VALUES (6604, 'Demon Splinter', 'Critical Stun', '<Свойство Кристалла Души> Дает шанс 27% оглушить цель при Крит. Атк. Наносит дополнительный урон в PvP.', 'Crt. Stun	a,<Soul Crystal Enhancement>n Produces a stun effect at a rate of about 25% during a critical attack. Increases damage inflicted during PvP.', 'weapon_demon_splinter_i01', 5);
