INSERT INTO `all_items` VALUES (6608, 'Arcana Mace', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Маг. На 15%. Наносит дополнительный урон в PvP.', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd. by 15%. Increases damage inflicted during PvP.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (6609, 'Arcana Mace', 'MP Regeneration', '<Свойство Кристалла Души> Увеличивает Реген. MP. Наносит дополнительный урон в PvP.', 'MP Regeneration	a,<Soul Crystal Enhancement>n Increases MP regeneration rate. Increases damage inflicted during PvP.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (6610, 'Arcana Mace', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Increases damage inflicted during PvP.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (6611, 'Infinity Blade', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При Крит. Атк. применяется вредоносное умение, понижающее Физ. Защ. противника. Увеличивает Макс. HP, Макс. MP, Макс. CP и защиту щита. Дает шанс отразить отрицательные эффекты обратно врагу. Наносит дополнительный урон в PvP.', 'During a critical attack, decreases one\'s P. Def and increases de-buff casting ability, damage shield effect, Max HP, Max MP, Max CP, and shield defense power. Enhances damage to target during PvP.', 'weapon_the_sword_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6612, 'Infinity Cleaver', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. Увеличивает шанс успеха/мощность Крит. Атк., Макс.HP, Макс.CP, наносит дополнительный урон в PvP. Также причиняет дополнительный урон при Крит. Атк. и дает шанс отразить отрицательные эффекты обратно врагу.', 'Increases critical attack success rate/power, MaxHP, MaxCP and damage inflicted during PvP. Inflicts extra damage on critical attack. Reflects debuff attack back on enemy.', 'weapon_the_two_handed_sword_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6613, 'Infinity Axe', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При критической атаке отражает часть урона и дает заклинание, вызывающее у противника внутренний конфликт. Увеличивает шанс защиты щитом, Макс. HP, Макс МР и Макс. CP. Наносит дополнительный урон в PvP.', 'During a critical attack, it bestows one the ability to cause internal conflict to one\'s opponent. Damage shield function, Max HP, Max MP, Max CP as well as one\'s shield defense rate are increased. It also enhances damage to target during PvP.', 'weapon_the_axe_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6614, 'Infinity Rod', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При использовании благотворного умения на цель увеличивает Восстановление HP до 100%, а также Макс. MP, Макс. CP, Скор. Маг. и Скорость Восстановления MP. Наносит дополнительный урон в PvP.', 'When good magic is cast upon a target, increases Max MP, Max CP, Casting Spd, and MP regeneration rate.  During PvP, HP regeneration is increased to 100% and enhances damage to target.', 'weapon_the_mace_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6615, 'Infinity Crusher', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. Увеличивает Макс. HP, Макс. CP и Скор. Атк. Оглушает цель при критической атаке и дает шанс отразить отрицательные эффекты обратно врагу. Наносит дополнительный урон в PvP.', 'Increases Max HP, Max CP, and Atk. Spd. Stuns a target when a critical attack occurs and has possibility of reflecting the skill back on the player. Enhances damage to target during PvP.', 'weapon_the_hammer_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6616, 'Infinity Scepter', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При использовании благотворного умения есть шанс Восстановления HP до 100%. Увеличивает Макс. MP, Макс. CP и Маг. Атк., уменьшает расход MP, увеличивает шанс магической Крит. Атк. и понижает шанс прерывания колдовства. Наносит дополнительный урон в PvP.', 'When casting good magic, HP regeneration increases 100%, raises MAX MP, Max CP, M. Atk., lowers MP Consumption, increases the Magic Critical rate, and reduces the Magic Cancel. Enhances damage to target during PvP.', 'weapon_the_staff_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6617, 'Infinity Stinger', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. Увеличивает Макс. MP, Макс. CP, Скор. Атк., Скорость, Скорость Восстановления MP и шанс успеха в случае применения Смертельного Удара со спины. При критической атаке накладывает на цель безмолвие и дает эффект Ярости Вампира. Наносит дополнительный урон в PvP.', 'Increases Max MP, Max CP, Atk. Spd., MP regen rate, and the success rate of Mortal and Deadly Blow from the back of the target. Silences the target when a critical attack occurs and has Vampiric Rage effect. Enhances damage to target during PvP.', 'weapon_the_dagger_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6618, 'Infinity Fang', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. Увеличивает Макс. HP, Макс MP, Макс. CP и Уклонение. Оглушает цель при критической атаке и дает шанс отразить отрицательные эффекты обратно врагу. Наносит дополнительный урон в PvP.', 'Increases Max HP, Max MP, Max CP and evasion. Stuns a target when a critical attack occurs and has possibility of reflecting the skill back on the player at a certain probability rate. Enhances damage to target during PvP.', 'weapon_the_fist_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6619, 'Infinity Bow', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При критической атаке замедляет цель, дает эффект Экономии, увеличивает скорострельность лука, Макс. MP и Макс. CP. Наносит дополнительный урон в PvP.', 'Increases Max MP/Max CP and decreases re-use delay of a bow. Slows target when a critical attack occurs and has Cheap Shot effect. Enhances damage to target during PvP.', 'weapon_the_bow_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6620, 'Infinity Wing', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При критической атаке накладывает на цель безмолвие, дает шанс отразить отрицательные эффекты обратно врагу, увеличивает Макс. HP, Макс. MP, Макс. CP и шанс Крит. Атк. Наносит дополнительный урон в PvP.', 'When a critical attack occurs, increases Max HP, Max MP, Max CP and critical chance. Silences the target and has possibility of reflecting the skill back on the target. Enhances damage to target during PvP.', 'weapon_the_dualsword_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6621, 'Infinity Spear', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При критическом ударе прерывает колдовство цели, дает шанс отразить отрицательные эффекты обратно врагу, увеличивает Макс. HP, Макс. CP, Скор. Атк. и Точность. Наносит дополнительный урон в PvP.', 'During a critical attack, increases Max HP, Max CP, Atk. Spd. and Accuracy. Casts dispel on a target and has possibility of reflecting the skill back on the target. Enhances damage to target during PvP.', 'weapon_the_pole_of_hero_i00', 5);
INSERT INTO `all_items` VALUES (6622, 'Giant\'s Codex', NULL, 'Кодекс гигантов. Необходим для модификации умений.', 'Giants\' Scroll. Take it to a certain NPC to enchant skills.', 'etc_codex_of_giant_i00', 0);
