INSERT INTO `all_items` VALUES (6665, 'Deluxe Chest Key - Grade 1', NULL, 'Очень старый и ржавый ключ, который больше нельзя использовать. Такие скупают в магазине.', 'Opens a level 1~19 treasure chest with a success rate of 100%. When opening a higher level treasure chest, the success rate will decrease. However, the success rate will be the same for receiving an item as a reward.', 'etc_old_key_i00', 0);
