INSERT INTO `all_items` VALUES (6673, 'Festival Adena', NULL, 'Валюта, используемая в ивенте «2005 Lineage II Live».', 'The coin was mined during a mermaid hunt.', 'etc_coin_of_fair_i00', 0);
INSERT INTO `all_items` VALUES (6674, 'Sealed Imperial Crusader Breastplate', NULL, 'Запечатанная Кираса Имперского Крестоносца. Печать может быть сломана с помощью Кузнеца Маммона.', 'Sealed Imperial Crusader Breastplate. Its seal can be broken with the help of the Blacksmith of Mammon.', 'armor_t88_u_i02', 0);
INSERT INTO `all_items` VALUES (6675, 'Sealed Imperial Crusader Gaiters', NULL, 'Запечатанные Набедренники Имперского Крестоносца. Печать может быть сломана с помощью Кузнеца Маммона.', 'Sealed Imperial Crusader Gaiters. Its seal can be broken with the help of the Blacksmith of Mammon.', 'armor_t88_l_i02', 0);
