INSERT INTO `all_items` VALUES (6724, 'Sealed Tateossian Earring', NULL, 'Печать может быть сломана с помощью Кузнеца Маммона. Снятие печати дает эффект Маг. Защ.+3 и MP+31.', 'The seal can be broken with the help of the Blacksmith of Mammon. When the seal is broken, the effect of M. Def+3 and MP+31 is given.', 'accessory_tateossian_earring_i02', 0);
INSERT INTO `all_items` VALUES (6725, 'Sealed Tateossian Ring', NULL, 'Печать может быть сломана с помощью Кузнеца Маммона. Снятие печати дает эффект Маг. Защ.+2 и MP+21.', 'The seal of this item can be broken by going through the Blacksmith of Mammon. When the seal is broken, it will produce the effects of M. Def. +2 and MP+21.', 'accessory_tateossian_ring_i02', 0);
