INSERT INTO `all_items` VALUES (6789, 'Mercenary Posting Ticket (Teleporter1)', NULL, 'Позволяет телепортироваться во внутренний двор замка или к стражам. Размещается в Годдарде внутри замка.', 'Placed in Goddard, at the Teleporter or inside the castle, this ticket allows teleportation to the inner castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (6790, 'Mercenary Posting Ticket (Teleporter2)', NULL, 'Позволяет телепортироваться во внешний двор замка или к стражам. Размещается в Годдарде внутри замка.', 'Placed in Goddard, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (6791, 'Mercenary Posting Ticket (Teleporter3)', NULL, 'Позволяет телепортироваться во внутренний или внешний двор замка. Размещается в Годдарде внутри замка.', 'Placed in Goddard, at the Teleporter or inside the castle, this ticket allows teleportation to the inner or outer castle.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (6792, 'Greater Mercenary Posting Ticket (Sword/Stationary)', NULL, 'Годдард/Мечники/Неподвижно. Используется, чтобы вызвать наемников, если Печатью Раздора владеют Лорды Рассвета.', 'Goddard/Sword/Stationary. Posting impossible when Seal of Strife is owned by Dusk.', 'mticket_sword_fix_i00', 8);
