INSERT INTO `all_items` VALUES (6834, 'Circlet of Innadril', NULL, 'Диадема Нарцисса. Может быть одета лордом замка Иннадрил и членами его клана, но не альянса. При надевании позволяет использовать умение замка. Не может быть обменена или выброшена.', 'Daffodil Circlet. Can be worn by the lord of Innadril Castle and clan members but not by allies. Allows use of Residential Skills when equipped.', 'accessory_pledge_cap1_i00', 0);
