INSERT INTO `all_items` VALUES (7015, 'Shield of Castle Pledge', NULL, 'Щит, который может использоваться только членами клана, которому принадлежит замок.', 'A shield that can only be used by the members of a clan that owns a castle.', 'shield_pledge_shield_i00', 0);
INSERT INTO `all_items` VALUES (7016, 'Seed: Blue Cobol', NULL, 'Семя Синего Кобола. Для получения плода вживите его в монстра в районе Диона. Наилучшего результата можно достичь, если персонаж и монстр 32-42 уровней.', 'Plant this seed onto a monster in the Dion area and it will bear the fruit of the Blue Cobol. For best results, a level 32-42 character must plant it on a level 32-42 monster.', 'etc_cobol_seed_i00', 10);
