INSERT INTO `all_items` VALUES (7138, 'Honey Pouch', NULL, 'Хорошо запечатанный мешочек меда, собранного пчелами. Отнесите это Эмилии.', 'Well sealed pouch of honey collected from bees. Take this to Emily.', 'etc_seed_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7139, 'Bracelet of Lizardman', NULL, 'Браслет Ящера Лито. Отдайте его Стражу Рату в Городе Гиран.', 'A bracelet that Leto Lizardman wears. Take this to Guard Rath in Giran Castle Town.', 'etc_leash_i00', 0);
INSERT INTO `all_items` VALUES (7140, 'Cross of Einhasad', NULL, 'Святой крест, который был найден в Лесу Неупокоенных. Отнесите это священнику Города Руна.', 'A holy item that was found in the Forest of the Dead. Take this to the priest of the Rune Township.', 'etc_cross_of_einhasad_i00', 0);
INSERT INTO `all_items` VALUES (7141, 'Cross of Einhasad', NULL, 'Святой крест, который был найден в Лесу Неупокоенных. Священник Городка Руны возвратил это Вам. Отнесите это Темному Магистру Эльфов Тифарену.', 'A holy cross that was found in the Forest of the Dead. The Priest of the Rune Township returned it to you. Take this to Dark Elf Magister Tifaren.', 'etc_cross_of_einhasad_i00', 0);
INSERT INTO `all_items` VALUES (7142, 'Lost Skull of Elf', NULL, 'Череп эльфа, о котором просил Великий Магистр Тифарен.', 'A skull of an elf that Grand Magister Tifaren asked you to bring.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (7143, 'Letter of Innocentin', NULL, 'Контракт между Верховным Жрецом Инносентином и мертвым исследователем находится в этом письме.', 'A contract between High Priest Innocentin and the dead explorer is in this letter.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (7144, 'Jewel of Adventurer', NULL, 'Драгоценный камень исследователя. Цвет драгоценного камня меняется по воле исследователя.', 'Jewel that the explorer possessed. The color of jewel changes by the explorer\'s call.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (7145, 'Jewel of Adventurer', NULL, 'Драгоценный камень исследователя. Цвет драгоценного камня меняется по воле исследователя.', 'Jewel that the explorer possessed. The color of jewel changes by the explorer\'s call.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (7146, 'Sealed Report Box', NULL, 'Коробка сообщений исследователя. Много раз запечатана. Отнесите это призраку исследователя.', 'Explorer\'s report box. It is sealed multiple times. Take this to the ghost of explorer.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7147, 'Report Box', NULL, 'Коробка сообщений исследователя. Заперта. Отнесите ее Верховному Жрецу Инносентину.', 'Explorer\'s report box. The box is locked. Take this to High Priest Innocentin.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7148, 'Lidia\'s Hairpin', NULL, 'Булавка из волос Лидии выполнена в форме лунного цветка.', 'Lidia\'s hair pin that has moonlight flower shape.', 'etc_flower_i00', 0);
INSERT INTO `all_items` VALUES (7149, 'Silver Key', NULL, 'Ключ с выгравированным серебряным копьем. Если есть ключ, значит где-то есть и замок.', 'A silver spear is engraved on this key. There must be a lock that can be opened with this key.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (7150, 'Silver Spear', NULL, 'Награда, которая дана семье за высокие заслуги членом королевской семьи Эльмора. Декоративное копье, в бою бесполезно.', 'A reward that is given to the family with highest merit by the royal member of Elmore land. It is a model spear thus it has no attack power.', 'weapon_winged_spear_i01', 0);
INSERT INTO `all_items` VALUES (7151, 'Suspicious Totem Doll', NULL, 'Кукла-тотем. Вы получили ее, охотясь на темных магов согласно инструкциям Служанки Лидии. Отнесите это к таинственному магу и задайте ему пару вопросов.', 'A totem doll you have obtained while hunting black magi according to the instructions of Lidia\'s maid. Take this to the mysterious magus and question him.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (7152, 'Flower Bouquet', NULL, 'Букет Цветов. Дориан просил, чтобы вы возложили его на могильном камне на юге.', 'A flower bouquet that Dorian asked you to lay at the gravestone in the south.', 'etc_flower_bouquet_i01', 0);
INSERT INTO `all_items` VALUES (7153, 'Silver Cross of Einhasad', NULL, 'Талисман, который дал Вам Дориан. Он попросил, чтобы вы нашли информацию о монстрах, которые появляются в Лесу Неупокоенных ночью.', 'A talisman given by Dorian. He asked you to find information about the monsters that appear in the Forest of the Dead at night.', 'etc_cross_of_einhasad_i00', 0);
INSERT INTO `all_items` VALUES (7154, 'Broken Silver Cross of Einhasad', NULL, 'Талисман, который дал Вам Дориан. Сломан неведомой чудовищной силой.', 'A talisman given by Dorian.  It seems to have been cracked by a powerful force.', 'etc_cross_of_einhasad_i01', 0);
INSERT INTO `all_items` VALUES (7155, 'Lidia\'s Dress', NULL, 'Красное платье из могилы. Выглядит довольно аристократично.', 'A red dress that was unearthed from the grave of Rose. It exhibits an aristocratic taste.', 'etc_ladys_dress_i00', 0);
INSERT INTO `all_items` VALUES (7156, 'Suspicious Totem Doll', NULL, 'Кукла-тотем, которая была возвращена таинственным магом. Отнесите ее жрецам Городка Руны и задайте им пару вопросов.', 'The totem doll that was returned by the mysterious magus. Take it to the priests of the Rune Township and question them about it.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (7157, 'Gemstone Key', NULL, 'Ключ, украшенный драгоценными камнями. Его называют \"Драгоценный жезл\", что указывает на принадлежность королю.', 'A gemstone studded key. It has a nickname of \"bejeweled staff\" that indicates the authority of the king.', 'etc_old_key_i00', 0);
INSERT INTO `all_items` VALUES (7158, 'Suspicious Totem Doll', NULL, 'Подозрительная кукла-тотем, полученная после убийства подчиненных Тироля.', 'A suspicious totem doll that one obtains after slaying the underlings of Triol.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (7159, 'Box of Cookies', NULL, 'Хорошо запечатанная коробка с печеньем.', 'Well sealed box of cookies.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7160, 'Luxury Wine', NULL, 'Элитное вино.', 'Premium wine that is on delivery.', 'etc_luxury_wine_a_i00', 0);
INSERT INTO `all_items` VALUES (7161, 'Skein of Yarn', NULL, 'Пряжа сделана из паутины. Она крепкая и эластичная.', 'Yarn made of twisted spider web. Tenacious and sturdy.', 'etc_skein_white_i00', 0);
INSERT INTO `all_items` VALUES (7162, 'Rough Jewel', NULL, 'Необработанный драгоценный камень.', 'Rough stone of jewel. Becomes a beautiful jewel when processed.', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (7163, 'Enchanted Iron', NULL, 'Это крепче обычного железа. Инструменты, сделанные из этого железа, как говорят, являются бесценными.', 'Sturdier than generic iron. Tools made of this iron are said to be priceless.', 'etc_lump_blue_i00', 0);
INSERT INTO `all_items` VALUES (7164, 'Signet Ring', NULL, 'Печать благородной семьи.', 'A seal that represents noble family.', 'etc_royal_seal_of_lord_i04', 0);
INSERT INTO `all_items` VALUES (7165, 'Map', NULL, 'Карта нарисованная для Кота Мики.', 'A map that is drawn for Miki the Cat.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7166, 'Medicinal Herb', NULL, 'Лекарственная трава, которую нашел Мики на Острове Дьявола. Она нужна Гентлеру.', 'A medicinal herb that Miki the Cat found in Devil\'s Isle. Gentler is in need of this herb.', 'etc_ginseng_red_i00', 0);
INSERT INTO `all_items` VALUES (7167, 'Crystal of Seal', NULL, 'Кристалл, который используется, чтобы запечатать алтарь.', 'A crystal that is used to activate the sealing in the altar.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (7168, 'Blood of Saint', NULL, 'Кровь святого. Обладает святой силой.', 'Saint\'s blood that has power of holiness.', 'etc_dragon_blood_i00', 0);
INSERT INTO `all_items` VALUES (7169, 'Blood of Saint', NULL, 'Кровь Псоглава. В ней заключена сила Эйнхасад.', 'The blood obtained at the time of Kel Mahum\'s death. It contains the power of Einhasad.', 'etc_dragons_blood_i01', 0);
INSERT INTO `all_items` VALUES (7170, 'Seal of Light', NULL, 'Печать Таинственного Некроманта. В ней заключена сила света.', 'A seal from a Mysterious Necromancer. It uses the power of light.', 'etc_jewel_white_i00', 0);
INSERT INTO `all_items` VALUES (7171, 'Bead of Obedience', NULL, 'Драгоценный камень, добытый у псоглавов. В нем заключена сила Эйнхасад.', 'A gem from Kel Mahum that has power of Einhasad.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (7172, 'Gem of Saints', NULL, 'Драгоценный камень, который остался после кремации святого. Обладает святой силой.', 'A gem that is left after the cremation of a saint. It has power of holiness.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (7173, 'Feather Ornament', NULL, 'Символ воина Ящеров Лангк.', 'A warrior symbol for Langk Lizardman.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (7174, 'Tooth of Totem', NULL, 'Зуб, обладающий таинственной силой.', 'A tooth that has mysterious power.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (7175, 'Tooth of Dragon', NULL, 'Клык, найденный у командиров Ящеров Лангк, который делает их сильнее.', 'A tooth of Langk Lizardman Commanders that strengthens their warriors.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (7176, 'Letter of Iris', NULL, 'Письмо от Ирис Магистру Ромеру в Город Глудио.', 'A letter from Iris to Magister Rohmer in the Town of Gludio.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (7177, 'Letter of Rohmer', NULL, 'Письмо от Ромера, адресованное Магистру Ирис в Деревню Глудин.', 'A letter from Rohmer to Magister Iris in Gludin Village.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (7178, 'Black Bone Necklace', NULL, 'Оберег Воинов Ящеров Мэль.', 'A charm of Maille Lizardman Warriors.', 'etc_totem_necklace_black_i00', 0);
INSERT INTO `all_items` VALUES (7179, 'Red Bone Necklace', NULL, 'Оберег Командиров Ящеров Мэль.', 'A charm of Maille Lizardman Commanders.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (7180, 'Incense Pouch', NULL, 'Мешочек ладана с таинственным ароматом.', 'A pouch of incense with mysterious scent.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7181, 'Gem of Maille Lizardman', NULL, 'Драгоценный камень Ящеров Мэль, обладающий таинственной силой.', 'A gem of Maille Lizardman that has mysterious power.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (7182, 'Patrol\'s Report', NULL, 'Сообщение от Стража Праги для Магистра Ромера.', 'A report from Guard Praga to Magister Rohmer.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (7183, 'Shining Gem', NULL, 'Драгоценный камень, управляющий арахнидами.', 'A gem that controls Araneid.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (7184, 'Shining Red Gem', NULL, 'Драгоценный камень в голове Арахнида, управляющий им.', 'A gem in Araneid\'s head that controls them.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (7185, 'Jewel of Innocence', NULL, 'Белый драгоценный камень зверя хранит его воспоминания.', 'A white jewel from the beast that brings back fond memories.', 'etc_crystal_ball_white_i00', 0);
INSERT INTO `all_items` VALUES (7186, 'Horn of Buffalo', NULL, 'Обломки рогов буйвола. Орки Кетра используют их в качестве денег.', 'Buffalo horn fragments used by Ketra Orcs as currency.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (7187, 'Nepenthes Seed', NULL, 'Семя Непентиса. Фавны Варка используют их в качестве денег.', 'Nepenthes seed used by Varka Silenos as currency.', 'etc_seed_green_i00', 0);
INSERT INTO `all_items` VALUES (7188, 'Proof of Avenger', NULL, 'Удостоверение Мстителя.', 'Certificate acquired when one becomes an avenger.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (7189, 'Eye of Darkness', NULL, 'Метка, которая доказывает принадлежность к семье Дэймона.', 'A mark that proves membership of Daimon\'s family.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (7190, 'Evil Spirit of Darkness', NULL, 'Предмет, заключающий в себе изначальную тьму Белоглазого Дэймона.', 'An object substantiating the intrinsic darkness of Daimon the White-Eyed.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (7191, 'Broken Crystal', NULL, 'Обломок кристалла, используется для призыва Дэймона.', 'A fraction of the crystal used to summon Daimon.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (7192, 'Unfinished Summon Crystal', NULL, 'Обломок незаконченной сферы, используется для призыва Дэймона.', 'A fraction of the crystal used to summon Daimon. Still in an unfinished state.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (7193, 'Summon Crystal', NULL, 'Сфера для призыва Дэймона. Испускает золотое сияние.', 'A crystal used to summon Daimon. Emits golden shine.', 'etc_crystal_ball_gold_i00', 0);
INSERT INTO `all_items` VALUES (7194, 'Essence of Daimon', NULL, 'Кристалл тьмы, заключающий в себе эссенцию Дэймона.', 'A crystal of darkness that constitutes Daimon.', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (7195, 'Boiled Eggs', NULL, 'Вкусные вареные яйца.', 'Delicious eggs boiled in spring water.', 'etc_egg_bundle_i00', 0);
INSERT INTO `all_items` VALUES (7196, 'Fee of Boiled Egg', NULL, 'Цена вареного яйца.', 'Price of the boiled egg.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (7197, 'Special Drink', NULL, 'Специальный напиток Горячих Источников.', 'Special drink at hot springs.', 'etc_winebottle_white_i00', 0);
INSERT INTO `all_items` VALUES (7198, 'Fee of Special Drink', NULL, 'Цена специального напитка.', 'Price of the special drink.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (7199, 'Leaf of Flava', NULL, 'Редкий компонент для пищи.', 'Rare ingredient for food.', 'etc_herb_green_i00', 0);
INSERT INTO `all_items` VALUES (7200, 'Buffalo Meat', NULL, 'Редкий компонент для пищи.', 'Rare ingredient for food.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (7201, 'Antelope Horn', NULL, 'Редкий компонент для пищи.', 'Rare ingredient for food.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (7202, 'Trunk of Nepenthes', NULL, 'Редкий компонент для пищи.', 'Rare ingredient for food.', 'etc_ginseng_gray_i00', 0);
INSERT INTO `all_items` VALUES (7203, 'Foot of Bandersnatchling', NULL, 'Редкий компонент для пищи.', 'Rare ingredient for food.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (7204, 'Secret Spice', NULL, 'Пикантная специя.', 'Piquant smelling spice.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (7205, 'Soy Sauce Jar', NULL, 'Соус импортирован через море из Империи Грация.', 'Sauce imported across the sea from the Gracia Empire.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (7206, 'Boiled Eggs for Delivery', NULL, 'Вкусное вареное яйцо.', 'Delicious egg boiled in spring water.', 'etc_egg_bundle_i00', 0);
INSERT INTO `all_items` VALUES (7207, 'Special Drink for Delivery', NULL, 'Особый напиток, который делают только в Горячих Источниках.', 'Special drink at hot springs.', 'etc_winebottle_white_i00', 0);
INSERT INTO `all_items` VALUES (7208, 'Hot Food Box', NULL, 'Коробка вкусной еды. Очень горячая.', 'Box of delicious food. Very hot.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7209, 'Food for Bumbalump', NULL, 'Любимая еда Ледяного Принца Бамбалампа.', 'Favorite food of Icicle Prince Bumbalump.', 'etc_food_dish_i00', 0);
INSERT INTO `all_items` VALUES (7210, 'Special Yeti Meat', NULL, 'Легендарный ингредиент, добывается убийством самых сильных Йети.', 'Legendary ingredient that can only be attained from the strongest Yeti.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (7211, 'Mark of Ketra\'s Alliance - Level 1', NULL, 'Ожерелье союзника племени Орков Кетра. Уровень 1 – благоразумие.', 'A necklace given to those who build an alliance with the Ketra Orc Tribe. Stage 1 - Prudent alliance relations.', 'etc_ketra_friendship_1_i00', 0);
INSERT INTO `all_items` VALUES (7212, 'Mark of Ketra\'s Alliance - Level 2', NULL, 'Ожерелье союзника племени Орков Кетра. Уровень 2 – зависимость.', 'A necklace given to those who build an alliance with the Ketra Orc Tribe. Stage 2 - Dependent alliance relations.', 'etc_ketra_friendship_2_i00', 0);
INSERT INTO `all_items` VALUES (7213, 'Mark of Ketra\'s Alliance - Level 3', NULL, 'Ожерелье союзника племени Орков Кетра. Уровень 3 – дружба.', 'A necklace given to those who build an alliance with the Ketra Orc Tribe. Stage 3 - Friendly alliance relations.', 'etc_ketra_friendship_3_i00', 0);
INSERT INTO `all_items` VALUES (7214, 'Mark of Ketra\'s Alliance - Level 4', NULL, 'Ожерелье союзника племени Орков Кетра. Уровень 4 – устойчивый союз.', 'A necklace given to those who build an alliance with the Ketra Orc Tribe. Stage 4 - Firm alliance relations.', 'etc_ketra_friendship_4_i00', 0);
INSERT INTO `all_items` VALUES (7215, 'Mark of Ketra\'s Alliance - Level 5', NULL, 'Ожерелье союзника племени Орков Кетра. Уровень 5 - крепкий союз.', 'A necklace given to those who build an alliance with the Ketra Orc Tribe. Stage 5 - Steadfast firm alliance relations.', 'etc_ketra_friendship_5_i00', 0);
INSERT INTO `all_items` VALUES (7216, 'Varka\'s Badge - Soldier', NULL, 'Значок, полученный после убийства Солдата Фавнов Варка.', 'A badge attained by slaying Varka Silenos Soldiers.', 'etc_barka_badge_grunt_i00', 0);
INSERT INTO `all_items` VALUES (7217, 'Varka\'s Badge - Captain', NULL, 'Значок, полученный после убийства Капитана Фавнов Варка.', 'A badge attained by slaying Varka Silenos Captains.', 'etc_barka_badge_captin_i01', 0);
INSERT INTO `all_items` VALUES (7218, 'Varka\'s Badge - General', NULL, 'Значок, полученный после убийства Генерала Фавнов Варка.', 'A badge attained by slaying Varka Silenos Generals.', 'etc_barka_badge_officer_i02', 0);
INSERT INTO `all_items` VALUES (7219, 'Totem of Valor', NULL, 'Тотем, передаваемый войнам племени Орков Кетра, чтобы засвидетельствовать их доблесть.', 'A totem presented to the warriors of the Ketra Orc tribe to attest their valor.', 'etc_royal_seal_of_lord_i00', 0);
INSERT INTO `all_items` VALUES (7220, 'Totem of Wisdom', NULL, 'Тотем, передаваемый войнам племени Орков Кетра, чтобы засвидетельствовать их мудрость.', 'A totem presented to the warriors of the Ketra Orc tribe to attest their wisdom.', 'etc_imperial_scepter_i02', 0);
INSERT INTO `all_items` VALUES (7221, 'Mark of Varka\'s Alliance - Level 1', NULL, 'Оберег союзника племени Варка. Уровень 1 – благоразумие.', 'A charm given to those who build an alliance with the Varka tribe. Stage 1 - Prudent alliance relations.', 'etc_barka_friendship_1_i00', 0);
INSERT INTO `all_items` VALUES (7222, 'Mark of Varka\'s Alliance - Level 2', NULL, 'Оберег союзника племени Варка. Уровень 2 – зависимость.', 'A charm given to those who build an alliance with the Varka tribe. Stage 2 - Dependent alliance relations.', 'etc_barka_friendship_2_i00', 0);
INSERT INTO `all_items` VALUES (7223, 'Mark of Varka\'s Alliance - Level 3', NULL, 'Оберег союзника племени Варка. Уровень 3 – дружба.', 'A charm given to those who build an alliance with the Varka tribe. Stage 3 - Friendly alliance relations.', 'etc_barka_friendship_3_i00', 0);
INSERT INTO `all_items` VALUES (7224, 'Mark of Varka\'s Alliance - Level 4', NULL, 'Оберег союзника племени Варка. Уровень 4 – устойчивый союз.', 'A charm given to those who build an alliance with the Varka tribe. Stage 4 - Firm alliance relations.', 'etc_barka_friendship_4_i00', 0);
INSERT INTO `all_items` VALUES (7225, 'Mark of Varka\'s Alliance - Level 5', NULL, 'Оберег союзника племени Варка. Уровень 5 – крепкий союз.', 'A charm given to those who build an alliance with the Varka tribe. Stage 5 - Steadfast firm alliance relations.', 'etc_barka_friendship_5_i00', 0);
INSERT INTO `all_items` VALUES (7226, 'Ketra\'s Badge - Soldier', NULL, 'Значок, полученный после убийства Солдата Орка Кетра.', 'A badge attained by slaying Ketra Orc Soldiers.', 'etc_ketra_badge_grunt_i00', 0);
INSERT INTO `all_items` VALUES (7227, 'Ketra\'s Badge - Captain', NULL, 'Значок, полученный после убийства Капитана Орка Кетра.', 'A badge attained by slaying Ketra Orc Captains.', 'etc_ketra_badge_captn_i01', 0);
INSERT INTO `all_items` VALUES (7228, 'Ketra\'s Badge - General', NULL, 'Значок, полученный после убийства Генерала Орка Кетра.', 'A badge attained by slaying Ketra Orc Generals.', 'etc_ketra_badge_officer_i02', 0);
INSERT INTO `all_items` VALUES (7229, 'Feather of Valor', NULL, 'Перо, передаваемое воинам Фавнов Варка, чтобы засвидетельствовать их доблесть.', 'A feather presented to the warriors of Varka Silenos tribe to attest their valor.', 'etc_royal_seal_of_lord_i00', 0);
INSERT INTO `all_items` VALUES (7230, 'Feather of Wisdom', NULL, 'Перо, передаваемое воинам Фавнов Варка, чтобы засвидетельствовать их мудрость.', 'A feather presented to the warriors of Varka Silenos tribe to attest their wisdom.', 'etc_imperial_scepter_i02', 0);
INSERT INTO `all_items` VALUES (7231, 'Munitions Box', NULL, 'Коробка боеприпасов, которую нужно доставить Оркам Кетра.', 'A munitions box that is on delivery to Ketra Orc tribe.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (7232, 'Munitions Box', NULL, 'Коробка боеприпасов, которую нужно доставить Фавнам Варка.', 'A munitions box that is on delivery to Varka Silenos tribe.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (7233, 'Varka\'s Mane', NULL, 'Грива Фавна Варка.', 'A mane attained from slaying Varka Silenos.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (7234, 'Molar of Ketra Orc', NULL, 'Зуб Орка Кетра.', 'A molar attained from slaying Ketra Orcs.', 'etc_molar_white_i00', 0);
INSERT INTO `all_items` VALUES (7235, 'Head of Shadith', NULL, 'Доказательство убийства Шадита.', 'A proof of slaying Shadith.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (7236, 'Head of Mos', NULL, 'Доказательство убийства Моса.', 'A proof of slaying Mos.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (7237, 'Stolen Green Totem', NULL, 'Зеленый тотем, украденный у Фавнов Варка.', 'A stolen green totem from the post of Varka Silenos.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (7238, 'Green Totem', NULL, 'Тотем используется для призыва Духа воды Ашутара.', 'A totem used to summon Water Spirit Ashutar.', 'etc_totem_green_i00', 0);
INSERT INTO `all_items` VALUES (7239, 'Ice Heart of Ashutar', NULL, 'Прозрачный осколок льда, доставшийся вам после убийства Духа Воды Ашутара.', 'A crystalline shard of ice attained from slaying Water Spirit Ashutar.', 'etc_jewel_blue_i00', 0);
INSERT INTO `all_items` VALUES (7240, 'Head of Hekaton', NULL, 'Доказательство убийства Героя Кетра Хекатона.', 'A proof of slaying the Hero of Ketra, Hekaton.', 'etc_skull_white_i00', 0);
INSERT INTO `all_items` VALUES (7241, 'Head of Tayr', NULL, 'Доказательство убийства Командира Кетра Тайра.', 'A proof of slaying the Commander of Ketra, Tayr.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (7242, 'Stolen Red Totem', NULL, 'Красный тотем, украденный у Орков Кетра.', 'A stolen red totem from the base of Ketra Orcs.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (7243, 'Red Totem', NULL, 'Тотем для призыва Духа Огня Настрона.', 'A totem used to summon Fire Spirit Nastron.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (7244, 'Fire Heart of Nastron', NULL, 'Руда Духа, доставшаяся вам после убийства Духа Огня Настрона.', 'A Spirit, ore of fire attained from slaying Fire Spirit Nastron.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (7245, 'Supply Box', NULL, 'Коробка с припасами, необходимо доставить Армии Золотого Овна.', 'A supply box that is on delivery to Golden Ram Army.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (7246, 'Golden Ram Badge - Recruit', NULL, 'Значок рекрута Армии Золотого Овна.', 'A badge that is given to recruits of Golden Ram Army.', 'etc_badge_silver_i00', 0);
INSERT INTO `all_items` VALUES (7247, 'Golden Ram Badge - Soldier', NULL, 'Значок солдата Армии Золотого Овна.', 'A badge that is given to soldiers of Golden Ram Army.', 'etc_badge_gold_i00', 0);
INSERT INTO `all_items` VALUES (7248, 'Splinter Stakato Chitin', NULL, 'Полосатый хитин Стакато Одиночки.', 'A striped chitin from Splinter Stakatos.', 'etc_scale_of_medusa_green_i00', 0);
INSERT INTO `all_items` VALUES (7249, 'Needle Stakato Chitin', NULL, 'Полосатый хитин Игольчатого Стакато.', 'A striped chitin from Needle Stakatos.', 'etc_scale_of_medusa_blue_i00', 0);
INSERT INTO `all_items` VALUES (7250, 'Talon of Stakato', NULL, 'Коготь Стакато из Болота Крика.', 'A talon from Stakatos in Swamp of Scream.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (7251, 'Golden Ram Coin', NULL, 'Монета, использовавшаяся в качестве валюты в Армии Золотого Овна.', 'A coin used by Golden Ram Army as currency.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (7252, 'Krorin\'s Journal', NULL, 'Журнал, найденный на теле Крорина.', 'A journal found in body of Krorin.', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (7253, 'Letter to Archaeologist', NULL, 'Письмо археологу, отправившемуся на исследование Гробницы Императоров.', 'A letter to an archaeologist who left to Imperial Tomb to explore.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (7254, 'Broken Relic Part', NULL, 'Часть реликвии, найденной в Гробнице Императоров. Похоже, продать не получится - сломано.', 'A fragment of relic found in Imperial Tomb. Looks like it has no value because it is broken.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (7255, 'Sealed Box', NULL, 'Запечатанная коробка, найденная в 4-м склепе. Она запечатана неизвестной силой.', 'A sealed box found in the 4th sepulcher. This box is sealed with a mysterious power.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7256, 'Goblet of Alectia', NULL, 'Кубок, полученный после убийства Тени Халиши в 4-м склепе.', 'A goblet attained by slaying Shadow of Halisha in the 4th sepulcher.', 'etc_holy_grail_i00', 0);
INSERT INTO `all_items` VALUES (7257, 'Goblet of Tishas', NULL, 'Кубок, полученный после убийства Тени Халиши в 4-м склепе.', 'A goblet attained by slaying Shadow of Halisha in the 4th sepulcher.', 'etc_holy_grail_i01', 0);
INSERT INTO `all_items` VALUES (7258, 'Goblet of Mekara', NULL, 'Кубок, полученный после убийства Тени Халиши в 4-м склепе.', 'A goblet attained by slaying Shadow of Halisha in the 4th sepulcher.', 'etc_holy_grail_i02', 0);
INSERT INTO `all_items` VALUES (7259, 'Goblet of Morigul', NULL, 'Кубок, полученный после убийства Тени Халиши в 4-м склепе.', 'A goblet attained by slaying Shadow of Halisha in the 4th sepulcher.', 'etc_holy_grail_i03', 0);
INSERT INTO `all_items` VALUES (7260, 'Chapel Key', NULL, 'Ключ, который открывает дверь часовни.', 'A key used to open the chapel door.', 'etc_key_i00', 0);
INSERT INTO `all_items` VALUES (7261, 'Used Grave Pass', NULL, 'Использованный Пропуск в четвертый склеп Гробницы Императоров. Нельзя использовать снова. Пригодится при встрече с Призраком Казначея Эльморедена.', 'A used pass necessary for entry into the 4th sepulcher at the Imperial Tomb. Cannot be used again. It may be useful when meeting the ghost of Elmoreden Chamberlain.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (7262, 'Antique Brooch', NULL, 'Драгоценная старинная брошь с величественным символом. Пригодится при встрече с Безымянным Духом.', 'A luxurious looking old brooch that displays a magnificent symbol. It may be useful when meeting the Nameless Spirit.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (7263, 'Package to Vulcan', NULL, 'Упаковка, которую необходимо отнести Вулкану в Пещеру Валакаса.', 'A package that needs to be delivered to Vulcan who\'s in Valakas\' Cave.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7264, 'Torch', NULL, 'Факел, который Вулкан попросил найти.', 'A torch that Vulcan requested to collect.', 'etc_torch_on_i00', 0);
INSERT INTO `all_items` VALUES (7265, 'Vacualite Ore', NULL, 'Руда, необходимая для создания Вакуалита.', 'A ore required to make Vacualite.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (7266, 'Vacualite', NULL, 'Готовый Вакуалит. Отнесите его Клейну.', 'Complete Vacualite. Take it to Klein.', 'etc_vacualite_noglow_white_i00', 0);
INSERT INTO `all_items` VALUES (7267, 'Vacualite Floating Stone', NULL, 'Камень, требующийся для входа в Долину Огня. Узнайте у Клейна, как им пользоваться. Раскалывается после первого использования.', 'A stone required to go to entrance of the Flame Path. It will break after use. Talk to Klein for instruction.', 'etc_vacualite_glowing_white_i00', 0);
