INSERT INTO `all_items` VALUES (7519, 'Shaved Ice', NULL, 'Любимый десерт Лили, сделанный из взбитого льда и сладких добавок.', 'Lilly\'s most favorite dessert that is made of a mixture of shaved ice and sweet flavorings.', 'etc_broken_crystal_white_i00', 0);
INSERT INTO `all_items` VALUES (7520, 'Ice Cream', NULL, 'Сладкое, мягкое, холодное мороженое.', 'Sweet, soft and cold scoop of ice cream.', 'etc_cobol_i00', 0);
INSERT INTO `all_items` VALUES (7521, 'Ice Crystal Gemstone', NULL, 'Когда на него попадает свет, он сияет всеми цветами радуги.', 'When sunlight reflects on it, it shines brightly with a rainbow of colors.', 'etc_deco_beed_i00', 0);
INSERT INTO `all_items` VALUES (7522, 'Offering', NULL, 'Пища, предназначенная Святой Агнес. Она запечатана для сохранения свежести.', 'Food that is dedicated to Saint Agnes.  It is tightly sealed to preserve its freshness.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7523, 'Offering', NULL, 'Пища, предназначенная Святой Агнес. Она запечатана для сохранения свежести.', 'Food that is dedicated to Saint Agnes.  It is tightly sealed to preserve its freshness.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7524, 'Offering', NULL, 'Пища, предназначенная Святой Агнес. Она запечатана для сохранения свежести.', 'Food that is dedicated to Saint Agnes.  It is tightly sealed to preserve its freshness.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7525, 'Offering', NULL, 'Пища, предназначенная Святой Агнес. Она запечатана для сохранения свежести.', 'Food that is dedicated to Saint Agnes.  It is tightly sealed to preserve its freshness.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7526, 'Ancient Language Dictionary', NULL, 'Словарь для расшифровки древнего языка.', 'A dictionary that is used to decipher an ancient language.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7527, 'Ancient Language Dictionary', NULL, 'Словарь для расшифровки древнего языка.', 'A dictionary that is used to decipher an ancient language.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7528, 'Spinneret', NULL, 'Анатомическая структура паука с указанием, откуда берется паутина.', 'A spider\'s anatomical structure from which spider web is produced.', 'etc_squares_silver_i00', 0);
INSERT INTO `all_items` VALUES (7529, 'Investigative Report', NULL, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Магистром Джастином.', 'A document received from Information Broker Mist. It contains the results of an investigation requested by Magister Justin.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7530, 'Investigative Report', NULL, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Магистром Альминасом.', 'A document received from Information Broker Mist. It contains the results of an investigation requested by Magister Alminas.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7531, 'Investigative Report', NULL, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Магистром Камиленом.', 'A document received from Information Broker Mist. It contains the results of an investigation requested by Magister Kamilen.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7532, 'Investigative Report', NULL, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Стражем Баердом.', 'A document received from Information Broker Bavarin. It contains the results of an investigation requested by Guard Baird.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7533, 'Investigative Report', NULL, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Верховным Жрецом Грегори.', 'A document received from Information Broker Mist. It contains the results of an investigation requested by High Priest Gregory.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (7534, 'Ice Cold Flower', NULL, 'Ледяной Кристалл, завернутый в чешую рыбы, от которого веет холодом. Созданный рукой настоящего мастера, он похож на цветок.', 'An ice crystal that is wrapped in fish scales and emits cold, icy air. Since it is beautifully created with a highly skilled hand, it looks like a flower.', 'etc_flower_i02', 0);
INSERT INTO `all_items` VALUES (7535, 'Pure Ice', NULL, 'Кусок чистейшего льда, созданного из очищенной воды. Говорят, он содержит силу богов с самого сотворения мира.', 'A chunk of purest ice that is made by freezing purified water. It is known to contain the power of the gods from the beginning of the world.', 'etc_echo_crystal_i01', 0);
INSERT INTO `all_items` VALUES (7536, 'Bitter Cold Beer', NULL, 'Пиво, которое запросил Кузнец Фейн. Одно прикосновение, и кажется, будто ваши пальцы замерзают.', 'The beer requested by Blacksmith Feynn. Just touching it makes your hands feel like they are freezing.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (7537, 'Multiple Course Meal', NULL, 'Изысканная пища, которую запросил Управляющий Арены. Говорят, ей питались дуэлисты с древних времен для повышения выносливости в бою.', 'An elaborate meal requested by the Arena Manager. It is said to be eaten by duelists in ancient times to strengthen their stamina the day before their match.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (7538, 'Dead Souls Fish Soup', NULL, 'Суп, который должен содержать все полезные вещества рыбы, из которой приготовлен. Согласно легенде, от типа рыбы зависит, будет ли съевший его больше или меньше.', 'A soup that is supposed to contain all the nutrition of the fish it is made from. According to legend, depending on the fish you use to make it, it can have the effect of increasing or decreasing one\'s lifespan.', 'etc_fish_seawater_i02', 0);
INSERT INTO `all_items` VALUES (7539, 'Bitter Cold Vodka', NULL, 'Легендарный напиток, производимый из соединения огня и льда. Холодный на губах, он становится обжигающим в желудке.', 'A legendary liquor that is made by dipping hot flames into cold, freezing ice. Although it feels cold to the lips it becomes hot in one\'s body.', 'etc_luxury_wine_c_i00', 0);
INSERT INTO `all_items` VALUES (7540, 'Silver Crystal', NULL, 'Тип кристалла, хранящего свадебную музыку.', 'The type of crystal that is needed to store wedding march music.', 'etc_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (7541, 'Red Crystal', NULL, 'Тип кристалла, хранящего музыку на день рождения.', 'The type of crystal that is needed to store birthday party music.', 'etc_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (7542, 'Vampire\'s Heart', NULL, 'Сердце, вырванное из тела Вампира. Оно все еще бьется.', 'The heart that is ripped out of the body of a vampire.  It is still beating and pumping out blood.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (7543, 'Zombie\'s Brain', NULL, 'Кусок мозга нежити из Леса Неупокоенных. Может содержать воспоминания о моменте смерти.', 'A piece of brain collected from an undead monster in the Forest of the Dead. It may contain the memory of the moment of its death.', 'etc_bodypart_brain_i00', 0);
INSERT INTO `all_items` VALUES (7544, 'Rib Bone of a Black Magus', NULL, 'Кость, оставшаяся на месте смерти Черного Мага. Возможно она использовалось для изменения внешнего вида Мага.', 'The remaining bone that is left in the place where a necromancer died and disappeared. Perhaps it was used to transfix the shape of the necromancer.', 'etc_rib_black_i00', 0);
INSERT INTO `all_items` VALUES (7545, 'Zombie\'s Liver', NULL, 'Печень, продолжающая гнить и исторгать ужасающий запах. Известна как средоточие магических свойств нежити.', 'A liver that is rotting and emitting a strong stench.  It is known to be a source of magical power of undead.', 'etc_bodypart_liver_i00', 0);
INSERT INTO `all_items` VALUES (7546, 'Top Quality Meat', NULL, 'Кусок мяса высокого качества, полученный с туши зверя нужного возраста. С каждого зверя можно получить только один такой кусок.', 'A piece of top quality meat that is obtained by slaughtering a wild beast of proper age.  Only one piece of this high quality meat can be obtained from one beast.', 'etc_meat_of_monstereye_i00', 0);
INSERT INTO `all_items` VALUES (7547, 'Young Wild Beast Meat', NULL, 'Кусок мяса, полученный с туши молодого зверя. Несмотря на приятный запах, его вкус недостаточно хорош.', 'A piece of meat obtained by slaughtering a wild beast that is too young. Although it may have a pleasant aroma, it doesn\'t give good flavor when eating it.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (7548, 'Map Piece', NULL, 'Обрывок карты Монстроглаза', 'A piece of a map that was once possessed by Monster Eyes.', 'etc_map_piece_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7549, 'Yellow Map', NULL, 'Карта с обозначением следов монстров. Отнесите ее Капитану Наемников Софье.', 'A map that contains a plot of the beasts. Take it to Mercenary Captain Sophya.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7550, 'Map Piece', NULL, 'Обрывок карты, полученный с призраков в Землях Казненных.', 'A piece of map obtained from the ghostly apparitions that haunt the Execution Groundss.', 'etc_map_piece_ivory_i00', 0);
INSERT INTO `all_items` VALUES (7551, 'Ivory Colored Map', NULL, 'Карта со странной информацией. Кстати, как-то недавно Торговец Галладучи жаловался, что до него не дошла одна из карт…', 'A map that contains strange information. By the way, sometime ago, Trader Galladucci complained that one of the maps he was supposed to receive didn\'t arrive...?', 'etc_map_ivory_i00', 0);
INSERT INTO `all_items` VALUES (7552, 'Broken Gemstone Fragment', NULL, 'Кусок драгоценного камня, полученный с Ящера Мэль.', 'A fragment of gemstone that can be obtained by hunting Maille Lizardmen.', 'etc_broken_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (7553, 'Gold Colored Gemstone', NULL, 'Сфера золотого цвета, которую ищет Верховный Жрец Дрикус.', 'A gold colored orb. High Priest Drikus is supposed to be looking for it.', 'etc_gem_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7554, 'Scroll of Escape: Talking Island Village', NULL, 'Магический свиток, с помощью которого можно переместиться на Говорящий Остров.', 'A magical scroll that relocates you to Talking Island.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7555, 'Scroll of Escape: Elven Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Эльфийскую Деревню.', 'A magical scroll that relocates you to Elven Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7556, 'Scroll of Escape: Dark Elven Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Темных Эльфов.', 'A magical scroll that relocates you to Dark Elf Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7557, 'Scroll of Escape: Orc Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Орков.', 'A magical scroll that relocates you to Orc Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7558, 'Scroll of Escape: Dwarven Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Гномов.', 'A magical scroll that relocates you to Dwarven Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7559, 'Scroll of Escape: Town of Giran', NULL, 'Магический свиток, с помощью которого можно переместиться в Гиран.', 'A magical scroll that relocates you to Giran Castle Town.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7560, 'Monster Only (Fishing Rod)', NULL, NULL, NULL, 'weapon_monster_i00', 0);
INSERT INTO `all_items` VALUES (7561, 'Fishing Manual', NULL, 'Руководство по технике рыбалки. Двойное нажатие позволит его прочитать.', 'An instructional book of fishing techniques. You can double-click it to read it.', 'etc_spellbook_blue_i00', 0);
INSERT INTO `all_items` VALUES (7562, 'Dimensional Diamond', NULL, 'Кристалл, наполненный магической силой. Необходим для телепортации. Вы можете обменять их у любого Хранителя Портала на Свитки Телепорта в различные города.', 'A crystal that is filled with magical power. It is needed when casting Instant Move magic. If you collect this item and take them to a gatekeeper, you can trade them for various types of Scroll of Escape.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (7563, 'Galladucci\'s Order (Document)', NULL, 'Документ с заказом Галадуччи. Отнесите его Торговцу Гентлеру в Лавку Магии.', 'A document describing Galladucci\'s orders. Take it to Trader Gentler at his magic shop.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (7564, 'Galladucci\'s Order (Document)', NULL, 'Документ с заказом Галадуччи. Отнесите его Ювелиру Сандре.', 'A document describing Galladucci\'s orders. Take it to Jeweler Sandra at her shop.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (7565, 'Galladucci\'s Order (Document)', NULL, 'Документ с заказом Галадуччи. Отнесите его Жрецу Дастину.', 'A document describing Galladucci\'s orders. Take it to Priest Dustin at his shop.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (7566, 'Purified Magic Necklace', NULL, 'Предмет, полученный от Жреца Дастина, который ищет Галадуччи.', 'It\'s the item given by Priest Dustin. It seems to be the item Trader Galladucci has been looking for.', 'etc_evil_necklace_i00', 0);
INSERT INTO `all_items` VALUES (7567, 'Gemstone Powder', NULL, 'Предмет, полученный от Ювелира Сандры, который ищет Галадуччи.', 'The item given by Trader Sandra. This seems to be the item Trader Galladucci has been looking for.', 'etc_powder_orange_i00', 0);
INSERT INTO `all_items` VALUES (7568, 'Magic Sword Hilt', NULL, 'Предмет, полученный от Торговца Гентлера, который ищет Галадуччи.', 'An item given by Trader Gentler. This seems to be the item Trader Galladucci has been looking for.', 'etc_hilt_i00', 0);
INSERT INTO `all_items` VALUES (7569, 'Four-leaf Golden Clover Coin', NULL, 'Золотая монета с гравировкой в форме четырехлистного клевера.', 'A gold coin that is engraved with a four-leaf clover design.', 'etc_gold_knight_i00', 0);
INSERT INTO `all_items` VALUES (7570, 'Mark of Traveler', NULL, 'Сертификат, доказывающий Торговцу Галадуччи принадлежность к Путешественникам.', 'A certificate to prove to Trader Galladucci the identity of the traveler.', 'etc_crest_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7571, 'Baulro\'s Letter', NULL, 'Письмо Сэру Виндавуду от Магистра Баулро.', 'The letter sent by Magister Baulro to Archon Sir Windawood.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (7572, 'Ariel\'s Recommendation', NULL, 'Рекомендация, написанная Торговцем Ариэль. Отдайте ее Иерарху Астериосу.', 'A letter of recommendation Trader Ariel wrote for you to be sent to Hierarch Asterios.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (7573, 'Roselyn\'s Note', NULL, 'Записка, которую Розалин написала в гневе. Отнесите ее Магистру Харн.', 'A note Roselyn wrote while being angry and wrathful. You should deliver it to Magister Harne.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (7574, 'Very Expensive Necklace', NULL, 'Подарок Жрецу Земли Геральду от Главного Кузнеца Рида. На вид достаточно дорогой.', 'A gift from Head Blacksmith Reed for Priest of the Earth Gerald. It looks very expensive.', 'accessary_necklace_of_devotion_i00', 0);
INSERT INTO `all_items` VALUES (7575, 'Draconic Bow', NULL, 'Дает возможность получить одно из следующих особых свойств: Экономия, Фокусировка, Крит. Замедление.', 'It can bestow one of the following functions: Cheap Shot, Focus, or Critical Slow.', 'weapon_draconic_bow_i00', 5);
INSERT INTO `all_items` VALUES (7576, 'Draconic Bow', 'Cheap Shot', '<Свойство Кристалла Души> При обычной атаке дает 26% шанс уменьшить расход MP до 1. Наносит дополнительный урон в PvP.', 'Cheap Shot	a,<Soul Crystal Enhancement>n During a general attack, 1 MP will be consumed 26% of the time. Enhances damage to a target during PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (7577, 'Draconic Bow', 'Focus', '<Свойство Кристалла Души> Увеличение шанса Крит. Атк. на 88. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement>n Increases Critical Attack by 88. Enhances damage to a target during PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (7578, 'Draconic Bow', 'Critical Slow', '<Свойство Кристалла Души> Шанс наложения Замедления при крит. атаке. Наносит дополнительный урон в PvP.', 'Critical Slow	a,<Soul Crystal Enhancement>n During a critical attack, you Slow your target temporarily. Enhances damage to a target during PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (7579, 'Draconic Bow Shaft', NULL, 'Основной материал для создания Лука Дракона. Может быть продан в лавке.', 'Main ingredient essentially required for a Dwarf to make a Draconic Bow. Can also be sold at ordinary shops.', 'etc_branch_gold_i00', 6);
INSERT INTO `all_items` VALUES (7580, 'Recipe: Draconic Bow (60%)', NULL, 'Только для Гномов. Рецепт Лука Дракона. Требуется умение Создать Предмет 9 уровня. 60% шанс успеха.', 'For Dwarves only. The recipe for a Draconic Bow. Requires Create Item - Skill Level 9. The success rate is 60%.', 'etc_recipe_black_i00', 5);
INSERT INTO `all_items` VALUES (7581, 'Recipe: Draconic Bow (100%)', NULL, 'Только для Гномов. Рецепт Лука Дракона. Требуется умение Создать Предмет 9 уровня. 100% шанс успеха.', 'For Dwarves only. The recipe for a Draconic Bow. Requires Create Item - Skill Level 9. The success rate is 100%.', 'etc_recipe_black_i00', 5);
INSERT INTO `all_items` VALUES (7582, 'Baby Spice', NULL, 'Еда для детенышей питомцев (кугуар, буйвол или кукабарра). При индикаторе голода 55% или ниже потребляется автоматически.', 'When the food gauge of a baby buffalo, a baby cougar or a baby kookaburra drops to 55% or below, this feed will be consumed automatically.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7583, 'Pet Exchange Ticket: Buffalo', NULL, NULL, NULL, 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (7584, 'Pet Exchange Ticket: Cougar', NULL, NULL, NULL, 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (7585, 'Pet Exchange Ticket: Kookaburra', NULL, NULL, NULL, 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (7586, 'Sweet Fluid', NULL, 'Жидкость со сладким ароматом. Используется для создания Приманки.', 'A type of fluid with a sweet fragrance. It is used as an ingredient to make a fishing shot.', 'etc_potion_gold_i00', 0);
INSERT INTO `all_items` VALUES (7587, 'Legend of Seventeen', NULL, 'История о семнадцати героях, сражавшихся против Антараса, Великого Дракона.', 'A record of the seventeen heroes who fought against Antharas, the Land Dragon.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (7588, 'Faded Poetry Book', NULL, 'Поэтическая книга, написанная неизвестным Эльфийским Бардом несколько сотен лет назад.', 'A poetry book written by an unknown Elven bard several hundred years ago.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (7589, 'Echo Crystal - Forgotten Song', NULL, 'Кристалл, содержащий песню о Забытых Героях.', 'An echo crystal that contains the song of Forgotten Heroes.', 'etc_echo_crystal_i02', 0);
INSERT INTO `all_items` VALUES (7590, 'Strand of Golden Hair', NULL, 'Клок волос, упавших с головы блондинки.', 'A strand of hair that seems to have fallen from a blonde-haired lady.', 'etc_braided_hemp_i00', 0);
INSERT INTO `all_items` VALUES (7591, 'Ring of Goddess: Waterbinder', NULL, 'Кольцо с нежно-голубым камнем. Издает звук текущего ручейка.', 'Ring with a subtle blue gem. When picked up, it makes a sound like a flowing brook.', 'accessary_elven_ring_i00', 0);
INSERT INTO `all_items` VALUES (7592, 'Necklace of Goddess: EverGreen', NULL, 'Ожерелье с чистым зеленым кристаллом в качестве медальона. Когда вы держите его в руках, оно издает приятных запах травы, политой весенним дождем.', 'A necklace with a clear and bright bluish green crystal as a medallion. The moment when you hold it in your hand, you smell the scent of grass,  wet with spring rain.', 'accessary_elemental_necklace_i00', 0);
INSERT INTO `all_items` VALUES (7593, 'Staff of Goddess: Rain Song', NULL, 'Деревянный посох с навершием в форме светло-синей сферы. Вы чувствуете дыхание океанского бриза, будто брызги попадают вам на лицо.', 'A wooden staff that is embedded with a light blue orb at the top of it. It gives you a feeling of an ocean breeze filled with moisture blowing gently in your face.', 'weapon_sprites_staff_i00', 0);
INSERT INTO `all_items` VALUES (7594, 'Relic Box', NULL, 'Коробка с тремя реликвиями Богини.', 'Box containing 3 relics of Goddess0', 'etc_treasure_box_i01', 0);
INSERT INTO `all_items` VALUES (7595, 'Orb of Binding', NULL, 'Серебряная сфера, источающая магическую силу.', 'A silver colored orb that emanates a strong feeling of magical power.', 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (7596, 'Sorcery Ingredient', NULL, 'Волшебный ингредиент, который использует Ведьма Калис.', 'A sorcery ingredient that is used by Witch  Kalis.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (7597, 'Malruk Succubus Claw', NULL, 'Острый коготь, полученный у Суккуба Малрука.', 'Thin and sharp claw obtained from Malruk Succubus0', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (7598, 'Crimson Moss', NULL, 'Красный мох, который можно найти в Болоте Криков.', 'Crimson Moss obtained from Swamp of Screams0', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (7599, 'Rahorakti\'s Miraculous Medicine', NULL, 'Лекарство, выписанное Девушке Гному Кассандре Великим Провидцем Рахоракти.', 'Remedy prescribed by Grand Seer Rahorakti for Dwarf Girl Kassandra0', 'etc_potion_scarlet_i00', 0);
INSERT INTO `all_items` VALUES (7600, 'Worn Tarot Card - Wealth', NULL, 'Старая потертая карта таро, полученная от Леди Озера. Означает богатство.', 'An old and worn out tarot card given by the Lady of the Lake.  This card symbolizes wealth.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (7601, 'Worn Tarot Card - Power', NULL, 'Старая потертая карта таро, полученная от Леди Озера. Означает власть.', 'An old and worn out tarot card given by the Lady of the Lake.  This card symbolizes power.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (7602, 'Worn Tarot Card - Love', NULL, 'Старая потертая карта таро, полученная от Леди Озера. Означает любовь.', 'An old and worn out tarot card given by the Lady of the Lake.  This card symbolizes love.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (7603, 'Worn Tarot Card - Knowledge', NULL, 'Старая потертая карта таро, полученная от Леди Озера. Означает знание.', 'An old and worn out tarot card given by the Lady of the Lake.  This card symbolizes knowledge.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (7604, 'Summoner Keats\' Letter', NULL, 'Письмо, написанное Призывателем Китом, превращенным в лягушку. Почерк у него был ужасен даже в человеческом обличии.', 'A clumsily written letter written by Summoner Keats who was turned into a frog.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (7605, 'Miracle Potion of Transferred Life', NULL, 'Чудотворное зелье Эльфов, созданное Жрецом Керенасом.', 'An Elven miracle cure mixed by Priest Cerenas.', 'etc_bless_of_eva_i00', 0);
INSERT INTO `all_items` VALUES (7606, 'Kamilen\'s Antidote', NULL, 'Лекарство, созданное Магистром Камилен для лечения Призывателя Ноктисс.', 'A medicine made by Magister Kamilen to cure Summoner Noctisse.', 'etc_dragons_blood_i04', 0);
INSERT INTO `all_items` VALUES (7607, 'Coolant of the Repaired Wilma #3', NULL, 'Охлаждающая система отремонтированной машины \"Вилма #3\".', 'The cooling system refrigerant of repaired time machine \"Wilma 3\".', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (7608, 'Sealed Envelope', NULL, 'Запечатанный конверт от Торговца Информацией Баварина.', 'A sealed envelope given by Information Broker Bavarin.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (7609, 'Proof of Catching a Fish', NULL, 'Сертификат рыбака. Соберите их и принесите члену Гильдии Рыбаков, чтобы изучить умение, расширяющее доступное место.', 'A fishing certificate. If you collect it and take it to a member of the Fishermen\'s Guild, you can learn a skill that is related to expanding a slot.', 'etc_ticket_i00', 0);
INSERT INTO `all_items` VALUES (7610, 'Wind Fishing Lure', NULL, 'Наживка, сделанная Ланоско. Содержит силу Ветра, но использовать ее непросто. Подходит только опытным рыболовам.', 'A lure that was given out by Lanosco.  It contains the hidden power of wind. It is not easy to use this lure. Only those who are highly skilled in fishing should use it.', 'etc_broken_crystal_silver_i00', 16);
INSERT INTO `all_items` VALUES (7611, 'Icy Air Fishing Lure', NULL, 'Наживка, сделанная О\'Фулле. Содержит силу Воды, но использовать ее непросто. Подходит только опытным рыболовам.', 'A lure that was given out by O\'Fulle.  It contains the hidden power of icy air. It is not easy to use this lure. Only those who are highly skilled in fishing should use it.', 'etc_broken_crystal_blue_i00', 16);
INSERT INTO `all_items` VALUES (7612, 'Earth Fishing Lure', NULL, 'Наживка, сделанная Вилли. Содержит силу Земли, но использовать ее непросто. Подходит только опытным рыболовам.', 'A lure that was given out by Willie.  It contains the hidden power of earth. It is not easy to use this lure. Only those who are highly skilled in fishing should use it.', 'etc_broken_crystal_gold_i00', 16);
INSERT INTO `all_items` VALUES (7613, 'Flaming Fishing Lure', NULL, 'Наживка, сделанная Линеусом. Содержит силу Огня, но использовать ее непросто. Подходит только опытным рыболовам.', 'A lure that was given out by Linnaeus.  It contains the hidden power of flames. It is not easy to use this lure. Only those who are highly skilled in fishing should use it.', 'etc_broken_crystal_red_i00', 16);
INSERT INTO `all_items` VALUES (7614, 'Chest Caught by Wind Fishing Lure', NULL, 'Сундук, выловленный при помощи силы Ветра.', 'A chest that was brought up out of the bait of wind by using the wind fishing lure.', 'etc_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (7615, 'Chest Caught by Icy Air Fishing Lure', NULL, 'Сундук, выловленный при помощи силы Воды.', 'A chest that was brought up out of the bait of icy air by using the wind fishing lure.', 'etc_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (7616, 'Chest Caught by Earth Fishing Lure', NULL, 'Сундук, выловленный при помощи силы Земли.', 'A chest that was brought up out of the bait of earth by using the wind fishing lure.', 'etc_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (7617, 'Chest Caught by using a Flaming Fishing Lure', NULL, 'Сундук, выловленный при помощи силы Огня.', 'A chest that was brought up out of the bait of fire water by using the wind fishing lure.', 'etc_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (7618, 'Scroll of Escape: Ketra Orc Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Орков Кетра. Нельзя продать в магазин.', 'A magic scroll that transports its bearer to Ketra Orc Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7619, 'Scroll of Escape: Varka Silenos Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Фавнов Варка. Нельзя продать в магазин.', 'A magic scroll that transports its bearer to Varka Silenos Village.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (7620, 'Trash', NULL, 'Кровь со святой силой.', 'Saint\'s blood that has power of holiness.', 'etc_dragons_blood_i01', 0);
INSERT INTO `all_items` VALUES (7621, 'Essence of Wind', NULL, 'Суть ветра, полученная у Поющего Ветра. Отнесите ее Ланоско.', 'Essence of wind extracted from Singing Wind.  It is an item requested by Lanosco.', 'etc_echo_crystal_i01', 0);
INSERT INTO `all_items` VALUES (7622, 'Lost Bait Ingredient', NULL, 'Потерянная наживка, найденная у Пленной Души. Верните ее О\'Фулле.', 'The lost bait that was recovered from a Fettered Soul.  O\'Fulle asked you to bring it back to him.', 'etc_codran_i00', 0);
INSERT INTO `all_items` VALUES (7623, 'Eye of Tarlk Basilisk', NULL, 'Глаз Василиска Тарлк. Отнесите его Вилли.', 'An eye harvested from a Tarlk Basilisk. Willie asked you to bring it back to him.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (7624, 'Crimson Drake Heart', NULL, 'Сердце Синего Дрейка, объятое огнем. Отнесите его Линеусу.', 'Heart of a Crimson Drake surrounded by flames.  Linnaeus asked you to bring it back to him.', 'etc_inf_ore_high_i00', 0);
INSERT INTO `all_items` VALUES (7625, 'Strange Golem Blueprint', NULL, 'План голема, отличающийся от всех остальных. Похоже, его дизайнером был Шалинг.', 'A golem blueprint with an unusual design that is different from any other golem blueprint. It seems to be designed by Shaling.', 'etc_ssq_scroll_i00', 0);
INSERT INTO `all_items` VALUES (7626, 'Kiki\'s Letter', NULL, 'Запечатанное письмо. На лицевой стороне имя адресата - Кики.', 'A completely sealed letter.  On the envelope,  Kiki\'s name is written as its recipient.', 'etc_permit_card_i00', 0);
INSERT INTO `all_items` VALUES (7627, 'Small Glass Box', NULL, 'Красивая коробка из стекла с гравировкой двух имен – Анабель и Лесли.', 'A beautiful box made of glass. It is engraved with the names of Anabel and Liesel.', 'etc_silver_mold_i00', 0);
INSERT INTO `all_items` VALUES (7628, 'Rukal\'s Musical Score', NULL, 'Ноты к красивой музыке. Имя автора - Рукал.', 'A musical score of  beautiful music. Its author is written down as Composer Rukal.', 'etc_ssq_i00', 0);
INSERT INTO `all_items` VALUES (7629, 'Looted Goods - White Cargo box', NULL, 'Белая Коробка из вагончика торговца. Похоже, в ней есть ценные товары. Двойное нажатие позволит посмотреть содержимое.', 'White Cargo Box looted from a trader\'s wagon. Seems to have valuable goods. Double-click to see the contents.', 'etc_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (7630, 'Looted Goods - Blue Cargo box', NULL, 'Синяя Коробка из вагончика торговца. Похоже, в ней есть ценные товары. Двойное нажатие позволит посмотреть содержимое.', 'Blue Cargo Box looted from a trader\'s wagon. Seems to have valuable goods. Double-click to see the contents.', 'etc_treasure_box_i01', 0);
