INSERT INTO `all_items` VALUES (7633, 'Looted Goods - Purple Cargo Box', NULL, 'Фиолетовая Коробка для Документов из вагончика торговца. Похоже, в ней есть ценные товары. Двойное нажатие позволит посмотреть содержимое.', 'Violet Document Box looted from a trader\'s wagon. Seems to have valuable goods. Double-click to see the contents.', 'etc_royal_seal_of_lord_i03', 0);
INSERT INTO `all_items` VALUES (7634, 'Looted Goods - Brown Pouch', NULL, 'Мешочек из вагончика торговца. Похоже, в ней есть ценные товары. Двойное нажатие позволит посмотреть содержимое.', 'Pouch looted from a trader\'s wagon. Seems to have valuable goods. Double-click to see the contents.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (7635, 'Looted Goods - Gray Pouch', NULL, 'Мешочек из вагончика торговца. Похоже, в ней есть ценные товары. Двойное нажатие позволит посмотреть содержимое.', 'Pouch looted from a trader\'s wagon. Seems to have valuable goods. Double-click to see the contents.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (7636, 'Booty - Yellow Pouch', NULL, 'Предмет из болот. Грязный желтый мешочек с множеством дыр. Двойное нажатие позволит посмотреть содержимое.', 'Item discovered in the marsh. Dirty yellow pouch ripped here and there. Double-click to see the contents.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (7637, 'Booty - Brown Pouch', NULL, 'Предмет из болот. Грязный коричневый мешочек с множеством дыр. Двойное нажатие позволит посмотреть содержимое.', 'Item discovered in the marsh. Dirty brown pouch ripped here and there. Double-click to see the contents.', 'etc_pouch_brown_i00', 0);
