INSERT INTO `all_items` VALUES (7677, 'Virgil\'s Letter', NULL, 'Письмо Виргила, богатого Гнома из Руны. В письме просьба о помощи.', 'Letter sent by Virgil, a rich Dwarf in the Rune Township. It asks for help.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (7678, 'Caradine\'s Letter', NULL, 'Письмо от Посланницы Озера, Карадин. Отправляйтесь в Годдард после получения 65 уровня на дополнительном классе.', 'Letter sent by Messenger of the Lake, Caradine. Says to go to the Town of Goddard when you reach Sub Class Level 65.', 'etc_letter_envelope_i00', 0);
