INSERT INTO `all_items` VALUES (7701, 'Stick of Faith', 'Mana Up', '<Свойство Кристалла Души> Увеличение Макс. MP на 30%.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%.', 'weapon_stick_of_faith_i01', 2);
INSERT INTO `all_items` VALUES (7702, 'Stick of Faith', 'Magic Hold', '<Свойство Кристалла Души>10% шанс наложения Корня Дриады при использовании вредоносного умения на цель.', 'Magic Hold	a,<Soul Crystal Enhancement>n Casts Dryad Root magic against the target with a 10% chance of success when using bad magic. Effect 1.', 'weapon_stick_of_faith_i01', 2);
INSERT INTO `all_items` VALUES (7703, 'Stick of Faith', 'Magic Shield', '<Свойство Кристалла Души>50% шанс наложения Ментального Щита при использовании благотворного умения на цель.', 'Magic Shield	a,<Soul Crystal Enhancement>n Casts Mental Shield magic upon the target with a 50% chance of success when using good magic. Effect 2.', 'weapon_stick_of_faith_i01', 2);
INSERT INTO `all_items` VALUES (7704, 'Stick of Eternity', 'Empower', '<Свойство Кристалла Души> Увеличение Маг. Атк. на 24.', 'Empower	a,<Soul Crystal Enhancement>n Increases M. Atk. by 24.', 'weapon_stick_of_eternity_i01', 2);
INSERT INTO `all_items` VALUES (7705, 'Stick of Eternity', 'Rsk. Evasion', '<Свойство Кристалла Души> Увеличение Уклонения на 7 при HP менее 60%.', 'Rsk., Evasion	a,<Soul Crystal Enhancement>n Increases Evasion by 7 when HP becomes 60% or lower.', 'weapon_stick_of_eternity_i01', 2);
INSERT INTO `all_items` VALUES (7706, 'Stick of Eternity', 'Blessed Body', '<Свойство Кристалла Души>20% шанс наложения Благословения Тела при использовании благотворного умения на цель.', 'Blessed Body	a,<Soul Crystal Enhancement>n Casts Blessed Body upon the target with a 20% chance of success when using good magic. Effect 3.', 'weapon_stick_of_eternity_i01', 2);
INSERT INTO `all_items` VALUES (7707, 'Nirvana Axe', 'M. Atk.', '<Свойство Кристалла Души> При использовании магии затраты MP увеличены на 15% и Маг. Атк. увеличена на 99.', 'Magic Power	a,<Soul Crystal Enhancement>n When using magic, the amount of MP consumption increases by 15% and M. Atk. also increases by 99.', 'weapon_nirvana_axe_i01', 2);
INSERT INTO `all_items` VALUES (7708, 'Nirvana Axe', 'Magic Poison', '<Свойство Кристалла Души>7% шанс отравить цель при использовании вредоносного умения на цель.', 'Magic Poison	a,<Soul Crystal Enhancement>n Casts Curse Poison against the target with a 7% chance of success when using bad magic. Effect 7.', 'weapon_nirvana_axe_i01', 2);
INSERT INTO `all_items` VALUES (7709, 'Nirvana Axe', 'Magic Weakness', '<Свойство Кристалла Души>7% шанс ослабит цель при использовании вредоносного умения на цель.', 'Magic Weakness	a,<Soul Crystal Enhancement>n Casts Curse Weakness against the target with a 7% chance of success when using bad magic. Effect 3.', 'weapon_nirvana_axe_i01', 2);
