INSERT INTO `all_items` VALUES (7714, 'Mace of Underworld', 'Magic Silence', '<Свойство Кристалла Души>10% шанс наложения Тишины при использовании вредоносного умения на цель.', 'Magic Silence	a,<Soul Crystal Enhancement>n When using bad magic against a target, casts Silence upon target with a 10% chance of success. Effect 1.', 'weapon_mace_of_underworld_i01', 2);
