INSERT INTO `all_items` VALUES (7719, 'Poleaxe', 'Critical Stun', '<Свойство Кристалла Души> При крит. атаке есть возможность Оглушить с шансом 25%.', 'Critical Stun	a,<Soul Crystal Enhancement>n During a critical attack, produces a stun effect at the rate of about 25%.', 'weapon_poleaxe_i01', 2);
