INSERT INTO `all_items` VALUES (7807, 'Green Colored Lure - For Beginners', NULL, 'Наживка для новичков. С ее помощью игрок может быстро научиться рыбачить. Подходит для быстрой рыбы.', 'A lure used by beginners. Since only the fish intended for beginners take the bait, a player can easily learn how to fish. This bait is preferred by fast moving fish.', 'etc_bait_i00', 16);
INSERT INTO `all_items` VALUES (7808, 'Purple Colored Lure - For Beginners', NULL, 'Наживка для новичков. С ее помощью игрок может быстро научиться рыбачить. Подходит для толстой рыбы.', 'A lure used by beginners. Since only the fish intended for beginners take the bait, a player can easily learn how to fish. This bait is preferred by fat fish.', 'etc_bait_i01', 16);
INSERT INTO `all_items` VALUES (7809, 'Yellow Colored Lure - For Beginners', NULL, 'Наживка для новичков. С ее помощью игрок может быстро научиться рыбачить. Подходит для уродливой рыбы.', 'A lure used by beginners. Since only the fish intended for beginners take the bait, a player can easily learn how to fish. This bait is preferred by ugly fish.', 'etc_bait_i02', 16);
INSERT INTO `all_items` VALUES (7810, 'Soulfire Dirk', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%.', 'weapon_dagger_of_magicflame_i01', 2);
INSERT INTO `all_items` VALUES (7811, 'Soulfire Dirk', 'Magic Hold', '<Свойство Кристалла Души>Дает 10% шанс колдовства Корня Дриады при использовании вредоносного умения на цель.', 'Magic Hold	a,<Soul Crystal Enhancement>n Casts Dryad Root magic against the target with a 10% chance of success when using bad magic. Effect 1.', 'weapon_dagger_of_magicflame_i01', 2);
INSERT INTO `all_items` VALUES (7812, 'Soulfire Dirk', 'Magic Silence', '<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель.', 'Magic Silence	a,<Soul Crystal Enhancement>n When using bad magic against a target, casts Silence upon target with a 10% chance of success. Effect 1.', 'weapon_dagger_of_magicflame_i01', 2);
INSERT INTO `all_items` VALUES (7813, 'Hell Knife', 'Magic Regeneration', '<Свойство Кристалла Души>Дает 30% шанс колдовства Регенерации при использовании благотворного умения на цель.', 'Magic Regeneration	a,<Soul Crystal Enhancement>n Casts HP Regeneration magic upon the target with a 30% chance of success when using good magic. Effect 3.', 'weapon_hell_knife_i01', 3);
INSERT INTO `all_items` VALUES (7814, 'Hell Knife', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель.', 'Mental Shield	a,<Soul Crystal Enhancement>n Casts Mental Shield magic upon the target with a 50% chance of success when using good magic. Effect 4.', 'weapon_hell_knife_i01', 3);
INSERT INTO `all_items` VALUES (7815, 'Hell Knife', 'Magic Weakness', '<Свойство Кристалла Души>Дает 7% шанс колдовства Проклятия Слабости при использовании вредоносного умения на цель.', 'Magic Weakness	a,<Soul Crystal Enhancement>n Casts Curse Weakness against the target with a 7% chance of success when using bad magic. Effect 3.', 'weapon_hell_knife_i01', 3);
INSERT INTO `all_items` VALUES (7816, 'Apprentice Adventurer\'s Staff', NULL, 'Посох Путешественника Новичка. Этот предмет нельзя обменять, выбросить, кристаллизовать и модифицировать. Если ваш счет PK больше 0, то вы не сможете его использовать.', 'Apprentice Adventurer\'s Staff. This item cannot be exchanged, dropped, crystallized, or enchanted.  If one\'s PK count is 1 or more, it cannot be used.', 'weapon_apprentices_staff_i00', 0);
