INSERT INTO `all_items` VALUES (7928, 'Mercenary Posting Ticket (Teleporter1)', NULL, 'Позволяет телепортироваться во внутренний двор замка или к стражам. Размещается в Шутгарте внутри замка.', 'Placed in Schuttgart, at the Teleporter or inside the castle, this ticket allows teleportation to the inner castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7929, 'Mercenary Posting Ticket (Teleporter2)', NULL, 'Позволяет телепортироваться во внешний двор замка или к стражам. Размещается в Шутгарте внутри замка.', 'Placed in Schuttgart, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7930, 'Mercenary Posting Ticket (Teleporter3)', NULL, 'Позволяет телепортироваться во внешний или внутренний двор замка. Размещается в Шутгарте внутри замка.', 'Placed in Schuttgart, at the Teleporter or inside the castle, this ticket allows teleportation to the inner or outer castle.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7931, 'Greater Mercenary Posting Ticket (Sword/Stationary)', NULL, 'Шутгарт/Мечники/Неподвижно. Используется, чтобы вызвать наемников. Недоступно, если Печатью Раздора владеют Мятежники Заката.', 'Schuttgart/Sword/Stationary. The Seal of Strife cannot be used to place a mercenary when in the possession of the Revolutionaries of Dusk.', 'mticket_sword_fix_i00', 8);
