INSERT INTO `all_items` VALUES (7983, 'Mercenary Posting Ticket (Teleporter1)', NULL, 'Позволяет телепортироваться к восточным воротам внутренней части замка, в западную части внешнего замка, на площадь или к стражам. Размещается в Руне внутри замка.', 'Placed in Rune, at the Teleporter or inside the castle, this ticket allows teleportation to the East Gate of the inner castle, the western section of the outer castle, the Plaza or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7984, 'Mercenary Posting Ticket (Teleporter2)', NULL, 'Позволяет телепортироваться во внешний двор замка, к восточным воротам внутренней части замка, на площадь или к стражам. Размещается в Руне внутри замка.', 'Placed in Rune, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the East Gate of the inner castle, the Plaza or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7985, 'Mercenary Posting Ticket (Teleporter3)', NULL, 'Позволяет телепортироваться во внешний двор замка, к западным воротам внешней части замка, на площадь или к стражам. Размещается в Руне внутри замка.', 'Placed in Rune, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the West Gate of the outer castle, the Plaza or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7986, 'Mercenary Posting Ticket (Teleporter4)', NULL, 'Позволяет телепортироваться во внешний двор, в западную часть внешнего замка, к восточным воротам внешнего двора или к стражам. Размещается в Руне внутри замка.', 'Placed in Rune, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the western section of the outer castle, the East Gate of the outer castle or the guardian\'s location.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7987, 'Mercenary Posting Ticket (Teleporter5)', NULL, 'Позволяет телепортироваться во внешний двор, в западную часть внешнего замка, к восточным воротам внешнего двора или на площадь. Размещается в Руне внутри замка.', 'Placed in Rune, at the Teleporter or inside the castle, this ticket allows teleportation to the outer castle, the western section of the outer castle, the East Gate of the outer castle or to the Plaza.', 'mticket_teleporter_fix_i00', 8);
INSERT INTO `all_items` VALUES (7988, 'Greater Mercenary Posting Ticket (Sword/Stationary)', NULL, 'Руна/Мечники/Неподвижно. Используется, чтобы вызвать наемников. Недоступно, если Печатью Раздора владеют Мятежники Заката.', 'Rune/Sword/Stationary. The Seal of Strife cannot be used to place a mercenary when in the possession of the Revolutionaries of Dusk.', 'mticket_sword_fix_i00', 8);
