INSERT INTO `all_items` VALUES (8030, 'Hot Spring Nectar', NULL, 'Используется во время сражения за Холл Клана Горячих Источников. Этот предмет может быть использован на Йети Горячих Источников. Не может быть обменян или выброшен.', 'Used during the Rainbow Springs Clan Hall Battle. This item may be used on the Hot Springs Yeti. It cannot be exchanged or dropped.', 'etc_hot_spring_nectar_i00', 0);
INSERT INTO `all_items` VALUES (8031, 'Hot Spring Mineral Water', NULL, 'Используется во время сражения за Холл Клана Горячих Источников. Этот предмет может быть использован на Йети Горячих Источников. Не может быть обменян или выброшен.', 'Used during the Rainbow Springs Clan Hall Battle. This item may be used on the Hot Springs Yeti. It cannot be exchanged or dropped.', 'etc_hot_spring_mineral_i00', 0);
INSERT INTO `all_items` VALUES (8032, 'Hot Spring Water', NULL, 'Используется во время сражения за Холл Клана Горячих Источников. Этот предмет может быть использован на Йети Горячих Источников. Не может быть обменян или выброшен.', 'Used during the Rainbow Springs Clan Hall Battle. This item may be used on the Hot Springs Yeti. It cannot be exchanged or dropped.', 'etc_hot_spring_fountain_i00', 0);
INSERT INTO `all_items` VALUES (8033, 'Hot Spring Sulfur', NULL, 'Используется во время сражения за Холл Клана Горячих Источников. Этот предмет может быть использован на Йети Горячих Источников. Не может быть обменян или выброшен.', 'Used during the Rainbow Springs Clan Hall Battle. This item may be used on the Hot Springs Yeti. It cannot be exchanged or dropped.', 'etc_hot_spring_sulfur_i00', 0);
INSERT INTO `all_items` VALUES (8034, 'Rainbow Springs Clan Hall War Decree', NULL, 'Это свидетельство позволяет принять участие в битве за Холл Клана Горячего Источника. Это награда за рыбалку в Годдарде.', 'This ticket allows entry to the Rainbow Springs Clan Hall Battle.  It is a reward for fishing in Goddard.', 'etc_hs_agit_war_joining_certificate_i00', 0);
INSERT INTO `all_items` VALUES (8035, 'Hot Spring Letter A', NULL, 'Используется в комбинации с такими же письмами, может давать награды во время сражения за Холл Клана Горячих Источников. Не может быть обменян или выброшен.', 'Combining these texts may grant rewards during the Rainbow Springs Clan Hall Battle. It cannot be exchanged or dropped.', 'etc_alphabet_a_i00', 0);
