INSERT INTO `all_items` VALUES (8062, 'Blood of Maille Lizardman', NULL, 'Кровь убитого Ящера Мэль.', 'Blood obtained by killing Maille Lizardmen.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (8063, 'Leg of King Araneid', NULL, 'Лапа побежденного Короля Арахнидов.', 'The legs obtained by defeating King Araneid.', 'etc_sting_b_i00', 0);
INSERT INTO `all_items` VALUES (8064, 'Visitor\'s Mark', NULL, 'Можно входить в Языческий Храм. Не потеряйте это!', 'Permits entry to the Pagan Temple. Don\'t lose it!', 'etc_red_rose_i00', 0);
INSERT INTO `all_items` VALUES (8065, 'Faded Visitor\'s Mark', NULL, 'Это метка для входа в Языческий Храм.', 'This faded mark permits entry to the Pagan Temple.', 'etc_white_rose_i00', 0);
INSERT INTO `all_items` VALUES (8066, 'Necromancer\'s Heart', NULL, 'Получите Сердце Некроманта из Аниматора Костей, Костяного Убийцы или Аниматора Черепов.', 'Obtain this necromantic heart by slaying Bone Animators, Bone Slayers or Skull Animators.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (8067, 'Pagan\'s Mark', NULL, 'Можно войти в часовню Языческого Храма.', 'Permits entry and access to the chapel of the Pagan Temple.', 'etc_totem_necklace_red_i00', 0);
INSERT INTO `all_items` VALUES (8068, 'Pagan Totem', NULL, 'Тотем, полученный убийством Язычника.', 'The totem obtained by defeating the Pagans.', 'etc_totem_necklace_green_i00', 0);
INSERT INTO `all_items` VALUES (8069, 'Monk\'s Scripture', NULL, 'Писание убитого монаха Монастыря Безмолвия.', 'The scripture obtained by defeating the monks within the Monastery of Silence.', 'etc_magic_book_white_i00', 0);
INSERT INTO `all_items` VALUES (8070, 'Water Bottle', NULL, 'Бутыль Гремори. Наберите воды из Святого Грааля в Сверкающей Комнате и возьмите ее с собой.', 'The bottle from Gremory. Pour the water into the Holy Grail in the Splendor Room and take it with you.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (8071, 'Bottle of water from the Holy Grail', NULL, 'Бутыль, наполненная водой из Святого Грааля в Сверкающей Комнате. Отдайте ее Гремори.', 'The bottle containing the water from the Holy Grail in the Splendor Room. Take it to Gremory.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (8072, 'Antelope Skin', NULL, 'Необычная шкура, нужная для создания магического свитка.', 'The exceptional hide needed to create the magical scroll.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (8073, 'Frintezza\'s Magic Force Field Removal Scroll', NULL, 'Свиток, позволяющий преодолеть силовое поле Фринтезы. Найти его вы сможете возле Гробницы Императоров, и он позволит вам войти на запретную территорию.', 'The scroll that permits passage though Frintezza\'s Magic Force Field. Meet his guide near the Imperial Tomb entrance and he will let you enter the forbidden area.', 'etc_scroll_gray_i00', 0);
INSERT INTO `all_items` VALUES (8074, 'Watching Eyes', NULL, 'Глаз Наблюдателя, который тревожил фермеров Флорана. Отдайте его Алексу во Флоране.', 'This \"Wandering Eye\" has been harassing the farmers of Floran. Take it to Almankel in Floran Village.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (8075, 'Roughly Hewn Rock Golem Shard', NULL, 'Кусок Голема из Грубо Отесанного Камня. Отлайте его Алексу в деревне Флоран.', 'This is a fragment from a Roughly Hewn Rock Golem. Take it to Almankel in Floran Village.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (8076, 'Delu Lizardman\'s Scale', NULL, 'Чешуя Ящера Делу, который наводил ужас на фермеров Флорана. Отдайте ее Алексу в Деревне Флоран.', 'This is a scale of the Delu Lizardman that has been harassing the farmers of Floran. Take it to Almankel in Floran Village.', 'etc_scale_of_medusa_green_i00', 0);
INSERT INTO `all_items` VALUES (8077, 'Silver Ice Crystal', NULL, 'Кристалл, полученный из монстра.', 'A crystal obtained from a monster. When processed, it becomes the Black Ice Crystal.', 'etc_broken_crystal_silver_i00', 0);
INSERT INTO `all_items` VALUES (8078, 'Black Ice Crystal', NULL, 'При наведении на цель персонаж становится неистовым.', 'When stuck into a target, the character becomes violent.', 'etc_gem_black_i00', 0);
INSERT INTO `all_items` VALUES (8079, 'Misa\'s Letter', NULL, 'Тайное письмо от Мисы для Раффорти. Не сломайте печать!', 'A secret letter from Misa to Rafforty. Don\'t break the seal!', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (8080, 'Rafforty\'s Letter', NULL, 'Тайное письмо от Раффорти для Мисы.', 'A secret letter from Rafforty to Misa.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (8081, 'Piece of Tablet', NULL, 'Обломок неизвестной таблички.', 'An unknown tablet fragment.', 'etc_broken_tablet_fragment_i00', 0);
INSERT INTO `all_items` VALUES (8082, 'Report Piece', NULL, 'Часть доклада от каменной статуи.', 'A fragment of the report from the stone statue.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (8083, 'Scout\'s Memo', NULL, 'Записка разведчика, искавшего гнездо.', 'A scribbled note written by a scout searching the nest.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (8084, 'Crystal of Purity', NULL, 'Белый кристалл добыт из дикого зверя с чистым сердцем.', 'This white crystal was expelled by a wild beast whose heart was pure.', 'etc_crystal_ball_white_i00', 0);
INSERT INTO `all_items` VALUES (8085, 'Fang of Stakato', NULL, 'Клыки убитых Стакато.', 'Fangs gained from killing Stakatos.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (8086, 'Box Containing the Fire of Holy Spirit', NULL, 'Коробка с огнем святого духа.', 'Box containing the Fire of the Holy Spirit0', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (8087, 'Cursed Doll', NULL, 'Волшебная кукла повелевает злыми тварями Орков Рагна.', 'An enchanted doll that has been said to control the evil creatures of the Ragna Orcs.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (8088, 'Orc Grave Goods', NULL, 'Останки, украденные грабителями могил.', 'Remains stolen by graverobbers.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (8089, 'Cursed Grave Goods', NULL, 'Предметы разгневанных духов.', 'Items made by angry spirits to use physical force.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (8090, 'Electric Wave Detector', NULL, 'Стержень, излучающий сильные электрические волны. Сейчас не работает.', 'This rod lights up in the presence of strong electric waves. It is presently unlit.', 'weapon_the_staff_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (8091, 'Electric Wave Detector', NULL, 'Стержень, излучающий сильные электрические волны. Сейчас работает.', 'This rod lights up in the presence of strong electric waves. It is presently lit.', 'weapon_the_staff_of_hero_i01', 0);
INSERT INTO `all_items` VALUES (8092, 'Telescope Golem\'s Corpse', NULL, 'Металл, добытый из останков Голема Разведчика. Возможно, он что-то таит в себе.', 'Metal obtained from hunting the Scout Golem. It may be concealing something.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (8093, 'Golem\'s Dispatcher', NULL, 'Устройство, добытое из останков Телескопического Голема.', 'Dispatcher obtained from hunting the Telescope Golem.', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (8094, 'Storage Medium', NULL, 'Накопитель, добытый из останков Голема. Пустой.', 'The storage medium taken from the Golem. It is empty.', 'etc_calculator_i00', 0);
INSERT INTO `all_items` VALUES (8095, 'Storage Medium', NULL, 'Накопитель, добытый из останков Голема. Содержит какую-то информацию.', 'The storage medium taken from the Golem. It contains information.', 'etc_calculator_i00', 0);
INSERT INTO `all_items` VALUES (8096, 'Ginzu Golem\'s Black Box', NULL, 'Черный ящик, добытый из останков Голема Гинзу.', 'The analysis device obtained from the Ginzu Golem.', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (8097, 'X-688', NULL, 'Интересный свиток, найденный в книжном шкафу Доктора Хаоса.', 'A curious scroll found on Dr. Chaos\'s bookshelf.', 'etc_map_ivory_i00', 0);
INSERT INTO `all_items` VALUES (8098, 'Supplying Goods for Railroad Worker', NULL, 'Материалы Снабжения Путевого Обходчика', 'Supplies sent by a Dwarven Elder to a Railroad Worker.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (8099, 'Thief Guild\'s Mark', NULL, 'Зубы животных, которые носили воры Разграбленных Равнин.', 'An animal\'s tooth worn by the thieves of the Plunderous Plains.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (8100, 'Destroyed Golem Shards', NULL, 'Обломок Голема.', 'Shards obtained from hunting the Golem.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (8101, 'Dwarf\'s Favor', NULL, 'Письмо для Юмиты, написанное Главным Кузнецом Шутгарта.', 'Letter of introduction  to Yumita, written by Head Blacksmith Newyear of Schuttgart Village.', 'etc_letter_white_i00', 0);
