INSERT INTO `all_items` VALUES (8104, 'Pa\'agrian Sword', 'Critical Drain', '<Свойство Кристалла Души> Поглощает 9 HP цели при использовании a Крит. Атк.', 'Critical Drain	a,<Soul Crystal Enhancement>n Absorbs 9 HP from a target when one makes a critical attack.', 'weapon_sword_of_paagrio_i01', 2);
