INSERT INTO `all_items` VALUES (8141, 'Spell Breaker', 'Acumen', '<Свойство Кристалла Души> Скор. Маг. +15%.', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd by 15%.', 'weapon_spell_breaker_i01', 3);
INSERT INTO `all_items` VALUES (8142, 'Spell Breaker', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель.', 'Magic Mental Shield	a,<Soul Crystal Enhancement>n Casts Mental Shield against the target with 50% chance of success when using good magic. Effect 4.', 'weapon_spell_breaker_i01', 3);
INSERT INTO `all_items` VALUES (8143, 'Spell Breaker', 'Magic Hold', '<Свойство Кристалла Души>Дает 10% шанс колдовства Корня Дриады при использовании вредоносного умения на цель.', 'Magic Hold	a,<Soul Crystal Enhancement>n Casts Dryad Root against the target with 10% chance of success when using bad magic. Effect 1.', 'weapon_spell_breaker_i01', 3);
INSERT INTO `all_items` VALUES (8144, 'Kaim Vanul\'s Bones', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%.', 'weapon_bone_of_kaim_vanul_i01', 3);
INSERT INTO `all_items` VALUES (8145, 'Kaim Vanul\'s Bones', 'Magic Silence', '<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель.', 'Magic Silence	a,<Soul Crystal Enhancement>n Casts Silence against the target with 10% chance of success when using bad magic. Effect 1.', 'weapon_bone_of_kaim_vanul_i01', 3);
INSERT INTO `all_items` VALUES (8146, 'Kaim Vanul\'s Bones', 'Conversion', '<Свойство Кристалла Души> Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%.', 'Conversion	a,<Soul Crystal Enhancement>n Increases the maximum MP by 60% and decreases the maximum HP by 40%.', 'weapon_bone_of_kaim_vanul_i01', 3);
INSERT INTO `all_items` VALUES (8147, 'Spiritual Eye', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Increases damage inflicted on one\'s opponent during PvP.', 'weapon_eye_of_soul_i01', 4);
INSERT INTO `all_items` VALUES (8148, 'Spiritual Eye', 'Magic Poison', '<Свойство Кристалла Души>Дает 8% шанс колдовства Проклятия Отравления при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Poison	a,<Soul Crystal Enhancement>n Casts Curse Poison against the target with an X% chance of success when using bad magic.', 'weapon_eye_of_soul_i01', 4);
INSERT INTO `all_items` VALUES (8149, 'Spiritual Eye', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd. by 15%.  Increases damage inflicted on one\'s opponent during PvP.', 'weapon_eye_of_soul_i01', 4);
INSERT INTO `all_items` VALUES (8150, 'Flaming Dragon Skull', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Acumen	a,<Soul Crystal Enhancement>n Increases Casting Spd. by 15%.  Increases damage inflicted on one\'s opponent during PvP.', 'weapon_dragon_flame_head_i01', 4);
INSERT INTO `all_items` VALUES (8151, 'Flaming Dragon Skull', 'M. Atk.', '<Свойство Кристалла Души> Увеличивает расход MP на 15%, Маг. Атк. на 167 и урон, причиняемый в PvP.', 'Magic Power	a,<Soul Crystal Enhancement>n Increases MP Consumption by 15%, M. Atk. by 167 and damage inflicted during PvP.', 'weapon_dragon_flame_head_i01', 4);
INSERT INTO `all_items` VALUES (8152, 'Flaming Dragon Skull', 'Magic Silence', '<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Silence	a,<Soul Crystal Enhancement>n Casts Silence against the target with 10% chance of success when using bad magic. Effect 1. Increases damage inflicted during PvP.', 'weapon_dragon_flame_head_i01', 4);
INSERT INTO `all_items` VALUES (8153, 'Adventurer\'s Guide Book', NULL, 'Необходимая вещь для любого путешественника.', 'An essential read for adventurers.', 'etc_spell_books_blue_i00', 0);
