INSERT INTO `all_items` VALUES (8177, 'Raid Challenger\'s Circlet', NULL, 'Диадема Участника Рейда для новичков.', 'Beginner\'s Raid Challenger Circlet.', 'accessory_raid_challenger_i00', 0);
INSERT INTO `all_items` VALUES (8178, 'Raid Adventurer\'s Circlet', NULL, 'Диадема Авантюриста Рейда', 'Intermediate Raid Adventurer Circlet0', 'accessory_raid_explorer_i00', 0);
INSERT INTO `all_items` VALUES (8179, 'Raid Master\'s Circlet', NULL, 'Диадема Мастера Рейда', 'Advanced Raid Master Circlet.', 'accessory_raid_master_i00', 0);
INSERT INTO `all_items` VALUES (8180, 'Circlet of Ice Fairy Sirra', NULL, 'Диадема, добытая убийством Ледяной Феи Сирры.', 'Circlet obtained by attacking the Ice Fairy Sirra.', 'accessory_ice_queen_i00', 0);
INSERT INTO `all_items` VALUES (8181, 'Academy Circlet', NULL, 'Диадема, которая выдается выпускникам Академии. При смерти персонажа 40~75 уровней снижает штраф на опыт на 50%. Можно повторно купить у кузнеца Глудио Пинтера.', 'Circlet awarded to graduates of the Academy.', 'accessory_academy_i00', 0);
INSERT INTO `all_items` VALUES (8182, 'Circlet of Rune', NULL, 'Розовая Диадема. Носится Лордом Замка Руна и членами клана, но не союзниками. Позволяет использовать Умения Резиденции. Нельзя обменять/выбросить.', 'Rose Circlet. Can be worn by the lord of Rune Castle and clan members but not by allies. Allows use of Residential Skills when equipped.', 'accessory_pledge_cap1_i01', 0);
INSERT INTO `all_items` VALUES (8183, 'Circlet of Schuttgart', NULL, 'Диадема Молота и Факела. Носится Лордом Замка Шутгарта и членами клана, но не союзниками. Позволяет использовать Умения Резиденции. Нельзя обменять/выбросить.', 'Hammer and Torch Circlet. Can be worn by the lord of Schuttgart Castle and clan members but not by allies. Allows use of Residential Skills when equipped.', 'accessory_pledge_cap1_i07', 0);
INSERT INTO `all_items` VALUES (8184, 'Party Hat', NULL, 'Забавный головной аксессуар. Требует две ячейки головных уборов.', 'A funky hair accessory which uses 2 hair accessory slots.', 'accessory_party_hat_i00', 0);
INSERT INTO `all_items` VALUES (8185, 'Feathered Hat', NULL, 'Широкополая шляпа с пером. Требует две ячейки головных уборов.', 'A wide-brimmed hat with a feather. Uses 2 accessory slots.', 'accessory_archer_hat_i00', 0);
INSERT INTO `all_items` VALUES (8186, 'Artisan\'s Goggles', NULL, 'Большие очки для защиты глаз. Требует две ячейки головных уборов.', 'Eye protection that uses 2 accessory slots.', 'accessory_dwarf_goggle_i00', 0);
INSERT INTO `all_items` VALUES (8187, 'Demon Horns', NULL, 'Головной аксессуар для ивента Helloween 2006.', 'A hair accessory for the 2006 Halloween Event.', 'accessory_hair_cornu_i00', 0);
INSERT INTO `all_items` VALUES (8188, 'Little Angel Wings', NULL, 'Головной аксессуар в виде маленького белого крыла.', 'A wing-shaped hair accessory.', 'accessory_hair_ring_i00', 0);
INSERT INTO `all_items` VALUES (8189, 'Fairy Antennae', NULL, 'Миловидный головной аксессуар в виде антенок со звездочками.', 'Cute antennae hair accessory with stars.', 'accessory_hair_feeler_i00', 0);
INSERT INTO `all_items` VALUES (8190, 'Demonic Sword Zariche', NULL, 'Смертоносный магический меч, сделанный Дьяволом Бремноном собственноручно. Всегда жаждет крови.', 'A deadly and powerful magical sword that was once wielded by the devil Bremnon himself. It is always thirsty for blood.', 'weapon_unique_zariche_i00', 0);
INSERT INTO `all_items` VALUES (8191, 'Necklace of Frintezza', NULL, 'Увеличивает MP на 42. Увеличивает сопротивление к усыплению/параличу/шоку на 15%. Увеличивает шанс усыпления/паралича/шокирования цели на 15%. Увеличивает сопротивление к отравлению/кровотечению на 25%. Увеличивает шанс отравить/пустить кровь на 25%. Уменьшает время отката умений. Обладает эффектом отражения части урона. Увеличивает сопротивление тьме.', 'Increases resistance to Sleep by 30%, to Poison by 50%, to Bleed by 50%, to Paralysis by 30%, to Shock by 30%. Decreases Re-use Delay. Also produces the effects of Damange Shield, and enhanced ability to defend against dark attacks.', 'accessory_necklace_of_frintessa_i00', 0);
INSERT INTO `all_items` VALUES (8192, 'Soul Breaking Arrow', NULL, 'Двойной щелчок по стреле временно прерывает музыкальную тему Фринтезы. Нельзя выбросить. Исчезает при входе в Пещеру Последнего Императора.', 'Double-click the arrow to temporarily stop Frintezza\'s musical performance. This gets deleted when one enters the Tomb of the Last Emperor.', 'etc_destory_soul_arrow_i00', 0);
INSERT INTO `all_items` VALUES (8193, 'Fisherman\'s Potion - Green', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать зеленую рыбу (уровень 1-3). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a green fish (level 1~3 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_green_i00', 0);
INSERT INTO `all_items` VALUES (8194, 'Fisherman\'s Potion - Jade', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать нефритовую рыбу (уровень 4-6). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a jade fish (level 4~6 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_jade_i00', 0);
INSERT INTO `all_items` VALUES (8195, 'Fisherman\'s Potion - Blue', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать синюю рыбу (уровень 7-9). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a blue fish (level 7~9 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_blue_i00', 0);
INSERT INTO `all_items` VALUES (8196, 'Fisherman\'s Potion - Yellow', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать желтую рыбу (уровень 10-12). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a yellow fish (level 10~12 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (8197, 'Fisherman\'s Potion - Orange', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать оранжевую рыбу (уровень 13-15). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch an orange fish (level 13~15 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_orange_i00', 0);
INSERT INTO `all_items` VALUES (8198, 'Fisherman\'s Potion - Purple', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать фиолетовую рыбу (уровень 16-18). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a purple fish (level 16~18 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_violet_i00', 0);
INSERT INTO `all_items` VALUES (8199, 'Fisherman\'s Potion - Red', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать красную рыбу (уровень 19-21). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a red fish (level 19~21 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_red_i00', 0);
INSERT INTO `all_items` VALUES (8200, 'Fisherman\'s Potion - White', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать белую рыбу (уровень 22-24). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a white fish (level 22~24 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_white_i00', 0);
INSERT INTO `all_items` VALUES (8201, 'Fisherman\'s Potion - Black', NULL, 'Понижая уровень умения рыболовства это зелье позволяет поймать черную рыбу (уровень 25-27). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'By lowering one\'s fishing skill level, this potion allows one to catch a green fish (level 25~27 fish).  If one uses a potion that is designed for a higher fishing skill level than one\'s own, the potion will have no effect.', 'etc_oblivion_black_i00', 0);
INSERT INTO `all_items` VALUES (8202, 'Fisherman\'s Potion', NULL, 'Восстанавливает уровень мастерства рыбалки после того, как было употреблено понижающее его зелье.', 'Restores a player\'s fishing mastery level, which was lowered by the Fisherman\'s Potion, back to the previous level.', 'etc_oblivion_black_i00', 0);
