INSERT INTO `all_items` VALUES (8223, 'Seed: Twin Codran', NULL, 'Семя Двойного Кодрана. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 53-63 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Twin Codran. For best results, a level 53-63 character must plant it on a level 53-63 monster.', 'etc_codran_seed_i00', 10);
INSERT INTO `all_items` VALUES (8224, 'Seed: Great Codran', NULL, 'Семя Большого Кодрана. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 56-66 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Great Codran. For best results, a level 56-66 character must plant it on a level 56-66 monster.', 'etc_codran_seed_i00', 10);
INSERT INTO `all_items` VALUES (8225, 'Seed: Desert Codran', NULL, 'Семя Пустынного Кодрана. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 59-69 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Desert Codran. For best results, a level 59-69 character must plant it on a level 59-69 monster.', 'etc_codran_seed_i00', 10);
