INSERT INTO `all_items` VALUES (8272, 'Seed: Alternative Twin Codran', NULL, 'Семя Нового Двойного Кодрана. Для получения плода вживите его в монстра в районе Шутгарта. Наилучшего результата можно достичь, если персонаж и монстр 53-63 уровней.', 'Plant this seed onto a monster in the Schuttgart area and it will bear the fruit of the Alternative Twin Codran. For best results, a level 53-63 character must plant it on a level 53-63 monster.', 'etc_codran_seed_i00', 11);
INSERT INTO `all_items` VALUES (8273, 'Anteroom Key', NULL, 'Открывает дверь в комнату ожидания Языческого Храма.', 'Opens the door to one of the Anterooms within the Pagan Temple.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (8274, 'Chapel Key', NULL, 'Открывает дверь в часовню Языческого Храма.', 'Opens the door to the chapel in the Pagan Temple.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (8275, 'Key of Darkness', NULL, 'Ключ, открывающий Дверь Тьмы у алтаря Языческого Храма.', 'The key that opens the Door of Darkness located at the altar within the Pagan Temple.', 'etc_old_key_i02', 0);
INSERT INTO `all_items` VALUES (8276, 'Sekina\'s Scale', NULL, 'Чешуя, добытая убийством Секины, Ведьмы Малрука.', 'The scale obtained by defeating Sekina, Malruk\'s Witch.', 'etc_scale_of_medusa_blue_i00', 0);
INSERT INTO `all_items` VALUES (8277, 'Themis\' Scale', NULL, 'Эта чешуя добывается убийством Королевы Палибати Темиса.', 'Obtain this scale by defeating Palibati Queen Themis.', 'etc_scale_of_medusa_red_i00', 0);
INSERT INTO `all_items` VALUES (8278, 'Vermilion Shard', NULL, 'Добывается убийством Вермилиона, Кровавого Дерева.', 'Debris obtained by defeating Vermilion, the Blood Tree.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (8279, 'Nucleus of Hekaton Prime', NULL, 'Ядро, полученное при убийстве Хекатона Прайма.', 'Nucleus obtained by defeating Hekaton Prime0', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (8280, 'Tiphon Shard', NULL, 'Камень, полученный при убийстве Повелителя Горгулий Тифона.', 'Debris obtained by defeating Tiphon, Gargoyle Lord.', 'etc_gargoyle_claw_i00', 0);
INSERT INTO `all_items` VALUES (8281, 'Glaki\'s Necleus', NULL, 'Ядро, добытое убийством Глаки, последнего младшего гиганта.', 'Nucleus obtained by defeating Glaki, the last lesser Giant.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (8282, 'Rahha\'s Fang', NULL, 'Клыки Раххи.', 'Fangs obtained by defeating Rahha.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (8283, 'Giant Poison Bee\'s Sting', NULL, 'Доказательство смерти монстра во имя безопасности Рудника Возрождения. Отдайте Хранителю Склада Норману в Деревне Глудин.', 'Evidence that a monster has been destroyed for the safety of the Strip Mine. Take it to Warehouse Keeper Norman in Gludin Village.', 'etc_sting_a_i00', 0);
INSERT INTO `all_items` VALUES (8284, 'Cloudy Gem', NULL, 'Доказательство смерти монстра во имя безопасности Рудника Возрождения. Отдайте Хранителю Склада Норману в Деревне Глудин.', 'Evidence that a monster has been destroyed for the safety of the Strip Mine. Take it to Warehouse Keeper Norman in Gludin Village.', 'etc_oriharukon_ore_i00', 0);
INSERT INTO `all_items` VALUES (8285, 'Talon of Young Araneid', NULL, 'Доказательство смерти монстра во имя безопасности Рудника Возрождения. Отдайте Хранителю Склада Норману в Деревне Глудин.', 'Evidence that a monster has been destroyed for the safety of the Strip Mine. Take it to Warehouse Keeper Norman in Gludin Village.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8286, 'Fairy Breath', NULL, 'Последнее дыхание безумной Феи Ветра. Отдайте его Галатее, Призывателю в Деревне Глудин, чтобы выучить силу духа баланса.', 'The last breath of the crazy Wind Fairy. Take it to Galatea, Gludin Village\'s Summoner, for the study of balancing spirit power.', 'etc_dragons_blood_i01', 0);
INSERT INTO `all_items` VALUES (8287, 'Starstone', NULL, 'Звездный Камень, выпавший из коробки.', 'The Starstone that slipped out of the box.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (8288, 'Yumi\'s Letter', NULL, 'Письмо от Юми, адресованное Невьяру, Главному Кузнецу.', 'The letter from Yumi to Newyear, the Head Blacksmith.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (8289, 'Starstone', NULL, 'Звездный Камень, о котором просила Юми.', 'The Starstone that Yumi asked you to find and bring back.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (8290, 'Flower of Pavel', NULL, 'Странный цветок от Атланты.', 'The strange flower from Atlanta.', 'etc_flower_i02', 0);
INSERT INTO `all_items` VALUES (8291, 'Heart of Atlanta', NULL, 'Камень, найденный там, где последний раз видели Атланту. Нужно отдать его Венди.', 'The stone found where Atlanta was last seen. It should be given to Wendy.', 'etc_inf_ore_medium_i00', 0);
INSERT INTO `all_items` VALUES (8292, 'Wendy\'s Necklace', NULL, 'Ожерелье, последний дар Венди. Он не обладает магической силой, но имеет большую историческую ценность.', 'The necklace that became Wendy\'s last gift. It\'s not powerful, but it has great historical significance.', 'accessary_necklace_of_devotion_i00', 0);
INSERT INTO `all_items` VALUES (8293, 'Trainer License', NULL, 'Метка, необходимая для участия в Войне за Холл Клана.', 'Mark needed to participate in a Clan Hall War.', 'etc_paper_red_i00', 0);
