INSERT INTO `all_items` VALUES (8484, 'Prize-Winning Fishing Lure', NULL, 'Наживка отличного качества, повышающая шанс поймать большую рыбу.', 'Use this lure to increase your chances of catching a large, prize-winning fish.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8485, 'Prize-Winning Night Fishing Lure', NULL, 'Наживка отличного качества, повышающая шанс поймать большую рыбу во время ночной рыбалки. Нельзя использовать днем.', 'Use this lure at night to increase your chances of catching a large, prize-winning fish. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8486, 'Prize-Winning Novice Fishing Lure', NULL, 'Наживка отличного качества, повышающая шанс новичка поймать большую рыбу. Можно использовать только для ловли рыбы для новичков.', 'Novice fishermen should use this lure to increase the chances of catching a large, prize-winning fish. Only fish intended for novice fishermen will take this bait, however.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8487, 'Recipe: Destroyer Hammer (60%)', NULL, 'Технология изготовления Молота Разрушителя используется только Гномами и требует умения Создание предметов 7 уровня. Шанс успеха 60%.', 'This formula for manufacturing a Destroyer Hammer can only be used by Dwarves and Requires Create Item - Skill Level 7. The success rate is 60%.', 'etc_recipe_violet_i00', 5);
INSERT INTO `all_items` VALUES (8488, 'Engraved Hammer', NULL, 'Молот с рисунком на рукоятке.', 'A hammer with a pattern engraved on its handle.', 'weapon_big_hammer_i00', 0);
INSERT INTO `all_items` VALUES (8489, 'Daimon\'s Eyes', NULL, 'Глаза Белоглазого Дэймона.', 'Eyes obtained by killing Daimon the White-Eyed.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (8490, 'Hestia\'s Fairy Stone', NULL, 'Камень Феи, взятый с тела убитой Гестии, Стражника Горячих Источников.', 'Fairy Stone obtained by defeating Hestia, the Guardian Deity of the Hot Springs.', 'etc_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (8491, 'Nucleus of Lesser Golem', NULL, 'Ядро, добытое убийством Младшего Голема.', 'Nucleus obtained by defeating the Lesser Golem.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (8492, 'Falston\'s Fang', NULL, 'Клык Фальстона, Агента Демона.', 'Fangs obtained by killing Falston, the Demon\'s Agent.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (8493, 'Shaid\'s Talon', NULL, 'Коготь Королевы Шипастых Стакато Шиид.', 'Talon obtained by defeating Spike Stakato Queen Shaid.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8494, 'Nucleus of Flamestone Giant', NULL, 'Ядро, добытое убийством Гиганта из Горящего Камня.', 'Nucleus obtained by defeating Flamestone Giant0', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (8495, 'Book of Grey Star', NULL, 'Книга дорожного работника Оби, украденная ворами. В ней описана история летающего поезда.', 'The book that Obi the railroad worker said was stolen by thieves. It tells the story of a train that flys.', 'etc_memopad_i00', 0);
INSERT INTO `all_items` VALUES (8496, 'Gludio Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Глудио. Уровень умения рыболовства: 7-9.', 'A luminous lure that is used to catch Gludio\'s Big Fish.  It is used in Gludio Territory by fishermen whose Fishing Mastery Level is between 7 and 9.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8497, 'Dion\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Диона. Уровень умения рыболовства: 10-12.', 'This luminous fishing lure can be used to catch Dion\'s Big Fish. It is used in Dion Territory by fishermen whose Fishing Mastery Level is 10-12.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8498, 'Giran\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Гирана. Уровень умения рыболовства: 16-18.', 'This luminous fishing lure can be used to catch Giran\'s Big Fish. It is used in Giran Territory by fishermen whose Fishing Mastery Level is 16-18.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8499, 'Oren\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Орена. Уровень умения рыболовства: 7-9.', 'This luminous fishing lure can be used to catch Oren\'s Big Fish. It is used in Oren Territory by fishermen whose Fishing Mastery Level is 7-9.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8500, 'Aden\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Адена. Уровень умения рыболовства: 19-21.', 'This luminous fishing lure can be used to catch Aden\'s Big Fish. It is used in Aden Territory by fishermen whose Fishing Mastery Level is 19-21.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8501, 'Innadril\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Иннадрила. Уровень умения рыболовства: 13-15.', 'This luminous fishing lure can be used to catch Innadril\'s Big Fish. It is used in Innadril Territory by fishermen whose Fishing Mastery Level is 13-15.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8502, 'Goddard\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Годдарда. Уровень умения рыболовства: 25-27.', 'This luminous fishing lure can be used to catch Goddard\'s Big Fish. It is used in Goddard Territory by fishermen whose Fishing Mastery Level is 25-27.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8503, 'Rune\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Руны. Уровень умения рыболовства: 22-24.', 'This luminous fishing lure can be used to catch Rune\'s Big Fish. It is used in Rune Territory by fishermen whose Fishing Mastery Level is 22-24.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8504, 'Schuttgart\'s Luminous Lure', NULL, 'Светящаяся наживка для ловли Большой Рыбы. Используется на территории Шутгарта. Уровень умения рыболовства: 7-9.', 'This luminous fishing lure can be used to catch Schuttgart\'s Big Fish. It is used in Schuttgart Territory by fishermen whose Fishing Mastery Level is 7-9.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8505, 'Green Luminous Lure - Low Grade', NULL, 'Наживка для ловли быстрой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch fast-moving low grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8506, 'Green Luminous Lure', NULL, 'Наживка для ловли быстрой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch fast-moving fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It lure cannot be used during the day.', 'etc_bait_i00', 16);
INSERT INTO `all_items` VALUES (8507, 'Green Colored Lure (High Grade)', NULL, 'Наживка для ловли быстрой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch fast-moving high grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8508, 'Purple Luminous Lure - Low Grade', NULL, 'Наживка для ловли толстой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch broad low grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8509, 'Purple Luminous Lure', NULL, 'Наживка для ловли толстой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch broad fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_bait_i01', 16);
INSERT INTO `all_items` VALUES (8510, 'Purple Luminous Lure (High Grade)', NULL, 'Наживка для ловли толстой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch broad high grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8511, 'Yellow Luminous Lure - Low Grade', NULL, 'Наживка для ловли уродливой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch ugly low grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8512, 'Yellow Luminous Lure', NULL, 'Наживка для ловли уродливой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch ugly fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_bait_i02', 16);
INSERT INTO `all_items` VALUES (8513, 'Yellow Luminous Lure (High Grade)', NULL, 'Наживка для ловли уродливой рыбы ночью. Чем выше ранг, тем быстрее рыба клюнет на нее. Днем использовать нельзя.', 'This fishing lure can be used to catch ugly high grade fish at night. The higher the lure\'s grade, the faster the fish will take the bait. It cannot be used during the day.', 'etc_gludio_fish_lure_i00', 16);
INSERT INTO `all_items` VALUES (8514, 'Remnants of Old Dwarves\' Dreams', NULL, 'Странный предмет, может выпасть из призраков древних гномов, если они обретут вечный покой.', 'This strange object may be dropped by the ghosts of ancient Dwarves as they find eternal rest.', 'etc_inf_ore_high_i00', 0);
INSERT INTO `all_items` VALUES (8515, 'Charm of Courage: No Grade', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 1-19.', 'Prevents Exp. loss if killed during a siege war. (For Level 1 - Level 19)', 'etc_charm_of_courage_i00', 1);
INSERT INTO `all_items` VALUES (8516, 'Charm of Courage (D-Grade)', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 20-39. Доступен и для персонажей ниже 20-го уровня.', 'Prevents Exp. loss if killed during a siege war. (For Level 20 - Level 39)', 'etc_charm_of_courage_i01', 1);
INSERT INTO `all_items` VALUES (8517, 'Charm of Courage (C-Grade)', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 40-51. Доступен и для персонажей ниже 40-го уровня.', 'Prevents Exp. loss if killed during a siege war. (For Level 40 - Level 51)', 'etc_charm_of_courage_i02', 1);
INSERT INTO `all_items` VALUES (8518, 'Charm of Courage (B-Grade)', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 52-60. Доступен и для персонажей ниже 52-го уровня.', 'Prevents Exp. loss if killed during a siege war. (For Level 52 - Level 60)', 'etc_charm_of_courage_i03', 1);
INSERT INTO `all_items` VALUES (8519, 'Charm of Courage (A-Grade)', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 61-75. Доступен и для персонажей ниже 61-го уровня.', 'Prevents Exp. loss if killed during a siege war. (For Level 61 ~ Level 75)', 'etc_charm_of_courage_i04', 1);
INSERT INTO `all_items` VALUES (8520, 'Charm of Courage (S-Grade)', NULL, 'Дает возможность воскрешаться на месте смерти при Осаде Замка, Холла Клана или Битвы за Крепость. Для уровней 76-85. Доступен и для персонажей ниже 76-го уровня.', 'Prevents Exp. loss if killed during a siege war (for Level 76 - Level 80). Can also be used by characters below level 76.', 'etc_charm_of_courage_i05', 1);
INSERT INTO `all_items` VALUES (8521, 'Seed: Sea Coba', NULL, 'Семя Морской Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 74-84 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Sea Coba. For best results, a level 74-84 character must plant it on a level 74-84 monster.', 'etc_sea_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (8522, 'Seed: Alternative Sea Coba', NULL, 'Семя Новой Морской Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 74-84 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Alternative Sea Coba. For best results, a level 74-84 character must plant it on a level 74-84 monster.', 'etc_sea_coba_seed_i00', 11);
INSERT INTO `all_items` VALUES (8523, 'Seed: Twin Coba', NULL, 'Семя Двойной Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 77-87 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Twin Coba. For best results, a level 77-87 character must plant it on a level 77-87 monster.', 'etc_twin_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (8524, 'Seed: Alternative Twin Coba', NULL, 'Семя Новой Двойной Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 77-87 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Alternative Twin Coba. For best results, a level 77-87 character must plant it on a level 77-87 monster.', 'etc_twin_coba_seed_i00', 11);
INSERT INTO `all_items` VALUES (8525, 'Seed: Great Coba', NULL, 'Семя Большой Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 80-90 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Great Coba. For best results, a level 80-90 character must plant it on a level 80-90 monster.', 'etc_great_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (8526, 'Seed: Alternative Great Coba', NULL, 'Семя Новой Большой Кобы. Для получения плода вживите его в монстра в районе Руны. Наилучшего результата можно достичь, если персонаж и монстр 80-90 уровней.', 'Plant this seed onto a monster in the Rune area and it will bear the fruit of the Alternative Great Coba. For best results, a level 80-90 character must plant it on a level 80-90 monster.', 'etc_great_coba_seed_i00', 11);
