INSERT INTO `all_items` VALUES (8537, 'Adventurer\'s Box: B-Grade Accessory (Low Grade)', NULL, 'Есть шанс, что открыв коробку, вы получите аксессуар низкого качества Ранга B.', 'Open the box for a chance to obtain a B-Grade, low quality accessory.', 'etc_box_of_adventure_2_i00', 0);
INSERT INTO `all_items` VALUES (8538, 'Adventurer\'s Box: B-Grade Accessory (High Grade)', NULL, 'Есть шанс, что открыв коробку, вы получите аксессуар высокого качества Ранга B.', 'Open the box for a chance to obtain a B-Grade, high quality accessory.', 'etc_box_of_adventure_3_i00', 0);
INSERT INTO `all_items` VALUES (8539, 'Adventurer\'s Box: Hair Accessory', NULL, 'Есть шанс, что открыв коробку, вы получите Головной Убор Налетчика.', 'Open the box for a chance to obtain a Raider\'s Hair Accessory.', 'etc_box_of_adventure_4_i00', 0);
INSERT INTO `all_items` VALUES (8540, 'Adventurer\'s Box: Cradle of Creation', NULL, 'Есть шанс, что открыв коробку, вы получите Колыбель Создания.', 'Open the box for a chance to obtain a Cradle of Creation.', 'etc_box_of_adventure_5_i00', 0);
INSERT INTO `all_items` VALUES (8541, 'Little Harness', NULL, 'Экипируйте вашего маленького питомца этим седлом с помощью двойного щелчка мышки.', 'Outfit a baby pet with this harness by double-clicking.', 'etc_pet_armor_little_harness_i00', 0);
INSERT INTO `all_items` VALUES (8542, 'Newbie Travel Token', NULL, 'Этот значок помогает начинающим путешественникам бродить по различным местам. Персонажи до 20 уровня могут купить его в Гильдии Новичков для путешествия между Деревней Говорящего Острова, Деревней Темных Эльфов, Эльфийской Деревней, Деревней Гномов, Деревней Орков и Деревней Камаэль.', 'This token is used to help novice travelers move to various places. Characters under level 20 may redeem it at a Newbie Guide for travel between Talking Island Village, Dark Elf Village, Elven Village, Dwarven Village and Orc Village.', 'etc_coins_gold_i00', 0);
INSERT INTO `all_items` VALUES (8543, 'Bead Parcel', NULL, 'Отдайте эту посылку Начальнику Склада Яшени из Шутгарта.', 'Take this parcel of woven beads to Warehouse Chief Yasheni in the Town of Schuttgart.', 'accessary_mage_earing_i00', 0);
INSERT INTO `all_items` VALUES (8544, 'Timora Orc\'s Head', NULL, 'Отрезанная голова Орка Тиморы, предателя своего племени, который примкнул к Оркам Рагна.', 'Severed head of the cowardly Timora Orc who betrayed his own tribe and joined the Ragna Orcs.', 'etc_skull_red_i00', 0);
INSERT INTO `all_items` VALUES (8545, 'Kasha Spider\'s Tooth', NULL, 'Этот зуб паука добыт в битве.', 'This crooked spider\'s tooth was pulled out by hand during close combat.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8546, 'Horn of Baar Dre Vanul', NULL, 'Безупречно гладкий рог, добытый у Баала Дре Ванул, обитающего в южной части Плато Бессмертия.', 'This smooth, flawless horn comes from Baar Dre Vanul, who inhabits the Immortal Plateau\'s Southern Region.', 'etc_horn_i00', 0);
INSERT INTO `all_items` VALUES (8547, 'Old Box', NULL, 'Старая коробка, которую вы выудили во время рыбалки в Горячих Источниках. Если вы дважды щелкните по ней, то, возможно, получите Сертификат участия в войне за холл клана в Горячих Источниках.', 'An old box that can be caught by fishing in the Hot Springs area. If you double-click it, you can obtain the Certificate for Participation in a Clan Hall war in the Hot Springs at a certain rate of probability.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (8548, 'Hot Springs Lure', NULL, 'Наживка для ловли старой коробки в Горячих Источниках Годдарда. Уровень мастерства рыболовства: 20 и выше.', 'This fishing lure can be used to catch old box while fishing in the Hot Springs area in Goddard. Only characters with Fishing Mastery Level 20 or higher can haul in the old box.', 'etc_bait_i02', 16);
INSERT INTO `all_items` VALUES (8549, 'Bruin Lizardman Blood', NULL, 'Кровь Ящера Бруина.', 'Blood obtained by slaying a Bruin Lizardman.', 'etc_lesser_potion_purple_i00', 0);
INSERT INTO `all_items` VALUES (8550, 'Picot Araneid\'s Leg', NULL, 'Лапа Арахнида Пикот.', 'Leg obtained by slaying a Picot Araneid.', 'etc_sting_b_i00', 0);
INSERT INTO `all_items` VALUES (8551, 'Box of Cheerleading Gear Used to encourage victory.', NULL, 'Коробка вспомогательных предметов. Двойной щелчок превратит ее в другой предмет случайным образом.', 'Box of Cheerleading Items for Cheering on the Red Devils. If you double-click it, it will randomly change to a different item.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (8552, 'Mask of Spirits', NULL, 'Головной аксессуар ивента Halloween 2006.', 'A hair accessory for the 2006 Halloween Event.', 'accessory_worldcup_mask_i00', 0);
INSERT INTO `all_items` VALUES (8553, 'Red Mask of Victory, Fabric', NULL, 'Основной материал для создания Маски Духов. Можно продать в Торговой Лавке.', 'The essential ingredient needed to make a Mask of the Red Devils. It can be sold at a regular store.', 'etc_piece_of_cloth_red_i00', 6);
INSERT INTO `all_items` VALUES (8554, 'Recipe: Red Mask of Victory (100%)', NULL, 'Доступно любой расе. Рецепт изготовления Маски Духов. Требует умения Создание Обычных Предметов 4 уровня.', 'For All Tribes. Recipe for a Mask of the Red Devils. Requires Create Common Item Skill Level 4.', 'etc_recipe_green_i00', 5);
INSERT INTO `all_items` VALUES (8555, 'Echo Crystal - Viva Victory Korea', NULL, 'Музыкальный Кристалл проигрывает тему Кубка Мира. После использования исчезает.', 'Echo Crystal that plays the theme music of the World Cup. It disappears after one use.', 'etc_echo_crystal_i00', 0);
INSERT INTO `all_items` VALUES (8556, 'Dewdrop of Destruction', NULL, 'Щелчок по Росе Разрушения приводит к исчезновению портрета. Нельзя выбросить, но при входе в Гробницу Последнего Императора исчезает сама по себе.', 'Clicking the Dewdrop of Destruction will make the portrait disappear. It will disappear when one enters the Last Imperial Sepulcher.', 'etc_lesser_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (8557, 'Blue Party Hat', NULL, 'Сувенир к трехлетнему юбилею. Требует две ячейки головных уборов.', 'Three year anniversary hair accessory souvenir. Uses two hair accessory slots.', 'accessory_party_hat_blue_i00', 0);
INSERT INTO `all_items` VALUES (8558, 'Eva\'s Mark (Event)', NULL, 'Изготовлено специально для ивента. Нельзя обменять/выбросить.', 'This hair accessory is awarded to the winners of the Fishing King Championship Tournament.', 'accessory_soaring_bird_i00', 0);
INSERT INTO `all_items` VALUES (8559, 'Diadem', NULL, 'Головной аксессуар невесты. Только для персонажей женского пола. Требует две ячейки головных уборов.', 'Hair accessory worn by a bride at her wedding ceremony.  This hair accessory can only be worn by females only.', 'accessory_flower_cap_i00', 0);
INSERT INTO `all_items` VALUES (8560, 'Teddy Bear Hat', NULL, 'Забавный Головной аксессуар в виде медвежонка. Требует две ячейки головных уборов.', 'A fun, bear-shaped hair accessory.', 'accessory_bear_cap_i00', 0);
INSERT INTO `all_items` VALUES (8561, 'Piggy Hat', NULL, 'Забавный Головной аксессуар в виде хрюшки. Требует две ячейки головных уборов.', 'A fun, pig-shaped hair accessory.', 'accessory_pig_cap_i00', 0);
INSERT INTO `all_items` VALUES (8562, 'Jester Hat', NULL, 'Шутовской колпак с раздвоенной верхушкой. Требует две ячейки головных уборов.', 'A festive jester hat with a split top.', 'accessory_jester_cap_i00', 0);
INSERT INTO `all_items` VALUES (8563, 'Wizard Hat', NULL, 'Широкополая шляпа чародея. Требует две ячейки головных уборов.', 'A Wizard Hat with a wide brim and bent tip.', 'accessory_magic_cap_i00', 0);
INSERT INTO `all_items` VALUES (8564, 'Dapper Cap', NULL, 'Стильная кепка с козырьком. Требует две ячейки головных уборов.', 'A stylish cap with a visor.', 'accessory_dandy_cap_i00', 0);
INSERT INTO `all_items` VALUES (8565, 'Romantic Chapeau', NULL, 'Экстравагантная модная шляпка. Требует две ячейки головных уборов.', 'An extravagant chapeau adorned with feathers.', 'accessory_romantic_chaperon_i00', 0);
INSERT INTO `all_items` VALUES (8566, 'Iron Circlet', NULL, 'Этот аксессуар может использоваться в иностранных ивентах. Нельзя обменять/выбросить. Требует две ячейки головных уборов.', 'Hair accessory used in overseas events.  This item is designed for use in events only and cannot be exchanged or dropped.', 'accessory_iron_circlet_i00', 0);
INSERT INTO `all_items` VALUES (8567, 'Valakas Slayer Circlet', NULL, 'Подарочная диадема для убийцы Валакаса.', 'The circlet presented to a player who has defeated Valakas.', 'accessory_valakas_circlet_i00', 0);
INSERT INTO `all_items` VALUES (8568, 'Antharas Slayer Circlet', NULL, 'Подарочная диадема для убийцы Антараса.', 'The circlet presented to a player who has defeated Antharas.', 'accessory_antaras_circlet_i00', 0);
INSERT INTO `all_items` VALUES (8569, 'Half Face Mask', NULL, 'Аксессуар, закрывающий пол-лица.', 'A mysterious costume accessory that covers half of the wearer\'s face.', 'accessory_half_face_i00', 0);
INSERT INTO `all_items` VALUES (8570, 'Event Gift Box', NULL, 'Предмет для ивента PC Сafe купона. Если щелкнуть по нему дважды, он случайным образом превратится в другой предмет. Нельзя обменять/выбросить. (Этот предмет может быть использован только в том случае, если ваш лимит веса заполнен не более чем на 80% и у вас есть 10 и более свободных ячеек в инвентаре.)', 'An item that is used for the PC Cafe coupon event.  If you double-click it, it will randomly change to a different item. This item cannot be exchanged or dropped. (This item can be used when the weight gauge shows less than 80% and 10 or more empty slots are available in the inventory.)', 'etc_box_of_adventure_3_i00', 0);
INSERT INTO `all_items` VALUES (8571, 'Event Gift Box', NULL, 'Предмет для ивента PC Сafe купона. Если щелкнуть по нему дважды, он случайным образом превратится в другой предмет. Нельзя обменять/выбросить. (Этот предмет может быть использован только в том случае, если ваш лимит веса заполнен не более чем на 80% и у вас есть 10 и более свободных ячеек в инвентаре.)', 'An item that is used for the PC Cafe coupon event.  If you double-click it, it will randomly change to a different item. This item cannot be exchanged or dropped. (This item can be used when the weight gauge shows less than 80% and 10 or more empty slots are available in the inventory.)', 'etc_box_of_adventure_3_i00', 0);
