INSERT INTO `all_items` VALUES (8592, 'Weapon Exchange Coupon - No Grade', NULL, 'Предмет для ивента PC Сafe. Этот купон можно обменять на оружие без ранга в Гильдии Путешественников.', 'An item that is used for the PC Cafe coupon event. An exchange coupon that can be used to exchange for a no grade weapon at Adventurers\' Guild.', 'etc_lottery_card_i00', 23);
INSERT INTO `all_items` VALUES (8593, 'Weapon Exchange Coupon (C-Grade)', NULL, 'Предмет для ивента PC Сafe. Этот купон можно обменять на оружие Ранга D в Гильдии Путешественников.', 'An item that is used for the PC Cafe coupon event.  An exchange coupon that can be used to exchange for a D grade weapon at Adventurers\' Guild.', 'etc_lottery_card_i00', 23);
INSERT INTO `all_items` VALUES (8594, 'Scroll: Recovery (No Grade)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 19 или ниже. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death. This item can only be used on self by a character of level 19 or below. This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i00', 1);
INSERT INTO `all_items` VALUES (8595, 'Scroll: Recovery (Grade D)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 20-39. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death.  This item can only be used on self by a character whose level is between 20 and 39.  This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i01', 1);
INSERT INTO `all_items` VALUES (8596, 'Scroll: Recovery (Grade C)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 40-51. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death.  This item can only be used on self by a character whose level is between 40 and 51.  This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i02', 1);
INSERT INTO `all_items` VALUES (8597, 'Scroll: Recovery (Grade B)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 52-60. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death.  This item can only be used on self by a character whose level is between 52 and 60.  This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i03', 1);
INSERT INTO `all_items` VALUES (8598, 'Scroll: Recovery (Grade A)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 61-75. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death.  This item can only be used on self by a character whose level is between 61 and 75.  This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i04', 1);
INSERT INTO `all_items` VALUES (8599, 'Scroll: Recovery (Grade S)', NULL, 'Восстанавливает характеристики персонажа после смерти. Можно использовать только на себе. Уровень персонажа: 76 и выше. Не может использоваться хаотическим персонажем.', 'This scroll recovers a character\'s abilities from the effects of death. This item can only be used by a character whose level is 76 or higher.  This scroll cannot be used by chaotic characters.', 'etc_penalty_recovery_i05', 1);
