INSERT INTO `all_items` VALUES (8615, 'Summoning Crystal', NULL, 'Кристалл, обладающий магической силой. Используется для телепортации.', 'A crystal imbued with mystical power.  Used for teleportation magic.', 'etc_recall_crystal_i00', 6);
INSERT INTO `all_items` VALUES (8616, 'Spellbook: Summon Friend', NULL, 'Книга, необходимая для изучения умения \"Призвать Друга\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 56.', 'Spellbook needed to learn Summon Friend. Used by Warlocks, Elemental Summoners and Phantom Summoners.', 'etc_party_sommons_i00', 0);
INSERT INTO `all_items` VALUES (8617, 'Spellbook: Word of Invitation', NULL, 'Книга, необходимая для изучения умения \"Приглашение\". Профессии: Властитель Огня, Певец Заклинаний, Заклинатель Бури.', 'Spellbook needed to learn Word of Invitation. Used by Sorcerers, Spellsingers and Spellhowlers.', 'etc_party_sommons_i01', 0);
INSERT INTO `all_items` VALUES (8618, 'Ancient Book: Divine Inspiration (Modern Language Version)', NULL, 'Возвращает забытые навыки. Эта книга была переиздана после перевода на современный язык. (Может использоваться только персонажами уровня 52 или выше.)', 'Restores forgotten abilities. The book was re-published after being translated into the modern language.  (Can only be used by characters level 52 or higher.)', 'etc_add_buffslot_i00', 0);
INSERT INTO `all_items` VALUES (8619, 'Ancient Book: Divine Inspiration (Original Language Version)', NULL, 'Возвращает забытые навыки. Эта книга была издана для древних учеников с обучающей целью. В ней содержится больше информации, чем в современной версии. (Может использоваться только персонажами уровня 61 или выше.)', 'Restores forgotten abilities. This book was published by ancient scholars for research purposes.  It contains more information than the modern language version. (Can only be used by characters level 61 or higher.)', 'etc_add_buffslot_i01', 0);
INSERT INTO `all_items` VALUES (8620, 'Ancient Book: Divine Inspiration (Manuscript)', NULL, 'Возвращает забытые навыки. Это рукописная копия книги. По содержанию не отличается от оригинала. (Может использоваться только персонажами уровня 76 или выше.)', 'Restores forgotten abilities. This book is a hand-written copy of the original. It is almost the same as the original version. (Can only be used by characters level 76 or higher.)', 'etc_add_buffslot_i02', 0);
INSERT INTO `all_items` VALUES (8621, 'Ancient Book: Divine Inspiration (Original Version)', NULL, 'Возвращает забытые навыки. Кто не знает древний язык, тот ничего не поймет из этой книги. (Может использоваться только персонажами уровня 76 или выше.)', 'Restores forgotten abilities. Those who lack the requisite knowledge cannot understand its contents. (Can only be used by characters level 76 or higher.)  This item cannot be exchanged or dropped.', 'etc_add_buffslot_i03', 0);
INSERT INTO `all_items` VALUES (8622, 'Elixir of Life (No Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 19 и ниже. Время перезарядки: 5 минут.', 'Regenerates HP. Can only be used by characters below level 19 upon themselves. Re-use delay is 5 minutes.', 'etc_super_hp_potion_i00', 24);
INSERT INTO `all_items` VALUES (8623, 'Elixir of Life (D-Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 20-39. Время перезарядки: 5 минут.', 'Regenerates HP.  This item can only be used by a character whose level is between 20 and 39.  Re-use delay is 5 minutes.', 'etc_super_hp_potion_i01', 24);
INSERT INTO `all_items` VALUES (8624, 'Elixir of Life (C-Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 40-51. Время перезарядки: 5 минут.', 'Regenerates HP.  This item can only be used by a character whose level is between 40 and 51.  Re-use delay is 5 minutes.', 'etc_super_hp_potion_i02', 24);
INSERT INTO `all_items` VALUES (8625, 'Elixir of Life (B-Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 52-60. Время перезарядки: 5 минут.', 'Regenerates HP.  This item can only be used by a character whose level is between 52 and 60.  Re-use delay is 5 minutes.', 'etc_super_hp_potion_i03', 24);
INSERT INTO `all_items` VALUES (8626, 'Elixir of Life (A-Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 61-75. Время перезарядки: 5 минут.', 'Regenerates HP.  This item can only be used by a character whose level is between 61 and 75.  Re-use delay is 5 minutes.', 'etc_super_hp_potion_i04', 24);
INSERT INTO `all_items` VALUES (8627, 'Elixir of Life (S-Grade)', NULL, 'Восстанавливает HP. Используется только на себя. Уровень персонажа: 76 и выше. Время перезарядки: 5 минут.', 'Regenerates HP. This item can only be used by a character whose level is 76 or higher. Re-use delay is 5 minutes.', 'etc_super_hp_potion_i05', 24);
INSERT INTO `all_items` VALUES (8628, 'Elixir of Mental Strength (No Grade)', NULL, 'Восстанавливает MP. Используется только на себя. Уровень персонажа: 19 и ниже. Время перезарядки: 5 минут.', 'Regenerates MP. Can only be used by characters below level 19 upon themselves. Re-use delay is 5 minutes.', 'etc_super_mp_potion_i00', 24);
INSERT INTO `all_items` VALUES (8629, 'Elixir of Mental Strength (D-Grade)', NULL, 'Восстанавливает MP. Используется только на себя. Уровень персонажа: 20-39. Время перезарядки: 5 минут.', 'Regenerates MP. Can be used by characters above level 20 and below level 39 upon themselves. Re-use delay 5 minutes.', 'etc_super_mp_potion_i01', 24);
INSERT INTO `all_items` VALUES (8630, 'Elixir of Mental Strength (C-Grade)', NULL, 'Восстанавливает MP. Используется только на себя. Уровень персонажа: 40-51. Время перезарядки: 5 минут.', 'Regenerates MP. Can be used by characters above level 40 and below level 51 upon themselves. Re-use delay 5 minutes.', 'etc_super_mp_potion_i02', 24);
