INSERT INTO `all_items` VALUES (8658, 'Mysterious Solvent', NULL, 'Разжижает любой предмет. Используется для изготовления Эликсиров.', 'Dilutes any substance it is mixed with. Used when creating an elixir.', 'etc_dragon_blood_i00', 6);
INSERT INTO `all_items` VALUES (8659, 'Coffer of Shadows', NULL, 'Загадочный предмет, в котором содержится немного нестабильной темной энергии. Двойной щелчок превращает его в особый предмет случайным образом.', 'A mystical object that has a tiny bit of unstable dark energy trapped inside.  Double-click to transform into a random special item.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (8660, 'Demon Horns', NULL, 'Головной аксессуар ивента Halloween 2006.', 'A hair accessory for the 2006 Halloween Event.', 'accessory_hair_cornu_i00', 0);
INSERT INTO `all_items` VALUES (8661, 'Mask of Spirits', NULL, 'Головной аксессуар ивента Halloween 2006.', 'A hair accessory for the 2006 Halloween Event.', 'accessory_worldcup_mask_i00', 0);
INSERT INTO `all_items` VALUES (8662, 'Fairy Antennae (Event)', NULL, 'Миловидный головной аксессуар в виде антенок со звездочками. Ивентовый предмет, который Нельзя обменять/выбросить.', 'Cute antennae hair accessory with stars. This is an event item which cannot be exchanged or dropped.', 'accessory_hair_feeler_i00', 0);
INSERT INTO `all_items` VALUES (8663, 'Mystery Potion (Event)', NULL, 'Ивентовый предмет из другого мира. На ярлыке написано «Эффект непредсказуем. Результат временный.»', 'Altered Realities Event Item.  The label reads \"Effects of this oil may be unpredictable.  Results are temporary at best.\"', 'etc_lesser_potion_clear_i00', 3);
INSERT INTO `all_items` VALUES (8664, 'Facelifting Potion - A (Event)', NULL, 'Ивентовый предмет из другого мира. На ярлыке написано «Эффект непредсказуем. ОСТОРОЖНО! Вызванные изменения останутся навсегда. Пейте на свой страх и риск!»', 'Altered Realities Event Item.  The label reads \"Effects of this oil may be unpredictable.  BEWARE!  Changes caused will be permanent.  Drink at your own risk!\"', 'etc_lesser_potion_purple_i00', 3);
