INSERT INTO `all_items` VALUES (8722, 'Daimon Crystal Fragment', NULL, 'Ингредиент, необходимый Гномам для изготовления Кристалла Дэймона. Можно продать в Торговой Лавке.', 'An essential ingredient needed by a Dwarf to make Daimon Crystal. It can be sold at a regular store.', 'etc_bark_gold_i00', 6);
INSERT INTO `all_items` VALUES (8723, 'Life Stone -  Level 46', NULL, 'Обычный минерал, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 46-го уровня и выше.', 'An ordinary mineral that has been petrified by a creature\'s physical or magical damage. Key component used in weapon Augmentation by characters level 46 and above.', 'etc_mineral_general_i00', 0);
