INSERT INTO `all_items` VALUES (8763, 'Elrokian Trap', NULL, 'Ловушка Первобытного Острова.', 'Trap weapon used on the Primeval Isle.', 'weapon_seize_mace_i00', 4);
INSERT INTO `all_items` VALUES (8764, 'Trap Stone', NULL, 'Камень, использующийся в Ловушке Элроки.', 'A stone used in the Elrokian Trap.', 'etc_capture_stone_i00', 0);
INSERT INTO `all_items` VALUES (8765, 'Red Gem', NULL, 'Красные самоцветы, которые собирает Начальник Склада Кламп в Городе Аден. Принесите ему 50 или больше самоцветов и сможете сыграть с ним в карточную игру.', 'Shiny red gems collected by Warehouse Chief Klump of Aden Castle Town. You can play the card game if you bring Klump more than 50 of these gems.', 'ets_red_abead_i00', 0);
INSERT INTO `all_items` VALUES (8766, 'Spirit Bead', NULL, 'Бисер, который собирает Кузнец Вилберт в Городе Аден. Принесите ему 50 или больше штук и сможете сыграть с ним в карточную игру.', 'Beads collected by Blacksmith Wilbert of Aden Castle Town. You can play the game if you bring him more than 50.', 'etc_bead_blue_i00', 0);
INSERT INTO `all_items` VALUES (8767, 'Tyrannosaurus Claw', NULL, 'Коготь убитого Тиранозавра.', 'This claw can be obtained by defeating a Tyrannosaurus.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8768, 'Diary Fragment', NULL, 'Часть дневника участника пропавшей экспедиции. Отнесите Капитану Маркесу, начальнику экспедиции.', 'This is a piece of a missing expedition member\'s diary. Deliver it to the expedition leader, Captain Marquez.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (8769, 'Expedition Member\'s Letter', NULL, 'Письмо участника пропавшей экспедиции, адресованное его другу Кирикачину из племени Элроки. Отнесите Кирикачину.', 'This is a letter that a missing expedition member sent to his Elrokian friend Kirikachin. Deliver it to Kirikachin.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (8770, 'Ornithomimus Claw', NULL, 'Отдайте это Азамаху, сыну вождя.', 'Take this to Asamah, the chief\'s son.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8771, 'Deinonychus Bone', NULL, 'Отдайте это Азамаху, сыну вождя.', 'Take this to Asamah, the chief\'s son.', 'etc_piece_bone_red_i00', 0);
INSERT INTO `all_items` VALUES (8772, 'Pachycephalosaurus Skin', NULL, 'Отдайте это Азамаху, сыну вождя.', 'Take this to Asamah, the chief\'s son.', 'etc_leather_yellow_i00', 0);
INSERT INTO `all_items` VALUES (8773, 'Practice Elrokian Trap', NULL, 'Отдайте эту ловушку Кирикачину.', 'Take this practice trap, which is necessary for learning a special Elrokian tribal skill, to Kirikachin.', 'weapon_seize_mace_i00', 0);
INSERT INTO `all_items` VALUES (8774, 'Dinosaur Tissue', NULL, 'Ткань Динозавра – незаменимый ингредиент для магов и Гномов-ремесленников.', 'This Dinosaur Tissue is a research ingredient for magicians and Dwarven craftsmen.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (8775, 'Dinosaur Egg', NULL, 'Яйцо Динозавра – незаменимый ингредиент для магов и Гномов-ремесленников.', 'This Dinosaur Egg is a research ingredient (along with Dinosaur Tissue) for magicians and Dwarven craftsmen.', 'etc_dragon_egg_i05', 0);
INSERT INTO `all_items` VALUES (8776, 'Bones of a Plains Dinosaur', NULL, 'Это незаменимый ингредиент для Жрецов Шилен и магов.', 'This is a research ingredient for Shilen\'s priests and magicians.', 'etc_piece_bone_black_i00', 0);
INSERT INTO `all_items` VALUES (8777, 'Ancient Creatures and How I Long To Be With Them', NULL, 'Найденная в главной библиотеке Руны, эта книга содержит информацию о древних существах.', 'Found in Rune\'s main library, this book contains information about ancient creatures.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (8778, 'Mantarasa Egg', NULL, 'Этот мистический предмет может лечить любые заболевания. Его можно добыть в Потерянном Гнезде на Первобытном Острове.', 'This mysterious item can cure any illness. It can be obtained in the Primeval Isle\'s Lost Nest.', 'etc_dragon_egg_i03', 0);
INSERT INTO `all_items` VALUES (8779, 'Ornithomimus Claw', NULL, 'Этот коготь динозавра нужен Шаману Элроки Каракавею для проведения особого ритуала.', 'This dinosaur claw can be used by the Elrokian Shaman Karakawei to perform a special ritual.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (8780, 'Deinonychus Bone Fragment', NULL, 'Обломок кости динозавра нужен Шаману Элроки Каракавею для проведения особого ритуала.', 'This dinosaur bone fragment can be used by the Elrokian Shaman Karakawei to perform a special ritual.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (8781, 'Epitaph of Wisdom', NULL, 'Эта эпитафия может быть добыта из Чута Каиму Колонны Мудрости в Потерянном Гнезде.', 'This epitaph can be obtained from the Chuta Kaimu Pillar of Wisdom in the Lost Nest.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (8782, 'Gazkh Fragment', NULL, 'Это обломок топора Газха, который Шилен дала воинам племени Элроки много лет назад.', 'This is a fragment of the axe Gazkh that Shilen gave to the Elrokian warriors long ago.', 'etc_piece_of_gazk_i00', 0);
INSERT INTO `all_items` VALUES (8783, 'Bone Powder', NULL, 'Этот прах древнего воина племени Элроки может быть получен после проведения мемориальной службы над Могилой Воина.', 'These ash-like remains of an ancient Elrokian warrior can be obtained after performing a memorial service at the Warrior\'s Grave.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (8784, 'Gazkh', NULL, 'Этот древний топор, Газх, может быть восстановлен Каменной Статуей Шилен. Он необходим в битве с Сэйлреном.', 'This ancient axe, Gazkh, can be reformed by Shilen\'s Stone Statue. It is necessary to battle Sailren.', 'etc_head_of_gazk_i00', 0);
INSERT INTO `all_items` VALUES (8785, 'Dinosaur Fang Necklace', NULL, 'Это ожерелье являлось знаком отличия древних членов племени Элроки, напавших на верфь.', 'This necklace is the mark of the ancient Elrokians who raid the wharf.', 'etc_ketra_friendship_1_i00', 0);
INSERT INTO `all_items` VALUES (8786, 'Primeval Potion', NULL, 'Увеличивает сопротивление к отравлению и анестезии.', 'Increases resistance to poison and anesthesia.', 'etc_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (8787, 'Sprigant\'s Fruit', NULL, 'Этот фрукт Спригана увеличивает сопротивление к отравлению и анестезии.', 'This fruit, dropped by Sprigants, increases resistance to poison and anesthesia.', 'etc_fruit_green_i00', 0);
INSERT INTO `all_items` VALUES (8788, 'Sirra\'s Blade', 'Haste', '<Свойство Кристалла Души> Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP.', 'Haste	a,<Soul Crystal Enhancement>n Increases Atk. Spd. by 6%. Increases damage inflicted during PvP.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (8789, 'Sirra\'s Blade', 'Health', '<Свойство Кристалла Души> Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.', 'Health	a,<Soul Crystal Enhancement>n Increases maximum HP by 25%. Increases damage inflicted during PvP.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (8790, 'Sirra\'s Blade', 'Critical Poison', '<Свойство Кристалла Души> Увеличивает шанс, что цель будет отравлена на 15% при обычной Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Poison	a,<Soul Crystal Enhancement>n Increases the possibility that the target will be poisoned by 15% during a regular critical attack. Increases damage inflicted during PvP.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (8791, 'Sword of Ipos', 'Focus', '<Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement> Increases Critical by 61. Increases damage inflicted during PvP.', 'weapon_sword_of_ipos_i01', 4);
