INSERT INTO `all_items` VALUES (8799, 'Behemoth\'s Tuning Fork', 'Anger', '<Свойство Кристалла Души> Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 32. Наносит дополнительный урон в PvP.', 'Anger	a,<Soul Crystal Enhancement>n Decreases maximum HP by 15% and increases P. Atk. by 32. Enhances damage to target during PvP.', 'weapon_tuning_fork_of_behemoth_i01', 4);
INSERT INTO `all_items` VALUES (8800, 'Naga Storm', 'Focus', '<Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 67. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement>n Increases critical attack rate by 67. Increases damage inflicted during PvP.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (8801, 'Naga Storm', 'Critical Damage', '<Свойство Кристалла Души> Увеличивает Физ. Атк. на 200 при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Damage	a,<Soul Crystal Enhancement>n Increases P. Atk. by 200 during a critical attack. Increases damage inflicted during PvP.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (8802, 'Naga Storm', 'Back Blow', '<Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 37 при атаке цели со спины. Наносит дополнительный урон в PvP.', 'Back Blow	a,<Soul Crystal Enhancement>n Increases the critical attack rate by 37 when attacking a target from behind. Increases damage inflicted during PvP.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (8803, 'Tiphon\'s Spear', 'Critical Stun', '<Свойство Кристалла Души> Дает 25% шанс оглушить при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Stun	a,<Soul Crystal Enhancement>n Increases the chance of stun effect by 25% during a critical attack. Increases damage inflicted during PvP.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (8804, 'Tiphon\'s Spear', 'Towering Blow', '<Свойство Кристалла Души> Увеличивает шанс увеличения дальности атаки. Наносит дополнительный урон в PvP.', 'Towering Blow	a,<Soul Crystal Enhancement>n Increases the possibility of increasing attack range. Increases damage inflicted during PvP.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (8805, 'Tiphon\'s Spear', 'Wild Blow', '<Свойство Кристалла Души> Увеличивает шанс увеличения угла атаки. Наносит дополнительный урон в PvP.', 'Wild Blow	a,<Soul Crystal Enhancement>n Increases the possibility of broadening the angle of attack. Increases damage inflicted during PvP.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (8806, 'Shyeed\'s Bow', 'Cheap Shot', '<Свойство Кристалла Души> Дополнительный 30% шанс понизить расход MP на 1 при обычной атаке. Наносит дополнительный урон в PvP.', 'Cheap Shot	a,<Soul Crystal Enhancement>n Decreases MP consumption by 1 at a 30% probability during an ordinary attack. Increases damage inflicted during PvP.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (8807, 'Shyeed\'s Bow', 'Focus', '<Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement> Increases Critical by 61. Increases damage inflicted during PvP.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (8808, 'Shyeed\'s Bow', 'Quick Recovery', '<Свойство Кристалла Души> Уменьшает время перезарядки приблизительно на 17%. Наносит дополнительный урон в PvP.', 'Quick Recovery	a,<Soul Crystal Enhancement>n Decreases re-use delay by about 17%. Increases damage inflicted during PvP.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (8809, 'Sobekk\'s Hurricane', 'Rsk. Haste', '<Свойство Кристалла Души> Увеличивает Скор. Атк. на 11% когда HP падают ниже 60%. Наносит дополнительный урон в PvP.', 'Rsk. Haste	a,<Soul Crystal Enhancement>n Increases Atk. Spd. by 11% when HP falls below 60%. Increases damage inflicted during PvP.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (8810, 'Sobekk\'s Hurricane', 'Haste', '<Свойство Кристалла Души> Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP.', 'Haste	a,<Soul Crystal Enhancement>n Increases Atk. Spd. by about 6%. Increases damage inflicted during PvP.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (8811, 'Sobekk\'s Hurricane', 'Critical Drain', '<Свойство Кристалла Души> Увеличивает возможность поглощения 14 HP при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Drain	a,<Soul Crystal Enhancement>n Increases the possibility of absorbing 14 HP during a critical attack. Increases damage inflicted during PvP.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (8812, 'Themis\' Tongue', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Increases damage inflicted during PvP.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (8813, 'Themis\' Tongue', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Mental Shield	a,<Soul Crystal Enhancement>n Increases the chances of causing Mental Shield by 50% when using good magic upon a target. Increases damage inflicted during PvP.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (8814, 'Themis\' Tongue', 'Magic Focus', '<Свойство Кристалла Души>Дает 20% шанс наложения Фокусировки при использовании благотворного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Focus	a,<Soul Crystal Enhancement>n Increases the chances of causing Focus by 20% when using good magic upon a target. Increases damage inflicted during PvP.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (8815, 'Cabrio\'s Hand', 'Conversion', '<Свойство Кристалла Души> Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP.', 'Conversion	a,<Soul Crystal Enhancement>n Increases maximum MP by 60% and decreases maximum HP by 40%. Increases damage inflicted during PvP.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (8816, 'Cabrio\'s Hand', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Increases damage inflicted during PvP.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (8817, 'Cabrio\'s Hand', 'Magic Silence', '<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Silence	a,<Soul Crystal Enhancement>n Increases the chances of causing Sleep by 10% when using bad magic upon a target. Increases damage inflicted during PvP.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (8818, 'Daimon Crystal', 'Mana Up', '<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>n Increases maximum MP by 30%. Increases damage inflicted during PvP.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (8819, 'Daimon Crystal', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Acumen	a,<Soul Crystal Enhancement>n Increases casting speed by 15%. Increases damage inflicted during PvP.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (8820, 'Daimon Crystal', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP.', 'Magic Mental Shield	a,<Soul Crystal Enhancement>n Increases the chances of causing Mental Shield by 50% when using good magic upon a target. Increases damage inflicted during PvP.', 'weapon_crystal_of_deamon_i01', 4);
