INSERT INTO `all_items` VALUES (8869, 'Shadow Item Exchange Coupon (D-Grade)', NULL, 'Купон, позволяющий получить Теневой Предмет Ранга D. Отдайте его любому Великому Мастеру или Магистру, отвечающему за смену профессии.', 'This exchange coupon allows you to obtain a D-grade Shadow Item.', 'etc_lottery_card_i00', 0);
INSERT INTO `all_items` VALUES (8870, 'Shadow Item Exchange Coupon (C-Grade)', NULL, 'Купон, позволяющий получить Теневой Предмет Ранга C. Отдайте его любому Великому Мастеру или Магистру, отвечающему за смену профессии.', 'This exchange coupon allows you to obtain a C-grade Shadow Item.', 'etc_lottery_card_i00', 0);
INSERT INTO `all_items` VALUES (8871, 'Strategy Guide', NULL, 'Эта книга содержит информацию о методах управления и стратегиях Командного Канала. Используйте ее, чтобы создать Канал Команды.', 'This book contains information about the methods and strategies used to lead a Command Channel. Use it to create a Command Channel.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (8872, 'Flash Gunpowder', NULL, 'Особый бездымный порох. Потребляется при использовании умения Штурмовое Орудие.', 'This specially processed gunpowder doesn\'t create smoke. It is consumed while using the swoop cannon skill.', 'etc_powder_gray_i00', 0);
INSERT INTO `all_items` VALUES (8873, 'Phoenix Blood', NULL, 'Расходный материал для использования Души Феникса.', 'A consumption item for using Soul of the Phoenix.', 'etc_feather_gold_i00', 0);
