INSERT INTO `all_items` VALUES (8905, 'Ancient Spellbook: Purification Field', NULL, 'Древняя Книга, необходимая для изучения умения \"Поле Очищения\". Профессия: Кардинал.', 'Ancient Spellbook needed to learn Purification Field. Used by a Cardinal.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (8906, 'Ancient Spellbook: Miracle', NULL, 'Древняя Книга, необходимая для изучения умения \"Чудо\". Профессия: Кардинал.', 'Ancient Spellbook needed to learn Miracle. Used by a Cardinal.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (8907, 'Ancient Spellbook: Flames of Invincibility', NULL, 'Древняя Книга, необходимая для изучения умения \"Пламя Неуязвимости\". Профессия: Деспот.', 'Ancient Spellbook needed to learn Flames of Invincibility. Used by a Dominator.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (8908, 'Ancient Spellbook: Mass Recharge', NULL, 'Древняя Книга, необходимая для изучения умения \"Массовое Восстановление\". Профессии: Жрец Евы, Жрец Шилен.', 'Ancient Spellbook needed to learn Mass Recharge. Can be used by an Eva\'s Saint and Shillien Saint.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (8909, 'Blueprint: Summon Swoop Cannon', NULL, 'Чертеж, необходимый для изучения умения \"Призвать Штурмовое Орудие\". Профессия: Кузнец.Необходимый уровень: 68', 'Blueprint needed to learn the Summon Swoop Cannon technique. Can be used by a Warsmith.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (8910, 'Black Feather Mask (Event)', NULL, 'Головной аксессуар с черным пером. Требует две ячейки головных уборов. Это предмет ивента, который нельзя выбросить или обменять.', 'Hair accessory containing a dark feather. It uses 2 hair accessory slots. This is an event item which cannot be exchanged or dropped.', 'accessary_black_feather_mask_i00', 0);
INSERT INTO `all_items` VALUES (8911, 'Black Half Mask (Event)', NULL, 'Черная полумаска. Предмет ивента.', 'A black-colored half mask. Event Item.', 'Accessary_black_half_mask_i00', 0);
INSERT INTO `all_items` VALUES (8912, 'Single Stem Flower', NULL, 'Заколка для волос в форме цветка.', 'Hair pin made in the shape of a flower.', 'accessory_hairpin_i00', 0);
INSERT INTO `all_items` VALUES (8913, 'Butterfly Hairpin', NULL, 'Заколка для волос в форме бабочки. Только для персонажей женского пола.', 'Hairpin in the shape of a butterfly. This is a female-only hair accessory.', 'Accessary_butterfly_hearpin_i00', 0);
INSERT INTO `all_items` VALUES (8914, 'Luxurious Gold Circlet', NULL, 'Элитная золотая диадема. Требует две ячейки головных уборов.', 'Luxurious Gold Circlet. It uses 2 hair accessory slots.', 'Accessary_gold_circlet_i00', 0);
INSERT INTO `all_items` VALUES (8915, 'Luxurious Silver Circlet', NULL, 'Превосходная серебряная диадема. Требует две ячейки головных уборов.', 'Luxurious Silver Circlet. It uses 2 hair accessory slots.', 'Accessary_gold_circlet_i01', 0);
