INSERT INTO `all_items` VALUES (8918, 'Leather Cap', NULL, 'Средневековая кожаная шляпа. Требует две ячейки головных уборов.', 'A medieval-era hat made of leather. It uses 2 hair accessory slots.', 'Accessary_middle_ages_i00', 0);
INSERT INTO `all_items` VALUES (8919, 'First Mate\'s Hat', NULL, 'Эта шляпа принадлежала Правой Руке Закена. Требует две ячейки головных уборов. Этот предмет Нельзя обменять/выбросить.', 'A hat befitting a favored member of Zaken\'s crew.  Uses 2 hair accessory slots. This item cannot be exchanged or dropped.', 'Accessary_middle_ages_i01', 0);
INSERT INTO `all_items` VALUES (8920, 'Angel Halo', NULL, 'Аксессуар, обладающий святой энергией. Требует две ячейки головных уборов.', 'Hair accessory imbued with holy energy. It uses 2 hair accessory slots.', 'Accessary_angel_circlet_i00', 0);
