INSERT INTO `all_items` VALUES (8936, 'Santa\'s Antlers', NULL, 'Праздничная шапка Деда Мороза рогами. Идеально подходит для празднований. Действует только до конца события.', 'Festive Santa hat with antlers. Ideal for celebrating the holidays. This item can only be equipped during the year end.', 'accessory_santas_antler_i00', 0);
INSERT INTO `all_items` VALUES (8937, 'Shadow Item: Stormbringer', NULL, 'Теневой предмет заключает в себе отраженную мощь Громовержца. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item contains the mirrored power of a Stormbringer. It cannot be traded, dropped or given other functions.', 'time_weapon_dual_sword_i00', 2);
INSERT INTO `all_items` VALUES (8938, 'Damascus * Tallum Blade', NULL, 'При модификации Физ. Атк. парных мечей возрастет больше, чем для одноручного оружия или кастетов. При модификации на +4 и выше Скор. Атк. Возрастет на 8%. Наносит дополнительный урон цели в PvP.', 'When enchanted, the P.Atk. of a dualsword will increase more significantly than that of a one-handed or fist weapon. When enchanted by 4 or more, Atk. Spd. will increase by 8%. Inflicts additional damage to target during PvP.', 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (8939, 'Dominic\'s Mark', NULL, 'Метка Доминика. Используется в тайной миссии.', 'Dominic\'s Mark. Used in carrying out a secret mission.', 'etc_leash_i00', 0);
INSERT INTO `all_items` VALUES (8940, 'Mark of the Future: Human', NULL, 'Знак Будущего. Получен у Великого Мастера Клауса из Орена.', 'Mark of the Future. Received from Grandmaster Klaus Blackbird of Oren Castle Town.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (8941, 'Mark of the Future: Dwarf', NULL, 'Метка Будущего. Получена от Начальника Склада Алдера в Городе Шутгарт.', 'Mark of the Future. Received from Warehouse Chief Alder of Schuttgart Castle Town.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (8942, 'Mark of the Future: Elf', NULL, 'Метка Будущего. Получена от Магистра Юриса в Городе Гиран.', 'Mark of the Future. Received from Magister Juris of Giran Castle Town.', 'etc_jewel_silver_i00', 0);
