INSERT INTO `all_items` VALUES (8945, 'Spellbook: Celestial Shield', NULL, 'Книга, необходимая для изучения умения \"Небесный Щит\". Профессия: Епископ.Необходимый уровень: 64.', 'Spellbook needed to learn Celestial Shield. Can be used by a Bishop.', 'etc_spell_books_assistance_i00', 0);
