INSERT INTO `all_items` VALUES (8954, 'Blue Primeval Crystal', NULL, 'Увеличивает SP на 50000 при использовании. Может использоваться только персонажами уровня 76 или выше.', 'Increases SP by 50000 when used. Can only be used by characters level 76 or higher.', 'etc_sp_crystal_i00', 1);
INSERT INTO `all_items` VALUES (8955, 'Green Primeval Crystal', NULL, 'Увеличивает SP на 100000 при использовании. Может использоваться только персонажами уровня 76 или выше.', 'Increases SP by 100000 when used. Can only be used by characters level 76 or higher.', 'etc_sp_crystal_i02', 1);
