INSERT INTO `all_items` VALUES (8957, 'Attack Orders', NULL, 'Фантастический свиток ивента Бегство. Хранитель Портала может обменять его на Теневой Предмет, соответствующий вашему уровню.', 'Call to Arms event item.  Can be exchanged through Strategist Lucien for a Shadow Item suitable to your level.', 'etc_lottery_card_i00', 0);
