INSERT INTO `all_items` VALUES (8960, 'No Grade Shadow Armor Set Box', NULL, 'Щелкните по коробке дважды и сможете получить Теневой Комплект Брони без ранга. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 60% и имеете минимум 20 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a No Grade Shadow Armor Set. (This item can be used when the weight gauge is below 60% and 20 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
