INSERT INTO `all_items` VALUES (8971, 'A-/ S- Grade Item Set Box (Warrior Use)', NULL, 'Щелкните по коробке дважды и сможете получить Боевой Предмет Ранга S. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Fighter-Use A- or S-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
