INSERT INTO `all_items` VALUES (9127, 'High A-Grade Shadow Armor Set Box (Robe)', NULL, 'Щелкнув по предмету дважды, вы получите Комплект Теневого Магического Доспеха Ранга S. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 60% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a high A-Grade Shadow Armor \"Robe Use\" Set. (This item can be used when the weight gauge is below 60% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9128, 'Shadow Item: Mithril Gauntlet', NULL, 'Теневой предмет содержит в себе отраженную мощь Мифриловых Рукавиц. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item contains the mirrored power of Mithril Gauntlets. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t61_g_i00', 0);
INSERT INTO `all_items` VALUES (9129, 'Shadow Item: Shield of Nightmare', NULL, 'Теневой предмет заключает в себе отраженную мощь Щита Кошмаров. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item contains the mirrored power of a Shield of Nightmare. It cannot be traded, dropped, crystallized, or given other functions.', 'shield_shield_of_nightmare_i00', 4);
INSERT INTO `all_items` VALUES (9130, 'No Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет без ранга. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use No Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9131, 'D-Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга D. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use D-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9132, 'C-Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга C. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use C-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9133, 'B-Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга B. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use B-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9134, 'A-Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга A. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use A-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (9135, 'A-/ S- Grade Item Set Box (Magic Use)', NULL, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга S. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'If you double-click on it, you can obtain a Magic-Use A- or S-Grade Item. (This item can be used when the weight gauge is below 80% and 10 or more empty slots are available in your inventory.)', 'etc_box_of_adventure_1_i00', 0);
