INSERT INTO `all_items` VALUES (9138, 'Santa\'s Hat', NULL, 'Праздничная шапка Деда Мороза. Действует только до конца события. Требует две ячейки головных уборов.', 'A Santa Claus hat that was created to celebrate the holidays. This hat can only be worn during the end-of-year holiday season. It uses 2 hair accessory slots.', 'accessory_santas_cap_i00', 0);
INSERT INTO `all_items` VALUES (9139, 'Santa\'s Hat', NULL, 'Праздничная шапка Деда Мороза. Действует только до конца события.', 'A Santa Claus hat that was created to celebrate the holidays.  This hat can only be worn only during the end of year holiday season.', 'accessory_santas_cap_i00', 0);
INSERT INTO `all_items` VALUES (9140, 'Salvation Bow', NULL, 'Послать сердечко с любовью. Позволяет использовать активное умение Счастье. Предупреждение: если использовать это умение на монстра, он нападет на вас.', 'Zaken\'s Curse event souvenir item.  Allows you to use the active skill Happiness.  Warning: If you use this skill against a monster, it will flag you for PvP.', 'weapon_krono_bow_i00', 0);
INSERT INTO `all_items` VALUES (9141, 'Redemption Bow', NULL, 'Предмет ивента. Послать сердечко с любовью выбранному мутанту. Позволяет использовать Активные умения Выстрел в Сердце и Двойное Выстрел в Сердце.', 'Zaken\'s Curse event item.  Enables you to free cursed pigs.  Allows you to use the active skills Forgiveness and Pardon.', 'weapon_krono_bow_i00', 0);
INSERT INTO `all_items` VALUES (9142, 'Apiga', NULL, 'Деньги проклятых созданий. Отдайте их в магическую лабораторию за вознаграждение.', 'A coin received upon completion of one of the events0', 'etc_pig_adena_i01', 0);
INSERT INTO `all_items` VALUES (9143, 'Donate coin', NULL, 'Редкие деньги проклятых созданий. В зависимости от их количества вы можете попытать счастья в лотерее. Нельзя обменять/выбросить.', 'A mysterious coin that is prized by merchants0', 'etc_pig_adena_i00', 0);
INSERT INTO `all_items` VALUES (9144, 'Pirate\'s Booty', NULL, 'Щелкнув по предмету дважды, вы получите шанс приобрести Золотую Апигу. Если вам не повезет, то вы не получите ничего. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'Double-clicking the item gives you a chance to acquire a Golden Apiga. If you\'re unlucky, you will receive nothing. (This item can only be used if you are loaded at no more than 80% and have at least 10 free inventory slots.)', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (9145, 'Little Angel Wings (Event)', NULL, 'Головной аксессуар в виде маленького белого крыла. Изготовлен специально для ивента, Нельзя обменять/выбросить.', 'Head accessory in the shape of a small white wing. Made specifically for the event. Cannot be traded/discarded.', 'accessory_hair_ring_i00', 0);
INSERT INTO `all_items` VALUES (9146, 'Scroll of Guidance (Event)', NULL, 'Увеличивает Точность. Вознаграждение за ивент.', 'Increases Accuracy. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9147, 'Scroll of Death Whisper (Event)', NULL, 'Увеличивает силу Крит. Атк.. Вознаграждение за ивент.', 'Increases Critical Attack Power. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9148, 'Scroll of Focus (Event)', NULL, 'Увеличивает Шанс Крит. Уд. Вознаграждение за ивент.', 'Increases Critical Hit Chance. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9149, 'Scroll of Acumen (Event)', NULL, 'Увеличивает Скор. Маг. Вознаграждение за ивент.', 'Increases Magic Speed. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9150, 'Scroll of Haste (Event)', NULL, 'Увеличивает Скор. Атк. Вознаграждение за ивент.', 'Increases Attack Speed. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9151, 'Scroll of Agility (Event)', NULL, 'Увеличивает Уклонение. Вознаграждение за ивент.', 'Increases Evasion. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9152, 'Scroll of Empower (Event)', NULL, 'Увеличивает Маг. Атк. Вознаграждение за ивент.', 'Increases Magic Attack. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9153, 'Scroll of Might (Event)', NULL, 'Увеличивает Силу Атаки. Вознаграждение за ивент.', 'Increases Attack Power. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9154, 'Scroll of Wind Walk (Event)', NULL, 'Увеличивает Скорость. Вознаграждение за ивент.', 'Increases Speed. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9155, 'Scroll of Shield (Event)', NULL, 'Увеличивает Защиту. Вознаграждение за ивент.', 'Increases Defense. Event reward.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (9156, 'Blessed Scroll of Escape Event', NULL, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение. Награда за ивент.', 'Magic scroll that allows you to teleport to the nearest settlement. Event reward.', 'etc_scroll_of_return_i01', 1);
INSERT INTO `all_items` VALUES (9157, 'Blessed Scroll of Resurrection Event', NULL, 'Магический свиток, воскрешающий мертвого персонажа с полным восстановлением очков опыта. Вознаграждение за ивент.', 'Magic scroll that resurrects a dead character with full experience points restored. Event reward.', 'etc_scroll_of_resurrection_i01', 1);
INSERT INTO `all_items` VALUES (9158, 'Gold Circlet of Redemption', NULL, 'Золотая диадема. Требует две ячейки головных уборов. Предмет ивента.', 'Golden diadem. Requires two headgear slots. Event item.', 'Accessary_gold_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9159, 'Silver Circlet of Salvation', NULL, 'Серебряная диадема. Требует две ячейки головных уборов. Предмет ивента.', 'Silver diadem. Requires two headgear slots. Event item.', 'Accessary_gold_circlet_i01', 0);
INSERT INTO `all_items` VALUES (9160, 'Pig Wrangler\'s Cap', NULL, 'Кожаная шляпа. Требует две ячейки головных уборов. Предмет ивента.', 'Leather hat. Requires two headgear slots. Event item.', 'Accessary_middle_ages_i00', 0);
INSERT INTO `all_items` VALUES (9161, 'Santa\'s Antlers', NULL, 'Праздничная шапка Деда Мороза с рогами. Идеально подходит для празднований. Действует только до конца события.', 'Festive Santa hat with horns. Perfect for celebrations. Only active until the end of the event.', 'accessory_santas_antler_i00', 0);
INSERT INTO `all_items` VALUES (9162, 'Red Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Красный Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the Red Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
INSERT INTO `all_items` VALUES (9163, 'Blue Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Синий Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the Blue Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
INSERT INTO `all_items` VALUES (9164, 'Orange Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Оранжевый Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the Orange Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
INSERT INTO `all_items` VALUES (9165, 'Black Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Черный Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the Black Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
INSERT INTO `all_items` VALUES (9166, 'White Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Белый Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the White Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
INSERT INTO `all_items` VALUES (9167, 'Green Philosopher\'s Stone Transmutation Circle', NULL, 'Доступно любой расе. Двойной щелчок добавит в вашу книгу рецептов Зеленый Философский Камень Цикла Перевоплощения. Требует умения Создать предмет 1 уровня. Шанс успеха 100%.', 'Available to any race. Double-clicking will add the Green Philosopher\'s Stone of the Reincarnation Cycle to your recipe book. Requires level 1 crafting skill. Success chance 100%.', 'etc_sign_i00', 5);
