INSERT INTO `all_items` VALUES (9177, 'Shadow Item - Teddy Bear Hat', 'Resurrection', 'Забавный теневой головной аксессуар, выполненный в форме медвежонка. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'A fun shadow head accessory shaped like a bear. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_bear_cap_i00', 0);
INSERT INTO `all_items` VALUES (9178, 'Shadow Item - Piggy Hat', 'Resurrection', 'Забавный теневой головной аксессуар, выполненный в форме хрюшки. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'A fun shadow head accessory shaped like a pig. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_pig_cap_i00', 0);
INSERT INTO `all_items` VALUES (9179, 'Shadow Item - Jester Hat', 'Resurrection', 'Праздничный теневой колпак шута с двумя верхушками. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'Festive shadow jester hat with two peaks. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_jester_cap_i00', 0);
INSERT INTO `all_items` VALUES (9180, 'Shadow Item - Wizard Hat', 'Resurrection', 'Теневая широкополая шляпа чародея. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'Shadow wide-brimmed wizard hat. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_magic_cap_i00', 0);
INSERT INTO `all_items` VALUES (9181, 'Shadow Item - Dapper Cap', 'Resurrection', 'Теневая кепка с козырьком. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'Shadow cap with a visor. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_dandy_cap_i00', 0);
INSERT INTO `all_items` VALUES (9182, 'Shadow Item - Romantic Chapeau', 'Resurrection', 'Теневая модная шляпа. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'Shadow fashionable hat. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_romantic_chaperon_i00', 0);
INSERT INTO `all_items` VALUES (9183, 'Shadow Item - Iron Circlet', 'Resurrection', 'Теневой железный головной аксессуар. Требует две ячейки головных уборов. Это ивентовый предмет с магическим эффектом. Нельзя обменять, выбросить, продать.', 'Shadow iron head accessory. Requires two headgear slots. This is an event item with a magical effect. Cannot be traded, discarded, or sold.', 'accessory_iron_circlet_i00', 0);
