INSERT INTO `all_items` VALUES (9206, 'Greater Healing Potion (Event)', NULL, 'Магическое зелье, быстро восстанавливающее HP. Эффект длится 15 секунд. Только для ивента.', 'A magical potion that quickly restores HP. Effect lasts for 15 seconds. Event only.', 'etc_reagent_white_i00', 3);
