INSERT INTO `all_items` VALUES (9228, 'Soldat Estoc', NULL, 'Эксклюзивное оружие Камаэль: Конверсия ГромовержцаДает возможность получить одно из следующих особых свойств: Крит. Ярость, Фокусировка или Легкость.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: StormBringer ConversionnBestows one of the following functions--Critical Anger, Focus, or Light.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9229, 'Soldat Estoc', 'Critical Anger', 'Эксклюзивное оружие Камаэль: Конверсия Громовержца<Свойство Кристалла Души>Уменьшает HP на 12 и увеличивает Физ. Атк. на 248 при Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Anger	Kamael-exclusive Weapon: StormBringer Conversion<Soul Crystal Enhancement>nDecreases HP by 12. Increases P. Atk. by 248 during a Critical Attack.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9230, 'Soldat Estoc', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Громовержца<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 86.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Thunderbreaker. <Soul Crystal Property> Increases Critical Attack Chance by 86. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9231, 'Soldat Estoc', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Громовержца<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Light	Kamael-exclusive Weapon: StormBringer Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9232, 'Schlager', NULL, 'Эксклюзивное оружие Камаэль: Конверсия ФламбергаДает возможность получить одно из следующих особых свойств: Крит. Урон, Фокусировка или Легкость.', 'Kamael-exclusive Weapon: Flamberge ConversionnBestows one of the following functions: P. Critical Damage, Focus, or Light.', 'weapon_schlaeger_i00', 2);
INSERT INTO `all_items` VALUES (9233, 'Schlager', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Конверсия Фламберга<Свойство Кристалла Души>Увеличивает Физ. Атк. на 174 при Крит. Атк.', 'Critical Damage	Kamael-exclusive Weapon: Flamberge Conversionn<Soul Crystal Enhancement>nIncreases P. Atk. by 174 during a Critical Attack.', 'weapon_schlaeger_i01', 2);
INSERT INTO `all_items` VALUES (9234, 'Schlager', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Фламберга<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 86.', 'Focus	Kamael-exclusive Weapon: Flamberge Conversionn<Soul Crystal Enhancement>nIncreases Critical by 86.', 'weapon_schlaeger_i01', 2);
INSERT INTO `all_items` VALUES (9235, 'Schlager', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Фламберга<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%.', 'Light	Kamael-exclusive Weapon: Flamberge Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%.', 'weapon_schlaeger_i01', 2);
INSERT INTO `all_items` VALUES (9236, 'Arbalest', NULL, 'Эксклюзивное оружие Камаэль: Ледяной Лук\\\\Дает возможность получить одно из следующих особых свойств: Наведение, Уклонение или Быстрое Восстановление.', 'Kamael-exclusive Weapon: Crystallized Ice BowBestows one of the following functions: Guidance, Evasion, or Quick Recovery.', 'weapon_arbalest_i00', 2);
INSERT INTO `all_items` VALUES (9237, 'Arbalest', 'Guidance', 'Эксклюзивное оружие Камаэль: Конверсия Ледяного Лука<Свойство Кристалла Души>Увеличивает Точность на 5.', 'Guidance	Kamael-exclusive Weapon: Crystallized Ice Bow Conversionn<Soul Crystal Enhancement>nIncreases Accuracy by 5.', 'weapon_arbalest_i01', 2);
INSERT INTO `all_items` VALUES (9238, 'Arbalest', 'Evasion', 'Эксклюзивное оружие Камаэль: Конверсия Ледяного Лука<Свойство Кристалла Души>Увеличивает Уклонение на 2.', 'Evasion	Kamael-exclusive Weapon: Crystallized Ice Bow Conversionn<Soul Crystal Enhancement>nIncreases Evasion by 2.', 'weapon_arbalest_i01', 2);
INSERT INTO `all_items` VALUES (9239, 'Arbalest', 'Quick Recovery', 'Эксклюзивное оружие Камаэль: Кристальный Лук Льда<Свойство Кристалла Души>Понижает время перезарядки приблизительно на 17%.', 'Quick Recovery	Kamael-exclusive Weapon: Crystallized Iced Bown<Soul Crystal Enhancement>nDecreases cooldown by about 17%.', 'weapon_arbalest_i01', 2);
INSERT INTO `all_items` VALUES (9240, 'Chevalier Rapier', NULL, 'Эксклюзивное оружие Камаэль: ШамширДает возможность получить одно из следующих особых свойств: Наведение, Удар в Спину или Риск. Уклонение.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Shamshir. Gives a chance to receive one of the following special properties: Targeting, Backstab, or Risk. Evasion. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9241, 'Chevalier Rapier', 'Guidance', 'Эксклюзивное оружие Камаэль: Шамшир<Свойство Кристалла Души>Увеличивает Точность на 6.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Guidance	Kamael-exclusive Weapon: Shamshirn<Soul Crystal Enhancement>nIncreases Accuracy by 6.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9242, 'Chevalier Rapier', 'Back Blow', 'Эксклюзивное оружие Камаэль: Шамшир<Свойство Кристалла Души>Увеличивает Шанс. Крит. Уд. на 67 при атаке цели со спины.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Back Blow	Kamael-exclusive Weapon: Shamshirn<Soul Crystal Enhancement>nIncreases P. Critical Rate by 56 when attacking the target from behind.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9243, 'Chevalier Rapier', 'Rsk. Evasion', 'Эксклюзивное оружие Камаэль: Шамшир<Свойство Кристалла Души>Увеличивает Уклонение на 7 при HP 60% или ниже.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rsk. Evasion	Kamael-exclusive Weapon: Shamshirn<Soul Crystal Enhancement>nIncreases Evasion by 7 when HP drops to 6% or below.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9244, 'Chevalier Rapier', NULL, 'Эксклюзивное оружие Камаэль: КатанаДает возможность получить одно из следующих особых свойств:Фокусировка, Крит. Урон или Ускорение.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: KatananBestows one of the following functions--Focus, P. Critical Damage, or Haste.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9245, 'Chevalier Rapier', 'Focus', 'Эксклюзивное оружие Камаэль: Катана<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 82.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Focus	Kamael-exclusive Weapon: Katanan<Soul Crystal Enhancement>nIncreases Critical by 82.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9246, 'Chevalier Rapier', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Катана<Свойство Кристалла Души>Увеличивает Физ. Атк. на 194 при Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Damage	Kamael-exclusive Weapon: Katanan<Soul Crystal Enhancement>nIncreases P. Atk. by 194 during a Critical Attack.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9247, 'Chevalier Rapier', 'Haste', 'Эксклюзивное оружие Камаэль: Катана<Свойство Кристалла Души>Увеличивает Скор. Атк. приблизительно на 7%.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Haste	Kamael-exclusive Weapon: Katanan<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 7%.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9248, 'Chevalier Rapier', NULL, 'Эксклюзивное оружие Камаэль: Меч ДуховДает возможность получить одно из следующих особых свойств:Крит. Урон, Крит. Отравление или Ускорение.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: Spirit SwordnBestows one of the following functions--P. Critical Damage, Critical Poison, or Haste.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9249, 'Chevalier Rapier', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Меч Духов<Свойство Кристалла Души>Увеличивает Физ. Атк. на 194 при Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Damage	Kamael-exclusive Weapon: Spirit Swordn<Soul Crystal Enhancement>nIncreases P. Atk. by 194 during a Critical Attack.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9250, 'Chevalier Rapier', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Меч Духов<Свойство Кристалла Души>Отравляет цель c 15% вероятностью при обычной Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Spirit Sword. <Soul Crystal Property> Poisons the target with a 15% chance on normal Critical Attack. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9251, 'Chevalier Rapier', 'Haste', 'Эксклюзивное оружие Камаэль: Меч Духов<Свойство Кристалла Души>Увеличивает Скор. Атк. приблизительно на 7%.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Haste	Kamael-exclusive Weapon: Spirit Swordn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 7%.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9252, 'Chevalier Rapier', NULL, 'Эксклюзивное оружие Камаэль: Меч НалетчикаДает возможность получить одно из следующих особых свойств:Фокусировка, Крит. Поглощение HP или Крит. Отравление.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: Raid SwordnBestows one of the following functions--Focus, Critical Drain, or Critical Poison.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9253, 'Chevalier Rapier', 'Focus', 'Эксклюзивное оружие Камаэль: Меч Налетчика<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 82.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Focus	Kamael-exclusive Weapon: Raid Swordn<Soul Crystal Enhancement>nIncreases Critical by 82.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9254, 'Chevalier Rapier', 'Critical Drain', 'Эксклюзивное оружие Камаэль: Меч Налетчика<Свойство Кристалла Души>Поглощает HP цели на 9 при Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Drain	Kamael-exclusive Weapon: Raid Swordn<Soul Crystal Enhancement>nAbsorbs 9 HP from the target during a Critical Attack.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9255, 'Chevalier Rapier', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Меч Налетчика<Свойство Кристалла Души>Отравляет цель c 15% вероятностью при обычной Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Poison	Kamael-exclusive Weapon: Raid Swordn<Soul Crystal Enhancement>nInflicts Poison on the target with a 15% chance during an ordinary Critical Attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_soldat_estoc_i01', 2);
INSERT INTO `all_items` VALUES (9256, 'Ballista', NULL, 'Эксклюзивное оружие Камаэль: Лук СтихииДает возможность получить одно из следующих особых свойств: Наведение, Скупость или Быстрое Восстановление.', 'Kamael-exclusive Weapon: Elemental BownBestows one of the following functions: Guidance, Miser, or Quick Recovery.', 'weapon_arbalest_i00', 2);
INSERT INTO `all_items` VALUES (9257, 'Ballista', 'Guidance', 'Эксклюзивное оружие Камаэль: Лук Стихии<Свойство Кристалла Души>Увеличивает Точность на 5.', 'Guidance	Kamael-exclusive Weapon: Elemental Bown<Soul Crystal Enhancement>nIncreases Accuracy by 5.', 'weapon_arbalest_i01', 2);
INSERT INTO `all_items` VALUES (9258, 'Ballista', 'Miser', 'Эксклюзивное оружие Камаэль: Лук Стихии<Свойство Кристалла Души>Дает 40% вероятности, что количество поглощенных зарядов души упадет до 4.', 'Miser	Kamael-exclusive Weapon: Elemental Bown<Soul Crystal Enhancement>nThere is a 4% chance that the number of soulshots consumed is reduced to 4.', 'weapon_arbalest_i01', 2);
INSERT INTO `all_items` VALUES (9259, 'Ballista', 'Quick Recovery', 'Эксклюзивное оружие Камаэль: Лук Стихии<Свойство Кристалла Души>Понижает время перезарядки приблизительно на 20%.', 'Quick Recovery	Kamael-exclusive Weapon: Elemental Bown<Soul Crystal Enhancement>nDecreases cooldown by about 2%.', 'weapon_arbalest_i01', 2);
