INSERT INTO `all_items` VALUES (9304, 'Military Fleuret', NULL, 'Эксклюзивное оружие Камаэль: КешанберкДает возможность получить одно из следующих особых свойств:Наведение, Фокусировка или Удар в Спину.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Keshanberk. Gives a chance to receive one of the following special properties: Targeting, Focus, or Backstab. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_assult_fleuret_i00', 3);
INSERT INTO `all_items` VALUES (9305, 'Military Fleuret', 'Guidance', 'Эксклюзивное оружие Камаэль: Кешанберк<Свойство Кристалла Души>Увеличивает Точность на 5.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Keshanberk. <Soul Crystal Property> Increases Accuracy by 5. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_assult_fleuret_i01', 3);
INSERT INTO `all_items` VALUES (9306, 'Military Fleuret', 'Focus', 'Эксклюзивное оружие Камаэль: Кешанберк<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 68.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Keshanberk. <Soul Crystal Property> Increases Critical Attack Chance by 68. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_assult_fleuret_i01', 3);
INSERT INTO `all_items` VALUES (9307, 'Military Fleuret', 'Back Blow', 'Эксклюзивное оружие Камаэль: Кешанберк<Свойство Кристалла Души>Увеличивает Шанс. Крит. Уд. на 56 при атаке цели со спины.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Keshanberk. <Soul Crystal Property> Increases Critical Hit Chance by 56 when attacking the target from behind. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_assult_fleuret_i01', 3);
INSERT INTO `all_items` VALUES (9308, 'Innominate Victory', NULL, 'Эксклюзивное оружие Камаэль: Большой МечДает возможность получить одно из следующих особых свойств: Здоровье, Крит. Урон или Фокусировка.', 'Exclusive weapon for Kamal: Great Sword. Gives a chance to receive one of the following special properties: Health, Critical Damage, or Focus.', 'weapon_nameless_victory_i00', 3);
INSERT INTO `all_items` VALUES (9309, 'Innominate Victory', 'Health', 'Эксклюзивное оружие Камаэль: Большой Меч<Свойство Кристалла Души>Увеличивает Макс. HP на 25%.', 'Exclusive weapon for Kamal: Great Sword. <Soul Crystal Property> Increases Max HP by 25%.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (9310, 'Innominate Victory', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Большой Меч<Свойство Кристалла Души>Увеличивает Физ. Атк. на 247 при Крит. Атк.', 'Exclusive weapon for Kamal: Great Sword. <Soul Crystal Property> Increases Physical Attack by 247 on Critical Attack.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (9311, 'Innominate Victory', 'Focus', 'Эксклюзивное оружие Камаэль: Большой Меч<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 68.', 'Focus	Kamael-exclusive Weapon: Great Swordn<Soul Crystal Enhancement>nIncreases Critical by 68.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (9312, 'Peacemaker', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Длинного Лука Темных ЭльфовДает возможность получить одно из следующих особых свойств: Уклонение, Крит. Кровопускание или Скупость.', 'Kamael-exclusive Weapon: Dark Elven Long Bow ConversionnBestows one of the following functions: Evasion, Critical Bleed, or Miser.', 'weapon_peace_maker_i00', 3);
INSERT INTO `all_items` VALUES (9313, 'Peacemaker', 'Evasion', 'Эксклюзивное оружие Камаэль: Конверсия Длинного Лука Темных Эльфов<Свойство Кристалла Души>Увеличивает Уклонение на 2.', 'Evasion	Kamael-exclusive Weapon: Dark Elven Long Bow Conversionn<Soul Crystal Enhancement>nIncreases Evasion by 2.', 'weapon_peace_maker_i01', 3);
INSERT INTO `all_items` VALUES (9314, 'Peacemaker', 'Critical Bleed', 'Эксклюзивное оружие Камаэль: Конверсия Длинного Лука Темных Эльфов<Свойство Кристалла Души>Дает 41% шанс вызвать кровотечение цели при Крит. Атк.', 'Critical Bleed	Kamael-exclusive Weapon: Dark Elven Long Bow Conversionn<Soul Crystal Enhancement>nHas a 41% chance of casting Bleed on the target during a standard Critical Attack.', 'weapon_peace_maker_i01', 3);
INSERT INTO `all_items` VALUES (9315, 'Peacemaker', 'Miser', 'Эксклюзивное оружие Камаэль: Конверсия Длинного Лука Темных Эльфов<Свойство Кристалла Души>Дает 19% вероятности, что количество поглощенных зарядов души упадет до 1.', 'Miser	Kamael-exclusive Weapon: Dark Elven Long Bow Conversionn<Soul Crystal Enhancement>nThere is a 19% chance that the number of soulshots consumed is reduced to 1.', 'weapon_peace_maker_i01', 3);
INSERT INTO `all_items` VALUES (9316, 'Colichemarde', NULL, 'Эксклюзивное оружие Камаэль: Конверсия ДамаскусаДает возможность получить одно из следующих особых свойств:Фокусировка, Крит. Урон или Ускорение.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: Sword of Damascus ConversionnBestows one of the following functions--Focus, P. Critical Damage, or Haste.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_colichemarde_i00', 3);
INSERT INTO `all_items` VALUES (9317, 'Colichemarde', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Дамаскуса<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 64.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Focus	Kamael-exclusive Weapon: Sword of Damascus Conversionn<Soul Crystal Enhancement>nIncreases Critical by 64.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_colichemarde_i01', 3);
INSERT INTO `all_items` VALUES (9318, 'Colichemarde', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Конверсия Дамаскуса<Свойство Кристалла Души>Увеличивает Физ. Атк. на 262 при Крит. Атк.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Damage	Kamael-exclusive Weapon: Sword of Damascus Conversionn<Soul Crystal Enhancement>nIncreases P. Atk. by 262 during a Critical Attack.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_colichemarde_i01', 3);
INSERT INTO `all_items` VALUES (9319, 'Colichemarde', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Дамаскуса<Свойство Кристалла Души>Увеличивает Скор. Атк. приблизительно на 6%.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Haste	Kamael-exclusive Weapon: Sword of Damascus Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 6%.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_colichemarde_i01', 3);
INSERT INTO `all_items` VALUES (9320, 'Dismantler', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Меча СтражаДает возможность получить одно из следующих особых свойств: Крит. Поглощение HP, Здоровье или Крит. Кровопускание.', 'Exclusive weapon for Kamal: Guardian Sword Conversion. Gives a chance to receive one of the following special properties: Critical HP Absorption, Health, or Critical Bleeding.', 'weapon_dismantler_i00', 3);
INSERT INTO `all_items` VALUES (9321, 'Dismantler', 'Critical Drain', 'Эксклюзивное оружие Камаэль: Конверсия Меча Стража<Свойство Кристалла Души>Позволяет поглотить 8 HP цели при Крит. Атк.', 'Critical Drain	Kamael-exclusive Weapon: Guardian Sword Conversionn<Soul Crystal Enhancement>nThe user absorbs 8 HP from the target during a Critical Attack.', 'weapon_dismantler_i01', 3);
INSERT INTO `all_items` VALUES (9322, 'Dismantler', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Стража<Свойство Кристалла Души>Увеличивает Макс. HP на 25%.', 'Health	Kamael-exclusive Weapon: Guardian Sword Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%.', 'weapon_dismantler_i01', 3);
INSERT INTO `all_items` VALUES (9323, 'Dismantler', 'Critical Bleed', 'Эксклюзивное оружие Камаэль: Конверсия Меча Стража<Свойство Кристалла Души>Дает 24% шанс вызвать кровотечение цели при Крит. Атк.', 'Critical Bleed	Kamael-exclusive Weapon: Guardian Sword Conversionn<Soul Crystal Enhancement>nHas a 41% chance of casting Bleed on the target during a standard Critical Attack.', 'weapon_dismantler_i01', 3);
INSERT INTO `all_items` VALUES (9324, 'Hell Hound', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Лука УгрозыДает возможность получить одно из следующих особых свойств: Наведение, Быстрое Восстановление или Экономия.', 'Kamael-exclusive Weapon: Bow of Peril ConversionnBestows one of the following functions: Guidance, Quick Recover, or Cheap Shot.', 'weapon_hell_hound_i00', 3);
INSERT INTO `all_items` VALUES (9325, 'Hell Hound', 'Guidance', 'Эксклюзивное оружие Камаэль: Конверсия Лука Угрозы<Свойство Кристалла Души>Увеличивает Точность на 3.', 'Guidance	Kamael-exclusive Weapon: Bow of Peril Conversionn<Soul Crystal Enhancement>nIncreases Accuracy by 3.', 'weapon_hell_hound_i01', 3);
INSERT INTO `all_items` VALUES (9326, 'Hell Hound', 'Quick Recovery', 'Эксклюзивное оружие Камаэль: Конверсия Лука Угрозы<Свойство Кристалла Души>Понижает время перезарядки приблизительно на 13%.', 'Quick Recovery	Kamael-exclusive Weapon: Bow of Peril Conversionn<Soul Crystal Enhancement>nDecreases cooldown by about 13%.', 'weapon_hell_hound_i01', 3);
INSERT INTO `all_items` VALUES (9327, 'Hell Hound', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Угрозы<Свойство Кристалла Души>Понижает расход MP на 12% при использовании умения.', 'Cheap Shot	Kamael-exclusive Weapon: Bow of Peril Conversionn<Soul Crystal Enhancement>nDecreased MP consumption by 12% during use of skill.', 'weapon_hell_hound_i01', 3);
INSERT INTO `all_items` VALUES (9328, 'White Lightning', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Клинка ТаллумаДает возможность получить одно из следующих особых свойств: Крит. Отравление, Ускорение или Ярость.При модификации на +4 и выше при Крит. Атк. увеличивает Физ. Атк., силу магии дает шанс лечения всех членов группы, включая вас; уменьшает расход MP при использовании умения.', 'Kamael-exclusive Weapon: Tallum Blade ConversionnBestows one of the following functions--Critical Poison, Haste, or Anger.nWhen enchanted to 4 or more, P. Atk., magical power, and received healing of all party members, including yourself, are increased during a Critical Attack with a certain chance, and MP consumption during skill use is decreased', 'weapon_lightning_blaze_i00', 4);
INSERT INTO `all_items` VALUES (9329, 'White Lightning', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума<Свойство Кристалла Души>Отравляет цель с 10% шансом Крит. Атк. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Poison	Kamael-exclusive Weapon: Tallum Blade Conversionn<Soul Crystal Enhancement>nPoisons the target with a 1% chance during a standard Critical Attack. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_lightning_blaze_i01', 4);
INSERT INTO `all_items` VALUES (9330, 'White Lightning', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума<Свойство Кристалла Души>Увеличивает Скор. Атк. приблизительно на 6%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Exclusive weapon for Kamal: Talum Blade Conversion. <Soul Crystal Property> Increases Attack Speed by approximately 6%. Deals additional damage in PvP. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magic Attack, and healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'weapon_lightning_blaze_i01', 4);
INSERT INTO `all_items` VALUES (9331, 'White Lightning', 'Anger', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума<Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 31. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Anger	Kamael-exclusive Weapon: Tallum Blade Conversionn<Soul Crystal Enhancement>nIncreases P. Atk. by 31 and decreases Max HP by 15%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_lightning_blaze_i01', 4);
INSERT INTO `all_items` VALUES (9332, 'Divine Pain', NULL, 'Эксклюзивное оружие Камаэль: Конверсия мастера ИнферноДает возможность получить одно из следующих особых свойств: Ускорение, Крит. Урон или Фокусировка.', 'Kamael-exclusive Weapon: Infernal Master ConversionnBestows one of the following functions: Haste, P. Critical Damage, or Focus.', 'weapon_pain_of_godness_i00', 4);
INSERT INTO `all_items` VALUES (9333, 'Divine Pain', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия мастера Инферно<Свойство Кристалла Души>Увеличивает Скор. Атк. приблизительно на 6%. Наносит повышенный урон в PvP.', 'Haste	Kamael-exclusive Weapon: Infernal Master Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP.', 'weapon_pain_of_godness_i01', 4);
INSERT INTO `all_items` VALUES (9334, 'Divine Pain', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Конверсия мастера Инферно<Свойство Кристалла Души>Увеличивает Физ. Атк. на 297 при Крит. Атк. Наносит повышенный урон в PvP.', 'Critical Damage	Kamael-exclusive Weapon: Infernal Master Conversionn<Soul Crystal Enhancement>nIncreases P. Atk. by 297 during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_pain_of_godness_i01', 4);
INSERT INTO `all_items` VALUES (9335, 'Divine Pain', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия мастера Инферно<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит повышенный урон в PvP.', 'Focus	Kamael-exclusive Weapon: Infernal Master Conversionn<Soul Crystal Enhancement>nIncreases Critical by 61. Increases damage inflicted during PvP.', 'weapon_pain_of_godness_i01', 4);
INSERT INTO `all_items` VALUES (9336, 'Doomchanter', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Кровавого ЛукаДает возможность получить одно из следующих особых свойств: Легкость, Крит. Кровопускание или Увеличение Маны.', 'Kamael-exclusive Weapon: Carnage Bow ConversionnBestows one of the following functions: Light, Critical Bleed, or Mana Up.', 'weapon_doom_singer_i00', 4);
INSERT INTO `all_items` VALUES (9337, 'Doomchanter', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Лука Побоища<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Увеличивает повреждение, наносимые в PvP.', 'Light	Kamael-exclusive Weapon: Carnage Bow Conversionn<Soul Crystal Enhancement>nWeight Gauge Increases by 2%. Increases damage inflicted during PvP.', 'weapon_doom_singer_i01', 4);
INSERT INTO `all_items` VALUES (9338, 'Doomchanter', 'Critical Bleed', 'Эксклюзивное оружие Камаэль: Конверсия Кровавого Лука<Свойство Кристалла Души>Дает 35% шанс вызвать кровотечение цели при Крит. Атк. Наносит повышенный урон в PvP.', 'Critical Bleed	Kamael-exclusive Weapon: Carnage Bow Conversionn<Soul Crystal Enhancement>nHas a 35% chance of casting Bleed on the target during a standard Critical Attack. Increases damage inflicted during PvP.', 'weapon_doom_singer_i01', 4);
INSERT INTO `all_items` VALUES (9339, 'Doomchanter', 'Mana Up', 'Эксклюзивное оружие Камаэль: Конверсия Кровавого Лука<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит повышенный урон в PvP.', 'Mana Up	Kamael-exclusive Weapon: Carnage Bow Conversionn<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP.', 'weapon_doom_singer_i01', 4);
