INSERT INTO `all_items` VALUES (9341, 'Lacerator', 'Critical Damage', 'Эксклюзивное оружие Камаэль: Конверсия Темного Легиона<Свойство Кристалла Души>Увеличивает Физ. Атк. на 326 при Крит. Атк. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Damage	Kamael-exclusive Weapon: Dark Legion Conversionn<Soul Crystal Enhancement>nIncreases P. Atk. by 326 during a Critical Attack. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (9342, 'Lacerator', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Темного Легиона<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Health	Kamael-exclusive Weapon: Dark Legion Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (9343, 'Lacerator', 'Rsk. Focus', 'Эксклюзивное оружие Камаэль: Конверсия Темного Легиона<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 130 при HP 60% и ниже. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rsk. Focus	Kamael-exclusive Weapon: Dark Legion Conversionn<Soul Crystal Enhancement>nIncreases Critical by 13 when HP drops to 6% or below. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (9344, 'Undertaker', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Убийцы ДраконовДает возможность получить одно из следующих особых свойств: Здоровье, Крит. Кровопускание или Крит. Поглощение HP.', 'Kamael-exclusive Weapon: Dragon Slayer ConversionnBestows one of the following functions: Health, Critical Bleed, or Critical Drain.', 'weapon_death_bringer_i00', 4);
INSERT INTO `all_items` VALUES (9345, 'Undertaker', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Убийцы Драконов<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит повышенный урон в PvP.', 'Health	Kamael-exclusive Weapon: Dragon Slayer Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.', 'weapon_death_bringer_i01', 4);
INSERT INTO `all_items` VALUES (9346, 'Undertaker', 'Critical Bleed', 'Эксклюзивное оружие Камаэль: Конверсия Убийцы Драконов<Свойство Кристалла Души>Дает 24% шанс вызвать кровотечение цели при Крит. Атк. Наносит повышенный урон в PvP.', 'Critical Bleed	Kamael-exclusive Weapon: Dragon Slayer Conversionn<Soul Crystal Enhancement>nHas a 24% chance of casting Bleed on the target during a standard Critical Attack. Increases damage inflicted during PvP.', 'weapon_death_bringer_i01', 4);
INSERT INTO `all_items` VALUES (9347, 'Undertaker', 'Critical Drain', 'Эксклюзивное оружие Камаэль: Конверсия Убийцы Драконов<Свойство Кристалла Души>Персонаж поглощает 11 HP цели при Крит. Атк. Наносит повышенный урон в PvP.', 'Critical Drain	Kamael-exclusive Weapon: Dragon Slayer Conversionn<Soul Crystal Enhancement>nUser absorbs 11 HP from the target during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_death_bringer_i01', 4);
INSERT INTO `all_items` VALUES (9348, 'Reaper', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Пронзателя ДушДает возможность получить одно из следующих особых свойств: Экономия, Быстрое Восстановление или Крит. Отравление.', 'Kamael-exclusive Weapon: Soul Bow ConversionnBestows one of the following functions: Cheap Shot, Quick Recovery, or Critical Poison.', 'weapon_soul_shooter_i00', 4);
INSERT INTO `all_items` VALUES (9349, 'Reaper', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ<Свойство Кристалла Души>Понижает расход MP на 12% при использовании умения. Наносит повышенный урон в PvP.', 'Cheap Shot	Kamael-exclusive Weapon: Soul Bow Conversionn<Soul Crystal Enhancement>nDecreased MP consumption by 12% during use of skill. Increases damage inflicted during PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (9350, 'Reaper', 'Quick Recovery', 'Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ<Свойство Кристалла Души>Уменьшает время перезарядки приблизительно на 15%. Наносит повышенный урон в PvP.', 'Exclusive weapon for Kamal: Soul Piercer Conversion. <Soul Crystal Property> Reduces cooldown time by approximately 15%. Deals increased damage in PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (9351, 'Reaper', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ<Свойство Кристалла Души>Дает 18% шанс, что цель будет отравлена при Крит. Атк.  Наносит повышенный урон в PvP.', 'Critical Poison	Kamael-exclusive Weapon: Soul Bow Conversionn<Soul Crystal Enhancement>nHas an 18% chance of casting Poison on the target during a standard Critical Attack. Increases damage inflicted during PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (9352, 'Г‰clair Bijou', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Клинка СиррыДает возможность получить одно из следующих особых свойств:Ускорение, Здоровье или Крит. Отравление.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: Sirra\'s Blade ConversionnBestows one of the following functions--Haste, Health, or Critical Poison.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_greed_stinger_i00', 4);
INSERT INTO `all_items` VALUES (9353, 'Г‰clair Bijou', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Увеличивает Скор. Атк. На 6%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Haste	Kamael-exclusive Weapon: Sirra\'s Blade Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_greed_stinger_i01', 4);
