INSERT INTO `all_items` VALUES (9376, 'Dynasty Rapier', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Меча ДинастииДает возможность получить одно из следующих особых свойств:Фокусировка, Здоровье или Легкость.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael-exclusive Weapon: Dynasty Sword ConversionnBestows one of the following functions--Focus, Health, or Light.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_dynasty_rapier_i00', 5);
INSERT INTO `all_items` VALUES (9377, 'Dynasty Rapier', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Focus	Kamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Critical Attack by 111. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (9378, 'Dynasty Rapier', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Health	Kamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, it Has a chance of increasing P. Atk., M. Atk., and healing power, and of decreasing MP consumption for skill use for you and your party members during a Critical Attack.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (9379, 'Dynasty Rapier', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Light	Kamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP. Enchanted to n4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (9380, 'Dynasty Ancient Sword', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Клинка ДинастииДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.', 'Exclusive weapon for Kamal: Dynasty Blade Conversion. Gives a chance to receive one of the following special properties: Focus, Health, or Lightness.', 'weapon_dynasty_ancient_sword_i00', 5);
INSERT INTO `all_items` VALUES (9381, 'Dynasty Ancient Sword', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP.', 'Focus	Kamael-exclusive Weapon: Dynasty Blade Conversionn<Soul Crystal Enhancement>nIncreases Critical Attack by 111. Increases damage inflicted during PvP.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (9382, 'Dynasty Ancient Sword', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит повышенный урон в PvP.', 'Health	Kamael-exclusive Weapon: Dynasty Blade Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (9383, 'Dynasty Ancient Sword', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP.', 'Light	Kamael-exclusive Weapon: Dynasty Blade Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (9384, 'Dynasty Crossbow', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Лука ДинастииДает возможность получить одно из следующих особых свойств: Экономия, Наведение или Фокусировка.', 'Kamael-exclusive Weapon: Dynasty Bow ConversionnBestows one of the following functions: Cheap Shot, Guidance, or Focus.', 'weapon_dynasty_crossbow_i00', 5);
INSERT INTO `all_items` VALUES (9385, 'Dynasty Crossbow', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Понижает расход MP на 12% при использовании умения. Наносит повышенный урон в PvP.', 'Cheap Shot	Kamael-exclusive Weapon: Dynasty Bow Conversionn<Soul Crystal Enhancement>nDecreased MP consumption by 12% during use of skill. Increases damage inflicted during PvP.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (9386, 'Dynasty Crossbow', 'Guidance', 'Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Увеличивает Точность на 5.32. Наносит дополнительный урон в PvP.', 'Guidance	Kamael-exclusive Weapon: Dynasty Bow Conversionn<Soul Crystal Enhancement>nIncreases Accuracy by 5.32. Increases damage inflicted during PvP.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (9387, 'Dynasty Crossbow', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116. Наносит дополнительный урон в PvP.', 'Focus	Kamael-exclusive Weapon: Dynasty Bow Conversionn<Soul Crystal Enhancement>nIncreases Critical Attack by 116. Increases damage inflicted during PvP.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (9388, 'Infinity Rapier', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При Крит. Атк. применяется вредоносное умение, понижающее Физ. Защ. противника, отражает часть урона, увеличивает Макс HP/Макс MP/Макс. CP. Наносит дополнительный урон в PvP.При Крит. Атк. дает шанс увеличить Физ. Атк., Маг. Атк., и мощность лечения, а также уменьшает расход MP для Вас и членов Вашей группы.', 'Divine hero\'s weapon. During a Critical Attack, casts a P. Def.-decreasing de-buff on the target. Also causes damage shield. Increases Max HP/Max MP/Max CP. Adds holy P. Atk. Increases damage inflicted during PvP.nThere is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_infinity_rapier_i00', 5);
INSERT INTO `all_items` VALUES (9389, 'Infinity Sword', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. Увеличивает шанс успеха/мощность Крит. Атк., Макс.HP, Макс.CP, и урон, причиняемый в PvP. Также причиняет дополнительный урон при Крит. Атк., и дает шанс отразить отрицательные эффекты обратно врагу.', 'Divine hero\'s weapon. During a Critical Attack, inflicts additional damage on the target. Also Has a chance of causing skill reflect and increasing Max HP/Max CP and P. Critical Damage/Rate. Adds holy P. Atk. Increases damage inflicted during PvP.', 'weapon_infinity_sword_i00', 5);
INSERT INTO `all_items` VALUES (9390, 'Infinity Shooter', NULL, 'Священное Оружие Героя. Добавляется Священная Физ. Атк. При Крит. Атк. дает следующие эффекты: замедление цели, уменьшение расхода MP при использовании умений, увеличение Макс.MP/Макс CP. Наносит дополнительный урон в PvP.', 'Sacred Hero Weapon. Adds Sacred Physical Attack. On Critical Attack, it provides the following effects: slows the target, reduces MP consumption when using skills, increases Max MP/Max CP. Deals additional damage in PvP.', 'weapon_infinity_shooter_i00', 5);
