INSERT INTO `all_items` VALUES (9406, 'Enchanter Circlet', NULL, 'Головной аксессуар, используемый Заклинателями после 2-й или 3-й смены профессии. Требует две ячейки головных уборов.', 'Head accessory used by Spellcasters after the 2nd or 3rd profession change. Requires two headgear slots.', 'accessary_enchanter_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9407, 'Weapon Master Circlet (Kamael only)', NULL, 'Диадема только для расы Камаэль и только для Оружейников после 2-й и 3-й смены профессии. Нельзя носить в состоянии подкласса. Требует две ячейки головных уборов.', 'Diadem only for the Kamal race and only for Weapon Masters after the 2nd and 3rd profession change. Cannot be worn in subclass state. Requires two headgear slots.', 'accessary_weapon_master_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9408, 'Bow Master Circlet (Kamael only)', NULL, 'Диадема только для расы Камаэль и только для Лучников после 2-й и 3-й смены профессии. Нельзя носить в состоянии подкласса. Требует две ячейки головных уборов.', 'Diadem only for the Kamal race and only for Archers after the 2nd and 3rd profession change. Cannot be worn in subclass state. Requires two headgear slots.', 'accessary_bow_master_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9409, 'Black Phantom Mask (Event)', NULL, 'Черная маска фантома сделана из черного металла и золота. Требует две ячейки головных уборов. Только для ивентов. Нельзя обменять/выбросить.', 'Black phantom mask made of black metal and gold. Requires two headgear slots. Event only. Cannot be traded/discarded.', 'accessory_high_phantom_mask_i00', 0);
