INSERT INTO `all_items` VALUES (9570, 'Red Soul Crystal - Stage 14', NULL, 'Красный кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'Red crystal that absorbs souls. Level 14. When filled, it grants special properties to weapons.', 'etc_soul_stone_i00', 1);
INSERT INTO `all_items` VALUES (9571, 'Blue Soul Crystal - Stage 14', NULL, 'Синий кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'Blue crystal that absorbs souls. Level 14. When filled, it grants special properties to weapons.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (9572, 'Green Soul Crystal - Stage 14', NULL, 'Зеленый кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'Green crystal that absorbs souls. Level 14. When filled, it grants special properties to weapons.', 'etc_soul_stone_i02', 1);
INSERT INTO `all_items` VALUES (9573, 'Life Stone -  Level 80', NULL, 'Обычный минерал, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 80-го уровня и выше.', 'Ordinary mineral petrified by someone\'s physical or magical power. Key component for enchanting weapons for characters level 80 and above.', 'etc_mineral_general_i03', 0);
INSERT INTO `all_items` VALUES (9574, 'Mid-Grade Life Stone -  Level 80', NULL, 'Минерал среднего качества, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 80-го уровня и выше.', 'Medium-quality mineral petrified by someone\'s physical or magical power. Key component for enchanting weapons for characters level 80 and above.', 'etc_mineral_special_i03', 0);
INSERT INTO `all_items` VALUES (9575, 'High-Grade Life Stone -  Level 80', NULL, 'Минерал высокого качества, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 80-го уровня и выше.', 'High-quality mineral petrified by someone\'s physical or magical power. Key component for enchanting weapons for characters level 80 and above.', 'etc_mineral_rare_i03', 0);
INSERT INTO `all_items` VALUES (9576, 'Top-Grade Life Stone -  Level 80', NULL, 'Минерал высшего качества, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 80-го уровня и выше.', 'Superior-quality mineral petrified by someone\'s physical or magical power. Key component for enchanting weapons for characters level 80 and above.', 'etc_mineral_unique_i03', 0);
