INSERT INTO `all_items` VALUES (9593, 'Yellow Seed of Evil - Shard', NULL, 'Кусочки Желтого Семени зла, вживленного в монстра Белефом. Если вы отнесете их Кузнецу Раму, он обменяет их на полезный предмет. Нельзя обменять/выбросить.', 'Pieces of Yellow Evil Seed implanted in the monster Belief. If you take them to Blacksmith Ram, he will exchange them for a useful item. Cannot be traded/discarded.', 'etc_seed_of_evil_i00', 0);
INSERT INTO `all_items` VALUES (9594, 'Green Seed of Evil - Shard', NULL, 'Кусочки Зеленого Семени Зла, вживленного в монстра Белефом. Если вы отнесете их Кузнецу Раму, он обменяет их на полезный предмет. Нельзя обменять/выбросить.', 'Pieces of Green Evil Seed implanted in the monster Belief. If you take them to Blacksmith Ram, he will exchange them for a useful item. Cannot be traded/discarded.', 'etc_seed_of_evil_i01', 0);
