INSERT INTO `all_items` VALUES (9605, 'Agathion Seal Bracelet - Rainbow Clan Hall', NULL, 'Браслет для призыва Агатиона. Надевается только на членов клана, владеющего Радужным Холлом Клана. Этот предмет Нельзя обменять/выбросить.', 'Bracelet for summoning Agathion. Can only be worn by clan members who own the Clan Rainbow Hall. This item cannot be traded/discarded.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (9606, 'Agathion Seal Bracelet - Wild Beast Reserve', NULL, 'Браслет для призыва Агатиона. Надевается только на членов клана, владеющего Берлогой Диких Зверей. Этот предмет Нельзя обменять/выбросить.', 'Bracelet for summoning Agathion. Can only be worn by clan members who own the Wild Beasts\' Den. This item cannot be traded/discarded.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (9607, 'Agathion Seal Bracelet - Gludio', NULL, 'Браслет для призыва Агатиона. Надевается только на членов клана, владеющего Замком Глудио. Этот предмет Нельзя обменять/выбросить.', 'Bracelet for summoning Agathion. Can only be worn by clan members who own the Gludio Castle. This item cannot be traded/discarded.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (9608, 'Agathion Seal Bracelet - Dion', NULL, 'Браслет для призыва Агатиона. Надевается только на членов клана, владеющего Замком Дион. Этот предмет Нельзя обменять/выбросить.', 'Bracelet for summoning Agathion. Can only be worn by clan members who own the Dion Castle. This item cannot be traded/discarded.', 'etc_rbracelet_aga_agit_i00', 0);
