INSERT INTO `all_items` VALUES (9616, 'Dynasty Sword Piece', NULL, 'Основной материал, используемый Гномами для создания Меча Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Sword. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_sword_body_i00', 6);
INSERT INTO `all_items` VALUES (9617, 'Dynasty Blade Piece', NULL, 'Основной материал, используемый Гномами для создания Клинка Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Blade. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_sword_body_i00', 6);
INSERT INTO `all_items` VALUES (9618, 'Dynasty Phantom Piece', NULL, 'Основной материал, используемый Гномами для создания Фантома Династии. Используется только Гномами. Можно продать в Торговой Лавке. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Phantom. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_sword_body_i00', 6);
INSERT INTO `all_items` VALUES (9619, 'Dynasty Bow Piece', NULL, 'Основной материал, используемый Гномами для создания Лука Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Bow. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_branch_gold_i00', 6);
INSERT INTO `all_items` VALUES (9620, 'Dynasty Knife Piece', NULL, 'Основной материал, используемый Гномами для создания Ножа Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Dagger. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_sword_body_i00', 6);
INSERT INTO `all_items` VALUES (9621, 'Dynasty Halberd Piece', NULL, 'Основной материал, используемый Гномами для создания Алебарды Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Halberd. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_squares_silver_i00', 6);
