INSERT INTO `all_items` VALUES (9623, 'Dynasty Mace Piece', NULL, 'Основной материал, используемый Гномами для создания Булавы Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Mace. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_squares_silver_i00', 6);
INSERT INTO `all_items` VALUES (9624, 'Dynasty Bagh-Nakh Piece', NULL, 'Основной материал, используемый Гномами для создания Когтя Тигра Династии. Используется только Гномами. Можно продать в Торговой Лавке.', 'Main material used by Dwarves to create the Dynasty Tiger Claw. Used only by Dwarves. Can be sold in the Trading Shop.', 'etc_squares_silver_i00', 6);
