INSERT INTO `all_items` VALUES (9668, 'Great Wolf Food', NULL, 'Автоматически потребляется, если показатель голода Великого Волка упадет до 55%.', 'Automatically consumed if the Great Wolf\'s hunger level drops to 55%.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (9669, 'Native Helmet', NULL, 'Используя это вместе с Туникой и Штанами Аборигенов, вы превратитесь в Аборигена. Для обратного превращения просто снимите это.', 'When you use this with Native Tunic and Pants, you can transform into a Native. Transformation will be cancelled if unequipped.', 'armor_leather_helmet_i00', 0);
INSERT INTO `all_items` VALUES (9670, 'Native Tunic', NULL, 'Используя это вместе с Шлемом и Штанами Аборигенов, вы превратитесь в Аборигена. Для обратного превращения просто снимите это.', 'Using this along with the Aborigine Helmet and Pants will transform you into an Aborigine. To revert, simply remove it.', 'armor_t34_u_i00', 0);
INSERT INTO `all_items` VALUES (9671, 'Native Pants', NULL, 'Используя это вместе с Туникой и Шлемом Аборигенов, вы превратитесь в Аборигена. Для обратного превращения просто снимите это.', 'When you use this with Native Helmet and Tunic, you can transform into a Native. Transformation will be cancelled if unequipped.', 'armor_t34_l_i00', 0);
INSERT INTO `all_items` VALUES (9672, 'Magic Bottle', NULL, 'Бутыль, в которой может храниться магическая сила Химеры.', 'Bottle that can hold the magical power of the Chimera.', 'etc_magical_bottle_i00', 0);
INSERT INTO `all_items` VALUES (9673, 'Holy Water', NULL, 'Позволяет призракам в храме обрести вечный покой.', 'Allows the spirits in the temple to find eternal peace.', 'etc_holy_water_i00', 0);
INSERT INTO `all_items` VALUES (9674, 'Darion\'s Badge', NULL, 'Мистическая сила последователей Белефа заключена в таких медальонах. Его обладатель может свободно путешествовать по Острову Ада, кем бы он ни был.', 'The mystical power of Belief\'s followers is contained in such medallions. Its holder can freely travel through the Island of Hell, regardless of who they are.', 'etc_hs_agit_war_joining_certificate_i00', 0);
INSERT INTO `all_items` VALUES (9675, 'Prayer Fragment', NULL, 'Фрагмент древней молитвы. Может быть, это нужно кому-нибудь.', 'Fragment of an ancient prayer. Perhaps it is needed by someone.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9676, 'Mark of Betrayal', NULL, 'Оберег, доказывающий, что вы убили предателей Караванов.', 'Amulet proving that you have killed the traitors of the Caravans.', 'etc_ketra_friendship_2_i00', 0);
INSERT INTO `all_items` VALUES (9677, 'Ring of Wind Mastery', NULL, 'Это кольцо позволяет вам стойко переносить порывы ветра.', 'This ring permits you to withstand strong gusts of wind.', 'accessary_ring_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (9678, 'Magic Gem', NULL, 'Это ключ, открывающий проход в другое измерение.', 'This key opens a passage to another dimension.', 'etc_magical_stone_i00', 6);
INSERT INTO `all_items` VALUES (9679, 'Steel Citadel Blueprints', NULL, 'Этот чертеж очень сложно достать.', 'This blueprint is very difficult to obtain.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (9680, 'Dim Life Force', NULL, 'Жизненная сила Химеры.', 'Life force of the Chimera.', 'etc_magic_energy_i00', 0);
INSERT INTO `all_items` VALUES (9681, 'Life Force', NULL, 'Жизненная сила Химеры.', 'Life force of the Chimera.', 'etc_magic_energy_i01', 0);
INSERT INTO `all_items` VALUES (9682, 'Contained Life Force', NULL, 'Жизненная сила Кельтуса Химеры.', 'Life force of Keltus the Chimera.', 'etc_magic_energy_i02', 0);
INSERT INTO `all_items` VALUES (9683, 'Sand Worm Tooth', NULL, 'Этот предмет можно очень выгодно обменять, торгуя с караванами.', 'This item can be exchanged profitably when trading with caravans.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (9684, 'Native Treasure', NULL, 'Можно найти в тайной подземной комнате в городе.', 'Can be found in a secret underground room in the city.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (9685, 'Gate Key: Darkness', NULL, 'Ключ с Символом Тьмы.', 'Key with the Symbol of Darkness.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9686, 'Gate Key: Destruction', NULL, 'Этот ключ открывает Врата Разрушения.', 'This key opens the Gates of Destruction.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9687, 'Gate Key: Blood', NULL, 'Этот ключ источает кровь.', 'This key exudes blood.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9688, 'Ballista Bomb', NULL, 'Вы можете использовать это, чтобы уничтожить Баллисту и поднять свою репутацию.', 'You can use this to destroy the Ballista and raise your reputation.', 'etc_dynamite_i00', 3);
INSERT INTO `all_items` VALUES (9689, 'Spirit of the Lake', NULL, 'Дух, который Семейство Фафуриона использовало, чтобы восстановить свои HP.', 'The spirit that the Fafurion Family used to restore their HP.', 'etc_talisman_i01', 3);
INSERT INTO `all_items` VALUES (9690, 'Contaminated Crystal', NULL, 'Черный матовый кристалл. Нужен, чтобы войти в Кристальные Пещеры.', 'Black matte crystal. Needed to enter the Crystal Caves.', 'etc_crystal_cave_crystal_i03', 0);
INSERT INTO `all_items` VALUES (9691, 'Water Dragon Scale', NULL, 'Чешуя Семейства Фафуриона. Может повредить определенным целям, но не будет действовать, если выбрать не ту цель.', 'Scale of the Fafurion Family. Can harm certain targets, but will not work if the wrong target is chosen.', 'etc_water_dragon_scale_i00', 0);
INSERT INTO `all_items` VALUES (9692, 'Red Coral', NULL, 'Обломок Красного Коралла, продлевающего время. Используется в Паровом Коридоре Кристальных Пещер.', 'Fragment of Red Coral that extends time. Used in the Steam Corridor of the Crystal Caves.', 'etc_red_coral_i00', 0);
INSERT INTO `all_items` VALUES (9693, 'Crystal Fragment', NULL, 'Обломок Кристального Голема. Используется в Коралловом Саду Кристальных Пещер.', 'Fragment of the Crystal Golem. Used in the Coral Garden of the Crystal Caves.', 'etc_crystal_piece_i00', 0);
INSERT INTO `all_items` VALUES (9694, 'Secret Key', NULL, 'Этот ключ открывает Тайные Врата.', 'This key opens the Secret Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9695, 'Blue Crystal', NULL, 'Кристалл, полученный убийством Дарнеля. Нужен для спасения Парме.', 'Crystal obtained by killing Darnel. Needed to save Parme.', 'etc_crystal_cave_crystal_i02', 0);
INSERT INTO `all_items` VALUES (9696, 'Red Crystal', NULL, 'Кристалл, полученный убийством Кечи. Нужен для спасения Парме.', 'Crystal obtained by killing Kechi. Needed to save Parme.', 'etc_crystal_cave_crystal_i01', 0);
INSERT INTO `all_items` VALUES (9697, 'Clear Crystal', NULL, 'Кристалл, полученный убийством Слез. Нужен для спасения Парме.', 'Crystal obtained by killing Tears. Needed to save Parme.', 'etc_crystal_cave_crystal_i0', 0);
INSERT INTO `all_items` VALUES (9698, 'Blue Coral Key', NULL, 'Ключ, открывающий Сапфировые Врата.', 'Key that opens the Sapphire Gates.', 'etc_crystal_cave_key_i01', 0);
INSERT INTO `all_items` VALUES (9699, 'Red Coral Key', NULL, 'Ключ, открывающий врата, ведущие в Паровой Коридор.', 'Key that opens the gates leading to the Steam Corridor.', 'etc_crystal_cave_key_i02', 0);
INSERT INTO `all_items` VALUES (9700, 'Water Dragon Claw', NULL, 'Предмет Семьи Фафуриона. Нужен для спасения Парме.', 'Item of the Fafurion Family. Needed to save Parme.', 'etc_water_dragon_claw_i00', 0);
INSERT INTO `all_items` VALUES (9701, 'Sealed Magic Field Key', NULL, 'Этот ключ может запечатать Силовое Поле.', 'This key can seal the Force Field.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9702, 'Caravaner\'s Remedy', NULL, 'Этот эликсир поможет охладить жару Пустыни Ада.', 'This elixir will help cool the heat of the Desert of Hell.', 'etc_lesser_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (9703, 'Gate Key: Kamael', NULL, 'Этот ключ открывает Врата Камаэль.', 'This key opens the Kamal Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9704, 'Gate Key: Archives', NULL, 'Этот ключ открывает Врата Архива.', 'This key opens the Archive Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9705, 'Gate Key: Observation', NULL, 'Этот ключ открывает Врата Обзора.', 'This key opens the Overview Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9706, 'Gate Key: Spicula', NULL, 'Этот ключ открывает Врата Спикулы.', 'This key opens the Spicula Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9707, 'Gate Key: Harkilgamed', NULL, 'Этот ключ открывает Врата Халкигамеда.', 'This key opens the Halkigamed Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9708, 'Gate Key: Rodenpicula', NULL, 'Этот ключ открывает Врата Роденпикулы.', 'This key opens the Rodenpicula Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9709, 'Gate Key: Arviterre', NULL, 'Этот ключ открывает Врата Арвитерра.', 'This key opens the Arviterra Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9710, 'Gate Key: Katenar', NULL, 'Этот ключ открывает Врата Катенара.', 'This key opens the Katenar Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9711, 'Gate Key: Prediction', NULL, 'Этот ключ открывает Врата Предсказаний.', 'This key opens the Prediction Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9712, 'Gate Key: Massive Cavern', NULL, 'Этот ключ открывает Врата Пещеры.', 'This key opens the Cave Gates.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9713, 'Nornil\'s Power', NULL, 'Используйте это в зоне, помеченной на карте желтым цветом.', 'Use this in the area marked in yellow on the map.', 'etc_talisman_i02', 3);
INSERT INTO `all_items` VALUES (9714, 'Key of the Evil Eye', NULL, 'У Мастера Ключей в городе есть ключ, который нужен вам, чтобы войти в Стальную Цитадель.', 'The Master of Keys in the city has a key that you need to enter the Steel Citadel.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9715, 'Giant Key', NULL, 'Ключ размером с человеческую руку. Для чего он?', 'A key the size of a human hand. What is it for?', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9716, 'Scroll of Escape: Kamael Village', NULL, 'Магический свиток, с помощью которого можно переместиться в Деревню Камаэль.', 'Magic scroll that allows you to teleport to the Village of Kamal.', 'etc_scroll_of_return_i00', 0);
INSERT INTO `all_items` VALUES (9717, 'Information on Eranus', NULL, 'Щелкните дважды, чтобы получить больше информации о Эранусе.', 'Double-click for more information about Eranus.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (9718, 'Report on the Crimson Duchess', NULL, 'Это доклад о миньоне Белефа, Багровой Герцогине, с которой вы можете столкнуться в поисках Камня Познания. Двойной щелчок для получения дополнительной информации.', 'This is a report on Belief\'s minion, the Crimson Duchess, whom you may encounter in your quest for the Stone of Knowledge. Double-click for additional information.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9719, 'List of Attackers', NULL, 'Список внезапно атаковавших Ангелов. Щелкните по нему дважды для получения дополнительной информации.', 'List of suddenly attacking Angels. Double-click for additional information.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9720, 'Warrior\'s Sword', NULL, 'Меч Воина Камаэль.', 'Sword of the Kamal Warrior.', 'weapon_sealed_rapier_i00', 0);
INSERT INTO `all_items` VALUES (9721, 'Freezer', NULL, 'Отнесите этот механизм Мастеру Дуроге.', 'Take this mechanism to Master Duroge.', 'etc_instrument_i00', 0);
INSERT INTO `all_items` VALUES (9722, 'Resonance Amulet - 1', NULL, 'Этот предмет нужен для общения с первым Камнем Познания.', 'This item is needed to communicate with the 1st Stone of Knowledge.', 'etc_resonance_amulet_i00', 0);
INSERT INTO `all_items` VALUES (9723, 'Resonance Amulet - 1', NULL, 'Этот предмет нужен для общения с первым Камнем Познания.', 'This item is needed to communicate with the 1st Stone of Knowledge.', 'etc_resonance_amulet_i00', 0);
