INSERT INTO `all_items` VALUES (9740, 'Halisha\'s Mark', NULL, 'Проклятая метка для призыва миньона Халиши.', 'A cursed mark used to summon Halisha\'s minion.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (9741, 'Halisha\'s Mark', NULL, 'Проклятая метка для призыва миньона Халиши.', 'A cursed mark used to summon Halisha\'s minion.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (9742, 'Halisha\'s Mark', NULL, 'Проклятая метка для призыва миньона Халиши.', 'A cursed mark used to summon Halisha\'s minion.', 'etc_eyeball_i00', 0);
INSERT INTO `all_items` VALUES (9743, 'Shining Medallion', NULL, 'Медаль Ангела Высшего Ранга.', 'High Rank Angel\'s Medal.', 'etc_event_glitter_medal_i00', 0);
INSERT INTO `all_items` VALUES (9744, 'Blood Jewel', NULL, 'Кроваво-красное украшение.', 'Blood Red Ornament.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (9745, 'Black Echo Crystal', NULL, 'Этот кристалл воспроизводит нечто зловещее.', 'This crystal plays back something ominous.', 'etc_echo_crystal_i00', 0);
INSERT INTO `all_items` VALUES (9746, 'Commander\'s Feather', NULL, 'Перо Командира Муэрто.', 'Muertos Commander\'s Feather.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (9747, 'Crimson Spider Claw', NULL, 'Отдайте этот коготь Второму Иерарху Первану.', 'Give this claw to Second Hierarch Pervane.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (9748, 'Muertos Feather', NULL, 'Перо, полученное при убийстве Муэрто. Отдайте его Торговцу Тревору.', 'A feather obtained from a Muertos. Give it to Trader Trevor.', 'etc_feather_white_i00', 0);
INSERT INTO `all_items` VALUES (9749, 'Felim Lizardman Head', NULL, 'Голова Ящера Фелим.', 'Felim Lizardman Head.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (9750, 'Venomous Spider\'s Leg', NULL, 'Лапка Гигантского Паука.', 'Giant Spider Leg.', 'etc_sting_b_i00', 0);
INSERT INTO `all_items` VALUES (9751, 'Tumran Bugbear Heart', NULL, 'Сердце Людоеда Тумран.', 'Tumran Bugbear Heart.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (9752, 'Shubain\'s Recommendation', NULL, 'Рекомендательное письмо, написанное Мастером Шубейном в Глудине. Отдайте его Гвейну из Глудио.', 'A letter of recommendation written by Master Shubein in Gludin. Give it to Gwayne in Gludio.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (9753, 'Gwain\'s Recommendation', NULL, 'Рекомендательное письмо, написанное Мастером Гвейном из Глудио. Отдайте его Великому Мастеру Камаэль для смены профессии.', 'A letter of recommendation written by Master Gwayne of Gludio. Give it to a Kamael Grand Master for a class change.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9754, 'Breka Orc Head', NULL, 'Голова Орка Брека.', 'Breka Orc Head.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (9755, 'Message Plate', NULL, 'Табличка с сообщением от Придорожного Падальщика.', 'A tablet with a message from a Road Scavenger.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (9756, 'Report - East', NULL, 'Доклад, найденный на трупе Поедателя Мертвечины в Земле Казненных.', 'A report found on the corpse of a Scavenger in the Execution Grounds.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9757, 'Report - North', NULL, 'Доклад, найденный на трупе Трутня Стакато в Топях Крума.', 'A report found on the corpse of a Staccato Drone in the Cruma Marshlands.', 'etc_roll_of_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (9758, 'Harkilgamed\'s Letter', NULL, 'Халкигамед просил вас отнести это письмо Мастеру Тенаину.', 'Halkigamed asked you to take this letter to Master Tenain.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9759, 'Tenain\'s Recommendation', NULL, 'Отнесите это рекомендательное письмо, написанное Мастером Тенаином, в Город Орен Мастеру Оркурусу.', 'Take this recommendation letter written by Master Tenain to Master Orim in Oren.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (9760, 'Orkurus\' Recommendation', NULL, 'Рекомендательное письмо, написанное Мастером Орукусом из Орена. Отдайте его Великому Мастеру Камаэль для смены профессии.', 'A letter of recommendation written by Master Orim of Oren. Give it to a Kamael Grand Master for a class change.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9761, 'Frozen Cell Samples', NULL, 'Мастер Джастин просил это для изучения жизненной энергии.', 'Master Justin requested this to study life energy.', 'etc_bodypart_liver_i00', 0);
INSERT INTO `all_items` VALUES (9762, 'Orders', NULL, 'Эти приказы Гноллов можно найти в пустынном лагере. Собирайте их вместе с организационными структурами и отнесите Мастеру Камаэль Сионе.', 'These Gnoll orders can be found at the desert camp. Collect them along with the organizational charts and take them to Kamael Master Siana.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9763, 'Organization Chart', NULL, 'Эти организационные структуры Гноллов можно найти в пустынном лагере. Собирайте их вместе с приказами и отнесите Мастеру Камаэль Сионе.', 'These Gnoll organizational charts can be found at the desert camp. Collect them along with the orders and take them to Kamael Master Siana.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (9764, 'Gobie\'s Orders', NULL, 'Основываясь на документах Гноллов, эти приказы описывают стратегию защиты от них. Отнесите Мастеру Камаэль Гоби.', 'Based on the Gnoll documents, these orders describe a defense strategy against them. Take them to Kamael Master Gobi.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (9765, 'Letter to the Humans', NULL, 'Это письмо написано союзниками людей из Камаэль, его нужно доставить Капитану Батису в Город Глудио.', 'This letter is written by the human allies of the Kamael. Deliver it to Captain Bathis in the Town of Gludio.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (9766, 'Humans\' Reply', NULL, 'Это письмо от Капитана Батиса нужно доставить Мастеру Гоби.', 'This letter from Captain Bathis must be delivered to Master Gobi.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9767, 'Letter to the Dark Elves', NULL, 'Письмо, написанное союзниками Темных Эльфов из Камаэль. Нужно доставить его Великому Мастеру Тобиасу в Глудио.', 'A letter written by the Dark Elf allies of the Kamael. Deliver it to Grand Master Tobias in Gludio.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (9768, 'Dark Elves\' Reply', NULL, 'Письмо Великого Мастера Тобиаса, которое нужно доставить Мастеру Камаэль Гоби.', 'A letter from Grand Master Tobias to be delivered to Kamael Master Gobi.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9769, 'Report to Sione', NULL, 'Этот доклад, написанный Гоби в связи с переговорами между Людьми и Темными Эльфами, нужно доставить Мастеру Сионе.', 'This report written by Gobi regarding the negotiations between Humans and Dark Elves must be delivered to Master Siana.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (9770, 'Empty Soul Crystal', NULL, 'Офицер Гноллов Так может быть заточен в этот кристалл.', 'Gnoll Officer Tak may be sealed inside this crystal.', 'etc_bead_white_i00', 0);
INSERT INTO `all_items` VALUES (9771, 'Tak\'s Captured Soul', NULL, 'Офицер Гноллов Так заточен в этот кристалл. Отдайте его Мастеру Гоби для допроса.', 'Gnoll Officer Tak is sealed inside this crystal. Give it to Master Gobi for interrogation.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (9772, 'Steelrazor Evaluation', NULL, 'Рекомендация \"Стилрейзора\", особого отряда Камаэль. Отдайте его любому Великому Мастеру Камаэль для смены профессии на Надзирателя.', 'A recommendation from the \"Steelrazor,\" a special Kamael unit. Give it to any Kamael Grand Master to change your class to Warder.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9773, 'Enmity Crystal', NULL, 'Магистр Клейтон ищет этот материал. Если вы принесете ему достаточное количество, он вознаградит вас информацией.', 'Magister Clayton is looking for this material. If you bring him enough, he will reward you with information.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (9774, 'Enmity Crystal Core', NULL, 'Этот магический предмет сделан из Кристалла Враждебности. Отдайте его Кузнецу Пойтану в Дионе.', 'This magical item is made from a Crystal of Hostility. Give it to Blacksmith Poitain in Dion.', 'etc_gem_red_i00', 0);
INSERT INTO `all_items` VALUES (9775, 'Manuscript Page', NULL, 'Хранитель Склада Хольвас ищет эти страницы. Соберите их и отдайте ему.', 'Warehouse Keeper Holvas is looking for these pages. Collect them and give them to him.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9776, 'Encoded Page on the Ancient Race', NULL, 'Зашифрованный документ о новых расах. По словам Хольваса, расшифровать его может Великий Мастер Камаэль Мельдина.', 'An encrypted document about the new races. According to Holvas, Kamael Grand Master Meldina can decipher it.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9777, 'Kamael Inquisitor Trainee Mark', NULL, 'Покажите это Сельсии, Начальнику Разведки Камаэль, и получите задание для смены профессии.', 'Show this to Selsia, the Kamael Intelligence Chief, to receive your class change quest.', 'etc_jewel_gold_i00', 0);
INSERT INTO `all_items` VALUES (9778, 'Fragment of Attack Orders', NULL, 'Фрагмент приказа об атаке, взятого с тела убитого Грандиса. Соберите все фрагменты, чтобы узнать, кто отдал приказ об атаке.', 'A fragment of an attack order taken from the corpse of a defeated Grandis. Collect all the fragments to find out who ordered the attack.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (9779, 'Grandis\' Attack Orders', NULL, 'Собранный приказ об атаке. Из его содержания ясно, что атака была спланирована Магистром Башни Слоновой Кости Гаюсом. Давайте-ка навестим Гаюса…', 'A collected attack order. Its contents reveal that the attack was planned by Ivory Tower Magister Gaius. Let\'s go visit Gaius...', 'etc_map_piece_yellow_i00', 0);
INSERT INTO `all_items` VALUES (9780, 'Manashen\'s Talisman', NULL, 'Обломки талисмана, добытые убийством Манашенов. Соберите все обломки и узнаете, кто управляет Манашенами.', 'Talisman fragments obtained by slaying Manashens. Collect all the fragments to find out who controls the Manashens.', 'etc_mark_red_i00', 0);
INSERT INTO `all_items` VALUES (9781, 'Research on the Giants and the Ancient Race', NULL, 'Этот документ гигантов содержит информацию об исследованиях тайной расы. Он находился у миньона Белефа, Багровой Герцогини. Отдайте его Сельсии.', 'This Giant document contains information about research on a secret race. It was in the possession of Beleth\'s minion, the Crimson Duchess. Give it to Selsia.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (9782, 'Kamael Inquisitor Mark', NULL, 'Знак, доказывающий, что Вы успешно прошли испытание Инквизитора. Покажите ее любому Великому Мастеру Камаэль, чтобы стать Арбалетчиком.', 'A mark proving that you have successfully completed the Inquisitor test. Show it to any Kamael Grand Master to become an Arbalester.', 'etc_jewel_red_i00', 0);
INSERT INTO `all_items` VALUES (9783, 'Echo Crystal of Free Thought', NULL, 'Изначально этот кристалл принадлежал Матери всех Ведьм. Он может помочь ведьме вернуть утраченную память.', 'Originally, this crystal belonged to the Mother of all Witches. It can help the witch recover her lost memory.', 'etc_echo_crystal_i02', 0);
INSERT INTO `all_items` VALUES (9784, 'Parme\'s Letter', NULL, 'Письмо от Ведьмы Водного Дракона должно быть доставлено Жрецу Карнису.', 'A letter from the Water Dragon Witch must be delivered to Priest Karnis.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (9785, 'Refined Crystal Sample', NULL, 'Этот магический материал нужен Чародею, посланному в Башню Слоновой Кости для обозревания Острова Ада. Отдайте это ему и попробуйте с ним поговорить.', 'This magical material is needed by the Wizard sent to the Ivory Tower to survey the Isle of Souls (Hellbound). Give it to him and try talking to him.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (9786, 'Stabilized Ectoplasm', NULL, 'Этот материал нужен Хардину для изучения магии превращений. Доставьте это ему, чтобы помочь в его экспериментах.', 'Hardin needs this material to study transformation magic. Deliver it to him to assist in his experiments.', 'etc_potion_clear_i00', 0);
INSERT INTO `all_items` VALUES (9787, 'Ectoplasm', NULL, 'Этот материал необходим для создания стабилизирующей эктоплазмы, которая используется в магии превращений.', 'This material is necessary to create stabilizing ectoplasm, which is used in transformation magic.', 'etc_lesser_potion_clear_i00', 0);
INSERT INTO `all_items` VALUES (9788, 'Hardin\'s Instructions', NULL, 'Эта инструкция по магии превращений написано Хардином. Ее нужно доставить Магистру Клейтону в Дион.', 'This guide on transformation magic was written by Hardin. It must be delivered to Magister Clayton in Dion.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9789, 'Glass Jaguar Crystal', NULL, 'Один из материалов, о которых говорил Хардин. Доставьте его Магистру Клейтону.', 'One of the materials Hardin mentioned. Deliver it to Magister Clayton.', 'etc_oriharukon_ore_i00', 0);
INSERT INTO `all_items` VALUES (9790, 'Blank Sealbook', NULL, 'Пустая запечатанная книга, в которой можно хранить силу магии превращений. Отнесите ее Хардину.', 'An empty sealed book capable of storing the power of transformation magic. Take it to Hardin.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (9791, 'Transformation Sealbook: Onyx Beast', NULL, 'Запечатанное письмо, содержащее силу магии превращений. Если вы отдадите его Магу Превращений на 2-м этаже Башни Слоновой Кости, то он сможет превратить вас.', 'A sealed letter containing the power of transformation magic. If you give it to the Transformation Wizard on the 2nd floor of the Ivory Tower, they can transform you.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (9792, 'Warehouse Manifest', NULL, 'Отчет о материалах, хранящихся на складе Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'A report on the supplies stored in the Kamael Village Warehouse. Give it to Supply Officer Markella.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (9793, 'Grocery Store Manifest', NULL, 'Отчет о товарах в торговой лавке Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'A report on the goods in the Kamael Village general shop. Give it to Supply Officer Markella.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (9794, 'Weapon Shop Manifest', NULL, 'Отчет о запасах оружия в магазине Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'A report on the weapon inventory in the Kamael Village weapon shop. Give it to Supply Officer Markella.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9795, 'Supply Report', NULL, 'Отчет Снабженца Маркеллы. Нужно доставить его Помощнику Иерарха Кэске.', 'Supply Officer Markella\'s report. It must be delivered to Hierarch Assistant Keshkage.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9796, 'Hills of Gold Monster Claw', NULL, 'Коготь монстра, найденного в Золотых Холмах. Отдайте его Снабженцу Маркелле.', 'A monster claw found in the Golden Hills. Give it to Supply Officer Markella.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (9797, 'Dungeon Leader Mark', NULL, 'Знак отличия лидера монстров, обитающих в подземелье. Доставьте его Управляющему Крепости Тюремного Лагеря Монстров.', 'An insignia of a monster leader inhabiting the dungeon. Deliver it to the Monster Prison Camp Fortress Manager.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (9798, 'Fragment of the Dungeon Leader Mark', NULL, 'Обломок знака отличия лидера монстров, обитающих в Подземелье. Доставьте его Управляющему Крепости Тюремного Лагеря Монстров.', 'A broken piece of the insignia of a monster leader inhabiting the Dungeon. Deliver it to the Monster Prison Camp Fortress Manager.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (9799, 'Wolf Tail', NULL, 'Этот хвост покрыт роскошным мехом.', 'This tail is covered in luxurious fur.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (9800, 'Ranku\'s Blueprint', NULL, 'Чертеж, принадлежащий Ранку. Отнесите его Мэтресу.', 'A blueprint belonging to Rank. Take it to Metheus.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9801, 'Demon Prince\'s Blueprint', NULL, 'Чертеж, принадлежащий Принцу Демонов. Отнесите его Мэтресу.', 'A blueprint belonging to the Demon Prince. Take it to Metheus.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9802, 'Safe Key', NULL, 'Ключ, изготовленный Кузнецом Ноэлем, нужно отдать Начальнику Склада Моне.', 'A key made by Blacksmith Noel must be given to Warehouse Chief Moma.', 'etc_old_key_i03', 0);
INSERT INTO `all_items` VALUES (9803, 'Sealed Document', NULL, 'Документ, предназначенный для Помощника Иерарха Кэски.', 'A document intended for Hierarch Assistant Keshkage.', 'etc_roll_of_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (9804, 'Wyrm Heart', NULL, 'Сердце Змея, о котором просил Кекропус.', 'The Serpent Heart requested by Kekropus.', 'etc_heart_i00', 0);
INSERT INTO `all_items` VALUES (9805, 'Kekropus\' Recommendation', NULL, 'Рекомендательное письмо от Кекропуса. Отнесите его Битусу в Гиран.', 'A letter of recommendation from Kekropus. Take it to Bitus in Giran.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (9806, 'Soul Breaker Certificate', NULL, 'Свидетельство Палача. Покажите его любому Великому Мастеру, чтобы стать Палачом.', 'Proof of the Executioner. Show it to any Grand Master to become an Executioner.', 'etc_roll_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (9807, 'Wolf Tail', NULL, 'Хвост волка, о котором просил Перван.', 'The wolf tail requested by Pervane.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (9808, 'Muertos Claw', NULL, 'Коготь, полученный при убийстве Муэрто. Соберите 10 таких и отдайте Кекропусу.', 'A claw obtained by killing a Muertos. Collect 10 of these and give them to Kekropus.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (9809, 'Grey Keltir Tooth', NULL, 'Клык монстра. Отнесите его Зверолову Виксону.', 'A monster fang. Take it to Beast Handler Vixon.', 'etc_fang_gray_i00', 0);
INSERT INTO `all_items` VALUES (9810, 'Black Wolf Tooth', NULL, 'Клык монстра. Отнесите его Зверолову Виксону.', 'A monster fang. Take it to Beast Handler Vixon.', 'etc_fang_ivory_i00', 0);
INSERT INTO `all_items` VALUES (9811, 'Fortress Certificate', NULL, 'Используйте это для получения припасов у Надзирателя Тюремного Лагеря.', 'Use this to obtain supplies from a Prison Camp Manager.', 'etc_lesser_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (9812, 'Castle Certificate', NULL, 'Используйте это для получения припасов у Надзирателя Тюремного Лагеря.', 'Use this to obtain supplies from a Prison Camp Manager.', 'etc_lesser_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (9813, 'Orc Officer', NULL, NULL, NULL, 'weapon_monster_i00', 3);
INSERT INTO `all_items` VALUES (9814, 'Memento Mori', NULL, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'Dropped by Raid Bosses. This Life Crystal can be exchanged for something useful.', 'etc_raid_a_i02', 0);
INSERT INTO `all_items` VALUES (9815, 'Dragon Heart', NULL, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'Dropped by Raid Bosses. This Life Crystal can be exchanged for something useful.', 'etc_raid_b_i02', 0);
INSERT INTO `all_items` VALUES (9816, 'Earth Egg', NULL, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'Dropped by Raid Bosses. This Life Crystal can be exchanged for something useful.', 'etc_raid_c_i02', 0);
INSERT INTO `all_items` VALUES (9817, 'Nonliving Nucleus', NULL, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'Dropped by Raid Bosses. This Life Crystal can be exchanged for something useful.', 'etc_raid_d_i02', 0);
INSERT INTO `all_items` VALUES (9818, 'Angelic Essence', NULL, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'Dropped by Raid Bosses. This Life Crystal can be exchanged for something useful.', 'etc_raid_e_i02', 0);
INSERT INTO `all_items` VALUES (9819, 'Combat flag', NULL, 'Этот флаг нужно повесить на флагшток во время Битвы за Крепость. Вы не можете атаковать и использовать атакующие умения, когда несете его, но можете использовать умения флага.', 'Put this into a the flagpole to win Fortress War. You are forced to wear it once you acquire it, during which time use of Attack and Attack Skills is impossible, but Flag Display Skills can be used.', 'weapon_fort_flag_i00', 0);
INSERT INTO `all_items` VALUES (9820, 'Shadow Item: Clan Oath Helm', NULL, 'Теневой предмет заключает в себе отраженную мощь Шлема Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'A shadow item imbued with the reflected power of the Oath Helm. Cannot be exchanged, dropped, crystallized, or enchanted.', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (9821, 'Shadow Item: Clan Oath Armor', NULL, 'Теневой предмет заключает в себе отраженную мощь Доспеха Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'This Shadow Item contains the mirrored power of a Clan Oath Armor. It cannot be exchanged, dropped, crystallized, or given other functions. Full body armor. It can only be used by one belonging to the Academy or its graduates.', 'armor_t1001_ul_i00', 0);
INSERT INTO `all_items` VALUES (9822, 'Shadow Item: Clan Oath Gauntlets', 'Heavy Armor', 'Теневой предмет содержит в себе отраженную мощь Рукавиц Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Heavy	This Shadow Item contains the mirrored power of Clan Oath Gauntlets. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1001_g_i00', 0);
INSERT INTO `all_items` VALUES (9823, 'Shadow Item: Clan Oath Sabaton', 'Heavy Armor', 'Теневой предмет содержит в себе отраженную мощь Солеретов Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Heavy	This Shadow Item contains the mirrored power of Clan Oath Sabaton. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1001_b_i00', 0);
INSERT INTO `all_items` VALUES (9824, 'Shadow Item: Clan Oath Brigandine', NULL, 'Теневой предмет содержит в себе отраженную мощь Панциря Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'This Shadow Item contains the mirrored power of Clan Oath Brigandine. It cannot be exchanged, dropped, crystallized, or given other functions. Full body armor. It can only be used by one belonging to the Academy or its graduates.', 'armor_t1002_ul_i00', 0);
INSERT INTO `all_items` VALUES (9825, 'Shadow Item: Clan Oath Leather Gloves', 'Light Armor', 'Теневой предмет содержит в себе отраженную мощь Кожаных Перчаток Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Light	This Shadow Item contains the mirrored power of Clan Oath Leather Gloves. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1002_g_i00', 0);
INSERT INTO `all_items` VALUES (9826, 'Shadow Item: Clan Oath Boots', 'Light Armor', 'Теневой предмет содержит в себе отраженную мощь Ботинок Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Light	This Shadow Item contains the mirrored power of Clan Oath Booths. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1002_b_i00', 0);
INSERT INTO `all_items` VALUES (9827, 'Shadow Item: Clan Oath Aketon', NULL, 'Теневой предмет содержит в себе отраженную мощь Накидки Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'This Shadow Item contains the mirrored power of Clan Oath Aketon. It cannot be exchanged, dropped, crystallized, or given other functions. Full body armor. It can only be used by one belonging to the Academy or its graduates.', 'armor_t1003_ul_i00', 0);
INSERT INTO `all_items` VALUES (9828, 'Shadow Item: Clan Oath Padded Gloves', 'Robe', 'Теневой предмет содержит в себе отраженную мощь Пластинчатых Перчаток Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Robe	This Shadow Item contains the mirrored power of Clan Oath Padded Gloves. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1003_g_i00', 0);
INSERT INTO `all_items` VALUES (9829, 'Shadow Item: Clan Oath Sandals', 'Robe', 'Теневой предмет содержит в себе отраженную мощь Сандалий Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'Robe	This Shadow Item contains the mirrored power of Clan Oath Sandals. It cannot be traded, dropped, crystallized, or given other functions.', 'armor_t1003_b_i00', 0);
INSERT INTO `all_items` VALUES (9830, 'Improved Apella Helm', NULL, 'Доступен только Баронам или Аристократам высокого ранга.', 'Available only to high-ranking Barons or Aristocrats.', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (9831, 'Improved Apella Plate Armor', NULL, 'Этот полный доспех для членов клана могут надевать Бароны или Аристократы высокого ранга.', 'This full body armor used by clan members can be worn by a Baron or higher-level Aristocrat.', 'armor_t1004_ul_i00', 0);
INSERT INTO `all_items` VALUES (9832, 'Improved Apella Gauntlet', 'Heavy Armor', 'Доступны только Баронам или Аристократам высокого ранга.', 'Heavy	Can be worn by a Baron or a higher-level Aristocrat.', 'armor_t1004_g_i00', 0);
INSERT INTO `all_items` VALUES (9833, 'Improved Apella Solleret', 'Heavy Armor', 'Доступно только Баронам или Аристократам высокого ранга.', 'Heavy	Can be worn by a Baron or a higher-level Aristocrat.', 'armor_t1004_b_i00', 0);
INSERT INTO `all_items` VALUES (9834, 'Improved Apella Brigandine', NULL, 'Доступен только Баронам или Аристократам высокого ранга.', 'Can be worn by a Baron or a higher-level Aristocrat.', 'armor_t1005_ul_i00', 0);
INSERT INTO `all_items` VALUES (9835, 'Improved Apella Leather Gloves', 'Light Armor', 'Доступны только Баронам или Аристократам высокого ранга.', 'Light	Can be worn by a Baron or a higher-level Aristocrat.', 'armor_t1005_g_i00', 0);
INSERT INTO `all_items` VALUES (9836, 'Improved Apella Boots', 'Light Armor', 'Доступны только Баронам или Аристократам высокого ранга.', 'Light	Can be worn by a Baron or a higher-level Aristocrat.', 'armor_t1005_b_i00', 0);
INSERT INTO `all_items` VALUES (9837, 'Improved Apella Doublet', NULL, 'Этот полный доспех для членов клана могут надевать Бароны или Аристократы высокого ранга.', 'This full body armor used by clan members can be worn by a Baron or higher-level Aristocrat.', 'armor_t1006_ul_i00', 0);
INSERT INTO `all_items` VALUES (9838, 'Improved Apella Silk Gloves', 'Robe', 'Доступны только Баронам или Аристократам высокого ранга.', 'Robe	Can be worn by a Baron or higher-level Aristocrat.', 'armor_t1006_g_i00', 0);
INSERT INTO `all_items` VALUES (9839, 'Improved Apella Sandals', 'Robe', 'Доступны только Баронам или Аристократам высокого ранга.', 'Robe	Can be worn by a Baron or higher-level Aristocrat.', 'armor_t1006_b_i00', 0);
INSERT INTO `all_items` VALUES (9840, 'Shadow Item: Chevalier Rapier', NULL, 'Теневой предмет, отражающий силу Рапиры Шевалье. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'A shadow item reflecting the power of the Chevalier\'s Rapier. Cannot be exchanged, dropped, crystallized, or enchanted.', 'weapon_soldat_estoc_i00', 2);
INSERT INTO `all_items` VALUES (9841, 'Shadow Item: Riter Schlager', NULL, 'Теневой предмет, отражающий силу Шлагера. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item Has the power of a Riter Schlager. It cannot be exchanged, dropped, crystallized or possess additional functions.', 'weapon_invincible_blade_i00', 2);
