INSERT INTO `all_items` VALUES (9844, 'Shadow Item: Immortal Edge', NULL, 'Теневой предмет, отражающий силу Лезвия Бессмертного. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item Has the power of an Immortal Edge. It cannot be exchanged, dropped, crystallized or possess additional functions.', 'weapon_invincible_blade_i00', 2);
INSERT INTO `all_items` VALUES (9845, 'Shadow Item: Tathlum', NULL, 'Теневой предмет, отражающий силу Татлума. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item Has the power of a Tathlum. It cannot be exchanged, dropped, crystallized or possess additional functions.', 'weapon_taslam_i00', 2);
INSERT INTO `all_items` VALUES (9846, 'Shadow Item: Military Fleuret', NULL, 'Теневой предмет, отражающий силу Боевой Рапиры. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item Has the power of a Military Fleuret. It cannot be exchanged, dropped, crystallized or possess additional functions.', 'weapon_assult_fleuret_i00', 3);
INSERT INTO `all_items` VALUES (9847, 'Shadow Item: Innominate Victory', NULL, 'Теневой предмет, отражающий силу Безымянной Победы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'This Shadow Item Has the power of an Innominate Victory. It cannot be exchanged, dropped, crystallized or possess additional functions.', 'weapon_nameless_victory_i00', 3);
