INSERT INTO `all_items` VALUES (9874, 'Dynasty Cudgel', 'Rsk. Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 164 при HP ниже 60%. Наносит дополнительный урон в PvP.', 'Rsk. Focus	a,<Soul Crystal Enhancement>nIncreases Critical by 164 when HP drops to 6% or below. Increases damage inflicted during PvP.', 'weapon_dynasty_hammer_i01', 5);
