INSERT INTO `all_items` VALUES (9881, 'Diploma', NULL, 'Отдайте этот диплом Второму Иерарху Первану.', 'Give this diploma to Second Hierarch Pervane.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (9882, 'Great Wolf Necklace', NULL, 'Ожерелье для призыва Великого Волка. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon a Great Wolf. The pet takes a portion of the EXP earned by its master.', 'etc_summon_wolf_r_01', 7);
INSERT INTO `all_items` VALUES (9883, 'Teddy Bear Hat', 'Big Head', 'Этот забавный Головной аксессуар в виде медвежонка, увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This fun, bear-shaped hair accessory makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_bear_cap_i00', 0);
INSERT INTO `all_items` VALUES (9884, 'Piggy Hat', 'Big Head', 'Этот забавный Головной аксессуар в виде хрюшки, увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This fun, pig-shaped hair accessory makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_pig_cap_i00', 0);
INSERT INTO `all_items` VALUES (9885, 'Jester Hat', 'Big Head', 'Праздничный шутовской колпак увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This festive, split-top jester hat makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_jester_cap_i00', 0);
INSERT INTO `all_items` VALUES (9886, 'Wizard Hat', 'Big Head', 'Широкополая шляпа чародея увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This Wizard Hat features a wide brim and bent tip and makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_magic_cap_i00', 0);
INSERT INTO `all_items` VALUES (9887, 'Dapper Cap', 'Big Head', 'Кепка с козырьком увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This stylish cap features a visor and makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_dandy_cap_i00', 0);
INSERT INTO `all_items` VALUES (9888, 'Romantic Chapeau', 'Big Head', 'Модная шляпа увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	This extravagant chapeau is adorned with feathers and makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_romantic_chaperon_i00', 0);
INSERT INTO `all_items` VALUES (9889, 'Iron Circlet', 'Big Head', 'Железная диадема увеличивает вашу голову, позволяя использовать активные умения. Требует две ячейки головных уборов.', 'Big Head	Iron circlet that makes your head bigger while allowing you to use active skills. Requires 2 hair accessory slots.', 'accessory_iron_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9890, 'Teddy Bear Hat', 'Firework', 'Этот забавный Головной аксессуар в виде медвежонка позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'This amusing bear cap allows you to use active skills and sets off fireworks when used. Requires 2 hair accessory slots.', 'accessory_bear_cap_i00', 0);
INSERT INTO `all_items` VALUES (9891, 'Piggy Hat', 'Firework', 'Этот забавный Головной аксессуар в виде хрюшки позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	Fun, pig-shaped hair accessory. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_pig_cap_i00', 0);
INSERT INTO `all_items` VALUES (9892, 'Jester Hat', 'Firework', 'Праздничный шутовской колпак позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	Festive jester hat with a split top. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_jester_cap_i00', 0);
INSERT INTO `all_items` VALUES (9893, 'Wizard Hat', 'Firework', 'Широкополая шляпа чародея позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	A Wizard Hat with a wide brim and bent tip. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_magic_cap_i00', 0);
INSERT INTO `all_items` VALUES (9894, 'Dapper Cap', 'Firework', 'Кепка с козырьком позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	Stylish cap with a visor. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_dandy_cap_i00', 0);
INSERT INTO `all_items` VALUES (9895, 'Romantic Chapeau', 'Firework', 'Модная шляпа позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	Extravagant chapeau adorned with feathers. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_romantic_chaperon_i00', 0);
INSERT INTO `all_items` VALUES (9896, 'Iron Circlet', 'Firework', 'Железная диадема позволяет использовать активные умения и запускает фейерверк при использовании. Требует две ячейки головных уборов.', 'Firework	Circlet made of iron. You can use active skills, and firecrackers are set off when it is used. Requires 2 hair accessory slots.', 'accessory_iron_circlet_i00', 0);
INSERT INTO `all_items` VALUES (9897, 'Scroll of Transformation - Pig', NULL, 'Свиток, превращающий вас в свинью на 60 минут. Не действует, если вы уже находитесь в превращенном состоянии.', 'A scroll that transforms you into a pig for 60 minutes. Cannot be used if you are already transformed.', 'etc_trans_4f_s_b_01', 1);
INSERT INTO `all_items` VALUES (9898, 'SP Scroll: Highest Grade', NULL, 'Свиток, который может дать 500 000 SP.', 'A scroll that can grant 500,000 SP.', 'etc_trans_4f_s_b_01', 1);
INSERT INTO `all_items` VALUES (9899, 'Weight Loss Ring', NULL, 'Уменьшает вес, когда экипирован. С дополнительным Кольцом Понижения Веса не действует.', 'Decreases weight when equipped. Effect does not stack with additional Weight Loss Rings.', 'accessary_ring_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (9900, 'Quiet Footsteps Ring', NULL, 'Надев это, вы сможете избежать первой атаки монстров на 400 минут. Теневой предмет, который Нельзя обменять/выбросить. Эффект не суммируется.', 'When equipped, helps you avoid the first monster attack for 400 minutes. A shadow item that cannot be traded or dropped. The effect does not stack.', 'accessary_ring_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (9901, 'Improved Falchion', NULL, 'Улучшенный Фальшион. Больше и мощнее, чем обычный.', 'Improved Falchion. Larger and more powerful than a standard one.', 'weapon_falchion_i00', 0);
INSERT INTO `all_items` VALUES (9902, 'Improved Great Spear', NULL, 'Улучшенное Копье. Больше и мощнее, чем обычное.', 'Improved Spear. Larger and more powerful than a standard one.', 'weapon_long_spear_i00', 0);
INSERT INTO `all_items` VALUES (9903, 'Improved Iron Hammer', NULL, 'Улучшенный Железный Молот. Больше и мощнее, чем обычный.', 'Improved Iron Hammer. Larger and more powerful than a standard one.', 'weapon_iron_hammer_i00', 0);
INSERT INTO `all_items` VALUES (9904, 'Improved Sword Breaker', NULL, 'Улучшенный Мечелом. Больше и мощнее, чем обычный.', 'Improved Swordbreaker. Larger and more powerful than a standard one.', 'weapon_sword_breaker_i00', 0);
INSERT INTO `all_items` VALUES (9905, 'Improved Viper Fang', NULL, 'Улучшенный Клык Гадюки. Больше и мощнее, чем обычный.', 'Improved Viper Fang. Larger and more powerful than a standard one.', 'weapon_vipers_canine_i00', 0);
INSERT INTO `all_items` VALUES (9906, 'Improved Composite Bow', NULL, 'Улучшенный Композитный Лук. Больше и мощнее, чем обычный.', 'Improved Composite Bow. Larger and more powerful than a standard one.', 'weapon_composition_bow_i00', 0);
INSERT INTO `all_items` VALUES (9907, 'Improved Flanged Mace', NULL, 'Улучшенная Палица. Больше и мощнее, чем обычная.', 'Improved Mace. Larger and more powerful than a standard one.', 'weapon_buzdygan_i00', 0);
INSERT INTO `all_items` VALUES (9908, 'Improved Mage Staff', NULL, 'Улучшенный Магический Посох. Больше и мощнее, чем обычный.', 'Improved Magic Staff. Larger and more powerful than a standard one.', 'weapon_apprentices_staff_i00', 0);
INSERT INTO `all_items` VALUES (9909, 'Agathion Seal Bracelet', NULL, 'Браслет, призывающий милого Агатиона Крепости. Теневой предмет, который Нельзя обменять/выбросить. Эффект длится 700 минут.', 'A bracelet that summons a cute Fortress Agathion. A shadow item that cannot be traded or dropped. The effect lasts for 700 minutes.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (9910, 'Blood Oath', NULL, 'Предмет, необходимый главе клана, чтобы поднять свой клан до 9 уровня. Также может быть использован для усиления подчиненных сил. Нельзя продать, выбросить или обменять.', 'An item required for a clan leader to raise their clan to level 9. Can also be used to strengthen subordinate forces. Cannot be sold, dropped, or traded.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (9911, 'Blood Alliance', NULL, 'Предмет, необходимый главе клана, чтобы поднять свой клан до 10 уровня. Также может быть использован для усиления подчиненных сил. Нельзя продать, выбросить или обменять.', 'An item required for a clan leader to raise their clan to level 10. Can also be used to strengthen subordinate forces. Cannot be sold, dropped, or traded.', 'etc_broken_crystal_red_i00', 0);
INSERT INTO `all_items` VALUES (9912, 'Knight\'s Epaulette', NULL, 'Метка, взятая с трупа погибшего врага. Используется для покупки особых предметов после Битвы за Крепость.', 'A token taken from the corpse of a fallen enemy. Used to purchase special items after a Fortress Siege.', 'etc_shoulder_strap_of_knight_i00', 0);
INSERT INTO `all_items` VALUES (9913, 'Talisman_Test', NULL, NULL, NULL, 'etc_crystal_ball_silver_i00', 0);
INSERT INTO `all_items` VALUES (9914, 'Blue Talisman of Power', NULL, 'При использовании увеличивает Физ. Атк. Эффект не суммируется с дополнительным талисманом такого же типа. Теневой предмет, который нельзя продать или выбросить.', 'Increases P. Atk. when in use. Effect does not stack with additional Talismans of the same type. Shadow Item that cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9915, 'Blue Talisman of Wild Magic', NULL, 'Временно увеличивает шанс Крит. Атк. магией. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'Increases P. Critical Rate of magic attacks temporarily. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9916, 'Blue Talisman of Defense', NULL, 'Временно уменьшает защиту/магическое сопротивление/уворот и увеличивает Физ. Атк./силу магии/Скор. Атк./Скор. Маг./Скорость. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'Temporarily decreases P. Def./M. Def./Evasion. Increases P. Atk./M. Atk./Atk. Spd./Casting Spd./speed. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9917, 'Red Talisman of Minimum Clarity', NULL, 'При использовании уменьшает расход MP. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'Decreases skill MP consumption when used. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (9918, 'Red Talisman of Maximum Clarity', NULL, 'При надевании временно, но значительно уменьшает расход MP. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'Temporarily greatly decreases skill MP consumption when used. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (9919, 'Blue Talisman of Reflection', NULL, 'При использовании он будет отражать все полученные повреждения в ближнем бою обратно врагу. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, grants a skill whereby any physical melee damage received will be reflected back onto your attacker. Effect does not stack with additional talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9920, 'Blue Talisman of Invisibility', NULL, 'Делает персонажа невидимым для монстров. Монстры не нападают первыми. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'Makes the character invisible to monsters. Monsters will not attack first. The effect does not stack with an additional talisman of the same type. This item cannot be sold or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9921, 'Blue Talisman - Shield Protection', NULL, 'При использовании увеличивает защитную силу щита. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, increases the protection power of a shield. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9922, 'Black Talisman - Mending', NULL, 'При использовании лечит кровотечение цели. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, it cures Bleeding. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i05', 0);
INSERT INTO `all_items` VALUES (9923, 'Black Talisman - Escape', NULL, 'При использовании отменяет все обездвиживающие состояния. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, it cancels all Movement Inability States. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i05', 0);
INSERT INTO `all_items` VALUES (9924, 'Blue Talisman of Healing', NULL, 'Временно увеличивает силу магии, восстанавливающей HP. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'It increases HP Recovery Magic temporarily. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9925, 'Red Talisman of Recovery', NULL, 'Восстанавливает HP/CP. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'It recovers HP/CP. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (9926, 'Blue Talisman of Defense', NULL, 'При использовании усиливает Физ. Защ. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, increases P. Def. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9927, 'Blue Talisman of Magic Defense', NULL, 'При использовании усиливает магическую защиту. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, increases magic P. Def. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9928, 'Red Talisman of Mental Regeneration', NULL, 'При использовании увеличивает скорость восстановления MP. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, it Speeds up MP recovery. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (9929, 'Blue Talisman of Protection', NULL, 'При использовании увеличивает шанс блока щитом. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, increases the protection power of a shield. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9930, 'Blue Talisman of Evasion', NULL, 'При использовании увеличивает Уклонение и уменьшает Шанс Крит. Удара против вас. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, increases Evasion and decreases the Critical Attack rate against you. The effect does not stack with an additional talisman of the same type. This item cannot be sold or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (9931, 'Red Talisman of Meditation', NULL, 'При использовании значительно увеличивает регенерацию MP. При регенерации вы не можете двигаться. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, it greatly increases MP Recovery Rate. You cannot move during recovery. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (9932, 'Blue Talisman - Divine Protection', NULL, 'При надевании создает временный защитный барьер. Вы становитесь неуязвимы против HP/MP урона. Эффект не суммируется с дополнительным талисманом такого же типа. Этот предмет нельзя продать или выбросить.', 'When used, P. Def. and M. Def. greatly Increases momentarily. Only one effect is applied when you wear the same two talismans. Shadow Item with no exchange/drop available', 'etc_talisman_i01', 0);
