INSERT INTO `all_items` VALUES (9997, 'Fire Potion', NULL, 'На 10 минут увеличивает защиту от атак огня на 30.', 'Increases Fire attack resistance by 30 for 10 minutes.', 'etc_fire_potion_i00', 3);
