INSERT INTO `all_items` VALUES (10099, 'Spellbook - Count of Fire', NULL, 'Книга, необходимая для изучения умения \"Пульсация Огня\". Профессия: Архимаг.', 'A book required to learn the skill \"Fire Surge\". Class: Archmage.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10100, 'Spellbook - Diamond Dust', NULL, 'Книга, необходимая для изучения умения \"Бриллиантовая Пыль\". Профессия: Магистр Магии.', 'A book required to learn the skill \"Diamond Dust\". Class: Mystic Muse.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10101, 'Spellbook - Throne of Ice', NULL, 'Книга, необходимая для изучения умения \"Ледяной Трон\". Профессия: Магистр Магии.', 'A book required to learn the skill \"Throne of Ice\". Class: Mystic Muse.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10102, 'Spellbook - Throne of Wind', NULL, 'Книга, необходимая для изучения умения \"Трон Ветра\". Профессия: Повелитель Бури.', 'A book required to learn the skill \"Throne of Wind\". Class: Storm Screamer.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10103, 'Spellbook - Divine Power', NULL, 'Книга, необходимая для изучения умения \"Сила Небес\". Профессия: Кардинал.', 'A book required to learn the skill \"Divine Power\". Class: Cardinal.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (10104, 'Spellbook - Mana Gain', NULL, 'Книга, необходимая для изучения умения \"Обретение Маны\". Профессии: Жрец Евы, Жрец Шилен.', 'A book required to learn the skill \"Mana Gain\". Classes: Eva\'s Saint, Shillien Saint.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (10105, 'Amulet - Chant of Protection', NULL, 'Амулет, необходимый для изучения умения \"Напев Охраны\". Профессия: Глас Судьбы.', 'An amulet required to learn the skill \"Chant of Protection\". Class: Doomcryer.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (10106, 'Amulet - Seal of Blockade', NULL, 'Амулет, необходимый для изучения умения \"Печать Блокады\". Профессия: Деспот.', 'An amulet required to learn the skill \"Seal of Blockade\". Class: Dominator.', 'etc_orcish_talisman_i00', 0);
INSERT INTO `all_items` VALUES (10107, 'Spellbook - Fire Vortex Buster', NULL, 'Книга, необходимая для изучения умения \"Взрыв Огненного Вихря\". Профессия: Архимаг.', 'A book required to learn the skill \"Count of Fire\". Class: Archmage.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10108, 'Spellbook - Ice Vortex Crusher', NULL, 'Книга, необходимая для изучения умения \"Молот Ледяного Вихря\". Профессия: Магистр Магии.', 'A book required to learn the skill \"Diamond Dust\". Class: Mystic Muse.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10109, 'Spellbook - Wind Vortex Slug', NULL, 'Книга, необходимая для изучения умения \"Порыв Ветряного Вихря\". Профессия: Повелитель Бури.', 'A book required to learn the skill \"Wind Cyclone\". Class: Storm Screamer.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (10110, 'Forgotten Scroll - Meteor', NULL, 'Книга, необходимая для изучения умения \"Метеор\". Профессии: Архимаг, Пожиратель Душ. Достоупно с 81-го уровня.', 'A book required to learn the skill \"Meteor\". Classes: Archmage, Soultaker. Available from Level 81.', 'BranchSys2.Icon.br_spell_books_magic_i01', 0);
INSERT INTO `all_items` VALUES (10111, 'Forgotten Scroll - Star Fall', NULL, 'Книга, необходимая для изучения умения \"Падение Звезды\". Профессии: Магистр Магии, Повелитель Бури. Доступно с 81-го уровня.', 'A book required to learn the skill \"Star Fall\". Classes: Mystic Muse, Storm Screamer. Available from Level 81.', 'BranchSys2.Icon.br_spell_books_magic_i01', 0);
INSERT INTO `all_items` VALUES (10112, 'Dark Seed', NULL, 'Предмет, необходимый для умения \"Насытить Темное Семя\". Нельзя обменять/выбросить.', 'An item required for the skill \"Saturation Dark Seed\". Cannot be traded or dropped.', 'etc_coda_i08', 0);
INSERT INTO `all_items` VALUES (10113, 'Special Bolt', NULL, 'Предмет, необходимый для умений \"Смертельная Рулетка\" и \"Кровавый Выстрел\". Нельзя обменять/выбросить.', 'An item required for the skills \"Death Roulette\" and \"Bleed Shot\". Cannot be traded or dropped.', 'etc_wooden_bolt_i00', 0);
INSERT INTO `all_items` VALUES (10114, 'Sealed Dynasty Sigil Piece', NULL, 'Основной материал, используемый Гномами для создания Запечатанного Символа Династии. Можно продать в Торговой Лавке.', 'A key material used by Dwarves to craft a Sealed Dynasty Sigil. Can be sold at a general shop.', 'etc_plate_silver_i00', 6);
INSERT INTO `all_items` VALUES (10115, 'Recipe: Sealed Dynasty Sigil (60%)', NULL, 'Только для Гномов. Рецепт создания Запечатанного Символа Династии. Требуется умение \"Создать Вещь\" 9-го уровня. Шанс создания: 60%.', 'Dwarves only. A recipe used to craft a Sealed Dynasty Sigil. Requires Create Item Level 9. Success rate: 60%.', 'etc_recipe_black_i00', 5);
INSERT INTO `all_items` VALUES (10116, 'Recipe: Sealed Dynasty Sigil (100%)', NULL, 'Только для Гномов. Рецепт создания Запечатанного Символа Династии. Требуется умение \"Создать Вещь\" 9-го уровня. Шанс создания: 100%.', 'Dwarves only. A recipe used to craft a Sealed Dynasty Sigil. Requires Create Item Level 9. Success rate: 100%.', 'etc_recipe_black_i00', 5);
INSERT INTO `all_items` VALUES (10117, 'Chaotic Sealed Dynasty Sigil', NULL, 'Редкий предмет, Запечатанный Символ Династии, нуждается в полировке. Можно полировать у Кузнеца Маммона.', 'A rare item, Sealed Dynasty Sigil, needs polishing. Can be polished by Blacksmith of Mammon.', 'armor_dynasty_sigil_i01', 0);
INSERT INTO `all_items` VALUES (10118, 'Chaotic Dynasty Sigil', NULL, 'Редкий предмет, Символ Династии, нуждается в полировке. Можно полировать у Кузнеца Маммона.', 'A rare item, Dynasty Sigil, needs polishing. Can be polished by Blacksmith of Mammon.', 'dynasty_sigil_i00', 0);
INSERT INTO `all_items` VALUES (10119, 'Dynasty Sigil', NULL, 'Увеличивает Маг. Защ. и сопротивление тьме.', 'Increases M. Def. and Dark resistance.', 'dynasty_sigil_i00', 0);
INSERT INTO `all_items` VALUES (10120, 'Sealed Dynasty Sigil', NULL, 'Запечатанный Символ Династии, Редкий предмет. Печать можно снять у Кузнеца Маммона или Мастера Ишумы.', 'Sealed Dynasty Sigil, Rare Item. Can be unsealed by Blacksmith of Mammon or Master Ishuma.', 'armor_dynasty_sigil_i01', 0);
INSERT INTO `all_items` VALUES (10121, 'Sealed Arcana Sigil', NULL, 'Запечатанный Символ Аркана, Редкий предмет. Печать можно снять у Кузнеца Маммона.', 'Sealed Arcana Sigil, Rare Item. Can be unsealed by Blacksmith of Mammon.', 'arcana_sigil_i01', 0);
INSERT INTO `all_items` VALUES (10122, 'Red Crescent Earring', NULL, 'Нельзя обменять, выбросить, кристаллизовать и модифицировать.', 'Cannot be exchanged, dropped, crystallized, or modified.', 'accessary_red_cresent_earing_i00', 0);
INSERT INTO `all_items` VALUES (10123, 'Necklace of Devotion', NULL, 'Нельзя обменять, выбросить, кристаллизовать и модифицировать.', 'Cannot be exchanged, dropped, crystallized, or modified.', 'accessary_necklace_of_devotion_i00', 0);
INSERT INTO `all_items` VALUES (10124, 'Ring of Devotion', NULL, 'Нельзя обменять, выбросить, кристаллизовать и модифицировать.', 'Cannot be exchanged, dropped, crystallized, or modified.', 'accessary_ring_of_devotion_i00', 0);
INSERT INTO `all_items` VALUES (10125, 'Shadow Item - War Axe', NULL, 'Теневой предмет с силой Топора Войны. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'A shadow item imbued with the power of the War Axe. Cannot be exchanged, dropped, crystallized, or enchanted.', 'weapon_war_axe_i00', 2);
INSERT INTO `all_items` VALUES (10126, 'Dynasty Leather Armor', 'Force Master', 'Профессии: Дуэлист, Аватар.', 'Classes: Duelist, Grand Khavatari.', 'armor_t92_ud_i00', 0);
INSERT INTO `all_items` VALUES (10127, 'Dynasty Leather Armor', 'Weapon Master', 'Профессии: Полководец, Титан, Кладоискатель, Мастер, Каратель, Инквизитор.', 'Classes: DreadNought, Titan, Fortune Seeker, Maestro, Doombringer, Male Soul Hound.', 'armor_t92_ub_i00', 0);
INSERT INTO `all_items` VALUES (10128, 'For Monster only (Crossbow)', NULL, NULL, NULL, 'weapon_monster_i00', 0);
INSERT INTO `all_items` VALUES (10129, 'Scroll of Escape: Fortress', NULL, 'Магический свиток, с помощью которого можно переместиться в крепость. Если у Вас нет крепости, Вы переместитесь в ближайшее поселение.', 'A magical scroll that teleports you to your fortress. If you do not own a fortress, you will be teleported to the nearest village.', 'etc_scroll_of_return_castle_i00', 1);
INSERT INTO `all_items` VALUES (10130, 'Blessed Scroll of Escape: Fortress', NULL, 'Магический свиток, с помощью которого можно быстро переместиться в крепость.', 'A magical scroll that quickly teleports you to your fortress.', 'etc_scroll_of_return_castle_i01', 1);
INSERT INTO `all_items` VALUES (10131, 'Transformation Scroll: Onyx Beast', NULL, 'Свиток, превращающий вас на 30 минут в Ониксового Зверя.', 'A scroll that transforms you into an Onyx Beast for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10132, 'Transformation Scroll: Death Blader', NULL, 'Свиток, превращающий вас на 30 минут в Роковое Видение.', 'A scroll that transforms you into a Doom Wraith for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10133, 'Transformation Scroll: Grail Apostle', NULL, 'Свиток, превращающий вас на 30 минут в Апостола Грааля.', 'A scroll that transforms you into a Grail Apostle for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10134, 'Transformation Scroll: Unicorn', NULL, 'Свиток, превращающий вас на 30 минут в Единорога.', 'A scroll that transforms you into a Unicorn for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10135, 'Transformation Scroll: Lilim Knight', NULL, 'Свиток, превращающий вас на 30 минут в Рыцаря Лилим.', 'A scroll that transforms you into a Lilim Knight for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10136, 'Transformation Scroll: Golem Guardian', NULL, 'Свиток, превращающий вас на 30 минут в Голема Стражника.', 'A scroll that transforms you into a Golem Guardian for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10137, 'Transformation Scroll: Inferno Drake', NULL, 'Свиток, превращающий вас на 30 минут в Дрейка Инферно.', 'A scroll that transforms you into an Inferno Drake for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10138, 'Transformation Scroll: Dragon Bomber', NULL, 'Свиток, превращающий вас на 30 минут в Панцирного Дракона.', 'A scroll that transforms you into a Dragon Bomber for 30 minutes.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10139, 'Agathion Bracelet', NULL, 'Браслет для призыва Агатиона Радужного Холла Клана. Теневой предмет, который Нельзя обменять/выбросить. Эффект длится 700 мин.', 'A bracelet used to summon a Rainbow Clan Hall Agathion. A shadow item that cannot be traded or dropped. The effect lasts for 700 minutes.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10140, 'Blessed Ring of Escape', NULL, 'Благословенный свиток Возврата, доступен в течение 120 мин. Время перезарядки: 60 секунд. Эффект не суммируется с дополнительными кольцами такого же типа.', 'Blessed Scroll of Escape, available for 120 minutes. Cooldown: 60 seconds. The effect does not stack with additional rings of the same type.', 'accessary_ring_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (10141, 'Grey Talisman - Yeti Transform', NULL, 'Может на время превратить вас в Йети. При снятии предмета трансформация отменяется. Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'Can temporarily transform you into a Yeti. Removing the item cancels the transformation. The effect does not stack with an additional talisman of the same type. This item cannot be sold or dropped.', 'etc_talisman_i07', 0);
INSERT INTO `all_items` VALUES (10142, 'Grey Talisman - Buffalo Transform', NULL, 'Может на время превратить вас в Буйвола. При снятии предмета трансформация отменяется. Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'Can temporarily transform you into a Buffalo. Removing the item cancels the transformation. The effect does not stack with an additional talisman of the same type. This item cannot be sold or dropped.', 'etc_talisman_i07', 0);
INSERT INTO `all_items` VALUES (10143, 'Battleground Spell - Shield Master', NULL, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Благословения Щита Ур. 6 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Wind Walk Lv. 2, Shield Lv. 3, Magic Barrier Lv. 2, Bless Shield Lv. 6, and Haste Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10144, 'Battleground Spell - Wizard', NULL, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Проницательности Ур. 1 и Воодушевления Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Wind Walk Lv. 2, Shield Lv. 3, Magic Barrier Lv. 2, Acumen Lv. 1, and Empower Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10145, 'Battleground Spell - Healer', NULL, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Проницательности Ур. 1 и Воодушевления Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Wind Walk Lv. 2, Shield Lv. 3, Magic Barrier Lv. 2, Acumen Lv. 1, and Empower Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10146, 'Battleground Spell - Dagger Master', NULL, 'Эффекты Легкой Походки Ур. 2, Могущества Ур. 3, Магического Барьера Ур. 2, Фокусировки Ур. 1 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Wind Walk Lv. 2, Might Lv. 3, Magic Barrier Lv. 2, Focus Lv. 1, and Haste Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10147, 'Battleground Spell - Bow Master', NULL, 'Эффекты Легкой Походки Ур. 2, Могущества Ур. 3, Магического Барьера Ур. 2, Наведения Ур. 1 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Wind Walk Lv. 2, Might Lv. 3, Magic Barrier Lv. 2, Guidance Lv. 1, and Haste Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10148, 'Battleground Spell - Berserker', NULL, 'Эффекты Духа Берсерка Ур. 2 и Чистоты Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Effects of Berserker Spirit Lv. 2 and Clarity Lv. 1 can be obtained for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (10149, 'Battleground Blessed Scroll of Escape', NULL, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение. Используется только при осаде или битве за Крепость.', 'A magical scroll that teleports you to the nearest village. Can only be used during a Castle Siege or Fortress Battle.', 'etc_scroll_of_return_i00', 1);
INSERT INTO `all_items` VALUES (10150, 'Battleground Blessed Scroll of Resurrection', NULL, 'Воскрешает мертвого персонажа и полностью восстанавливает его опыт. Используется только при Осаде или Битве за Крепость.', 'Resurrects a dead character and completely restores their Lost EXP. Can only be used during a Castle Siege or Fortress Battle.', 'etc_scroll_of_resurrection_i00', 1);
INSERT INTO `all_items` VALUES (10151, 'Battleground Transform Spell', NULL, 'При использовании превращает вас в Фею на определенное время. Можно использовать только на поле боя при Осаде или Битве за Крепость. Не действует, если вы уже превращены.', 'When used, transforms you into a Pixy for a certain period of time. Can only be used on the battlefield during a Castle Siege or Fortress Battle. Does not work if you are already transformed.', 'etc_trans_4f_s_b_01', 1);
INSERT INTO `all_items` VALUES (10152, 'Battle Health Recovery Potion', NULL, 'При использовании восстанавливает HP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'When used, restores HP. Does not affect characters below Lv. 52. Can only be used during a Castle Siege or Fortress Battle.', 'etc_super_hp_potion_i00', 24);
INSERT INTO `all_items` VALUES (10153, 'Battle Mana Recovery Potion', NULL, 'При использовании восстанавливает MP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'When used, restores MP. Does not affect characters below Lv. 52. Can only be used during a Castle Siege or Fortress Battle.', 'etc_super_mp_potion_i00', 24);
INSERT INTO `all_items` VALUES (10154, 'Battle CP Recovery Potion', NULL, 'При использовании восстанавливает СP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'When used, restores CP. Does not affect characters below Lv. 52. Can only be used during a Castle Siege or Fortress Battle.', 'etc_super_cp_potion_i00', 24);
INSERT INTO `all_items` VALUES (10155, 'Mental Strengthening Potion', NULL, 'Увеличивает сопротивление удержанию и усыплению на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'Increases resistance to Hold and Sleep for a certain period of time. Available only during Castle Sieges and Fortress Battles.', 'etc_lesser_potion_yellow_i00', 3);
INSERT INTO `all_items` VALUES (10156, 'Medusa\'s Potion', NULL, 'Временно делает неуязвимым. Доступно только при Осаде и Воине за Крепость.', 'Renders you invulnerable for a short time. Available only during Castle Sieges and Fortress Battles.', 'etc_lesser_potion_yellow_i00', 3);
INSERT INTO `all_items` VALUES (10157, 'Instant Haste Potion', NULL, 'Немедленно увеличивает Скорость. Доступно только при Осаде и Воине за Крепость.', 'Instantly increases Speed. Available only during Castle Sieges and Fortress Battles.', 'etc_lesser_potion_yellow_i00', 3);
INSERT INTO `all_items` VALUES (10158, 'Grey Talisman of Upper Grade Fishing', NULL, 'Дарует Мастерство Рыболова высокого ранга (Ур.24). Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'Grants High-Grade Fishing Expertise (Lv. 24). The effect does not stack with an additional talisman of the same type. This item cannot be sold or dropped.', 'etc_talisman_i07', 0);
INSERT INTO `all_items` VALUES (10159, 'Capture Rope', NULL, 'Обездвиживает цель. Используется только при и Осаде или Битвы за Крепость.', 'Immobilizes the target. Can only be used during a Castle Siege or Fortress Battle.', 'etc_braided_hemp_i00', 3);
INSERT INTO `all_items` VALUES (10160, 'Cursed Red Soul Crystal - Stage 14', NULL, 'Красный кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'A red crystal imbued with the Curse of Darkness, Level 14. Take it to Legendary Blacksmith Shadai on Hellbound to process it.', 'etc_broken_crystal_red_i00', 1);
INSERT INTO `all_items` VALUES (10161, 'Cursed Blue Soul Crystal - Stage 14', NULL, 'Синий кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'A blue crystal imbued with the Curse of Darkness, Level 14. Take it to Legendary Blacksmith Shadai on Hellbound to process it.', 'etc_broken_crystal_blue_i00', 1);
INSERT INTO `all_items` VALUES (10162, 'Cursed Green Soul Crystal - Stage 14', NULL, 'Зеленый кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'A green crystal imbued with the Curse of Darkness, Level 14. Take it to Legendary Blacksmith Shadai on Hellbound to process it.', 'etc_broken_crystal_green_i00', 1);
INSERT INTO `all_items` VALUES (10163, 'Wolf Collar', NULL, 'Ожерелье для призыва волков. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon a Wolf. The pet takes a portion of the EXP earned by its master.', 'etc_prefect_belt_i00', 7);
INSERT INTO `all_items` VALUES (10164, 'Animal Slayer\'s List', NULL, 'Уничтожайте Багровых Пауков в Лесу Мимира.', 'Slay Crimson Spiders in Mimir\'s Forest.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (10165, 'Bloody Red Claw', NULL, 'Окровавленный коготь. Соберите 50 таких и отдайте Мартину, Управляющему Питомцами Города Глудин.', 'A bloody claw. Collect 50 of these and give them to Pet Manager Martin in the Town of Gludin.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (10166, 'Hot Springs CP Potion', NULL, 'При использовании восстанавливает CP.', 'When used, restores CP.', 'etc_hot_spring_mineral_i00', 24);
INSERT INTO `all_items` VALUES (10167, 'Pig Lollipop', NULL, 'Магический леденец с хрюшкой. Если использовать его для атаки, он будет визжать. На короткое время превращает персонажа в свинью. Этот предмет нельзя продать или выбросить, но можно положить на хранение. Памятный предмет 4-й годовщины игры.', 'A magical piggy lollipop. If used to attack, it squeaks. Temporarily turns the character into a pig. This item cannot be sold or dropped, but can be deposited into freight. A 4th Anniversary Commemorative Item.', 'etc_pig_candy_i00', 0);
INSERT INTO `all_items` VALUES (10168, 'Dynasty Leather Armor', 'Enchanter', 'Профессии: Апостол, Деспот, Глас Судьбы, Арбитр.', 'Classes: Hierophant, Dominator, Doomcryer, Inspector.', 'armor_t92_ud_i00', 0);
INSERT INTO `all_items` VALUES (10169, 'Enchanter Circlet (Kamael only)', NULL, 'Только для Камаэль. Головной аксессуар для Зачарователей после 2-й или 3-й смены профессии. Нельзя носить в состоянии подкласса. Требует две ячейки головных уборов.', 'Kamael only. A head accessory for Enchanters after their 2nd or 3rd Class Transfer. Cannot be equipped while in subclass state. Requires 2 hair accessory slots.', 'accessary_weapon_master_circlet_i00', 0);
INSERT INTO `all_items` VALUES (10170, 'Baylor\'s Earring', NULL, 'Сопротивление тьме +30, MP+31.', 'Dark Resistance +30, MP +31.', 'accessary_dynasty_earing_i00', 0);
INSERT INTO `all_items` VALUES (10171, 'Seed: Dark Coda', NULL, 'Семя Темной Коды. Для получения плода вживите его в монстра в районе Адена. Наилучшего результата можно достичь, если персонаж и монстр 5-15 уровней.', 'Dark Coda Seed. Implant it into a monster in the Aden territory to reap the fruit. Best results are achieved if the character and monster are between Lv. 5-15.', 'etc_coda_seed_i00', 10);
INSERT INTO `all_items` VALUES (10172, 'Seed: Red Coda', NULL, 'Семя Красной Коды. Для получения плода вживите его в монстра в районе Адена. Наилучшего результата можно достичь, если персонаж и монстр 8-18 уровней.', 'Red Coda Seed. Implant it into a monster in the Aden territory to reap the fruit. Best results are achieved if the character and monster are between Lv. 8-18.', 'etc_coda_seed_i00', 10);
INSERT INTO `all_items` VALUES (10173, 'Seed: Chilly Coda', NULL, 'Семя Холодной Коды. Для получения плода вживите его в монстра в районе Адена. Наилучшего результата можно достичь, если персонаж и монстр 11-21 уровней.', 'Chilly Coda Seed. Implant it into a monster in the Aden territory to reap the fruit. Best results are achieved if the character and monster are between Lv. 11-21.', 'etc_coda_seed_i00', 10);
INSERT INTO `all_items` VALUES (10174, 'Seed: Blue Coda', NULL, 'Семя Синей Коды. Для получения плода вживите его в монстра в районе Адена. Наилучшего результата можно достичь, если персонаж и монстр 14-24 уровней.', 'Blue Coda Seed. Implant it into a monster in the Aden territory to reap the fruit. Best results are achieved if the character and monster are between Lv. 14-24.', 'etc_coda_seed_i00', 10);
INSERT INTO `all_items` VALUES (10175, 'Goblin Circlet (Event)', NULL, 'Диадема в форме гоблина золотого цвета. Этот предмет изготовлен только для ивента и не может быть обменян или выброшен.', 'A golden goblin-shaped circlet. This item was created for an event only and cannot be traded or dropped.', 'accessory_taiwan_i00', 0);
INSERT INTO `all_items` VALUES (10176, 'White Half Mask', NULL, 'Мистический аксессуар, закрывающий половину лица. Нельзя продать или выбросить.', 'A mystical accessory that covers half of the face. Cannot be sold or dropped.', 'accessory_half_face_i00', 0);
INSERT INTO `all_items` VALUES (10177, 'Black Half Mask', NULL, 'Мистическая черная маска. Хотите знать, где ее вторая половина? Нельзя продать или выбросить. Памятный предмет 4-й годовщины игры.', 'A mystical black mask. Wondering where the other half is? Cannot be sold or dropped. A 4th Anniversary Commemorative Item.', 'Accessary_black_half_mask_i00', 0);
INSERT INTO `all_items` VALUES (10178, 'Sweet Fruit Cocktail', NULL, 'Коктейль, приготовленный из редких фруктов, дарует временные эффекты Могущества, Щита, Легкой Походки, Фокусировки, Смертельного Шепота, Наведения, Благословения Щита, Благословения Тела, Ускорения и Ярости Вампира.', 'A cocktail made from rare fruits that grants temporary effects of Might, Shield, Wind Walk, Focus, Death Whisper, Guidance, Bless Shield, Bless the Body, Haste, and Vampiric Rage.', 'etc_fruit_cocktail_i00', 3);
INSERT INTO `all_items` VALUES (10179, 'Fresh Fruit Cocktail', NULL, 'Коктейль, приготовленный из редких фруктов, дарует временные эффекты Духа Берсерка, Благословения Тела, Магического Барьера, Щита, Легкой Походки, Благословения Души, Воодушевления, Проницательности и Чистоты.', 'A cocktail made from rare fruits that grants temporary effects of Berserker Spirit, Bless the Body, Magic Barrier, Shield, Wind Walk, Bless the Soul, Empower, Acumen, and Clarity.', 'etc_fruit_cocktail_i01', 3);
INSERT INTO `all_items` VALUES (10180, 'Battle Manual - Penetrate Shot', NULL, 'Книга, необходимая для изучения умения \"Проникающий Выстрел\". Профессия: Надзиратель.Необходимый уровень: 20.', 'A book required to learn the skill \"Penetrating Shot\". Class: Warder. Required Level: 20.', 'etc_kamael_skill_book_i00', 0);
