INSERT INTO `all_items` VALUES (10203, 'Spellbook - Empowering Echo', NULL, 'Книга, необходимая для изучения умения \"Благословляющее Эхо\". Профессия: Повелитель Бури.', 'A book required to learn the skill \"Echo of Blessing\". Class: Storm Screamer.', 'etc_spell_books_element_i00', 0);
