INSERT INTO `all_items` VALUES (10207, 'Enhanced Striped Scale Shirt', NULL, 'Увеличивает Макс. MP на 35, и Маг. Защ.', 'Increases Max MP by 35 and M. Def.', 'etc_stripe_shirts_a_i04', 0);
INSERT INTO `all_items` VALUES (10208, 'Enhanced Striped Mithril Shirt', NULL, 'Увеличивает Макс. MP на 70, и Маг. Защ. На 50.', 'Increases Max MP by 70 and M. Def. by 50.', 'etc_stripe_shirts_s_i05', 0);
INSERT INTO `all_items` VALUES (10209, 'Enhanced Steel Bracelet', NULL, 'При надевании добавляет 3 ячейки талисманов. Увеличивает Макс. MP на 60.', 'When equipped, unlocks 3 talisman slots. Increases Max MP by 60.', 'etc_rbracelet_a_i02', 0);
INSERT INTO `all_items` VALUES (10210, 'Enhanced Mithril Bracelet', NULL, 'При надевании добавляет активирует 4 ячейки талисманов. Увеличивает Макс. MP на 120.', 'When equipped, unlocks 4 talisman slots. Increases Max MP by 120.', 'etc_rbracelet_s_i03', 0);
INSERT INTO `all_items` VALUES (10211, 'Blessed Ring of Resurrection', NULL, 'Благословенное Воскрешение на 120 мин. Эффект не суммируется с дополнительным кольцом такого же типа.', 'Blessed Resurrection for 120 minutes. The effect does not stack with an additional ring of the same type.', 'accessary_ring_of_mana_i00', 0);
INSERT INTO `all_items` VALUES (10212, 'For NPC (Bow)', NULL, NULL, NULL, 'weapon_monster_i00', 0);
INSERT INTO `all_items` VALUES (10214, 'Dynasty Leather Armor', 'Summoner', 'Профессии: Чернокнижник, Мастер Стихий, Владыка Теней.', 'Classes: Arcana Lord, Elemental Master, Spectral Master.', 'armor_t92_u_i00', 0);
INSERT INTO `all_items` VALUES (10215, 'Icarus Sawsword', NULL, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.', 'Grants one of the following special abilities: Focus, Health, or Light.', 'weapon_icarus_sowsword_i00', 6);
INSERT INTO `all_items` VALUES (10216, 'Icarus Disperser', NULL, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Уклонение или Крит. Урон.', 'Grants one of the following special abilities: Focus, Evasion, or Critical Damage.', 'weapon_icarus_disperser_i00', 6);
INSERT INTO `all_items` VALUES (10217, 'Icarus Spirit', NULL, 'Дает возможность получить одно из следующих особых свойств: Проницательность, Увеличение Маны или Конверсия.', 'Grants one of the following special abilities: Acumen, Mana Up, or Conversion.', 'weapon_icarus_spirits_i00', 6);
INSERT INTO `all_items` VALUES (10218, 'Icarus Heavy Arms', NULL, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.', 'Grants one of the following special abilities: Focus, Health, or Light.', 'weapon_icarus_heavy_arms_i00', 6);
INSERT INTO `all_items` VALUES (10219, 'Icarus Trident', NULL, 'Дает возможность получить одно из следующих особых свойств: Ярость, Крит. Оглушение или Легкость.', 'Grants one of the following special abilities: Anger, Critical Stun, or Light.', 'weapon_icarus_trident_i00', 6);
INSERT INTO `all_items` VALUES (10220, 'Icarus Hammer', NULL, 'Дает возможность получить одно из следующих особых свойств: Ярость, Здоровье или Риск. Фокусировка.', 'Grants one of the following special abilities: Anger, Health, or Risk Focus.', 'weapon_icarus_hammer_i00', 6);
INSERT INTO `all_items` VALUES (10221, 'Icarus Hand', NULL, 'Дает возможность получить одно из следующих особых свойств: Риск. Уклонение, Фокусировка или Ускорение.', 'Grants one of the following special abilities: Risk Evasion, Focus, or Haste.', 'weapon_icarus_knuckle_i00', 6);
INSERT INTO `all_items` VALUES (10222, 'Icarus Hall', NULL, 'Дает возможность получить одно из следующих особых свойств: Увеличение Маны, Конверсия или Проницательность.', 'Grants one of the following special abilities: Mana Up, Conversion, or Acumen.', 'weapon_icarus_stick_i00', 6);
INSERT INTO `all_items` VALUES (10223, 'Icarus Spitter', NULL, 'Дает возможность получить одно из следующих особых свойств: Экономия, Наведение или Фокусировка.', 'Grants one of the following special abilities: Cheap Shot, Guidance, or Focus.', 'weapon_icarus_spiter_i00', 6);
INSERT INTO `all_items` VALUES (10224, 'Icarus Stinger', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Зазубренного Меча ИкараДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Icarus Sawsword Conversion. Grants one of the following special abilities: Focus, Health, or Light. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_icarus_stinger_i00', 6);
INSERT INTO `all_items` VALUES (10225, 'Icarus Wingblade', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук ИкараДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.', 'Kamael Exclusive Weapon: Icarus Heavy Arms Conversion. Grants one of the following special abilities: Focus, Health, or Light.', 'weapon_icarus_wing_blade_i00', 6);
INSERT INTO `all_items` VALUES (10226, 'Icarus Shooter', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Лука ИкараДает возможность получить одно из следующих особых свойств: Экономия, Наведение или Фокусировка.', 'Kamael Exclusive Weapon: Icarus Bow Conversion. Grants one of the following special abilities: Cheap Shot, Guidance, or Focus.', 'weapon_icarus_shooter_i00', 6);
