INSERT INTO `all_items` VALUES (10260, 'Alacrity Juice', NULL, 'Напиток, сделанный из редких фруктов. При использовании увеличивает Скор. Атк. на 33%.', 'A drink made from rare fruits. When used, increases Atk. Spd. by 33%.', 'etc_fruit_juice_glass_bottle_i00', 1);
INSERT INTO `all_items` VALUES (10261, 'Accuracy Juice', NULL, 'Напиток, сделанный из редких фруктов. Увеличивает Точность на 4 при использовании.', 'A drink made from rare fruits. Increases Accuracy by 4 when used.', 'etc_fruit_juice_glass_bottle_i01', 1);
INSERT INTO `all_items` VALUES (10262, 'Critical Hit Juice', NULL, 'Напиток, сделанный из редких фруктов. Увеличивает силу Крит. Атк. на 35% при использовании.', 'A drink made from rare fruits. Increases Critical Damage by 35% when used.', 'etc_fruit_juice_glass_bottle_i02', 1);
