INSERT INTO `all_items` VALUES (10264, 'Casting Spd. Juice', NULL, 'Напиток, сделанный из редких фруктов. Увеличивает Скор. Маг. На 30% при использовании.', 'A drink made from rare fruits. Increases Casting Spd. by 30% when used.', 'etc_fruit_juice_glass_bottle_i04', 1);
