INSERT INTO `all_items` VALUES (10270, 'MP Consumption Juice', NULL, 'Напиток, сделанный из редких фруктов. Уменьшает расход MP на физические умения на 10%, расход MP на магические умения на 4%, а расход МР для физических навыков пения и танца на 10%.', 'A drink made from rare fruits. Reduces MP consumption for physical skills by 10%, magical skills by 4%, and song/dance physical skills by 10%.', 'etc_fruit_juice_glass_bottle_i10', 0);
