INSERT INTO `all_items` VALUES (10280, 'Certificate - Emergent Ability', NULL, 'Сертификат, необходимый для изучения Новых Навыков. Только основные классы могут учить это умение. Этот предмет нельзя обменять, выбросить, уничтожить и отдать на хранение.', 'A certificate required to learn New Skills. Only main classes can learn this skill. This item cannot be traded, dropped, destroyed, or deposited into warehouse.', 'etc_all_subjob_skillbook_i00', 0);
INSERT INTO `all_items` VALUES (10281, 'Certificate - Warrior Ability', NULL, 'Сертификат, необходимый для изучения Навыков Воителя. Только основные классы могут учить это умение. Этот предмет нельзя обменять, выбросить, уничтожить и отдать на хранение.', 'A certificate required to learn Warrior Skills. Only main classes can learn this skill. This item cannot be traded, dropped, destroyed, or deposited into warehouse.', 'etc_warrior_subjob_skillbook_i00', 0);
INSERT INTO `all_items` VALUES (10282, 'Certificate - Knight Ability', NULL, 'Сертификат, необходимый для изучения Навыков Рыцаря. Только основные классы могут учить это умение. Этот предмет нельзя обменять, выбросить, уничтожить и отдать на хранение.', 'A certificate required to learn Knight Skills. Only main classes can learn this skill. This item cannot be traded, dropped, destroyed, or deposited into warehouse.', 'etc_knight_subjob_skillbook_i00', 0);
