INSERT INTO `all_items` VALUES (10297, 'Transformation Sealbook: Venom', NULL, 'Описание способа превращения в Бенома.', 'A description of how to transform into Venom.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10298, 'Transformation Sealbook: Gordon', NULL, 'Описание способа превращения в Гордона.', 'A description of how to transform into Gordon.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10299, 'Transformation Sealbook: Ranku', NULL, 'Описание способа превращения в Ранку.', 'A description of how to transform into Ranku.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10300, 'Transformation Sealbook  - Kechi', NULL, 'Описание способа превращения в Кечи.', 'A description of how to transform into Kechi.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10301, 'Transformation Sealbook: Demon Prince', NULL, 'Книга, в которой описан способ превращения в Принца Демонов.', 'A book describing how to transform into the Demon Prince.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10302, 'Transformation Sealbook: Heretic', NULL, 'Описание способа превращения в Еретика.', 'A description of how to transform into Heretic.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10303, 'Transformation Sealbook: Veil Master', NULL, 'Описание способа превращения в Мастера Долин.', 'A description of how to transform into Vale Master.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10304, 'Transformation Sealbook: Saber Tooth Tiger', NULL, 'Описание способа превращения в Саблезубого Тигра.', 'A description of how to transform into Saber-Tooth Tiger.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10305, 'Transformation Sealbook: Oel Mahum', NULL, 'Описание способа превращения в Сфинкса.', 'A description of how to transform into Olym.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10306, 'Transformation Sealbook: Doll Blader', NULL, 'Описание способа превращения в Куклу.', 'A description of how to transform into Doll Blader.', 'BranchSys2.etc_sb_transform_i00', 0);
INSERT INTO `all_items` VALUES (10307, 'Great Snow Wolf Necklace', NULL, 'Ожерелье для призыва Гигантского Снежного Волка. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon a Giant Snow Wolf. The pet takes a portion of the EXP earned by its master.', 'etc_summon_wolf_r_01', 7);
INSERT INTO `all_items` VALUES (10308, 'Red Dragon Bugle of Wind', NULL, 'Горн для призыва Красного Ездового Дракона Ветра. Питомец забирает часть опыта, заработанного хозяином.', 'A horn used to summon a Red Wind Strider. The pet takes a portion of the EXP earned by its master.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (10309, 'Red Dragon Bugle of Star', NULL, 'Горн для призыва Красного Ездового Дракона Звезд. Питомец забирает часть опыта, заработанного хозяином.', 'A horn used to summon a Red Star Strider. The pet takes a portion of the EXP earned by its master.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (10310, 'Red Dragon Bugle of Twilight', NULL, 'Горн для призыва Красного Ездового Дракона Сумерек. Питомец забирает часть опыта, заработанного хозяином.', 'A horn used to summon a Red Twilight Strider. The pet takes a portion of the EXP earned by its master.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (10311, 'Improved Buffalo Panpipe', NULL, 'Ожерелье для призыва Подросшего Детеныша Буйвола. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon an Improved Baby Buffalo. The pet takes a portion of the EXP earned by its master.', 'etc_buffalo_panpipe_i00', 7);
INSERT INTO `all_items` VALUES (10312, 'Improved Cougar Chime', NULL, 'Ожерелье для призыва Подросшего Детеныша Кугуара. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon an Improved Baby Kookaburra. The pet takes a portion of the EXP earned by its master.', 'etc_cougar_chime_i00', 7);
INSERT INTO `all_items` VALUES (10313, 'Improved Kookaburra Ocarina', NULL, 'Ожерелье для призыва Подросшего Детеныша Кукубарры. Питомец забирает часть опыта, заработанного хозяином.', 'A necklace used to summon an Improved Baby Cougar. The pet takes a portion of the EXP earned by its master.', 'etc_kukaburo_ocarina_i00', 7);
INSERT INTO `all_items` VALUES (10314, 'Ring of Beleth', NULL, 'Кольцо, которое Белеф дал Тулли. Дарует магическое сопротивление +12%,', 'A ring given to Tully by Beleth. Grants M. Def. +12%.', 'accessary_dynasty_ring_i00', 0);
INSERT INTO `all_items` VALUES (10315, 'Shadow Item - Purple Viking Circlet', NULL, 'Требует две ячейки головных уборов. Этот предмет Нельзя обменять/выбросить. Эффект длится 500 мин.', 'Requires 2 hair accessory slots. This item cannot be traded or dropped. The effect lasts for 500 minutes.', 'accessory_viking_circlet_violet_i00', 0);
INSERT INTO `all_items` VALUES (10316, 'Agathion Seal Bracelet - Little Angel', 'Firework', 'Браслет для призыва милого маленького ангела Агатиона. Нельзя обменять/выбросить.', 'An agathion bracelet used to summon a cute little angel. Cannot be traded or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10317, 'Agathion Seal Bracelet - Little Angel', 'Big Head', 'Браслет для призыва милого маленького ангела Агатиона. Нельзя обменять/выбросить.', 'An agathion bracelet used to summon a cute little angel. Cannot be traded or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10318, 'Agathion Seal Bracelet - Little Angel', 'Escape', 'Браслет для призыва милого маленького ангела Агатиона. Нельзя обменять/выбросить.', 'An agathion_bracelet used to summon a cute little angel. Cannot be traded or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
