INSERT INTO `all_items` VALUES (10321, 'Shadow Item - Golden Viking Circlet', NULL, 'Требует две ячейки головных уборов. Этот предмет Нельзя обменять/выбросить. Эффект длится 500 мин.', 'Requires 2 hair accessory slots. This item cannot be traded or dropped. The effect lasts for 500 minutes.', 'accessory_viking_circlet_gold_i00', 0);
INSERT INTO `all_items` VALUES (10322, 'Agathion Seal Bracelet - Little Devil', 'Firework', 'Браслет для призыва милого маленького дьявола Агатиона. Нельзя продать или выбросить.', 'An agathion bracelet used to summon a cute little devil. Cannot be sold or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10323, 'Agathion Seal Bracelet - Little Devil', 'Big Head', 'Браслет для призыва милого маленького дьявола Агатиона. Нельзя продать или выбросить.', 'An agathion bracelet used to summon a cute little devil. Cannot be sold or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
