INSERT INTO `all_items` VALUES (10325, 'Agathion Seal Bracelet - Little Devil', 'Resurrection', 'Браслет для призыва милого маленького дьявола Агатиона. Нельзя продать или выбросить.', 'An agathion bracelet used to summon a cute little devil. Cannot be sold or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10326, 'Agathion Seal Bracelet - Little Devil', NULL, 'Браслет для призыва милого маленького дьявола Агатиона. Нельзя продать или выбросить.', 'An agathion bracelet used to summon a cute little devil. Cannot be sold or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (10327, 'Evil Weapon', NULL, 'Это оружие можно добыть только у злых духов, созданных в Литейной Монстров.', 'This weapon can only be obtained from evil spirits created in the Monster Foundry.', 'etc_sting_b_i00', 0);
INSERT INTO `all_items` VALUES (10328, 'Stolen Cargo', NULL, 'Груз, украденный у Смотрителя Склада Сонина из Деревни Флоран. Возвращайтесь к Сонину.', 'Cargo stolen from Warehouse Keeper Sonin in the Town of Floran. Return to Sonin.', 'etc_wine_barrel_i00', 0);
INSERT INTO `all_items` VALUES (10329, 'Hate Crystal', NULL, 'Важный предмет, который требуется Бакалейщику Пано в Деревне Флоран.', 'An important item requested by Grocer Pano in the Town of Floran.', 'etc_stone_gray_i00', 0);
INSERT INTO `all_items` VALUES (10330, 'Old Treasure Map', NULL, 'Важный предмет, который требуется Капитану Алексу в Деревне Флоран.', 'An important item requested by Captain Alex in the Town of Floran.', 'etc_map_yellow_i00', 0);
INSERT INTO `all_items` VALUES (10331, 'Sonin\'s Credentials', NULL, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Пано и Алекса.', 'Take this to Priest Shegfield in the Town of Dion along with Pano\'s and Alex\'s certificates.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (10332, 'Pano\'s Credentials', NULL, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Сонина и Алекса.', 'Take this to Priest Shegfield in the Town of Dion along with Sonin\'s and Alex\'s certificates.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (10333, 'Alex\'s Credentials', NULL, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Пано и Сонина.', 'Take this to Priest Shegfield in the Town of Dion along with Pano\'s and Sonin\'s certificates.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (10334, 'Badge - Temple Executor', NULL, 'Отнесите это Верховному Жрецу Сильвиану вместе со свидетельством Храма Эйнхасад и значком Миссионера Храма.', 'Take this to High Priest Sylvain along with the Einhasad Temple Certificate and the Temple Missionary Badge.', 'etc_jewel_white_i00', 0);
INSERT INTO `all_items` VALUES (10335, 'Giants\' Experimental Tool Fragment', NULL, 'Реликвия Гигантов, найденная у монстров и отступников в Топях Крума. Отдайте ее Продавцу Книг Заклинаний Роуку.', 'A Giant relic found on monsters and renegades in the Cruma Marshlands. Give it to Spellbook Trader Rouke.', 'etc_mechanic_box_i00', 0);
INSERT INTO `all_items` VALUES (10336, 'Giants\' Experimental Tool', NULL, 'Созданные Гигантами инструменты для опытов. Можно использовать для приманки отступников в Топях Крумы.', 'Giant-made experimental tools. Can be used to lure renegades in the Cruma Marshlands.', 'etc_instrument_i00', 0);
INSERT INTO `all_items` VALUES (10337, 'Giants\' Technology Report', NULL, 'Доказательство смерти предателя, убитого в Топях Крума. Отдайте Продавцу Книг Заклинаний Роуку.', 'Proof of death of a traitor killed in the Cruma Marshlands. Give it to Spellbook Trader Rouke.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (10338, 'Rouke\'s Report', NULL, 'Отчет Роука. Отнесите его Жрице Гливке.', 'Rouke\'s report. Take it to Priestess Gleevia.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (10339, 'Badge - Temple Missionary', NULL, 'Отнесите это Верховному Жрецу Сильвиану вместе со свидетельством Храма Эйнхасад и значком Палача Храма.', 'Take this to High Priest Sylvain along with the Einhasad Temple Certificate and the Temple Executioner Badge.', 'etc_jewel_silver_i00', 0);
INSERT INTO `all_items` VALUES (10340, 'Report Fragment', NULL, 'Фрагмент отчета об исследовании, принадлежавший пропавшему исследователю храма. Отдайте Верховному Жрецу Сильвиану.', 'A fragment of a research report belonging to a missing temple researcher. Give it to High Priest Sylvain.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (10341, 'Temple Manifesto', NULL, 'Манифест Храма, описывающий только права.', 'A Temple manifesto detailing rights only.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (10342, 'Relics of the Dark Elf Trainee', NULL, 'Вещь ученика Темных Эльфов, убитого во время тренировки. Отдайте Темному Эльфу Ангусу.', 'An item belonging to a Dark Elf trainee killed during practice. Give it to Dark Elf Angus.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (10343, 'Angus\' Recommendation', NULL, 'Значок, данный Ангусом в знак благодарности. Покажите его Жрице Пупине.', 'A badge given by Angus as a token of gratitude. Show it to Priestess Pupina.', 'etc_paper_blue_i00', 0);
INSERT INTO `all_items` VALUES (10344, 'Pupina\'s Recommendation', NULL, 'Рекомендация, дающая право общаться с проповедниками. Покажите ее Проповеднику Сла.', 'A recommendation granting the right to speak with preachers. Show it to Preacher Sla.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (10345, 'Records Chest Key Fragment', NULL, 'Обломок ключа Ящера Тасаба. Если вы отнесете его Смотрителю Склада Мии, она обменяет его на Ключ от Сундука с Записями.', 'A fragment of a Tasaba Lizardman key. If you take it to Warehouse Keeper Mia, she will exchange it for a Record Box Key.', 'etc_old_key_i00', 0);
INSERT INTO `all_items` VALUES (10346, 'Records Chest', NULL, 'Ящик с Записями Ящера Тасаба. Отдайте его Смотрителю Склада Мии, чтобы посмотреть содержимое.', 'Tasaba Lizardman Record Box. Give it to Warehouse Keeper Mia to inspect its contents.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (10347, 'Dark Crystal', NULL, 'Ингредиент для изготовления Темного Оксида. Отдайте мастеру Ксеновии.', 'An ingredient for making Dark Oxide. Give it to Master Xenovia.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (10348, 'Dark Oxide', NULL, 'Субстанция, необходимая Ксеновии для экспериментов.', 'A substance required by Xenovia for her experiments.', 'etc_dragons_blood_i02', 0);
INSERT INTO `all_items` VALUES (10349, 'Cryptogram of the Goddess Sword', NULL, 'Секретный документ сделки с Мечом Богини, который Ева, Богиня Озера, даровала Лионелю. Принесите его Рабочему Склада Клаку.', 'A secret deal document regarding the Goddess\' Sword, which Eva, Goddess of the Lake, bestowed upon Lionel. Bring it to Warehouse Worker Clack.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (10350, 'Predecessor\'s Report', NULL, 'Отчет об исследованиях, в котором описана смерть Сумрачного Лиса. Отдайте его Начальнику Склада Натулсу.', 'A research report detailing the death of the Shadow Fox. Give it to Warehouse Chief Natuls.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (10351, 'Cryptogram of the Angel Search', NULL, 'Разметка местонахождения ангелов, открытых Исследовательским агентством Сумрачного Лиса. Зашифровано как Криптограмма. Расшифруйте ее с помощью Верховного Жреца Раймонда в Городе Глудио.', 'A map marking the locations of angels discovered by the Shadow Fox Research Agency. Encrypted as a cryptogram. Decipher it with the help of High Priest Raymond in the Town of Gludio.', 'etc_piece_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (10352, 'Prophecy Fragment', NULL, 'Пророчество – Путь Бога. Когда фрагменты пророчества будут собраны, они откроют вам местонахождение Падших Ангелов.', 'Prophecy - The Path of God. When the fragments of the prophecy are gathered, they will reveal the location of the Fallen Angels.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (10353, 'Fallen Angel Blood', NULL, 'Доказательство уничтожения падших Ангелов. Доставьте его Верховному Жрецу Раймонду.', 'Proof of destroying Fallen Angels. Deliver it to High Priest Raymond.', 'etc_reagent_red_i00', 0);
INSERT INTO `all_items` VALUES (10354, 'Sealed Prophecy - Path of the God', NULL, 'Запечатанное пророчество, рассказывающее о местонахождении ангела. Отнесите его Великому Мастеру Тобиасу в Глудио.', 'A sealed prophecy revealing the location of an angel. Take it to Grand Master Tobias in Gludio.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (10355, 'Prophecy - Path of the God', NULL, 'Запечатанное пророчество, рассказывающее о местонахождении ангела. Попросите Старейшину Казиана расшифровать его.', 'A sealed prophecy revealing the location of an angel. Ask Elder Casian to decipher it.', 'etc_spellbook_red_i00', 0);
INSERT INTO `all_items` VALUES (10356, 'Empty Sound Crystal', NULL, 'Звуковой Кристалл для хранения послания ангелов. Пока на нем ничего не записано.', 'A sound crystal used to store an angel\'s message. Nothing has been recorded on it yet.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (10357, 'Angel Medicine', NULL, 'Лекарство, сделанное Казианом для лечения ангела. Отдайте Падшему Ангелу.', 'Medicine made by Casian to cure the angel. Give it to the Fallen Angel.', 'etc_lesser_potion_red_i00', 0);
INSERT INTO `all_items` VALUES (10358, 'Angel\'s Message', NULL, 'Звуковой кристалл, хранящий послание ангела. Отнесите его Великому Мастеру Тобиасу в Глудио.', 'A sound crystal storing an angel\'s message. Take it to Grand Master Tobias in Gludio.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (10359, 'Metallograph', NULL, 'Металлическое устройство, добытое в Башне Крума. Возможно, это записывающее устройство эпохи Гигантов.', 'A metallic device obtained in the Cruma Tower. It might be a recording device from the Giants\' era.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (10360, 'Broken Metal Pieces', NULL, 'Обрывок карты, добытый в Башне Крума.', 'A map piece obtained in the Cruma Tower.', 'etc_broken_tablet_fragment_i00', 0);
INSERT INTO `all_items` VALUES (10361, 'Nikola\'s Map', NULL, 'Карта, показывающая место, которое ищет Николя.', 'A map showing the location Nicholas is looking for.', 'etc_painting_i00', 0);
INSERT INTO `all_items` VALUES (10362, 'Loraine\'s Certificate', NULL, 'Свидетельство о получении Металлографа, который Лорейн добыла в Башне Крума. Сохраните его и возвращайтесь к ней позже.', 'A receipt for obtaining the metallograph that Lorraine retrieved in the Cruma Tower. Keep it and return to her later.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (10363, 'Metallograph', NULL, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство эпохи Гигантов.', 'A metallograph obtained in the Cruma Tower. It must be a recording device from the Giants\' era.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (10364, 'Broken Metal Pieces', NULL, 'Обломки Металлографа, добытые в Башне Крума.', 'Metallograph fragments obtained in the Cruma Tower.', 'etc_broken_tablet_fragment_i00', 0);
INSERT INTO `all_items` VALUES (10365, 'Nikola\'s Map', NULL, 'Карта, показывающая место, которое ищет Николя.', 'A map showing the location Nicholas is looking for.', 'etc_painting_i00', 0);
INSERT INTO `all_items` VALUES (10366, 'Metallograph - Research Report', NULL, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство, использующееся в Лаборатории Башни Крума.', 'A metallograph obtained in the Cruma Tower. It must be a recording device used in the Cruma Tower Laboratory.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (10367, 'Leto Lizardman Accessory', NULL, 'Украшение, которое носят Ящеры Лито. Оно нужно Торговцу Чертежами Луке.', 'An ornament worn by Lito Lizardmen. It is needed by Blueprint Trader Luka.', 'etc_chain_i00', 0);
INSERT INTO `all_items` VALUES (10368, 'Metallograph', NULL, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство эпохи Гигантов.', 'A metallograph obtained in the Cruma Tower. It must be a recording device from the Giants\' era.', 'etc_ancient_tablet_i00', 0);
INSERT INTO `all_items` VALUES (10369, 'Broken Metal Pieces', NULL, 'Обломки Металлографа, добытые в Башне Крума.', 'Metallograph fragments obtained in the Cruma Tower.', 'etc_broken_tablet_fragment_i00', 0);
INSERT INTO `all_items` VALUES (10370, 'Metallograph - Decipher Pattern', NULL, 'Лука суммировал содержимое, списанное с металлической пластинки. Отдайте ее назад Лорейн.', 'Luka summarized the contents copied from the metal plate. Give it back to Lorraine.', 'etc_ssq_scroll_i00', 0);
INSERT INTO `all_items` VALUES (10371, 'Repaired Metallograph', NULL, 'Дороти отремонтировала металлограф.', 'Dorothy repaired the metallograph.', 'etc_broken_tablet_fragment_i00', 0);
INSERT INTO `all_items` VALUES (10372, 'Red Stone', NULL, 'Предмет, который Мэтрес просил ему принести в качестве доказательства смерти монстров. О его истинном назначении он вам ничего не сказал.', 'An item Metheus asked you to bring as proof of monster deaths. He didn\'t tell you its true purpose.', 'etc_bead_red_i00', 0);
INSERT INTO `all_items` VALUES (10373, 'Recipe - Icarus Sawsword (60%)', NULL, 'Только для Гномов. Рецепт изготовления Зазубренного Меча Икара. Требует умения Создание Предметов - уровень 9. 60% шанс успеха.', 'Dwarves only. A recipe used to craft an Icarus Sawsword. Requires Create Item Level 9. Success rate: 60%.', 'etc_recipe_black_i00', 5);
