INSERT INTO `all_items` VALUES (10521, 'Rough Fire Ore', NULL, 'Увеличивает силу огня на 5 при использовании на оружие. Увеличивает силу огня на 3 и сопротивление воде при использовании на броню. Устанавливается начиная с третьего уровня; ниже сила будет потеряна. Нельзя обменять/выбросить.', 'Увеличивает силу огня на 5 при использовании на оружие. Увеличивает силу огня на 3 и сопротивление воде при использовании на броню. Устанавливается начиная с третьего уровня; ниже сила будет потеряна. Нельзя обменять/выбросить.', 'etc_fire_stone_i00', 25);
