INSERT INTO `all_items` VALUES (10612, 'Certificate - Master Ability', NULL, 'Сертификат, необходимый для изучения Навыков Мастера. Только основные классы могут учить эти умения. Этот предмет нельзя обменять, выбросить, уничтожить или сдать на хранение.', 'Сертификат, необходимый для изучения Навыков Мастера. Только основные классы могут учить эти умения. Этот предмет нельзя обменять, выбросить, уничтожить или сдать на хранение.', 'etc_all_subjob_skillbook_i00', 0);
INSERT INTO `all_items` VALUES (10613, 'Bird Nest (Event)', NULL, 'Головной аксессуар в виде птичьего гнезда. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'Головной аксессуар в виде птичьего гнезда. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'accessory_nest_hat_i00', 0);
INSERT INTO `all_items` VALUES (10614, 'White Wool Hat (Event)', NULL, 'Головной аксессуар в виде белой овцы. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'Головной аксессуар в виде белой овцы. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'accessory_sheep_cap_white_i00', 0);
INSERT INTO `all_items` VALUES (10615, 'Black Wool Hat (Event)', NULL, 'Головной аксессуар в виде черной овцы. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'Головной аксессуар в виде черной овцы. Требует две ячейки головных уборов. Ивентовый предмет, Нельзя обменять/выбросить.', 'accessory_sheep_cap_black_i00', 0);
INSERT INTO `all_items` VALUES (10616, 'Straw Hat (Event)', NULL, 'Соломенная шляпа. Требует две ячейки головных уборов. Изготовлена специально для ивента. Нельзя обменять/выбросить.', 'Соломенная шляпа. Требует две ячейки головных уборов. Изготовлена специально для ивента. Нельзя обменять/выбросить.', 'accessory_straw_hat_i00', 0);
INSERT INTO `all_items` VALUES (10617, 'Ant Hat', 'Year 2008', 'Забавный головной аксессуар, выполненный в форме Муравья. Требует две ячейки головных уборов. Может использоваться как эксклюзивный аксессуар сервиса I-Card до 31/12/2008. Нельзя обменять, выбросить и отдать на хранение.', 'An amusing ant-shaped head accessory. Requires 2 hair accessory slots. Can be used as an exclusive I-Card service accessory until 12/31/2008. Cannot be traded, dropped, or deposited into warehouse.', 'accessory_ant_cap_i00', 0);
INSERT INTO `all_items` VALUES (10618, 'Ol Mahum Hat', 'Year 2008', 'Забавный головной аксессуар, выполненный в форме Гнолла. Требует две ячейки головных уборов. Может использоваться как эксклюзивный аксессуар сервиса I-Card до 31/12/2008. Нельзя обменять, выбросить и отдать на хранение.', 'An amusing gnoll-shaped head accessory. Requires 2 hair accessory slots. Can be used as an exclusive I-Card service accessory until 12/31/2008. Cannot be traded, dropped, or deposited into warehouse.', 'accessory_ol_mahum_cap_i00', 0);
