INSERT INTO `all_items` VALUES (10632, 'Wondrous Cubic', NULL, 'Щелкните дважды, чтобы создать Фрагмент Кубика, который можно обменять на Свиток: Модифицировать Оружие/Доспех. Нельзя обменять/выбросить. (Используется только 1 раз в день).', 'Double-click to create a Dice Fragment, which can be exchanged for a Scroll: Enchant Weapon/Armor. Cannot be traded or dropped. (Can only be used once a day).', 'Branchsys2.cube_event_i01', 24);
INSERT INTO `all_items` VALUES (10633, 'Cube Fragment Armor - D', NULL, 'У Смотрителя Склада грузов можно обменять на Свиток: Модифицировать Доспех (D).', 'Can be exchanged for a Scroll: Enchant Armor (D-grade) with a Freight Manager.', 'Branchsys2.event_cubic_a_piece_i00', 0);
