INSERT INTO `all_items` VALUES (10638, 'Rough Black Cubic Piece', NULL, 'Вы можете получить этот предмет, поговорив со Смотрителем Склада грузов.', 'You can obtain this item by talking to a Freight Manager.', 'event_cubic_piece_i04', 0);
INSERT INTO `all_items` VALUES (10639, 'Mouse Coin', NULL, 'Деньги Крыс-Мутантов. Отдайте их в магическую лабораторию за вознаграждение.', 'Mutated Rat Money. Take it to a magic laboratory for a reward.', 'mouse_coin_i00', 0);
INSERT INTO `all_items` VALUES (10640, 'Cloned Squash Seed', NULL, 'Ивент L2 Extravaganza – Щелкните по нему дважды и появится Малая Тыква. Этот предмет Нельзя обменять/выбросить.', 'L2 Extravaganza Event – Double-click to spawn a Small Pumpkin. This item cannot be traded or dropped.', 'etc_gourd_i00', 0);
