INSERT INTO `all_items` VALUES (10667, 'Sirra\'s Blade {PvP}', 'Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (10668, 'Sirra\'s Blade {PvP}', 'Health', '<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (10669, 'Sirra\'s Blade {PvP}', 'Critical Poison', '<Свойство Кристалла Души>Дополнительный 15% шанс, что цель будет отравлена при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Grants an additional 15% chance to poison the target on Critical Attacks. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (10670, 'Sword of Ipos {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (10671, 'Sword of Ipos {PvP}', 'Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (10672, 'Sword of Ipos {PvP}', 'Health', '<Свойство Кристалла Души>Увеличивает Макс. MP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Max MP by 25%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (10673, 'Barakiel\'s Axe {PvP}', 'Health', '<Свойство Кристалла Души>Увеличивает Макс. MP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 25%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (10674, 'Barakiel\'s Axe {PvP}', 'Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (10675, 'Barakiel\'s Axe {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (10676, 'Behemoth\'s Tuning Fork {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tuning_fork_of_behemoth_i01', 4);
INSERT INTO `all_items` VALUES (10677, 'Behemoth\'s Tuning Fork {PvP}', 'Health', '<Свойство Кристалла Души>Увеличивает Макс. MP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Max MP by 25%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tuning_fork_of_behemoth_i01', 4);
INSERT INTO `all_items` VALUES (10678, 'Behemoth\'s Tuning Fork {PvP}', 'Anger', '<Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 32. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Decreases Max HP by 15% and increases P. Atk. by 32. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tuning_fork_of_behemoth_i01', 4);
INSERT INTO `all_items` VALUES (10679, 'Naga Storm {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 67. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Critical Rate by 67. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (10680, 'Naga Storm {PvP}', 'Critical Damage', '<Свойство Кристалла Души>Увеличивает Физ. Атк. на 200 при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases P. Atk. by 200 upon Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (10681, 'Naga Storm {PvP}', 'Back Blow', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 37 при атаке цели со спины. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Critical Rate by 37 when attacking the target from behind. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (10682, 'Tiphon\'s Spear {PvP}', 'Critical Stun', '<Свойство Кристалла Души>Дает 25% шанс оглушить при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Grants a 25% chance to stun on Critical Attacks. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (10683, 'Tiphon\'s Spear {PvP}', 'Towering Blow', '<Свойство Кристалла Души>Увеличивает Дальность. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases Attack Range. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (10684, 'Tiphon\'s Spear {PvP}', 'Wild Blow', '<Свойство Кристалла Души>Увеличивает угол атаки. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases attack angle. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (10685, 'Shyeed\'s Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души>Дополнительный 30% шанс понизить расход MP на 1 при обычной атаке. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Grants an additional 30% chance to reduce MP consumption to 1 on basic attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (10686, 'Shyeed\'s Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (10687, 'Shyeed\'s Bow {PvP}', 'Quick Recovery', '<Свойство Кристалла Души>Уменьшает время перезарядки на 17%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Decreases skill reuse delay by 17%. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (10688, 'Sobekk\'s Hurricane {PvP}', 'Rsk. Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 11% когда HP падают ниже 60%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Atk. Spd. by 11% when HP falls below 60%. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (10689, 'Sobekk\'s Hurricane {PvP}', 'Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (10690, 'Sobekk\'s Hurricane {PvP}', 'Critical Drain', '<Свойство Кристалла Души>Дополнительный шанс поглощения 14 HP цели при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Grants an additional chance to absorb 14 HP of the target on Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (10691, 'Themis\' Tongue {PvP}', 'Mana Up', '<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 30%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (10692, 'Themis\' Tongue {PvP}', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Grants a 50% chance to apply Mental Shield when using a beneficial skill on a target. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (10693, 'Themis\' Tongue {PvP}', 'Magic Focus', '<Свойство Кристалла Души>Дает 20% шанс наложения Фокусировки при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Grants a 20% chance to apply Focus when using a beneficial skill on a target. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (10694, 'Cabrio\'s Hand {PvP}', 'Conversion', '<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 60% and decreases Max HP by 40%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (10695, 'Cabrio\'s Hand {PvP}', 'Mana Up', '<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 30%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (10696, 'Cabrio\'s Hand {PvP}', 'Magic Silence', '<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Grants a 10% chance to apply Silence when using a harmful skill on a target. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_hand_of_cabrio_i01', 4);
