INSERT INTO `all_items` VALUES (10698, 'Daimon Crystal {PvP}', 'Acumen', '<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (10699, 'Daimon Crystal {PvP}', 'Mental Shield', '<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Grants a 50% chance to apply Mental Shield when using a beneficial skill on a target. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (10700, 'Г‰clair Bijou {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры <Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Sirra Blade Conversion <Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (10701, 'Eclair Bijou {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры <Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Sirra Blade Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (10702, 'Eclair Bijou {PvP}', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры. <Свойство Кристалла Души>Дает 6% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Sirra Blade Conversion <Soul Crystal Effect> Grants a 6% chance to poison the target on Critical Attacks. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (10703, 'Durendal {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Ипоса. <Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Kamael Exclusive Weapon: Ipos Sword Conversion <Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_death_bringer_i00', 4);
