INSERT INTO `all_items` VALUES (10721, 'Dragon Hunter Axe {PvP}', 'HP Drain', '<Свойство Кристалла Души> 3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> 3% of the damage dealt is added to your HP. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (10722, 'Angel Slayer {PvP}', 'Critical Damage', '<Свойство Кристалла Души> Увеличивает Физ. Атк. на 265 при Крит. Атк. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Increases P. Atk. by 265 upon Critical Attacks. Deals extra damage in PvP.', 'weapon_angel_slayer_i01', 5);
INSERT INTO `all_items` VALUES (10723, 'Angel Slayer {PvP}', 'HP Drain', '<Свойство Кристалла Души> 3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> 3% of the damage dealt is added to your HP. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_angel_slayer_i01', 5);
INSERT INTO `all_items` VALUES (10724, 'Angel Slayer {PvP}', 'Haste', '<Свойство Кристалла Души> Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_angel_slayer_i01', 5);
