INSERT INTO `all_items` VALUES (10730, 'Demon Splinter {PvP}', 'Critical Stun', '<Свойство Кристалла Души>Дает 27% шанс колдовства Оглушение при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Grants a 27% chance to cast Stun on Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_demon_splinter_i01', 5);
INSERT INTO `all_items` VALUES (10731, 'Arcana Mace {PvP}', 'Acumen', '<Свойство Кристалла Души> Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (10732, 'Arcana Mace {PvP}', 'MP Regeneration', '<Свойство Кристалла Души> Увеличивает регенерацию MP. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases MP regeneration. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_arcana_mace_i01', 5);
