INSERT INTO `all_items` VALUES (10734, 'Imperial Staff {PvP}', 'Empower', '<Свойство Кристалла Души> Увеличивает Маг. Атк. на 60. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases M. Atk. by 60. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_imperial_staff_i01', 5);
INSERT INTO `all_items` VALUES (10735, 'Imperial Staff {PvP}', 'MP Regeneration', '<Свойство Кристалла Души> Увеличивает регенерацию MP. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases MP regeneration. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_imperial_staff_i01', 5);
INSERT INTO `all_items` VALUES (10736, 'Imperial Staff {PvP}', 'Magic Hold', '<Свойство Кристалла Души>Дает 20% шанс колдовства Корень Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Grants a 20% chance to cast Dryad Root when using a harmful skill on a target. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_imperial_staff_i01', 5);
INSERT INTO `all_items` VALUES (10737, 'Draconic Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души> Дает 26% шанс понизить расход MP до 1 при обычной атаке. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Grants an additional 26% chance to reduce MP consumption to 1 on basic attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (10738, 'Draconic Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 88. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Increases Critical Rate by 88. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (10739, 'Draconic Bow {PvP}', 'Critical Slow', '<Свойство Кристалла Души> Дает шанс наложить Замедление при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Grants a chance to apply Slow on Critical Attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (10740, 'Laevateinn {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован. При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (10741, 'Laevateinn {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка <Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (10742, 'Laevateinn {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 84. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован. При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Critical Rate by 84. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (10743, 'Gram {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Разделителя Небес. <Свойство Кристалла Души> Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Kamael Exclusive Weapon: Heaven\'s Divider Conversion <Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_gram_i01', 5);
