INSERT INTO `all_items` VALUES (10762, 'Dynasty Knife {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Critical Rate by 116. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (10763, 'Dynasty Knife {PvP}', 'Evasion', '<Свойство Кристалла Души>Увеличивает Уклонение на 5. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Evasion by 5. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (10764, 'Dynasty Knife {PvP}', 'Critical Damage', '<Свойство Кристалла Души>Увеличивает Физ. Атк. на 559 при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases P. Atk. by 559 upon Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (10765, 'Dynasty Halberd {PvP}', 'Anger', '<Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 78. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Decreases Max HP by 15% and increases P. Atk. by 78. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_spear_i01', 5);
INSERT INTO `all_items` VALUES (10766, 'Dynasty Halberd {PvP}', 'Critical Stun', '<Свойство Кристалла Души>Дает 48% шанс колдовства Оглушение при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Grants a 48% chance to cast Stun on Critical Attacks. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_spear_i01', 5);
INSERT INTO `all_items` VALUES (10767, 'Dynasty Halberd {PvP}', 'Light', '<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', '<Soul Crystal Effect> Increases weight limit by 20%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_spear_i01', 5);
INSERT INTO `all_items` VALUES (10768, 'Dynasty Bagh-Nakh {PvP}', 'Rsk. Evasion', '<Свойство Кристалла Души>Увеличивает Уклонение на 6.8 при HP равном 60% или ниже. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Evasion by 6.8 when HP is 60% or lower. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_jamadhr_i01', 5);
INSERT INTO `all_items` VALUES (10769, 'Dynasty Bagh-Nakh {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 106. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Critical Rate by 106. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_jamadhr_i01', 5);
INSERT INTO `all_items` VALUES (10770, 'Dynasty Bagh-Nakh {PvP}', 'Haste', '<Свойство Кристалла Души>Увеличивает Скор. Атк. на 10% Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', '<Soul Crystal Effect> Increases Atk. Spd. by 10%. Deals extra damage in PvP. Grants a chance on attack to remove one or more buffs from the enemy and decrease their Shield Defense.', 'weapon_dynasty_jamadhr_i01', 5);
INSERT INTO `all_items` VALUES (10771, 'Dynasty Phantom {PvP}', 'Acumen', '<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_dynasty_magic_sword_i01', 5);
INSERT INTO `all_items` VALUES (10772, 'Dynasty Phantom {PvP}', 'Mana Up', '<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 30%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_dynasty_magic_sword_i01', 5);
INSERT INTO `all_items` VALUES (10773, 'Dynasty Phantom {PvP}', 'Conversion', '<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', '<Soul Crystal Effect> Increases Max MP by 60% and decreases Max HP by 40%. Deals extra damage in PvP and grants a chance to increase Casting Spd. when the character is attacked.', 'weapon_dynasty_magic_sword_i01', 5);
