INSERT INTO `all_items` VALUES (10780, 'Dynasty Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души> Дает 26% шанс понизить расход MP до 1 при обычной атаке. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Grants an additional 26% chance to reduce MP consumption to 1 on basic attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_bow_i01', 5);
INSERT INTO `all_items` VALUES (10781, 'Dynasty Bow {PvP}', 'Guidance', '<Свойство Кристалла Души>Увеличивает Точность на 5.32. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Increases Accuracy by 5.32. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_bow_i01', 5);
INSERT INTO `all_items` VALUES (10782, 'Dynasty Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', '<Soul Crystal Effect> Increases Critical Rate by 116. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_bow_i01', 5);
INSERT INTO `all_items` VALUES (10783, 'Dynasty Rapier {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Dynasty Sword Conversion <Soul Crystal Effect> Increases Critical Rate by 111. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (10784, 'Dynasty Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Dynasty Sword Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (10785, 'Dynasty Rapier {PvP}', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Kamael Exclusive Weapon: Dynasty Sword Conversion <Soul Crystal Effect> Increases weight limit by 20%. Deals extra damage in PvP and grants a chance to restore CP when the character is attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (10786, 'Dynasty Ancient Sword {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Kamael Exclusive Weapon: Dynasty Blade Conversion <Soul Crystal Effect> Increases Critical Rate by 111. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (10787, 'Dynasty Ancient Sword {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Kamael Exclusive Weapon: Dynasty Blade Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (10788, 'Dynasty Ancient Sword {PvP}', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Kamael Exclusive Weapon: Dynasty Blade Conversion <Soul Crystal Effect> Increases weight limit by 20%. Deals extra damage in PvP and grants a chance to increase damage on attacks.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (10789, 'Dynasty Crossbow {PvP}', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души> Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Kamael Exclusive Weapon: Dynasty Bow Conversion <Soul Crystal Effect> Decreases MP consumption for skills by 12%. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (10790, 'Dynasty Crossbow {PvP}', 'Guidance', 'Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Увеличивает Точность на 5.32. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Kamael Exclusive Weapon: Dynasty Bow Conversion <Soul Crystal Effect> Increases Accuracy by 5.32. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_crossbow_i01', 5);
