INSERT INTO `all_items` VALUES (10866, 'Energy Ore', NULL, 'Энергетическая руда, обнаруженная в шахтах восточного региона. Используется в качестве ингредиента в преобразователе энергии, созданном Мару.', 'Energy ore found in the mines of the eastern region. Used as an ingredient in the energy converter created by Maru.', 'etc_crystal_white_i00', 0);
INSERT INTO `all_items` VALUES (10867, 'Bloody Cloth Fragment', NULL, 'Кусок ткани, пропитанный кровью Марка. Необходим для определения типа яда.', 'A piece of cloth soaked in Mark\'s blood. Required to determine the type of poison.', 'etc_piece_of_cloth_red_i00', 0);
INSERT INTO `all_items` VALUES (10868, 'Helvetia\'s Antidote', NULL, 'Противоядие, купленное у Хельветии. Отдайте Марку', 'An antidote purchased from Helvetia. Give it to Mark.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (10869, 'Contaminated Kasha Spider Venom', NULL, 'Яд Паука Кхаши создан Кхашей, злым духом разложения и смерти. Соберите яд и отнесите Торговцу Кунай', 'Khasha Spider Poison created by Khasha, an evil spirit of decay and death. Gather the poison and take it to Trader Kunai.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (10870, 'Great Sword - Lightning', NULL, 'Редкий предмет, увеличивает шанс Крит. Атк.Дает возможность получить одно из следующих особых свойств: Здоровье, Крит. Урон или Фокусировка.', 'Rare item, increases Critical Rate. Grants one of the following special abilities: Health, Critical Damage, or Focus.', 'weapon_great_sword_i00', 3);
INSERT INTO `all_items` VALUES (10871, 'Great Sword - Lightning', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Increases Max HP by 25%.', 'weapon_great_sword_i01', 3);
INSERT INTO `all_items` VALUES (10872, 'Great Sword - Lightning', 'Critical Damage', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 247 при Крит. Атк.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Increases P. Atk. by 247 upon Critical Attacks.', 'weapon_great_sword_i01', 3);
INSERT INTO `all_items` VALUES (10873, 'Great Sword - Lightning', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 68.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Increases Critical Rate by 68.', 'weapon_great_sword_i01', 3);
INSERT INTO `all_items` VALUES (10874, 'Great Axe - Thunder', NULL, 'Редкий предмет, увеличивает силу Крит. Атк.Дает возможность получить одно из следующих особых свойств: Ярость Крит. Оглушение или Легкость.', 'Rare item, increases Critical Damage. Grants one of the following special abilities: Anger, Critical Stun, or Light.', 'weapon_great_axe_i00', 3);
INSERT INTO `all_items` VALUES (10875, 'Great Axe - Thunder', 'Anger', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Уменьшает Макс. HP на 15%, и увеличивает Физ. Атк. на 28.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Decreases Max HP by 15% and increases P. Atk. by 28.', 'weapon_great_axe_i01', 3);
INSERT INTO `all_items` VALUES (10876, 'Great Axe - Thunder', 'Critical Stun', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души> Дает 27% шанс колдовства Оглушение при Крит. Атк.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Grants a 27% chance to cast Stun on Critical Attacks.', 'weapon_great_axe_i01', 3);
INSERT INTO `all_items` VALUES (10877, 'Great Axe - Thunder', 'Light', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Increases weight limit by 20%.', 'weapon_great_axe_i01', 3);
INSERT INTO `all_items` VALUES (10878, 'Sword of Limit*Sword of Limit - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 127.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Critical Rate increases by 127.', 'weapon_dual_sword_i00', 3);
INSERT INTO `all_items` VALUES (10879, 'Sword of Limit*Sword of Delusion - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Макс. HP на 25%.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Max HP increases by 25%.', 'weapon_dual_sword_i00', 3);
INSERT INTO `all_items` VALUES (10880, 'Sword of Limit*Sword of Nightmare - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 54.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Critical Rate increases by 54.', 'weapon_dual_sword_i00', 3);
INSERT INTO `all_items` VALUES (10881, 'Sword of Limit*Tsurugi - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Скор. Атк. на 5%.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Atk. Spd. increases by 5%.', 'weapon_dual_sword_i00', 3);
INSERT INTO `all_items` VALUES (10882, 'Innominate Victory - Lightning', NULL, 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Большой Меч Дает возможность получить одно из следующих особых свойств: Здоровье, Крит. Урон или Фокусировка.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Great Sword. Grants one of the following special abilities: Health, Critical Damage, or Focus.', 'weapon_nameless_victory_i00', 3);
INSERT INTO `all_items` VALUES (10883, 'Innominate Victory - Lightning', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Большого Меча<Свойство Кристалла Души>Увеличивает Макс. HP на 25%.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Great Sword Conversion <Soul Crystal Effect> Increases Max HP by 25%.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (10884, 'Innominate Victory - Lightning', 'Critical Damage', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Большого Меча<Свойство Кристалла Души>Увеличивает Физ. Атк. на 247 при Крит. Атк.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Great Sword Conversion <Soul Crystal Effect> Increases P. Atk. by 247 upon Critical Attacks.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (10885, 'Innominate Victory - Lightning', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Большого Меча<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 68.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Great Sword Conversion <Soul Crystal Effect> Increases Critical Rate by 68.', 'weapon_nameless_victory_i01', 3);
INSERT INTO `all_items` VALUES (10886, 'Dark Elven Long Bow - Concentration', NULL, 'Редкий предмет, увеличивает Точность.Дает возможность получить одно из следующих особых свойств: Уклонение, Крит. Кровопускание, Скупость.', 'Rare item, increases Accuracy. Grants one of the following special abilities: Evasion, Critical Bleed, or Cheap Shot.', 'weapon_dark_elven_long_bow_i00', 3);
INSERT INTO `all_items` VALUES (10887, 'Dark Elven Long Bow - Concentration', 'Evasion', 'Редкий предмет, увеличивает Точность.<Свойство Кристалла Души>Увеличивает Уклонение на 2.', 'Rare item, increases Accuracy. <Soul Crystal Effect> Increases Evasion by 2.', 'weapon_dark_elven_long_bow_i01', 3);
INSERT INTO `all_items` VALUES (10888, 'Dark Elven Long Bow - Concentration', 'Critical Bleed', 'Редкий предмет, увеличивает Точность.<Свойство Кристалла Души>Дает 41% шанс вызвать кровотечение цели при Крит. Атк.', 'Rare item, increases Accuracy. <Soul Crystal Effect> Grants a 41% chance to bleed the target on Critical Attacks.', 'weapon_dark_elven_long_bow_i01', 3);
INSERT INTO `all_items` VALUES (10889, 'Dark Elven Long Bow - Concentration', 'Miser', 'Редкий предмет, увеличивает Точность<Свойство Кристалла Души> Дает 19% шанс понизить количество поглощенных выстрелов души до 2.', 'Rare item, increases Accuracy. <Soul Crystal Effect> Grants a 19% chance to reduce SoulShot consumption to 2.', 'weapon_dark_elven_long_bow_i01', 3);
INSERT INTO `all_items` VALUES (10890, 'Sword of Delusion*Sword of Delusion - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Точность на 4.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Accuracy increases by 4.', 'weapon_dual_sword_i00', 3);
INSERT INTO `all_items` VALUES (10891, 'Sword of Delusion*Sword of Nightmare - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 127.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Critical Rate increases by 127.', 'weapon_dual_sword_i00', 3);
