INSERT INTO `all_items` VALUES (10895, 'Sword of Valhalla - Nature', 'Magic Weakness', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Дает 7% шанс колдовства Проклятие Слабости при использовании вредоносного умения на цель.', 'Rare item, increases Max MP. <Soul Crystal Effect> Grants a 7% chance to cast Curse Weakness when using a harmful skill on a target.', 'weapon_sword_of_valhalla_i01', 3);
INSERT INTO `all_items` VALUES (10896, 'Sword of Valhalla - Nature', 'Magic Regeneration', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Дает 30% шанс колдовства Восстановления при использовании благотворного умения на цель.', 'Rare item, increases Max MP. <Soul Crystal Effect> Grants a 30% chance to cast Regeneration when using a beneficial skill on a target.', 'weapon_sword_of_valhalla_i01', 3);
