INSERT INTO `all_items` VALUES (10903, 'Arthro Nail - Destruction', 'Critical Poison', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Дает 14% шанс отравить цель при Крит. Атк. Эффект 6', 'Rare item, increases P. Atk. <Soul Crystal Effect> Grants a 14% chance to poison the target on Critical Attacks. Effect 6.', 'weapon_arthro_nail_i01', 3);
