INSERT INTO `all_items` VALUES (10970, 'Lance - Earth', 'Towering Blow', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает дальность атаки.', 'Rare item, increases Max HP. <Soul Crystal Effect> Increases attack range.', 'weapon_lancia_i01', 3);
INSERT INTO `all_items` VALUES (10971, 'Bellion Cestus - Great Gale', NULL, 'Редкий предмет, увеличивает Скор. Атк.Дает возможность получить одно из следующих особых свойств: Крит. Поглощение HP, Крит. Отравление, или Риск. Ускорение.', 'Rare item, increases Atk. Spd. Grants one of the following special abilities: Critical Drain, Critical Poison, or Risk Haste.', 'weapon_bellion_cestus_i00', 3);
INSERT INTO `all_items` VALUES (10972, 'Bellion Cestus - Great Gale', 'Critical Drain', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Поглощает 14 HP цели при Крит. Атк.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Drains 14 HP of the target on Critical Attacks.', 'weapon_bellion_cestus_i01', 3);
INSERT INTO `all_items` VALUES (10973, 'Bellion Cestus - Great Gale', 'Critical Poison', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Дополнительный 12% шанс, что цель будет отравлена при Крит. Атк. Эффект 7', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants an additional 12% chance to poison the target on Critical Attacks. Effect 7.', 'weapon_bellion_cestus_i01', 3);
INSERT INTO `all_items` VALUES (10974, 'Bellion Cestus - Great Gale', 'Rsk. Haste', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 9% при HP равном 60% или ниже.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Increases Atk. Spd. by 9% when HP is 60% or lower.', 'weapon_bellion_cestus_i01', 3);
INSERT INTO `all_items` VALUES (10975, 'Staff of Evil Spirits - Holy Spirit', NULL, 'Редкий предмет, увеличивает эффективность лечения.Дает возможность получить одно из следующих особых свойств: Маг. Фокусировка, Благословение Тела, или Отравление.', 'Rare item, increases healing effectiveness. Grants one of the following special abilities: Magic Focus, Bless the Body, or Poison.', 'weapon_staff_of_evil_sprit_i00', 3);
INSERT INTO `all_items` VALUES (10976, 'Staff of Evil Spirits - Holy Spirit', 'Magic Focus', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Дает 20% шанс наложения Фокусировки при использовании благотворного умения на цель.', 'Rare item, increases healing effectiveness. <Soul Crystal Effect> Grants a 20% chance to apply Focus when using a beneficial skill on a target.', 'weapon_staff_of_evil_sprit_i01', 3);
INSERT INTO `all_items` VALUES (10977, 'Staff of Evil Spirits - Holy Spirit', 'Blessed Body', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Дает 20% шанс колдовства Bless the Body при использовании благотворного умения на цель.', 'Rare item, increases healing effectiveness. <Soul Crystal Effect> Grants a 20% chance to cast Bless the Body when using a beneficial skill on a target.', 'weapon_staff_of_evil_sprit_i01', 3);
INSERT INTO `all_items` VALUES (10978, 'Staff of Evil Spirits - Holy Spirit', 'Magic Poison', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Дает 6% шанс колдовства Проклятие Отравления при использовании вредоносного умения на цель.', 'Rare item, increases healing effectiveness. <Soul Crystal Effect> Grants a 6% chance to cast Curse Poison when using a harmful skill on a target.', 'weapon_staff_of_evil_sprit_i01', 3);
