INSERT INTO `all_items` VALUES (11008, 'Wizard\'s Tear - Cleverness', 'Conversion', 'Редкий предмет, увеличивает скорость восстановления MР.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и Макс. HP уменьшает на 40%.', 'Rare item, increases MP regeneration rate. <Soul Crystal Effect> Increases Max MP by 60% and decreases Max HP by 40%.', 'weapon_tears_of_wizard_i01', 3);
