INSERT INTO `all_items` VALUES (11019, 'Dasparion\'s Staff - Hail', 'Conversion', 'Редкий предмет, увеличивает Маг. Атк.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Increases Max MP by 60% and decreases Max HP by 40%. Deals extra damage in PvP.', 'weapon_dasparions_staff_i01', 4);
INSERT INTO `all_items` VALUES (11020, 'Dasparion\'s Staff - Hail', 'Acumen', 'Редкий предмет, увеличивает Маг. Атк.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP.', 'weapon_dasparions_staff_i01', 4);
INSERT INTO `all_items` VALUES (11021, 'Doomchanter - Concentration', NULL, 'Редкий предмет, увеличивает Точность.Эксклюзивное оружие Камаэль: Конверсия Кровавого ЛукаДает возможность получить одно из следующих особых свойств: Легкость, Крит. Кровопускание или Увеличение Маны.', 'Rare item, increases Accuracy. Kamael Exclusive Weapon: Bloody Bow Conversion. Grants one of the following special abilities: Light, Critical Bleed, or Mana Up.', 'weapon_doom_singer_i00', 4);
INSERT INTO `all_items` VALUES (11022, 'Doomchanter - Concentration', 'Light', 'Редкий предмет, увеличивает Точность.Эксклюзивное оружие Камаэль: Конверсия Кровавого Лука<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP.', 'Rare item, increases Accuracy. Kamael Exclusive Weapon: Bloody Bow Conversion <Soul Crystal Effect> Increases weight limit by 20%. Deals extra damage in PvP.', 'weapon_doom_singer_i01', 4);
INSERT INTO `all_items` VALUES (11023, 'Doomchanter - Concentration', 'Critical Bleed', 'Редкий предмет, увеличивает ТочностьЭксклюзивное оружие Камаэль: Конверсия Кровавого Лука<Свойство Кристалла Души> Дает 35% шанс вызвать кровотечение цели при Крит. Атк. Наносит дополнительный урон в PvP.', 'Rare item, increases Accuracy. Kamael Exclusive Weapon: Bloody Bow Conversion <Soul Crystal Effect> Grants a 35% chance to bleed the target on Critical Attacks. Deals extra damage in PvP.', 'weapon_doom_singer_i01', 4);
INSERT INTO `all_items` VALUES (11024, 'Doomchanter - Concentration', 'Mana Up', 'Редкий предмет, увеличивает ТочностьЭксклюзивное оружие Камаэль: Конверсия Кровавого Лука<Свойство Кристалла Души> Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP.', 'Rare item, increases Accuracy. Kamael Exclusive Weapon: Bloody Bow Conversion <Soul Crystal Effect> Increases Max MP by 30%. Deals extra damage in PvP.', 'weapon_doom_singer_i01', 4);
INSERT INTO `all_items` VALUES (11025, 'White Lightning - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк.Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума Дает возможность получить одно из следующих особых свойств: Крит. Отравление, Ускорение или Ярость При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases P. Atk. Kamael Exclusive Weapon: Tallum Blade Conversion. Grants one of the following special abilities: Critical Poison, Haste, or Anger. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_lightning_blaze_i00', 4);
INSERT INTO `all_items` VALUES (11026, 'White Lightning - Destruction', 'Critical Poison', 'Редкий предмет, увеличивает Физ. Атк.Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума <Свойство Кристалла Души> Дает 10% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases P. Atk. Kamael Exclusive Weapon: Tallum Blade Conversion <Soul Crystal Effect> Grants a 10% chance to poison the target on Critical Attacks. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_lightning_blaze_i01', 4);
INSERT INTO `all_items` VALUES (11027, 'White Lightning - Destruction', 'Haste', 'Редкий предмет, увеличивает Физ. Атк.Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases P. Atk. Kamael Exclusive Weapon: Tallum Blade Conversion <Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_lightning_blaze_i01', 4);
INSERT INTO `all_items` VALUES (11028, 'White Lightning - Destruction', 'Anger', 'Редкий предмет, увеличивает Физ. Атк.Эксклюзивное оружие Камаэль: Конверсия Клинка Таллума <Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 31. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases P. Atk. Kamael Exclusive Weapon: Tallum Blade Conversion <Soul Crystal Effect> Decreases Max HP by 15% and increases P. Atk. by 31. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_lightning_blaze_i01', 4);
