INSERT INTO `all_items` VALUES (11070, 'Halberd - Lightning', NULL, 'Редкий предмет, увеличивает шанс Крит. Атк.Дает возможность получить одно из следующих особых свойств: Ускорение, Крит. Оглушение или Угол Атаки.', 'Rare item, increases Critical Rate. Grants one of the following special abilities: Haste, Critical Stun, or Attack Angle.', 'weapon_halbard_i00', 4);
INSERT INTO `all_items` VALUES (11071, 'Halberd - Lightning', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Increases Atk. Spd. by 6%. Deals extra damage in PvP.', 'weapon_halbard_i01', 4);
INSERT INTO `all_items` VALUES (11072, 'Halberd - Lightning', 'Critical Stun', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души> Дает 25% шанс оглушить при Крит. Атк. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Grants a 25% chance to stun on Critical Attacks. Deals extra damage in PvP.', 'weapon_halbard_i01', 4);
INSERT INTO `all_items` VALUES (11073, 'Halberd - Lightning', 'Wide Blow', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает угол атаки. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Increases attack range. Deals extra damage in PvP.', 'weapon_halbard_i01', 4);
INSERT INTO `all_items` VALUES (11074, 'Keshanberk*Damascus - Destruction', NULL, 'Редкий предмет, увеличивает Физ. Атк. При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.', 'Rare item, increases P. Atk. When enchanted, P. Atk. increases more for dual swords, two-handed swords, two-handed blunt weapons, and fist weapons than for one-handed swords. When enchanted to +4 or higher, Max HP increases by 25%. Deals extra damage in PvP.', 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (11075, 'Lacerator - Thunder', NULL, 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Темного Легиона Дает возможность получить одно из следующих особых свойств: Крит. Урон, Здоровье или Риск. Фокусировка При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Damage. Kamael Exclusive Weapon: Dark Legion Conversion. Grants one of the following special abilities: Critical Damage, Health, or Risk Focus. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i00', 4);
INSERT INTO `all_items` VALUES (11076, 'Lacerator - Thunder', 'Critical Damage', 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Темного Легиона <Свойство Кристалла Души>Увеличивает Физ. Атк. на 326 при Крит. Атк. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Damage. Kamael Exclusive Weapon: Dark Legion Conversion <Soul Crystal Effect> Increases P. Atk. by 326 upon Critical Attacks. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (11077, 'Lacerator - Thunder', 'Health', 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Темного Легиона <Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Damage. Kamael Exclusive Weapon: Dark Legion Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (11078, 'Lacerator - Thunder', 'Rsk. Focus', 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Темного Легиона <Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 130 при HP 60% и ниже. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Damage. Kamael Exclusive Weapon: Dark Legion Conversion <Soul Crystal Effect> Increases Critical Rate by 130 when HP is 60% or lower. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_greed_stinger_i01', 4);
