INSERT INTO `all_items` VALUES (11101, 'Flaming Dragon Skull - Wisdom', 'Acumen', 'Редкий предмет, уменьшает расход MP при использовании умения.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Rare item, decreases MP consumption for skills. <Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP.', 'weapon_dragon_flame_head_i01', 4);
