INSERT INTO `all_items` VALUES (11104, 'Branch of the Mother Tree - Nature', NULL, 'Редкий предмет, увеличивает Макс. MPДает возможность получить одно из следующих особых свойств: Конверсия, Маг. Урон или Проницательность.', 'Rare item, increases Max MP. Grants one of the following special abilities: Conversion, Magic Damage, or Acumen.', 'weapon_worldtrees_branch_i00', 4);
INSERT INTO `all_items` VALUES (11105, 'Branch of the Mother Tree - Nature', 'Conversion', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP.', 'Rare item, increases Max MP. <Soul Crystal Effect> Increases Max MP by 60% and decreases Max HP by 40%. Deals extra damage in PvP.', 'weapon_worldtrees_branch_i01', 4);
INSERT INTO `all_items` VALUES (11106, 'Branch of the Mother Tree - Nature', 'Magic Damage', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Дает 30% шанс нанесения дополнительного магического урона мощностью 8 при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Rare item, increases Max MP. <Soul Crystal Effect> Grants a 30% chance to deal additional magical damage of 8 power when using a harmful skill on a target. Deals extra damage in PvP.', 'weapon_worldtrees_branch_i01', 4);
INSERT INTO `all_items` VALUES (11107, 'Branch of the Mother Tree - Nature', 'Acumen', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Rare item, increases Max MP. <Soul Crystal Effect> Increases Casting Spd. by 15%. Deals extra damage in PvP.', 'weapon_worldtrees_branch_i01', 4);
INSERT INTO `all_items` VALUES (11108, 'Sword of Miracles - Holy Spirit', NULL, 'Редкий предмет, увеличивает эффективность лечения.Дает возможность получить одно из следующих особых свойств: Маг. Сила, Безмолвие или Проницательность.', 'Rare item, increases healing effectiveness. Grants one of the following special abilities: Magic Power, Silence, or Acumen.', 'weapon_sword_of_miracle_i00', 4);
INSERT INTO `all_items` VALUES (11109, 'Sword of Miracles - Holy Spirit', 'M. Atk.', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Увеличивает расход MP на 15% и увеличивает Маг. Атк. на 167 при использовании магии. Наносит дополнительный урон в PvP.', 'Rare item, increases healing effectiveness. <Soul Crystal Effect> Increases MP consumption by 15% and increases M. Atk. by 167 when using magic. Deals extra damage in PvP.', 'weapon_sword_of_miracle_i01', 4);
INSERT INTO `all_items` VALUES (11110, 'Sword of Miracles - Holy Spirit', 'Magic Silence', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель.Наносит дополнительный урон в PvP.', 'Rare item, increases healing effectiveness. <Soul Crystal Effect> Grants a 10% chance to apply Silence when using a harmful skill on a target. Deals extra damage in PvP.', 'weapon_sword_of_miracle_i01', 4);
INSERT INTO `all_items` VALUES (11111, 'Sword of Miracles - Holy Spirit', 'Acumen', 'Редкий предмет, увеличивает эффективность лечения.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP.', 'Acumen	Masterwork Item that increases heal amount.n<Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP.', 'weapon_sword_of_miracle_i01', 4);
INSERT INTO `all_items` VALUES (11112, 'Reaper - Clairvoyance', NULL, 'Редкий предмет, увеличивает дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Пронзателя ДушДает возможность получить одно из следующих особых свойств: Экономия, Быстрое Восстановление или Крит. Отравление.', 'Masterwork Item that Increases the attack range.nKamael-exclusive Weapon: Soul Bow ConversionnBestows one of the following functions: Cheap Shot, Quick Recovery, or Critical Poison .', 'weapon_soul_shooter_i00', 4);
INSERT INTO `all_items` VALUES (11113, 'Reaper - Clairvoyance', 'Cheap Shot', 'Редкий предмет, увеличивает дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ<Свойство Кристалла Души> Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP.', 'Cheap Shot	Masterwork Item that Increases the attack range.nKamael-exclusive Weapon: Soul Bow Conversionn<Soul Crystal Enhancement> nDecreases MP consumption by 12% when using skills. Increases damage inflicted during PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (11114, 'Reaper - Clairvoyance', 'Quick Recovery', 'Редкий предмет, увеличивает дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ. <Свойство Кристалла Души> Уменьшает время перезарядки на 15%. Наносит дополнительный урон в PvP.', 'Quick Recovery	Masterwork Item that Increases the attack range.nKamael-exclusive Weapon: Soul Bow Conversion. n<Soul Crystal Enhancement> nDecreases cooldown by 15%. Increases damage inflicted during PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (11115, 'Reaper - Clairvoyance', 'Critical Poison', 'Редкий предмет, увеличивает дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Пронзателя Душ <Свойство Кристалла Души> Дает 18% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Poison	Masterwork Item that increases the range.nKamael-exclusive Weapon: Soul Bow Conversionn<Soul Crystal Enhancement>nPoisons the target with an 18% chance during a standard Critical Attack. Increases damage inflicted during PvP.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (11116, 'Soul Separator - On Fire', NULL, 'Редкий предмет, увеличивает регенерацию HP.Дает возможность получить одно из следующих особых свойств: Наведение, Крит. Урон, или Риск. Ускорение.', 'Masterwork Item that increases HP Recovery Rate.nBestows one of the following functions: Guidance, P. Critical Damage, or Rsk. Haste.', 'weapon_soul_separator_i00', 4);
INSERT INTO `all_items` VALUES (11117, 'Soul Separator - On Fire', 'Guidance', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Точность на 4. Наносит дополнительный урон в PvP.', 'Guidance	Masterwork Item that increases HP Recovery Rate.n<Soul Crystal Enhancement>nIncreases Accuracy by about 4. Increases damage inflicted during PvP.', 'weapon_soul_separator_i01', 4);
INSERT INTO `all_items` VALUES (11118, 'Soul Separator - On Fire', 'Critical Damage', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 200 при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Damage	Masterwork Item that increases HP Recovery Rate.n<Soul Crystal Enhancement>nIncreases P. Atk. by 2 during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_soul_separator_i01', 4);
INSERT INTO `all_items` VALUES (11119, 'Soul Separator - On Fire', 'Rsk. Haste', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 11% когда HP падают ниже 60%. Наносит дополнительный урон в PvP.', 'Rsk. Haste	Masterwork Item that increases HP Recovery Rate.n<Soul Crystal Enhancement>nIncreases Atk. Spd. by 11% when HP drops to 6% or below. Increases damage inflicted during PvP.', 'weapon_soul_separator_i01', 4);
INSERT INTO `all_items` VALUES (11120, 'Elysian - Great Gale', NULL, 'Редкий предмет, увеличивает Скор. Атк.Дает возможность получить одно из следующих особых свойств: Здоровье, Ярость или Крит. Поглощение HP.', 'Rare item, increases Atk. Spd. Grants one of the following special abilities: Health, Anger, or Critical Drain.', 'weapon_elysian_i00', 4);
