INSERT INTO `all_items` VALUES (11199, 'Draconic Bow - Earth', 'Cheap Shot', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Дает 26% шанс понизить расход MP до 1 при обычной атаке. Наносит дополнительный урон в PvP.', 'Cheap Shot	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nHas a 26% chance of decreasing MP consumption to 1 during a standard attack. Increases damage inflicted during PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (11200, 'Draconic Bow - Earth', 'Focus', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 88. Наносит дополнительный урон в PvP.', 'Rare item, increases Max HP. <Soul Crystal Effect> Increases Critical Rate by 88. Deals extra damage in PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (11201, 'Draconic Bow - Earth', 'Critical Slow', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Дает шанс наложить Замедление при Крит. Атк. Наносит дополнительный урон в PvP.', 'Rare item, increases Max HP. <Soul Crystal Effect> Grants a chance to apply Slow on Critical Attacks. Deals extra damage in PvP.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (11202, 'Dragon Hunter Axe - Thunder', NULL, 'Редкий предмет, увеличивает силу Крит. Атк.Дает возможность получить одно из следующих особых свойств: Регенерация HP, Здоровье или Поглощение HP.', 'Rare item, increases Critical Damage. Grants one of the following special abilities: HP Regeneration, Health, or HP Drain.', 'weapon_dragon_hunter_axe_i00', 5);
