INSERT INTO `all_items` VALUES (11204, 'Dragon Hunter Axe - Thunder', 'Health', 'Редкий предмет, увеличивает Шанс. Крит. Уд.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (11205, 'Dragon Hunter Axe - Thunder', 'HP Drain', 'Редкий предмет, увеличивает Шанс. Крит. Уд.<Свойство Кристалла Души>3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> 3% of the damage dealt is added to your HP. Deals extra damage in PvP.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (11206, 'Laevateinn - Lightning', NULL, 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого КлинкаДает возможность получить одно из следующих особых свойств: Ускорение, Здоровье или Фокусировка.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion. Grants one of the following special abilities: Haste, Health, or Focus. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i00', 5);
INSERT INTO `all_items` VALUES (11207, 'Laevateinn - Lightning', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает Скор. Атк. на 7%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Atk. Spd. by 7%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (11208, 'Laevateinn - Lightning', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
