INSERT INTO `all_items` VALUES (11283, 'Dynasty Cudgel - Landslide', 'Rsk. Focus', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 164 при HP ниже 60%. Наносит дополнительный урон в PvP.', 'Rsk. Focus	Masterwork Item that has a chance to Stun on the target during an attack.n<Soul Crystal Enhancement>nIncreases Critical by 164 when HP drops to 6% or below. Increases damage inflicted during PvP.', 'weapon_dynasty_hammer_i01', 5);
