INSERT INTO `all_items` VALUES (11324, 'Icarus Spitter - Concentration', 'Focus', 'Редкий предмет, увеличивает Точность.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116 при Крит. Атк. Наносит дополнительный урон в PvP.', 'Focus	Masterwork Item that increases Accuracy.n<Soul Crystal Enhancement>nIncreases Critical by 116 during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_icarus_spiter_i01', 6);
INSERT INTO `all_items` VALUES (11325, 'Icarus Wingblade - Lightning', NULL, 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук ИкараДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.', 'Masterwork Item that increases P. Critical Rate.nKamael-exclusive Weapon: Icarus Heavy Arms ConversionnBestows one of the following functions: Focus, Health, or Light.', 'weapon_icarus_wing_blade_i00', 6);
INSERT INTO `all_items` VALUES (11326, 'Icarus Wingblade - Lightning', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук Икара<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP.', 'Focus	Masterwork Item that increases P. Critical Rate.nKamael-exclusive Weapon: Icarus Heavy Arms Conversionn<Soul Crystal Enhancement>nIncreases Critical by 111. Increases damage inflicted during PvP.', 'weapon_icarus_wing_blade_i01', 6);
INSERT INTO `all_items` VALUES (11327, 'Icarus Wingblade - Lightning', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук Икара<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.', 'Health	Masterwork Item that increases P. Critical Rate.nKamael-exclusive Weapon: Icarus Heavy Arms Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.', 'weapon_icarus_wing_blade_i01', 6);
INSERT INTO `all_items` VALUES (11328, 'Icarus Wingblade - Lightning', 'Light', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук Икара<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP.', 'Light	Masterwork Item that increases P. Critical Rate.nKamael-exclusive Weapon: Icarus Heavy Arms Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP.', 'weapon_icarus_wing_blade_i01', 6);
INSERT INTO `all_items` VALUES (11329, 'Icarus Trident - Thunder', NULL, 'Редкий предмет, увеличивает силу Крит. Атк.Дает возможность получить одно из следующих особых свойств: Ярость Крит. Оглушение или Легкость.', 'Masterwork Item that increases P. Critical Damage.nBestows one of the following functions: Anger, Critical Stun, or Light.', 'weapon_icarus_trident_i00', 6);
INSERT INTO `all_items` VALUES (11330, 'Icarus Trident - Thunder', 'Anger', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. на 78. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Decreases Max HP by 15% and increases P. Atk. by 78. Deals extra damage in PvP.', 'weapon_icarus_trident_i01', 6);
INSERT INTO `all_items` VALUES (11331, 'Icarus Trident - Thunder', 'Critical Stun', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души> Есть шанс 48% оглушить противника при критической атаке. Наносит дополнительный урон в PvP.', 'Critical Stun	Masterwork Item that increases P. Critical Damage.n<Soul Crystal Enhancement>nHas a 48% chance of casting Stun on the target during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_icarus_trident_i01', 6);
