INSERT INTO `all_items` VALUES (12814, 'Shadow Item - Gatekeeper Transformation Stick', NULL, 'Превращает в Хранителя Портала на 60 минут. Если снять предмет, трансформация отменяется. Нельзя обменять/выбросить.', 'Allows you to transform into a Gatekeeper for 6 min. The transformation ends when you unequip the item. Cannot be exchanged or dropped.', 'etc_gateleeper_stick_i00', 0);
INSERT INTO `all_items` VALUES (12815, 'Red Talisman - Max CP', NULL, 'При использовании увеличивает Макс. CP. Эффект не сочетается с дополнительным талисманом аналогичного типа. Теневой предмет, который Нельзя обменять/выбросить.', 'Increases Max CP when equipped. Effect does not stack with additional Talismans of the same type. Shadow Item that cannot be exchanged or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (12816, 'Red Talisman - CP Regeneration', NULL, 'Увеличивает регенерацию CP при использовании. Эффект не сочетается с дополнительным талисманом аналогичного типа. Теневой предмет, который Нельзя обменять/выбросить.', 'Increases CP Recovery Rate rate when equipped. Effect does not stack with additional Talismans of the same type. Shadow Item that cannot be exchanged or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (12817, 'Yellow Talisman - Increase Force', NULL, 'При надевании увеличивает энергию для зарядки умений Гладиатора и Отшельника, если Вас атакуют. Эффект не сочетается с дополнительным талисманом аналогичного типа. Теневой предмет, который Нельзя обменять/выбросить.', 'Increases your Force Level when attacked while equipped. Effect does not stack with additional Talismans of the same type. Shadow Item that cannot be exchanged or dropped.', 'etc_talisman_i02', 0);
INSERT INTO `all_items` VALUES (12818, 'Yellow Talisman - Damage Transition', NULL, 'При надевании переводит часть полученных вами повреждений слуге. Эффект не сочетается с дополнительным талисманом аналогичного типа. Теневой предмет, который Нельзя обменять/выбросить.', 'Transfers a portion of damage you take onto your servitor while equipped. Effect does not stack with additional Talismans of the same type. Shadow Item that cannot be exchanged or dropped.', 'etc_talisman_i02', 0);
INSERT INTO `all_items` VALUES (12819, 'Recovery Spellbook for Combat Use', NULL, 'Отменяет штраф за смерть. Действует только на поле боя.', 'Cancels death penalty. Applies only on the battlefield.', 'etc_penalty_recovery_i00', 1);
INSERT INTO `all_items` VALUES (12820, 'Blueprint - Summon Merchant Golem', NULL, 'Чертеж, необходимый для изучения умения \"Призвать Торгового Голема\". Профессия: Кузнец.Необходимый уровень: 52.', 'A blueprint required to learn the skill Summon Merchant Golem. Class: Warsmith. Required Level: 52.', 'etc_plan_i00', 0);
