INSERT INTO `all_items` VALUES (12835, 'Shadow Item - Teddy Bear Hat', NULL, 'Забавный головной аксессуар, выполненный в форме медвежонка. Требует две ячейки головных уборов. Нельзя обменять/выбросить.', 'Interesting hair accessory that looks like a teddy bear. Uses 2 hair accessory slots. Shadow Item that cannot be exchanged or dropped.', 'accessory_bear_cap_i00', 0);
INSERT INTO `all_items` VALUES (12836, 'Shadow Item - Piggy Hat', NULL, 'Забавный головной аксессуар, выполненный в форме хрюшки. Требует две ячейки головных уборов. Нельзя обменять/выбросить.', 'Interesting hair accessory that looks like a piggy. Uses 2 hair accessory slots. Shadow Item that cannot be exchanged or dropped.', 'accessory_pig_cap_i00', 0);
INSERT INTO `all_items` VALUES (12837, 'Shadow Item - Jester Hat', NULL, 'Фестивальный колпак с раздвоенной верхушкой. Теневой предмет, который Нельзя обменять/выбросить. Требует две ячейки головных уборов.', 'Festive jester hat with a split top. Uses 2 hair accessory slots. Shadow Item that cannot be exchanged or dropped.', 'accessory_jester_cap_i00', 0);
INSERT INTO `all_items` VALUES (12838, 'Fish Hat (Event)', NULL, 'Забавный головной аксессуар, выполненный в форме рыбы. Требует две ячейки головных уборов. Нельзя обменять/выбросить.', 'Interesting hair accessory that looks like a fish. Uses 2 hair accessory slots. This event item cannot be exchanged or dropped.', 'accessory_fish_cap_i00', 0);
INSERT INTO `all_items` VALUES (12839, 'Medieval Style Party Mask (Event)', NULL, 'Маска средневекового стиля. Требует две ячейки головных уборов. Этот предмет Нельзя обменять/выбросить.', 'Medieval-style party mask. Uses 2 hair accessory slots. This event item cannot be exchanged or dropped.', 'accessory_middle_age_party_mask_i00', 0);
