INSERT INTO `all_items` VALUES (12852, 'Naga Storm - Molar {PvP}', 'Focus', 'Редкий предмет, дает шанс отравить при атаке.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 67. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Focus	Masterwork Item that activates the Poison  effect occasionally during an attack.n<Soul Crystal Enhancement>nIncreases Critical by 67. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (12853, 'Naga Storm - Molar {PvP}', 'Critical Damage', 'Редкий предмет, дает шанс отравить при атаке.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 200 при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Critical Damage	Masterwork Item that activates the Poison  effect occasionally during an attack.n<Soul Crystal Enhancement>nP. Atk. +2 during a Critical Attack. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (12854, 'Naga Storm - Molar {PvP}', 'Back Blow', 'Редкий предмет, дает шанс отравить при атаке.<Свойство Кристалла Души>Увеличивает Шанс Крит. Уд. на 37 при атаке цели со спины. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Back Blow	Masterwork Item that activates the Poison  effect occasionally during an attack.n<Soul Crystal Enhancement>nP. Critical Rate increases by 37 during an attack from behind the target. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_naga_storm_i01', 4);
INSERT INTO `all_items` VALUES (12855, 'Daimon Crystal - Wisdom {PvP}', 'Mana Up', 'Редкий предмет, уменьшает расход MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that decreases MP consumption when using the skill.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (12856, 'Daimon Crystal - Wisdom {PvP}', 'Acumen', 'Редкий предмет, уменьшает расход MP.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Acumen	Masterwork Item that decreases MP consumption when using the skill.n<Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (12857, 'Daimon Crystal - Wisdom {PvP}', 'Mental Shield', 'Редкий предмет, уменьшает расход MP.<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mental Shield	Masterwork Item that decreases MP consumption upon skill use.n<Soul Crystal Enhancement>nHas a 5% chance of casting Mental Shield on the target during magic use. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_crystal_of_deamon_i01', 4);
INSERT INTO `all_items` VALUES (12858, 'Barakiel\'s Axe - On Fire {PvP}', 'Health', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Health	Masterwork Item that increases HP Recovery Rate.n<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (12859, 'Barakiel\'s Axe - On Fire {PvP}', 'Haste', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Haste	Masterwork Item that increases HP Recovery Rate.nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (12860, 'Barakiel\'s Axe - On Fire {PvP}', 'Focus', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Rare item, increases HP regeneration. <Soul Crystal Effect> Increases Critical Rate by 61. Deals extra damage in PvP and grants a chance to restore CP when attacked.', 'weapon_barakiel_axe_i01', 4);
INSERT INTO `all_items` VALUES (12861, 'Screaming Vengeance - Concentration {PvP}', 'Cheap Shot', 'Редкий предмет, уменьшает расход MP при использовании лука.Эксклюзивное оружие Камаэль: Конверсия Лука Шиид<Свойство Кристалла Души>Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Cheap Shot	Masterwork Item that decreases MP consumption when using a bow.nKamael-exclusive Weapon: Shyeed\'s Bow Conversionn<Soul Crystal Enhancement>when using the nSkill MP consumption decreases by 12%. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (12862, 'Screaming Vengeance - Concentration {PvP}', 'Focus', 'Редкий предмет, уменьшает расход MP при использовании лука.Эксклюзивное оружие Камаэль: Конверсия Лука Шиид<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Focus	Masterwork Item that decreases MP consumption when using a bow.nKamael-exclusive Weapon: Shyeed\'s Bow Conversionn<Soul Crystal Enhancement>nIncreases Critical by 61. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_soul_shooter_i01', 4);
INSERT INTO `all_items` VALUES (12863, 'Screaming Vengeance - Concentration {PvP}', 'Quick Recovery', 'Редкий предмет, уменьшает расход MP при использовании лука.Эксклюзивное оружие Камаэль: Конверсия Лука Шиид<Свойство Кристалла Души>Уменьшает время перезарядки на 17%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Quick Recovery	Masterwork Item that decreases MP consumption when using a bow.nKamael-exclusive Weapon: Shyeed\'s Bow conversionn<Soul Crystal Enhancement> nDecreases cooldown by about 17%. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_soul_shooter_i01', 4);
