INSERT INTO `all_items` VALUES (12872, 'Shyeed\'s Bow - Concentration {PvP}', 'Quick Recovery', 'Редкий предмет, уменьшает расход MP при использовании лука.<Свойство Кристалла Души>Уменьшает время перезарядки на 17%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Quick Recovery	Masterwork Item that decreases MP consumption when using a bow.n<Soul Crystal Enhancement>nCooldown decreases by about 17%. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_shyid_bow_i01', 4);
INSERT INTO `all_items` VALUES (12873, 'Sword of Ipos - Earth {PvP}', 'Focus', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Focus	Masterwork Item that increases Max HPn<Soul Crystal Enhancement>nIncreases Critical by 61. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (12874, 'Sword of Ipos - Earth {PvP}', 'Haste', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Haste	Masterwork Item that increases Max HP.nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (12875, 'Sword of Ipos - Earth {PvP}', 'Health', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Health	Masterwork Item that increases Max HPn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_sword_of_ipos_i01', 4);
INSERT INTO `all_items` VALUES (12876, 'Sobekk\'s Hurricane - Landslide {PvP}', 'Rsk. Haste', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 11% когда HP падают ниже 60%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Rsk. Haste	Masterwork Item that activates the Stun effect occasionally during an attack.n<Soul Crystal Enhancement>nIncreases Atk. Spd. by 11% when HP drops to 6% or below. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (12877, 'Sobekk\'s Hurricane - Landslide {PvP}', 'Haste', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Haste	Masterwork Item that has the Stun effect occasionally when hitting.nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (12878, 'Sobekk\'s Hurricane - Landslide {PvP}', 'Critical Drain', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Поглощает 14 HP цели при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Critical Drain	Masterwork Item that activates the Stun effect occasionally during an attack.n<Soul Crystal Enhancement>nAbsorbs HP 14 of the target during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_sobekk_hurricane_i01', 4);
INSERT INTO `all_items` VALUES (12879, 'Sirra\'s Blade - Landslide {PvP}', 'Haste', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Haste	Masterwork Item that has the Stun effect occasionally when hitting.nIncreases Atk. Spd. by about 6%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (12880, 'Sirra\'s Blade - Landslide {PvP}', 'Health', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Rare item, grants a chance to stun on attack. <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when attacked.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (12881, 'Sirra\'s Blade - Landslide {PvP}', 'Critical Poison', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Дает 15% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Critical Poison	Masterwork Item that activates the Stun effect occasionally during an attack.n<Soul Crystal Enhancement>nPoisons the target at the chance of 15% during the standard attack Critical. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_sirr_blade_i01', 4);
INSERT INTO `all_items` VALUES (12882, 'Г‰clair Bijou - Landslide {PvP}', 'Haste', 'Редкий предмет, дает шанс оглушить при атаке.Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Haste	Masterwork Item that activates the Stun effect occasionally during an attack.nKamael-exclusive Weapon: Sirra\'s Blade Conversion The nAtk. Spd. of n<Soul Crystal Enhancement> increases by 6%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (12883, 'Г‰clair Bijou - Landslide {PvP}', 'Health', 'Редкий предмет, дает шанс оглушить при атаке.Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Health	Masterwork Item that activates the Stun effect occasionally during an attack.nKamael-exclusive Weapon: Sirra\'s Blade Conversion n<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (12884, 'Г‰clair Bijou - Landslide {PvP}', 'Critical Poison', 'Редкий предмет, дает шанс оглушить при атаке.Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Дает 15% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Critical Poison	Masterwork Item that activates the Stun effect occasionally during an attack.nKamael-exclusive Weapon: Sirra\'s Blade Conversionn<Soul Crystal Enhancement>nHas a 15% chance of casting Poison on the target during a standard Critical Attack. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (12885, 'Tiphon\'s Spear - Landslide {PvP}', 'Critical Stun', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Дает 25% шанс оглушить при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Critical Stun	Masterwork Item that activates the Stun effect occasionally during an attack.n<Soul Crystal Enhancement>nHas about a 25% chance of casting Stun during a Critical Attack. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (12886, 'Tiphon\'s Spear - Landslide {PvP}', 'Towering Blow', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает дальность атаки. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Long Blow	Masterwork Item that has the Stun effect occasionally when hitting.n<Soul Crystal Enhancement>nThe range increases. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (12887, 'Tiphon\'s Spear - Landslide {PvP}', 'Wild Blow', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Увеличивает угол атаки. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Wild Blow	Masterwork Item that has the Stun effect occasionally when hitting.n<Soul Crystal Enhancement>nThe angle of attack widens. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_tiphon_spear_i01', 4);
INSERT INTO `all_items` VALUES (12888, 'Tallum Blade*Damascus - Landslide {PvP}', NULL, 'Редкий предмет, при атаке с определенной вероятностью оглушает цель.При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов повысится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Скор. Атк. на 8%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'Masterwork Item that has the Stun effect occasionally when hitting.nWhen enchanted with a two-handed sword, a two-handed blunt weapon or a fist weapon, its P. Atk. increases more than that of a regular one-handed sword. When enchanted to 4 or more, Increases Atk. Spd. by 8%. Increases damage inflicted during PvP, and decreases the range of bows/crossbows occasionally during an attack.', 'weapon_dual_sword_i00', 4);
INSERT INTO `all_items` VALUES (12889, 'Themis\' Tongue - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает скорость восстановления MР<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that increases MP Recovery Rate.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (12890, 'Themis\' Tongue - Cleverness {PvP}', 'Mental Shield', 'Редкий предмет, увеличивает скорость восстановления MР.<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Rare item, increases MP regeneration rate. <Soul Crystal Effect> Grants a 50% chance to apply Mental Shield when using a beneficial skill on a target. Deals extra damage in PvP, and grants a chance to increase Casting Spd. when attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (12891, 'Themis\' Tongue - Cleverness {PvP}', 'Magic Focus', 'Редкий предмет, увеличивает скорость восстановления MР.<Свойство Кристалла Души>Дает 20% шанс наложения Фокусировки при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Magic Focus	Masterwork Item that increases MP Recovery Rate.n<Soul Crystal Enhancement>nHas a 2% chance of casting Focus on the target during magic use. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_tongue_of_themis_i01', 4);
INSERT INTO `all_items` VALUES (12892, 'Cabrio\'s Hand - Cleverness {PvP}', 'Conversion', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Conversion	Masterwork Item that increases MP Recovery Raten<Soul Crystal Enhancement>nIncreases Max MP by 6% and decreases Max HP by 4%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (12893, 'Cabrio\'s Hand - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that increases MP Recovery Rate.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (12894, 'Cabrio\'s Hand - Cleverness {PvP}', 'Magic Silence', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Дает 10% шанс наложения Безмолвия при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Magic Silence	Masterwork Item that increases MP Recovery Rate.n<Soul Crystal Enhancement>nHas a 1% chance of casting Silence on the target during magic use. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_hand_of_cabrio_i01', 4);
INSERT INTO `all_items` VALUES (12895, 'Gram - Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Разделителя Небес<Свойство Кристалла Души>Увеличивает Скор. Атк. на 7%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Haste	Masterwork Item than increases the Critical impact.nKamael-exclusive Weapon: Heaven\'s Divider Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 7%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_gram_i01', 5);
