INSERT INTO `all_items` VALUES (12897, 'Gram - Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивает силу Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Разделителя Небес<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 84. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Focus	Masterwork Item than increases the Critical impact.nKamael-exclusive Weapon: Heaven\'s Divider Conversionn<Soul Crystal Enhancement>nIncreases Critical by 84. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_gram_i01', 5);
INSERT INTO `all_items` VALUES (12898, 'Demon Splinter - Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 80. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Focus	Masterwork Item that increases P. Critical Damage.n<Soul Crystal Enhancement>nIncreases Critical by 8. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_demon_splinter_i01', 5);
INSERT INTO `all_items` VALUES (12899, 'Demon Splinter - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Health	Masterwork Item that increases P. Critical Damage.n<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_demon_splinter_i01', 5);
INSERT INTO `all_items` VALUES (12900, 'Demon Splinter - Thunder {PvP}', 'Critical Stun', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Дает 27% шанс оглушения при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Rare item, increases Critical Damage. <Soul Crystal Effect> Grants a 27% chance to stun on Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more positive effects from the enemy and decrease their Shield Defense.', 'weapon_demon_splinter_i01', 5);
INSERT INTO `all_items` VALUES (12901, 'Draconic Bow - Earth {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Уменьшает расход MP на 1 с вероятностью 26% при обычной атаке. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Rare item, increases Max HP. <Soul Crystal Effect> Decreases MP consumption by 1 with a 26% probability on basic attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (12902, 'Draconic Bow - Earth {PvP}', 'Focus', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 88. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Rare item, increases Max HP. <Soul Crystal Effect> Increases Critical Rate by 88. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (12903, 'Draconic Bow - Earth {PvP}', 'Critical Slow', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Вызывает Замедление с определенной вероятностью при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Rare item, increases Max HP. <Soul Crystal Effect> Applies Slow with a certain probability on Critical Attacks. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_draconic_bow_i01', 5);
INSERT INTO `all_items` VALUES (12904, 'Dragon Hunter Axe - Thunder {PvP}', 'HP Regeneration', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Увеличивает восстановление HP. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Rare item, increases P. Atk. <Soul Crystal Effect> Increases HP recovery. Deals extra damage in PvP and grants a chance to increase damage on attack.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (12905, 'Dragon Hunter Axe - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Rare item, increases P. Atk. <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to increase damage on attack.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (12906, 'Dragon Hunter Axe - Thunder {PvP}', 'HP Drain', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Rare item, increases P. Atk. <Soul Crystal Effect> 3% of the damage dealt is added to your HP. Deals extra damage in PvP and grants a chance to increase damage on attack.', 'weapon_dragon_hunter_axe_i01', 5);
INSERT INTO `all_items` VALUES (12907, 'Laevateinn - Lightning {PvP}', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает Скор. Атк. на 7%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Atk. Spd. by 7%. Deals extra damage in PvP and grants a chance to restore CP when attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (12908, 'Laevateinn - Lightning {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Max HP by 25%. Deals extra damage in PvP and grants a chance to restore CP when attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (12909, 'Laevateinn - Lightning {PvP}', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Забытого Клинка<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 84. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Forgotten Blade Conversion <Soul Crystal Effect> Increases Critical Rate by 84. Deals extra damage in PvP and grants a chance to restore CP when attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_leavatein_i01', 5);
INSERT INTO `all_items` VALUES (12910, 'Basalt Battlehammer - Concentration {PvP}', 'HP Drain', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Rare item, increases HP regeneration. <Soul Crystal Effect> 3% of the damage dealt is added to your HP. Deals extra damage in PvP and grants a chance to restore CP when attacked.', 'weapon_basalt_battlehammer_i01', 5);
INSERT INTO `all_items` VALUES (12911, 'Basalt Battlehammer - Concentration {PvP}', 'Health', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Health	Masterwork Item that increases the effect of increased Accuracyn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_basalt_battlehammer_i01', 5);
INSERT INTO `all_items` VALUES (12912, 'Basalt Battlehammer - Concentration {PvP}', 'HP Regeneration', 'Редкий предмет, увеличивает регенерацию HP.<Свойство Кристалла Души>Увеличивает восстановление HP. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'HP Regeneration	Masterwork Item that increases the effect of increased Accuracyn<Soul Crystal Enhancement>nIncreases HP Recovery Rate. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_basalt_battlehammer_i01', 5);
INSERT INTO `all_items` VALUES (12913, 'Sarunga - Earth {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Лука Дракона<Свойство Кристалла Души>Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Cheap Shot	Masterwork Item than increases Max HP.nKamael-exclusive Weapon: Draconic Bow Conversionn<Soul Crystal Enhancement>when using the nSkill MP consumption decreases by 12%. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_sarnga_i01', 5);
INSERT INTO `all_items` VALUES (12914, 'Sarunga - Earth {PvP}', 'Focus', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Лука Дракона<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 88. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Focus	Masterwork Item than increases Max HP.nKamael-exclusive Weapon: Draconic Bow Conversionn<Soul Crystal Enhancement>nIncreases Critical by 88. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_sarnga_i01', 5);
INSERT INTO `all_items` VALUES (12915, 'Sarunga - Earth {PvP}', 'Critical Slow', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Лука Дракона<Свойство Кристалла Души>Дает шанс наложить Замедление при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Critical Slow	Masterwork Item than increases Max HP.nKamael-exclusive Weapon: Draconic Bow Conversionn<Soul Crystal Enhancement>nHas a chance of casting Slow during a Critical Attack Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_sarnga_i01', 5);
