INSERT INTO `all_items` VALUES (12919, 'Arcana Mace - Nature {PvP}', 'Acumen', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Acumen	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (12920, 'Arcana Mace - Nature {PvP}', 'MP Regeneration', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Увеличивает восстановление MP. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Rare item, increases Max MP. <Soul Crystal Effect> Increases MP recovery. Deals extra damage in PvP, and grants a chance to increase Casting Spd. when attacked.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (12921, 'Arcana Mace - Nature {PvP}', 'Mana Up', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_arcana_mace_i01', 5);
INSERT INTO `all_items` VALUES (12922, 'Angel Slayer - Concentration {PvP}', 'Critical Damage', 'Редкий предмет, увеличивает Точность<Свойство Кристалла Души>Увеличивает Физ. Атк. на 265 при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Critical Damage	Masterwork Item that increases Accuracy.n<Soul Crystal Enhancement>nIncreases P. Atk. by 265 during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_angel_slayer_i01', 5);
INSERT INTO `all_items` VALUES (12923, 'Angel Slayer - Concentration {PvP}', 'HP Drain', 'Редкий предмет, увеличивает Точность<Свойство Кристалла Души>3% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'HP Drain	Masterwork Item that increases Accuracy.n<Soul Crystal Enhancement>nAbsorbs 3% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP, during an attack, cancels the target\'s enhanced status b', 'weapon_angel_slayer_i01', 5);
INSERT INTO `all_items` VALUES (12924, 'Angel Slayer - Concentration {PvP}', 'Haste', 'Редкий предмет, увеличивает Точность<Свойство Кристалла Души>Увеличивает Скор. Атк. на 7%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Haste	Masterwork Item that increases Accuracy.n<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 7%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_angel_slayer_i01', 5);
INSERT INTO `all_items` VALUES (12925, 'Imperial Staff - Nature {PvP}', 'Empower', 'Редкий предмет, увеличивает Макс. MP.<Свойство Кристалла Души>Маг. Атк. увеличивает на 60. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Empower	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases M. Atk. by 6. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_imperial_staff_i01', 5);
