INSERT INTO `all_items` VALUES (12937, 'Dynasty Ancient Sword - Great Gale {PvP}', 'Light', 'Редкий предмет, увеличивает Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Клинка Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Light	Masterwork Item that increases Atk. Spd.nKamael-exclusive Weapon: Dynasty Blade Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_dynasty_ancient_sword_i01', 5);
INSERT INTO `all_items` VALUES (12938, 'Dynasty Knife - Great Gale {PvP}', 'Focus', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Focus	Masterwork Item that increases Atk. Spd.n<Soul Crystal Enhancement>nIncreases Critical by 116. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (12939, 'Dynasty Knife - Great Gale {PvP}', 'Evasion', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Увеличивает Уклонение на 5. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Evasion	Masterwork Item that increases Atk. Spd.n<Soul Crystal Enhancement>nIncreases Evasion by 5. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (12940, 'Dynasty Knife - Great Gale {PvP}', 'Critical Damage', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 559 при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Increases P. Atk. by 559 upon Critical Attacks. Deals extra damage in PvP. Grants a chance on attack to remove one or more positive effects from the enemy and decrease their Shield Defense.', 'weapon_dynasty_dagger_i01', 5);
INSERT INTO `all_items` VALUES (12941, 'Dynasty Dual Sword - Earth {PvP}', NULL, 'Редкий предмет, увеличивает Макс. HP.При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 109 и Увеличивает Макс. HP на 10%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'Masterwork Item that increases Max HP.nWhen enchanted with a two-handed sword, a two-handed blunt weapon or a fist weapon, its P. Atk. increases more than that of a regular one-handed sword. When enchanted to 4 or more, increases Critical Attack by 19 and Max HP by  1%. Increases damage inflicted during PvP, and decreases the range of bows/crossbows occasionally during an attack.', 'weapon_dual_sword_i00', 5);
INSERT INTO `all_items` VALUES (12942, 'Dynasty Rapier - Earth {PvP}', 'Focus', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Focus	Masterwork Item than increases Max HP.nKamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Critical by 111. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (12943, 'Dynasty Rapier - Earth {PvP}', 'Health', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Health	Masterwork Item than increases Max HP.nKamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (12944, 'Dynasty Rapier - Earth {PvP}', 'Light', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'Light	Masterwork Item that increases Max HP.nKamael-exclusive Weapon: Dynasty Sword Conversionn<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_dynasty_rapier_i01', 5);
INSERT INTO `all_items` VALUES (12945, 'Dynasty Mace - Earth {PvP}', 'Mana Up', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_dynasty_staff_i01', 5);
INSERT INTO `all_items` VALUES (12946, 'Dynasty Mace - Earth {PvP}', 'Conversion', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Conversion	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nIncreases Max MP by 6% and decreases Max HP by 4%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_dynasty_staff_i01', 5);
