INSERT INTO `all_items` VALUES (12969, 'Dynasty Crossbow - Great Gale {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивает Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Cheap Shot	Masterwork Item than increases Atk. Spd.nKamael-exclusive Weapon: Dynasty Bow Conversionn<Soul Crystal Enhancement>when using the nSkill MP consumption decreases by 12%. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (12970, 'Dynasty Crossbow - Great Gale {PvP}', 'Guidance', 'Редкий предмет, увеличивает Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Увеличивает Точность на 5.32. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Rare item, increases Atk. Spd. Kamael Exclusive Weapon: Dynasty Bow Conversion <Soul Crystal Effect> Increases Accuracy by 5.32. Deals extra damage in PvP and grants a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (12971, 'Dynasty Crossbow - Great Gale {PvP}', 'Focus', 'Редкий предмет, увеличивает Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Лука Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 116. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Focus	Masterwork Item than increases Atk. Spd.nKamael-exclusive Weapon: Dynasty Bow Conversionn<Soul Crystal Enhancement>nIncreases Critical by 116. Increases damage inflicted during PvP. Has a chance of increasing Atk. Spd. of bows/crossbows during an attack.', 'weapon_dynasty_crossbow_i01', 5);
INSERT INTO `all_items` VALUES (12972, 'Dynasty Phantom - Nature {PvP}', 'Acumen', 'Редкий предмет, уменьшает расход MP.<Свойство Кристалла Души>Увеличивает Скор. Маг. На 15%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Acumen	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_dynasty_magic_sword_i01', 5);
INSERT INTO `all_items` VALUES (12973, 'Dynasty Phantom - Nature {PvP}', 'Mana Up', 'Редкий предмет, уменьшает расход MP.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Mana Up	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_dynasty_magic_sword_i01', 5);
INSERT INTO `all_items` VALUES (12974, 'Dynasty Phantom - Nature {PvP}', 'Conversion', 'Редкий предмет, уменьшает расход MP при использовании умения us<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и уменьшает Макс. HP на 40%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'Conversion	Masterwork Item that increases Max MP.n<Soul Crystal Enhancement>nIncreases Max MP by 6% and decreases Max HP by 4%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_dynasty_magic_sword_i01', 5);
INSERT INTO `all_items` VALUES (12975, 'Dynasty Halberd - Earth {PvP}', 'Anger', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Уменьшает Макс. HP на 15% и увеличивает Физ. Атк. На 78. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Anger	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nYour own HP decreases by 15%. Increases P. Atk. by 78 during a Critical Attack. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_dynasty_spear_i01', 5);
INSERT INTO `all_items` VALUES (12976, 'Dynasty Halberd - Earth {PvP}', 'Critical Stun', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Есть 48% шанс оглушить противника при критической атаке. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Critical Stun	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nHas a 48% of Stun effect during a Critical Attack. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_dynasty_spear_i01', 5);
INSERT INTO `all_items` VALUES (12977, 'Dynasty Halberd - Earth {PvP}', 'Light', 'Редкий предмет, увеличивает Макс. HP.<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'Light	Masterwork Item that increases Max HP.n<Soul Crystal Enhancement>nIncreases Weight Gauge by 2%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_dynasty_spear_i01', 5);
