INSERT INTO `all_items` VALUES (12987, 'Dark Crystal Helmet', 'Robe', 'Редкий предмет, увеличивает Физ. Защ., скорость передвижения, сопротивление параличу. Уменьшает шанс отмены магии.', 'Robe	Masterwork Item that increases P. Def., Speed, and Resistance to Paralysis, and decreases Magic Cancel Rate.', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (12988, 'Tallum Helmet', 'Light Armor Use', 'Редкий предмет, увеличивает регенерацию MP, Макс. MP, сопротивление отравлению и сопротивление кровотечению.', 'Light Use	Masterwork Item that increases MP Recovery Rate, Max MP, and Resistance to Poison and Bleed.', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (12989, 'Tallum Helmet', 'Robe', 'Редкий предмет, увеличивает сопротивление магии, отравлению и кровотечению.', 'Robe	Masterwork Item that increases M. Def. and Resistance to Poison /Bleed', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (12990, 'Majestic Circlet', 'Light Armor Use', 'Редкий предмет, увеличивает Физ. Атк. для луков и арбалетов, увеличивает Макс. MP, грузоподъемность и сопротивление оглушению.', 'Rare item, increases P. Atk. for bows and crossbows, increases Max MP, weight limit, and resistance to Shock.', 'armor_leather_helmet_i00', 0);
