INSERT INTO `all_items` VALUES (12992, 'Helm of Nightmare', 'Light Armor Use', 'Редкий предмет, увеличивает сопротивление магии, усыплению и обездвиживанию.', 'Light Use	Masterwork Item that increases M. Def. and Resistance to Sleep/hold', 'armor_leather_helmet_i00', 0);
