INSERT INTO `all_items` VALUES (13008, 'Spellbook - Bless the Blood', NULL, 'Книга, необходимая для изучения умения \"Благословение Крови\". Профессия: Мудрец Шилен.Необходимый уровень: 40.', 'A book required to learn the skill Blood Blessing. Class: Shillien Elder. Required Level: 40.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (13010, 'Extra Entrance Pass - Kamaloka (Hall of the Abyss)', NULL, 'Витаминный предметДополнительный Билет в Камалоку (Зал Бездны). Снимает ограничение на вход. Можно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Additional Kamaoka Ticket (Seed of Destruction / Hall of the Abyss). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13011, 'Extra Entrance Pass - Near Kamaloka', NULL, 'Витаминный предметДополнительный Билет в Земли Камалоки. Снимает ограничение на вход. Можно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Additional Kamaoka Ticket (Kamaloka - Near/Surrounding areas). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13012, 'Extra Entrance Pass - Kamaloka (Labyrinth of the Abyss)', NULL, 'Витаминный предметДополнительный Билет в Камалоку (Лабиринт Бездны). Снимает ограничение на вход. Можно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Additional Kamaoka Ticket (Labyrinth of the Abyss). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13013, 'Gesto\'s Box', NULL, 'Ящик для Гесто. Необходимо собрать 300 таких.', 'Box for Gesto. You need to collect 300 of these.', 'etc_squares_wood_i00', 0);
INSERT INTO `all_items` VALUES (13014, 'Freight Chest\'s Seal', NULL, 'Печать, которую ставят на ящики с товарами. Необходимо отнести ее Гесто.', 'A seal placed on cargo boxes. Must be delivered to Gesto.', 'etc_jewel_green_i00', 0);
INSERT INTO `all_items` VALUES (13015, 'My Teleport Spellbook', NULL, 'Витаминный предметУвеличивает кол-во ячеек в списке для Телепорта к Флагу на 3. Максимально возможно расширение до 9 ячеек. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Increases the number of slots in the Teleport to Flag list by 3. Maximum possible expansion is up to 9 slots. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'bookmark_book_i00', 0);
INSERT INTO `all_items` VALUES (13016, 'My Teleport Scroll', NULL, 'Витаминный предметПредмет, который исчезает после телепортации в место сохранения. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. An item that disappears after teleporting to a saved location. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'bookmark_scroll_i00', 35);
INSERT INTO `all_items` VALUES (13017, 'White Weasel Hunting Helper Necklace', NULL, 'Витаминный предметПредмет, с помощью которого каждый раз в определенное время призывается  питомец, использующий вспомогательные умения воинов. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to periodically summon a pet that casts warrior buff skills. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13018, 'Fairy Princess Hunting Helper Necklace', NULL, 'Витаминный предметПредмет, с помощью которого каждый раз в определенное время призывается  питомец, использующий вспомогательные умения магов. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to periodically summon a pet that casts wizard buff skills. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13019, 'Wild Beast Fighter Hunting Helper Necklace', NULL, 'Витаминный предметПредмет, с помощью которого призывается питомец боевого типа. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to summon a combat-type pet. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13020, 'Fox Shaman Hunting Helper Necklace', NULL, 'Витаминный предметПредмет, с помощью которого призывается питомец магического типа. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to summon a magic-type pet. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13021, 'Color Name', NULL, 'Витаминный предметПредмет, с помощью которого можно изменить цвет титула персонажа. При выходе из клана цветной титул исчезает, как и обычный (кроме Дворян), но при вступлении в клан и установке нового титула цвет появляется вновь. После изменения цвета титула введите команду \'/resetname\', чтобы вернуть первоначальный цвет. Если предыдущего титула не было, титул исчезает. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. An item used to change the color of a character\'s title. Upon leaving a clan, the colored title disappears just like a regular one (except for Noblesse), but reappears upon joining a clan and setting a new title. After changing the title color, type \'/resetname\' to restore the original color. If there was no previous title, the title disappears. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'color_name_i00', 0);
INSERT INTO `all_items` VALUES (13022, 'Light Purple-Maned Horse Mount Bracelet', '7-day limited period', 'Витаминный предметПозволяет оседлать Сиреневого Коня. Действует 7 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to ride a Lilac Horse. Duration: 7 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13023, 'Agathion of Love', '30-day limited period', 'Витаминный предметПозволяет призвать Агатиона Любви. Действует 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to summon the Agathion of Love. Duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13024, 'Sudden Agathion', '30-day limited period', 'Витаминный предметПозволяет призвать Агатиона Гнева. Действует 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to summon the Agathion of Anger. Duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13025, 'Shiny Agathion', '30-day limited period', 'Витаминный предметПозволяет призвать Агатиона Радости. Действует 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to summon the Agathion of Joy. Duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13026, 'Sobbing Agathion', '30-day limited period', 'Витаминный предметПозволяет призвать Агатиона Печали. Действует 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to summon the Agathion of Sadness. Duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13027, 'Gran Kain\'s Gift Box', '30-day limited period', 'Витаминный предметИз коробки можно вынимать по одному предмету в день. Хранится 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. You can take one item per day from the box. Storage period: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'special_cube_i00', 24);
INSERT INTO `all_items` VALUES (13032, 'Pailaka Instant Shield', NULL, 'Зелье, дающее неуязвимость. Нельзя обменять/выбросить. Можно использовать только во временной зоне Пайлака.', 'A potion granting invulnerability. Cannot be traded/dropped. Can only be used within the Seed of Destruction / Kamaloka / Pailaka instance zone.', 'etc_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (13033, 'Quick Healing Potion', NULL, 'Мгновенно восстанавливает HP. Нельзя обменять/выбросить. Можно использовать только во временной зоне Пайлака.', 'Instantly restores HP. Cannot be traded/dropped. Can only be used within the Pailaka instance zone.', 'etc_potion_red_i00', 3);
INSERT INTO `all_items` VALUES (13034, 'Sprite\'s Sword', NULL, 'Меч, созданный водой и огнем. Нельзя обменять/выбросить. Можно использовать только во временной зоне Пайлака.', 'A sword created by water and fire. Cannot be traded/dropped. Can only be used within the Pailaka instance zone.', 'weapon_dual_sword_i00', 1);
