INSERT INTO `all_items` VALUES (13036, 'Sword of Ice and Fire', NULL, 'Меч, созданный водой и огнем. Нельзя обменять/выбросить. Можно использовать только во временной зоне Пайлака.', 'A sword created by water and fire. Cannot be traded/dropped. Can only be used within the Pailaka instance zone.', 'weapon_dual_sword_i00', 1);
INSERT INTO `all_items` VALUES (13037, 'Pailaka Soulshot - Grade D', NULL, 'Капсула, в которой заключена сила древнего духа. Придает оружию дополнительную силу. Используется с Мечом Льда и Огня.', 'A capsule containing the power of an ancient spirit. Grants additional power to weapons. Used with the Sword of Ice and Fire.', 'etc_spirit_bullet_blue_i00', 0);
INSERT INTO `all_items` VALUES (13038, 'Essence of Water', NULL, 'Если отнести ее Следователю Храма вместе с Мечом Духов, то можно получить Усиленный Меч Духов.', 'If you take it to the Temple Investigator along with the Spirit Sword, you can obtain an Enhanced Spirit Sword.', 'etc_scroll_of_enchant_weapon_i04', 0);
