INSERT INTO `all_items` VALUES (13040, 'Fire Attribute Enhancer', NULL, 'Увеличивает защиту от Огня. Нельзя обменять/выбросить. Можно использовать только во временной зоне Пайлака.', 'Increases Fire resistance. Cannot be traded/dropped. Can only be used within the Pailaka instance zone.', 'etc_fire_potion_i00', 3);
