INSERT INTO `all_items` VALUES (13046, 'Pailaka Weapon Upgrade Stage 1', NULL, 'Если отнести его Гному Путешественнику вместе с Мечом Древнего Наследия, то можно получить Усиленный Меч Древнего Наследия.', 'If you take it to the Dwarf Adventurer along with the Sword of Ancient Legacy, you can obtain an Enhanced Sword of Ancient Legacy.', 'etc_scroll_of_enchant_weapon_i04', 0);
