INSERT INTO `all_items` VALUES (13268, 'Gran Kain\'s Firework', NULL, 'Грандиозный Фейерверк, запускающийся в небо. Нельзя передать, выбросить или уничтожить, но можно поместить в личное хранилище..', 'A grand fireworks display launched into the sky. Cannot be traded, dropped, or destroyed, but can be deposited into a personal warehouse.', 'etc_small_ultra_bomb_i00', 0);
INSERT INTO `all_items` VALUES (13269, 'Gran Kain\'s Large Firework', NULL, 'Грандиозный Фейерверк, запускающийся в небо и взрывающийся разноцветными вспышками. Нельзя передать, выбросить или уничтожить, но можно поместить в личное хранилище..', 'A grand fireworks display launched into the sky that explodes in colorful flashes. Cannot be traded, dropped, or destroyed, but can be deposited into a personal warehouse.', 'etc_ultra_bomb_i00', 0);
INSERT INTO `all_items` VALUES (13270, 'Pathfinder\'s Reward - AU Karm', NULL, 'Подарок за участие в приключениях. Существует вероятность создания Знака Ау.', 'A gift for participating in adventures. There is a chance to create the Sign of Au.', 'etc_bead_gold_i00', 0);
