INSERT INTO `all_items` VALUES (13293, 'Pailaka Earring', NULL, 'Награда Пайлаки Забытого Храма. Серьга с превосходной Маг. Защ. Увеличивает MP на 20. Невозможно передать, выбросить или модифицировать.', 'Pailaka Forgotten Temple reward item. Earring with prominent M. Def. MP +2 effect. Cannot be exchanged, dropped, or enchanted.', 'accessary_onyxbeastseye_earing_i00', 0);
INSERT INTO `all_items` VALUES (13294, 'Pailaka Ring', NULL, 'Награда Пайлаки Забытого Храма. Кольцо с превосходной Маг. Защ. Увеличивает MP на 15. Невозможно передать, выбросить или модифицировать.', 'Pailaka Forgotten Temple reward item. Ring with prominent M. Def. MP 15 effect. Cannot be exchanged, dropped, or enchanted.', 'accessary_mithril_ring_i00', 0);
INSERT INTO `all_items` VALUES (13295, 'Pailaka Bracelet', NULL, 'Награда Пайлаки Острова Дьявола. При надевании увеличивает MP на 20 и добавляет 2 ячейки для талисманов. Невозможно передать, выбросить или модифицировать.', 'Pailaka Devil\'s Isle reward item. MP +2. Activates 2 talisman slots when equipped. Cannot be exchanged, dropped, or enchanted.', 'etc_rbracelet_c_i00', 0);
INSERT INTO `all_items` VALUES (13296, 'Pailaka Shirt', NULL, 'Награда Фавнов Варка Пайлаки. Рубаха с превосходной Физ. Защ. Увеличивает MP на 40. Невозможно передать, выбросить или модифицировать.', 'Pailaka Varka Silenos reward item. Shirt with prominent P. Def. MP 4 effect. Cannot be exchanged, dropped, or enchanted.', 'etc_shirts_a_i04', 0);
INSERT INTO `all_items` VALUES (13297, 'Extra Entrance Pass - Kamaloka (Hall of the Abyss) (Event)', NULL, 'Витаминный предметБилет в Камалоку (Зал Бездны). Снимает ограничение на вход. Можно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Kamaloka Ticket (Hall of the Abyss). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13298, 'Extra Entrance Pass - Near Kamaloka (Event)', NULL, 'Витаминный предметДополнительный Билет в Земли Камалоки. Снимает ограничение на вход. Возможно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Additional Kamaloka Ticket (Vicinity). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13299, 'Extra Entrance Pass - Kamaloka (Labyrinth of the Abyss) (Event)', NULL, 'Витаминный предметДополнительный Билет в Камалоку (Лабиринт Бездны). Снимает ограничение на вход. Возможно использовать один раз в день вне Камалоки. Эффект исчезает, когда данное подземелье обновляется. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Additional Kamaloka Ticket (Labyrinth of the Abyss). Removes entry restrictions. Can be used once a day outside of Kamaloka. The effect disappears when the dungeon resets. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (13300, 'Feather of Blessing (Event)', NULL, 'Витаминный предметПозволяет персонажу воскреснуть сразу после смерти. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Allows the character to resurrect immediately upon death. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'blessed_feather_i00', 0);
INSERT INTO `all_items` VALUES (13301, 'My Teleport Spellbook (Event)', NULL, 'Витаминный предметУвеличивает количество ячеек в списке для Телепорта к Флагу на 3. Максимально возможно расширение до 9 ячеек. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Increases the number of slots in the Teleport to Flag list by 3. Maximum possible expansion is up to 9 slots. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'bookmark_book_i00', 0);
INSERT INTO `all_items` VALUES (13302, 'My Teleport Scroll (Event)', NULL, 'Витаминный предметПредмет, который исчезает после телепортации в место сохранения. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. An item that disappears after teleporting to a saved location. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'bookmark_scroll_i00', 0);
INSERT INTO `all_items` VALUES (13303, 'White Weasel Hunting Helper Necklace (Event)', NULL, 'Витаминный предметПредмет, с помощью которого каждый раз в определенное время призывается питомец, использующий вспомогательные умения воинов. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to periodically summon a pet that casts warrior buff skills. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13304, 'Fairy Princess Hunting Helper Necklace (Event)', NULL, 'Витаминный предметПредмет, с помощью которого каждый раз в определенное время призывается питомец, использующий вспомогательные умения магов. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to periodically summon a pet that casts wizard buff skills. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13305, 'Wild Beast Fighter Hunting Helper Necklace (Event)', NULL, 'Витаминный предметПредмет, с помощью которого призывается питомец воинского типа. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to summon a warrior-type pet. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13306, 'Fox Shaman Hunting Helper Necklace (Event)', NULL, 'Витаминный предметПредмет, с помощью которого призывается питомец магического типа. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище.', 'Vitality Item. An item used to summon a magic-type pet. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13307, 'Color Name (Event)', NULL, 'Витаминный предметПредмет, с помощью которого можно изменить цвет титула персонажа. После изменения цвета титула введите команду \'/Обновить титул\', чтобы изменить назначенный по умолчанию цвет титула. Если предыдущего титула не было, титул исчезает. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. An item used to change the color of a character\'s title. After changing the title color, type \'/resetname\' to change the default title color back. If there was no previous title, the title disappears. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'color_name_i00', 0);
INSERT INTO `all_items` VALUES (13308, 'Light Purple-Maned Horse Mount Bracelet (Event)', '7-day limited period', 'Витаминный предметПозволяет оседлать Сиреневого Коня. Предмет используется 7 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to ride a Lilac Horse. Item duration: 7 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (13309, 'Agathion of Love (Event)', '30-day limited period', 'Витаминный предметИспользование позволяет призвать Агатиона Любви. Предмет используется 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to summon the Agathion of Love. Item duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
