INSERT INTO `all_items` VALUES (13382, 'Gran Kain\'s Gift Box (Event)', '30-day limited period', 'Из коробки можно вынимать по одному предмету в день. Хранится 30 дней. Нельзя передать, выбросить или уничтожить, но можно поместить в личное хранилище.', 'You can take one item per day from the box. Storage period: 30 days. Cannot be transferred, dropped, or destroyed, but can be deposited into a personal warehouse.', 'special_cube_i00', 24);
INSERT INTO `all_items` VALUES (13383, 'Hunting Helper Exchange Coupon - 5 hours (Event)', NULL, 'Витаминный предметКупон, который можно обменять у Менеджера Витаминов на Ожерелье Питомца (5 ч.). Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. A coupon that can be exchanged with the Vit Manager for a Pet Necklace (5 hours). Cannot be traded, dropped, or destroyed. Can be deposited into a personal warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (13384, 'Hunting Helper Exchange Coupon 3-Sheet Pack (Event)', NULL, 'Витаминная коробкаКоробка с купоном, который можно обменять у Менеджера Витаминов на Ожерелье Питомца (5 ч.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Box. Box containing a coupon that can be exchanged with the Vit Manager for a Pet Necklace (5 hours). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (13385, 'Hunting Helper Exchange Coupon 1-Sheet Pack (Event)', NULL, 'Витаминная коробкаКоробка с купоном, который можно обменять у Менеджера Витаминов на Ожерелье Питомца (5 ч.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Box. Box containing a coupon that can be exchanged with the Vit Manager for a Pet Necklace (5 hours). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i02', 0);
INSERT INTO `all_items` VALUES (13386, 'Blue Crystal of Fantasy', NULL, 'При использовании увеличивает SP на 50000. Необходимый уровень: 76. Нельзя обменять/выбросить.', 'When used, increases SP by 50,000. Required Level: 76. Cannot be traded/dropped.', 'etc_sp_crystal_i00', 1);
