INSERT INTO `all_items` VALUES (13415, 'Frog Hat', NULL, 'Интересный Головной аксессуар в виде лягушки. Требует две ячейки головных уборов. Нельзя обменять/выбросить.', 'This unique Frog Hat requires 2 hair accessory slots. Cannot be exchanged or dropped.', 'accessory_frog_cap_i00', 0);
INSERT INTO `all_items` VALUES (13416, 'Chicken Hat', NULL, 'Интересный Головной аксессуар в виде цыпленка. Требует две ячейки головных уборов. Нельзя обменять/выбросить.', 'This unique Chicken Hat requires 2 hair accessory slots. Cannot be exchanged or dropped.', 'accessory_chicken_cap_i00', 0);
INSERT INTO `all_items` VALUES (13417, 'L2day - Y', NULL, 'Предмет для ивента \"День L2\". Составьте определенное слово, отдайте его Коллекционеру Письмен \"Кошка-Ангел\" и получите подарок!', 'Item for the \"L2 Day\" event. Spell out a specific word, give it to the Letter Collector \"Angel Cat\", and receive a gift!', 'etc_alphabet_y_i00', 0);
INSERT INTO `all_items` VALUES (13418, 'L2day - Letter 5', NULL, 'Предмет для ивента \"День L2\". Составьте определенное слово, отдайте его Коллекционеру Письмен \"Кошка-Ангел\" и получите подарок!', 'Item for the \"L2 Day\" event. Spell out a specific word, give it to the Letter Collector \"Angel Cat\", and receive a gift!', 'etc_alphabet_5_i00', 0);
INSERT INTO `all_items` VALUES (13419, 'Lineage II Commemorative Mark', NULL, 'Знак юбилея Lineage II. Если сохранить его, то может произойти что-нибудь хорошее. Нельзя обменять/выбросить. Разрешается поместить в личное хранилище.', 'Lineage II Anniversary Badge. If you keep it, something good might happen. Cannot be traded/dropped. Can be deposited into a personal warehouse.', 'etc_scroll_of_memory_i00', 0);
INSERT INTO `all_items` VALUES (13420, 'Multi-colored Honey Rice Cake', NULL, 'Полностью восстанавливает энергию. Не действует на питомцев. Время ожидания повторного использовния: 60 мин.', 'Fully restores Energy. Does not affect pets. Reuse delay: 60 min.', 'etc_five_color_honey_cake_i00', 3);
INSERT INTO `all_items` VALUES (13421, 'Honey Wheat Cake', NULL, 'Полностью восстанавливает энергию. Не действует на питомцев. Нельзя обменять/выбросить. Можно хранить в личном хранилище. Время ожидания повторного использовния: 60 мин.', 'Fully restores Energy. Does not affect pets. Cannot be traded/dropped. Can be stored in a personal warehouse. Reuse delay: 60 min.', 'etc_cake_of_wheatlfour_i00', 3);
INSERT INTO `all_items` VALUES (13422, 'Medium Parchment Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находятся Свитки Телепорта в Деревню. Получите Свитки Телепорта, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing Village Teleport Scrolls. Obtain Teleport Scrolls by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (13423, 'Medium Mineral Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находятся Камни. Получите Камни, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing Stones. Obtain Stones by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (13424, 'Large Libation Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находятся Напитки. Получите Напитки, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing Beverages. Obtain Beverages by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (13425, 'Small Parchment Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находится Свиток Телепорта. Получите Свиток Телепорта, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing a Teleport Scroll. Obtain a Teleport Scroll by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (13426, 'Small Mineral Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находится Камень. Получите Камень, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing a Stone. Obtain a Stone by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (13427, 'Medium Libation Box', NULL, 'Ивентовый предмет для Дня L2. Коробка, в которой находятся Напитки. Получите Напитки, щелкнув два раза на коробку. Нельзя обменять/выбросить.', 'Event item for L2 Day. A box containing Beverages. Obtain Beverages by double-clicking the box. Cannot be traded/dropped.', 'etc_exchange_box_i00', 0);
