INSERT INTO `all_items` VALUES (13541, 'Yogi\'s Enchanted Treasure Box', NULL, 'Если открыть этот редко появляющийся сундук, можно получить свиток', 'Opening this rarely appearing chest allows you to obtain a scroll.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (13542, 'Yogi\'s Enchanted Reward Cube', NULL, 'Что будет, если открыть этот куб? Испытайте свою удачу, и узнаете.', 'What happens if you open this cube? Test your luck and find out.', 'cube_event_i00', 0);
INSERT INTO `all_items` VALUES (13543, 'Agathion Summon Bracelet - Collection', NULL, 'Созданный по схемам гномов голем для коллекции. Можно вытащить соединительный камень.', 'This Collection-Use Golem was created by the Dwarves using Agathion as the model. It is able extract a compression stone from seed effect.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (13544, 'Agathion Summon Bracelet - Boy Teddy Bear', NULL, 'Витаминный предметПозволяет призвать Плюшевого Медведя. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Dimensional ItemnCan summon an Agathion - Teddy Boy when equipped. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (13545, 'Agathion Summon Bracelet - Girl Teddy Bear', NULL, 'Витаминный предметПозволяет призвать Плюшевую Медведицу. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Dimensional ItemnCan summon an Agathion - Teddy Girl when equipped. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (13546, 'Steam Sledge Mount Bracelet', NULL, 'Витаминный предметПредмет позволяет кататься на санях. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Dimensional ItemnCan mount a Steam Sledge when equipped. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (13547, 'Tawny-Maned Lion Mount Bracelet', NULL, 'Витаминный предметПредмет позволяет ездить на льве. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Dimensional ItemnCan mount a Tawny Maned Lion when equipped. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (13548, 'Toy Knight Hunting Helper Necklace', NULL, 'Витаминный предметПозволяет призвать питомца на поле битвы. Нельзя передать или выбросить. Можно положить в личное хранилище.', 'Vitality Item. Allows you to summon a pet onto the battlefield. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13549, 'Soul Monk Hunting Helper Necklace', NULL, 'Витаминный предметПозволяет призвать питомца на поле битвы. Нельзя передать или выбросить. Можно положить в личное хранилище.', 'Vitality Item. Allows you to summon a pet onto the battlefield. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'pet_controler_i00', 7);
INSERT INTO `all_items` VALUES (13550, 'Owl Monk Hunting Helper Necklace', NULL, 'Витаминный предметПозволяет призвать питомца на поле битвы. Нельзя передать или выбросить. Можно положить в личное хранилище.', 'Vitality Item. Allows you to summon a pet onto the battlefield. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13551, 'Turtle Ascetic Hunting Helper Necklace', NULL, 'Витаминный предметПозволяет призвать питомца на поле битвы. Нельзя передать или выбросить. Можно положить в личное хранилище.', 'Vitality Item. Allows you to summon a pet onto the battlefield. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'pet_controler_i01', 7);
INSERT INTO `all_items` VALUES (13552, 'Spellbook - Flying Final Form', NULL, 'Книга, при помощи которой можно превратиться в ветер.', 'A book used to transform into the wind.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (13553, 'Spellbook - Aurabird Falcon', NULL, 'Книга, при помощи которой можно стать стремительным, как сокол.', 'A book used to become as swift as a falcon.', 'etc_codex_of_giant_i03', 0);
INSERT INTO `all_items` VALUES (13554, 'Spellbook - Aurabird Owl', NULL, 'Книга, при помощи которой можно превратиться в мастера стрельбы.', 'A book used to transform into a master marksman.', 'etc_codex_of_giant_i03', 0);
INSERT INTO `all_items` VALUES (13555, 'Combined Transformation Scroll', NULL, 'Книга, при помощи которой можно объединиться с призванным существом.', 'A book used to merge with a summoned creature.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (13556, 'Airship Helm', NULL, 'Устройство для управления воздушным кораблем.', 'Used to control a Airship.', 'etc_gateleeper_stick_i00', 0);
INSERT INTO `all_items` VALUES (13557, 'Airship Cannon', NULL, 'Устройство для управления пушкой.', 'Used to control a Airship\'s cannon.', 'etc_gateleeper_stick_i00', 0);
INSERT INTO `all_items` VALUES (13558, 'Airship Cannon Briquet', NULL, 'Боеприпасы для зарядки пушек на воздушном корабле.', 'Projectile fired by a Flying Boat\'s cannon.', 'weapon_fort_flag_i00', 0);
INSERT INTO `all_items` VALUES (13559, 'Airship Summon License', NULL, 'Позволяет призывать воздушный корабль своего клана.', 'Allows you to summon your clan\'s airship.', 'etc_scroll_white_i00', 0);
INSERT INTO `all_items` VALUES (13560, 'Gludio Ward', NULL, 'Флаг Владения Глудио. Дает бонусы всем союзникам клана, в замке которого находится. Персонаж, несущий флаг, не может атаковать и использовать умения.', 'Gludio Territory Flag. Grants bonuses to all allies of the clan holding the castle. The character carrying the flag cannot attack or use skills.', 'weapon_fort_flag_i00', 0);
INSERT INTO `all_items` VALUES (13561, 'Dion Ward', NULL, 'Флаг Владения Дион. Дает бонусы всем союзникам клана, в замке которого находится. Персонаж, несущий флаг, не может атаковать и использовать умения.', 'Ward bearing the unique pattern of Dion. Can obtain great strength when capturing the friendly forces\' outpost. It is automatically equipped when acquired, and attack and attack skills cannot be used. The ward capturing skill can be used instead.', 'weapon_fort_flag_i00', 0);
