INSERT INTO `all_items` VALUES (13726, 'Design: Energy Star Stone', NULL, 'Рецепт создания Звездного Камня, питающего энергией Воздушный Корабль. Требуется умение \"Создать Обычный Предмет\" 9-го уровня. Шанс создания: 100%.', 'A recipe used to craft a Star Stone, which powers the Airship. Requires Create Item Level 9. Success rate: 100%.', 'scroll_of_verification_i04', 5);
INSERT INTO `all_items` VALUES (13727, 'Design: Greater Quality Energy Star Stone', NULL, 'Рецепт создания Граненого Звездного Камня, питающего энергией Воздушный Корабль. Требуется умение \"Создать Обычный Предмет\" 9-го уровня. Шанс создания: 100%.', 'A recipe used to craft a Faceted Star Stone, which powers the Airship. Requires Create Item Level 9. Success rate: 100%.', 'scroll_of_verification_i05', 5);
INSERT INTO `all_items` VALUES (13728, 'Expert Text - Star Stone Extraction Skill. Level 1', NULL, 'Книга позволяет получить умение \"Извлечение Звездного Камня, 1-й уровень\". Для использования необходим 75-й уровень.', 'A book that grants the skill Star Stone Extraction Level 1. Requires level 75 to use.', 'etc_magic_book_black_i00', 0);
INSERT INTO `all_items` VALUES (13729, 'Expert Text - Star Stone Extraction Skill. Level 2', NULL, 'Книга позволяет получить умение \"Извлечение Звездного Камня, 2-й уровень\".', 'A book that grants the skill Star Stone Extraction Level 2.', 'etc_magic_book_blue_i00', 0);
INSERT INTO `all_items` VALUES (13730, 'Expert Text - Star Stone Extraction Skill. Level 3', NULL, 'Книга позволяет получить умение \"Извлечение Звездного Камня, 3-й уровень\".', 'A book that grants the skill Star Stone Extraction Level 3.', 'etc_magic_book_red_i00', 0);
