INSERT INTO `all_items` VALUES (13971, 'Red Boing Fantasy Hammer', NULL, 'Фантастический предмет. Существует вероятность, что при ударе увеличится голова. Нельзя передать, выбросить или уничтожить. Разрешается поместить в личное хранилище.', 'Fantasy Isle reward item. It enlarges the target\'s head at a certain rate with attacks. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'weapon_bbyong_hammer_a_i00', 2);
