INSERT INTO `all_items` VALUES (14052, 'Noble Enhancement Stone', NULL, 'Камень, усиливающий предметы Венеры. Обмен у мастера Ишумы. Можно передать, выбросить и поместить в личное хранилище.', 'A stone used to upgrade Vesper items. Can be exchanged through Master Ishuma. Can be traded, dropped, and deposited into a personal warehouse.', 'energy_condenser_i01', 0);
INSERT INTO `all_items` VALUES (14053, 'Gold-Maned Lion Mount Bracelet', '7-day limited period', 'Витаминный предметПозволяет оседлать Златогривого Льва. Предмет используется 7 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to ride a Golden-mane Lion. Item duration: 7 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (14054, 'Steam Beatle Mount Bracelet', '7-day limited period', 'Витаминный предметПозволяет оседлать Парового Жука. Предмет используется 7 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to ride a Steam Beetle. Item duration: 7 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (14055, 'Vitality Replenishing Beverage', NULL, 'Витаминный предметПозволяет восстановить до 100% энергии. Повторное использование возможно через час. Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Restores up to 100% of Energy. Reuse delay: 1 hour. Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'etc_potion_of_energy_i00', 3);
INSERT INTO `all_items` VALUES (14056, 'Snow Kung Transformation Stick', '30-day limited period', 'Витаминный предметПозволяет превратиться в Снеговика. Предмет используется 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to transform into a Snowman. Item duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'weapon_snowman_stick_i00', 0);
INSERT INTO `all_items` VALUES (14057, 'Scarecrow Jack Transformation Stick', '30-day limited period', 'Витаминный предметПозволяет превратиться в Пугало. Предмет используется 30 дней. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Item. Allows you to transform into a Scarecrow. Item duration: 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'weapon_scarescow_stick_i00', 0);
