INSERT INTO `all_items` VALUES (14086, 'Armor-type Enhance Backup Stone (A-Grade) (event)', NULL, 'Витаминный предметШанс успешной модификации +18%. Используется только для модификации на +4-9 (полный доспех +5-9). Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Success rate for armor enchantment +18%. Used only for enchanting from +4 to +9 (full body armor +5 to +9). Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ench_am_stone_i03', 28);
INSERT INTO `all_items` VALUES (14087, 'Armor-type Enhance Backup Stone (S-Grade) (event)', NULL, 'Витаминный предметШанс успешной модификации +15%. Используется только для модификации на +4-9 (полный доспех +5-9). Нельзя продать, выбросить, обменять или уничтожить, но можно положить в хранилище. Возможен обмен между персонажами в аккаунте при помощи Менеджера Витаминов.', 'Vitality Item. Success rate for armor enchantment +15%. Used only for enchanting from +4 to +9 (full body armor +5 to +9). Cannot be sold, dropped, traded, or destroyed, but can be deposited into a warehouse. Can be exchanged between characters on the account using the Vit Manager.', 'ench_am_stone_i04', 28);
