INSERT INTO `all_items` VALUES (14118, 'Vesper Cutter', 'Haste', '<Свойство Кристалла Души>Скор. Атк. увеличивается на 11%. Наносит дополнительный урон в PvP.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP.', 'weapon_vesper_cutter_i01', 7);
