INSERT INTO `all_items` VALUES (14120, 'Vesper Cutter', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 131. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Critical Rate increases by 131. Deals additional damage in PvP.', 'weapon_vesper_cutter_i01', 7);
