INSERT INTO `all_items` VALUES (14126, 'Vesper Buster', 'Magic Hold', '<Свойство Кристалла Души>Дает 20% вероятности, что заклинание Корень Дриады будет наложен на цель при использовании атакующего умения. Повышает урон, наносимый в PvP.', 'Magic Hold	a,<Soul Crystal Enhancement>nHas a 2% chance of casting Dryad Root on the target during magic use. Increases damage inflicted during PvP.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (14127, 'Vesper Shaper', 'Critical Damage', '<Свойство Кристалла Души>Дает шанс увеличить Физ. Атк. на 906 при Крит. Атк. Наносит дополнительный урон в PvP.', 'Critical Damage	a,<Soul Crystal Enhancement>nIncreases P. Atk. by 96 during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_vesper_shaper_i01', 7);
INSERT INTO `all_items` VALUES (14128, 'Vesper Shaper', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Повышает урон, наносимый в PvP.', 'HP Drain	a,<Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP.', 'weapon_vesper_shaper_i01', 7);
