INSERT INTO `all_items` VALUES (14142, 'Vesper Caster', 'Acumen', '<Свойство Кристалла Души>Скор. Маг. увеличивается на 15%. Повышает урон, наносимый в PvP.', 'Acumen	a,<Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (14143, 'Vesper Caster', 'MP Regeneration', '<Свойство Кристалла Души>Ускоряет Восстановление МР. Повышает урон, наносимый в PvP.', 'MP Regeneration	a,<Soul Crystal Enhancement>nIncreases MP Recovery Rate. Increases damage inflicted during PvP.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (14144, 'Vesper Caster', 'Mana Up', '<Свойство Кристалла Души>Макс.МР увеличивается на 30%. Повышает урон, наносимый в PvP.', 'Mana Up	a,<Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (14145, 'Vesper Singer', 'Empower', '<Свойство Кристалла Души>Маг. Атк. увеличивает на 151. Наносит дополнительный урон в PvP.', 'Empower	a,<Soul Crystal Enhancement>nIncreases M. Atk. by 151. Increases damage inflicted during PvP.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (14146, 'Vesper Singer', 'MP Regeneration', '<Свойство Кристалла Души>Ускоряет регенерацию МP. Повышает урон, наносимый в PvP.', 'MP Regeneration	a,<Soul Crystal Enhancement>nIncreases MP Recovery Rate. Increases damage inflicted during PvP.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (14147, 'Vesper Singer', 'Magic Hold', '<Свойство Кристалла Души>Дает 20% вероятности, что заклинание Корень Дриады будет наложено на цель при использовании атакующего умения. Повышает урон, наносимый в PvP.', 'Magic Hold	a,<Soul Crystal Enhancement>nHas a 2% chance of casting Dryad Root on the target during magic use. Increases damage inflicted during PvP.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (14148, 'Vesper Thrower', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке расход MP уменьшается до 1 с вероятностью 61%. Повышает урон, наносимый в PvP.', 'Cheap Shot	a,<Soul Crystal Enhancement>nDecreases MP consumption by 8% during a skill attack. Increases damage inflicted during PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (14149, 'Vesper Thrower', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 133. Наносит дополнительный урон в PvP.', 'Focus	a,<Soul Crystal Enhancement>nIncreases Critical by 133. Increases damage inflicted during PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (14150, 'Vesper Thrower', 'Critical Slow', '<Свойство Кристалла Души>Дает 33% вероятности наложения эффекта Замедления на цель при Крит. Атк. Повышает урон, наносимый в PvP.', '<Soul Crystal Effect> Grants a 33% probability to apply Slow on the target upon Critical Attacks. Increases damage dealt in PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (14151, 'Vesper Pincer', 'Haste', 'Эксклюзивное оружие Камаэль: конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается на 11%. Наносит дополнительный урон в PvP. При модификации на +4 и выше для Вас и членов Вашей группы активируется эффект, который при Крит. Атк. с определенной вероятностью увеличивает Физ. Атк., Маг. Атк., мощность лечения, а также уменьшает расход МР на использование умений.', 'Haste	Kamael-exclusive Weapon: Vesper Cutter Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (14152, 'Vesper Pincer', 'Health', 'Эксклюзивное оружие Камаэль: конверсия Резака Венеры<Свойство Кристалла Души>Макс. НР увеличивается на 25%. Повышает урон, наносимый в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Health	Kamael-exclusive Weapon: Vesper Cutter Conversionn<Soul Crystal Enhancement>nMax HP increased by 25%. Increases damage inflicted during PvP.nWhen enchanted to 4 or more, there\'s a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal and decreased MP consumption per skill during a Critical Attack.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (14153, 'Vesper Pincer', 'Focus', 'Эксклюзивное оружие Камаэль: конверсия Резака Венеры<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 131. Наносит дополнительный урон в PvP. При модификации на +4 и выше для Вас и членов Вашей группы активируется эффект, который при Крит. Атк. с определенной вероятностью увеличивает Физ. Атк., Маг. Атк., эффективность лечения, а также уменьшает расход МР на использование умений.', 'Focus	Kamael-exclusive Weapon: Vesper Cutter Conversionn<Soul Crystal Enhancement>nIncreases Critical by 131. Increases damage inflicted during PvP.nWhen enchanted over 4, there is a chance that party members including yourself can Increases P. Atk., M. Atk., and healing capacity and decrease MP consumption per skill during a Critical Attack.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (14154, 'Vesper Shooter', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: конверсия Броска Венеры<Свойство Кристалла Души>Расход MP уменьшается до 1 с вероятностью 61% при обычной атаке. Повышает урон, наносимый в PvP.', 'Cheap Shot	Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nMP consumption decreases 12%. Increases damage inflicted during PvP.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (14155, 'Vesper Shooter', 'Focus', 'Эксклюзивное оружие Камаэль: конверсия Броска Венеры<Свойство Кристалла Души>Шанс Крит. увеличивается на 133. Наносит дополнительный урон в PvP.', 'Focus	Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nIncreases Critical by 133. Increases damage inflicted during PvP.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (14156, 'Vesper Shooter', 'Critical Slow', 'Эксклюзивное оружие Камаэль: конверсия Броска Венеры<Свойство Кристалла Души>Существует 24%-я вероятность наложения на цель эффекта Замедления при Крит. Атк. Повышает урон, наносимый в PvP.', 'Critical Slow	Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nCasts Slow at a 24% rate during a Critical Attack. Increases damage inflicted during PvP.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (14157, 'Vesper Nagan', 'Haste', 'Эксклюзивное оружие Камаэль: конверсия Эспадона Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP.', 'Haste	Kamael-exclusive Weapon: Vesper Slasher Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP.', 'weapon_vesper_nagen_i01', 7);
