INSERT INTO `all_items` VALUES (14159, 'Vesper Nagan', 'Focus', 'Эксклюзивное оружие Камаэль: конверсия Эспадона Венеры<Свойство Кристалла Души>Шанс Крит. увеличивается на 131. Наносит дополнительный урон в PvP.', 'Focus	Kamael-exclusive Weapon: Vesper Slasher Conversionn<Soul Crystal Enhancement>nIncreases Critical by 131. Increases damage inflicted during PvP.', 'weapon_vesper_nagen_i01', 7);
INSERT INTO `all_items` VALUES (14160, 'Sealed Vesper Earring', NULL, 'Печать можно снять у Кузнеца Маммона или Мастера Ишумы. Когда печать снята, добавляется эффект Маг. Защ. +11, МР +37.', 'The seal can be removed by Blacksmith of Mammon or Master Ishuma. When unsealed, M. Def. +11 and MP +37 effects are added.', 'vesper_earring_i01', 0);
INSERT INTO `all_items` VALUES (14161, 'Sealed Vesper Necklace', NULL, 'Печать можно снять у Кузнеца Маммона или Мастера Ишумы. Когда печать снята, добавляется эффект Маг. Защ. +15, МР +50.', 'Seal can be removed by the Blacksmith of Mammon or Maestro Ishuma. When the seal is released, the effect is M. Def.+15 and MP+5.', 'vesper_necklace_i01', 0);
INSERT INTO `all_items` VALUES (14162, 'Sealed Vesper Ring', NULL, 'Печать можно снять у Кузнеца Маммона или Мастера Ишумы. Когда печать снята, добавляется эффект Маг. Защ. +7, МР +25.', 'Seal can be removed by the Blacksmith of Mammon or Maestro Ishuma. When the seal is released, the effect is M. Def.+7 and MP+25.', 'vesper_ring_i01', 0);
INSERT INTO `all_items` VALUES (14163, 'Vesper Earring', NULL, 'Серьга Венеры. МР +37.', 'Vesper Earring. The effect is MP +37.', 'vesper_earring_i00', 0);
INSERT INTO `all_items` VALUES (14164, 'Vesper Necklace', NULL, 'Ожерелье Венеры. МР +50', 'Vesper Necklace. The effect is MP +5.', 'vesper_necklace_i00', 0);
INSERT INTO `all_items` VALUES (14165, 'Vesper Ring', NULL, 'Кольцо Венеры. МР +25.', 'Vesper Ring. The effect is MP +25.', 'vesper_ring_i00', 0);
INSERT INTO `all_items` VALUES (14166, 'Life Stone -  Level 84', NULL, 'Минерал, окаменевший вследствие воздействия неизвестной физической или магической силы. Ключевой компонент для зачарования оружия персонажей 84-го уровня и выше.', 'A mineral petrified as a result of an unknown physical or magical force. A key component for enchanting weapons of characters level 84 and above.', 'etc_mineral_general_i03', 0);
INSERT INTO `all_items` VALUES (14167, 'Mid-Grade Life Stone -  Level 84', NULL, 'Минерал среднего качества, окаменевший вследствие воздействия неизвестной физической или магической силы. Ключевой компонент для зачарования оружия персонажей 84-го уровня и выше.', 'Medium-quality mineral petrified as a result of an unknown physical or magical force. A key component for enchanting weapons of characters level 84 and above.', 'etc_mineral_special_i03', 0);
INSERT INTO `all_items` VALUES (14168, 'High-Grade Life Stone -  Level 84', NULL, 'Высококачественный минерал, окаменевший вследствие воздействия неизвестной физической или магической силы. Ключевой компонент для зачарования оружия персонажей 84-го уровня и выше.', 'High-quality mineral petrified as a result of an unknown physical or magical force. A key component for enchanting weapons of characters level 84 and above.', 'etc_mineral_rare_i03', 0);
INSERT INTO `all_items` VALUES (14169, 'Top-Grade Life Stone -  Level 84', NULL, 'Минерал высшего качества, окаменевший вследствие воздействия неизвестной физической или магической силы. Ключевой компонент для зачарования оружия персонажей 84-го уровня и выше.', 'Top-quality mineral petrified as a result of an unknown physical or magical force. A key component for enchanting weapons of characters level 84 and above.', 'etc_mineral_unique_i03', 0);
