INSERT INTO `all_items` VALUES (14351, 'Gracian Anniversary Coins', NULL, 'Монета Грации. Торговец может дать за нее неплохое вознаграждение. Нельзя обменять, выбросить, уничтожить, положить в хранилище.', 'Coin of Grace. A merchant can give a good reward for it. Cannot be traded, dropped, destroyed, or deposited into a warehouse.', 'etc_coins_silver_i00', 0);
