INSERT INTO `all_items` VALUES (14592, 'Gludio Earth Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Глудио. Защита от Земли +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Gludio territory. Resistance to Earth +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings having the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14593, 'Dion Water Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Диона. Защита от Воды +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Dion territory. Water power defense +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14594, 'Giran Fire Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Гирана. Защита от Огня +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Giran territory. Fire power defense +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14595, 'Oren Earth Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Орена. Защита от Земли +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Oren territory. Resistance to Earth +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14596, 'Aden Holy Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Адена. Защита от Святости +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Aden territory. Resistance to Holy +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14597, 'Innadril Holy Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Иннадрила. Защита от Святости +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Innadril territory. Resistance to Holy +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14598, 'Goddard Dark Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Годдарда. Защита от Тьмы +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Goddard territory. Resistance to Dark +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14599, 'Rune Wind Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Руны. Защита от Ветра +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'Ring given to the guardian of Rune territory. Wind power defense +12. Cannot be exchanged or dropped. Only one effect is applied even when wearing two earrings with the same effect.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14600, 'Schuttgart Dark Resistance Ring', NULL, 'Кольцо, которым награждается Хранитель Шутгарта. Защита от Тьмы +12. Нельзя обменять/выбросить. При надевании двух одинаковых колец, действует эффект лишь одного.', 'A necklace awarded to the Schuttgart Guardian. Dark resistance +12. Cannot be traded or dropped. If two identical rings are worn, only the effect of one will apply.', 'accessary_inferno_ring_i00', 0);
INSERT INTO `all_items` VALUES (14601, 'Ancient Cloak: Kamael exclusive', 'Kamael Use', 'Искусно отделанный древний плащ. Слот для плаща открывается после облачения в полный комплект Династии. Предназначен для Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Finely crafted ancient cloak. The cloak slot is unlocked after equipping a full Dynasty set. Designed for Kamaels. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (14602, 'Ancient Cloak', NULL, 'Искусно отделанный древний плащ. Слот для плаща открывается после облачения в полный комплект Династии. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Finely crafted ancient cloak. The cloak slot is unlocked after equipping a full Dynasty set. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (14603, 'Sealed Ancient Cloak', NULL, 'Запечатанный искусно отделанный древний плащ. Печать можно снять у Ольфа Каноре или Ольфа Адамса. Нельзя надеть до снятия печати. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Sealed finely crafted ancient cloak. The seal can be removed by Olf Kanore or Olf Adams. Cannot be worn before unsealing. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'sealed_vesper_cloack_i01', 0);
INSERT INTO `all_items` VALUES (14604, 'Red Talisman - Territory Guardian', NULL, 'При использовании намного повышается СР и ускоряется регенерация СР. При использовании двух одинаковых талисманов учитывается эффект только одного. Теневой Предмет, который Нельзя обменять/выбросить.', 'When used, significantly increases CP and accelerates CP regeneration. When using two identical talismans, only the effect of one is taken into account. Shadow Item that cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (14605, 'Red Talisman - Territory Guard', NULL, 'При использовании намного повышается СР и ускоряется регенерация СР. При использовании двух одинаковых талисманов учитывается эффект только одного. Теневой Предмет, который Нельзя обменять/выбросить.', 'When used, significantly increases CP and accelerates CP regeneration. When using two identical talismans, only the effect of one is taken into account. Shadow Item that cannot be traded or dropped.', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (14606, 'Gracian Soldier Two-Handed Sword', NULL, 'Меч воина Грации. Требует две ячейки головных уборов.', 'Gracia warrior\'s sword. Requires two hair accessory slots.', 'weapon_mon_gracia_soldier_sword_i00', 1);
INSERT INTO `all_items` VALUES (14607, 'Mark of Gracia', NULL, 'Знак Грации, выдаваемый новичку на сервере Грации. У Торговца Знаками можно обменять его на предмет.', 'Mark of Gracia, given to a beginner on the Gracia server. Can be exchanged for an item with the Mark Trader.', 'etc_coins_silver_i00', 0);
INSERT INTO `all_items` VALUES (14608, 'Ancient Cloak: Light Armor exclusive', NULL, 'Искусно отделанный древний плащ. Слот для плаща открывается после облачения в полный комплект Династии. Используется Воинами, Мастерами Щита, Силачами и Бардами. Не подходит Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Finely crafted ancient cloak. The cloak slot is unlocked after equipping a full Dynasty set. Used by Warriors, Shield Masters, Berserkers, and Bards. Not suitable for Kamaels. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (14609, 'Ancient Cloak', NULL, 'Искусно отделанный древний плащ. Слот для плаща открывается после облачения в полный комплект доспехов Династии или выше. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять, выбросить.', 'Finely crafted ancient cloak. The cloak slot is unlocked after equipping a full Dynasty set or higher. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (14610, 'Ancient Cloak: Robe exclusive', NULL, 'Искусно отделанный древний плащ. Слот для плаща открывается после облачения в полный комплект Династии. Используется Целителями, Чародеями, Волшебниками и Призывателями. Не подходит Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Finely crafted ancient cloak. The cloak slot is unlocked after equipping a full Dynasty set. Used by Healers, Wizards, Spell singers/howlers, and Summoners. Not suitable for Kamaels. Cannot be modified, enchanted with attributes, or given special abilities. Cannot be traded or dropped.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (14611, 'Rudolph\'s Nose', NULL, 'Нос Рудольфа. Используется 14 дней. Нельзя обменять/выбросить.', '14-Day Limited Period	Rudolph\'s Nose. 14-day-limited-time Item. Cannot be exchanged or dropped.', 'Accessory_nose_of_rudolph_mask_i00', 0);
INSERT INTO `all_items` VALUES (14612, 'Christmas Red Sock', NULL, 'Предмет для подарков Деда Мороза, появляющийся в каждой крепости. Нельзя обменять/выбросить.', 'Santa\'s gift item appearing in every fortress. Cannot be traded or dropped.', 'xmas_present_i00', 0);
INSERT INTO `all_items` VALUES (14613, 'Rock-Paper-Scissors Santa Hat', NULL, 'При использовании в каждой крепости можно поиграть в \"Камень-Ножницы-Бумага\". Нельзя обменять/выбросить.', 'When used, one can play rock-paper-scissors with Thomas D. Turkey in each territory. Cannot be exchanged or dropped.', 'accessory_santas_cap_i00', 0);
INSERT INTO `all_items` VALUES (14614, 'Santa\'s Buff Gift Set', NULL, 'Новогодний Набор Положительных Эффектов. При использовании дарует усиливающее благословение, действие которого длится 1 час.', 'New Year Buff Set. When used, grants a buff blessing that lasts for 1 hour.', 'etc_level_bustup_ticket_i01', 3);
INSERT INTO `all_items` VALUES (14615, 'Scroll of Christmas Festival - Mage Type', NULL, 'Свиток празднования Нового Года. После использования эффект длится 1 час.', 'New Year Celebration Scroll. After use, the effect lasts for 1 hour.', 'etc_level_bustup_ticket_i02', 3);
INSERT INTO `all_items` VALUES (14616, 'Gift from Santa Claus', NULL, 'Подарок Деда Мороза.', 'Santa\'s Gift.', 'lucky_bag_box_i00', 0);
INSERT INTO `all_items` VALUES (14617, 'Agathion Seal Bracelet - Rudolph', NULL, 'Браслет для призыва Агатиона Рудольфа. Используется 14 дней. Нельзя обменять/выбросить.', 'The bracelet which can summon cute Rudolph Agathion. 14-day-limited-time Item. Cannot be exchanged or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (14618, 'Agathion Seal Bracelet - Rudolph', NULL, 'Браслет для призыва Агатиона Рудольфа. Можно использовать только в период новогодних праздников. Нельзя обменять/выбросить.', 'A bracelet used to summon the Rudolph Agathion. Can only be used during the New Year holidays. Cannot be traded or dropped.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (14619, 'Santa Claus\' Weapon Exchange Ticket', NULL, 'Подарок Деда Мороза. Меняется на оружие у Рождественской Кошки.', 'Santa\'s Gift. Can be exchanged for a weapon with the Christmas Cat.', 'etc_level_bustup_ticket_i00', 0);
