INSERT INTO `all_items` VALUES (14664, 'Gludio Protection Earring', NULL, 'Серьга, которой награждается Хранитель Глудио. Оглушающая атака +15%, Защита от кровотечения +15%, Защита от Воды +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Gludio territory. Stun Attack +15%, Bleed Defense +15%, Water Power Defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14665, 'Dion Protection Earring', NULL, 'Серьга, которой награждается Хранитель Диона. Удерживающая атака +15%, Защита от отравления +15%, Защита от Святости +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Dion territory. Hold Attack +15%, Resistance to Poison +15%,  Resistance to Holy +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14666, 'Giran Protection Earring', NULL, 'Серьга, которой награждается Хранитель Гирана. Кровопускающая атака +15%, Защита от паралича +15%, Защита от Ветра +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Giran territory. Bleed Attack +15%, Paralysis Defense +15%, Wind Power Defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14667, 'Oren Protection Earring', NULL, 'Серьга, которой награждается Хранитель Орена. Парализующая атака +15%, Защита от удержания +15%, Защита от Тьмы +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Oren territory. Paralysis attack +15%, hold defense +15%, darkness defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14668, 'Aden Protection Earring', NULL, 'Серьга, которой награждается Хранитель Адена. Ментальная атака +15%, Защита от оглушения +15%, Защита от Земли +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Aden territory. Mind Attack +15%, Stun Defense +15%, Earth Power Defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing two earrings with the same effect.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14669, 'Innadril Protection Earring', NULL, 'Серьга, которой награждается Хранитель Иннадрила. Усыпляющая атака +15%, Защита от оглушения +15%, Защита от Воды +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Innadril territory. Sleep Attack +15%, Stun Defense +15%, Water Power Defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14670, 'Goddard Protection Earring', NULL, 'Серьга, которой награждается Хранитель Годдарда. Оглушающая атака +15%, Защита от усыпления +15%, Защита от Огня +8. Нельзя обменять/выбросить.', 'An earring awarded to the Goddard Guardian. Stun attack resistance +15%, Sleep resistance +15%, Fire resistance +8. Cannot be traded or dropped.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14671, 'Rune Protection Earring', NULL, 'Серьга, которой награждается Хранитель Руны. Ядовитая атака +15%, Защита от удержания +15%, Защита от Огня +8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Rune territory. Poison Attack +15%, Hold Defense +15%, Fire Power Defense +8. Cannot be exchanged or dropped. Only one effect is applied when wearing the same two earrings.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14672, 'Schuttgart Protection Earring', NULL, 'Серьга, которой награждается Хранитель Шутгарта. Удерживающая атака +15%, Защита от страха +15%, Защита от Ветра на 8. Нельзя обменять/выбросить.', 'Earring given to the guardian of Schuttgart. Hold attack +15%, mental attack defense +15%, resistance to wind +8. Cannot be exchanged or dropped. Only one effect is applied when two earrings with the same effect are equipped.', 'accessary_inferno_earing_i00', 0);
INSERT INTO `all_items` VALUES (14673, 'Rudolph\'s Nose', NULL, 'Нос Рудольфа. Используется только в период новогодних праздников.', 'Rudolph\'s Nose. Can only be used during the New Year holidays.', 'Accessory_nose_of_rudolph_mask_i00', 0);
INSERT INTO `all_items` VALUES (14674, 'Santa Claus\' Tallum Blade*Damascus', NULL, 'Клинок Таллума*Дамаскус - Новогодний Подарок', 'Santa Claus\' Tallum Blade*Damascus', 'weapon_dual_sword_i00', 0);
INSERT INTO `all_items` VALUES (14675, 'Agathion Seal Bracelet - Neolithica', NULL, 'Браслет для призыва Агатиона. Нельзя обменять/выбросить.', 'Bracelet that can summon an Agathion. Cannot be exchanged or dropped. Cannot receive the gift if the inventory and weight are full.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (14676, 'Agathion\'s New Year\'s Gift', NULL, 'Новогодний Подарок: Агатион. Щелкните два раза по предмету, чтобы получить подарок.', 'New Year Gift: Agathion. Double-click the item to receive a gift.', 'etc_pi_gift_box_i03', 0);
INSERT INTO `all_items` VALUES (14677, 'Agathion\'s New Year\'s Gift', NULL, 'Новогодний Подарок: Агатион. Щелкните два раза по предмету, чтобы получить подарок.', 'New Year Gift: Agathion. Double-click the item to receive a gift.', 'etc_pi_gift_box_i03', 0);
INSERT INTO `all_items` VALUES (14678, 'Neolithic Crystal - B', NULL, 'У Менеджера Витаминов можно обменять обычный предмет Ранга B на Редкий предмет.', 'You can exchange a regular B-grade item for a Rare item with the Vit Manager.', 'etc_warding_orb_blue_i00', 0);
INSERT INTO `all_items` VALUES (14679, 'Neolithic Crystal - A', NULL, 'У Менеджера Витаминов можно обменять обычный предмет Ранга А на Редкий предмет.', 'You can exchange a regular A-grade item for a Rare item with the Vit Manager.', 'etc_warding_orb_green_i00', 0);
INSERT INTO `all_items` VALUES (14680, 'Neolithic Crystal - S', NULL, 'У Менеджера Витаминов можно обменять обычный предмет Ранга S на Редкий предмет.', 'You can exchange a regular S-grade item for a Rare item with the Vit Manager.', 'etc_warding_orb_red_i00', 0);
INSERT INTO `all_items` VALUES (14681, 'Neolithic Crystal - S80', NULL, 'У Менеджера Витаминов можно обменять обычный предмет Ранга S80 на Редкий предмет.', 'You can exchange a regular S80-grade item for a Rare item with the Vit Manager.', 'etc_warding_orb_black_i00', 0);
INSERT INTO `all_items` VALUES (14682, 'Greater Elixir of Life (No-Grade)', NULL, 'Восстанавливает HP. Используется персонажами, чей уровень меньше 19-го. Эффект накладывается только на персонажа, выпившего эликсир. Время перезарядки: 5 минут.', 'Restores HP. Used by characters below level 19. The effect applies only to the character who drank the elixir. Reuse delay: 5 minutes.', 'etc_super_hp_potion_i00', 24);
INSERT INTO `all_items` VALUES (14683, 'Greater Elixir of Life (D-Grade)', NULL, 'Восстанавливает HP. Используется персонажами от 20-го до 39-го уровня. Эффект накладывается только на персонажа, выпившего эликсир. Время перезарядки: 5 мин.', 'Restores HP. Used by characters from level 20 to 39. The effect applies only to the character who drank the elixir. Reuse delay: 5 min.', 'etc_super_hp_potion_i01', 24);
INSERT INTO `all_items` VALUES (14684, 'Greater Elixir of Life (C-Grade)', NULL, 'Восстанавливает HP. Используется персонажами от 40-го до 51-го уровня. Эффект накладывается только на персонажа, выпившего эликсир. Время перезарядки: 5 мин.', 'Restores HP. Used by characters from level 40 to 51. The effect applies only to the character who drank the elixir. Reuse delay: 5 min.', 'etc_super_hp_potion_i02', 24);
INSERT INTO `all_items` VALUES (14685, 'Greater Elixir of Life (B-Grade)', NULL, 'Восстанавливает HP. Используется персонажами от 52-го до 60-го уровня. Эффект накладывается только на персонажа, выпившего эликсир. Время перезарядки: 5 мин.', 'Restores HP. Used by characters from level 52 to 60. The effect applies only to the character who drank the elixir. Reuse delay: 5 min.', 'etc_super_hp_potion_i03', 24);
INSERT INTO `all_items` VALUES (14686, 'Greater Elixir of Life (A-Grade)', NULL, 'Восстанавливает HP. Используется персонажами от 61-го до 75-го уровня. Эффект накладывается только на персонажа, выпившего эликсир. Время перезарядки: 5 мин.', 'Restores HP. Used by characters from level 61 to 75. The effect applies only to the character who drank the elixir. Reuse delay: 5 min.', 'etc_super_hp_potion_i04', 24);
