INSERT INTO `all_items` VALUES (14702, 'Agathion Auxiliary Stone: Enchant Weapon (D-Grade)', NULL, 'При модификации оружия Ранга D увеличивает шанс успеха на 20%. Используется только для модификации на +4-9.', 'When enchanting D-grade weapons, increases success rate by 20%. Used only for enchanting from +4 to +9.', 'ench_wp_stone_i00', 27);
