INSERT INTO `all_items` VALUES (14719, 'Full Vitality Event Pack', NULL, 'Ивентовая Коробка ЭнергииСодержит 1 Браслет Печати Агатиона: Сэром. Нельзя передать или выкинуть, можно положить в личное хранилище.', 'Event Energy Box. Contains 1 Agathion Seal Bracelet: Cern. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (14720, 'Event - Apiga', NULL, 'Деньги созданий из магической лаборатории. Отдайте их в магическую лабораторию за вознаграждение. Нельзя выбросить.', 'Currency from the magic laboratory. Return them to the magic laboratory for a reward. Cannot be dropped.', 'etc_pig_adena_i01', 0);
INSERT INTO `all_items` VALUES (14721, 'Event - Golden Apiga', NULL, 'Редкие деньги созданий из магической лаборатории. Если принести их в магическую лабораторию, то есть вероятность получения Энергетического Зелья. Нельзя выбросить.', 'Rare currency from the magic laboratory. Bringing them to the magic laboratory grants a chance to obtain an Energy Potion. Cannot be dropped.', 'etc_pig_adena_i00', 0);
INSERT INTO `all_items` VALUES (14722, 'Event - Cupid\'s Fatigue Recovery Potion', NULL, 'Восстанавливает силы Коровы.', 'Restores the Cow\'s energy.', 'etc_faitgue_relief_of_cupid_i00', 24);
INSERT INTO `all_items` VALUES (14723, 'Event - Cupid\'s Powerful Fatigue Recovery Potion', NULL, 'Восстанавливает силы Коровы. Действует эффективнее, чем Ивентовое Лекарство Купидона.', 'Restores the Cow\'s energy. More effective than Cupid\'s Event Medicine.', 'etc_nutrients_of_cupid_i00', 24);
INSERT INTO `all_items` VALUES (14724, 'Event - Milk Cow Summon Scroll', NULL, 'Свиток Призыва Коровы. Если восстановить энергию Коровы, то можно получить Апигу. (Восстановление возможно только с помощью Лекарства Купидона или Сильнодействующего Лекарства Купидона.) Возможен обмен.', 'Cow Summon Scroll. Restoring the Cow\'s energy allows you to obtain an Apiga. (Restoration is possible only using Cupid\'s Medicine or Potent Cupid\'s Medicine.) Tradable.', 'etc_scroll_of_milkcattle_i00', 1);
INSERT INTO `all_items` VALUES (14725, 'Event - Head Milk Cow Summon Scroll', NULL, 'Свиток призыва Тучной Коровы. Если восстановить энергию Тучной Коровы, то можно получить Апигу. (Восстановление возможно только с помощью Лекарства Купидона или Сильнодействующего Лекарства Купидона.) Возможен обмен.', 'Fat Cow Summon Scroll. Restoring the Fat Cow\'s energy allows you to obtain an Apiga. (Restoration is possible only using Cupid\'s Medicine or Potent Cupid\'s Medicine.) Tradable.', 'etc_scroll_of_milkcattle_b_i00', 1);
INSERT INTO `all_items` VALUES (14726, 'Event - Gloomy Milk Cow Summon Scroll', NULL, 'Свиток призыва Грустной Коровы. Если восстановить энергию Грустной Коровы, то можно получить Апигу. (Восстановление возможно только с помощью Лекарства Купидона или Сильнодействующего Лекарства Купидона.) Возможен обмен.', 'Sad Cow Summon Scroll. Restoring the Sad Cow\'s energy allows you to obtain an Apiga. (Restoration is possible only using Cupid\'s Medicine or Potent Cupid\'s Medicine.) Tradable.', 'etc_scroll_of_milkcattle_i00', 1);
INSERT INTO `all_items` VALUES (14727, 'Event - Gloomy Head Milk Cow Summon Scroll', NULL, 'Свиток призыва Грустной Тучной Коровы. Если восстановить энергию Грустной Тучной Коровы, то можно получить Апигу. (Восстановление возможно только с помощью Лекарства Купидона или Сильнодействующего Лекарства Купидона.) Возможен обмен.', 'Sad Fat Cow Summon Scroll. Restoring the Sad Fat Cow\'s energy allows you to obtain an Apiga. (Restoration is possible only using Cupid\'s Medicine or Potent Cupid\'s Medicine.) Tradable.', 'etc_scroll_of_milkcattle_b_i00', 1);
INSERT INTO `all_items` VALUES (14728, 'Event - Orr Cube', '30-day limited period', 'Кубик, который используется 30 дней. Щелкните два раза по предмету, чтобы получить Часть Кубика Руды. Нельзя обменять/выбросить. (Можно использовать только один раз в день.)', 'A cube that can be used for 30 days. Double-click the item to obtain a Cube Ore Piece. Cannot be traded or dropped. (Can only be used once a day.)', 'etc_ore_cube_event_i00', 24);
INSERT INTO `all_items` VALUES (14729, 'Event - Crystal Cube', NULL, 'Одноразовый кубик. Чтобы получить Часть Кристального Кубика, щелкните на нем два раза левой кнопкой мыши.', 'A single-use cube. Double-click it with the left mouse button to obtain a Crystal Cube Piece.', 'etc_crystal_cube_event_i00', 0);
INSERT INTO `all_items` VALUES (14730, 'Event - Gold Crystal Cube Fragment', NULL, 'О предназначении этого предмета можно узнать у Смотрителя Склада. Нельзя выбросить.', 'You can learn about the purpose of this item from the Warehouse Keeper. Cannot be dropped.', 'etc_golden_ore_cube_pc_i00', 0);
INSERT INTO `all_items` VALUES (14731, 'Event - Silver Crystal Cube Fragment', NULL, 'О предназначении этого предмета можно узнать у Смотрителя Склада. Нельзя выбросить.', 'You can learn about the purpose of this item from the Warehouse Keeper. Cannot be dropped.', 'etc_silver_ore_cube_pc_i00', 0);
