INSERT INTO `all_items` VALUES (14795, 'Baguette\'s Dualsword', NULL, 'Парные Мечи, изготовленные из хлеба. Нельзя обменять, выбросить или продать. Можно положить в личное хранилище.', 'Two-handed sword made of bread. Two-handed sword containing Baguett\'s great power. No exchange, drop, or sale available. Can be stored in a private warehouse.', 'weapon_dual_sword_i00', 0);
INSERT INTO `all_items` VALUES (14796, 'Baguette\'s Sigil', NULL, 'Символ, изготовленный из хлеба. Нельзя обменять, выбросить или продать. Можно положить в личное хранилище.', 'Sigil made of bread. Can feel Baguette\'s ease. No exchange, drop, or sale available. Can be stored in a private warehouse.', 'dynasty_sigil_i00', 0);
INSERT INTO `all_items` VALUES (14797, 'Baguette\'s Two-handed Dagger', NULL, 'Парные Кинжалы, изготовленные из хлеба. Нельзя обменять, выбросить или продать. Можно положить в личное хранилище.', 'Two-handed dagger made of bread. Can feel Baguette\'s sharpness. No exchange, drop, or sale available. Can be stored in a private warehouse.', 'dual_dagger_i00', 0);
INSERT INTO `all_items` VALUES (14798, 'Afro Perm Wig - Black', NULL, 'Шикарный парик в стиле афро. Нельзя снять.', 'Lush Afro perm hair. Cannot undo equip', 'accessory_captain_cap_i00', 0);
INSERT INTO `all_items` VALUES (14799, 'Afro Perm Wig - Gold', NULL, 'Шикарный парик в стиле афро. Нельзя снять.', 'Lush Afro perm hair. Cannot undo equip', 'accessory_captain_cap_i00', 0);
INSERT INTO `all_items` VALUES (14800, 'Afro Perm Wig - Pink', NULL, 'Шикарный парик в стиле афро. Нельзя снять.', 'A fancy afro wig. Cannot be removed.', 'accessory_captain_cap_i00', 0);
INSERT INTO `all_items` VALUES (14801, 'Gludio Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Глудио. Оглушающая атака +15%, Защита от кровотечения +15%, Защита от Воды +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Gludio Guard. Stun attack resistance +15%, Bleed resistance +15%, Water resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14802, 'Dion Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Диона. Удерживающая атака +15%, Защита от отравления +15%, Защита от Святости +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Dion Guard. Hold attack resistance +15%, Poison resistance +15%, Divine resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14803, 'Giran Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Гирана. Кровопускающая атака +15%, Защита от паралича +15%, Защита от Ветра +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Giran Guard. Bleed attack resistance +15%, Paralysis resistance +15%, Wind resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14804, 'Oren Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Орена. Парализующая атака +15%, Защита от удержания +15%, Защита от Тьмы +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Oren Guard. Paralysis attack resistance +15%, Hold resistance +15%, Dark resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14805, 'Aden Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Адена. Ментальная атака +15%, Защита от оглушения +15%, Защита от Земли +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Aden Guard. Mental attack resistance +15%, Stun resistance +15%, Earth resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14806, 'Innadril Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Иннадрила. Усыпляющая атака +15%, Защита от оглушения +15%, Защита от Воды +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Innadril Guard. Sleep attack resistance +15%, Stun resistance +15%, Water resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14807, 'Goddard Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Годдарда. Оглушающая атака +15%, Защита от усыпления +15%, Защита от Огня +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Goddard Guard. Stun attack resistance +15%, Sleep resistance +15%, Fire resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14808, 'Rune Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Руны. Отравляющая атака +15%, Защита от удержания +15%, Защита от Огня +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Rune Guard. Poison attack resistance +15%, Hold resistance +15%, Fire resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14809, 'Schuttgart Guard Earring', NULL, 'Серьга, которой награждается Гвардеец Шутгарта. Удерживающая атака +15%, Защита от устрашения +15%, Защита от Ветра +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'An earring awarded to the Schuttgart Guard. Hold attack resistance +15%, Fear resistance +15%, Wind resistance +10, Max CP +5%. Cannot be traded or dropped.', 'accessory_earring_of_domi_protection_i00', 0);
INSERT INTO `all_items` VALUES (14810, 'Blue Talisman - Buff Cancel', NULL, 'Снимает положительные эффекты с противников, находящихся неподалеку. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'Removes buffs from nearby enemies. When using two talismans, the effect does not change. Shadow item. Cannot be traded or dropped.', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (14811, 'Blue Talisman - Buff Steal', NULL, 'Забирает положительный эффект противника. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'Steals the target\'s abnormal status upon use. Only one effect is applied when you wear the same two talismans. Shadow Item with no exchange/drop available', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (14812, 'Red Talisman - Territory Guard', NULL, 'Увеличивает Макс. СР, восстанавливает уровень СР. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'When used, Max CP is greatly increased and a certain amount of CP is greatly recovered. Only one effect is applied when you wear the same two talismans. Shadow Item with no exchange/drop available', 'etc_talisman_i00', 0);
INSERT INTO `all_items` VALUES (14813, 'Blue Talisman - Lord\'s Divine Protection', NULL, 'Уменьшает урон, получаемый во время PvP. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'Upon use, greatly decreases the damage received during PvP. Only one effect is applied when you wear the same two talismans. Shadow Item with no exchange/drop available', 'etc_talisman_i01', 0);
INSERT INTO `all_items` VALUES (14814, 'White Talisman -  All Resistance', NULL, 'Увеличивает сопротивление ко всем стихиям. При использовании двух талисманов эффект не суммируется. Теневой предмет. Нельзя обменять/выбросить.', 'Increases Resistance to all elements. Effect does not stack with additional Talismans of the same type. This item cannot be traded or dropped.', 'etc_talisman_i06', 0);
INSERT INTO `all_items` VALUES (14815, 'Territory Health Recovery Potion', NULL, 'Восстанавливает уровень HP. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'Restores HP level. Does not work for characters below level 61. Can be used exclusively on the battlefield.', 'etc_super_hp_potion_i05', 24);
INSERT INTO `all_items` VALUES (14816, 'Territory Mana Recovery Potion', NULL, 'Восстанавливает уровень MP. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'Restores MP level. Does not work for characters below level 61. Can be used exclusively on the battlefield.', 'etc_super_mp_potion_i05', 24);
INSERT INTO `all_items` VALUES (14817, 'Territory CP Recovery Potion', NULL, 'Восстанавливает уровень СР. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'Restores CP level. Does not work for characters below level 61. Can be used exclusively on the battlefield.', 'etc_super_cp_potion_i05', 24);
INSERT INTO `all_items` VALUES (14818, 'Enriched Pet Food for Wolves', NULL, 'Восстанавливает уровень сытости Питомца.', 'Restores pet\'s satiety level.', 'etc_pouch_red_i00', 0);
INSERT INTO `all_items` VALUES (14819, 'Guardian\'s Dragon Bugle', NULL, 'Горн, необходимый для призыва Ездового Дракона Хранителя. Питомец забирает часть опыта, заработанного хозяином.', 'A horn required to summon the Guardian Strider. The pet takes a portion of the experience earned by its master.', 'etc_bugle_i00', 7);
INSERT INTO `all_items` VALUES (14820, 'Skull Key of Suffering', NULL, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Зал Страданий.', 'A key required by high-level undead for free movement through the Seed of Immortality. Grants entry to the Hall of Suffering.', 'etc_skeleton_key_i00', 0);
INSERT INTO `all_items` VALUES (14821, 'Skull Key of Erosion', NULL, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Зал Гибели.', 'A key required by high-level undead for free movement through the Seed of Immortality. Grants entry to the Hall of Agony.', 'etc_skeleton_key_i00', 0);
INSERT INTO `all_items` VALUES (14822, 'Skull Key of the Heart', NULL, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Источник Бессмертия.', 'A key required by high-level undead for free movement through the Seed of Immortality. Grants entry to the Heart of Immortality.', 'etc_skeleton_key_i00', 0);
INSERT INTO `all_items` VALUES (14823, 'Soul Extraction Device', NULL, 'Устройство, позволяющее извлечь души из монстров. Доступно исключительно в Семени Бессмертия.', 'A device used to extract souls from monsters. Available exclusively in the Seed of Immortality.', 'etc_lantern_i00', 0);
