INSERT INTO `all_items` VALUES (14828, 'Deinonychus Mesozoic Stone', NULL, 'Камень, позволяющий призвать первозданное существо Дейнониха', 'A stone used to summon a primordial Deinonychus.', 'etc_life_stone_of_begining_i00', 7);
INSERT INTO `all_items` VALUES (14829, 'Cave Exploration Text 1 Sheet', NULL, 'Книга, в которой путешественники записали результаты исследования пещер', 'A book in which travelers recorded the results of cave explorations.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14830, 'Cave Exploration Text 2 Sheet', NULL, 'Книга, в которой описаны результаты исследования изменений Гигантов', 'A book describing the results of research on Giant mutations.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14831, 'Cave Exploration Text 3 Sheet', NULL, 'Книга, в которой записан секрет Хекатонов Прайм', 'A book recording the secret of Hekaton Prime.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14832, 'Growth Accelerator', NULL, 'Здесь хранится кровь Стакато.', 'Staccato blood is stored here.', 'etc_medicine_of_growth_i00', 3);
INSERT INTO `all_items` VALUES (14833, 'Small Stakato Cocoon', NULL, 'У этого кокона очень плотные стенки. Но вряд ли внутри него теплится жизнь. Слишком уж он мал.', 'This cocoon has very thick walls. However, life is hardly stirring inside. It is simply too small.', 'etc_dragon_egg_i04', 0);
INSERT INTO `all_items` VALUES (14834, 'Large Stakato Cocoon', NULL, 'У этого кокона очень плотные стенки. Но вряд ли внутри него теплится жизнь. Слишком уж он огромен.', 'This cocoon has very thick walls. However, life is hardly stirring inside. It is simply too huge.', 'etc_dragon_egg_i01', 0);
INSERT INTO `all_items` VALUES (14835, 'Multi-colored Jewel', NULL, 'Разноцветный минерал. Использовав его, можно попасть ко входу в Гнездо Стакато.', 'A multicolored mineral. Using it will take you to the entrance of the Staccato Nest.', 'etc_crystal_cave_crystal_i02', 0);
INSERT INTO `all_items` VALUES (14836, 'Knowledge of the Giants Anthology, Chapter 1', NULL, 'Часть Древнего Писания Гигантов. 1-й том из 5.', 'Part of Ancient Giant Scripture. Volume 1 of 5.', 'etc_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (14837, 'Knowledge of the Giants Anthology, Chapter 2', NULL, 'Часть Древнего Писания Гигантов. 2-й том из 5.', 'Part of Ancient Giant Scripture. Volume 2 of 5.', 'etc_paper_black_i00', 0);
