INSERT INTO `all_items` VALUES (14841, 'Ancient Parchment', NULL, 'Пергамент Гигантов. Дважды кликнув на нем, можно прочесть написанное.', 'Giant Parchment. Double-click to read what is written.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (14842, 'Wisdom of the Giants Text, Chapter 1', NULL, 'Книга, в которой собраны все отчеты об исследованиях Гигантов. 1-й том из 5.', 'A book containing all Giant research reports. Volume 1 of 5.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (14843, 'Wisdom of the Giants Text, Chapter 2', NULL, 'Книга, в которой собраны все отчеты об исследованиях Гигантов. 2-й том из 5.', 'A book containing all Giant research reports. Volume 2 of 5.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (14844, 'Wisdom of the Giants Text, Chapter 3', NULL, 'Книга, в которой собраны все отчеты об исследованиях Гигантов. 3-й том из 5.', 'A book containing all Giant research reports. Volume 3 of 5.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (14845, 'Wisdom of the Giants Text, Chapter 4', NULL, 'Книга, в которой собраны все отчеты об исследованиях Гигантов. 4-й том из 5.', 'A book containing all Giant research reports. Volume 4 of 5.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (14846, 'Wisdom of the Giants Text, Chapter 5', NULL, 'Книга, в которой собраны все отчеты об исследованиях Гигантов. 5-й том из 5.', 'A book containing all Giant research reports. Volume 5 of 5.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (14847, 'Titan Ancient Book', NULL, 'Книга Гигантов. Дважды кликнув на ней, можно ее прочитать.', 'Book of Giants. Double-click to read it.', 'etc_spell_books_black_i00', 0);
INSERT INTO `all_items` VALUES (14848, 'Protection Soul\'s Pendant', NULL, 'Амулет, защищенный от притязаний злых духов. В середине его находится ядро, излучающее красный свет.', 'An amulet protected from the claims of evil spirits. In its middle is a core emitting red light.', 'ect_charm_of_protection_i00', 0);
INSERT INTO `all_items` VALUES (14849, 'Kahman\'s Supply Box', NULL, 'Ящик припасов, полученный от Кахмана. Дважды кликнув на нем, можно посмотреть, что хранится внутри.', 'Supply box obtained from Kahman. Double-click to see what is stored inside.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (14850, 'Droph\'s Support Items', NULL, 'Подарок, полученный у Дрогфа за истребление Хекатонов Прайм. Дважды кликнув на нем, можно посмотреть, что хранится внутри.', 'Gift received from Drogf for exterminating Hekaton Primes. Double-click to see what is stored inside.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (14851, 'Cave Exploration Text 1 Sheet', NULL, 'Книга, в которой путешественники записали результаты исследования пещер.', 'A book in which travelers recorded the results of cave explorations.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14852, 'Cave Exploration Text 2 Sheet', NULL, 'Книга, в которой описаны результаты исследования изменений Гигантов.', 'A book describing the results of research on Giant mutations.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14853, 'Cave Exploration Text 3 Sheet', NULL, 'Книга, в которой записан секрет Хекатонов Прайм.', 'A book recording the secret of Hekaton Prime.', 'etc_cave_page_i00', 0);
INSERT INTO `all_items` VALUES (14854, 'Recipe - Spiteful Soul Energy', NULL, 'Квестовый рецепт. Необходим для изготовления Энергии Души. Необходимо умение \"Создать Вещь\" 2-го уровня.', 'Quest recipe. Required to craft Soul Energy. Requires Create Item Level 2.', 'etc_recipe_white_i00', 0);
INSERT INTO `all_items` VALUES (14855, 'Spiteful Soul Energy', NULL, 'Душа, полученная у Главаря Злобных Душ. Соберите их и отнесите Бальтазару.', 'A soul obtained from the Malevolent Spirit Leader. Collect them and take them to Balthazar.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (14856, 'Spiteful Soul Vengeance', NULL, 'Сфера, полученная у Главаря Злобных Душ. Не наполненная энергией, она никому не нужна.', 'A sphere obtained from the Malevolent Spirit Leader. Uncharged with energy, it is useless to anyone.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (14857, 'Shell of Monsters', NULL, 'Панцирь, полученный во время сражения с монстрами недалеко от Пещеры Гигантов. Отнесите его Магистру Ханелин.', 'A carapace obtained during battle with monsters near the Cave of Giants. Take it to Magister Hanellin.', 'etc_bark_gold_i00', 0);
INSERT INTO `all_items` VALUES (14858, 'Scout\'s Note', NULL, 'Записка, найденная при осмотре трупа Разведчика. Необходимо отнести Капитану Наемников Пирсу.', 'A note found while examining a Scout\'s corpse. Must be taken to Mercenary Captain Pierce.', 'etc_piece_of_report_i00', 0);
INSERT INTO `all_items` VALUES (14859, 'Stakato Queen\'s Fang', NULL, 'Клык, полученный у Королевы Стакато Шиид. Необходимо отнести Наемнику Кахману.', 'A fang obtained from Staccato Queen Shyeed. Must be taken to Mercenary Kahman.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (14860, 'Box Containing the Flame of the Holy Spirit', NULL, 'Ящик, таящий в себе благословенный огонь. Необходимо отнести Смотрителю Маяка Торранту в Логово Зла.', 'A box concealing blessed fire. Must be taken to Lighthouse Keeper Torrent in the Plains of the Lizardmen (Corpse / Wretched / Devastated Castle).', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (14861, 'Cursed Burial Items', NULL, 'Украшение, созданное злыми духами.', 'An ornament created by evil spirits.', 'etc_totem_black_i00', 0);
INSERT INTO `all_items` VALUES (14862, 'Flauen\'s Letter', NULL, 'Письмо Хранителя Портала Хейна - Флоена. Отнеся это Ясону Хейну, можно подробнее узнать о предстоящем задании.', 'A letter from Heine Port Keeper Floen. Taking this to Jason Heine will allow you to learn more about the upcoming task.', 'etc_letter_envelope_i00', 0);
INSERT INTO `all_items` VALUES (14863, 'Letter to Helvetica', NULL, 'Документ с обещанием Ясона Хейна о готовности выслать помощь. Необходимо отнести разработчику Гельдремов Гаке на Поля Безмолвия.', 'A document with Jason Heine\'s promise of readiness to send assistance. Must be taken to Gekka, the Gelid developer at the Fields of Silence.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (14864, 'Letter to Athenia', NULL, 'Документ с обещанием Ясона Хейна о готовности выслать помощь. Необходимо отнести на Шепчущие Поля Повелителю Духов Минеру.', 'A document with Jason Heine\'s promise of readiness to send assistance. Must be taken to Spirit Lord Miner at the Whispering Fields.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (14865, 'Certificate of Support', NULL, 'Документ, полученный у Гаки, разработчика Гельдремов. Необходим для получения дополнительной миссии.', 'A document obtained from Gekka, the Gelid developer. Required to receive an additional mission.', 'etc_letter_red_i00', 0);
INSERT INTO `all_items` VALUES (14866, 'Certificate of Support', NULL, 'Документ, полученный у Минера, Повелителя Духов. Необходим для получения дополнительной миссии.', 'A document obtained from Spirit Lord Miner. Required to receive an additional mission.', 'etc_letter_blue_i00', 0);
INSERT INTO `all_items` VALUES (14867, 'Damaged Torch Fragment', NULL, 'Обломок, оставшийся после разрушения Алтаря Огня, находившегося в окрестностях Лагеря Поклонения Огню. Соберите их и отнесите Гаке, разработчику Гельдремов.', 'A fragment left after the destruction of the Fire Altar located near the Camp of Fire Worship. Collect them and take them to Gekka, the Gelid developer.', 'etc_charcoal_i00', 0);
INSERT INTO `all_items` VALUES (14868, 'Guardian Spirit Fragment', NULL, 'Частица, полученная во время охоты на Хранителей Огня и Духов Огненной Защиты. Соберите их и отнесите Гаке, разработчику Гельдремов.', 'A particle obtained while hunting Fire Guardians and Fire Protection Spirits. Collect them and take them to Gekka, the Gelid developer.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (14869, 'Destroyed machine piece', NULL, 'Обломок одной из составных частей Измельчителя Мусора. Соберите их и отнесите Повелителю Духов, Минеру.', 'A fragment of one of the Trash Shredder\'s components. Collect them and take them to Spirit Lord Miner.', 'etc_plate_black_i00', 0);
INSERT INTO `all_items` VALUES (14870, 'Enchanted Golem Shard', NULL, 'Осколок Гельдрема, полученный во время охоты. Отнесите его Повелителю Огня Минеру.', 'A Gelid shard obtained during hunting. Take it to Fire Lord Miner.', 'etc_plate_glay_i00', 0);
INSERT INTO `all_items` VALUES (14871, 'Mucrokian Hide', NULL, 'Доказательство победы над Макронианами. Отнесите это Конт Тэн Саузену в Укрепление Разработчиков Гельдремов.', 'Proof of victory over Macronians. Take it to Cont Ten Sauzen at the Gelid Developer Outpost.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (14872, 'Awakened Mucrokian Hide', NULL, 'Доказательство победы над Зараженными Макронианами. Отнесите это Счетчику в Укрепление Разработчиков Гельдремов.', 'Proof of victory over Infected Macronians. Take it to the Counter at the Gelid Developer Outpost.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (14873, 'Mucrokian Hide', NULL, 'Доказательство победы над Макронианами. Отнесите это Участнику Ритуала Поклонения Огню Ауту.', 'Proof of victory over Macronians. Take it to Fire Worship Ritual Participant Aut.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (14874, 'Fallen Mucrokian Hide', NULL, 'Доказательство победы над Измененными Макронианами. Отнесите это Участнику Ритуала Поклонения Огню Ауту.', 'Proof of victory over Modified Macronians. Take it to Fire Worship Ritual Participant Aut.', 'etc_leather_brown_i00', 0);
INSERT INTO `all_items` VALUES (14875, 'Mineral Fragment', NULL, 'Осколок, полученный в бою на территории Мифрилового Рудника. Возьмите его и отнесите в Деревню Гномов Представителю Гильдии Серой Колонны Филару.', 'A shard obtained in battle in the Mithril Mines area. Take it to Gray Pillar Guild Representative Filar in the Dwarven Village.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (14876, 'Evidence of Migration', NULL, 'Документ, свидетельствующий об успешной поездке к Крысолюдам. Возьмите его и отнесите Командиру Грабителей Могил Канемике.', 'A document proving a successful trip to Ratmen. Take it to Grave Robber Commander Kanemika.', 'etc_paper_red_i00', 0);
INSERT INTO `all_items` VALUES (14877, 'Replenished Power Bead', NULL, 'Бусина Алтаря Люсьена, необходимый для поддержания энергетического запаса границ. Необходимо отнести это в каждый из Алтарей Люсьена для усиления границ между мирами.', 'Lucien\'s Altar Bead, required to maintain the boundary energy supply. Must be taken to each of Lucien\'s Altars to strengthen the boundaries between worlds.', 'etc_crystal_ball_blue_i00', 0);
INSERT INTO `all_items` VALUES (14878, 'Discharged Power Bead', NULL, 'Разряженная Бусина. Является свидетельством выполнения задания. После подзарядки всех Алтарей Люсьена необходимо отнести в Деревню Гномов Жрецу Земли Дайчиру.', 'Discharged Bead. Proof of completing the task. After recharging all of Lucien\'s Altars, it must be taken to Earth Priest Daichir in the Dwarven Village.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (14879, 'Stakato Fang', NULL, 'Клык, полученный во время сражения со Стакато в Гнезде Стакато. Отнесите это Наемнику Кахману и докажите свои способности.', 'A fang obtained during battle with Staccatos in the Staccato Nest. Take it to Mercenary Kahman to prove your abilities.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (14880, 'Dirty Bead', NULL, 'Бусина, полученная в битве со Стакато. Эту непонятную вещь необходимо отнести Кинтайджину.', 'A bead obtained in battle against Staccatos. This incomprehensible item must be taken to Kintaijin.', 'etc_bead_gold_i00', 0);
INSERT INTO `all_items` VALUES (14881, 'Soul Core Containing Evil Spirit', NULL, 'Ядро, наполненное злой энергией. Излучает слабый фиолетовый свет.', 'A core filled with evil energy. Emits a faint purple light.', 'etc_evil_soul_core_i00', 0);
INSERT INTO `all_items` VALUES (14882, 'Ragna Orc\'s Amulet', NULL, 'Игрушка, используемая Орками Рагна для управления другими существами. Возьмите ее и отнесите Смотрителю Маяка Торранту.', 'A toy used by Ragna Orcs to control other creatures. Take it and deliver it to Lighthouse Keeper Torrent.', 'etc_totem_red_i00', 0);
INSERT INTO `all_items` VALUES (14883, 'Hisilrome\'s Heart', NULL, 'Сердце, полученное после сражения с Хисилромой.', 'A heart obtained after battling Hissilroma.', 'etc_bodypart_heart_i00', 0);
INSERT INTO `all_items` VALUES (14884, 'Gludio Supply Box - Magic Rune Clip', 'Grade S, A', 'Сундук с гербом Глудио. Открыв его, можно получить Магическую Заколку высокого Ранга.', 'Gludio Crest Chest. Opening it grants a High-grade Magic Hairpin.', 'etc_box_of_adventure_1_i00', 0);
