INSERT INTO `all_items` VALUES (14902, 'Sealed Magic Rune Clip (A-Grade)', NULL, 'Печать можно снять у Ольфа Каноре или Ольфа Адамса.', 'The seal can be removed by Olf Kanore or Olf Adams.', 'etc_rune_clip_i00', 0);
