INSERT INTO `all_items` VALUES (14906, 'Low-level Magic Rune Clip (A-Grade)', NULL, 'Используется для улучшения Железного Пояса.', 'Used to upgrade an Iron Belt.', 'etc_rune_clip_i00', 0);
