INSERT INTO `all_items` VALUES (14910, 'Low-level Magic Rune Clip (S-Grade)', NULL, 'Используется для улучшения Мифрилового Пояса.', 'Used to upgrade a Mithril Belt.', 'etc_rune_clip_i00', 0);
