INSERT INTO `all_items` VALUES (15186, 'Г‰clair Bijou of Fortune', '10-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +6%. Наносит дополнительный урон в PvP. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений Вами и членами Вашей группы. Нельзя обменять/выбросить.', '1-Day Limited Period	Kamael-exclusive Weapon. Increases Atk. Spd. by about 6%. Increases damage inflicted during PvP. Has a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (15187, 'Colichemarde of Fortune', '10-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +6%. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений Вами и членами Вашей группы. Нельзя обменять/выбросить.', '1-Day Limited Period	Kamael-exclusive Weapon. Increases Atk. Spd. by about 6%, and improves the chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_colichemarde_i01', 3);
INSERT INTO `all_items` VALUES (15188, 'Admiral\'s Estoc of Fortune', '10-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +7%. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений Вами и членами Вашей группы. Нельзя обменять/выбросить.', '1-Day Limited Period	Kamael-exclusive Weapon. Increases Atk. Spd. by about 7%, and improves the chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_blink_slasher_i01', 2);
INSERT INTO `all_items` VALUES (15189, 'Grand Г‰pГ©e of Fortune', '10-day limited period', 'Эксклюзивное оружие Камаэль. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений Вами и членами Вашей группы. Нельзя обменять/выбросить.', '1-Day Limited Period	Kamael-exclusive Weapon. Has a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_rapier_i00', 1);
INSERT INTO `all_items` VALUES (15190, 'Screaming Vengeance of Fortune', '10-day limited period', 'Эксклюзивное оружие Камаэль. Крит. Атк. + 61. Наносит дополнительный урон в PvP. Нельзя обменять/выбросить.', 'Kamael Exclusive Weapon. Critical Damage +61. Deals extra damage in PvP. Cannot be traded or dropped.', 'weapon_soul_shooter_i01', 4);
