INSERT INTO `all_items` VALUES (15208, 'Bracelet of Friendship', '30-day limited period', 'Браслет Дружбы, позволяющий призвать друга к себе. Необходимо, чтобы оба человека обладали Браслетом Дружбы. Время действия: 30 дн. Нельзя обменять/выбросить.', 'Friendship Bracelet allowing you to summon a friend to your location. Requires both players to have a Friendship Bracelet. Duration: 30 days. Cannot be traded or dropped.', 'accessory_ring_of_friendship_i00', 0);
INSERT INTO `all_items` VALUES (15209, 'Equipment Set 10-Day Pack Exchange Coupon', NULL, 'Использовав талон, можно превратить комплект предметов в упаковку (10 дн.).', 'Using this ticket transforms the item set into a package (10 days).', 'etc_exchange_ticket_i00', 0);
INSERT INTO `all_items` VALUES (15210, 'Equipment Set 10-Day Pack', '10-day limited period', 'Использовав данный предмет, Вы получите комплект (10 дн.), подходящий для Вашего класса. Использование возможно после 1-й смены профессии. Если не использовать в течение 10 дней, он исчезнет. Нельзя обменять/выбросить.', 'Using this item grants a set (10 days) suitable for your class. Usable after the 1st class transfer. Disappears if not used within 10 days. Cannot be traded or dropped.', 'etc_equip_item_box_i01', 1);
INSERT INTO `all_items` VALUES (15211, 'Equipment Set 30-Day Pack', '30-day limited period', 'Использовав данный предмет, Вы получите комплект (30 дн.), подходящий для Вашего класса. Использование возможно после 1-й смены профессии. Если не использовать в течение 10 дней, он исчезнет. Нельзя обменять/выбросить.', 'Using this item grants a set (30 days) suitable for your class. Usable after the 1st class transfer. Disappears if not used within 10 days. Cannot be traded or dropped.', 'etc_equip_item_box_i01', 1);
INSERT INTO `all_items` VALUES (15212, 'Friend Recommend Round 1 Reward Pack Exchange Coupon', 'Recommender', 'Если использовать этот талон, он превратиться в 1-ю награду за приглашение друзей в игру.', 'Using this ticket turns it into the 1st friend invitation reward.', 'etc_exchange_ticket_i01', 0);
INSERT INTO `all_items` VALUES (15213, 'Friend Recommend Round 1 Reward Pack', '30-day limited period', 'Упаковка с наградами, с помощью которой можно получить Браслет Дружбы, головной убор и купон на Питомца. Исчезнет, если не использовать в течение 30 дн. Нельзя обменять/выбросить.', 'Reward package containing a Friendship Bracelet, a hair accessory, and a pet coupon. Disappears if not used within 30 days. Cannot be traded or dropped.', 'etc_exchange_ticket_i01', 0);
INSERT INTO `all_items` VALUES (15214, 'Friend Recommend Round 2 Reward Pack Exchange Coupon', 'Recommender', 'Если использовать этот талон, он превратиться во 2-ю награду за приглашение друзей в игру.', 'Using this ticket turns it into the 2nd friend invitation reward.', 'etc_exchange_ticket_i02', 0);
INSERT INTO `all_items` VALUES (15215, 'Friend Recommend Round 2 Reward Pack', '30-day limited period', 'Упаковка с наградами, с помощью которой можно получить Браслет Дружбы, Браслет Печати Агатиона - Ккульккуль, купон на Особого Питомца и рекомендацию друга. Исчезнет, если не использовать в течение 30 дн. Нельзя обменять/выбросить.', 'Reward package containing a Friendship Bracelet, Agathion Seal Bracelet - Kkulkkul, a special pet coupon, and a friend recommendation. Disappears if not used within 30 days. Cannot be traded or dropped.', 'etc_exchange_ticket_i02', 0);
INSERT INTO `all_items` VALUES (15216, 'Friend Recommend Round 1 Reward Pack Exchange Coupon', 'New Dormancy', 'Если использовать этот талон, он превратиться в 1-ю награду за приглашение друзей в игру.', 'Using this ticket turns it into the 1st friend invitation reward.', 'etc_exchange_ticket_i01', 0);
