INSERT INTO `all_items` VALUES (15278, 'Dimensional Merchant\'s Gift', NULL, 'Особый подарок, полученный у Менеджера Витаминов. При использовании можно получить Парное Молоко, Благословенный Свиток Телепорта, Благословенный Свиток Воскрешения и Камень: Модифицировать Оружие.', 'A special gift obtained from the Vit Manager. Using it grants Mixed Milk, Blessed Scroll of Escape, Blessed Scroll of Resurrection, and Scroll: Enchant Weapon.', 'etc_treasure_box_i05', 0);
INSERT INTO `all_items` VALUES (15279, 'Friend Recommendation Proof', NULL, 'Если отнести этот документ Менеджеру Витаминов, можно получить особый подарок. Нельзя обменять/выбросить.', 'Taking this document to the Vit Manager grants a special gift. Cannot be traded or dropped.', 'etc_exchange_ticket_i03', 0);
