INSERT INTO `all_items` VALUES (15425, 'Hero\'s Treasure Box', 'Event', 'Упаковка: Комплект снаряжения - 30 дн. Внутри находятся предметы: Купон на Ожерелье Питомца и Точка Возвращения Героя. Нельзя обменять/выбросить/уничтожить.', 'Package: Equipment Set - 30 days. Contains items: Pet Necklace Coupon and Hero\'s Return Point. Cannot be traded, dropped, or destroyed.', 'event_hero_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (15426, 'Hero\'s Summon Point', 'Event', 'Дважды щелкнув по нему мышкой, вы получите 10 000 очков компьютерного клуба. Время перезарядки: 7 дн. Нельзя обменять/выбросить/уничтожить.', 'Double-click to receive 10,000 PC Cafe points. Reuse delay: 7 days. Cannot be traded, dropped, or destroyed.', 'etc_pccafe_point_i00', 0);
INSERT INTO `all_items` VALUES (15427, '6th Anniversary Party Cake', 'Event', 'При получении опыта в течение 1 часа восстанавливается энергия. Время перезарядки: 12 ч. Нельзя обменять/выбросить/уничтожить.', 'Restores energy while gaining EXP for 1 hour. Reuse delay: 12 hours. Cannot be traded, dropped, or destroyed.', 'event_six_party_cake_i00', 3);
INSERT INTO `all_items` VALUES (15428, '6th Anniversary Party Earring (Event)', '30-day limited period', 'Увеличивает MP на 31, сопротивление шоковым и ментальным атакам, вызывающим аномальные статусы, на 20%. Имеет эффект Ярости Вампира. Эффект не суммируется. Срок действия: 30 дн. Нельзя обменять/выбросить/уничтожить.', '3-Day Limited Period	3-day limited-time Item. increases MP by 31 and Resistance to Shock/Mind attacks by 2%. Increases Shock/Mental Atk. Rate by 2%. Has the Vampiric Rage effect. Only one effect is applied even when the two identical earrings are worn. Cannot be exchanged, dropped, or destroyed.', 'event_six_party_earing_i00', 0);
INSERT INTO `all_items` VALUES (15429, '6th Anniversary Party Belt (Event)', '7-day limited period', 'Поддерживает уровень энергии в течение 30 минут. Время перезарядки: 23 ч. Срок действия: 7 дн. Нельзя обменять/выбросить/уничтожить.', '7-Day Limited Period	7-Day Limited Period item. Vitality is maintained for 3 min. Cooldown is 23 hours. Cannot be exchanged, dropped, or destroyed. Vitality item with a limited number of use.', 'event_energy_belt_i00', 0);
INSERT INTO `all_items` VALUES (15430, 'Event - Halloween Candy', 'Event', 'Сладкая Конфета Хэллоуина. Можно обменять у Скульди на Коробку Игрушек Хэллоуина.', 'Sweet Halloween Candy. Can be exchanged for a Halloween Toy Box with Skuld.', 'ev_hallowinday_candy_i00', 0);
INSERT INTO `all_items` VALUES (15431, 'Event - Uldie Summon Scroll', NULL, 'С помощью данного свитка можно призвать Ульди и сыграть с ней в Игру Джека. Нельзя призвать Ульди, если у Вас призван питомец или нет маски Хэллоуина. Нельзя играть в Игру Джека в состоянии перевоплощения!', 'Using this scroll, you can summon Uldy and play Jack\'s Game with her. You cannot summon Uldy if you have a summoned pet or are not wearing a Halloween mask. You cannot play Jack\'s Game while transformed!', 'ev_scroll_of_wooldie_i00', 1);
INSERT INTO `all_items` VALUES (15432, 'Event - Belldandy Summon Scroll', NULL, 'С помощью данного свитка можно призвать Верданди и сыграть с ней в Игру Джека. Нельзя призвать Ульди, если у Вас призван питомец или нет маски Хэллоуина. Нельзя играть в Игру Джека в состоянии перевоплощения!', 'Using this scroll, you can summon Verthandi and play Jack\'s Game with her. You cannot summon Uldy if you have a summoned pet or are not wearing a Halloween mask. You cannot play Jack\'s Game while transformed!', 'ev_scroll_of_berdandi_i00', 1);
INSERT INTO `all_items` VALUES (15433, 'Event - Skooldie Summon Scroll', NULL, 'С помощью данного свитка можно призвать Скульди и потренироваться с ним в Игре Джека. Нельзя призвать Скульди, если у Вас призван питомец или нет маски Хэллоуина. Нельзя играть в Игру Джека в состоянии перевоплощения! Нельзя обменять/выбросить/уничтожить.', 'Using this scroll, you can summon Skuld and practice Jack\'s Game with her. You cannot summon Skuld if you have a summoned pet or are not wearing a Halloween mask. You cannot play Jack\'s Game while transformed! Cannot be traded, dropped, or destroyed.', 'ev_scroll_of_scooldie_i00', 1);
INSERT INTO `all_items` VALUES (15434, 'Halloween Toy Chest', NULL, 'С определенным шансом можно получить одну из Масок Хэллоуина. Нельзя обменять/выбросить/уничтожить.', 'Grants a certain chance to obtain one of the Halloween Masks. Cannot be traded, dropped, or destroyed.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (15435, 'Shiny Halloween Toy Chest', NULL, 'С определенным шансом можно получить одну из Блестящих Масок Хэллоуина. Нельзя обменять/выбросить/уничтожить.', 'Grants a certain chance to obtain one of the Shining Halloween Masks. Cannot be traded, dropped, or destroyed.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (15436, 'Halloween Transformation Stick', '7-day limited period', 'Можно перевоплотиться в Тыкву Хэллоуина. Аксессуар - 7 дн. Нельзя обменять/выбросить/уничтожить.', 'Allows you to transform into a Halloween Pumpkin. Accessory - 7 days. Cannot be traded, dropped, or destroyed.', 'weapon_pumpkin_stick_i00', 0);
INSERT INTO `all_items` VALUES (15437, 'Transformation Scroll Box', NULL, 'С определенным шансом можно получить один из свитков перевоплощения в Зверя Знамения, Роковое Видение или Апостола Грааля. Нельзя обменять/выбросить/уничтожить.', 'Grants a certain chance to obtain a transformation scroll into an Omen Beast, Doom Vision, or Grail Apostle. Cannot be traded, dropped, or destroyed.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (15438, 'Vitality Maintaining Potion (10 minutes)', NULL, 'В течение 10 минут поддерживается уровень энергии. Можно использовать раз в 30 минут. Нельзя обменять/выбросить/уничтожить.', 'Maintains energy level for 10 minutes. Can be used once every 30 minutes. Cannot be traded, dropped, or destroyed.', 'etc_lesser_potion_blue_i00', 3);
INSERT INTO `all_items` VALUES (15439, '10,000 SP scroll', NULL, '100 000 свитков восстановления SP.', '100,000 SP recovery scrolls.', 'etc_sp_scroll3_i00', 1);
INSERT INTO `all_items` VALUES (15440, 'Vitality Maintaining Potion (30 Minutes)', NULL, 'В течение 30 минут поддерживает уровень энергии. Можно использовать раз в 60 минут. Нельзя обменять/выбросить/уничтожить.', 'Maintains energy level for 30 minutes. Can be used once every 60 minutes. Cannot be traded, dropped, or destroyed.', 'etc_lesser_potion_scarlet_i00', 3);
INSERT INTO `all_items` VALUES (15441, 'Red Flare Valakas Hair Accessory', NULL, 'Шляпа Валакаса красного цвета. Нельзя обменять/выбросить.', 'Burning red Valakas Helm. Cannot be exchanged or dropped.', 'ev_valakas_the_flame_i00', 0);
INSERT INTO `all_items` VALUES (15442, 'Jack O\'Lantern Mask', NULL, 'Если надеть маску, можно использовать умение карты, необходимое во время Игры Джека. Нельзя обменять/выбросить/уничтожить.', 'You can use the card skill necessary for playing Jack\'s game when equipped. Cannot be exchanged, dropped, or destroyed.', 'ev_jack0_mask_i00', 0);
INSERT INTO `all_items` VALUES (15443, 'Super Strong Giant\'s Mask', NULL, 'Маска Гиганта. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Super Strong Giant\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'br_frankenstein_mask_i00', 0);
INSERT INTO `all_items` VALUES (15444, 'Silent Scream\'s Mask', NULL, 'Маска Беззвучного Крика. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Silent Scream\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_scream_mask_i00', 0);
INSERT INTO `all_items` VALUES (15445, 'Wrathful Spirit\'s Mask', NULL, 'Маска Разгневанного Духа. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Wrathful Spirit\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_doccabi_mask_i00', 0);
INSERT INTO `all_items` VALUES (15446, 'Unrotten Corpse\'s Mask', NULL, 'Маска Нетленного Трупа. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 2 ч. Нельзя обменять/выбросить/уничтожить.', 'Unrotten Corpse\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_mummy_mask_i00', 0);
INSERT INTO `all_items` VALUES (15447, 'Planet X235 Alien\'s Mask', NULL, 'Маска Инопланетянина X235. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Planet X235 Alien\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_alien_mask_i00', 0);
INSERT INTO `all_items` VALUES (15448, 'Golden Jack O\'Lantern Mask', 'Permanent Use', 'Маска Джека О\'Лантерна из золота. Ярко блестит. Нельзя обменять/выбросить/уничтожить.', 'Permanent Use	Jack O\'Lantern Mask made of gold. Shines brightly. Cannot be exchanged, dropped, or destroyed.', 'ev_golden_jack0_mask_i00', 0);
INSERT INTO `all_items` VALUES (15449, 'Shiny Planet X235 Alien\'s Mask', NULL, 'Блестящая Маска Инопланетянина X235. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Gloriously Shiny Planet X235 Alien\'s Mask You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_shiny_alien_mask_i00', 0);
INSERT INTO `all_items` VALUES (15450, 'Shiny Super Strong Giant\'s Mask', NULL, 'Блестящая Маска Гиганта. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Shining Giant Mask. When worn, allows you to use the card skill required during Jack\'s Game. Duration: 4 hours. Reuse delay: 1 hour. Cannot be traded, dropped, or destroyed.', 'ev_shiny_frankenstein_mask_i00', 0);
INSERT INTO `all_items` VALUES (15451, 'Shiny Silent Scream\'s Mask', NULL, 'Блестящая Маска Беззвучного Крика. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Gloriously Shiny Silent Scream\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_shiny_scream_mask_i00', 0);
INSERT INTO `all_items` VALUES (15452, 'Shiny Wrathful Spirit\'s Mask', NULL, 'Блестящая Маска Разгневанного Духа. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Gloriously Shiny Wrathful Spirit\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_shiny_doccabi_mask_i00', 0);
INSERT INTO `all_items` VALUES (15453, 'Shiny Unrotten Corpse\'s Mask', NULL, 'Блестящая Маска Нетленного Трупа. Если ее надеть, можно использовать умение карты, необходимое во время Игры Джека. Срок действия: 4 ч. Время перезарядки: 1 ч. Нельзя обменять/выбросить/уничтожить.', 'Gloriously Shiny Unrotten Corpse\'s Mask. You can use the card skill necessary for playing Jack\'s game when equipped. 4-hour limited-time Item. Cooldown 1 hour. Cannot be exchanged, dropped, or destroyed.', 'ev_shiny_mummy_mask_i00', 0);
INSERT INTO `all_items` VALUES (15454, 'Shiny Planet X235 Alien\'s Mask Pack', 'Event', 'Внутри находится Блестящая Маска Инопланетянина X235. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Shining Alien Mask X235. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15455, 'Shiny Super Strong Giant\'s Mask Pack', 'Event', 'Внутри находится Блестящая Маска Гиганта. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Shining Giant Mask. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15456, 'Shiny Silent Scream\'s Mask Pack', 'Event', 'Внутри находится Блестящая Маска Беззвучного Крика. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Shining Silent Scream Mask. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15457, 'Shiny Wrathful Spirit\'s Mask Pack', 'Event', 'Внутри находится Блестящая Маска Разгневанного Духа. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Shining Enraged Spirit Mask. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15458, 'Shiny Unrotten Corpse\'s Mask Pack', 'Event', 'Внутри находится Блестящая Маска Нетленного Трупа. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Shining Undead Corpse Mask. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15459, 'Halloween Nectar Pumpkin Pack', 'Event', 'В упаковке находится Медовая Тыква Хэллоуина. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Halloween Honey Pumpkin. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15460, 'Halloween King Pumpkin Pack', 'Event', 'В упаковке находится Большая Тыква Хэллоуина. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Halloween Large Pumpkin. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15461, 'Halloween Nectar Pumpkin', 'Event', 'Медовая Тыква Хэллоуина. С определенным шансом можно получить Зелье Всплеска Энергии, Благословенное Перо и Маленькую Тыкву Хэллоуина. Можно обменять, но нельзя выбросить и продать в личной торговой лавке.', 'Halloween Honey Pumpkin. Grants a certain chance to obtain an Energy Splash Potion, Blessed Feather, and Small Halloween Pumpkin. Tradable, but cannot be dropped or sold in a private store.', 'event_halloween_pumpkin_i00', 0);
INSERT INTO `all_items` VALUES (15462, 'Halloween King Pumpkin', 'Event', 'Большая Тыква Хэллоуина. Внутри находятся предметы: Медовая Тыква Хэллоуина - 6 шт. и Золотая Маска Джека О\'Лантерна (7 дн.). Можно обменять, но нельзя выбросить и продать в личной торговой лавке.', 'Halloween Large Pumpkin. Contains: Halloween Honey Pumpkin (6 pcs.) and Golden Jack O\'Lantern Mask (7 days). Tradable, but cannot be dropped or sold in a private store.', 'event_halloween_king_pumpkini00', 0);
INSERT INTO `all_items` VALUES (15463, 'Small Halloween Pumpkin', 'Event', 'Маленькая Тыква Хэллоуина. Щелкнув дважды по тыкве, можно получить с определенным шансом 1 бонусный предмет. Нельзя обменять/выбросить/продать в личной торговой лавке/уничтожить.', 'Small Halloween Pumpkin. Double-clicking the pumpkin grants a certain chance to obtain 1 bonus item. Cannot be traded, dropped, sold in a private store, or destroyed.', 'event_halloween_pumpkin_i00', 0);
INSERT INTO `all_items` VALUES (15464, 'Golden Jack O\'Lantern Mask', '7-day limited period', 'Маска Джека О\'Лантерна из золота. Ярко блестит. Время перезарядки: 23 ч. Нельзя обменять/выбросить/продать в личной торговой лавке/уничтожить.', '7-Day Limited Period	Golden Jack O\'Lantern Mask. Shines brightly. Cooldown is 23 hour. Cannot be exchanged, dropped, or put in private store. Can be destroyed.', 'ev_golden_jack0_mask_i00', 0);
INSERT INTO `all_items` VALUES (15465, 'Halloween Nectar Pumpkin Pack (Event)', 'Event', 'В упаковке находится Медовая Тыква Хэллоуина. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Halloween Honey Pumpkin. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15466, 'Halloween King Pumpkin Pack (Event)', 'Event', 'В упаковке находится Большая Тыква Хэллоуина. Нельзя обменять/выбросить/продать в личной торговой лавке.', 'Contains a Halloween Large Pumpkin. Cannot be traded, dropped, or sold in a private store.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (15467, 'Halloween Nectar Pumpkin (Event)', 'Event', 'Медовая Тыква Хэллоуина. С определенным шансом можно получить Зелье Всплеска Энергии, Благословенное Перо и Маленькую Тыкву Хэллоуина. Можно обменять, но нельзя выбросить и продать в личной торговой лавке.', 'Halloween Honey Pumpkin. Grants a certain chance to obtain an Energy Splash Potion, Blessed Feather, and Small Halloween Pumpkin. Tradable, but cannot be dropped or sold in a private store.', 'event_halloween_pumpkin_i00', 0);
INSERT INTO `all_items` VALUES (15468, 'Halloween King Pumpkin (Event)', 'Event', 'Большая Тыква Хэллоуина. Внутри находятся предметы: Медовая Тыква Хэллоуина - 6 шт. и Золотая Маска Джека О\'Лантерна (7 дн.). Можно обменять, но нельзя выбросить и продать в личной торговой лавке.', 'Halloween Large Pumpkin. Contains: Halloween Honey Pumpkin (6 pcs.) and Golden Jack O\'Lantern Mask (7 days). Tradable, but cannot be dropped or sold in a private store.', 'event_halloween_king_pumpkini00', 0);
INSERT INTO `all_items` VALUES (15469, 'Frozen Core', NULL, 'Магический камень, который может временно заблокировать сильную магию Фреи.', 'A magical stone that can temporarily block Freya\'s powerful magic.', 'etc_freezing_core_i00', 0);
INSERT INTO `all_items` VALUES (15470, 'Black Frozen Core', NULL, 'Магический камень, который может временно заблокировать сильную магию Фреи.', 'A magical stone that can temporarily block Freya\'s powerful magic.', 'etc_black_freezing_core_i00', 0);
INSERT INTO `all_items` VALUES (15471, 'Invisible Weapon for Freya', NULL, NULL, NULL, 'event_halloween_king_pumpkin_i03', 0);
INSERT INTO `all_items` VALUES (15472, 'Sealed Mystery Sword', NULL, 'Меч Богов, который может обессилить Фрею. Нельзя использовать из-за непонятной магической силы.', 'Sword of the Gods, which can weaken Freya. Cannot be used due to an incomprehensible magical force.', 'etc_sealed_mystery_sword_i00', 0);
INSERT INTO `all_items` VALUES (15473, 'Beast Handler\'s Whip', NULL, 'Кнут, предназначенный для дрессировки диких зверей.', 'A whip designed for training wild beasts.', 'etc_training_whip_i00', 0);
INSERT INTO `all_items` VALUES (15474, 'Golden Spice', NULL, 'Пища для созданий с Фермы Зверей. Когда монстры, способные развиваться, потребляют эту пищу, это дает различный эффект. Как только монстр достигает определенного уровня развития, он становится питомцем. Еще эта пища заставляет монстров оставлять после смерти только адены и предметы.', 'Food for creatures of the Beast Farm. When evolving monsters consume this food, it produces various effects. Once a monster reaches a certain stage of development, it becomes a pet. This food also causes monsters to drop only adena and items upon death.', 'etc_golden_spice_new_i00', 0);
INSERT INTO `all_items` VALUES (15475, 'Crystal Spice', NULL, 'Пища для созданий с Фермы Зверей. Когда монстры, способные развиваться, потребляют эту пищу, это дает различный эффект. Как только монстр достигает определенного уровня развития, он становится питомцем. Еще эта пища заставляет монстров оставлять после смерти только очки опыта.', 'Food for creatures of the Beast Farm. When evolving monsters consume this food, it produces various effects. Once a monster reaches a certain stage of development, it becomes a pet. This food also causes monsters to drop only EXP points upon death.', 'etc_crystal_spice_new_i00', 0);
INSERT INTO `all_items` VALUES (15476, 'Blessed Golden Spice', NULL, 'Хорошая пища для созданий с Фермы Зверей. Дает большой шанс превратить монстра в питомца.', 'Good food for creatures of the Beast Farm. Grants a high chance to turn a monster into a pet.', 'etc_golden_spice_blessed_i00', 0);
INSERT INTO `all_items` VALUES (15477, 'Blessed Crystal Spice', NULL, 'Хорошая пища для созданий с Фермы Зверей. Дает большой шанс превратить монстра в питомца.', 'Good food for creatures of the Beast Farm. Grants a high chance to turn a monster into a pet.', 'etc_crystal_spice_blessed_i00', 0);
INSERT INTO `all_items` VALUES (15478, 'Golden Spice (S-Grade)', NULL, 'Хорошая пища для созданий с Фермы Зверей. Дает большой шанс превратить монстра во взрослого монстра. Еще эта пища заставляет монстров оставлять после смерти только адены и предметы.', 'Good food for creatures of the Beast Farm. Grants a high chance to turn a monster into an adult monster. This food also causes monsters to drop only adena and items upon death.', 'etc_golden_spice_s_i00', 0);
INSERT INTO `all_items` VALUES (15479, 'Crystal Spice (S-Grade)', NULL, 'Хорошая пища для созданий с Фермы Зверей. Дает большой шанс превратить монстра во взрослого монстра. Еще эта пища заставляет монстров оставлять после смерти только очки опыта.', 'Good food for creatures of the Beast Farm. Grants a high chance to turn a monster into an adult monster. This food also causes monsters to drop only EXP points upon death.', 'etc_crystal_spice_s_i00', 0);
INSERT INTO `all_items` VALUES (15480, 'Old Golden Spice', NULL, 'Этой едой нельзя кормить зверей, потому что она очень старая.', 'This food cannot be fed to beasts because it is very old.', 'event_halloween_king_pumpkin_i12', 0);
INSERT INTO `all_items` VALUES (15481, 'Old Crystal Spice', NULL, 'Этой едой нельзя кормить зверей, потому что она очень старая.', 'This food cannot be fed to beasts because it is very old.', 'event_halloween_king_pumpkin_i13', 0);
INSERT INTO `all_items` VALUES (15482, 'Golden Spice Crate', NULL, 'Маленькая упаковка с Золотыми Специями. Внутри находится 50 Золотых Специй. Иногда можно получить хорошую специю.', 'Small package of Golden Spices. Contains 50 Golden Spices. Sometimes yields a better spice.', 'etc_golden_spice_comp_i00', 0);
INSERT INTO `all_items` VALUES (15483, 'Crystal Spice Compressed Pack', NULL, 'Маленькая упаковка с Кристальными Специями. Внутри находится 50 Кристальных Специй. Иногда можно получить хорошую специю.', 'Small package of Crystal Spices. Contains 50 Crystal Spices. Sometimes yields a better spice.', 'etc_crystal_spice_comp_i00', 0);
INSERT INTO `all_items` VALUES (15484, 'High-level Angel Circlet', NULL, 'Нимб Высшего Ангела. Требует две ячейки головных уборов. Можно использовать Благословенное Возвращение.', 'High-level Angel Circlet. Uses 2 hair accessory slots. Blessed Escape skill can be used.', 'accessory_highangel_circlet_i00', 0);
INSERT INTO `all_items` VALUES (15485, 'Torch', NULL, 'Можно поджечь костер. Нельзя обменять, выкинуть или продать в личном магазине.', 'Can be used to light a campfire. Cannot be traded, dropped, or sold in a personal store.', 'etc_torchlight_i00', 0);
INSERT INTO `all_items` VALUES (15486, 'Spirit Stone Fragment', NULL, 'Осколок камня, наполненный энергией жизни. Кажется, сейчас он не пригоден.', 'A stone shard filled with life energy. It seems unusable right now.', 'etc_a_broken_piece_of_soul_stone_i00', 0);
INSERT INTO `all_items` VALUES (15487, 'Maguen Plasma Collector', NULL, 'Механическое устройство, собирающее Плазму Магвена.', 'A mechanical device that collects Maguen Plasma.', 'etc_machine_for_marguene_i00', 0);
INSERT INTO `all_items` VALUES (15488, 'Maguen Pet Collar', NULL, 'С помощью этого Рога можно призвать питомца Магвена, который питается пищей для волков и забирает некое количество опыта у хозяина.', 'Using this horn, you can summon a Maguen pet that feeds on wolf food and takes a portion of its master\'s experience.', 'etc_marguene_pet_collar_i00', 7);
INSERT INTO `all_items` VALUES (15489, 'Elite Maguen Pet Collar', NULL, 'С помощью этого Рога можно призвать питомца Элитного Магвена, который питается пищей для волков и забирает некое количество опыта у хозяина.', 'Using this horn, you can summon an Elite Maguen pet that feeds on wolf food and takes a portion of its master\'s experience.', 'etc_elite_marguene_pet_collar_i00', 7);
INSERT INTO `all_items` VALUES (15490, 'Maguen Collection Box', NULL, 'Кажется, внутри что-то есть. Попробуйте открыть.', 'It seems there is something inside. Try opening it.', 'etc_marguene_collection_box_i00', 0);
INSERT INTO `all_items` VALUES (15491, 'Elite Maguen Collection Box', NULL, 'Кажется, внутри что-то есть. Попробуйте открыть.', 'It seems there is something inside. Try opening it.', 'etc_elite_marguene_collection_box_i00', 0);
INSERT INTO `all_items` VALUES (15492, 'Sel Mahum Salmon Porridge', NULL, 'Любимая Каша с Лососем Ксель-Махум. Выглядит аппетитно, а пахнет еще лучше.', 'Xel-Mahum\'s Favorite Salmon Porridge. Looks appetizing and smells even better.', 'etc_salmon_soup_i00', 0);
INSERT INTO `all_items` VALUES (15493, 'Fantasy Mushroom Pouch', NULL, 'Споры Ядовитого Гриба, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'Spores of a Poisonous Mushroom growing in the Lizardmen Valley. More detailed information can be obtained from Explorer Guild Member Harry in the Lizardmen Valley.', 'etc_pouch_yellow_i00', 0);
INSERT INTO `all_items` VALUES (15494, 'Sticky Mushroom Pouch', NULL, 'Споры Клейкого Гриба, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'Spores of a Sticky Mushroom growing in the Lizardmen Valley. More detailed information can be obtained from Explorer Guild Member Harry in the Lizardmen Valley.', 'etc_pouch_gray_i00', 0);
INSERT INTO `all_items` VALUES (15495, 'Vitality Plant Leaf', NULL, 'Лист целебного растения, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'A leaf of a medicinal plant growing in the Lizardmen Valley. More detailed information can be obtained from Explorer Guild Member Harry in the Lizardmen Valley.', 'etc_leaf_blue_i00', 0);
INSERT INTO `all_items` VALUES (15496, 'Seer Ugoros Pass', NULL, 'Аттестат Члена Гильдии Исследователей Джанни из Долины Ящеров свидетельствует о том, что Вы очень опытный воин. Теперь Вы можете отправиться к Провидцу Тантаар Югору. Нужно показать аттестат Привратнику Батракусу.', 'Explorer Guild Member Gianni\'s Certificate from the Lizardmen Valley proves that you are a very experienced warrior. Now you can go to Seer Tantaar Yugor. You need to show the certificate to Gatekeeper Batracos.', 'etc_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (15497, 'High-Grade Lizard Scale', NULL, 'Чешуя Ящера, найденная после уничтожения Провидца Тантаар Югора. Отнесите ее Торговцу Анкуми в Долину Ящеров.', 'Lizardman Scale found after defeating Seer Tantaar Yugor. Take it to Trader Ankumi in the Lizardmen Valley.', 'etc_godad_fish_scale_i00', 0);
INSERT INTO `all_items` VALUES (15498, 'Middle-Grade Lizard Scale', NULL, 'Чешуя Ящера, найденная после уничтожения Провидца Тантаар Югора. Отнесите ее Торговцу Анкуми в Долину Ящеров.', 'Lizardman Scale found after defeating Seer Tantaar Yugor. Take it to Trader Ankumi in the Lizardmen Valley.', 'etc_innadrile_fish_scale_i00', 0);
INSERT INTO `all_items` VALUES (15499, 'Vial of Tanta Blood', NULL, 'Бутыль с кровью Ящеров Тантаар, обитающих в Долине Ящеров. Отнесите ее Члену Гильдии Исследователей Лаки в Долину Ящеров.', 'A bottle of blood of Tantaar Lizardmen inhabiting the Lizardmen Valley. Take it to Explorer Guild Member Lucky in the Lizardmen Valley.', 'etc_dragons_blood_i04', 0);
INSERT INTO `all_items` VALUES (15500, 'Sel Mahum Diary', NULL, 'Дневник, в котором описаны повседневные дела Ксель-Махум. Отнесите его Стражу Стэну в Город Орен.', 'A diary describing the daily affairs of Xel-Mahums. Take it to Guard Stan in Oren Town.', 'etc_spell_books_white_i00', 0);
INSERT INTO `all_items` VALUES (15501, 'Sel Mahum Cookbook Page', NULL, 'Часть Кулинарной Книги, которую носят с собой повара Ксель-Махум. Отнесите ее Стражу Стэну в Город Орен.', 'Part of a Cookbook carried by Xel-Mahum chefs. Take it to Guard Stan in Oren Town.', 'etc_hidden_2nd_page_i00', 0);
INSERT INTO `all_items` VALUES (15502, 'Sel Mahum Cookbook', NULL, 'Кулинарная Книга, которую носят с собой повара Ксель-Махум. Отнесите ее Стражу Стэну в Город Орен.', 'Cookbook carried by Xel-Mahum chefs. Take it to Guard Stan in Oren Town.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (15503, 'Shiny Salmon', NULL, 'Очень аппетитный лосось с ярко блестящей чешуей. Отнесите его Стражу Стэну в Город Орен.', 'A very appetizing salmon with brightly shining scales. Take it to Guard Stan in Oren Town.', 'etc_tuna_i00', 0);
INSERT INTO `all_items` VALUES (15504, 'Gray Salmon', NULL, 'На вид вполне съедобный лосось. Отнесите его Стражу Стэну в Город Орен.', 'A reasonably edible-looking salmon. Take it to Guard Stan in Oren Town.', 'etc_tuna_i02', 0);
INSERT INTO `all_items` VALUES (15505, 'Sickly Salmon', NULL, 'Выглядит неаппетитно. Отнесите его Стражу Стэну в Город Орен.', 'Looks unappetizing. Take it to Guard Stan in Oren Town.', 'etc_tuna_i08', 0);
INSERT INTO `all_items` VALUES (15506, 'Salmon Lure', NULL, 'Наживка для лосося. Без нее поймать лосося невозможно.', 'Salmon bait. It is impossible to catch salmon without it.', 'etc_bait_i00', 0);
INSERT INTO `all_items` VALUES (15507, 'Foul Fruit', NULL, 'Неизвестный плод с отвратительным вкусом. Если добавить его в Кашу с Лососем, можно ее основательно испортить.', 'An unknown fruit with a repulsive taste. Adding it to Salmon Porridge will thoroughly ruin it.', 'etc_codran_i06', 0);
INSERT INTO `all_items` VALUES (15508, 'Sel Mahum Training Diary', NULL, 'Кропотливо заполненный Дневник Тренировок Ксель-Махум. Отнесите его Стражу Пинапсу в Город Орен.', 'Meticulously filled Xel-Mahum Training Diary. Take it to Guard Pinaps in Oren Town.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (15509, 'Sel Mahum Training Timetable', NULL, 'Лист с Расписанием Тренировок Ксель-Махум. Отнесите его Стражу Пинапсу в Город Орен.', 'Xel-Mahum Training Schedule Sheet. Take it to Guard Pinaps in Oren Town.', 'etc_plan_i00', 0);
INSERT INTO `all_items` VALUES (15510, 'Golem Corps Log', NULL, 'Лист бумаги с непонятными записями отряда големов. Нужно собрать все записи.', 'A sheet of paper with incomprehensible notes from the golem squad. You need to collect all the notes.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (15511, 'Golem Corps Collection', NULL, 'Сборник непонятных записей отряда големов. Отнесите его Коллекционеру Гутенхагену, находящемуся в Руинах Павла.', 'A collection of incomprehensible notes from the golem squad. Take it to Collector Gutenberg in Pavel Ruins.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (15512, 'Seed of Annihilation Orders', NULL, 'Приказ командира Базы Альянса Кецеруса Ковальдира. Отправляйтесь в Пристань Семени Уничтожения и передайте приказ Офицеру Клемису.', 'Order from Keucereus Alliance Base Commander Kovaldir. Head to the Seed of Destruction Wharf and deliver the order to Officer Klemis.', 'etc_letter_white_i00', 0);
INSERT INTO `all_items` VALUES (15513, 'Gracian Soldier Tag', NULL, 'Знак отличия, подобранный в Семени Уничтожения с тела Солдата Грации. Отнесите этот знак Офицеру Клемису. Найти его можно в Пристани Семени Уничтожения.', 'Insignia picked up from the body of a Gracia Soldier in the Seed of Destruction. Take this insignia to Officer Klemis. You can find him at the Seed of Destruction Wharf.', 'etc_ticket_blue_i00', 0);
INSERT INTO `all_items` VALUES (15514, 'Cold Resistance Potion', NULL, 'Особое зелье, созданное в Гильдии Зинии для защиты от проклятия Снежной Королевы. Необходимо для освобождения Крегора, подверженного опасности.', 'A special potion created in the Zinia Guild to protect against the Snow Queen\'s curse. Required to rescue Kregor, who is in danger.', 'etc_cp_potion_i00', 0);
INSERT INTO `all_items` VALUES (15515, 'Seal Breaker - 5th Floor', NULL, 'Камень Отмены Границы, необходимый для встречи с Принцем Демонов на 5 этаже Башни Вечности Стальной Цитадели. Разрушается после одного использования.', 'Boundary Removal Stone required to meet the Prince of Demons on the 5th floor of the Steel Citadel\'s Tower of Eternity. Destroyed after one use.', 'etc_crystal_cave_crystal_i0', 0);
INSERT INTO `all_items` VALUES (15516, 'Seal Breaker - 10th Floor', NULL, 'Камень Отмены Границы, необходимый для встречи с Ранку на 10 этаже Башни Вечности Стальной Цитадели. Разрушается после одного использования.', 'Boundary Removal Stone required to meet Ranku on the 10th floor of the Steel Citadel\'s Tower of Eternity. Destroyed after one use.', 'etc_crystal_cave_crystal_i00', 0);
INSERT INTO `all_items` VALUES (15517, 'Seal Components Part 1', NULL, 'Компонент Границы, полученный после уничтожения Космического Разведчика в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'Boundary Component obtained after defeating a Space Scout in the Tower of Eternity. Combining it with the other components allows you to create a Boundary Removal Stone.', 'etc_debris_i00', 0);
INSERT INTO `all_items` VALUES (15518, 'Seal Components Part 2', NULL, 'Компонент Границы, полученный после уничтожения Космического Наблюдателя в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'Boundary Component obtained after defeating a Space Watcher in the Tower of Eternity. Combining it with the other components allows you to create a Boundary Removal Stone.', 'etc_stone_black_i00', 0);
INSERT INTO `all_items` VALUES (15519, 'Seal Components Part 3', NULL, 'Компонент Границы, полученный после уничтожения Космического Жреца в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'Boundary Component obtained after defeating a Space Priest in the Tower of Eternity. Combining it with the other components allows you to create a Boundary Removal Stone.', 'etc_synthetic_cokes_i00', 0);
INSERT INTO `all_items` VALUES (15520, 'Seal Components Part 4', NULL, 'Компонент Границы, полученный после уничтожения Космического Повелителя в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'Boundary Component obtained after defeating a Space Overlord in the Tower of Eternity. Combining it with the other components allows you to create a Boundary Removal Stone.', 'event_cubic_i00', 0);
INSERT INTO `all_items` VALUES (15521, 'Broken Golem Shard', NULL, 'Осколок, полученный во время охоты на големов.', 'A shard obtained while hunting golems.', 'etc_plate_white_i00', 0);
INSERT INTO `all_items` VALUES (15522, 'Shabby Necklace', NULL, 'Блеклое Ожерелье, которое Страж Антараса Теодрик дает только тем, кто действительно сможет уничтожить Антараса. Говорят, если уничтожить Антараса, ожерелье изменится.', 'Faded Necklace given by Antaras Watcher Theodric only to those who can truly defeat Antaras. They say that if Antaras is defeated, the necklace will change.', 'armor_neck01', 0);
INSERT INTO `all_items` VALUES (15523, 'Miracle Necklace', NULL, 'Предмет, в который превратилось Блеклое Ожерелье после уничтожения Антараса. Отнесите его Стражу Антараса Теодрику.', 'The item into which the Faded Necklace turned after defeating Antaras. Take it to Antaras Watcher Theodric.', 'accessary_necklace_of_protection_i00', 0);
INSERT INTO `all_items` VALUES (15524, 'Poor Necklace', NULL, 'Дешевое Ожерелье, которое Страж Валакаса Клейн дает только тем, кто действительно сможет уничтожить Валакаса. Говорят, если уничтожить Валакаса, ожерелье изменится.', 'Cheap Necklace given by Valakas Watcher Klein only to those who can truly defeat Valakas. They say that if Valakas is defeated, the necklace will change.', 'armor_neck02', 0);
INSERT INTO `all_items` VALUES (15525, 'Valor Necklace', NULL, 'Предмет, в который превратилось Дешевое Ожерелье после уничтожения Валакаса. Отнесите его Стражу Валакаса Клейну.', 'The item into which the Cheap Necklace turned after defeating Valakas. Take it to Valakas Watcher Klein.', 'accessary_necklace_of_valor_i00', 0);
INSERT INTO `all_items` VALUES (15526, 'Tattered Monk Clothes', NULL, 'Лохмотья Монаха, полученные после уничтожения монахов в Монастыре Безмолвия. Отнесите их Гремори. Найти его можно в Монастыре Безмолвия.', 'Monk\'s Rags obtained after defeating monks in the Monastery of Silence. Take them to Greymore. You can find him in the Monastery of Silence.', 'etc_leather_gray_i00', 0);
INSERT INTO `all_items` VALUES (15527, 'Mark of Splendor', NULL, 'Доказательство уничтожения Главы Флиндов Анаиса по просьбе Жреца Гремори. Если отнести его Гремори, он даст хорошую награду.', 'Proof of defeating Flindo Chief Anays at the request of Priest Greymore. If you take it to Greymore, he will give a good reward.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (15528, 'Mark of Darkness', NULL, 'Доказательство уничтожения Главы Флиндов Анаиса по просьбе Жреца Гремори. Но вместо Знака Сияния Вам в руки попал Знак Тьмы. Если отнести его Гремори, он лишь посмеется.', 'Proof of defeating Flindo Chief Anays at the request of Priest Greymore. But instead of the Sign of Shining, you received the Sign of Darkness. If you take it to Greymore, he will only laugh.', 'etc_potion_yellow_i00', 0);
INSERT INTO `all_items` VALUES (15529, 'Priest Dominic\'s Letter', NULL, 'Секретное письмо, которое Жрец Доминик попросила передать Гремори. Войдите в Монастырь Безмолвия и отдайте его Жрецу Гремори.', 'A secret letter that Priest Dominic asked to be delivered to Greymore. Enter the Monastery of Silence and give it to Priest Greymore.', 'etc_piece_of_paper_gray_i00', 0);
INSERT INTO `all_items` VALUES (15530, 'Monk Scripture', NULL, 'Манускрипт, полученный после уничтожения монахов в Монастыре Безмолвия. Отнесите его Жрецу Гремори.', 'Manuscript obtained after defeating monks in the Monastery of Silence. Take it to Priest Greymore.', 'etc_magic_book_white_i00', 0);
INSERT INTO `all_items` VALUES (15531, 'Sel Mahum Mane', NULL, 'Шерсть, полученная во время уничтожения Махумов, атакующих Ферму Диких Зверей. Отправляйтесь на Ферму Диких Зверей и передайте шерсть Келае.', 'Wool obtained by defeating Mahums attacking the Beast Farm. Head to the Beast Farm and deliver the wool to Kela.', 'etc_mane_i00', 0);
INSERT INTO `all_items` VALUES (15532, 'Veal', NULL, 'Мясо, полученное после уничтожения очень молодого зверя. Пахнет аппетитно, но на вкус не очень. Отправляйтесь на Ферму Диких Зверей и отдайте его Пастуху Тунатуну.', 'Meat obtained after defeating a very young beast. Smells appetizing, but doesn\'t taste great. Head to the Beast Farm and give it to Shepherd Tunatun.', 'etc_meat_i00', 0);
INSERT INTO `all_items` VALUES (15533, 'Innocence Jewel', NULL, 'Белый самоцвет. Такие самоцветы выплевывают дикие звери, пока не вырастут. Если долго смотреть на него, вспоминаются давние времена.', 'White gemstone. Such gems are spit out by wild beasts until they grow up. Looking at it for a long time brings back memories of old times.', 'etc_crystal_ball_white_i00', 0);
INSERT INTO `all_items` VALUES (15534, 'Prime Meat', NULL, 'Хорошее мясо, полученное после уничтожения взрослого зверя. Говорят с одного зверя можно получить только один кусок мяса. Соберите мясо и отправляйтесь на Ферму Диких Зверей к Пастуху Тунатуну.', 'Good meat obtained after defeating an adult beast. They say only one piece of meat can be obtained from a single beast. Collect the meat and head to the Beast Farm to see Shepherd Tunatun.', 'etc_meat_of_monstereye_i00', 0);
INSERT INTO `all_items` VALUES (15535, 'Concentrated Spirit Energy', NULL, 'Концентрированная Энергия Жизни, полученная в Семени Уничтожения. Если отправиться на Базу Альянса Кецеруса к Контрабандисту Кокрану, он обменяет ее на что-нибудь ценное.', 'Concentrated Life Energy obtained in the Seed of Destruction. If you go to Smuggler Kokuran at the Keucereus Alliance Base, he will exchange it for something valuable.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (15536, 'Spirit Stone Dust', NULL, 'Порошок Осколка Камня Души, полученный в Семени Бессмертия. Если отправиться на Базу Альянса Кецеруса к Контрабандисту Кокрану, он обменяет его на Осколок Камня Души.', 'Soul Stone Shard Powder obtained in the Seed of Immortality. If you go to Smuggler Kokuran at the Keucereus Alliance Base, he will exchange it for a Soul Stone Shard.', 'etc_pouch_brown_i00', 0);
INSERT INTO `all_items` VALUES (15537, 'Strongbox of Promise', NULL, 'Маленький сейф, полученный во время уничтожения монахов в Монастыре Безмолвия. Щелкнув по сейфу дважды, можно посмотреть содержание квеста. Начальный квестовый предмет.', 'A small safe obtained while defeating monks in the Monastery of Silence. Double-clicking the safe allows you to view the quest contents. Initial quest item.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (15538, 'Book of Silence', NULL, 'Древнее Писание, которое находилось в Сейфе Клятвы. Чтобы вернуть эту книгу владельцу, сначала нужно узнать, кто он. Отправляйтесь в Замок Руна и попросите помощи у Управляющего Библиотекой Мудрецов Софии.', 'Ancient Scripture found inside the Oath Safe. To return this book to its owner, you must first find out who they are. Head to Rune Castle and ask Sage Library Manager Sophia for help.', 'high_kamael_skill_book_i00', 0);
INSERT INTO `all_items` VALUES (15539, 'Book of Silence', NULL, 'Управляющий Библиотекой Мудрецов София рассказала Вам о хозяине этой книги. Теперь нужно вернуть писание ему.', 'Sage Library Manager Sophia told you about the owner of this book. Now you need to return the scripture to him.', 'high_kamael_skill_book_i00', 0);
INSERT INTO `all_items` VALUES (15540, 'Unlit Torchlight', NULL, 'Предмет, необходимый для получения Сундука с Сокровищами в Потайной Комнате в Монастыре Безмолвия.', 'Item required to obtain a Treasure Chest in the Secret Room within the Monastery of Silence.', 'weapon_club_i00', 0);
INSERT INTO `all_items` VALUES (15541, 'Red Soul Crystal - Stage 17', NULL, 'Красный кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'Red crystal that absorbs souls. Level 17. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use. A crystal of this level can absorb souls independently.', 'etc_soul_stone_i00', 1);
INSERT INTO `all_items` VALUES (15542, 'Blue Soul Crystal - Stage 17', NULL, 'Синий кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'Blue crystal that absorbs souls. Level 17. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use. A crystal of this level can absorb souls independently.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (15543, 'Green Soul Crystal - Stage 17', NULL, 'Зеленый кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'Green crystal that absorbs souls. Level 17. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use. A crystal of this level can absorb souls independently.', 'etc_soul_stone_i02', 1);
INSERT INTO `all_items` VALUES (15544, 'Eternal Core Sword', NULL, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.', 'Bestows one of the following functions: Health, Focus, or Haste.', 'weapon_incessantcore_sword_i00', 7);
