INSERT INTO `all_items` VALUES (15711, 'War Veteran Voucher', NULL, 'Доказательство Подвигов на территории Семени Уничтожения. Если собрать достаточное количество доказательств и отнести Солдату Ильвенису в Пристань Семени Уничтожения, можно получить хорошую награду.', 'Proof of Feats in the Seed of Destruction. Collecting a sufficient amount of proof and taking it to Soldier Ilvenis at the Seed of Destruction Wharf grants a good reward.', 'etc_charm_of_courage_i00', 0);
INSERT INTO `all_items` VALUES (15712, 'Full Barrel of Soup', NULL, 'Бочонок каши, из которого едят Ксель-Махум. Наполнен кашей. Отправляйтесь в Город Орен и отдайте его Стражу Стэну.', 'A keg of porridge eaten by Xel-Mahums. Filled with porridge. Head to Oren Town and give it to Guard Stan.', 'etc_oil_pot_black_i00', 0);
INSERT INTO `all_items` VALUES (15713, 'Empty Soup Barrel', NULL, 'Бочонок каши, из которого едят Ксель-Махум. Пустой. Отправляйтесь в Город Орен и отдайте его Стражу Стэну.', 'A keg of porridge eaten by Xel-Mahums. Empty. Head to Oren Town and give it to Guard Stan.', 'etc_oil_pot_white_i00', 0);
INSERT INTO `all_items` VALUES (15714, 'Sel Mahum ID Tag', NULL, 'Знак Отличия Ксель-Махума, проходившего тренировку в Школе Полномочий. Отправляйтесь в Город Орен и отдайте его Стражу Пинапсу.', 'Xel-Mahum Insignia from training at the School of Authority. Head to Oren Town and give it to Guard Pinaps.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (15715, 'Damaged Book', NULL, 'Древний документ. Прочитать содержание невозможно из-за того, что он сильно поврежден. Если продать в лавку, можно получить хоть какие-то деньги.', 'Ancient document. Its contents cannot be read because it is badly damaged. Selling it to a shop yields at least some money.', 'etc_spellbook_gray_i00', 0);
INSERT INTO `all_items` VALUES (15716, 'Packaged Book', NULL, 'Предмет, полученный после спасения Искателя сокровищ. Хорошо упакован. Непонятно, что лежит внутри. Можно открыть, дважды щелкнув по предмету кнопкой мыши.', 'An item obtained after rescuing a Treasure Seeker. Well-packed. It is unclear what lies inside. Can be opened by double-clicking the item with the mouse button.', 'etc_memopad_i00', 0);
