INSERT INTO `all_items` VALUES (15826, 'Red Soul Crystal - Stage 18', NULL, 'Красный кристалл, поглощающий души. Уровень 18. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании.', 'Red crystal that absorbs souls. Level 18. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use.', 'etc_soul_stone_i00', 1);
INSERT INTO `all_items` VALUES (15827, 'Blue Soul Crystal - Stage 18', NULL, 'Синий кристалл, поглощающий души. Уровень 18. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании.', 'Blue crystal that absorbs souls. Level 18. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use.', 'etc_soul_stone_i01', 1);
INSERT INTO `all_items` VALUES (15828, 'Green Soul Crystal - Stage 18', NULL, 'Зеленый кристалл, поглощающий души. Уровень 18. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании.', 'Green crystal that absorbs souls. Level 18. When filled, grants special abilities to a weapon. Consumes 26 MP upon each use.', 'etc_soul_stone_i02', 1);
INSERT INTO `all_items` VALUES (15829, 'Periel Sword', 'Health', '<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP.', 'Health	a,<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15830, 'Periel Sword', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Critical Rate +134. Deals extra damage in PvP.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15831, 'Periel Sword', 'Haste', '<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15832, 'Skull Edge', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP.', 'HP Drain	a,<Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP.', 'weapon_skulledge_i01', 7);
INSERT INTO `all_items` VALUES (15833, 'Skull Edge', 'Haste', '<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP.', 'weapon_skulledge_i01', 7);
