INSERT INTO `all_items` VALUES (15900, 'Archangel Sword', 'Acumen', '<Свойство Кристалла Души>Скор. Маг. +15%. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Casting Spd. +15%. Deals extra damage in PvP.', 'weapon_archangel_sword_i001', 7);
INSERT INTO `all_items` VALUES (15901, 'Recurve Thorne Bow', 'Critical Slow', '<Свойство Кристалла Души>Существует 44% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Has a 44% probability to apply Slow on Critical Attacks. Deals extra damage in PvP.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (15902, 'Recurve Thorne Bow', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1.Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Grants an 8% chance on basic attacks to reduce MP consumption to 1. Deals extra damage in PvP.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (15903, 'Recurve Thorne Bow', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP.', '<Soul Crystal Effect> Critical Rate +139. Deals extra damage in PvP.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (15904, 'Heavenstare Rapier', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Critical Rate +139. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15905, 'Heavenstare Rapier', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Atk. Spd. +11%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15906, 'Heavenstare Rapier', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Max HP +25%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15907, 'Pyseal Blade', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Пылающей Пилы<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP.', 'Kamael Exclusive Weapon: Blazing Saw Conversion <Soul Crystal Effect> Critical Rate +134. Deals extra damage in PvP.', 'weapon_pyseal_blade_i01', 7);
