INSERT INTO `all_items` VALUES (15939, 'Finale Blade {PvP}', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Клинка ПераДает возможность получить одно из следующих особых свойств: Фокусировка, Ускорение, Здоровье. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Kamael-exclusive Weapon: Feather Eye Blade ConversionnBestows one of the following functions: Focus, Haste, or Health. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_findragon blade_i00', 7);
INSERT INTO `all_items` VALUES (15940, 'Dominion Crossbow {PvP}', NULL, 'Эксклюзивное оружие Камаэль: Конверсия КарниумаКрит. Дает возможность получить одно из следующих особых свойств: Замедление, Экономия, Фокусировка. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Kamael Exclusive Weapon: Carnium Conversion <Soul Crystal Effect> Grants one of the following special abilities: Slow, Cheap Shot, or Focus. Deals extra damage in PvP and grants a chance to restore CP when attacked.', 'weapon_rudecutter_crossbow_i00', 7);
INSERT INTO `all_items` VALUES (15941, 'Periel Sword {PvP}', 'Health', '<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Health	a,<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15942, 'Periel Sword {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Focus	a,<Soul Crystal Enhancement>nIncreases Critical by 134. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15943, 'Periel Sword {PvP}', 'Haste', '<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_periwing_sword_i01', 7);
INSERT INTO `all_items` VALUES (15944, 'Skull Edge {PvP}', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'HP Drain	a,<Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_skulledge_i01', 7);
INSERT INTO `all_items` VALUES (15945, 'Skull Edge {PvP}', 'Haste', '<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_skulledge_i01', 7);
INSERT INTO `all_items` VALUES (15946, 'Skull Edge {PvP}', 'Critical Damage', '<Свойство Кристалла Души>Физ. Атк. при Крит. ударе +1000. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Critical Damage	a,<Soul Crystal Enhancement>nIncreases P. Atk. by 1, during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_skulledge_i01', 7);
