INSERT INTO `all_items` VALUES (15962, 'Rising Star {PvP}', 'MP Regeneration', '<Свойство Кристалла Души>Скорость регенерации МР 2. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'MP Regeneration	a,<Soul Crystal Enhancement>nIncreases MP Recovery Rate. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_cuticle_i01', 7);
