INSERT INTO `all_items` VALUES (15971, 'Skull Carnium Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Focus	a,<Soul Crystal Enhancement>nIncreases Critical by 139. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_skullgrove_bow_i01', 7);
INSERT INTO `all_items` VALUES (15972, 'Skull Carnium Bow {PvP}', 'Critical Slow', '<Свойство Кристалла Души>Существует 33% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Critical Slow	a,<Soul Crystal Enhancement>nHas a 33% chance of casting Slow on the target during a Critical Attack. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_skullgrove_bow_i01', 7);
INSERT INTO `all_items` VALUES (15973, 'Skull Carnium Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Cheap Shot	a,<Soul Crystal Enhancement>nHas an 8% chance of decreasing MP consumption to 1 during a standard attack. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_skullgrove_bow_i01', 7);
INSERT INTO `all_items` VALUES (15974, 'Gemtail Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Очарования<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Health	Kamael-exclusive weapon Peri El Sword Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, party members including yourself will get increased P. Atk., M. Atk., and healing capacity by a fixed rate, and MP consumption during skill use is decreased.', 'weapon_gemtail_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15975, 'Gemtail Rapier {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Очарования<Свойство Кристалла Души> Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Focus	Kamael-exclusive weapon Peri El Sword Conversionn<Soul Crystal Enhancement>nIncreases Critical by 134. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, party members including yourself will get increased P. Atk., M. Atk., and healing capacity by a fixed rate, and MP consumption during skill use is decreased.', 'weapon_gemtail_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15976, 'Gemtail Rapier {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Меча Очарования<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Haste	Kamael-exclusive weapon Peri El Sword Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, party members including yourself will get increased P. Atk., M. Atk., and healing capacity by a fixed rate, and MP consumption during skill use is decreased.', 'weapon_gemtail_rapier_i01', 7);
INSERT INTO `all_items` VALUES (15977, 'Finale Blade {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Пера<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Health	Kamael-exclusive weapon Feather Eye Blade Conversionn<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Inflicts additional damage with a fixed rate during an attack.', 'weapon_findragon blade_i01', 7);
