INSERT INTO `all_items` VALUES (15979, 'Finale Blade {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Пера<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Haste	Kamael-exclusive weapon Feather Eye Blade Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Inflicts additional damage with a fixed rate during an attack.', 'weapon_findragon blade_i01', 7);
INSERT INTO `all_items` VALUES (15980, 'Dominion Crossbow {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Карниума<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'Kamael Exclusive Weapon: Carnium Conversion <Soul Crystal Effect> Critical Rate +134. Deals extra damage in PvP. Grants a chance to restore CP on attack and a chance to increase bow/crossbow Atk. Spd. on attack.', 'weapon_rudecutter_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (15981, 'Dominion Crossbow {PvP}', 'Critical Slow', 'Эксклюзивное оружие Камаэль: Конверсия Карниума<Свойство Кристалла Души>Существует 24% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Critical Slow	Kamael-exclusive weapon Skull Carnium Bow Conversionn<Soul Crystal Enhancement>nInflicts Slow at a 24% rate during a Critical Attack. Increases damage inflicted during PvP. Increases Atk. Spd. of bows/crossbows with a fixed rate during an attack.', 'weapon_rudecutter_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (15982, 'Dominion Crossbow {PvP}', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Карниума<Свойство Кристалла Души>При обычной атаке дает 12% шанс уменьшить расход MP до 1. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Cheap Shot	Kamael-exclusive weapon Skull Carnium Bow Conversionn<Soul Crystal Enhancement>nHas a 12% chance of decreasing MP consumption to 1 during a standard attack. Increases damage inflicted during PvP. Increases Atk. Spd. of bows/crossbows with a fixed rate during an attack.', 'weapon_rudecutter_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (15983, 'Eternal Core Sword {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Focus	a,<Soul Crystal Enhancement>nIncreases Critical by 134. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_incessantcore_sword_i01', 7);
INSERT INTO `all_items` VALUES (15984, 'Eternal Core Sword {PvP}', 'Haste', '<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_incessantcore_sword_i01', 7);
INSERT INTO `all_items` VALUES (15985, 'Eternal Core Sword {PvP}', 'Health', '<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Health	a,<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_incessantcore_sword_i01', 7);
INSERT INTO `all_items` VALUES (15986, 'Mamba Edge {PvP}', 'Haste', '<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Haste	a,<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_mambaedge_i01', 7);
INSERT INTO `all_items` VALUES (15987, 'Mamba Edge {PvP}', 'Critical Damage', '<Свойство Кристалла Души>Физ. Атк. при Крит. ударе +1060. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Critical Damage	a,<Soul Crystal Enhancement>nIncreases P. Atk. by 16 during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_mambaedge_i01', 7);
INSERT INTO `all_items` VALUES (15988, 'Mamba Edge {PvP}', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'HP Drain	a,<Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_mambaedge_i01', 7);
INSERT INTO `all_items` VALUES (15989, 'Eversor Mace {PvP}', 'HP Regeneration', '<Свойство Кристалла Души>Ускоряет восстановление HP на 5. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'HP Regeneration	a,<Soul Crystal Enhancement>nIncreases HP Recovery Rate. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_expowder_mace_i01', 7);
INSERT INTO `all_items` VALUES (15990, 'Eversor Mace {PvP}', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', '<Soul Crystal Effect> 4% of the damage dealt is added to your HP. Deals extra damage in PvP and grants a chance to restore CP when attacked.', 'weapon_expowder_mace_i01', 7);
