INSERT INTO `all_items` VALUES (16004, 'Sacredium {PvP}', 'Mana Up', '<Свойство Кристалла Души>Макс. МР увеличивается на 30%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> Max MP increases by 30%. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_sacredumors_i01', 7);
INSERT INTO `all_items` VALUES (16005, 'Sacredium {PvP}', 'Acumen', '<Свойство Кристалла Души>Увеличение Скор. Магии на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> Casting Spd. increases by 15%. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_sacredumors_i01', 7);
INSERT INTO `all_items` VALUES (16006, 'Sacredium {PvP}', 'MP Regeneration', '<Свойство Кристалла Души>Скорость регенерации МР 2. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> MP recovery rate 2. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_sacredumors_i01', 7);
INSERT INTO `all_items` VALUES (16007, 'Cyclic Cane {PvP}', 'Magic Hold', '<Свойство Кристалла Души>Дает шанс 20% колдовства Корня Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> Has a 20% chance to cast Dryad Root when using a harmful skill on a target. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_psyskilt_cane_i01', 7);
INSERT INTO `all_items` VALUES (16008, 'Cyclic Cane {PvP}', 'Empower', '<Свойство Кристалла Души>Увеличивает Маг. Атк. на 177. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> M. Atk. increases by 177. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_psyskilt_cane_i01', 7);
