INSERT INTO `all_items` VALUES (16012, 'Archangel Sword {PvP}', 'Acumen', '<Свойство Кристалла Души>Увеличение Скор. Магии на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении урона.', '<Soul Crystal Effect> Casting Spd. increases by 15%. Deals extra damage in PvP. Grants a chance to increase Casting Spd. when taking damage.', 'weapon_archangel_sword_i001', 7);
INSERT INTO `all_items` VALUES (16013, 'Recurve Thorne Bow {PvP}', 'Critical Slow', '<Свойство Кристалла Души>Существует 44% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> Has a 44% probability to apply Slow on Critical Attacks. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (16014, 'Recurve Thorne Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1.', '<Soul Crystal Effect> Grants an 8% chance on basic attacks to reduce MP consumption to 1.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (16015, 'Recurve Thorne Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Effect> Critical Rate +139. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_recurvethorne_bow_i01', 7);
INSERT INTO `all_items` VALUES (16016, 'Heavenstare Rapier {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Critical Rate +139. Deals extra damage in PvP and grants a chance to restore CP when attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (16017, 'Heavenstare Rapier {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Atk. Spd. +11%. Deals extra damage in PvP. Grants a chance to restore CP upon attack. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (16018, 'Heavenstare Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Kamael Exclusive Weapon: Undying Essence Sword Conversion <Soul Crystal Effect> Max HP +25%. Deals extra damage in PvP and grants a chance to restore CP when attacked. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_heavenstair_rapier_i01', 7);
INSERT INTO `all_items` VALUES (16019, 'Pyseal Blade {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Пылающей Пилы<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Kamael Exclusive Weapon: Blazing Saw Conversion <Soul Crystal Effect> Critical Rate +134. Deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_pyseal_blade_i01', 7);
INSERT INTO `all_items` VALUES (16020, 'Pyseal Blade {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Пылающей Пилы<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Kamael Exclusive Weapon: Blazing Saw Conversion <Soul Crystal Effect> Atk. Spd. +11%. Deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_pyseal_blade_i01', 7);
INSERT INTO `all_items` VALUES (16021, 'Pyseal Blade {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Пылающей Пилы<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Kamael Exclusive Weapon: Blazing Saw Conversion <Soul Crystal Effect> Max HP +25%. Deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_pyseal_blade_i01', 7);
INSERT INTO `all_items` VALUES (16022, 'Thorne Crossbow {PvP}', 'Critical Slow', 'Эксклюзивное оружие Камаэль: Конверсия Лука Изогнутых Шипов<Свойство Кристалла Души>Существует 24% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Kamael Exclusive Weapon: Curved Thorn Bow Conversion <Soul Crystal Effect> Has a 24% probability to apply Slow on Critical Attacks. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_thorne_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (16023, 'Thorne Crossbow {PvP}', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Изогнутых Шипов<Свойство Кристалла Души>При обычной атаке дает 12% шанс уменьшить расход MP до 1.', 'Kamael Exclusive Weapon: Curved Thorn Bow Conversion <Soul Crystal Effect> Grants a 12% chance on basic attacks to reduce MP consumption to 1.', 'weapon_thorne_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (16024, 'Thorne Crossbow {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Лука Изогнутых Шипов<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Kamael Exclusive Weapon: Curved Thorn Bow Conversion <Soul Crystal Effect> Critical Rate +139. Deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_thorne_crossbow_i01', 7);
INSERT INTO `all_items` VALUES (16025, 'Necklace of Freya', NULL, 'Увеличивает сопротивление воде на 10, кровотечению на 20%, параличу на 15%, шокирующим эффектам на 15%, усыплению на 15%, сокращает время перезарядки магических умений на 5%. Отражает 4% урона в ближнем бою, увеличивает макс. MP на 50, восстановление MP на 0.23, сопротивление ментальным атакам на 10%.', 'Water resistance +10, Bleed resistance +20%, Paralysis resistance +15%, Stun resistance +15%, Sleep resistance +15%, magic skill reuse delay reduced by 5%. Reflects 4% of melee damage, Max MP +50, MP recovery +0.23, mental attack resistance +10%.', 'accessary_queen_of_ice_necklace_i00', 0);
INSERT INTO `all_items` VALUES (16026, 'Blessed Necklace of Freya', NULL, 'Увеличивает сопротивление воде на 15, кровотечению на 25%, параличу 20%, шокирующим эффектам на 20%, усыплению 20%, сокращает время перезарядки магических умений на 5%. Отражает 4% урона в ближнем бою, увеличивает макс. MP на 50, восстановление MP на 0.46, сопротивление ментальным атакам на 10%, силу исцеляющей магии на 15.6, ДУХ  +2, ВЫН +1, СИЛ -1, уменьшает расход MP магических умений на 5%.', 'Water resistance +15, Bleed resistance +25%, Paralysis resistance +20%, Stun resistance +20%, Sleep resistance +20%, magic skill reuse delay reduced by 5%. Reflects 4% of melee damage, Max MP +50, MP recovery +0.46, mental attack resistance +10%, healing magic power +15.6, MEN +2, CON +1, STR -1, magic skill MP consumption reduced by 5%.', 'accessary_queen_of_ice_necklace_i00', 0);
INSERT INTO `all_items` VALUES (16027, 'Bottle of Freya\'s Soul', NULL, 'Бутыль, содержащая Душу Фреи, которую можно вдохнуть в ожерелье Фреи.', 'A vial containing Freya\'s Soul, which can be infused into Freya\'s Necklace.', 'etc_recovery_set_i00', 6);
