INSERT INTO `all_items` VALUES (16056, 'Vesper Cutter - Thunder', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк., <Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Atk. Spd. increases by approximately 11%. Deals extra damage in PvP.', 'weapon_vesper_cutter_i01', 7);
INSERT INTO `all_items` VALUES (16057, 'Vesper Cutter - Thunder', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк., <Свойство Кристалла Души>Макс. HP увеличивается на 25%. Наносит дополнительный урон в PvP.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Max HP increases by 25%. Deals extra damage in PvP.', 'weapon_vesper_cutter_i01', 7);
