INSERT INTO `all_items` VALUES (16062, 'Vesper Buster - Cleverness', 'Mana Up', 'Редкий предмет, повышает способность восстановления MP, <Свойство Кристалла Души>Макс. MP увеличивается на 30%. Наносит дополнительный урон в PvP.', 'Rare item, enhances MP recovery ability. <Soul Crystal Effect> Max MP increases by 30%. Deals extra damage in PvP.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16063, 'Vesper Buster - Cleverness', 'Acumen', 'Редкий предмет, повышает способность восстановления MP, <Свойство Кристалла Души>Скор. Маг. увеличивается на 15%. Наносит дополнительный урон в PvP.', 'Rare item, enhances MP recovery ability. <Soul Crystal Effect> Casting Spd. increases by 15%. Deals extra damage in PvP.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16064, 'Vesper Buster - Cleverness', 'Magic Hold', 'Редкий предмет, повышает способность восстановления MP, <Свойство Кристалла Души>Дает шанс 20% магии Корней Дриад при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Rare item, enhances MP recovery ability. <Soul Crystal Effect> Has a 20% chance to cast Dryad Root when using a harmful skill on a target. Deals extra damage in PvP.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16065, 'Vesper Shaper - Gale', 'Critical Damage', 'Редкий предмет, увеличивающий Скор. Атк., <Свойство Кристалла Души>Дает шанс увеличить Физ. Атк. на 906 при Крит. Атк. Наносит дополнительный урон в PvP.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants a chance to increase P. Atk. by 906 upon Critical Attacks. Deals extra damage in PvP.', 'weapon_vesper_shaper_i01', 7);
