INSERT INTO `all_items` VALUES (16085, 'Vesper Singer - Hail', 'Magic Hold', 'Редкий предмет, увеличивающий Маг. Атк., <Свойство Кристалла Души>Дает шанс 20% магии Корней Дриад при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Has a 20% chance to cast Dryad Root when using a harmful skill on a target. Deals extra damage in PvP.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (16086, 'Vesper Thrower - Clairvoyance', 'Cheap Shot', 'Редкий предмет, увеличивающий дальность атаки, <Свойство Кристалла Души>Снижает расход MP на 8% при обычной атаке. Наносит дополнительный урон в PvP.', 'Rare item, increases attack range. <Soul Crystal Effect> Decreases MP consumption by 8% on basic attacks. Deals extra damage in PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16087, 'Vesper Thrower - Clairvoyance', 'Focus', 'Редкий предмет, увеличивающий дальность атаки, <Свойство Кристалла Души>Шанс Крит. Атк. +133. Наносит дополнительный урон в PvP.', 'Rare item, increases attack range. <Soul Crystal Effect> Critical Rate +133. Deals extra damage in PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16088, 'Vesper Thrower - Clairvoyance', 'Critical Slow', 'Редкий предмет, увеличивающий дальность атаки, <Свойство Кристалла Души>Дает 33% вероятности наложения эффекта Замедления на цель при Крит. Атк. Наносит дополнительный урон в PvP.', 'Rare item, increases attack range. <Soul Crystal Effect> Has a 33% probability to apply Slow on the target upon Critical Attacks. Deals extra damage in PvP.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16089, 'Vesper Pincer - Thunder', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Vesper Cutter Conversion <Soul Crystal Effect> Atk. Spd. increases by approximately 11%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16090, 'Vesper Pincer - Thunder', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Макс. HP увеличивается на 25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Vesper Cutter Conversion <Soul Crystal Effect> Max HP increases by 25%. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16091, 'Vesper Pincer - Thunder', 'Focus', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры.<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 131. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item, increases Critical Rate. Kamael Exclusive Weapon: Vesper Cutter Conversion <Soul Crystal Effect> Critical Rate increases by 131. Deals extra damage in PvP. When enchanted to +4 or higher, critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16092, 'Vesper Shooter - Clairvoyance', 'Cheap Shot', 'Редкий предмет, увеличивающий дальность атаки, Эксклюзивное оружие Камаэль: Конверсия Броска Венеры.<Свойство Кристалла Души>Расход МР на умения сокращается на 12%. Наносит дополнительный урон в PvP.', 'Rare item, increases attack range. Kamael Exclusive Weapon: Vesper Caster Conversion <Soul Crystal Effect> MP consumption for skills is reduced by 12%. Deals extra damage in PvP.', 'weapon_vesper_schutze_i01', 7);
