INSERT INTO `all_items` VALUES (16177, 'Accessory Type Life Stone -  Level 85', NULL, 'Минерал, появившийся в результате воздействия какого-то существа. Используется для зачарования предметов персонажами уровня 85 и выше.', 'A mineral created as a result of a creature\'s influence. Used for augmenting items by characters level 85 and above.', 'etc_mineral_general_i03', 0);
