INSERT INTO `all_items` VALUES (16179, 'Vesper Cutter- Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души> Дает возможность увеличить Скор. Атк. на 11%, наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Haste	Masterwork Item that increases P. Critical Rate. <Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_vesper_cutter_i01', 7);
INSERT INTO `all_items` VALUES (16180, 'Vesper Cutter- Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души> Дает возможность увеличить макс. HP на 25%, наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item, increases Critical Rate. <Soul Crystal Effect> Grants a chance to increase Max HP by 25%, deals extra damage in PvP. Grants a chance to restore CP upon attack.', 'weapon_vesper_cutter_i01', 7);
INSERT INTO `all_items` VALUES (16181, 'Vesper Cutter- Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души> Дает возможность увеличить шанс Крит. Атк. на 131, наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Focus	Masterwork Item that increases P. Critical Rate. <Soul Crystal Enhancement>nIncreases Critical by 131. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_vesper_cutter_i01', 7);
INSERT INTO `all_items` VALUES (16182, 'Vesper Slasher- Gale {PvP}', 'Haste', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить скор. Атк. на 11%, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Haste	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_slasher_i01', 7);
INSERT INTO `all_items` VALUES (16183, 'Vesper Slasher- Gale {PvP}', 'Health', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить макс. HP на 25%, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Health	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_slasher_i01', 7);
INSERT INTO `all_items` VALUES (16184, 'Vesper Slasher- Gale {PvP}', 'Focus', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить шанс Крит. Атк. на 131, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Focus	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases Critical by 131. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_slasher_i01', 7);
INSERT INTO `all_items` VALUES (16185, 'Vesper Buster - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает возможность увеличить макс. MP на 30%, наносит дополнительный урон в PvP. С определенной вероятностью увеличивается Скор. Маг. при получении урона.', 'Mana Up	Masterwork Item that increases MP Recovery. <Soul Crystal Enhancement>nIncreases Max MP by 3%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16186, 'Vesper Buster - Cleverness {PvP}', 'Acumen', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает возможность увеличить макс. MP на 15%, наносит дополнительный урон в PvP. С определенной вероятностью увеличивается Скор. Маг. при получении урона.', 'Acumen	Masterwork Item that increases MP Recovery. <Soul Crystal Enhancement>nIncreases Casting Spd. by 15%. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16187, 'Vesper Buster - Cleverness {PvP}', 'Magic Hold', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает шанс 20% колдовства Корня Дриады, наносит дополнительный урон в PvP. С определенной вероятностью увеличивается Скор. Маг. при получении урона.', 'Magic Hold	Masterwork Item that increases MP Recovery. <Soul Crystal Enhancement>nHas a 2% chance of casting Dryad Root on the target during magic use. Increases damage inflicted during PvP. Has a chance of increasing Casting Spd. when attacked.', 'weapon_vesper_burster_i01', 7);
INSERT INTO `all_items` VALUES (16188, 'Vesper Shaper - Gale {PvP}', 'Critical Damage', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает шанс увеличить Физ. Атк. на 906 при Крит. Атк., наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'Critical Damage	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases P. Atk. by 96 during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_vesper_shaper_i01', 7);
INSERT INTO `all_items` VALUES (16189, 'Vesper Shaper - Gale {PvP}', 'HP Drain', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность восстановить 4% нанесенного врагу урона в HP, наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'HP Drain	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_vesper_shaper_i01', 7);
INSERT INTO `all_items` VALUES (16190, 'Vesper Shaper - Gale {PvP}', 'Haste', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить Скор. Атк. примерно на 11%, наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants a chance to increase Atk. Spd. by approximately 11%, deals extra damage in PvP. Grants a certain probability to remove one or more positive effects from the enemy on attack or decrease their Shield Defense.', 'weapon_vesper_shaper_i01', 7);
INSERT INTO `all_items` VALUES (16191, 'Vesper Fighter - Gale {PvP}', 'Focus', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить шанс Крит. Атк. на 123, наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'Focus	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases Critical by 123. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_vesper_fighter_i01', 7);
INSERT INTO `all_items` VALUES (16192, 'Vesper Fighter - Gale {PvP}', 'Health', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить макс. HP нa 25%, наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'Health	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_vesper_fighter_i01', 7);
INSERT INTO `all_items` VALUES (16193, 'Vesper Fighter - Gale {PvP}', 'Critical Stun', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность с вероятностью в 43% оглушить врага при критическом ударе, наносит дополнительный урон в PvP. С определенной вероятностью отменяет один или больше положительных эффектов врага при атаке или уменьшает его Защиту Щитом.', 'Critical Stun	Masterwork Item that increases Atk. Spd. <Soul Crystal Enhancement>nInflicts Stun with about a 43% chance during a Critical Attack. Increases damage inflicted during PvP. Has a chance of canceling 1 or more of the target\'s enhanced status, or of decreasing the target\'s Shield Defense during an attack.', 'weapon_vesper_fighter_i01', 7);
INSERT INTO `all_items` VALUES (16194, 'Vesper Stormer - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души>Дает возможность увеличить макс. HP нa 25%, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Health	Masterwork Item that increases P. Critical Rate. <Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_stormer_i01', 7);
INSERT INTO `all_items` VALUES (16195, 'Vesper Stormer - Thunder {PvP}', 'Guidance', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души>Дает возможность увеличить Точность нa 7.5, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Guidance	Masterwork Item that increases P. Critical Rate. <Soul Crystal Enhancement>nIncreases Accuracy by 7.5. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_stormer_i01', 7);
INSERT INTO `all_items` VALUES (16196, 'Vesper Stormer - Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души>Дает возможность увеличить Скор. Атк. примерно нa 11%, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Haste	Masterwork Item that increases P. Critical Rate. <Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_stormer_i01', 7);
INSERT INTO `all_items` VALUES (16197, 'Vesper Avenger - Landslide {PvP}', 'HP Drain', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Дает возможность восстановить 4% нанесенного в ближнем бою врагу урона в HP. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'HP Drain	Masterwork Item that has a chance of casting Stun on the target during an attack.n<Soul Crystal Enhancement>nAbsorbs 4% of standard melee damage inflicted upon the enemy as HP. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_vesper_avenger_i01', 7);
INSERT INTO `all_items` VALUES (16198, 'Vesper Avenger - Landslide {PvP}', 'Health', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Дает возможность увеличить макс. HP нa 25%, наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Health	Masterwork Item that has a chance of casting Stun on the target during an attack.n<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_vesper_avenger_i01', 7);
INSERT INTO `all_items` VALUES (16199, 'Vesper Avenger - Landslide {PvP}', 'HP Regeneration', 'Редкий предмет, дает шанс оглушить при атаке.<Свойство Кристалла Души>Дает возможность увеличить скорость восстановления HP. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'HP Regeneration	Masterwork Item that has a chance of casting Stun on the target during an attack.n<Soul Crystal Enhancement>nIncreases HP Recovery Rate. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.', 'weapon_vesper_avenger_i01', 7);
INSERT INTO `all_items` VALUES (16200, 'Vesper Retributer - Gale {PvP}', 'HP Regeneration', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить скорость восстановления HP, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants a chance to increase HP recovery rate, deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_vesper_retributer_i01', 7);
INSERT INTO `all_items` VALUES (16201, 'Vesper Retributer - Gale {PvP}', 'Health', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить макс. HP на 25%, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants a chance to increase Max HP by 25%, deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_vesper_retributer_i01', 7);
INSERT INTO `all_items` VALUES (16202, 'Vesper Retributer - Gale {PvP}', 'HP Drain', 'Редкий предмет, увеличивает Скор. Атк., <Свойство Кристалла Души>Дает возможность увеличить восстановить 4% нанесенного в ближнем бою врагу урона в HP, наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item, increases Atk. Spd. <Soul Crystal Effect> Grants a chance to restore 4% of damage dealt in melee combat as HP, deals extra damage in PvP. Grants a chance to deal extra damage on attack.', 'weapon_vesper_retributer_i01', 7);
INSERT INTO `all_items` VALUES (16203, 'Vesper Caster - Cleverness {PvP}', 'Acumen', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает возможность увеличить Скор. Маг. на 15%, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases MP recovery rate. <Soul Crystal Effect> Grants a chance to increase Casting Spd. by 15%, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (16204, 'Vesper Caster - Cleverness {PvP}', 'MP Regeneration', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает возможность увеличить скорость восстановления MP, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases MP recovery rate. <Soul Crystal Effect> Grants a chance to increase MP recovery rate, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (16205, 'Vesper Caster - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает макс. MP на 30%, <Свойство Кристалла Души>Дает возможность увеличить скорость восстановления MP, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases Max MP by 30%. <Soul Crystal Effect> Grants a chance to increase MP recovery rate, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_caster_i01', 7);
INSERT INTO `all_items` VALUES (16206, 'Vesper Singer - Hail {PvP}', 'Empower', 'Редкий предмет, увеличивает Маг. Атк., <Свойство Кристалла Души>Дает возможность увеличить Маг. Атк. на 151, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Grants a chance to increase M. Atk. by 151, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (16207, 'Vesper Singer - Hail {PvP}', 'MP Regeneration', 'Редкий предмет, увеличивает Маг. Атк., <Свойство Кристалла Души>Дает возможность увеличить скорость восстановления MP, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Grants a chance to increase MP recovery rate, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (16208, 'Vesper Singer - Hail {PvP}', 'Magic Hold', 'Редкий предмет, увеличивает Маг. Атк., <Свойство Кристалла Души>Дает 20% колдовства Корня Дриады, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Маг. при атаке.', 'Rare item, increases M. Atk. <Soul Crystal Effect> Grants a 20% chance to cast Dryad Root, deals extra damage in PvP. Grants a certain probability to increase Casting Spd. on attack.', 'weapon_vesper_singer_i01', 7);
INSERT INTO `all_items` VALUES (16209, 'Vesper Thrower - Clairvoyance {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивает дальность атаки, <Свойство Кристалла Души>Дает возможность уменьшить расход MP на 8% при атаке магией, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Rare item, increases attack range. <Soul Crystal Effect> Grants a chance to decrease MP consumption by 8% when using magic, deals extra damage in PvP. Grants a certain probability to increase bow/crossbow Atk. Spd. on attack.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16210, 'Vesper Thrower - Clairvoyance {PvP}', 'Focus', 'Редкий предмет, увеличивает дальность атаки, <Свойство Кристалла Души>Дает возможность увеличить шанс Крит. Атк. на 113, наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Rare item, increases attack range. <Soul Crystal Effect> Grants a chance to increase Critical Rate by 113, deals extra damage in PvP. Grants a certain probability to increase bow/crossbow Atk. Spd. on attack.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16211, 'Vesper Thrower - Clairvoyance {PvP}', 'Critical Slow', 'Редкий предмет, увеличивает дальность атаки, <Свойство Кристалла Души>Дает 33% шанса замедлить при нанесении Крит. Атк., наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Critical Slow	Masterwork Item that increases range. <Soul Crystal Enhancement>nInflicts Slow with 33% chance during a Critical Attack. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_vesper_thrower_i01', 7);
INSERT INTO `all_items` VALUES (16212, 'Vesper Pincer- Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Haste	Masterwork Item that increases P. Critical Rate. Kamael-exclusive Weapon: Vesper Cutter Conversion n<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16213, 'Vesper Pincer- Thunder {PvP}', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Макс. HP увеличивается на 25%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Health	Masterwork Item that increases P. Critical Rate. Kamael-exclusive Weapon: Vesper Cutter Conversion n<Soul Crystal Enhancement>nIncreases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16214, 'Vesper Pincer- Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 131. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки. При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Focus	Masterwork Item that increases P. Critical Rate. Kamael-exclusive Weapon: Vesper Cutter Conversion n<Soul Crystal Enhancement>nIncreases Critical by 131. Increases damage inflicted during PvP. Has a chance of recovering CP during an attack.nWhen enchanted to 4 or more, there is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption during skill use.', 'weapon_vesper_pincer_i01', 7);
INSERT INTO `all_items` VALUES (16215, 'Vesper Shooter - Clairvoyance {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивающий дальность атаки, Эксклюзивное оружие Камаэль: Конверсия Броска Венеры.<Свойство Кристалла Души>Расход МР на умения сокращается на 12%. Наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Cheap Shot	Masterwork Item that increases range. Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nMP consumption decreases by 12% during skill use. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (16216, 'Vesper Shooter - Clairvoyance {PvP}', 'Focus', 'Редкий предмет, увеличивающий дальность атаки, Эксклюзивное оружие Камаэль: Конверсия Броска Венеры.<Свойство Кристалла Души>Увеличивается шанс Крит. Атк. на 133. Наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Focus	Masterwork Item that increases range. Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nIncreases Critical by 133. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (16217, 'Vesper Shooter - Clairvoyance {PvP}', 'Critical Slow', 'Редкий предмет, увеличивающий дальность атаки, Эксклюзивное оружие Камаэль: Конверсия Броска Венеры.<Свойство Кристалла Души>Дает 24% шанса замедлить врага при критической атаке. Наносит дополнительный урон в PvP. С определенной вероятностью увеличивает Скор. Атк. из лука/арбалета.', 'Critical Slow	Masterwork Item that increases range. Kamael-exclusive Weapon: Vesper Thrower Conversionn<Soul Crystal Enhancement>nCasts Slow at a 24% rate during a Critical Attack. Increases damage inflicted during PvP. Has a chance of increasing  Atk. Spd. of bows/crossbows during an attack.', 'weapon_vesper_schutze_i01', 7);
INSERT INTO `all_items` VALUES (16218, 'Vesper Nagan - Gale {PvP}', 'Haste', 'Редкий предмет, увеличивающий Скор. Атк., Эксклюзивное оружие Камаэль: Конверсия Эспадона Венеры.<Свойство Кристалла Души>Увеличивает Скор. Атк. прибл. на 11%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Haste	Masterwork Item that increases Atk. Spd. Kamael-exclusive Weapon: Vesper Slasher Conversionn<Soul Crystal Enhancement>nIncreases Atk. Spd. by about 11%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'weapon_vesper_nagen_i01', 7);
