INSERT INTO `all_items` VALUES (16369, 'Sealed Vesper Ring', NULL, 'Запечатанный редкий предмет. Печать можно снять у Кузнеца Маммона или у Мастера Ишумы. Распечатанный предмет увеличивает сопротивление шоку.', 'Sealed Masterwork Item. Seal can be removed by the Blacksmith of Mammon or Maestro Ishuma. When the seal is broken, Resistance to Shock is increased.', 'vesper_ring_i01', 0);
