INSERT INTO `all_items` VALUES (16381, 'Training Order Paper', NULL, 'Приказ, который находится у Главного Наставника Ксель-Махума. Отнесите его Стражу Стэну в Орен.', 'An order held by Xel-Mahum Head Instructor. Take it to Guard Stan in Oren.', 'roll_of_paper_red_i00', 0);
