INSERT INTO `all_items` VALUES (16403, 'Christmas Cake', NULL, 'Новогодний Торт. Восстанавливает всю энергию. Время повторного использования: 60 мин. Нельзя обменять, выбросить, уничтожить и положить в личное хранилище.', 'New Year Cake. Fully restores Vitality. Reuse delay: 60 min. Cannot be traded, dropped, destroyed, or deposited into a personal warehouse.', 'event_six_party_cake_i00', 3);
INSERT INTO `all_items` VALUES (16404, 'White Christmas Wish Candle', NULL, 'Белая Новогодняя Свеча. Поддерживает уровень энергии в течение 10 минут. Время повторного использования: 30 мин. Нельзя обменять, выбросить, уничтожить и продать в личном магазине.', 'White New Year Candle. Maintains energy level for 10 minutes. Reuse delay: 30 min. Cannot be traded, dropped, destroyed, or sold in a private store.', 'etc_candle_white_i00', 3);
INSERT INTO `all_items` VALUES (16405, 'Christmas Cake (event)', NULL, 'Новогодний Торт. Восстанавливает всю энергию. Время повторного использования: 60 мин. Нельзя обменять, выбросить, уничтожить и положить в личное хранилище.', 'New Year Cake. Fully restores Vitality. Reuse delay: 60 min. Cannot be traded, dropped, destroyed, or deposited into a personal warehouse.', 'event_six_party_cake_i00', 3);
INSERT INTO `all_items` VALUES (16406, 'White Christmas Wish Candle (event)', NULL, 'Белая Новогодняя Свеча. Поддерживает уровень энергии в течение 10 минут. Время повторного использования: 30 мин. Нельзя обменять, выбросить, уничтожить и продать в личном магазине.', 'White New Year Candle. Maintains energy level for 10 minutes. Reuse delay: 30 min. Cannot be traded, dropped, destroyed, or sold in a private store.', 'etc_candle_white_i00', 3);
INSERT INTO `all_items` VALUES (16407, 'Santa\'s Stocking', 'Event', 'Носок для Подарков. Если по нему дважды кликнуть мышкой, есть шанс получить бонусный предмет. Нельзя обменять, выкинуть, уничтожить и положить в личное хранилище.', 'Gift Sock. Double-clicking it grants a chance to receive a bonus item. Cannot be traded, dropped, destroyed, or deposited into a personal warehouse.', 'xmas_present_i00', 0);
INSERT INTO `all_items` VALUES (16408, 'Santa\'s Buff Scroll', 'Event', 'Свиток Положительных Эффектов Деда Мороза. При использовании Вы получаете Благословение Деда Мороза на 1 час. Нельзя обменять, выбросить, уничтожить и положить в личное хранилище.', 'Santa\'s Buff Scroll. When used, you receive Santa\'s Blessing for 1 hour. Cannot be traded, dropped, destroyed, or deposited into a personal warehouse.', 'mysterious_wedding_i00', 3);
