INSERT INTO `all_items` VALUES (16960, 'Г‰clair Bijou of Fortune', '90-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +6%. Наносит дополнительный урон в PvP. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений для Вас и членов Вашей группы. Нельзя обменять/выбросить.', 'Kamael Exclusive Weapon. Atk. Spd. +6%. Deals extra damage in PvP. Critical attacks grant a chance to increase P. Atk., M. Atk., and healing power, while decreasing MP consumption for skills used by you and your party members. Cannot be traded or dropped.', 'weapon_greed_stinger_i01', 4);
INSERT INTO `all_items` VALUES (16961, 'Colichemarde of Fortune', '90-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +6%, При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений для Вас и членов Вашей группы. Нельзя обменять/выбросить.', '9-Day Limited Period	Kamael-exclusive Weapon. Increases Atk. Spd. by about 6%. There is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_colichemarde_i01', 3);
INSERT INTO `all_items` VALUES (16962, 'Admiral\'s Estoc of Fortune', '90-day limited period', 'Эксклюзивное оружие Камаэль. Скор. Атк. +7%, При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений для Вас и членов Вашей группы. Нельзя обменять/выбросить.', '9-Day Limited Period	Kamael-exclusive Weapon. Increases Atk. Spd. by about 7%. There is a chance that party members including yourself will get increased P. Atk., M. Atk., and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_blink_slasher_i01', 2);
INSERT INTO `all_items` VALUES (16963, 'Grand Г‰pГ©e of Fortune', '90-day limited period', 'Эксклюзивное оружие Камаэль. При критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании Умений для Вас и членов Вашей группы. Нельзя обменять/выбросить.', '9-Day Limited Period	Kamael-exclusive Weapon. Has a chance that party members including yourself will get increased P. Atk., M. Atk. and the amount of received heal, and decreased MP consumption per skill during a Critical Attack. Cannot be exchanged or dropped.', 'weapon_rapier_i00', 1);
