INSERT INTO `all_items` VALUES (17018, 'Hot Springs Potion', NULL, 'Бутылка с водой из горячего источника. Может вылечить от ревматизма, холеры и гриппа…', 'Bottle of Hot Spring Water. Can cure rheumatism, cholera, and flu...', 'etc_cp_potion_i01', 3);
INSERT INTO `all_items` VALUES (17019, 'Mounting Item 3 Pack', NULL, 'Витаминная упаковкаВнутри находится Браслет Златогривого Льва (7 дн.), Браслет Сиреневого Коня (7 дн.) и Браслет Парового Жука (7 дн.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Gold-maned Lion Bracelet (7 days), Lilac Horse Bracelet (7 days), and Steam Beetle Bracelet (7 days). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (17020, 'Fresh Milk Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Парное Молоко - Ивент. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Mixed Milk - Event. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17021, 'Dimensional Experience Pack 30 - For Events', NULL, 'Витаминная упаковкаВнутри находится Упаковка: Купон Обмена Особого Питомца (2 шт.), Благословенное Перо (3 шт.) и Билет в Камалоку (3 шт.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Special Pet Exchange Coupon Package (2 pcs.), Blessed Feather (3 pcs.), and Kamaloka Ticket (3 pcs.). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17022, 'Varka Karm Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Знак Варка (Для Фавнов Варка). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Varka Badge (for Varka Silenos). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17023, 'Ketra Karm Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Знак Кетра (Для Орков Кетра). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Ketra Badge (for Ketra Orcs). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17024, 'Vitality Maintaining Potion Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Зелье Поддержания Энергии на 30 минут (5 шт.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains 30-minute Energy Maintenance Potion (5 pcs.). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17025, 'PC Cafe Point (7000 Points) Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится 7000 Очков Компьютерного Клуба. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains 7,000 PC Cafe Points. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17026, 'Admiral\'s Cap Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Шляпа Старшего Помощника - Ивент. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Senior Assistant Hat - Event. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
