INSERT INTO `all_items` VALUES (17029, 'Black Phantom Mask Pack - For Events', NULL, 'Витаминная упаковкаВнутри находится Черная Маска Фантома - Ивент. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitality Package. Contains Black Phantom Mask - Event. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17030, 'Forgotten Scroll - Create Item Lv 10', NULL, 'Свиток, необходимый для изучения умения \"Создание Предметов. Уровень 10\". Профессия: Мастер. Необходимый уровень : 82.', 'Scroll required to learn \"Create Item Level 10\". Class: Master. Required level: 82.', 'BranchSys2.Icon.br_spell_books_sword_i01', 0);
INSERT INTO `all_items` VALUES (17031, 'Freya White Pack', NULL, 'Содержит Напиток Всплеска Энергии (3 шт.)Кристаллы ветра, огня, воды, земли, святости, тьмы.Венец льда. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Contains Energy Splash Potion (3 pcs.), Wind, Fire, Water, Earth, Divine, Dark Attribute Crystals, and Ice Crown. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17032, 'Hero\'s Treasure Pack', NULL, 'Содержит сундук с Сокровищами Героя. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Contains Hero\'s Treasure Chest. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17033, 'Circlet of Freeze - For Events', '30-day limited period', 'Венец, обладающий силой льда. Увеличивает сопротивление воде. Требует две ячейки головных уборов. Время действия: 30 дн.', 'A circlet imbued with the power of ice. Increases Water resistance. Requires two hair accessory slots. Duration: 30 days.', 'accessory_ice_circlet_i00', 0);
INSERT INTO `all_items` VALUES (17034, 'Forgotten Scroll - Fighter\'s Will - For Events', NULL, 'Свиток, необходимый для изучения умения \"Воля Воина\". Можно использовать с 81 уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Warrior\'s Will\". Usable from level 81. Cannot be traded or dropped. Event item.', 'BranchSys2.Icon.br_spell_books_sword_i00', 0);
INSERT INTO `all_items` VALUES (17035, 'Forgotten Scroll - Archer\'s Will - For Events', NULL, 'Свиток, необходимый для изучения умения \"Воля Стрелка\". Можно использовать с 81 уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Archer\'s Will\". Usable from level 81. Cannot be traded or dropped. Event item.', 'BranchSys2.Icon.br_spell_books_sword_i00', 0);
INSERT INTO `all_items` VALUES (17036, 'Forgotten Scroll - Magician\'s Will - For Events', NULL, 'Свиток, необходимый для изучения умения \"Воля Мага\". Класс: Маги. Можно использовать с 81 уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Wizard\'s Will\". Class: Mages. Usable from level 81. Cannot be traded or dropped. Event item.', 'BranchSys2.Icon.br_spell_books_magic_i00', 0);
INSERT INTO `all_items` VALUES (17037, 'Forgotten Scroll - Protection of Rune - For Events', NULL, 'Свиток, необходимый для изучения умения \"Защита Рун\". Можно использовать с 82-го уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Protection of Rune\". Usable from level 82. Cannot be traded or dropped. Event item.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (17038, 'Forgotten Scroll - Protection of Elemental - For Events', NULL, 'Свиток, необходимый для изучения умения \"Защита Стихий\". Можно использовать с 82-го уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Protection of Elements\". Usable from level 82. Cannot be traded or dropped. Event item.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (17039, 'Forgotten Scroll - Protection of Alignment - For Events', NULL, 'Свиток, необходимый для изучения умения \"Защита Равновесия\". Можно использовать с 82-го уровня. Нельзя обменять/выбросить. Предмет для ивента.', 'Scroll required to learn the skill \"Protection of Alignment\". Usable from level 82. Cannot be traded or dropped. Event item.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (17040, 'Love Box Pack', NULL, 'Упаковка, в которой находится Сундук Любви. Нельзя обменять или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7 июля.', 'Package containing a Chest of Love. Cannot be traded or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_love_pack', 0);
INSERT INTO `all_items` VALUES (17041, 'Sentiment Box Pack', NULL, 'Упаковка, в которой находится Сундук Сердцебиения. Нельзя обменять или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7 июля.', 'Package containing a Chest of Heartbeats. Cannot be traded or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_belief_pack', 0);
INSERT INTO `all_items` VALUES (17042, 'Confession Box Pack', NULL, 'Упаковка, в которой находится Сундук Признания. Нельзя обменять или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7 июля.', 'Package containing a Chest of Confessions. Cannot be traded or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_wish_pack', 0);
INSERT INTO `all_items` VALUES (17043, 'Joy Box Pack', NULL, 'Упаковка, в которой находится Сундук Радости. Нельзя обменять или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7 июля.', 'Package containing a Chest of Joy. Cannot be traded or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_joy_pack', 0);
INSERT INTO `all_items` VALUES (17044, 'Love Box', NULL, 'Талисманы СИЛ, ЛВК, ВЫН. Нельзя уничтожить или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7-го июля.', 'STR, DEX, CON Talismans. Cannot be destroyed or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_love_pack', 0);
INSERT INTO `all_items` VALUES (17045, 'Sentiment Box', NULL, 'Талисманы МДР, ДУХ, ИНТ. Нельзя уничтожить или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7-го июля.', 'WIT, MEN, INT Talismans. Cannot be destroyed or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_belief_pack', 0);
INSERT INTO `all_items` VALUES (17046, 'Confession Box', NULL, 'Талисманы, дающие сопротивление оглушению, усыплению, удерживанию, параличу. Нельзя уничтожить или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7-го июля.', 'Talismans granting resistance to stun, sleep, hold, and paralysis. Cannot be destroyed or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_wish_pack', 0);
INSERT INTO `all_items` VALUES (17047, 'Joy Box', NULL, 'Содержит Сундуки Любви, Сердцебиения, Признания. Нельзя уничтожить или выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7-го июля.', 'Contains Chests of Love, Heartbeats, and Confessions. Cannot be destroyed or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'etc_pi_box_joy_pack', 0);
INSERT INTO `all_items` VALUES (17048, 'Shiny Bracelet Pack', NULL, 'Упаковка, в которой находится блестящий браслет.  Этот предмет исчезнет после проверки 7 июля.', 'Package containing a shining bracelet. This item will disappear after the July 7 maintenance.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17049, 'Shiny Bracelet', NULL, 'При надевании добавляет 3 ячейки для талисманов. Нельзя использовать во время Олимпиады, нельзя обменять, выбросить, можно положить в личное хранилище.  Этот предмет исчезнет после проверки 7-го июля.', 'When equipped, adds 3 talisman slots. Cannot be used during the Olympiad. Cannot be traded or dropped, but can be deposited into a personal warehouse. This item will disappear after the July 7 maintenance.', 'accessory_shiny_bracelet', 0);
INSERT INTO `all_items` VALUES (17050, 'Shiny Couple Ring', NULL, 'Кольцо, с помощью которого можно призвать другого персонажа при условии, что оба персонажа обладают таким кольцом. Повторное использование через 1 час. Нельзя обменять, выбросить.  Этот предмет исчезнет после проверки 7-го июля.', 'A ring used to summon another character, provided both characters possess such a ring. Reuse delay: 1 hour. Cannot be traded or dropped. This item will disappear after the July 7 maintenance.', 'accessory_shiny_couple_ring', 0);
INSERT INTO `all_items` VALUES (17051, 'Talisman - STR', NULL, 'Предмет для ивента. При надевании дает СИЛ +2. Нельзя обменять, выбросить и использовать в олимпиаде. Этот предмет исчезнет через 14 дней после получения.', 'Event item. When equipped, grants STR +2. Cannot be traded, dropped, or used in the Olympiad. This item disappears 14 days after acquisition.', 'etc_talisman_event_i00', 0);
