INSERT INTO `all_items` VALUES (17072, 'Vesper Armor Box', 'Event', 'Внутри находится доспех Венеры.', 'Contains Vesper armor.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17073, 'Moirai Armor Box', 'Event', 'Внутри находится доспех Дестино.', 'Contains Destino armor.', 'etc_pi_gift_box_i04', 0);
