INSERT INTO `all_items` VALUES (17075, 'Soul Crystal - Stage 14 Box', 'Event', 'Коробка, в которой находится один из Кристаллов Души - Уровень 14.', 'A box containing a Level 14 Soul Crystal.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17076, 'Soul Crystal - Stage 15 Box', 'Event', 'Коробка, в которой находится один из Кристаллов Души - Уровень 15.', 'A box containing a Level 15 Soul Crystal.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17077, 'Soul Crystal - Stage 16 Box', 'Event', 'Коробка, в которой находится один из Кристаллов Души - Уровень 16.', 'A box containing a Level 16 Soul Crystal.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17078, 'Potion Box of Mask Type', NULL, 'Коробка, в которой находится одно из Зелий Внешности. Иногда попадается Парное Молоко.', 'A box containing a Face Potion. Sometimes yields Mixed Milk.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17079, 'Potion Box of Hair Color', NULL, 'Коробка, в которой находится одно из Красящих Зелий. Иногда попадается Парное Молоко.', 'A box containing a Dye Potion. Sometimes yields Mixed Milk.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17080, 'Potion Box of Hair Style', NULL, 'Коробка, в которой находится одно из Зелий Прически. Иногда попадается Парное Молоко.', 'A box containing a Hair Potion. Sometimes yields Mixed Milk.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17081, 'Golden Apigas Box', NULL, 'Коробка, в которой находится Самоцвет: Ранг S и одна руда.', 'A box containing an S-grade Gemstone and one ore.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17082, 'Transformation Sealbook: Anakim Pack', NULL, 'Упаковка, в которой находится Книга Трансформации в Анакима. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Package containing the Anakim Transformation Book. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17083, 'Bird Nest - For Events', NULL, 'Упаковка , в которой находится Птичье Гнездо. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Package containing a Bird Nest. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17084, 'Shadow Item - Magician Cap Pack', 'Escape', 'Упаковка , в которой находится Теневой Предмет - Шляпа Чародея. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Package containing a Shadow Item - Wizard\'s Hat. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17085, 'Shadow Item - Magician Cap Pack', 'Big Head', 'Упаковка , в которой находится Теневой Предмет - Шляпа Чародея. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Package containing a Shadow Item - Wizard\'s Hat. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17086, 'Shadow Item - Magician Cap Pack', 'Firework', 'Упаковка , в которой находится Теневой Предмет - Шляпа Чародея. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Package containing a Shadow Item - Wizard\'s Hat. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17087, 'Twin Coba Seed', NULL, 'Семя Двойной Кобы. Для получения плода вживите его в монстра в районе Орена. Наилучшего результата можно достичь, если персонаж и монстр 77-87 уровней.', 'Double Cob Seed. Plant it in a monster in the Oren region to obtain fruit. Best results are achieved when the character and monster are levels 77-87.', 'etc_twin_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (17088, 'Seed: Alternative Twin Coba', NULL, 'Семя Новой Двойной Кобы. Для получения плода вживите его в монстра в районе Орена. Наилучшего результата можно достичь, если персонаж и монстр 77-87 уровней.', 'New Double Cob Seed. Plant it in a monster in the Oren region to obtain fruit. Best results are achieved when the character and monster are levels 77-87.', 'etc_twin_coba_seed_i00', 11);
INSERT INTO `all_items` VALUES (17089, 'Red Coba Seed', NULL, 'Семя Красной Кобы. Для получения плода вживите его в монстра в районе Шутгарта. Наилучшего результата можно достичь, если персонаж и монстр 65-75 уровней.', 'Red Cob Seed. Plant it in a monster in the Schuttgart region to obtain fruit. Best results are achieved when the character and monster are levels 65-75.', 'etc_red_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (17090, 'Seed: Alternative Red Coba', NULL, 'Семя Новой Красной Кобы. Для получения плода вживите его в монстра в районе Шутгарта. Наилучшего результата можно достичь, если персонаж и монстр 65-75 уровней.', 'New Red Cob Seed. Plant it in a monster in the Schuttgart region to obtain fruit. Best results are achieved when the character and monster are levels 65-75.', 'etc_red_coba_seed_i00', 11);
INSERT INTO `all_items` VALUES (17091, 'Golden Coba Seed', NULL, 'Семя Золотой Кобы. Для получения плода вживите его в монстра в районе Шутгарта. Наилучшего результата можно достичь, если персонаж и монстр 68-78 уровней.', 'Gold Cob Seed. Plant it in a monster in the Schuttgart region to obtain fruit. Best results are achieved when the character and monster are levels 68-78.', 'etc_golden_coba_seed_i00', 10);
INSERT INTO `all_items` VALUES (17092, 'Seed: Alternative Golden Coba', NULL, 'Семя Новой Золотой Кобы. Для получения плода вживите его в монстра в районе Шутгарта. Наилучшего результата можно достичь, если персонаж и монстр 68-78 уровней.', 'New Gold Cob Seed. Plant it in a monster in the Schuttgart region to obtain fruit. Best results are achieved when the character and monster are levels 68-78.', 'etc_golden_coba_seed_i00', 11);
INSERT INTO `all_items` VALUES (17093, 'Vitality Maintaining Potion (10 mintues) (Event)', NULL, 'Поддерживает уровень энергии в течение 10 минут. Время повторного использования: 30 мин. Нельзя обменять, выбросить и уничтожить.', 'Maintains energy level for 10 minutes. Reuse delay: 30 min. Cannot be traded, dropped, or destroyed.', 'etc_lesser_potion_blue_i00', 3);
INSERT INTO `all_items` VALUES (17094, 'Nevit\'s Voice', NULL, 'Раковина моллюска, содержащая голос Невитта. Увеличивает кол-во рекомендаций на 10. Нельзя обменять/выбросить.', 'A seashell containing Nevit\'s voice. Increases the number of recommendations by 10. Cannot be traded or dropped.', 'etc_fish_scale_i01', 3);
INSERT INTO `all_items` VALUES (17095, 'Nevit\'s Hourglass - 1 hour', '1~19', 'Увеличивают время действия Благословения Невитта на 1 час, можно использовать только с 1-го по 19-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 1 hour. Usable only by levels 1-19. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
