INSERT INTO `all_items` VALUES (17122, 'Nevit\'s Hourglass - 2 hour', '76~79', 'Увеличивают время действия Благословения Невитта на 2 часа, можно использовать только с  76-го по 79-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2 hours. Usable only by levels 76-79. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17123, 'Nevit\'s Hourglass - 2.5 hour', '76~79', 'Увеличивают время действия Благословения Невитта на 2.5 часа, можно использовать только с  76-го по 79-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2.5 hours. Usable only by levels 76-79. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17124, 'Nevit\'s Hourglass - 3 hour', '76~79', 'Увеличивают время действия Благословения Невитта на 3 часа, можно использовать только с  76-го по 79-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 3 hours. Usable only by levels 76-79. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17125, 'Nevit\'s Hourglass - 1 hour', '80~85', 'Увеличивают время действия Благословения Невитта на 1 час, можно использовать только с  80-го по 85-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 1 hour. Usable only by levels 80-85. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17126, 'Nevit\'s Hourglass - 1.5 hour', '80~85', 'Увеличивают время действия Благословения Невитта на 1.5 часа, можно использовать только с  80-го по 85-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 1.5 hours. Usable only by levels 80-85. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17127, 'Nevit\'s Hourglass - 2 hour', '80~85', 'Увеличивают время действия Благословения Невитта на 2 часа, можно использовать только с  80-го по 85-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2 hours. Usable only by levels 80-85. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17128, 'Nevit\'s Hourglass - 2.5 hour', '80~85', 'Увеличивают время действия Благословения Невитта на 2.5 часа, можно использовать только с  80-го по 85-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2.5 hours. Usable only by levels 80-85. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17129, 'Nevit\'s Hourglass - 3 hour', '80~85', 'Увеличивают время действия Благословения Невитта на 3 часа, можно использовать только с  80-го по 85-й уровень, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 3 hours. Usable only by levels 80-85. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17130, 'Freesia Bouquet (Event)', NULL, 'Букет фрезии, на языке цветов обозначающей <невинность>. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A bouquet of freesia, which means \"innocence\" in the language of flowers. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_flower_bouquet_i02', 1);
INSERT INTO `all_items` VALUES (17131, 'Baby Breath Bouquet (Event)', NULL, 'Букет мыльного корня, на языке цветов обозначающего <грусть> . Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A bouquet of soapwort, which means \"sadness\" in the language of flowers. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_flower_bouquet_i03', 1);
INSERT INTO `all_items` VALUES (17132, 'Pink Lady (Event)', NULL, 'Коктейль, посвященный поставленной в 1912 году в Лондоне и по тем временам популярной английской пьесе <Розовая леди>. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A cocktail dedicated to the popular 1912 London-staged English play \"The Pink Lady.\" If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_fruit_cocktail_i02', 1);
INSERT INTO `all_items` VALUES (17133, 'June Bug (Event)', NULL, 'На аромат сладкого сочно-зеленого коктейля <Июньский жук>, как на цветы, слетаются жуки. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'Bugs flock to the sweet, lush green \"June Bug\" cocktail just like flowers. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_fruit_cocktail_i03', 1);
INSERT INTO `all_items` VALUES (17134, 'Soft Cheesecake (Event)', NULL, 'Умеренно сладкий вкусный пудинг высшего качества. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A moderately sweet, delicious top-quality pudding. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_herb_of_cheesecake', 1);
INSERT INTO `all_items` VALUES (17135, 'Freshly-Baked Baguette (Event)', NULL, 'В отличие от обычных жестких багетов, этот очень мягкий и вкусный. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'Unlike regular hard baguettes, this one is very soft and delicious. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_herb_of_baguette', 1);
INSERT INTO `all_items` VALUES (17136, 'Sweet Cream Bun (Event)', NULL, 'Сладкое лакомство, изготовленное из яичных желтков, а не из сливок и крема. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A sweet treat made from egg yolks rather than cream. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_herb_of_cream', 1);
INSERT INTO `all_items` VALUES (17137, 'White Day Candy (Event)', NULL, 'Сладкий подарок, который понравится каждому. Если его применить к персонажу, атакующему первым, имя которого отображается фиолетовым цветом, или хаотическому персонажу, то собственное имя тоже может изменить свой цвет на фиолетовый.', 'A sweet gift that everyone will enjoy. If used on a first-attacking character whose name appears in purple or on a chaotic character, your own name may also turn purple.', 'etc_whiteday_candy_i00', 1);
INSERT INTO `all_items` VALUES (17138, 'Freya\'s Gift', NULL, 'Коробка, в которой содержится душа Снежной Королевы.', 'A box containing the soul of the Snow Queen.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17139, 'Transformation Scroll: Anakim', NULL, 'На 30 минут превращает в Анаким. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Transforms you into Anakim for 30 minutes. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_trans_4f_s_b_01', 0);
INSERT INTO `all_items` VALUES (17140, 'Transformation Scroll: Zaken', NULL, 'На 30 минут превращает в Закена. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Transforms you into Zaken for 30 minutes. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_trans_4f_s_b_01', 0);
INSERT INTO `all_items` VALUES (17141, 'Ribbon Hairband', 'Promotion', 'Длинная лента бантиком. Только для персонажей женского пола. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Large ribbon hair accessory. Can only be equipped by females. Takes up two hair accessory slots. Cannot be traded, dropped, or stored in a private store. Can be stored in a private warehouse.', 'accessory_ev_ribbon_band_i00', 0);
INSERT INTO `all_items` VALUES (17142, 'Refined Wizard Hat', 'Promotion', 'Элегантный Колпак мага. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Refined Wizard Hat. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_magician_cap2_i00', 0);
INSERT INTO `all_items` VALUES (17143, 'Refined Jester Hat', 'Promotion', 'Элегантный Колпак Шута. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Refined Jester Hat. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_jester_cap_2_i00', 0);
INSERT INTO `all_items` VALUES (17144, 'Refined Romantic Chapeau', 'Promotion', 'Элегантный Капюшон Романтика. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Refined Romantic Chapeau. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_archer_hat2_i00', 0);
INSERT INTO `all_items` VALUES (17145, 'Refined Dapper Cap', 'Promotion', 'Элегантная Шляпа. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Refined Dapper Cap. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_dandy_cap2_i00', 0);
INSERT INTO `all_items` VALUES (17146, 'Refined Angel Ring', 'Promotion', 'Элегантный Обруч Ангела. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Refined Angel Ring. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_angel_ring_i00', 0);
INSERT INTO `all_items` VALUES (17147, 'Popped-Out Eye', 'Promotion', 'Головной убор в форме Глаза Жука. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Popped-out eye shaped hat. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_beetle_eye_i00', 0);
INSERT INTO `all_items` VALUES (17148, 'Bird Nest', 'Promotion', 'Головной убор в форме Птичьего Гнезда. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Bird nest shaped hair accessory. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_nest_hat_i00', 0);
INSERT INTO `all_items` VALUES (17149, 'Varka Karm (used by Varka Silenos)', 'Promotion', 'Головной убор, символ племени Варка. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Karm that represents the Varka race. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_barka_karm_i00', 0);
INSERT INTO `all_items` VALUES (17150, 'Ketra Karm (used by Ketra Orcs)', 'Promotion', 'Головной убор, символ племени Кетра. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'A headwear symbol of the Ketra tribe. Requires two hair accessory slots. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'accessory_ketra_karm_i00', 0);
INSERT INTO `all_items` VALUES (17151, 'Puffy Hat of Friendship', 'Promotion', 'Шляпа Удачи, предназначенная для друзей. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Puffy hat created to commemorate your friendship with a friend. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_globefish_cap_i00', 0);
INSERT INTO `all_items` VALUES (17152, 'Arrow-Pierced Apple', 'Promotion', 'Стрела в яблоке. Помещается на голову. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Arrow-pierced Apple. It can be worn on the head. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_arrow_apple_i00', 0);
INSERT INTO `all_items` VALUES (17153, 'Fish Hat', 'Promotion', 'Интересный Головной аксессуар в виде рыбы. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Interesting hair accessory that looks like a fish. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_fish_cap_i00', 0);
INSERT INTO `all_items` VALUES (17154, 'Purple Viking Circlet', 'Promotion', 'Фиолетовая Диадема Викингов. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Purple Viking Circlet. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_viking_circlet_violet_i00', 0);
INSERT INTO `all_items` VALUES (17155, 'Golden Viking Circlet', 'Promotion', 'Золотая Диадема Викингов. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Golden Viking Circlet. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_viking_circlet_gold_i00', 0);
INSERT INTO `all_items` VALUES (17156, 'White Sheep Hat', 'Promotion', 'Головной аксессуар в виде белой овцы. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Fun hair accessory in the shape of a white sheep. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_sheep_cap_white_i00', 0);
INSERT INTO `all_items` VALUES (17157, 'Black Sheep Hat', 'Promotion', 'Головной аксессуар в виде черной овцы. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Promotion	Black sheep shaped funny hair accessory. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'accessory_sheep_cap_black_i00', 0);
INSERT INTO `all_items` VALUES (17161, 'Special Gift of April Fool\'s Day (Event)', NULL, 'Особая коробка удачи, которую в День Смеха получает самый успешный человек. Что же внутри?', 'A special lucky box received by the most successful person on April Fools\' Day. What\'s inside?', 'etc_pi_gift_box_i01', 0);
INSERT INTO `all_items` VALUES (17162, 'Golem Shard Piece', NULL, 'Обломок Голема, добытый в результате охоты на големов. Соберите эти предметы и отнесите Яшени.', 'Golem fragment obtained by hunting golems. Collect these items and take them to Yasheni.', 'etc_coal_i00', 0);
INSERT INTO `all_items` VALUES (17163, 'Event - Energy of Sprout', NULL, 'На 1 час Энергия Ростка дает усиление. Нельзя обменять, выбросить, уничтожить.', 'Sprout Energy grants a buff for 1 hour. Cannot be traded, dropped, or destroyed.', 'etc_leaf_green_i00', 3);
INSERT INTO `all_items` VALUES (17164, 'Event - Pack of Energy of Sprout', NULL, 'Ивентовая упаковка, содержащая Энергию Ростка (3 штуки); нельзя обменять, выбросить, уничтожить.', 'Event package containing Sprout Energy (3 pcs.); cannot be traded, dropped, or destroyed.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17165, 'Event - Vitality Replenishing Herb Tea 30 minutes', NULL, 'Ивентовая упаковка, содержащая 5 Отваров Всплеска Энергии: 30 минут; нельзя обменять, выбросить, уничтожить.', 'Event package containing 5 Energy Splash Potions: 30 minutes; cannot be traded, dropped, or destroyed.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17166, 'Pack of 10 Noble Enhancement Stones', NULL, 'Упаковка, содержащая 10 Усиливающих Камней Венеры.', 'Package containing 10 Vesper Enhancing Stones.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17167, 'Scroll: Enchant Weapon (S-Grade) Pack', NULL, 'Упаковка, содержащая 1 Свиток: Модифицировать Оружие (S).', 'Package containing 1 Scroll: Enchant Weapon (S).', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17168, 'Lesser Giant\'s Codex - Mastery Pack', NULL, 'Упаковка, содержащая 1 Кодекс Гигантов - Мастерство', 'Package containing 1 Giant\'s Codex - Mastery.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17169, 'Olympiad Treasure Chest', NULL, 'Сундук Олимпиады, нельзя обменять, выбросить, уничтожить.', 'Olympiad Chest. Cannot be traded, dropped, or destroyed.', 'event_hero_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (17170, 'Soccer Ball Afro Hair - White', NULL, 'Окрашивает прическу \"Афро\" в белый цвет. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Dyes the \"Afro\" hairstyle white. Requires two hair accessory slots. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_worldcup_hair_i00', 0);
INSERT INTO `all_items` VALUES (17171, 'Soccer Ball Afro Hair - Blue', NULL, 'Окрашивает прическу \"Афро\" в синий цвет. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Afro hair that has been dyed like a blue soccer ball. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'BranchSys2.br_worldcup_hair_i01', 0);
INSERT INTO `all_items` VALUES (17172, 'Soccer Ball Afro Hair - Red', NULL, 'Окрашивает прическу \"Афро\" в красный цвет. При использовании повышает скорость передвижения на 2%. Требует две ячейки головных уборов. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Afro hair that has been dyed like a red soccer ball. When equipped, you can receive the blessing of victory effect that raises Speed by 2%. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'BranchSys2.br_worldcup_hair_i02', 0);
INSERT INTO `all_items` VALUES (17173, 'Mark of Victory - Korea', NULL, 'Знак пожелания победы южнокорейской команде на Чемпионате мира по футболу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Mark that wishes for victory by the Korean team. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'BranchSys2.br_worldcup_face_deco_i00', 0);
INSERT INTO `all_items` VALUES (17174, 'Mark of Cheers', NULL, 'Знак поддержки любимой команды на Чемпионате мира по футболу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Mark containing a cheering heart. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'BranchSys2.br_worldcup_face_deco_i00', 0);
INSERT INTO `all_items` VALUES (17175, 'Balloon Stick of Cheers - Red', NULL, 'Флажок в поддержку любимой команды на Чемпионате мира по футболу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Balloon stick containing a cheering heart. Cannot be exchanged or dropped. Cannot use a private store. Can be stored in a private warehouse.', 'BranchSys2.br_worldcup_stick_i00', 0);
