INSERT INTO `all_items` VALUES (17184, '500,000 SP scroll', NULL, 'Свиток, восстанавливающий 500 000 SP.', 'Scroll that restores 500,000 SP.', 'etc_sp_scroll3_i00', 1);
INSERT INTO `all_items` VALUES (17185, '1,000,000 SP scroll', NULL, 'Свиток, восстанавливающий 1 000 000 SP.', 'Scroll that restores 1,000,000 SP.', 'etc_sp_scroll3_i00', 1);
INSERT INTO `all_items` VALUES (17186, 'National Representative Warrior\'s Ring', '3-day limited period', 'Кольцо Национального Героя. Можно использовать в течение 3 дней. Эффекты: МР +21, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления Удержанию на 30%, увеличение шанса Удержания на 30%. При надевании двух колец эффекты не суммируются. Нельзя обменять/выбросить.', '3-Day Limited Period	National Representative Warrior\'s Ring. Limited time item available for 3 days. MP+ 21; Resistance to Hold +3%; a chance of Hold attack +3%; increases Accuracy and P. Critical Damage. Only one effect is applied even when two identical rings are worn. Cannot be exchanged or dropped.', 'accessory_ring_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (17187, 'National Representative Warrior\'s Necklace', '3-day limited period', 'Ожерелье Национального Героя. Можно использовать в течение 3 дней. Эффекты: МР + 42, увеличение сопротивления к Параличу/Усыплению/Оглушению на 15%, увеличение шанса Паралича/Усыпления/Оглушения цели на 15%, уменьшение времени перезарядки умений. Отражает часть урона. Нельзя обменять/выбросить.', '3-Day Limited Period	National Representative Warrior\'s Necklace. Limited time item available for 3 days. MP+42, Sleep/Paralysis/Shock Resistance Increases by 15%. Sleep/Paralysis/Shock Atk. Rate Increases by 15%. Decreased skill cooldown and damage shield effects. Cannot be exchanged or dropped.', 'accessory_necklace_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (17188, 'National Representative Warrior\'s Earring', '3-day limited period', 'Серьга Национального Героя. Можно использовать в течение 3 дней. Эффекты: MP +31, эффект Ярости Вампира, увеличение сопротивления Оглушению и Отрицательным Эффектам на 20%, увеличение шанса Оглушения цели и наложения на нее Отрицательных Эффектов на 20%. Нельзя обменять/выбросить. При надевании двух серег эффекты не суммируются.', '3-Day Limited Period	National Representative Warrior\'s Earring. Limited-time item that can be worn for 3 days. It Has effects of MP +31, Shock/mind attack resistance +2%, Shock/Mental Atk. Rate +2% and Vampiric Rage. When equipped with two identical earrings, the effect of only one earring will be applied. Cannot be exchanged or dropped.', 'accessory_earring_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (17189, 'National Representative Warrior\'s Ring', '7-day limited period', 'Кольцо Национального Героя. Можно использовать в течение 7 дней. Эффекты: МР +21, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления Удержанию на 30%, увеличение шанса Удержания на 30%. При надевании двух колец эффекты не суммируются. Нельзя обменять/выбросить.', '7-Day Limited Period	National Representative Warrior\'s Ring. Limited time item available for 7 days. MP+ 21; Resistance to Hold +3%; a chance of Hold attack +3%; increases Accuracy and P. Critical Damage. Only one effect is applied even when two identical rings are worn. Cannot be exchanged or dropped.', 'accessory_ring_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (17190, 'National Representative Warrior\'s Necklace', '7-day limited period', 'Ожерелье Национального Героя. Можно использовать в течение 7 дней. Эффекты: МР + 42, увеличение сопротивления к Параличу/Усыплению/Оглушению на 15%, увеличение шанса Паралича/Усыпления/Оглушения цели на 15%, уменьшение времени перезарядки умений. Отражает часть урона. Нельзя обменять/выбросить.', 'National Hero\'s Necklace. Usable for 7 days. Effects: MP +42, Paralysis/Sleep/Stun resistance increased by 15%, target\'s Paralysis/Sleep/Stun chance increased by 15%, skill reuse delay decreased. Reflects a portion of damage. Cannot be traded or dropped.', 'accessory_necklace_of_hero_i00', 0);
INSERT INTO `all_items` VALUES (17191, 'National Representative Warrior\'s Earring', '7-day limited period', 'Серьга Национального Героя. Можно использовать в течение 7 дней. Эффекты: MP +31, эффект Ярости Вампира, увеличение сопротивления Оглушению и Отрицательным Эффектам на 20%, увеличение шанса Оглушения цели и наложения на нее Отрицательных Эффектов на 20%. Нельзя обменять/выбросить. При надевании двух серег эффекты не суммируются.', '7-Day Limited Period	National Representative Warrior\'s Earring. Limited-time item that can be worn for 7 days. It Has effects of MP +31, Shock/mind attack resistance +2%, Shock/Mental Atk. Rate +2% and Vampiric Rage. When equipped with two identical earrings, the effect of only one earring will be applied. Cannot be exchanged or dropped.', 'accessory_earring_of_hero_i00', 0);
