INSERT INTO `all_items` VALUES (17201, 'Proof of Cheers', NULL, 'Знак, необходимый для умения \"Воля Национального Героя\", \"Заклинание Благословения\", \"Энергия Победы\". Нельзя обменять/выбросить.', 'A sign required for the skills \"National Hero\'s Will\", \"Spell of Blessing\", and \"Energy of Victory\". Cannot be traded or dropped.', 'BranchSys2.br_cheer_symbol_i00', 0);
INSERT INTO `all_items` VALUES (17202, 'Proof of Cheers 10 Pack', NULL, 'Упаковка Знаков Болельщика, содержит 10 штук. Нельзя обменять/выбросить.', 'Cheerleader Sign Package, contains 10 pcs. Cannot be traded or dropped.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17203, 'Agathion Seal Bracelet - Ball Trapping Gnosian', NULL, 'Браслет для призыва Гасиона с мячом. Носит красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Bracelet for summoning Gasion with a ball. Wears a red uniform. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_aga_kball_male_i00', 0);
INSERT INTO `all_items` VALUES (17204, 'Agathion Seal Bracelet - Ball Trapping Orodriel', NULL, 'Браслет для призыва Родриэля с мячом. Носит красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Bracelet for summoning Rodrielle with a ball. Wears a red uniform. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_aga_kball_female_i00', 0);
INSERT INTO `all_items` VALUES (17205, 'Agathion Seal Bracelet - Penalty Kick', NULL, 'Браслет для призыва Гасиона или Родриэля, выполняющих пенальти. Носят красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Bracelet for summoning Gasion or Rodrielle performing a penalty kick. Wear red uniforms. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_aga_kball_kick_i00', 0);
INSERT INTO `all_items` VALUES (17206, 'Nevit\'s Hourglass - 1 hour', NULL, 'Увеличивают время действия Благословения Невитта на 1 час, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 1 hour. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17207, 'Nevit\'s Hourglass - 1.5 hour', NULL, 'Увеличивают время действия Благословения Невитта на 1.5 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 1.5 hours. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17208, 'Nevit\'s Hourglass - 2 hour', NULL, 'Увеличивают время действия Благословения Невитта на 2 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2 hours. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17209, 'Nevit\'s Hourglass - 2.5 hour', NULL, 'Увеличивают время действия Благословения Невитта на 2.5 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 2.5 hours. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17210, 'Nevit\'s Hourglass - 3 hour', NULL, 'Увеличивают время действия Благословения Невитта на 3 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 3 hours. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17211, 'Nevit\'s Hourglass - 4 hour', NULL, 'Увеличивают время действия Благословения Невитта на 4 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'Increases Nevit\'s Blessing duration by 4 hours. Usable at any level. Cannot be traded or dropped.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17212, 'Nevit\'s Voice', NULL, 'Раковина моллюска, содержащая голос Невитта. Увеличивает кол-во рекомендаций на 10. Нельзя обменять/выбросить.', 'A seashell containing Nevit\'s voice. Increases the number of recommendations by 10. Cannot be traded or dropped.', 'etc_fish_scale_i01', 3);
INSERT INTO `all_items` VALUES (17213, 'Solina\'s Biography', NULL, 'Книга, повествующая о жизни Солины и святой королевской семьи Эльморедена. Была запрещена лично королем, поэтому найти такую книгу - большая удача. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'A book detailing the life of Solina and the holy royal family of Elmoreden. It was banned by the king himself, so finding such a book is great luck. Can be studied by double-clicking the item with the mouse button.', 'etc_old_evil_book_i00', 0);
INSERT INTO `all_items` VALUES (17214, 'Kaerun\'s Memoir', NULL, 'Книга, повествующая о жизни Солины с точки зрения ее современника Каэруна. Хранилась в монастыре и никогда еще не покидала его пределы. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'A book detailing the life of Solina from the perspective of her contemporary Kaerun. Kept in the monastery and has never left its bounds. Can be studied by double-clicking the item with the mouse button.', 'etc_spell_books_assistance_i00', 0);
INSERT INTO `all_items` VALUES (17215, 'Kaerun\'s Memoir Part 1', NULL, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'Part of Kaerun\'s records detailing the life of Solina. The records are divided into 4 parts and kept in the Monastery of Silence. Can be studied by double-clicking the item with the mouse button.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (17216, 'Kaerun\'s Memoir Part 2', NULL, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'Part of Kaerun\'s records detailing the life of Solina. The records are divided into 4 parts and kept in the Monastery of Silence. Can be studied by double-clicking the item with the mouse button.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (17217, 'Kaerun\'s Memoir Part 3', NULL, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'Part of Kaerun\'s records detailing the life of Solina. The records are divided into 4 parts and kept in the Monastery of Silence. Can be studied by double-clicking the item with the mouse button.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (17218, 'Kaerun\'s Memoir Part 4', NULL, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'Part of Kaerun\'s records detailing the life of Solina. The records are divided into 4 parts and kept in the Monastery of Silence. Can be studied by double-clicking the item with the mouse button.', 'etc_piece_of_paper_white_i00', 0);
INSERT INTO `all_items` VALUES (17219, 'Eris\'s Chronicle', NULL, 'Записи настоятельницы Монастыря Безмолвия Элис, повествующие о последних днях жизни Солины. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'Records by Alice, Abbess of the Monastery of Silence, detailing the final days of Solina\'s life. Can be studied by double-clicking the item with the mouse button.', 'etc_spell_books_red_i00', 0);
INSERT INTO `all_items` VALUES (17220, 'Catalog Card', NULL, 'Записка Софии, смотрителя главной библиотеки Руны, в которой указано местонахождение обнаруженных ею книг. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'A note from Sophia, Rune Main Library Manager, indicating the location of the books she discovered. Can be studied by double-clicking the item with the mouse button.', 'etc_roll_of_paper_black_i00', 0);
INSERT INTO `all_items` VALUES (17221, 'Key to the Passageway', NULL, 'Ключ, открывающий дверь Прохода, запечатанного Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'A key that opens the door of the Pass sealed by the Saint. Having the key allows you to enter and exit the enclosed room.', 'etc_old_key_i00', 0);
INSERT INTO `all_items` VALUES (17222, 'Key to the Tomb', NULL, 'Ключ, открывающий дверь Усыпальницы в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'A key that opens the door of the Sepulcher in the Saint\'s chambers. Having the key allows you to enter and exit the enclosed room.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (17223, 'Key to the Library', NULL, 'Ключ, открывающий дверь Библиотеки в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'A key that opens the door of the Library in the Saint\'s chambers. Having the key allows you to enter and exit the enclosed room.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (17224, 'Key to the Warehouse', NULL, 'Ключ, открывающий дверь Склада в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'A key that opens the door of the Storage in the Saint\'s chambers. Having the key allows you to enter and exit the enclosed room.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (17225, 'Key to the Armory', NULL, 'Ключ, открывающий дверь Оружейной в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'A key that opens the door of the Armory in the Saint\'s chambers. Having the key allows you to enter and exit the enclosed room.', 'etc_old_key_i01', 0);
INSERT INTO `all_items` VALUES (17226, 'Elcadia\'s Mark', NULL, 'Магический рунный знак, необходимый для испытания Элькардии.', 'A magical rune sign required for Elcardia\'s trial.', 'etc_fire_mantra_i00', 0);
INSERT INTO `all_items` VALUES (17227, 'Elcadia\'s Token', NULL, 'Магический рунный знак, необходимый для испытания Элькардии.', 'A magical rune sign required for Elcardia\'s trial.', 'etc_fire_rune_i00', 0);
INSERT INTO `all_items` VALUES (17228, 'Scroll of Abstinence', NULL, 'Магический свиток, найденный в покоях Святой. Излучает странную энергию, хотя выглядит очень древним и ветхим.', 'A magical scroll found in the Saint\'s chambers. Emits a strange energy, although it looks very ancient and dilapidated.', 'etc_spell_books_element_i00', 0);
INSERT INTO `all_items` VALUES (17229, 'Shield of Sacrifice', NULL, 'Щит, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'A shield found in the Saint\'s chambers. Emits a strange energy, although it is old and unusable.', 'shield_shrnoens_shield_i00', 0);
INSERT INTO `all_items` VALUES (17230, 'Sword of Holy Spirit', NULL, 'Меч, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'A sword found in the Saint\'s chambers. Emits a strange energy, although it is old and unusable.', 'weapon_raid_sword_i01', 0);
INSERT INTO `all_items` VALUES (17231, 'Staff of Blessing', NULL, 'Посох, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'A staff found in the Saint\'s chambers. Emits a strange energy, although it is old and unusable.', 'weapon_mace_of_prayer_i01', 0);
INSERT INTO `all_items` VALUES (17232, 'Ball Trapping Gnosian Agathion Pack', NULL, 'Упаковка с Браслетом Гасиона с Мячом. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Package containing Gasion with a Ball Bracelet. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17233, 'Ball Trapping Orodriel Agathion Pack', NULL, 'Упаковка с Браслетом Родриэля с Мячом. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Package containing Rodrielle with a Ball Bracelet. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17234, 'Penalty Kick Agathion Pack', NULL, 'Упаковка с Браслетом Пенальти. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'Package containing Penalty Bracelet. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17235, 'World Cup Special Gift', NULL, 'Специальный подарок для празднования Чемпионата мира по футболу. При использовании можно получить разные предметы.', 'A special gift to celebrate the World Cup. Using it grants various items.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17236, 'Gift of Victory Box', NULL, 'Подарочная коробка для празднования победы. При использовании можно получить Голос и Песочные Часы Невитта.', 'A gift box to celebrate victory. Using it grants Voice and Nevit\'s Hourglass.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17237, 'Luxury Gift of Victory Box', NULL, 'Подарочная коробка для празднования победы. При использовании можно получить Голос и Песочные Часы Невитта.', 'A gift box to celebrate victory. Using it grants Voice and Nevit\'s Hourglass.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17238, 'Olympiad Match 3 Participation Certificate', NULL, 'Бумага, доказывающая участие в трех Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить небольшую награду.', 'Paper proving participation in three Olympiad matches. If you bring it to the Olympiad Manager, you can receive a small reward.', 'mercenary_certification_i00', 0);
INSERT INTO `all_items` VALUES (17239, 'Olympiad Match 5 Participation Certificate', NULL, 'Бумага, доказывающая участие в пяти Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить некоторую награду.', 'Paper proving participation in five Olympiad matches. If you bring it to the Olympiad Manager, you can receive some reward.', 'mercenary_certification_i01', 0);
INSERT INTO `all_items` VALUES (17240, 'Olympiad Match 10 Participation Certificate', NULL, 'Бумага, доказывающая участие в десяти Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить внушительную награду.', 'Paper proving participation in ten Olympiad matches. If you bring it to the Olympiad Manager, you can receive a substantial reward.', 'mercenary_certification_i02', 0);
INSERT INTO `all_items` VALUES (17241, 'Olympiad Team Event Certificate', NULL, 'Сертификат, подтверждающий участие в пяти Командных Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Свободной и Классовой Олимпиады, можно получить внушительную награду.', 'Certificate confirming participation in five Team Olympiad matches. Take it to the Olympiad Manager. If you also collect Free and Class Olympiad Certificates, you can receive a substantial reward.', 'scroll_of_verification_i01', 0);
INSERT INTO `all_items` VALUES (17242, 'Olympiad Class-Free Battle Certificate', NULL, 'Сертификат, подтверждающий участие в пяти Свободных Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Командной и Классовой Олимпиады, можно получить внушительную награду.', 'Certificate confirming participation in five Free Olympiad matches. Take it to the Olympiad Manager. If you also collect Team and Class Olympiad Certificates, you can receive a substantial reward.', 'scroll_of_verification_i03', 0);
INSERT INTO `all_items` VALUES (17243, 'Olympiad Class Battle Certificate', NULL, 'Сертификат, подтверждающий участие в пяти Классовых Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Свободной и Командной Олимпиады, можно получить внушительную награду.', 'Certificate confirming participation in five Class Olympiad matches. Take it to the Olympiad Manager. If you also collect Free and Team Olympiad Certificates, you can receive a substantial reward.', 'scroll_of_verification_i00', 0);
INSERT INTO `all_items` VALUES (17244, 'Olympiad 2 Consecutive Wins Confirmation', NULL, 'Бумага, доказывающая победу в двух Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить небольшую награду.', 'Paper proving victory in two consecutive Olympiad matches. If you bring it to the Olympiad Manager, you can receive a small reward.', 'etc_charm_of_courage_i01', 0);
INSERT INTO `all_items` VALUES (17245, 'Olympiad 5 Consecutive Wins Confirmation', NULL, 'Бумага, доказывающая победу в пяти Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить некоторую награду.', 'Paper proving victory in five consecutive Olympiad matches. If you bring it to the Olympiad Manager, you can receive some reward.', 'etc_charm_of_courage_i02', 0);
INSERT INTO `all_items` VALUES (17246, 'Olympiad 10 Consecutive Wins Confirmation', NULL, 'Бумага, доказывающая победу в десяти Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить внушительную награду.', 'Paper proving victory in ten consecutive Olympiad matches. If you bring it to the Olympiad Manager, you can receive a substantial reward.', 'etc_charm_of_courage_i03', 0);
INSERT INTO `all_items` VALUES (17248, 'Large Dragon Bone', NULL, 'Позволяет призывать особых чудовищ в специальной точке Долины Драконов. Нельзя использовать, если чудовище уже находится на своем месте.', 'Allows summoning special monsters at a specific point in the Dragon Valley. Cannot be used if the monster is already in place.', 'big_dragon_bone_summon', 0);
INSERT INTO `all_items` VALUES (17249, 'Large Dragon Skull', NULL, 'Останки особого чудовища из Долины Драконов. Добыв останки у семи разных драконов, отнесите их Гильмору.', 'Remains of a special monster from the Dragon Valley. After obtaining remains from seven different dragons, take them to Gilmore.', 'etc_fang_red_i00', 0);
INSERT INTO `all_items` VALUES (17250, 'Large Baby Dragon', NULL, 'Зуб особого чудовища из Долины Драконов. Возьмите зуб и отнесите его находящемуся в Долине Драконов Неприкаянному Духу.', 'Tooth of a special monster from the Dragon Valley. Take the tooth and deliver it to the Wandering Spirit located in the Dragon Valley.', 'etc_claw_i00', 0);
INSERT INTO `all_items` VALUES (17251, 'Drake Lord\'s Essence', NULL, 'Эссенция Повелителя Дрейков. Отнесите ее Теодрику.', 'Drake Lord Essence. Take it to Theodric.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (17252, 'Behemoth Leader\'s Essence', NULL, 'Эссенция Главы Бехимосов. Отнесите ее Теодрику.', 'Behemoth Leader Essence. Take it to Theodric.', 'etc_crystal_green_i00', 0);
INSERT INTO `all_items` VALUES (17253, 'Dragon Beast\'s Essence', NULL, 'Эссенция Чудовищного Дракона. Отнесите ее Теодрику.', 'Monstrous Dragon Essence. Take it to Theodric.', 'etc_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (17254, 'Box of Theodric', NULL, 'Старинный ящик. Внутри что-то есть.', 'An old box. There is something inside.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (17255, 'Blessed Scroll: Enchant Weapon (A-Grade)', 'Event', 'Для модификации оружия Ранга A. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов и древкового оружия на 4, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов – на 5, а луков – на 8. Увеличивает Маг. Атк. всех типов оружия на 3. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'For enchanting A-grade weapons. Increases P. Atk. of one-handed swords, one-handed blunts, daggers, and polearms by 4, two-handed swords, two-handed blunts, dual swords, and fist weapons by 5, and bows by 8. Increases M. Atk. of all weapon types by 3. When enchanted to +4 or higher, provides additional doubling bonuses to P. Atk./M. Atk. Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0.', 'etc_blessed_scrl_of_ench_wp_a_i04', 21);
INSERT INTO `all_items` VALUES (17256, 'Blessed Scroll: Enchant Armor (A-Grade)', 'Event', 'Увеличивает Физ. Защ. брони и аксессуаров ранга А на 1. При модификации на +4 и выше Физ. Защ. будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'Increases P. Def. of A-grade armor and accessories by 1. When enchanted to +4 or higher, P. Def. increases by 3. Safe enchantment up to +3 (full body armor +4). Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0. When armor is enchanted to +4 or higher, HP also increases according to the enchantment value.', 'etc_blessed_scrl_of_ench_am_a_i04', 22);
INSERT INTO `all_items` VALUES (17257, 'Blessed Scroll: Enchant Weapon (B-Grade)', 'Event', 'Для модификации оружия Ранга B. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов и древкового оружия на 3, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов – на 4, а луков – на 6. Увеличивает Маг. Атк. всех типов оружия на 3. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'For enchanting B-grade weapons. Increases P. Atk. of one-handed swords, one-handed blunts, daggers, and polearms by 3, two-handed swords, two-handed blunts, dual swords, and fist weapons by 4, and bows by 6. Increases M. Atk. of all weapon types by 3. When enchanted to +4 or higher, provides additional doubling bonuses to P. Atk./M. Atk. Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0.', 'etc_blessed_scrl_of_ench_wp_b_i03', 21);
INSERT INTO `all_items` VALUES (17258, 'Blessed Scroll: Enchant Armor (B-Grade)', 'Event', 'Увеличивает Физ. Защ. Брони и аксессуаров ранга В на 1. При модификации на +4 и выше Физ. Защ. Будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'Increases P. Def. of B-grade armor and accessories by 1. When enchanted to +4 or higher, P. Def. increases by 3. Safe enchantment up to +3 (full body armor +4). Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0. When armor is enchanted to +4 or higher, HP also increases according to the enchantment value.', 'etc_blessed_scrl_of_ench_am_b_i03', 22);
INSERT INTO `all_items` VALUES (17259, 'Blessed Scroll: Enchant Weapon (C-Grade)', 'Event', 'Для модификации оружия Ранга С. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов и древкового оружия на 3, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов – на 4, а луков – на 6. Увеличивает Маг. Атк. всех типов оружия на 3. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'For enchanting C-grade weapons. Increases P. Atk. of one-handed swords, one-handed blunts, daggers, and polearms by 3, two-handed swords, two-handed blunts, dual swords, and fist weapons by 4, and bows by 6. Increases M. Atk. of all weapon types by 3. When enchanted to +4 or higher, provides additional doubling bonuses to P. Atk./M. Atk. Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0.', 'etc_blessed_scrl_of_ench_wp_c_i02', 21);
INSERT INTO `all_items` VALUES (17260, 'Blessed Scroll: Enchant Armor (C-Grade)', 'Event', 'Увеличивает Физ. Защ. Брони и аксессуаров ранга С на 1. При модификации на +4 и выше Физ. Защ. Будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'Increases P. Def. of C-grade armor and accessories by 1. When enchanted to +4 or higher, P. Def. increases by 3. Safe enchantment up to +3 (full body armor +4). Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0. When armor is enchanted to +4 or higher, HP also increases according to the enchantment value.', 'etc_blessed_scrl_of_ench_am_c_i02', 22);
INSERT INTO `all_items` VALUES (17261, 'Blessed Scroll: Enchant Weapon (D-Grade)', 'Event', 'Ранг D. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов, древкового оружия, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов на 2, а луков – на 4. Увеличивает Маг. Атк. всех типов оружия на 2. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'Grade D. Increases P. Atk. of one-handed swords, one-handed blunts, daggers, polearms, two-handed swords, two-handed blunts, dual swords, and fist weapons by 2, and bows by 4. Increases M. Atk. of all weapon types by 2. When enchanted to +4 or higher, provides additional doubling bonuses to P. Atk./M. Atk. Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0.', 'etc_blessed_scrl_of_ench_wp_d_i01', 21);
INSERT INTO `all_items` VALUES (17262, 'Blessed Scroll: Enchant Armor (D-Grade)', 'Event', 'Увеличивает Физ. Защ. Брони и аксессуаров ранга D на 1. При модификации на +4 и выше Физ. Защ. Будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'Increases P. Def. of D-grade armor and accessories by 1. When enchanted to +4 or higher, P. Def. increases by 3. Safe enchantment up to +3 (full body armor +4). Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0. When armor is enchanted to +4 or higher, HP also increases according to the enchantment value.', 'etc_blessed_scrl_of_ench_am_d_i01', 22);
INSERT INTO `all_items` VALUES (17263, 'Blessed Scroll: Enchant Weapon (S-Grade)', 'Event', 'Для модификации оружия Ранга S. Одноручный меч, одноручное дробящее, кинжал, древковое: Физ. Атк. +5. Двуручный меч, двуручное дробящее, парные клинки, кастеты: Физ. Атк. +6. Луки: Физ. Атк +10. Все оружие: Маг. Атк. +4. При модификации на +4 и выше бонус к Физ. Атк. и Маг. Атк. удваивается. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'For enchanting S-grade weapons. One-handed sword, one-handed blunt, dagger, polearm: P. Atk. +5. Two-handed sword, two-handed blunt, dual swords, fist weapons: P. Atk. +6. Bows: P. Atk. +10. All weapons: M. Atk. +4. When enchanted to +4 or higher, the bonus to P. Atk. and M. Atk. is doubled. Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0.', 'etc_blessed_scrl_of_ench_wp_s_i05', 21);
INSERT INTO `all_items` VALUES (17264, 'Blessed Scroll: Enchant Armor (S-Grade)', 'Event', 'Увеличивает Физ. Защ. Брони и аксессуаров ранга S на 1. При модификации на +4 и выше Физ. Защ. Будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'Increases P. Def. of S-grade armor and accessories by 1. When enchanted to +4 or higher, P. Def. increases by 3. Safe enchantment up to +3 (full body armor +4). Upon failed enchantment, the item does not shatter into crystals, but its enchantment level drops to 0. When armor is enchanted to +4 or higher, HP also increases according to the enchantment value.', 'etc_blessed_scrl_of_ench_am_s_i05', 22);
INSERT INTO `all_items` VALUES (17265, 'Certificate of Dawn', NULL, 'Доказательство принадлежности к Ордену Рассвета, выданное Францем. У жреца Уда его можно обменять на свиток, позволяющий забыть профессию, выученную на 81 уровне.', 'Proof of belonging to the Dawn order, issued by Franz. Can be exchanged with Priest Wood for a scroll that allows you to forget a profession learned at level 81.', 'etc_charm_of_courage_i05', 0);
INSERT INTO `all_items` VALUES (17266, 'Will of Antharas', NULL, 'Один из камней, созданный Антарасом. Чтобы подчинять своей воле могущественных монстров, Антарас вживляет такие камни в их сердца, после чего постоянно за ними наблюдает.', 'One of the stones created by Antharas. To bend powerful monsters to his will, Antharas implants such stones into their hearts and then constantly monitors them.', 'etc_unholy_potion_i00', 0);
INSERT INTO `all_items` VALUES (17267, 'Sealed Blood Crystal', NULL, 'Яд из крови, пролитой Антарасом, заразил окружающую зону, а кровь, которая осталась после фильтрации ее от токсинов, за долгие годы кристаллизовалась.', 'Poison from the blood spilled by Antharas has infected the surrounding area, and the blood remaining after filtering out toxins has crystallized over many years.', 'etc_powder_red_i00', 0);
INSERT INTO `all_items` VALUES (17268, 'Antharas Blood Crystal', NULL, 'Используя силу Антараса, воскрешают всех погибших союзников. Могут использоваться только в Гнезде Антараса. Могут использоваться максимум 1 раз в час.', 'Using Antharas\'s power, resurrects all fallen allies. Can only be used in Antharas\' Lair. Can be used a maximum of once per hour.', 'etc_fire_crystal_1_i00', 3);
INSERT INTO `all_items` VALUES (17269, 'Agathion Seal Bracelet - Antharas', NULL, 'Браслет, призывающий милого Агатиона Антараса. Нельзя обменять/выбросить.', 'Bracelet that summons a cute Agathion - Antharas. Cannot be exchanged or dropped.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (17270, 'Agathion Seal Bracelet - Nevit\'s Messenger Kanna', NULL, 'Браслет, призывающий Агатиона Герольда Невитта Канну. Нельзя обменять/выбросить.', 'Bracelet summoning Agathion Herald Canna of Nevit. Cannot be traded or dropped.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (17271, 'Agathion Seal Bracelet - Guardian of the Dawn Kallesin', NULL, 'Браслет, призывающий Агатиона Хранителя Рассвета Калесина. Нельзя обменять/выбросить.', 'Bracelet that summons an Agathion - Guardian of the Dawn Kallesin. Cannot be exchanged or dropped.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (17272, 'Antharas Agathion PAck', NULL, 'Особый подарок в ознаменование завоевания Долины Драконов. При использовании можно получить Браслет Печати Агатиона Антараса', 'A special gift commemorating the conquest of Dragon Valley. Using it grants an Antharas Agathion Seal Bracelet.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17273, 'Nevit\'s Messenger Kanna Agathion Pack', NULL, 'Особый подарок в ознаменование завершения квеста Семи Печатей. При использовании можно получить Браслет Печати Агатиона Герольда Невитта Канны.', 'A special gift commemorating the completion of the Seven Signs quest. Using it grants a Herald Canna of Nevit Agathion Seal Bracelet.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17274, 'Guardian of the Dawn Kallesin Agathion Pack', NULL, 'Особый подарок в ознаменование завершения квеста Семи Печатей. При использовании можно получить Браслет Печати Агатиона Хранителя Рассвета Калесина.', 'A special gift commemorating the completion of the Seven Signs quest. Using it grants a Guardian of Dawn Kalesin Agathion Seal Bracelet.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17275, 'Strider Pet Exchange Coupon', NULL, 'Справка, подтверждающая право на получение Питомца Ездового Дракона, которую можно обменять на Питомца Ездового Дракона через Ленту Новостей.', 'A certificate confirming the right to obtain a Strider mount, which can be exchanged for a Strider via the News Feed.', 'etc_ticket_i00', 0);
INSERT INTO `all_items` VALUES (17276, '5,000,000 SP scroll', NULL, '5 000 000 свитков восстановления SP.', '5,000,000 SP recovery scrolls.', 'etc_sp_scroll3_i00', 1);
INSERT INTO `all_items` VALUES (17277, '100,000,000 SP scroll', NULL, '10 000 000 свитков восстановления SP.', '10,000,000 SP recovery scrolls.', 'etc_sp_scroll3_i00', 1);
INSERT INTO `all_items` VALUES (17278, 'Strider Pet Exchange Pack', NULL, 'Витаминная упаковка. Упаковка, содержащая Купон на Ездового Дракона. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Vitality Package. Package containing a Strider Coupon. Cannot be traded, dropped, or destroyed. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17279, 'Transformation Scroll: Anakim Pack', NULL, 'Подарочный ящик, содержащий 1 Свиток Трансформации Анаким. При использовании можно получить Свиток Трансформации в Анакима. Нельзя обменять, выбросить или уничтожить.', 'Gift box containing 1 Anakim Transformation Scroll. Using it grants an Anakim Transformation Scroll. Cannot be traded, dropped, or destroyed.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17280, 'Transformation Sealbook: Anakim Pack', NULL, 'Подарочный ящик, содержащий 1 Книгу Трансформации в Анаким. При использовании можно получить Книгу Трансформации – Анаким. Нельзя обменять, выбросить или уничтожить.', 'Gift box containing 1 Anakim Transformation Book. Using it grants an Anakim Transformation Book. Cannot be traded, dropped, or destroyed.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17281, 'Delivery Box', NULL, 'Ящик, который попросил доставить Изаэль Серебряная Тень из Деревни Охотников. Отнесите его в Долину Драконов Торговцу Долины Китске.', 'A box that Yitzhak Silver Shadow asked to be delivered from the Hunter\'s Village. Take it to Valley Trader Kitska in Dragon Valley.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (17282, '2010 Summer Special Pack', NULL, 'Витаминная упаковкаПодарочный ящик, содержащий Песочные Часы Невитта, Свежий Ветер Фреи и Ледяную Шапку-Арбуз. Нельзя обменять или выбросить. Можно положить в личное хранилище.', 'Vitality Package. Gift box containing Nevit\'s Hourglass, Freya\'s Fresh Wind, and Ice Watermelon Cap. Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17283, 'Nevit\'s Hourglass - 4 hour', NULL, 'Витаминный предметПесочные Часы, увеличивающие время действия Благословения Невитта на 4 часа, можно использовать независимо от уровня, Нельзя обменять/выбросить/уничтожить. Можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов', 'Vitality item. Hourglass that increases Nevit\'s Blessing duration by 4 hours, usable regardless of level. Cannot be traded, dropped, or destroyed. Can be shared among characters within the account via the Vitamin Manager.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17284, 'Nevit\'s Hourglass - 4 hour', 'Event', 'Витаминный предметПесочные Часы, увеличивающие время действия Благословения Невитта на 4 часа, можно использовать независимо от уровня, Нельзя обменять/выбросить. Можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов', 'Vitality item. Hourglass that increases Nevit\'s Blessing duration by 4 hours, usable regardless of level. Cannot be traded or dropped. Can be shared among characters within the account via the Vitamin Manager.', 'etc_dragons_blood_i03', 3);
INSERT INTO `all_items` VALUES (17285, 'Freya\'s Refreshing Breeze', NULL, 'Витаминный предметПри использовании  восстанавливает энергию в течение 4 часов. Эффект не суммируется с \"Радостью Дня Рождения\". Нельзя обменять/выбросить. Можно положить в личное хранилище.', 'Vitality item. When used, restores energy over 4 hours. The effect does not stack with \"Birthday Joy\". Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'etc_hot_spring_mineral_i00', 3);
INSERT INTO `all_items` VALUES (17286, 'Freya\'s Refreshing Breeze', 'Event', 'Витаминный предметПри использовании  восстанавливает энергию в течение 4 часов. Эффект не суммируется с \"Радостью Дня Рождения\". Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Vitality item. When used, restores energy over 4 hours. The effect does not stack with \"Birthday Joy\". Cannot be traded, dropped, or destroyed. Can be deposited into a personal warehouse.', 'etc_hot_spring_mineral_i00', 3);
INSERT INTO `all_items` VALUES (17287, '2010 Summer Special Pack', 'Event', 'Витаминная упаковкаПодарочный ящик, содержащий Песочные Часы Невитта, Свежий Ветер Фреи и Ледяную Шапку-Арбуз. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Vitality Package. Gift box containing Nevit\'s Hourglass, Freya\'s Fresh Wind, and Ice Watermelon Cap. Cannot be traded, dropped, or destroyed. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (17288, 'Ice Watermelon Hat', 'Event', 'Витаминный предметШапка в форме арбуза. При одном взгляде на нее чувствуется свежесть. Требует две ячейки головных уборов. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Event	Dimensional ItemnHat that looks like a watermelon. Just looking at it is refreshing. Uses 2 hair accessory slots. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'BranchSys.br_watermelon_cap_a_i00', 0);
INSERT INTO `all_items` VALUES (17289, 'Ice Watermelon Hat', NULL, 'Витаминный предметnШапка в форме арбуза. При одном взгляде на нее чувствуется свежесть. Требует две ячейки головных уборов. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'Dimensional ItemnHat that looks like a watermelon. Just looking at it is refreshing. Uses 2 hair accessory slots. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'BranchSys.br_watermelon_cap_a_i00', 0);
INSERT INTO `all_items` VALUES (20000, 'Spicy Kimchee', NULL, 'Ивентовый предметУдивительное Кимчи, увеличивающее Скор. Восстановления. Эффект 1.', 'Event item. Amazing Kimchi, increases Recovery Spd. Effect 1.', 'BranchSys.etc_kimchi_power_i00', 0);
INSERT INTO `all_items` VALUES (20001, 'Spicy Kimchee', NULL, 'Ивентовый предметУдивительное Кимчи, увеличивающее Скор. Восстановления и Ур. Атаки. Эффект 2.', 'Event item. Amazing Kimchi, increases Recovery Spd. and Atk. Lvl. Effect 2.', 'BranchSys.etc_kimchi_power_i00', 0);
INSERT INTO `all_items` VALUES (20002, 'Spicy Kimchee', NULL, 'Ивентовый предметУдивительное Кимчи, увеличивающее Скор. Восстановления, Ур. и Скор. Атаки. Эффект 3.', 'Event item. Amazing Kimchi, increases Recovery Spd., Atk. Lvl., and Atk. Spd. Effect 3.', 'BranchSys.etc_kimchi_power_i00', 0);
INSERT INTO `all_items` VALUES (20003, 'Sweet-and-Sour White Kimchee', NULL, 'Ивентовый предметВолшебное Кимчи, увеличивающее действие Острого Кимчи на 5 мин.', 'Event item. Magic Kimchi, extends the duration of Spicy Kimchi by 5 min.', 'BranchSys.etc_kimchi_time_i00', 0);
INSERT INTO `all_items` VALUES (20004, 'Vitality Ginseng', NULL, 'Ивентовый предметПри получении Опыта восстанавливается энергия.', 'Event item. Energy is restored when gaining EXP.', 'BranchSys.etc_ginseng_recovery_i00', 0);
INSERT INTO `all_items` VALUES (20006, 'Agathion Seal Bracelet - Majo', NULL, 'Браслет, призывающий Агатиона Майо. Нельзя обменять/выбросить.', 'Bracelet summoning Agathion Mayo. Cannot be traded or dropped.', 'BranchSys.br_bracelet_aga_mazu_i00', 0);
INSERT INTO `all_items` VALUES (20007, 'Agathion Seal Bracelet - Gold Majo', NULL, 'Браслет, призывающий Золотого Агатиона. Нельзя обменять/выбросить.', 'Bracelet summoning Golden Agathion. Cannot be traded or dropped.', 'BranchSys.br_bracelet_aga_mazu_i00', 0);
