INSERT INTO `all_items` VALUES (20016, 'Horn-Rimmed Glasses', 'Agility', 'Волшебные Очки в роговой оправе. Нельзя обменять/выбросить.', 'Magic horn-rimmed glasses. Cannot be traded or dropped.', 'BranchSys.br_Eye_Glasses_i00', 0);
INSERT INTO `all_items` VALUES (20017, 'Afro Hair', NULL, 'Парик в афроамериканском стиле. Требует две ячейки головных уборов.', 'African-style afro wig. Requires two hair accessory slots.', 'BranchSys.br_Afro_hair_i00', 0);
