INSERT INTO `all_items` VALUES (20020, 'Uniform Hat', NULL, 'Очень стильный головной убор. Требует две ячейки головных уборов.', 'A very stylish headwear. Requires two hair accessory slots.', 'BranchSys.br_Uniform_Hat_i00', 0);
INSERT INTO `all_items` VALUES (20021, 'Assassin\'s Bamboo Hat', NULL, 'Шляпа, изготовленная из бамбука. Требует две ячейки головных уборов.', 'Hat made of bamboo. Requires two hair accessory slots.', 'BranchSys.br_Bamboo_Hat_i00', 0);
