INSERT INTO `all_items` VALUES (20023, 'Ribbon Hairband', NULL, 'Головной аксессуар в виде банта. Только для персонажей женского пола.', 'A bow-shaped hair accessory. For female characters only.', 'BranchSys.br_Ribbon_i00', 0);
