INSERT INTO `all_items` VALUES (20026, 'Extra Entrance Pass - Kamaloka (Hall of the Abyss)', NULL, 'Билет для входа в Камалоку (Зал Бездны). Снимает ограничение на вход при использовании. Позволяет попасть в Зал Бездны один раз.', 'Kamaloka (Hall of the Abyss) entry ticket. Removes the entry restriction when used. Grants access to the Hall of the Abyss once.', 'ticket_i00', 0);
