INSERT INTO `all_items` VALUES (20097, 'Mysterious Formal Dress (Event) Pack', NULL, 'Можно получить волшебное одеяние. Нельзя обменять/выбросить/продать.', 'Grants magic robes. Cannot be traded, dropped, or sold.', 'BranchSys.br_mysterious_wedding_i00', 0);
INSERT INTO `all_items` VALUES (20098, 'Formal Dress (Event)', '1 hour Shadow time', 'Удивительное одеяние, превращающееся в мужской смокинг или свадебное платье, в зависимости от того, кто его одел. Заменяет доспехи. Нельзя обменять/выбросить/продать.', 'An amazing robe that transforms into a men\'s tuxedo or wedding dress depending on who wears it. Replaces armor. Cannot be traded, dropped, or sold.', 'armor_t2000_ul_i00', 0);
INSERT INTO `all_items` VALUES (20099, 'Formal Dress (Event)', '7-day limited period', 'Удивительное одеяние, превращающееся в мужской смокинг или свадебное платье, в зависимости от того, кто его одел. Заменяет доспехи. Нельзя обменять/выбросить/продать.', 'An amazing robe that transforms into a men\'s tuxedo or wedding dress depending on who wears it. Replaces armor. Cannot be traded, dropped, or sold.', 'armor_t2000_ul_i00', 0);
INSERT INTO `all_items` VALUES (20100, 'Saving Santa Hat', '24-hour limited period', 'Шапка Санта Клауса, изготовленная для этого святого праздника. Можно сыграть в игру \"Камень-ножницы-бумага\". Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать/отдать в хранилище.', 'Santa\'s Hat made for this holy holiday. Allows playing Rock-Paper-Scissors. Requires two hair accessory slots. Cannot be traded, dropped, sold, or deposited into a warehouse.', 'BranchSys.br_xmas_gawibawibo_cap_i00', 0);
INSERT INTO `all_items` VALUES (20101, 'Santa Claus\' Gift Set', NULL, 'Комплект подарков, подаренных Санта Клаусом. Можно получить различные подарки.', 'Set of gifts given by Santa Claus. Grants various gifts.', 'BranchSys.br_xmas_present_i00', 0);
