INSERT INTO `all_items` VALUES (20190, 'Premium Valentine Decoration', '15-day limited period', 'Если отнести это вместе с Совершенным Тортом Валентина Посланнице Любви, Королеве Янь, то возможно завершить Фантастический Торт Валентина.  Нельзя обменять/выбросить/продать.', 'If you take this along with the Perfect Valentine Cake to Love Envoy Queen Yan, you can complete the Fantastic Valentine Cake. Cannot be traded, dropped, or sold.', 'BranchSys.br_valentine_deco_i00', 0);
INSERT INTO `all_items` VALUES (20191, 'Valentine Cake Recipe', NULL, 'Рецепт на изготовление Торта Валентина. Нельзя обменять/выбросить/продать.', 'Recipe for crafting Valentine Cake. Cannot be traded, dropped, or sold.', 'BranchSys.br_valentine_recipe_i00', 5);
INSERT INTO `all_items` VALUES (20192, 'Valentine Dark Chocolate', NULL, 'Необходимые ингредиенты для приготовления Торта Валентина.', 'Required ingredients for making Valentine Cake.', 'BranchSys.br_valentine_darkchoco_i00', 0);
INSERT INTO `all_items` VALUES (20193, 'Valentine White Chocolate', NULL, 'Необходимые ингредиенты для приготовления Торта Валентина.', 'Required ingredients for making Valentine Cake.', 'BranchSys.br_valentine_whitechoco_i00', 0);
INSERT INTO `all_items` VALUES (20194, 'Valentine Fresh Cream', NULL, 'Необходимые ингредиенты для приготовления Торта Валентина.', 'Required ingredients for making Valentine Cake.', 'BranchSys.br_valentine_cream_i00', 0);
INSERT INTO `all_items` VALUES (20195, 'Simple Valentine Cake', NULL, 'Еще не готовый Торт Валентина. Если добавить еще несколько ингредиентов, получится Обычный Торт Валентина.', 'Unfinished Valentine Cake. Adding a few more ingredients will yield a Regular Valentine Cake.', 'BranchSys.br_valentine_cake_1_i00', 0);
INSERT INTO `all_items` VALUES (20196, 'Velvety Valentine Cake', NULL, 'Немного готовый Торт Валентина. Если добавить еще несколько ингредиентов, получится Вкусный Торт Валентина.', 'Partially prepared Valentine Cake. Adding a few more ingredients will yield a Delicious Valentine Cake.', 'BranchSys.br_valentine_cake_2_i00', 0);
INSERT INTO `all_items` VALUES (20197, 'Delectable Valentine Cake', NULL, 'Почти готовый Торт Валентина. Если добавить еще несколько ингредиентов, получится  Совершенный Торт Валентина.', 'Almost finished Valentine Cake. Adding a few more ingredients will yield a Perfect Valentine Cake.', 'BranchSys.br_valentine_cake_3_i00', 0);
INSERT INTO `all_items` VALUES (20198, 'Decadent Valentine Cake', NULL, 'Совершенный Торт Валентина. Если отнести его и Декорации Валентина Посланнице Любви, Королеве Янь, он станет Фантастическим Тортом Валентина.', 'Perfect Valentine Cake. If you take it along with Valentine Decorations to Love Envoy Queen Yan, it will become a Fantastic Valentine Cake.', 'BranchSys.br_valentine_cake_4_i00', 0);
INSERT INTO `all_items` VALUES (20199, 'Heavenly Valentine Cake', '30-day limited period', 'Торт Валентина, с мистической силой, полученный от Посланницы Любви, Королевы Янь. Нельзя обменять/выбросить/продать.', 'Valentine Cake imbued with mystical power, obtained from Love Envoy Queen Yan. Cannot be traded, dropped, or sold.', 'BranchSys.br_valentine_cake_5_i00', 0);
INSERT INTO `all_items` VALUES (20200, 'Agathion of Love', '3-day limited period', 'Браслет, с помощью которого возможно призвать Агатиона Любви. Нельзя обменять/выбросить/продать. Задержка на использование Особого Умения: 12 ч.', 'Bracelet used to summon Love Agathion. Cannot be traded, dropped, or sold. Special skill reuse delay: 12 hours.', 'etc_rbracelet_aga_agit_i00', 0);
INSERT INTO `all_items` VALUES (20201, 'Agathion of Love', '7-day limited period', 'Браслет, с помощью которого возможно призвать Агатиона Любви. Нельзя обменять/выбросить/продать. Задержка на использование Особого Умения: 12 ч.', 'Bracelet used to summon Love Agathion. Cannot be traded, dropped, or sold. Special skill reuse delay: 12 hours.', 'etc_rbracelet_aga_agit_i00', 0);
