INSERT INTO `all_items` VALUES (20204, 'Queen Ant\'s Ring (Event)', '3-day limited period', 'Ивентовое Кольцо Королевы Муравьев. Увеличивает: MP+21, Сопротивление Яду + 30%, Шанс Атаки Ядом +30%, повышает Точность и урон от Крит. Атк., увеличивает Сопротивление Обездвиживанию +20% и Шанс Обездвиживающей Атаки +20%. Даже если носить 2 одинаковых кольца, эффект будет исходить только от одного. Нельзя обменять/выбросить/продать.', 'Event Ring of Queen Ant. Increases: MP +21, Poison resistance +30%, Poison attack chance +30%, increases Accuracy and Critical damage, increases Root resistance +20% and Root attack chance +20%. Even if you wear 2 identical rings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_ring_of_queen_ant_i00', 0);
INSERT INTO `all_items` VALUES (20205, 'Queen Ant\'s Ring (Event)', '7-day limited period', 'Ивентовое Кольцо Королевы Муравьев. Увеличивает: MP+21, Сопротивление Яду + 30%, Шанс Атаки Ядом +30%, повышает Точность и урон от Крит. Атк., увеличивает Сопротивление Обездвиживанию +20% и Шанс Обездвиживающей Атаки +20%. Даже если носить 2 одинаковых кольца, эффект будет исходить только от одного. Нельзя обменять/выбросить/продать.', 'Event Ring of Queen Ant. Increases: MP +21, Poison resistance +30%, Poison attack chance +30%, increases Accuracy and Critical damage, increases Root resistance +20% and Root attack chance +20%. Even if you wear 2 identical rings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_ring_of_queen_ant_i00', 0);
INSERT INTO `all_items` VALUES (20206, 'Queen Ant\'s Ring (Event)', '15-day limited period', 'Ивентовое Кольцо Королевы Муравьев. Увеличивает: MP+21, Сопротивление Яду + 30%, Шанс Атаки Ядом +30%, повышает Точность и урон от Крит. Атк., увеличивает Сопротивление Обездвиживанию +20% и Шанс Обездвиживающей Атаки +20%. Даже если носить 2 одинаковых кольца, эффект будет исходить только от одного. Нельзя обменять/выбросить/продать.', 'Event Ring of Queen Ant. Increases: MP +21, Poison resistance +30%, Poison attack chance +30%, increases Accuracy and Critical damage, increases Root resistance +20% and Root attack chance +20%. Even if you wear 2 identical rings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_ring_of_queen_ant_i00', 0);
INSERT INTO `all_items` VALUES (20207, 'Earring of Zaken (Event)', '3-day limited period', 'Ивентовая Серьга Закена. Увеличивает MP+31, Сопротивление Кровотечению +30%, Шанс Атаки Кровотечением +30%, Эффективность Лечения, придает Ярость Вампира, повышает Сопротивление Шоковым и Ментальным Атакам +20% и Шанс нанесения Шоковых и Ментальных Атак +20%. Даже если носить 2 серьги, эффект будет исходить только от одной. Нельзя обменять/выбросить/продать.', 'Event Zaken\'s Earring. Increases MP +31, Bleed resistance +30%, Bleed attack chance +30%, Heal effectiveness, grants Vampiric Rage, increases Stun and Mental attack resistance +20% and Stun and Mental attack chance +20%. Even if you wear 2 earrings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_earring_of_zaken_i00', 0);
INSERT INTO `all_items` VALUES (20208, 'Earring of Zaken (Event)', '7-day limited period', 'Ивентовая Серьга Закена. Увеличивает MP+31, Сопротивление Кровотечению +30%, Шанс Атаки Кровотечением +30%, Эффективность Лечения, придает Ярость Вампира, повышает Сопротивление Шоковым и Ментальным Атакам +20% и Шанс нанесения Шоковых и Ментальных Атак +20%. Даже если носить 2 серьги, эффект будет исходить только от одной. Нельзя обменять/выбросить/продать.', 'Event Zaken\'s Earring. Increases MP +31, Bleed resistance +30%, Bleed attack chance +30%, Heal effectiveness, grants Vampiric Rage, increases Stun and Mental attack resistance +20% and Stun and Mental attack chance +20%. Even if you wear 2 earrings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_earring_of_zaken_i00', 0);
INSERT INTO `all_items` VALUES (20209, 'Earring of Zaken (Event)', '15-day limited period', 'Ивентовая Серьга Закена. Увеличивает MP+31, Сопротивление Кровотечению +30%, Шанс Атаки Кровотечением +30%, Эффективность Лечения, придает Ярость Вампира, повышает Сопротивление Шоковым и Ментальным Атакам +20% и Шанс нанесения Шоковых и Ментальных Атак +20%. Даже если носить 2 серьги, эффект будет исходить только от одной. Нельзя обменять/выбросить/продать.', 'Event Zaken\'s Earring. Increases MP +31, Bleed resistance +30%, Bleed attack chance +30%, Heal effectiveness, grants Vampiric Rage, increases Stun and Mental attack resistance +20% and Stun and Mental attack chance +20%. Even if you wear 2 earrings, the effect will only apply from one. Cannot be traded, dropped, or sold.', 'accessory_earring_of_zaken_i00', 0);
