INSERT INTO `all_items` VALUES (20316, 'Napoleon Hat Pack', NULL, 'Упаковка со Шляпой Наполеона. Нельзя обменять/выбросить.', 'Package with Napoleon Hat. Cannot be traded or dropped.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20317, 'Horn Hairband Pack', NULL, 'Упаковка с Рожками. Только для персонажей женского пола. Нельзя обменять/выбросить.', 'Package with Little Horns. Female characters only. Cannot be traded or dropped.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20318, 'Black Gem Mask Pack', NULL, 'Упаковка с Маской из Черных Камней. Нельзя обменять/выбросить.', 'Package with Black Stone Mask. Cannot be traded or dropped.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20319, 'Plastic Hair Pack', NULL, 'Упаковка с Пластиковым Париком. Нельзя обменять/выбросить.', 'Package with Plastic Wig. Cannot be traded or dropped.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20320, 'Birthday Cake', 'Energy - 24-hour limited period', 'При получении опыта призывает Праздничный Торт, восстанавливающий энергию. Срабатывает только на определенном расстоянии от города. Нельзя обменять/выбросить.', 'When gaining EXP, summons a Holiday Cake that restores Vitality. Triggers only at a certain distance from a town. Cannot be traded or dropped.', 'BranchSys.br_birthday_cake_i00', 3);
INSERT INTO `all_items` VALUES (20321, 'Goggle', NULL, 'Стильные очки, украшенные серебром. Нельзя обменять/выбросить.', 'Stylish glasses decorated with silver. Cannot be traded or dropped.', 'BranchSys.br_goggles_i00', 0);
INSERT INTO `all_items` VALUES (20322, 'Napoleon Hat', NULL, 'Шляпа, которую когда-то носил великий император. Нельзя обменять/выбросить.', 'A hat once worn by a great emperor. Cannot be traded or dropped.', 'BranchSys.br_napoleonic_cap_i00', 0);
INSERT INTO `all_items` VALUES (20323, 'Horn Hairband', NULL, 'Головное украшение розового цвета с миловидными рожками. Только для персонажей женского пола. Нельзя обменять/выбросить.', 'A pink head accessory with cute horns. Female characters only. Cannot be traded or dropped.', 'BranchSys.br_horn_hairband_i00', 0);
INSERT INTO `all_items` VALUES (20324, 'Black Gem Mask', NULL, 'Маска, сделанная из Черных Камней. Нельзя обменять/выбросить.', 'A mask made of Black Stones. Cannot be traded or dropped.', 'BranchSys.br_black_gem_mask_i00', 0);
INSERT INTO `all_items` VALUES (20325, 'Plastic Hair', NULL, 'Пластиковое Украшение. Женское - розового цвета, мужское - синего. Занимает 2 ячейки аксессуаров для головы. Нельзя обменять/выбросить.', 'Plastic Ornament. Female version is pink, male version is blue. Occupies 2 hair accessory slots. Cannot be traded or dropped.', 'BranchSys.br_plastic_hair_f_i00', 0);
INSERT INTO `all_items` VALUES (20326, 'Beast Soulshot Pack', NULL, 'Использовав этот предмет, Вы получите 5 тысяч Зарядов Души Зверя.', 'Using this item grants 5,000 Beast Soulshots.', 'BranchSys.br_box_beast_soul_shot_i00', 0);
INSERT INTO `all_items` VALUES (20327, 'Beast Spiritshot Pack', NULL, 'Использовав этот предмет, Вы получите 5 тысяч Зарядов Духа Зверя.', 'Using this item grants 5,000 Beast Spiritshots.', 'BranchSys.br_box_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20328, 'Blessed Beast Spiritshot Pack', NULL, 'Использовав этот предмет, Вы получите 5 тысяч Благословенных Зарядов Духа Зверя.', 'Using this item grants 5,000 Blessed Beast Spiritshots.', 'BranchSys.br_box_blessed_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20329, 'Beast Soulshot Large Pack', NULL, 'Использовав этот предмет, Вы получите 10 тысяч Зарядов Души Зверя.', 'Using this item grants 10,000 Beast Soulshots.', 'BranchSys.br_box_beast_soul_shot_i00', 0);
INSERT INTO `all_items` VALUES (20330, 'Beast Spiritshot Large Pack', NULL, 'Использовав этот предмет, Вы получите 10 тысяч Зарядов Духа Зверя.', 'Using this item grants 10,000 Beast Spiritshots.', 'BranchSys.br_box_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20331, 'Blessed Beast Spiritshot Large Pack', NULL, 'Использовав этот предмет, Вы получите 10 тысяч Благословенных Зарядов Духа Зверя.', 'Using this item grants 10,000 Blessed Beast Spiritshots.', 'BranchSys.br_box_blessed_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20332, 'Beast Soulshot', NULL, 'Питомец/Слуга наносит более сильный удар противнику. Нельзя обменять/выбросить. Проверить кол-во оставшихся Зарядов Души можно в окне информации о Питомце/Слуге.(Использование из инвентаря хозяина.)', 'Pet/Servant inflicts a more powerful strike on the enemy. Cannot be traded or dropped. The remaining amount of Soulshots can be checked in the Pet/Servant info window. (Used from master\'s inventory.)', 'BranchSys.br_beast_soul_shot_i00', 0);
INSERT INTO `all_items` VALUES (20333, 'Beast Spiritshot', NULL, 'Питомец/Слуга наносит более сильный удар противнику. Нельзя обменять/выбросить. Проверить кол-во оставшихся Зарядов Духа можно в окне информации о Питомце/Слуге.(Использование из инвентаря хозяина.)', 'Pet/Servant inflicts a more powerful strike on the enemy. Cannot be traded or dropped. The remaining amount of Spiritshots can be checked in the Pet/Servant info window. (Used from master\'s inventory.)', 'BranchSys.br_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20334, 'Blessed Beast Spiritshot', NULL, 'Мощность магии Питомца/Слуги увеличивается. Очень легкий предмет. Нельзя обменять/выбросить. Проверить кол-во оставшихся Благословенных Зарядов Духа можно в окне информации о Питомце/Слуге(Использование из инвентаря хозяина.)', 'Pet/Servant magic power is increased. Very light item. Cannot be traded or dropped. The remaining amount of Blessed Spiritshots can be checked in the Pet/Servant info window. (Used from master\'s inventory.)', 'BranchSys.br_blessed_beast_spirit_shot_i00', 0);
INSERT INTO `all_items` VALUES (20335, 'Rune of Experience Points 30%', '5-hour limited period', 'Древняя руна, содержащая в себе мистическую силу. Если хранить ее в инвентаре, увеличивает получаемый опыт на 30%. Оставшееся время расходуется, даже если Вы не находитесь в игре. Нельзя обменять/выбросить.', 'An ancient rune containing mystical power. When kept in the inventory, increases acquired EXP by 30%. Remaining time continues to decrease even when logged out. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_rune_of_exp_i00', 33);
