INSERT INTO `all_items` VALUES (20353, 'Greater CP Potion', NULL, 'Восстанавливает CP на 200 ед. Время до повторного использования очень мало. Нельзя обменять/выбросить.', 'Restores CP by 200. Very short reuse delay. Cannot be traded or dropped.', 'BranchSys.br_cp_potion_i01', 3);
INSERT INTO `all_items` VALUES (20354, 'Secret medicine of Will (C-Grade)', NULL, 'Восстанавливает CP на 800 ед. Используется только с 20 по 39 уровень. Время до повторного использования - 5 минут. Нельзя обменять/выбросить.', 'Restores CP by 800. Can only be used from level 20 to 39. Reuse delay is 5 minutes. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_elixir_of_combative_d_i00', 24);
INSERT INTO `all_items` VALUES (20355, 'Secret medicine of Will (C-Grade)', NULL, 'Восстанавливает CP на 1500 ед. Используется только с 40 по 51 уровень. Время до повторного использования - 5 минут. Нельзя обменять/выбросить.', 'Restores CP by 1500. Can only be used from level 40 to 51. Reuse delay is 5 minutes. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_elixir_of_combative_c_i00', 24);
INSERT INTO `all_items` VALUES (20356, 'Secret medicine of Will (B-Grade)', NULL, 'Восстанавливает CP на 2000 ед. Используется только с 52 по 60 уровень. Время до повторного использования - 5 минут. Нельзя обменять/выбросить.', 'Restores CP by 2000. Can only be used from level 52 to 60. Reuse delay is 5 minutes. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_elixir_of_combative_b_i00', 24);
