INSERT INTO `all_items` VALUES (20358, 'Secret medicine of Will (S-Grade)', NULL, 'Восстанавливает CP на 3000 ед. Используется только с 76 уровня. Время до повторного использования - 5 минут. Нельзя обменять/выбросить.', 'Restores CP by 3000. Can only be used from level 76 or higher. Reuse delay is 5 minutes. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_elixir_of_combative_s_i00', 24);
