INSERT INTO `all_items` VALUES (20391, 'Vitality Maintaining Potion', NULL, 'Магический эликсир, который поддерживает уровень энергии. Время до повторного использования: 30 минут. Нельзя обменять/выбросить.', 'A magical elixir that maintains energy level. Reuse delay: 30 minutes. Cannot be traded or dropped.', 'BranchSys.br_vitality_potion_i00', 3);
