INSERT INTO `all_items` VALUES (20415, 'Afro Hair', 'Big Head, Firework - 7-day limited period', 'Парик в афроамериканском стиле. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'African-style afro wig. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Afro_hair_i00', 0);
