INSERT INTO `all_items` VALUES (20417, 'Uniform Hat', 'Blessed Resurrection - 7-day limited period', 'Очень стильный головной убор. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A very stylish headwear. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Uniform_Hat_i00', 0);
INSERT INTO `all_items` VALUES (20418, 'Assassin\'s Bamboo Hat', 'Wind Walk - 7-Day Limited Period', 'Шляпа, изготовленная из бамбука. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Hat made of bamboo. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Bamboo_Hat_i00', 0);
INSERT INTO `all_items` VALUES (20419, 'Ruthless Tribe Mask', 'Agility - 7-day limited period', 'Маска, принадлежавшая мародерам. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A mask that belonged to looters. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_mask_i00', 0);
INSERT INTO `all_items` VALUES (20420, 'Ribbon Hairband', 'Reflect Damage - 7-Day Limited Period', 'Головной аксессуар в виде банта. Только для персонажей женского пола. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A bow-shaped hair accessory. For female characters only. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Ribbon_i00', 0);
