INSERT INTO `all_items` VALUES (20424, 'Afro Hair - Gold', 'Agility - 7-day limited period', 'Золотой парик в афроамериканском стиле. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Golden afro wig. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Afro_hair_i00', 0);
INSERT INTO `all_items` VALUES (20425, 'Afro Hair - Pink', 'Wild Magic - 7-Day Limited Period', 'Розовый парик в афроамериканском стиле. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Pink afro wig. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Afro_hair_i00', 0);
INSERT INTO `all_items` VALUES (20426, 'Goggles', 'Wind Walk - 7-Day Limited Period', 'Стильные очки, украшенные серебром. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Stylish glasses adorned with silver. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_goggles_i00', 0);
INSERT INTO `all_items` VALUES (20427, 'Napoleon Hat', 'Mana Regeneration - 7-Day Limited Period', 'Шляпа, которую когда-то носил великий император. Нельзя обменять, выкинуть и продать, но можно положить в личное хранилище.', 'A hat once worn by a great emperor. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_napoleonic_cap_i00', 0);
INSERT INTO `all_items` VALUES (20428, 'Horn Hairband', 'Reflect Damage - 7-Day Limited Period', 'Головное украшение розового цвета с миловидными рожками. Только для персонажей женского пола. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A pink head ornament with cute horns. For female characters only. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_horn_hairband_i00', 0);
INSERT INTO `all_items` VALUES (20429, 'Black Gem Mask', 'Vitality - 7-Day Limited Period', 'Маска, сделанная из Черных Камней. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A mask made of Black Stones. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_black_gem_mask_i00', 0);
INSERT INTO `all_items` VALUES (20430, 'Plastic Hair', 'Blessed Escape - 7-day limited period', 'Пластиковое Украшение. Женское - розового цвета, мужское - синего. Занимает 2 ячейки аксессуаров для головы. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Plastic Ornament. Pink for females, blue for males. Occupies 2 head accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_plastic_hair_f_i00', 0);
