INSERT INTO `all_items` VALUES (20504, 'Steam Beatle Mount Bracelet', '30-day limited period', 'Используется для призыва Парового Жука. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Браслет действует 30 дней вне зависимости от того, находится он на персонаже, в инвентаре или в хранилище и от того, вызваны ли сани.', 'Used to summon a Steam Beetle. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. The bracelet remains active for 30 days regardless of whether it is on the character, in the inventory, or in the warehouse, and regardless of whether the sleigh is summoned.', 'etc_rbracelet_aga_agit_i00', 0);
