INSERT INTO `all_items` VALUES (20528, 'Mental Shield Scroll', NULL, 'Увеличивает сопротивление к Удержанию, Сну, Страху и Ментальным Атакам на 40. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases resistance to Hold, Sleep, Fear, and Mental Attacks by 40. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_scroll_of_wind_walk_i00', 1);
