INSERT INTO `all_items` VALUES (20535, 'Steam Beatle Mount Bracelet', '30-day limited period', 'Используется для призыва Парового Жука. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Used to summon a Steam Beetle. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (20536, 'Gold-Maned Lion Mount Bracelet', '30-day limited period', 'Позволяет оседлать Златогривого Льва. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Allows you to ride a Gold-maned Lion. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'pi_high_agathion_bracelet_i00', 0);
INSERT INTO `all_items` VALUES (20537, 'Afro Hair', 'Energy - 7-Day Limited Period', 'Парик в афроамериканском стиле. Требует две ячейки головных уборов. Повторное использование умения \"Энергия\" возможно через 12 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'African-style afro wig. Requires two hair accessory slots. Reuse delay for the \"Energy\" skill is 12 hours. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Afro_hair_i00', 0);
INSERT INTO `all_items` VALUES (20538, 'Horn Rimmed Glasses', 'Energy - 7-Day Limited Period', 'Волшебные Очки в роговой оправе. Повторное использование умения \"Энергия\" возможно через 12 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Magic horn-rimmed glasses. Reuse delay for the \"Energy\" skill is 12 hours. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Eye_Glasses_i00', 0);
INSERT INTO `all_items` VALUES (20539, 'Assassin\'s Bamboo Hat', 'Energy - 7-Day Limited Period', 'Шляпа, изготовленная из бамбука. Требует две ячейки головных уборов. Повторное использование умения \"Энергия\" возможно через 12 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Hat made of bamboo. Requires two hair accessory slots. Reuse delay for the \"Energy\" skill is 12 hours. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_Bamboo_Hat_i00', 0);
