INSERT INTO `all_items` VALUES (20567, 'Eva\'s Circlet (event)', '3-day limited period', 'Ивентовый предмет. Диадема Евы. Использует 2 ячейки аксессуаров для волос. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Event item. Eva\'s Tiara. Uses 2 hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_circlet_of_eva_i00', 0);
INSERT INTO `all_items` VALUES (20568, 'Eva\'s Circlet', '7-day limited period', 'Диадема Евы. Использует 2 ячейки аксессуаров для волос. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Eva\'s Tiara. Uses 2 hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_circlet_of_eva_i00', 0);
INSERT INTO `all_items` VALUES (20569, 'Eva\'s Circlet', NULL, 'Диадема Евы. Использует 2 ячейки аксессуаров для волос. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Eva\'s Tiara. Uses 2 hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_circlet_of_eva_i00', 0);
INSERT INTO `all_items` VALUES (20570, 'Eva\'s Rune (event)', '5-hour limited period', 'Ивентовый предмет. При хранении в инвентаре наделяет владельца особой силой Евы. Время действия предмета не останавливается, даже если Вы не находитесь в игре. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Event item. When kept in the inventory, grants the owner Eva\'s special power. The item\'s duration does not stop even when you are offline. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_rune_of_eva_i00', 33);
INSERT INTO `all_items` VALUES (20571, 'Eva\'s Rune (event)', '3-day limited period', 'Ивентовый предмет. При хранении в инвентаре наделяет владельца особой силой Евы. Время действия предмета не останавливается, даже если Вы не находитесь в игре. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Event item. When kept in the inventory, grants the owner Eva\'s special power. The item\'s duration does not stop even when you are offline. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_rune_of_eva_i00', 33);
INSERT INTO `all_items` VALUES (20572, 'Rune of Experience Points 30%', '3-hour limited period', 'При хранении в инвентаре наделяет владельца особыми способностями. Получаемые очки опыта +30%. Время действия предмета не останавливается, даже если Вы не находитесь в игре. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'When kept in the inventory, grants the owner special abilities. Acquired XP +30%. The item\'s duration does not stop even when you are offline. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_rune_of_exp_i00', 33);
