INSERT INTO `all_items` VALUES (20581, 'Rune of Experience Points 30% - 3-Hour Pack (Event)', NULL, 'Упаковка с Руной Опыта 30% (3 ч.). Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Package with 30% XP Rune (3 hrs.). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20582, 'Power Juice', NULL, 'Напиток из редких фруктов. Физ. Атк. + 15%. Очень легок. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Rare fruit drink. P. Atk. +15%. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_fruit_juice_glass_bottle_i07', 1);
INSERT INTO `all_items` VALUES (20583, 'Blessed Scroll of Escape (Event)', NULL, 'Ивентовый предмет. Перемещает в ближайший город. Нельзя обменять/выбросить/продать. Можно положить в личное хранилище.', 'Event item. Teleports to the nearest town. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_scroll_of_return_i01', 1);
INSERT INTO `all_items` VALUES (20584, 'Blessed Scroll of Resurrection (Event)', NULL, 'Ивентовый предмет. Магический свиток, воскрешающий мертвого персонажа и полностью восстанавливающий потерянный им опыт. Нельзя обменять/выбросить/продать. Можно положить в личное хранилище.', 'Event item. A magical scroll that resurrects a dead character and fully restores lost XP. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_scroll_of_resurrection_i01', 1);
INSERT INTO `all_items` VALUES (20585, 'Seed of Fire (event)', NULL, 'Ивентовый предмет. Позволяет призывать Огненного Духа.', 'Event item. Allows you to summon a Fire Spirit.', 'BranchSys.br_seed_of_fire_i00', 1);
