INSERT INTO `all_items` VALUES (20594, 'Summon of Love Bracelet (event)', '24-hour limited period', 'Браслет, позволяющий призывать возлюбленного. Призыв возможен, если оба персонажа состоят в одной группе и носят Браслет Любви. Нельзя обменять/выбросить/продать. Можно положить в личное хранилище.', 'Bracelet allowing you to summon your beloved. Summoning is possible if both characters are in the same party and wearing Love Bracelets. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys.br_ring_of_friendship_i00', 0);
INSERT INTO `all_items` VALUES (20597, 'Girl\'s Soul Ore', NULL, 'Руда Души, необходимый для использования особых умений Агатиона Вега. Нельзя Продать. Можно положить в личное хранилище.', 'Soul Ore, required to use Vega Agathion\'s special skills. Cannot be sold. Can be deposited into a personal warehouse.', 'BranchSys.br_sevenlove_stone_i00', 0);
