INSERT INTO `all_items` VALUES (20628, 'Summon of Love Bracelet', '7-day limited period', 'Браслет, призывающий друга. Оба персонажа должны состоять в одной группе и носить Браслет Любви. Нельзя обменять/выбросить/продать. Можно положить в личное хранилище.', 'Bracelet used to summon a friend. Both characters must be in the same party and wearing Love Bracelets. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys.br_ring_of_friendship_i00', 0);
