INSERT INTO `all_items` VALUES (20633, 'Watermelon Hat', 'Ability of a Cool Watermelon - 7-day limited period', 'Шляпа в виде арбуза. Свежесть ощущается при одном взгляде на нее. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Watermelon-shaped hat. Looks refreshing at a glance. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_watermelon_cap_a_i00', 0);
INSERT INTO `all_items` VALUES (20634, 'Watermelon Hat', NULL, 'Шляпа в виде арбуза. Свежесть ощущается при одном взгляде на нее. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Watermelon-shaped hat. Looks refreshing at a glance. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_watermelon_cap_a_i00', 0);
INSERT INTO `all_items` VALUES (20635, 'No Grade Beginner\'s Adventurer Support Pack', NULL, 'Комплект предметов для новичков Адена. В нем хранится снаряжение (без ранга) и напитки.  Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Aden Newbie Item Set. Contains no-grade equipment and potions. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (20636, 'D-Grade Fighter Support Pack', NULL, 'Комплект предметов для новичков Адена. В нем хранится снаряжение воина(D-ранг).  Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Aden Newbie Item Set. Contains warrior equipment (D-grade). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (20637, 'D-Grade Mage Support Pack', NULL, 'Комплект предметов для новичков Адена. В нем хранится снаряжение мага(D-ранг).  Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Aden Newbie Item Set. Contains mage equipment (D-grade). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (20638, 'Beginner\'s Adventurer Reinforcement Pack', NULL, 'Комплект предметов для новичков Адена. В нем хранятся полезные предметы.  Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Aden Newbie Item Set. Contains useful items. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
