INSERT INTO `all_items` VALUES (20717, 'Shiny Halloween Toy Box (Event)', NULL, 'Для ивента. С определенным шансом можно получить одну из блестящих масок Хэллоуина. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Event item. Grants a certain chance to obtain a shiny Halloween mask. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_box_of_adventure_1_i00', 0);
INSERT INTO `all_items` VALUES (20718, 'Shiny Super Strong Giant\'s Mask (Event)', 'Blessing of Halloween - 4-Hour Limited Period', 'Для ивента. Блестящая Маска Гиганта. Надев ее, можно использовать умение карты, необходимое для игры Джека. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения - 2 ч.', 'Event item. Shiny Giant Mask. Wearing it allows you to use the card skill required for Jack\'s game. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 2 hrs.', 'BranchSys.br_shiny_frankenstein_mask_i00', 0);
