INSERT INTO `all_items` VALUES (20866, 'Soul Avatar Set', NULL, 'Упаковка с огромным комплектом из 12 Упаковок Духовных Аватаров. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Package containing a massive set of 12 Spirit Avatar Packages. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_bright_gold_box_i00', 0);
INSERT INTO `all_items` VALUES (20867, 'Kadomas Transformation Stick', '7-day limited period', 'Жезл Трансформации в Кадомацу. Можно использовать в течение 7 дней. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Kadomatsu Transformation Wand. Usable for 7 days. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_kadomatsu_wp_i00', 0);
INSERT INTO `all_items` VALUES (20868, 'Kotatz', NULL, 'Призывает Котацу, увеличивающий восстановление HP на 40% и MP на 20%. Необходимо призывать Котацу на определенном расстоянии от города, иначе эффекта не будет. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Summons Kotatsu, which increases HP recovery by 40% and MP recovery by 20%. Kotatsu must be summoned within a certain distance from a town, otherwise there is no effect. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_kotatsu_i00', 3);
INSERT INTO `all_items` VALUES (20869, 'New Year\'s Money', NULL, 'В подарке находится Жезл Перевоплощения Кадомацу и 3 Котацу. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Contains a Kadomatsu Transformation Wand and 3 Kotatsus. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_otoshidama_i00', 0);
INSERT INTO `all_items` VALUES (20870, 'Red Firework', NULL, 'Взрывается красный фейерверк. Увеличивает защиту от воды на 30 и СИЛ на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes red fireworks. Increases Water resistance by 30 and STR by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_red_i00', 0);
INSERT INTO `all_items` VALUES (20871, 'Gold Firework', NULL, 'Взрывает золотой фейерверк. Увеличивает защиту от святости на 30 и ВЫН на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes gold fireworks. Increases Divine resistance by 30 and CON by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_gold_i00', 0);
INSERT INTO `all_items` VALUES (20872, 'Blue Firework', NULL, 'Взрывает синий фейерверк. Увеличивает защиту от огня на 30 и ЛВК на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes blue fireworks. Increases Fire resistance by 30 and DEX by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_blue_i00', 0);
INSERT INTO `all_items` VALUES (20873, 'Pink Firework', NULL, 'Взрывает фиолетовый фейерверк. Увеличивает защиту от земли на 30 и ДУХ на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes purple fireworks. Increases Earth resistance by 30 and MEN by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_pink_i00', 0);
INSERT INTO `all_items` VALUES (20874, 'White Firework', NULL, 'Взрывает белый фейерверк. Увеличивает защиту от ветра на 30 и МДР на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes white fireworks. Increases Wind resistance by 30 and WIT by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_white_i00', 0);
INSERT INTO `all_items` VALUES (20875, 'Silver Firework', NULL, 'Взрывает серебряный фейерверк. Увеличивает защиту от тьмы на 30 и ИНТ на 1. Время действия: 10 мин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 4 ч.', 'Explodes silver fireworks. Increases Dark resistance by 30 and INT by 1. Duration: 10 min. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 4 hrs.', 'BranchSys.br_firecracker_silver_i00', 0);
INSERT INTO `all_items` VALUES (20876, 'Love for All Seasons', 'Empower, Wild Magic', 'Увеличивает Маг. Атк. на 75% и шанс нанесения Крит. Атк. магией на 2. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases M. Atk. by 75% and magic Critical Rate by 2. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_a_i00', 0);
INSERT INTO `all_items` VALUES (20877, 'Happy New Year', 'Death Whisper, Focus, Guidance', 'Увеличивает мощность Крит. Атк. на 35%, шанс нанесения Крит. Атк. на 30 и точность на 4. Время действия: 1 ч.. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases Critical damage power by 35%, Critical Rate by 30, and Accuracy by 4. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_b_i00', 0);
INSERT INTO `all_items` VALUES (20878, 'Female Aniruddha', 'Shield, Magic Barrier, Blessed Shield', 'Увеличивает Физ. Защ. на 15%, Маг. Защ. на 30% и шанс блока щитом на 15. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases P. Def. by 15%, M. Def. by 30%, and Shield Defense rate by 15. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_c_i00', 0);
INSERT INTO `all_items` VALUES (20879, 'Kung Hei Fat Choy', 'Might, Berserker Spirit, Vampiric Rage', 'Снижает Физ. Защ. на 8%, Маг. Защ. на 16% и Уклонение на 4, но увеличивает Атаку на 15%, Маг. Атк. на 16%, Скор. Атк. на 8%, Скор. Маг. на 8% и Скорость на 8. Восстанавливает 9% HP от нанесенного противнику урона. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Decreases P. Def. by 8%, M. Def. by 16%, and Evasion by 4, but increases Atk. by 15%, M. Atk. by 16%, Atk. Spd. by 8%, Casting Spd. by 8%, and Speed by 8. Restores 9% of damage dealt to the enemy as HP. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_d_i00', 0);
INSERT INTO `all_items` VALUES (20880, 'Chinese Feast', 'Clarity, Acumen, Blessed Soul', 'Снижает расход MP для умений на 20%, для магии - на 10% и для песен/танцев - на 20%. Увеличивает Скор. Маг. на 30%, Макс. MP на 35%. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Decreases skill MP consumption by 20%, magic MP consumption by 10%, and song/dance MP consumption by 20%. Increases Casting Spd. by 30% and Max MP by 35%. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_e_i00', 0);
INSERT INTO `all_items` VALUES (20881, 'Hwa Gei Bu Gwi', 'Decrease Weight, Haste', 'Увеличивает Скор. Атк. на 33% и штраф на вес до 9000. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases Atk. Spd. by 33% and weight penalty limit by 9,000. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_f_i00', 0);
INSERT INTO `all_items` VALUES (20882, 'Fire Stamp', 'Wind Walk, Agility Blessed Body', 'Увеличивает Скорость на 33, Шанс уклонения на 4 и Макс. HP на 35%. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Increases Speed by 33, Evasion rate by 4, and Max HP by 35%. Duration: 1 hr. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_taiwan_newyear_food_g_i00', 0);
