INSERT INTO `all_items` VALUES (20896, 'Red Dimensional Stone', NULL, 'Камень, искажающий пространство и время. Если использовать после выполнения квеста в Пайлаке, туда можно будет зайти еще 1 раз. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования - 5 ч.', 'A stone that distorts space and time. If used after completing the Pailaka quest, you can enter it 1 more time. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Reuse delay: 5 hrs.', 'BranchSys.br_stone_of_time_i00', 0);
INSERT INTO `all_items` VALUES (20897, 'Purple Paper Mask', 'Blessed Soul - 7-day limited period', 'Роскошная маска из фиолетовой бумаги. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения - 1 ч.', 'Luxurious purple paper mask. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys.br_party_mask_purple_i00', 0);
INSERT INTO `all_items` VALUES (20898, 'Purple Paper Mask 7-Day Pack', 'Blessed Soul', 'Упаковка с маской из фиолетовой бумаги (7 дн.). Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Package with Purple Paper Mask (7 days). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20899, 'Mango Dessert', NULL, 'Сладкий манго и клейкий рис. При использовании восстанавливает всю энергию. Время ожидания повторного использования: 60 мин.', 'Sweet mango and sticky rice. When used, fully restores Vitality. Reuse delay: 60 min.', 'BranchSys.br_thai_desert_i00', 3);
INSERT INTO `all_items` VALUES (20900, 'Santa Hat', '14-day limited period', 'Шапка Седобородого Деда Мороза, созданная, чтобы поздравлять всех с Новым годом. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Gray-Bearded Santa\'s Hat, made to wish everyone a happy new year. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_xmas_gawibawibo_cap_i00', 0);
INSERT INTO `all_items` VALUES (20901, 'Santa Hat Set', NULL, 'В упаковке находятся Шапка Седобородого Деда Мороза и Нос Рудольфа. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Package containing Gray-Bearded Santa\'s Hat and Rudolph\'s Nose. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (20902, 'Ring of Queen Ant 7-Day Pack', NULL, 'Упаковка с Кольцом Королевы Муравьев (7 дн.). Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Package with Queen Ant Ring (7 days). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (20903, 'Rose Petal', NULL, 'Под воздействием аромата розы, скорость восстановления HP/MP увеличена на 20%. Время действия: 20мин.', 'Under the influence of the rose\'s aroma, HP/MP recovery rate is increased by 20%. Duration: 20 min.', 'BranchSys.br_herb_of_baguette_i00', 0);
