INSERT INTO `all_items` VALUES (20938, 'Jet Bike Mount Bracelet', '7-day limited period', 'Используется для призыва Реактивного Мотоцикла, созданного гномами. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Used to summon a Jet Bike created by dwarves. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_z_bike_i00', 0);
INSERT INTO `all_items` VALUES (20939, 'Jet Bike Mount Bracelet', '30-day limited period', 'Используется для призыва Реактивного Мотоцикла, созданного гномами. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Used to summon a Jet Bike created by dwarves. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_z_bike_i00', 0);
INSERT INTO `all_items` VALUES (20940, 'Phoenix Agthion Seal Bracelet', 'Nirvana Rebirth - 7-day limited period', 'Браслет призыва Агатиона Феникса. При использовании умения Нирвана мгновенно восстанавливает HP, MP, CP и дает неуязвимость на 5 секунд. Можно использовать только при HP ниже 30%. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения: 12 ч.', 'Phoenix Agathion Summon Bracelet. Using the Nirvana skill instantly restores HP, MP, and CP and grants invulnerability for 5 seconds. Can only be used when HP is below 30%. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 12 hrs.', 'BranchSys2.br_aga_china_phoenix_i00', 0);
INSERT INTO `all_items` VALUES (20941, 'Phoenix Agthion Seal Bracelet', 'Oriental Phoenix - 7-day limited period', 'Браслет призыва Агатиона Феникса. При использовании умения Очищение Феникса отменяет все отрицательные эффекты. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения: 4 ч.', 'Phoenix Agathion Summon Bracelet. Using the Phoenix Purification skill removes all negative effects. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 4 hrs.', 'BranchSys2.br_aga_china_phoenix_i00', 0);
INSERT INTO `all_items` VALUES (20942, 'Fox Mask', NULL, 'Маска Лисы. Во время боя автоматически закрывает лицо. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Fox Mask. Automatically covers the face during battle. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_fox_japan_cap_i00', 0);
INSERT INTO `all_items` VALUES (20943, 'Fox Mask', 'Silent Move - 7-day limited period', 'Маска Лисы. Во время боя автоматически закрывает лицо. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения: 4 ч.', 'Fox Mask. Automatically covers the face during battle. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 4 hrs.', 'BranchSys2.br_fox_japan_cap_i00', 0);
INSERT INTO `all_items` VALUES (20944, 'Paiwan Hat', NULL, 'Национальная Шляпа Пайван. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Paiwan National Hat. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_paiwan_cap_i00', 0);
INSERT INTO `all_items` VALUES (20945, 'Paiwan Hat', 'Power of Guardian Deity - 7-day limited period', 'Национальная Шляпа Пайван. При использовании умения Сила Богов увеличивает мощность Крит. Атк. на 35% в течение 10 минут. Требует две ячейки головных уборов. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время повторного использования особого умения: 1 ч.', 'Paiwan National Hat. Using the Gods\' Power skill increases Critical damage power by 35% for 10 minutes. Requires two hair accessory slots. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_paiwan_cap_i00', 0);
