INSERT INTO `all_items` VALUES (20970, 'Agathion Seal Bracelet - Three-headed Dragon', 'Wind Walk', 'Браслет для призыва забавного Трехглавого Дракона. Нельзя обменять/выбросить/продать. Время перезарядки особого умения - 1 час.', 'Bracelet for summoning a funny Three-Headed Dragon. Cannot be traded, dropped, or sold. Special skill reuse delay: 1 hr.', 'BranchSys2.br_aga_threehead_i00', 0);
INSERT INTO `all_items` VALUES (20971, 'Trejuo Transformation Stick', 'Blessed Child Transformation', 'Жезл, с помощью которого можно перевоплотиться в Благословенного Тайского Мальчика Трежера. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Wand used to transform into Blessed Thai Boy Treasure. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_blessed_taiboy_i00', 0);
INSERT INTO `all_items` VALUES (20972, 'Sujin Transformation Stick', 'Blessed Child Transformation', 'Жезл, с помощью которого можно перевоплотиться в Благословенную Тайскую Девочку Суджин. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'Wand used to transform into Blessed Thai Girl Sujin. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_blessed_taigirl_i00', 0);
INSERT INTO `all_items` VALUES (20973, 'Opera Mask - Liu Bei', 'Buff of Virtue, Age of the Three Kingdoms', 'Маска Пекинской Оперы, которую надевает актер, исполняющий роль Юэ Фэя. Позволяет использовать Эффект Добродетели и Дух Трех Государств. Нельзя обменять/выбросить/продать. Требует две ячейки головных уборов. Можно поместить в личное хранилище. Время перезарядки особого умения - 1 час.', 'Peking Opera mask worn by the actor playing Yue Fei. Allows the use of Virtue Effect and Spirit of the Three Kingdoms. Cannot be traded, dropped, or sold. Requires two hair accessory slots. Can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_pekingopera_mask_a_i00', 0);
INSERT INTO `all_items` VALUES (20974, 'Opera Mask - Guan Yu', 'Silence of Fidelity, Age of the Three Kingdoms', 'Маска Пекинской Оперы, которую надевает актер, исполняющий роль Гуань Юя. Позволяет использовать Безмолвие Преданности и Дух Трех Государств. Нельзя обменять/выбросить/продать. Требует две ячейки головных уборов. Можно поместить в личное хранилище. Время перезарядки особого умения - 1 час.', 'Peking Opera mask worn by the actor playing Guan Yu. Allows the use of Silence of Devotion and Spirit of the Three Kingdoms. Cannot be traded, dropped, or sold. Requires two hair accessory slots. Can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_pekingopera_mask_b_i00', 0);
INSERT INTO `all_items` VALUES (20975, 'Opera Mask - Zhang Fei', 'Vitality of Courage, Age of the Three Kingdoms', 'Маска Пекинской Оперы, которую надевает актер, исполняющий роль Джань Фэя. Позволяет использовать Энергию Алмаза, Дух Трех Государств. Нельзя обменять/выбросить/продать. Требует две ячейки головных уборов. Можно поместить в личное хранилище. Время перезарядки особого умения - 1 час.', 'Peking Opera mask worn by the actor playing Zhang Fei. Allows the use of Diamond Energy and Spirit of the Three Kingdoms. Cannot be traded, dropped, or sold. Requires two hair accessory slots. Can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_pekingopera_mask_c_i00', 0);
INSERT INTO `all_items` VALUES (20976, 'Proof of a Warrior', '30-day limited period', 'Благородный знак, символизирующий храбрость. Необходим для использования Эффекта Добродетели, Безмолвия Преданности и Энергии Алмаза с Маской Пекинской Оперы. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'A noble mark symbolizing bravery. Required to use Virtue Effect, Silence of Devotion, and Diamond Energy with the Peking Opera Mask. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_pekingopera_symbol_a_i00', 0);
INSERT INTO `all_items` VALUES (20977, 'Proof of Friendship', NULL, 'Благородный знак, символизирующий дружбу. Необходим для использования Духа Трех Государств с Маской Пекинской Оперы. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'A noble mark symbolizing friendship. Required to use Spirit of the Three Kingdoms with the Peking Opera Mask. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_pekingopera_symbol_b_i00', 0);
INSERT INTO `all_items` VALUES (20978, 'Zhongzi (B-Grade)', NULL, 'Традиционное тайское блюдо, повышающее вероятность модификации оружия ранга B на 15%. Используется только для модификации на +4-9. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Traditional Thai dish that increases B-grade weapon enchant success rate by 15%. Used only for enchants from +4 to +9. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_taiwan_riceball_a_i00', 27);
INSERT INTO `all_items` VALUES (20979, 'Zhongzi (A-Grade)', NULL, 'Традиционное тайское блюдо, повышающее вероятность модификации оружия ранга А на 12%. Используется только для модификации на +4-9. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Traditional Thai dish that increases A-grade weapon enchant success rate by 12%. Used only for enchants from +4 to +9. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_taiwan_riceball_b_i00', 27);
INSERT INTO `all_items` VALUES (20980, 'Zhongzi (S-Grade)', NULL, 'Традиционное тайское блюдо, повышающее вероятность модификации оружия ранга S на 10%. Используется только для модификации на +4-9. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Traditional Thai dish that increases S-grade weapon enchant success rate by 10%. Used only for enchants from +4 to +9. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_taiwan_riceball_c_i00', 27);
INSERT INTO `all_items` VALUES (20981, 'Dragon Boat', NULL, 'Традиционная шапка лодочника в виде дракона. Нельзя обменять/выбросить/продать. Требует две ячейки головных уборов. Можно поместить в личное хранилище.', 'Traditional dragon-shaped boatman hat. Cannot be traded, dropped, or sold. Requires two hair accessory slots. Can be deposited into a personal warehouse.', 'BranchSys2.br_dragonboat_cap_i00', 0);
INSERT INTO `all_items` VALUES (20982, 'Dragon Boat', 'Haste - 7-day limited period', 'Традиционная шапка лодочника в виде дракона. Нельзя обменять/выбросить/продать. Требует две ячейки головных уборов. Можно поместить в личное хранилище. Время перезарядки особого умения - 1 час.', 'Traditional dragon-shaped boatman hat. Cannot be traded, dropped, or sold. Requires two hair accessory slots. Can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_dragonboat_cap_i00', 0);
INSERT INTO `all_items` VALUES (20983, 'Agathion Seal Bracelet - Ball Trapping Gnosian', 'Soccer Ball of Cheers, Buff of Cheers', 'Браслет для призыва Охотника за Мячом Гносиана. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище. Время перезарядки особого умения - 1 час.', 'Bracelet for summoning Ball Hunter Gnosian. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse. Special skill reuse delay: 1 hr.', 'BranchSys2.br_aga_ball_male_i00', 0);
