INSERT INTO `all_items` VALUES (21034, 'Evain\'s Recovery Scroll', NULL, 'Заклинание силы Ивеина. Мгновенно восстанавливает 500 HP союзников вокруг. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Yvein\'s Power Spell. Instantly restores 500 HP of surrounding allies. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_scroll_of_yibein_i00', 1);
INSERT INTO `all_items` VALUES (21037, 'Warrior\'s Breath', NULL, 'Зелье силы древнего воина. Восстанавливает 300 CP. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Ancient Warrior\'s Power Potion. Restores 300 CP. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_breath_of_hero_i00', 3);
INSERT INTO `all_items` VALUES (21038, 'Potion of a Hero', NULL, 'Зелье духа героя. Мгновенно восстанавливает 500 HP и 200 MP. Время ожидания повторного использования : 60 сек. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Hero\'s Spirit Potion. Instantly restores 500 HP and 200 MP. Reuse delay: 60 sec. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'BranchSys2.br_hero_potion_i00', 3);
INSERT INTO `all_items` VALUES (21039, 'Highest Power Healing Potion', NULL, 'В течение 15 секунд восстанавливает 100 HP каждую секунду. Нельзя обменять/выбросить/продать. Можно поместить в личное хранилище.', 'Restores 100 HP every second for 15 seconds. Cannot be traded, dropped, or sold. Can be deposited into a personal warehouse.', 'etc_reagent_white_i00', 3);
