INSERT INTO `all_items` VALUES (21148, 'Transformation Scroll: Dragon Master Lee', NULL, 'Свиток, позволяющий трансформироваться в Дракона-Мастера Ли. Эффект сохраняется в течение 1 часа. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Scroll allowing transformation into Dragon Master Lee. Effect lasts for 1 hour. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (21149, 'Transformation Scroll: Dragon Master Karin', NULL, 'Свиток, позволяющий трансформироваться в Дракона-Мастера Карин. Эффект сохраняется в течение 1 часа. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Scroll allowing transformation into Dragon Master Karin. Effect lasts for 1 hour. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_scroll_white_i00', 1);
INSERT INTO `all_items` VALUES (21150, 'Shiny Lit Platform Summon Bracelet', NULL, 'Надев, можно подняться на сцену, сияющую роскошным освещением. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Wearing it allows you to step onto a stage shining with luxurious lighting. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.Icon.br_shiny_platform_i00', 0);
INSERT INTO `all_items` VALUES (21151, 'Shiny Lighting', NULL, 'Свиток, вызывающий роскошное сияние. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Scroll that summons a luxurious glow. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.br_aga_singer_dancer_i00', 1);
INSERT INTO `all_items` VALUES (21152, 'Agathion Seal Bracelet - Singer & Dancer', NULL, 'Браслет, вызывающий весело танцующего и поющего Агатиона. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Bracelet that summons an Agathion - Singer & Dancer that gleefully sings and dances. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse.', 'BranchSys2.br_aga_singer_dancer_i00', 0);
INSERT INTO `all_items` VALUES (21153, 'Agathion Seal Bracelet - Singer & Dancer', '7-day limited period', 'Браслет, вызывающий весело танцующего и поющего Агатиона. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', '7-Day Limited Period	Bracelet that summons an Agathion - Singer & Dancer that gleefully sings and dances. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse.', 'BranchSys2.br_aga_singer_dancer_i00', 0);
INSERT INTO `all_items` VALUES (21154, 'Singer & Dancer Agathion Pack', NULL, 'Упаковка с поющим и танцующим Агатионом. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Package with singing and dancing Agathion. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21155, 'Singer & Dancer Agathion Pack', NULL, 'Упаковка с поющим и танцующим Агатионом (7 дней). Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Package with singing and dancing Agathion (7 days). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21156, 'Big Wedding Cake', NULL, 'Свиток вызова большого трехслойного Свадебного Торта, без которого не обойтись на свадьбе. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Scroll summoning a large three-tier Wedding Cake, a must-have for a wedding. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.Icon.br_big_wedding_cake_i00', 0);
INSERT INTO `all_items` VALUES (21157, 'Flower Shower', NULL, 'Дождь из цветов, которыми осыпают жениха и невесту.', 'Shower of flowers showered upon the bride and groom.', 'BranchSys2.Icon.br_flower_shower_i00', 0);
INSERT INTO `all_items` VALUES (21158, 'Echo Crystal', NULL, 'Кристалл, при использовании которого слышатся фантастические голоса.', 'A crystal that emits fantastic voices when used.', 'BranchSys2.Icon.br_eco_crystal_i00', 0);
INSERT INTO `all_items` VALUES (21159, 'Wedding Ring - Male', NULL, 'Обручальное Кольцо из тех, которыми обмениваются помолвленные, условившиеся о свадьбе. Мужское.', 'Wedding ring exchanged by an engaged couple. Male use.', 'BranchSys2.Icon.br_wedding_ring_m_i00', 0);
INSERT INTO `all_items` VALUES (21160, 'Wedding Ring - Female', NULL, 'Обручальное Кольцо из тех, которыми обмениваются помолвленные, условившиеся о свадьбе. Женское.', 'A wedding ring exchanged by fiancés who have agreed to marry. Female.', 'BranchSys2.Icon.br_wedding_ring_f_i00', 0);
INSERT INTO `all_items` VALUES (21161, 'Wedding Pack', NULL, 'Свадебная Упаковка, содержащая Билет на Медовый Месяц и Большой Свадебный Торт.', 'Wedding Package containing a Honeymoon Ticket and a Large Wedding Cake.', 'BranchSys2.Icon.br_wedding_box_i00', 0);
INSERT INTO `all_items` VALUES (21162, 'Wedding Veil', NULL, 'Сияющая белизной Свадебная Вуаль. Только для персонажей женского пола. Требует 2 ячейки головных уборов. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Pure white and shiny wedding veil. Female exclusive item. Uses 2 hair accessory slot(s). Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse.', 'BranchSys2.br_wedding_vail_i00', 0);
INSERT INTO `all_items` VALUES (21163, 'Wedding Bouquet', NULL, 'Свадебный Букет из прекрасных цветов. Только для персонажей женского пола. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Wedding bouquet of beautiful flowers. Female exclusive item. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse.', 'BranchSys2.br_wedding_bouquet_i00', 0);
INSERT INTO `all_items` VALUES (21164, 'Honeymoon Ticket', '7-day limited period', 'Билет на Медовый Месяц, который жених дарит невесте. При использовании Энергия сохраняется в течение 1 часа. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Honeymoon Ticket given by the groom to the bride. When used, Vitality is maintained for 1 hour. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys2.Icon.br_weddin_ticket_i00', 0);
INSERT INTO `all_items` VALUES (21165, 'Agathion Seal Bracelet - Zaken Spirit Sword', NULL, 'Браслет, вызывающий Мечи Духа Закена, включающие в себя 6 мечей Закена. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Bracelet that summons Zaken\'s Spirit Sword, which is made up of Zaken\'s 6 swords. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse.', 'BranchSys2.Icon.br_aga_zaken_i00', 0);
INSERT INTO `all_items` VALUES (21166, 'Agathion Seal Bracelet - Zaken\'s Spirit Swords', '7-day limited period', 'Браслет, вызывающий Мечи Духа Закена, включающие в себя 6 мечей Закена. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Swords\' Song - 7-Day Limited Period	Can summon Zaken\'s Spirit Swords when equipped. Special skill cooldown is 2 hours. Can be used for 7 days. Cannot be exchanged or dropped.', 'BranchSys2.Icon.br_aga_zaken_i00', 0);
INSERT INTO `all_items` VALUES (21167, 'Zaken Spirit Sword Pack', NULL, 'Упаковка с Мечами Духа Закена. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Package with Zaken\'s Spirit Swords. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21168, 'Zaken Spirit Sword Pack', NULL, 'Упаковка с Мечами Духа Закена (7 дней). Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'Package with Zaken\'s Spirit Swords (7 days). Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21169, 'Birthday Present Pack', NULL, 'Подарок на день рождения, выдаваемый Аллегрией. При использовании можно получить 3 порции энергии радости, Торт Именинника, а также колпак. Обменять и выбросить невозможно. Можно положить в личное хранилище.', 'Birthday gift issued by Allegria. When used, grants 3 portions of joy energy, a Birthday Cake, and a party hat. Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'event_hero_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (21170, 'Birthday Vitality Potion', NULL, 'При использовании в течение 12 часов восстанавливает энергию после получения опыта во время охоты. Нельзя обменять, выбросить или продать, можно положить в личное хранилище.', 'When used for 12 hours, restores Vitality after gaining EXP during hunting. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'etc_potion_blue_i00', 3);
INSERT INTO `all_items` VALUES (21171, 'Transformation Scroll: Treasure Hunter', 'Event', 'Свиток, на 10 минут перевоплощающий в Синий Кубик. При использовании на Острове Грез можно найти сокровища. При использовании в состоянии перевоплощения нет никакого эффекта.', 'A scroll that transforms you into a Blue Cube for 10 minutes. Can be used to find treasures on Isle of Prayer. Has no effect if used while already transformed.', 'etc_trans_4f_s_b_01', 1);
INSERT INTO `all_items` VALUES (21172, 'Transformation Scroll: Onyx Beast', 'Event', 'Свиток, позволяющий на 30 минут перевоплотиться в Ониксового Зверя. При использовании в состоянии перевоплощения нет никакого эффекта.', 'A scroll that allows you to transform into an Onyx Beast for 30 minutes. Has no effect if used while already transformed.', 'etc_trans_4f_s_b_01', 1);
