INSERT INTO `all_items` VALUES (21191, 'Transformation Scroll: Demon Prince', 'Event', 'Свиток, позволяющий на 30 минут перевоплотиться в Принца Демонов. При использовании в состоянии перевоплощения нет никакого эффекта.', 'A scroll that allows you to transform into Demon Prince for 30 minutes. Has no effect if used while already transformed.', 'etc_trans_4f_s_b_01', 1);
INSERT INTO `all_items` VALUES (21192, 'Dimension Diamond Pack', NULL, 'Витаминная упаковкаПодарочная коробка, содержащая 50 Алмазов Иных Миров. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 50 Otherworld Diamonds. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21193, 'Dimension Diamond', NULL, 'Витаминный предметКристалл, наполненный магической силой. Необходим для телепортации. Вы можете обменять их у любого Хранителя Портала на Свитки Телепорта в различные города. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. A crystal filled with magical power. Required for teleportation. You can exchange them with any Gatekeeper for Scroll of Escape to various towns. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'etc_gem_clear_i00', 0);
INSERT INTO `all_items` VALUES (21194, 'Blessed Scroll of Escape Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 1 Благословенный Свиток Телепорта. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 1 Blessed Scroll of Escape. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21195, 'Blessed Scroll of Escape', NULL, 'Витаминный предметМагический свиток, с помощью которого можно переместиться в ближайшее поселение. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. A magical scroll that teleports you to the nearest settlement. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'etc_scroll_of_return_i01', 1);
INSERT INTO `all_items` VALUES (21196, 'Highest Power Temporary Healing Potion Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 5 шт. Великого Быстродействующего Зелья Исцеления. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 5 Greater Healing Potions. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21197, 'Highest Power Temporary Healing Potion', NULL, 'Витаминный предметМагическое зелье, мгновенно восстанавливающее HP. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. A magic potion that instantly restores HP. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'etc_potion_gold_i00', 3);
INSERT INTO `all_items` VALUES (21198, 'Mysterious Scroll Pack - 2 Prophecies of Wind', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 2 Чудодейственных Свитка - Пророчество Воздуха. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 2 Miracle Scrolls - Prophecy of Wind. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21199, 'Mysterious Scroll Pack - 8 Prophecies of Wind', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 8 Чудодейственных Свитков - Пророчество Воздуха. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 8 Miracle Scrolls - Prophecy of Wind. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21200, 'Mysterious Scroll - Prophecy of Wind', NULL, 'Витаминный предметНа 60 минут с помощью Великого Духа повышает Макс. НР на 20%, вероятность Крит Удара на 20%, мощность Крит. Атк. магией на 20%, Атк. на 10%, Защ. на 20, Скорость Атк. на 20%, Маг. Атк. на 20%, Маг. Защ. на 20%, Скор. Маг. на 20%, сопротивление вредоносным умениям на 10%, также снижает Скорость на 20%. Придает способность возвращать в виде НР 5% обычного физического урона, нанесенного противнику в ближнем бою. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. For 60 minutes, through Great Spirit, increases Max HP by 20%, Critical Rate by 20%, magic Critical Damage power by 20%, Atk. by 10%, P. Def. by 20, Atk. Spd. by 20%, M. Atk. by 20%, M. Def. by 20%, Casting Spd. by 20%, and Debuff Resistance by 10%, while decreasing Speed by 20%. Grants the ability to restore 5% of standard physical damage dealt to a melee target as HP. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_xmas_scroll_i00', 1);
INSERT INTO `all_items` VALUES (21201, 'Magic Glasses 30-Day Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 1 Магические Очки. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 1 Magic Glasses. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21202, 'Magic Glasses', '30-day limited period', 'Витаминный предметМагические Очки, увеличивающие МР на 10% и Маг. Защ. на 70. Можно пользоваться 30 дней. Нельзя обменять/выбросить, но можно положить в личное хранилище.', 'Vitamin item. Magic Glasses that increase MP by 10% and M. Def. by 70. Usable for 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'BranchSys.br_Eye_Glasses_i00', 0);
INSERT INTO `all_items` VALUES (21203, 'Queen Ant\'s Ring 30-Day Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 1 Кольцо Королевы Муравьев (30 дней). Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 1 Queen Ant Ring (30 days). Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21204, 'Baium\'s Ring 30-Day Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 1 Кольцо Баюма (30 дней). Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 1 Baium\'s Ring (30 days). Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21205, 'Earring of Zaken 30-Day Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 1 Кольцо Закена (30 дней). Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 1 Zaken\'s Earring (30 days). Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21206, 'Queen Ant\'s Ring', '30-day limited period', 'Витаминный предметДает следующие эффекты: MP +21, увеличение сопротивления отравлению на 30%, увеличение шанса отравления на 30%, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления удержанию на 20%, увеличение шанса удержания на 20%. Если персонаж надевает два таких кольца, то эффект проявится только у одного из них. Можно использовать в течение 30 дней. Нельзя обменять/выбросить, но можно положить в личное хранилище.', 'Vitamin item. Grants the following effects: MP +21, Poison resistance +30%, Poison attack rate +30%, Accuracy increase, Critical Damage increase, Hold resistance +20%, Hold attack rate +20%. If a character wears two such rings, the effect applies only to one of them. Usable for 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'accessory_ring_of_queen_ant_i00', 0);
INSERT INTO `all_items` VALUES (21207, 'Baium\'s Ring', '30-day limited period', 'Витаминный предметДает следующие эффекты: MP +21, увеличение сопротивления отравлению на 40%, увеличение шанса отравления на 40%, увеличение Точности, увеличение Крит. урона, увеличение сопротивления удержанию на 30%, увеличение шанса удержания на 30%, увеличение Атк. и Скор. Маг. Если персонаж надевает два таких кольца, то эффект проявится только у одного из них. Можно использовать в течение 30 дней. Нельзя обменять/выбросить, но можно положить в личное хранилище.', 'Vitamin item. Grants the following effects: MP +21, Poison resistance +40%, Poison attack rate +40%, Accuracy increase, Critical Damage increase, Hold resistance +30%, Hold attack rate +30%, Atk. and Casting Spd. increase. If a character wears two such rings, the effect applies only to one of them. Usable for 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'accessory_ring_of_baium_i00', 0);
INSERT INTO `all_items` VALUES (21208, 'Earring of Zaken', '30-day limited period', 'Витаминный предметДает следующие эффекты: MP +31, увеличение сопротивления кровотечению на 30%, увеличение шанса вызвать кровотечение цели на 30%, увеличение эффективности лечения, эффект Ярости Вампира, увеличение сопротивления шоку/аномальному состоянию на 20%, увеличение шанса вызвать шок/аномальное состояние цели на 20%. Если персонаж надевает две таких серьги, то эффект проявится только у одной из них. Можно использовать в течение 30 дней. Нельзя обменять/выбросить, но можно положить в личное хранилище.', 'Vitamin item. Grants the following effects: MP +31, Bleed resistance +30%, Bleed attack rate +30%, Heal effectiveness increase, Vampiric Rage effect, Shock/Abnormal State resistance +20%, Shock/Abnormal State attack rate +20%. If a character wears two such earrings, the effect applies only to one of them. Usable for 30 days. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'accessory_earring_of_zaken_i00', 0);
INSERT INTO `all_items` VALUES (21209, 'MP Recovery Potion Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 3 ед. Зелья Восстановления МР (+50%). Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 3 MP Recovery Potions (+50%). Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21210, 'MP Recovery Potion', NULL, 'Витаминный предметМагическое Зелье, при использовании мгновенно повышающее Макс. МР на 50%. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. A magic potion that instantly increases Max MP by 50% upon use. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_vitality_potion_i00', 24);
INSERT INTO `all_items` VALUES (21211, 'Vitality Replenishing Herb Tea Pack', NULL, 'Витаминная упаковкаПодарочная Коробка, содержащая 10 Отваров Всплеска Энергии. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin package. Gift box containing 10 Vitality Replenishing Potions. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'BranchSys.br_four_leaf_clover_box_i00', 0);
INSERT INTO `all_items` VALUES (21212, 'Vitality Replenishing Herb Tea', NULL, 'Витаминный предметНа 30 минут заряжает энергией при получении Очков Опыта посредством охоты. Нельзя обменять/выбросить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'Vitamin item. Charges Vitality when gaining EXP through hunting for 30 minutes. Cannot be traded or dropped, but can be shared among characters within the account via the Vitamin Manager or deposited into a personal warehouse.', 'etc_hot_spring_mineral_i00', 3);
