INSERT INTO `all_items` VALUES (21573, 'Plastic Hair', '7-day limited period', 'Витаминный предметПластиковый Парик. Очаровательный розовый парик для женщин и элегантный голубой парик для мужчин. Можно использовать 7 дней. Требует 2 ячейки головных уборов. Нельзя обменять/выбросить, но можно положить в личное хранилище.', '7-Day Limited Period	Dimensional ItemnPlastic hair. Changes into an attractive pink wig for females and a handsome blue wig for males. Can be used for 7 days. Uses 2 hair accessory slots. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys.br_plastic_hair_f_i00', 0);
INSERT INTO `all_items` VALUES (21574, 'Plastic Hair', '7-day limited period (event)', 'Витаминный предметПластиковый Парик. Очаровательный розовый парик для женщин и элегантный голубой парик для мужчин. Можно использовать 7 дней. Требует 2 ячейки головных уборов. Нельзя обменять, выбросить или разрушить, но можно положить в личное хранилище.', '7-Day Limited Period (event)	Dimensional ItemnPlastic hair. Changes into an attractive pink wig for females and a handsome blue wig for males. Can be used for 7 days. Uses 2 hair accessory slots. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'BranchSys.br_plastic_hair_f_i00', 0);
