INSERT INTO `all_items` VALUES (21741, 'Sword of Magic Fog', 'Event', 'Меч Магического Тумана Памяти Собирателя Письмен', 'Event	Letter Collector\'s Sword of Magic Fog of Memory', 'weapon_sword_of_magic_fog_i00', 1);
INSERT INTO `all_items` VALUES (21742, 'Bastard Sword*Bastard Sword', 'Event', 'Полуторный Меч*Полуторный Меч Памяти Собирателя Письмен', 'Event	Letter Collector\'s Bastars*Bastard of Memory', 'weapon_dual_sword_i00', 1);
INSERT INTO `all_items` VALUES (21743, 'Bich\'Hwa', 'Event', 'Бичхва Памяти Собирателя Письмен', 'Event	Letter Collector\'s Bich\'Hwa of Memory', 'weapon_bichhwa_i00', 1);
INSERT INTO `all_items` VALUES (21744, 'Katzbalger', 'Event', 'Кацбальгер Памяти Собирателя Письмен', 'Event	Letter Collector\'s Katzbalger of Memory', 'weapon_tulwar_i00', 1);
INSERT INTO `all_items` VALUES (21745, 'Arm Breaker', 'Event', 'Расчленитель Тьмы Памяти Собирателя Письмен', 'Event	Letter Collector\'s Arm Breaker of Memory', 'weapon_hunting_gun_i00', 1);
INSERT INTO `all_items` VALUES (21746, 'Maestro\'s Key', NULL, 'Позволяет открывать сундуки 21 – 85 уровней с вероятностью, составляющей 100%. В случае применения персонажами ниже 77 уровня к сундукам более чем на 6 уровней выше или персонажами выше 78 уровня к сундукам более чем на 5 уровней выше, ключ исчезает без возможности получения вознаграждения.', 'Allows opening chests of levels 21–85 with a 100% success rate. If used by characters below level 77 on chests more than 6 levels higher, or by characters above level 78 on chests more than 5 levels higher, the key disappears without granting a reward.', 'etc_old_key_i00', 0);
INSERT INTO `all_items` VALUES (21747, 'Beginner Adventurer\'s Treasure Sack', NULL, 'Содержит в себе сокровища для начинающего путешественника. При использовании можно заполучить оружие категории D~C.', 'Contains treasures for a beginner traveler. Using it grants D to C-grade weapons.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (21748, 'Experienced Adventurer\'s Treasure Sack', NULL, 'Содержит в себе сокровища для опытного путешественника. При использовании можно заполучить оружие категории B~S(кроме Династии).', 'Contains treasures for an experienced traveler. Using it grants B to S-grade weapons (except Dynasty).', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (21749, 'Great Adventurer\'s Treasure Sack', NULL, 'Содержит в себе сокровища для великого путешественника. При использовании можно заполучить оружие категории Династии~Венеры.', 'Contains treasures for a great traveler. Using it grants Dynasty to Vesper-grade weapons.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (21750, 'Blue Elmore Coin', NULL, 'Знак, получаемый путешественниками, исполнившими приказ короля Эльмора. При наличии знака можно получить награду у Капитана Рун Матиаса. Невозможно обменять или выбросить. Возможно хранить на личном складе.', 'A mark obtained by travelers who fulfilled the King of Elmore\'s order. With this mark, you can receive a reward from Captain Rune Mathias. Cannot be traded or dropped. Can be stored in a personal warehouse.', 'etc_coins_blue_i00', 0);
INSERT INTO `all_items` VALUES (21751, 'Rune Jewelry Box - Crystal', NULL, 'Шкатулка, содержащая сокровища Рун. При использовании можно получить с определенной вероятностью 15 кристаллов жизни.', 'Box containing Rune treasures. Using it grants a certain chance to obtain 15 Life Stones.', 'etc_treasure_box_i07', 0);
INSERT INTO `all_items` VALUES (21752, 'Rune Jewelry Box - Talisman', NULL, 'Шкатулка, содержащая сокровища Рун. При использовании можно получить с определенной вероятностью один талисман.', 'Box containing Rune treasures. Using it grants a certain chance to obtain one talisman.', 'etc_treasure_box_i06', 0);
INSERT INTO `all_items` VALUES (21753, 'Pablo\'s Box', NULL, 'Шкатулка, содержащая сокровища ученного Павлио, назначенного королем Эльмором. При использовании можно получить с определенной вероятностью шапку.', 'Box containing treasures of scholar Pavlio appointed by the King of Elmore. Using it grants a certain chance to obtain a hat.', 'etc_treasure_box_i01', 0);
INSERT INTO `all_items` VALUES (21754, 'Server Ziggi\'s Magic Pencil', NULL, 'Магический карандаш с острым концом. Выдается охранникам сервера. Невозможно обменять или выбросить. Возможно хранить на личном складе.', 'Magic pencil with a sharp tip. Provided to and only used by Pencil Corps. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys2.g_pencil_of_servermaster', 0);
INSERT INTO `all_items` VALUES (21755, 'Manor Scholar\'s Hat', NULL, 'Колпак - символ мудрости. С отделкой золотого цвета. Невозможно обменять или выкинуть. Можно хранить на личном складе.', 'Scholar\'s hat showing knowledge. Gold tassel is attached. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys2.g_graduation_cap_gold', 0);
INSERT INTO `all_items` VALUES (21756, 'Rank 1 Scholar\'s Hat', NULL, 'Колпак - символ мудрости. С отделкой белого цвета. Невозможно обменять или выкинуть. Можно хранить на личном складе.', 'Scholar\'s hat showing knowledge. Silver tassel is attached. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys2.g_graduation_cap_white', 0);
INSERT INTO `all_items` VALUES (21757, 'Rank 2 Scholar\'s Hat', NULL, 'Колпак - символ мудрости. С отделкой красного цвета. Невозможно обменять или выкинуть. Можно хранить на личном складе.', 'Scholar\'s hat showing knowledge. Red tassel is attached. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys2.g_graduation_cap_red', 0);
INSERT INTO `all_items` VALUES (21758, 'Rank 3 Scholar\'s Hat', NULL, 'Колпак - символ мудрости. С отделкой синего цвета. Невозможно обменять или выкинуть. Можно хранить на личном складе.', 'Scholar\'s hat showing knowledge. Blue tassel is attached. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'BranchSys2.g_graduation_cap_blue', 0);
INSERT INTO `all_items` VALUES (21759, 'Illumination - Red', NULL, 'Ярко сверкающая иллюминация', 'Brightly glowing illumination', 'BranchSys2.g_illumination_red', 0);
