INSERT INTO `all_items` VALUES (21768, 'Illumination - White', NULL, 'Ярко сверкающая иллюминация', 'Brightly glowing illumination', 'BranchSys2.g_illumination_white', 0);
INSERT INTO `all_items` VALUES (21769, 'Unrefined Ore', NULL, 'Необработанная руда. Необходим мастеру для изготовления драгоценных камней. Можно продать в магазин за определенную сумму денег.', 'Unrefined Ore. Needed by craftsmen to craft gemstones. Can be sold to stores for a certain amount of adena.', 'etc_stone_piece_i00', 0);
INSERT INTO `all_items` VALUES (21770, 'Unrefined Jewel', NULL, 'Необработанный самоцвет. Необходим мастеру для изготовления драгоценных камней. Можно продать в магазин за определенную сумму денег.', 'Raw gemstone. Required by masters to craft gemstones. Can be sold to a store for a certain amount of adena.', 'etc_vacualite_noglow_blue_i00', 0);
INSERT INTO `all_items` VALUES (21771, 'Jewel of Dusk', NULL, 'Самоцвет, обработанный при помощи древних технологий. Сильно сверкает. Можно продать в магазин за определенную сумму денег.', 'A gemstone processed using ancient technology. Sparkles brightly. Can be sold to a store for a certain amount of adena.', 'BranchSys2.g_twilight_gem', 0);
INSERT INTO `all_items` VALUES (21772, 'Jewel of Dawn', NULL, 'Самоцвет, обработанный при помощи древних технологий древним мастером. Сильно сверкает. Можно продать в магазин за определенную сумму денег.', 'A gemstone processed by an ancient master using ancient technology. Sparkles brightly. Can be sold to a store for a certain amount of adena.', 'BranchSys2.g_dawn_gem', 0);
INSERT INTO `all_items` VALUES (21773, 'Jewel of Splendor', NULL, 'Самоцвет, обработанный при помощи древних технологий древним мастером. Сильно сверкает. Можно продать в магазин за определенную сумму денег.', 'A gemstone processed by an ancient master using ancient technology. Sparkles brightly. Can be sold to a store for a certain amount of adena.', 'BranchSys2.g_brilliance_gem', 0);
INSERT INTO `all_items` VALUES (21774, 'Giant\'s Jewel', NULL, 'Самоцвет Великана, обработанный при помощи древних технологий древним мастером. Сильно сверкает. Можно продать в магазин за определенную сумму денег.', 'Giant\'s gemstone processed by an ancient master using ancient technology. Sparkles brightly. Can be sold to a store for a certain amount of adena.', 'BranchSys2.g_giant_gem', 0);
INSERT INTO `all_items` VALUES (21775, 'Imperial Crusader Breastplate of Fortune', '90-day limited period', 'Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно придавать свойства стихий.', '9-Day Limited Period	Cannot be exchanged or dropped. Can be stored in a private warehouse. Can be assigned an attribute.', 'armor_t88_u_i00', 0);
