INSERT INTO `all_items` VALUES (21779, 'Imperial Crusader Helmet of Fortune', '90-day limited period', 'Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно придавать свойства стихий.', '9-Day Limited Period	Cannot be exchanged or dropped. Can be stored in a private warehouse. Can be assigned an attribute.', 'armor_helmet_i00', 0);
INSERT INTO `all_items` VALUES (21780, 'Imperial Crusader Shield of Fortune', '90-day limited period', 'Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно придавать свойства стихий.', 'Cannot be traded or dropped, but can be deposited into a personal warehouse. Attribute can be added.', 'shield_imperial_crusader_shield_i00', 5);
INSERT INTO `all_items` VALUES (21781, 'Imperial Crusader of Fortune Set Pack (S-Grade)', '90-day limited period', 'При использовании выдается Эльфийский Комплект Латных Доспехов Имперского Крестоносца. Если не использовать, исчезнет через 90 дней. Нельзя обменять или выбросить, но можно положить в личное хранилище.', 'When used, grants an Elven Imperial Crusader Heavy Armor Set. Disappears after 90 days if unused. Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_equip_item_box_i02', 0);
INSERT INTO `all_items` VALUES (21782, 'Draconic Leather Armor of Fortune', '90-day limited period', 'Полный доспех. Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно придавать свойства стихий.', '9-Day Limited Period	One-piece Body Armor. Cannot be exchanged or dropped. Can be stored in a private warehouse. Can be assigned an attribute.', 'armor_t89_ul_i00', 0);
