INSERT INTO `all_items` VALUES (21971, 'Blood Brother - Great Gale {PvP}', 'Health', 'Редкий предмет, обладающий эффектом, повышающим скорость атаки<Свойство Кристалла Души>Двуручный меч, используемый Йоханом Кланикусом. Наделяет использующего особой силой. Увеличивает Макс. HP на 25%. Во время PvP увеличивается наносимый урон. При атаке с определенной вероятностью наносит дополнительный урон.', 'Health	Masterwork Item than increases Atk. Spd.n<Soul Crystal Enhancement>nTwo-handed sword used by Yehan Klodekus. Bestows a special power upon the wielder. Increases Max HP by 25%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'BranchSys2.br_wp_tirbing_i01', 5);
INSERT INTO `all_items` VALUES (21972, 'Blood Brother - Great Gale {PvP}', 'Light', 'Редкий предмет, обладающий эффектом, повышающим скорость атаки<Свойство Кристалла Души>Двуручный меч, используемый Йоханом Кланикусом. Наделяет использующего особой силой. Увеличивает Лимит Веса на 20%. Во время PvP увеличивается наносимый урон. При атаке с определенной вероятностью наносит дополнительный урон.', 'Light	Masterwork Item than increases Atk. Spd.n<Soul Crystal Enhancement>nTwo-handed sword used by Yehan Klodekus. Bestows a special power upon the wielder. Increases Weight Gauge by 2%. Increases damage inflicted during PvP. Has a chance of inflicting additional damage during an attack.', 'BranchSys2.br_wp_tirbing_i01', 5);
INSERT INTO `all_items` VALUES (21973, 'Mardil\'s Fan', NULL, 'Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Маг. Сила, Безмолвие или Проницательность.', 'Magic fan used by Mardil. Bestows a special power upon the wielder. Bestows one of the following functions: M. Atk., Magic Silence or Acumen.', 'BranchSys2.br_wp_wind_of_mardil_i00', 4);
INSERT INTO `all_items` VALUES (21974, 'Mardil\'s Fan', 'M. Atk.', '<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. При использовании магии на 15% увеличивается затрачиваемые MP. Маг. Сила увеличивается на 167. Во время PvP увеличивается наносимый урон.', 'M. Atk.	a,<Soul Crystal Enhancement>nMagic fan used by Mardil. Bestows a special power upon the wielder. Increases MP consumption by 15% and M. Atk. by 167 during magic use. Increases damage inflicted during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
INSERT INTO `all_items` VALUES (21975, 'Mardil\'s Fan', 'Magic Silence', '<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. При использовании магических умений на противника, с вероятностью в 10% наводит Безмолвие. Во время PvP увеличивается наносимый урон.', 'Magic Silence	a,<Soul Crystal Enhancement>nMagic fan used by Mardil. Bestows a special power upon the wielder. Inflicts Silence on the target with a 1% chance during magic use. Increases damage inflicted during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
INSERT INTO `all_items` VALUES (21976, 'Mardil\'s Fan', 'Acumen', '<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. Увеличивает скорость наведения чар на 15%. Во время PvP увеличивается наносимый урон.', 'Acumen	a,<Soul Crystal Enhancement>nMagic fan used by Mardil. Bestows a special power upon the wielder. Increases Casting Spd. by 15%. Increases damage inflicted during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
INSERT INTO `all_items` VALUES (21977, 'Mardil\'s Fan - Holy Spirit', NULL, 'Редкий предмет, обладающий эффектом усиления целительных уменийВолшебный веер, используемый Мардиллом. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Маг. Сила, Безмолвие или Проницательность.', 'Masterwork Item that increases heal amount.nMagic fan used by Mardil. Bestows a special power upon the wielder. Bestows one of the following functions: M. Atk., Magic Silence or Acumen.', 'BranchSys2.br_wp_wind_of_mardil_i00', 4);
INSERT INTO `all_items` VALUES (21978, 'Mardil\'s Fan - Holy Spirit', 'M. Atk.', 'Редкий предмет, обладающий эффектом усиления целительных умений<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. При использовании магии на 15% увеличивается затрачиваемые MP. Маг. Сила увеличивается на 167. Во время PvP увеличивается наносимый урон.', 'M. Atk.	Masterwork Item that increases heal amount.n<Soul Crystal Enhancement>nMagic fan used by Mardil. Bestows a special power upon the wielder. Increases MP consumption by 15% and M. Atk. by 167 during magic use. Increases damage inflicted during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
INSERT INTO `all_items` VALUES (21979, 'Mardil\'s Fan - Holy Spirit', 'Magic Silence', 'Редкий предмет, обладающий эффектом усиления целительных умений<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. При использовании магических умений на противника, с вероятностью в 10% наводит Безмолвие. Во время PvP увеличивается наносимый урон.', 'Magic Silence	Masterwork Item that increases heal amount.n<Soul Crystal Enhancement>nMagic fan used by Mardil. Bestows a special power upon the wielder. Inflicts Silence on the target with a 1% chance during magic use. Increases damage inflicted during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
INSERT INTO `all_items` VALUES (21980, 'Mardil\'s Fan - Holy Spirit', 'Acumen', 'Редкий предмет, обладающий эффектом усиления целительных умений<Свойство Кристалла Души> Волшебный веер, используемый Мардиллом. Наделяет использующего особой силой. Увеличивает скорость наведения чар на 15%. Во время PvP увеличивается наносимый урон.', 'A rare item with a healing skill enhancement effect.<Soul Crystal Effect> A magic fan used by Mardil. Grants the wielder special power. Increases casting speed by 15%. Increases damage dealt during PvP.', 'BranchSys2.br_wp_wind_of_mardil_i01', 4);
