INSERT INTO `all_items` VALUES (21993, 'Lavasaurus Alpha Fragment', NULL, 'Часть Старейшего Лавазавра. Необходимо отнести стражу Валакаса Клейну.', 'Part of an Ancient Lavasaurus. Must be taken to Valakas Guardian Klein.', 'etc_broken_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (21994, 'Vitality Replenishing Beverage - Pack of 9', NULL, 'Витаминная упаковкаУпаковка, содержащая Напитки Всплеска Энергии (9 шт.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitamin package. Package containing Vitality Replenishing Drinks (9 pcs.). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (21995, 'Vitality Replenishing Beverage - Pack of 12', NULL, 'Витаминная упаковкаУпаковка, содержащая Напитки Всплеска Энергии (12 шт.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitamin package. Package containing Vitality Replenishing Drinks (12 pcs.). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (21996, 'Vitality Replenishing Beverage - Pack of 15', NULL, 'Витаминная упаковкаУпаковка, содержащая Напиток Всплеска Энергии (15 шт.). Нельзя обменять или выбросить, можно положить в личное хранилище.', 'Vitamin package. Package containing Vitality Replenishing Drinks (15 pcs.). Cannot be traded or dropped, but can be deposited into a personal warehouse.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (21997, 'Shattered Bones', NULL, 'Осколок кости, который можно получить у Орков Кетра и Фавнов Варка. Необходимо отнести Капитану стражи Руны Матиасу.', 'A bone shard obtainable from Ketra Orcs and Varka Silenos. Must be taken to Rune Guard Captain Mathias.', 'etc_broken_crystal_gold_i00', 0);
INSERT INTO `all_items` VALUES (21998, 'Cannibalistic Stakato Leader Claw', NULL, 'Коготь Командира Каннибалов Стакато. Необходимо отнести Капитану стражи Руны Матиасу.', 'Claw of a Cannibal Stakato Commander. Must be taken to Rune Guard Captain Mathias.', 'etc_parasite_i00', 0);
INSERT INTO `all_items` VALUES (21999, 'Anais Scroll', NULL, 'Волшебный Свиток Анаиса. Необходимо отнести Капитану стражи Руны Матиасу.', 'Anais\' Magic Scroll. Must be taken to Rune Guard Captain Mathias.', 'BranchSys2.g_ancient_book_piece_high', 0);
INSERT INTO `all_items` VALUES (22000, 'Small fortuna box', NULL, 'Дает шанс получить Древний Кристалл: Модифицировать Оружие или Свиток: Модифицировать Оружие с шансом успешной модификации +10%. Нельзя обменять или выбросить.', 'Grants a chance to obtain an Ancient Crystal: Enchant Weapon or a Scroll: Enchant Weapon with a +10% success rate. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_box_i00', 0);
INSERT INTO `all_items` VALUES (22001, 'Middle fortuna box', NULL, 'Дает шанс получить Древний Кристалл: Модифицировать Оружие высокого ранга или Свиток: Модифицировать Оружие с шансом успешной модификации +10%. Нельзя обменять или выбросить.', 'Grants a chance to obtain a High-grade Ancient Crystal: Enchant Weapon or a Scroll: Enchant Weapon with a +10% success rate. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_box_i00', 0);
INSERT INTO `all_items` VALUES (22002, 'Large fortuna box', NULL, 'Дает шанс получить Священный Кристалл: Модифицировать Оружие или Древний Кристалл: Модифицировать Оружие высокого ранга. Нельзя обменять или выбросить.', 'Grants a chance to obtain a Holy Crystal: Enchant Weapon or a High-grade Ancient Crystal: Enchant Weapon. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_box_i00', 0);
INSERT INTO `all_items` VALUES (22003, 'Small fortuna cube', NULL, 'Дает шанс получить Древний Кристалл: Модифицировать Доспех или Свиток: Модифицировать Доспех с шансом успешной модификации +10%. Нельзя обменять или выбросить.', 'Grants a chance to obtain an Ancient Crystal: Enchant Armor or a Scroll: Enchant Armor with a +10% success rate. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_cube_i00', 0);
INSERT INTO `all_items` VALUES (22004, 'Middle fortuna cube', NULL, 'Дает шанс получить Древний Кристалл: Модифицировать Доспех высокого ранга или Свиток: Модифицировать Доспех с шансом успешной модификации +10%. Нельзя обменять или выбросить.', 'Grants a chance to obtain a High-grade Ancient Crystal: Enchant Armor or a Scroll: Enchant Armor with a +10% success rate. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_cube_i00', 0);
INSERT INTO `all_items` VALUES (22005, 'Large fortuna cube', NULL, 'Дает шанс получить Священный Кристалл: Модифицировать Доспех или Древний Кристалл: Модифицировать Доспех высокого ранга. Нельзя обменять или выбросить.', 'Grants a chance to obtain a Holy Crystal: Enchant Armor or a High-grade Ancient Crystal: Enchant Armor. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_lucky_cube_i00', 0);
INSERT INTO `all_items` VALUES (22006, 'Scroll: Enchant Weapon (C-Grade)', NULL, 'Шанс успешной модификации увеличен на 10%.Одноручное и двуручное оружие: Физ. Атк. +2. Лук: Физ. Атк. +4. Все оружие: Маг. Атк. +3. При улучшении оружия до +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасное улучшение: +3. Нельзя обменять/выбросить.', 'Enchant success rate increased by 10%. One-handed and two-handed weapons: P. Atk. +2. Bow: P. Atk. +4. All weapons: M. Atk. +3. When enchanting weapons to +4 and higher, the P. Atk. and M. Atk. bonuses are doubled. Safe enchant: +3. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_scrl_of_ench_wp_d_i00', 19);
INSERT INTO `all_items` VALUES (22007, 'Scroll: Enchant Weapon (C-Grade)', NULL, 'Шанс успешной модификации увеличен на 10%.Одноручное и двуручное оружие: Физ. Атк. +2. Лук: Физ. Атк. +4. Все оружие: Маг. Атк. +3. При улучшении оружия до +4 и выше бонус к Ф. Атк. и М. Атк. удваивается. Безопасное улучшение: +3. Нельзя обменять/выбросить.', 'Enchant success rate increased by 10%. One-handed and two-handed weapons: P. Atk. +2. Bow: P. Atk. +4. All weapons: M. Atk. +3. When enchanting weapons to +4 and higher, the P. Atk. and M. Atk. bonuses are doubled. Safe enchant: +3. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_scrl_of_ench_wp_c_i00', 19);
