INSERT INTO `all_items` VALUES (22022, 'High grade potion which improves attack speed', NULL, 'Магическое зелье, увеличивающее Скор. Атк. на 33%. Очень легкое. Нельзя обменять/выбросить/продать.', 'A magic potion that increases Atk. Spd. by 33%. Very light. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_adv_swift_attack_potion_i00', 3);
