INSERT INTO `all_items` VALUES (22027, 'Secret medicine of Will (C-Grade)', NULL, 'Восстанавливает CP. Использовать могут только персонажи выше 20 уровня и ниже 39 уровня. Возможность быстрого повторного использования. Нельзя обменять/выбросить.', 'Restores CP. Usable only by characters above level 20 and below level 39. Short reuse delay. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_elixir_of_combative_d_i00', 24);
