INSERT INTO `all_items` VALUES (22045, 'Empower Scroll', NULL, 'Увеличивает Маг. Атк. на 75%. Нельзя обменять/выбросить/продать.', 'Increases M. Atk. by 75%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_empower_i00', 1);
INSERT INTO `all_items` VALUES (22046, 'Grater Acumen Scroll', NULL, 'Уменьшает время чтения заклинаний на 30%. Нельзя обменять/выбросить/продать.', 'Decreases casting time by 30%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_greater_acumen_i00', 1);
INSERT INTO `all_items` VALUES (22047, 'Vampiric Rage Scroll', NULL, 'Возвращает 9% HP от нанесенного физического урона противнику. Нельзя обменять/выбросить/продать.', 'Restores 9% of physical damage dealt to the enemy as HP. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_vampiric_rage_i00', 1);
INSERT INTO `all_items` VALUES (22048, 'Bless the Body Scroll', NULL, 'Увеличивает HP на 35%. Нельзя обменять/выбросить/продать.', 'Increases HP by 35%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_bless_the_body_i00', 1);
INSERT INTO `all_items` VALUES (22049, 'Berserker Spirit Scroll', NULL, 'Снижает у всех членов группы Физ. Защ. на 8%, Маг. Защ. на 16% и Уклонение  на 4, но увеличивает атаку на 8%, магическую атаку  на 16%, Скор. Атк.  на 8% и Скор. Передвижения на 8%. Нельзя обменять/выбросить/продать.', 'Decreases P. Def. by 8%, M. Def. by 16%, and Evasion by 4 for all party members, but increases attack by 8%, magic attack by 16%, Atk. Spd. by 8%, and Movement Speed by 8%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_berserker_spirit_i00', 1);
INSERT INTO `all_items` VALUES (22050, 'Magic Barrier Scroll', NULL, 'Увеличивает Маг. Защ. на 30%. Нельзя обменять/выбросить/продать.', 'Increases M. Def. by 30%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_magic_barrier_i00', 1);
INSERT INTO `all_items` VALUES (22051, 'Bless the Soul Scroll', NULL, 'Увеличивает Макс. MP на 35%. Нельзя обменять/выбросить/продать.', 'Increases Max MP by 35%. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_bless_the_soul_i00', 1);
INSERT INTO `all_items` VALUES (22052, 'Clarity Scroll', NULL, 'Уменьшает расход MP во время чтения заклинаний на 10%, использования физических умений на 20% и песен/танцев на 20%. Нельзя обменять/выбросить/продать.', 'Reduces MP consumption by 10% for spellcasting, 20% for physical skills, and 20% for songs/dances. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_clarity_i00', 1);
INSERT INTO `all_items` VALUES (22053, 'Wild Magic Scroll', NULL, 'Увеличивает шанс Крит. Атк. магией на 2. Нельзя обменять/выбросить/продать.', 'Increases magic Critical Rate by 2. Cannot be traded, dropped, or sold.', 'br_cashtex.item.br_cash_scroll_of_wild_magic_i00', 1);
INSERT INTO `all_items` VALUES (22054, 'Rune of Experience Points', '24-hour limited period', 'Этот символ хранит силу древних. При наличии в инвентаре увеличивает получаемые очки опыта на 10%. Максимально можно увеличить данный показатель на 50%. При  выходе из игры время использования продолжает уменьшаться. Обмен или возврат невозможен.  Нельзя обменять/выбросить.', 'This symbol holds the power of the ancients. When kept in the inventory, increases acquired EXP by 10%. Can be increased by a maximum of 50%. Usage time continues to decrease even when logged out. Cannot be traded or refunded. Cannot be traded or dropped.', 'br_cashtex.item.br_cash_rune_of_exp_i00', 34);
