INSERT INTO `all_items` VALUES (22067, 'Bone Arrow', NULL, 'Стрела, изготовленная из заостренной кости. Может быть использована с луками Ранга D. Очень легкая. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'An arrow made from pointed bone. Can be used with D-grade bows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_bone_arrow_i00', 2);
INSERT INTO `all_items` VALUES (22068, 'Steel Arrow', NULL, 'Стрела, изготовленная из стали. Может быть использована с луками Ранга C. Очень легкая. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'An arrow made of steel. Can be used with C-grade bows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_fine_steel_arrow_i00', 2);
INSERT INTO `all_items` VALUES (22069, 'Silver Arrow', NULL, 'Стальная стрела, покрытая серебром. Может быть использована с луками Ранга B. Очень легкая. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A silver-plated steel arrow. Can be used with B-grade bows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_silver_arrow_i00', 2);
INSERT INTO `all_items` VALUES (22070, 'Mithril Arrow', NULL, 'Стальная стрела, покрытая мифрилом. Может быть использована с луками Ранга A. Очень легкая. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A mithril-plated steel arrow. Can be used with A-grade bows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_mithril_arrow_i00', 2);
INSERT INTO `all_items` VALUES (22071, 'Arrow of Light', NULL, 'Лучшая стрела из неизвестного материала. Может быть использована с луками Ранга S. Очень легкая. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A superior arrow made of unknown material. Can be used with S-grade bows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_shining_arrow_i00', 2);
