INSERT INTO `all_items` VALUES (22144, 'Bone Bolt', NULL, 'Болт, изготовленный из заостренной кости. Предназначен для арбалетов Ранга D. Очень легкий. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A bolt made from pointed bone. Designed for D-grade crossbows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_bone_bolt_i00', 26);
INSERT INTO `all_items` VALUES (22145, 'Steel Bolt', NULL, 'Болт, изготовленный из стали. Предназначен для арбалетов Ранга C. Очень легкий. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A bolt made of steel. Designed for C-grade crossbows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_fine_steel_bolt_i00', 26);
INSERT INTO `all_items` VALUES (22146, 'Silver Bolt', NULL, 'Стальной болт, покрытый серебром. Предназначен для арбалетов Ранга B. Очень легкий. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A silver-plated steel bolt. Designed for B-grade crossbows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_silver_bolt_i00', 26);
INSERT INTO `all_items` VALUES (22147, 'Mithril Bolt', NULL, 'Стальной болт, покрытый мифрилом. Предназначен для арбалетов Ранга A. Очень легкий. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A mithril-plated steel bolt. Designed for A-grade crossbows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_mithril_bolt_i00', 26);
INSERT INTO `all_items` VALUES (22148, 'Bolt of Light', NULL, 'Лучший болт из неизвестного материала. Предназначен для арбалетов Ранга S. Очень легкий. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'A superior bolt made of unknown material. Designed for S-grade crossbows. Very light. Cannot be traded, dropped, or sold, but can be deposited into a personal warehouse.', 'br_cashtex.item.br_cash_shining_bolt_i00', 26);
