INSERT INTO `all_items` VALUES (22168, 'Rabbit Ear', NULL, 'Головной аксессуар в виде ушек кролика. Нельзя обменять/выбросить.', 'Bonny Girls Rabbit Ear shaped hair accessory. Cannot be exchanged or dropped.', 'accessory_rabbit_ear_i00', 0);
INSERT INTO `all_items` VALUES (22169, 'Little Angel Wings', NULL, 'Головной аксессуар в виде маленького белого крыла. Нельзя обменять/выбросить.', 'Wings shaped hair accessory. Cannot be exchanged or dropped.', 'accessory_hair_ring_i00', 0);
INSERT INTO `all_items` VALUES (22170, 'Fairy\'s Tentacle', NULL, 'Миловидный головной аксессуар в виде антенок со звездочками. Нельзя обменять/выбросить.', 'A cute head accessory in the shape of star antennae. Cannot be traded or dropped.', 'accessory_hair_feeler_i00', 0);
INSERT INTO `all_items` VALUES (22171, 'Dandy\'s Chapeau', NULL, 'Элегантная шляпа, украшенная перьями. Занимает 2 ячейки в головных аксессуарах. Нельзя обменять/выбросить.', 'Handsome hat with an attached feather. Uses 2 hair accessory slots. Cannot be exchanged or dropped.', 'accessory_archer_hat_i00', 0);
INSERT INTO `all_items` VALUES (22172, 'Artisan\'s Goggles', NULL, 'Большие очки для защиты глаз. Занимают 2 ячейки в головных аксессуарах. Нельзя обменять/выбросить.', 'Large goggles that protect the eyes. Uses 2 hair accessory slots. Cannot be exchanged or dropped.', 'accessory_dwarf_goggle_i00', 0);
INSERT INTO `all_items` VALUES (22173, 'Improved Ring of Baium', NULL, 'MP +21, сопротивление отравлению +40%, шанс отравить +40%, увеличение силы Крит. Атк., сопротивление удержанию +30%, шанс удержать +30%, Физ. Атк. и Маг. Атк. При надевании двух одинаковых колец эффект не суммируется', 'MP +21, Resistance to Poison +4%, Poison Atk. Rate +4%, Resistance to Hold +3%, Hold Atk. Rate +3%. Increases Accuracy, P. Critical Damage, P. Atk., and Casting Spd. Only one effect is applied when wearing two of the same ring.', 'accessory_ring_of_baium_i00', 0);
INSERT INTO `all_items` VALUES (22174, 'Improved Ring of Queen Ant', NULL, 'MP +21, сопротивление отравлению +30%, шанс отравить +30%, увеличение шанса и силы Крит. Атк., сопротивление удержанию +20%, шанс удержать +20%. При надевании двух одинаковых колец эффект не суммируется', 'MP +21, Resistance to Poison +3%, Poison Atk. Rate +3%, Resistance to Hold +2%, Hold Atk. Rate +2%. Increases Accuracy and P. Critical Damage. Only one effect is applied when wearing two of the same ring.', 'accessory_ring_of_queen_ant_i00', 0);
INSERT INTO `all_items` VALUES (22175, 'Improved Blessed Earring of Zaken', NULL, 'MP +37, сопротивление кровотечению +30%, шанс кровопускания +30%, усиление целительных умений +15%, эффект Ярости Вампира, сопротивление шоковым/ментальной атакам +30%, защита от Тьмы +15. При использовании двух серьг эффективна толька одна. При надевании вместе с обычной серьгой Закена эффективна только Серьга Бессмертного Закена.', 'MP +37, Resistance to Bleed +3%, Bleed Atk. Rate +3%, heal amount +15%, Vampiric Rage effect, Resistance to Shock/Metal attacks +3%, Shock/Metal Atk. Rate +3%, and Resistance to Dark +15. Only one effect is applied even when the same two earrings are worn. If it is equipped together with a standard Earring of Zaken, only the effect of Blessed Earring of Zaken will be applied.', 'accessory_earring_of_zaken_i00', 0);
INSERT INTO `all_items` VALUES (22176, 'Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Кролика-Хулигана. Можно получить апиги, сняв усталость Кролика-Хулигана (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'Hooligan Rabbit Summon Scroll. You can obtain agathions by relieving the Hooligan Rabbit\'s fatigue (recovery is possible only by using Cupid\'s Medicine and Potent Cupid\'s Medicine).', 'BranchSys2.icon2.g_ev_rabbit', 1);
INSERT INTO `all_items` VALUES (22177, 'Fearless Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Бесполезного Кролика. Во время восстановления он может превратиться в Наглого Кролика (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'Useless Rabbit Summon Scroll. While recovering, it may transform into a Naughty Rabbit (recovery is possible only by using Cupid\'s Medicine and Potent Cupid\'s Medicine).', 'BranchSys2.icon2.g_ev_rabbit', 1);
INSERT INTO `all_items` VALUES (22178, 'Large Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Вожака Кроликов-Хулиганов. Можно получить апиги, сняв усталость Вожака Кроликов-Хулиганов (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'Hooligan Rabbit Leader Summon Scroll. You can obtain agathions by relieving the Hooligan Rabbit Leader\'s fatigue (recovery is possible only by using Cupid\'s Medicine and Potent Cupid\'s Medicine).', 'BranchSys2.icon2.g_ev_rabbit_boss', 1);
INSERT INTO `all_items` VALUES (22179, 'Large Fearless Bunny Lure Scroll', 'Event', 'Свиток призыва Вожака Бесполезных Кроликов. Во время восстановления Вожака Бесполезных Кроликов может превратиться в Вожака Наглых Кроликов (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'Useless Rabbit Leader Summon Scroll. During the recovery of the Useless Rabbit Leader, it may transform into a Naughty Rabbit Leader (recovery is possible only by using Cupid\'s Medicine and Potent Cupid\'s Medicine).', 'BranchSys2.icon2.g_ev_rabbit_boss', 1);
INSERT INTO `all_items` VALUES (22180, 'Bunny Anger Management Kit', 'Event', 'Ивентовая упаковка, которую можно получить один раз в 12 часов на каждый аккаунт. При двойном нажатии можно получить необходимый свиток вызова Кролика-Хулигана, а также Лекарство Купидона. Нельзя обменять/выбросить. Можно положить в личное хранилище.', 'Event package obtainable once every 12 hours per account. Double-clicking grants the necessary Hooligan Rabbit summon scroll and Cupid\'s Medicine. Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'etc_jewel_box_i00', 0);
INSERT INTO `all_items` VALUES (22181, 'Bunny Pacifier Juice', 'Event', 'Снимает усталость кролика.', 'Relieves rabbit fatigue.', 'etc_faitgue_relief_of_cupid_i00', 24);
INSERT INTO `all_items` VALUES (22182, 'Improved Bunny Pacifier Juice', 'Event', 'Снимает усталость кролика эффективнее, чем лекарство Купидона.', 'Relieves rabbit fatigue more effectively than Cupid\'s Medicine.', 'etc_nutrients_of_cupid_i00', 24);
INSERT INTO `all_items` VALUES (22183, 'Graduation Cap', NULL, 'Колпак Выпускника. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'Graduation Cap. Uses 2 hair accessory slots. Cannot be exchanged, dropped, or sold.', 'accessory_graduation_cap_i00', 0);
INSERT INTO `all_items` VALUES (22184, 'Admiral\'s Hat', NULL, 'Изящная шляпа, украшенная золотом. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'Admiral\'s Hat. Uses 2 hair accessory slots. Cannot be exchanged, dropped, or sold.', 'Accessary_middle_ages_i01', 0);
INSERT INTO `all_items` VALUES (22185, 'Illumination - Yellow', NULL, 'Яркая иллюминация', 'Bright illumination', 'BranchSys2.g_illumination_yellow', 0);
INSERT INTO `all_items` VALUES (22186, 'Cat the Ranger Summon Necklace Exchange Coupon', NULL, 'Купон на ожерелье (5 часов) призыва Кота-Рейнджера. Невозможно обменять/выбросить. Можно передавать через Менеджера Витаминов. Можно положить в личное хранилище.', 'Coupon for Ranger Cat summon necklace (5 hrs.). Cannot be traded or dropped. Can be transferred via the Vitamin Manager. Can be deposited into a personal warehouse.', 'etc_ticket_red_i00', 0);
INSERT INTO `all_items` VALUES (22187, 'Birthday Present Pack', NULL, 'Подарок на день рождения, выдаваемый Аллегрией. При использовании можно получить 3 порции энергии радости, Торт Именинника, а также колпак. Обменять и выбросить невозможно. Можно положить в личное хранилище.', 'Birthday gift issued by Allegria. When used, grants 3 portions of joy energy, a Birthday Cake, and a party hat. Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'event_hero_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (22188, 'Birthday Vitality Potion', NULL, 'При использовании в течение 4 часов восстанавливает энергию после получения опыта во время охоты. Обменять и выбросить невозможно. Можно положить в личное хранилище.', 'When used for 4 hours, restores Vitality after gaining EXP during hunting. Cannot be traded or dropped. Can be deposited into a personal warehouse.', 'etc_potion_blue_i00', 3);
INSERT INTO `all_items` VALUES (22189, 'Child\'s Hat - Boy', NULL, 'Детская шапочка для мальчиков. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'Taiwanese child exclusive hat (boy). Uses 2 hair accessory slots. Cannot be exchanged, dropped, or sold. Item that can be stored in a private warehouse.', 'BranchSys2.br_hat_for_boy_i00', 0);
INSERT INTO `all_items` VALUES (22190, 'Child\'s Hat - Girl', NULL, 'Детская шапочка для девочек. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'Children\'s cap for girls. Requires 2 hair accessory slots. Cannot be traded, dropped, or sold.', 'BranchSys2.br_hat_for_girl_i00', 0);
INSERT INTO `all_items` VALUES (22191, 'Rocking Horse Mount Bracelet', '7-day limited period', 'Витаминный предметПри использовании позволяет оседлать Коня-Качалку. Можно использовать в течении 7 дн. Невозможно обменять/выбросить. Можно положить в личное хранилище.', '7-Day Limited Period	Dimensional ItemnCan mount a Rocking Horse when equipped. Can be used for 7 days. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'branchsys2.g_wooen_house', 0);
INSERT INTO `all_items` VALUES (22192, 'Rocking Horse Mount Bracelet', '30-day limited period', 'Витаминный предметПри использовании позволяет оседлать Коня-Качалку. Можно использовать в течении 30 дн. Невозможно обменять/выбросить. Можно положить в личное хранилище.', '3-Day Limited Period	Dimensional ItemnCan mount a Rocking Horse when equipped. Can be used for 3 days. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'branchsys2.g_wooen_house', 0);
INSERT INTO `all_items` VALUES (22193, 'Rocking Horse Mount Bracelet', NULL, 'Витаминный предметПри использовании позволяет оседлать Коня-Качалку. Невозможно обменять/выбросить. Можно положить в личное хранилище.', 'Dimensional ItemnCan mount a Rocking Horse when equipped. Cannot be exchanged or dropped. Can be stored in a private warehouse.', 'branchsys2.g_wooen_house', 0);
INSERT INTO `all_items` VALUES (22194, '1st Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 1 место.', 'Double-clicking grants 1st place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22195, '2nd Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 2 место.', 'Double-clicking grants 2nd place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22196, '3rd Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 3 место.', 'Double-clicking grants 3rd place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22197, '4th Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 4 место.', 'Double-clicking grants 4th place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22198, '5th Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 5 место.', 'Double-clicking grants 5th place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22199, '6th Place Treasure Sack', NULL, 'При двойном нажатии с определенной вероятностью выдаются призы за 6 место.', 'Double-clicking grants 6th place prizes with a certain chance.', 'BranchSys2.etc_ancient_treasure_sack_i00', 0);
INSERT INTO `all_items` VALUES (22200, 'Agathion Seal Bracelet - Lantern', '33-day limited period (event)', 'Браслет, призывающий Сияющего Агатиона. Чтобы получить подарок Сияющего Агатиона, в инвентаре должно быть свободное место. Обменять/выбросить/уничтожить невозможно. Можно положить в личное хранилище.', 'Bracelet that summons a Radiant Agathion. To receive the Radiant Agathion gift, your inventory must have free space. Cannot be traded, dropped, or destroyed. Can be deposited into a personal warehouse.', 'BranchSys2.event_agathion_han_i00', 0);
INSERT INTO `all_items` VALUES (22201, 'Lantern Agathion Pack', 'Event', 'Откройте упаковку двойным щелчком мыши, чтобы получить Сияющего Агатиона. Нельзя обменять, уничтожить. Можно положить в личное хранилище.', 'Open the package with a double-click to obtain a Radiant Agathion. Cannot be traded or destroyed. Can be deposited into a personal warehouse.', 'etc_pi_gift_box_i03', 0);
INSERT INTO `all_items` VALUES (22202, 'S84 Weapon Box', 'Event', 'Ящик с оружием ранга S84. Интересно, каким именно?', 'S84-grade weapon box. Wonder which one it is?', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (22203, 'Vorpal Armor Box', 'Event', 'Ящик с доспехом Верпеса. Интересно, каким именно?', 'Vesper armor box. Wonder which one it is?', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (22204, 'Attribute Stone Box', 'Event', 'Ящик с Камнем одной из стихий. Интересно, каким именно?', 'Attribute stone box. Wonder which one it is?', 'etc_pi_gift_box_i04', 0);
