INSERT INTO `all_items` VALUES (22283, 'Trejuo Transformation Stick', '7-day limited period (event)', 'Stick that transforms you into the Blessed Child Trejuo. The transformation ends when you de-equip the item. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse. Special skill re-use delay is 4 hour(s).', '7-Day Limited Period (event)	Stick that transforms you into a the Blessed Child Trejuo. The transformation ends when you de-equip the item. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse. Special skill cooldown is 4 hours.', 'BranchSys2.br_blessed_taiboy_i00', 0);
