INSERT INTO `all_items` VALUES (22305, 'Baium\'s Ring', '7-day limited period (event)', 'MP +21, resistance to Poison +40%, Poison attack rate +40%, resistance to Hold +30%, Hold attack rate +30%, and increases Accuracy, Critical Damage, P. Atk., and Casting Spd. Only one effect is applied when two of the same ring are equipped.', 'MP +21, resistance to Poison +40%, Poison attack rate +40%, resistance to Hold +30%, Hold attack rate +30%, and increases Accuracy, Critical Damage, P. Atk., and Casting Spd. Only one effect is applied when two of the same ring are equipped.', 'accessory_ring_of_baium_i00', 0);
INSERT INTO `all_items` VALUES (22306, 'Scroll: Enchant Weapon (S-Grade)', 'Event', 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'etc_scroll_of_enchant_weapon_i05', 19);
INSERT INTO `all_items` VALUES (22307, 'Scroll: Enchant Weapon (A-Grade)', 'Event', 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'etc_scroll_of_enchant_weapon_i04', 19);
INSERT INTO `all_items` VALUES (22308, 'Scroll: Enchant Armor (S-Grade)', 'Event', 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'etc_scroll_of_enchant_armor_i05', 20);
INSERT INTO `all_items` VALUES (22309, 'Scroll: Enchant Armor (A-Grade)', 'Event', 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'etc_scroll_of_enchant_armor_i04', 20);
