INSERT INTO `all_items` VALUES (22314, 'Blessed Scroll: Enchant Weapon (S-Grade)', NULL, 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_s_i05', 21);
INSERT INTO `all_items` VALUES (22315, 'Blessed Scroll: Enchant Armor (S-Grade)', NULL, 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_am_s_i05', 22);
INSERT INTO `all_items` VALUES (22316, 'Blessed Scroll: Enchant Weapon (A-Grade)', NULL, 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_a_i04', 21);
INSERT INTO `all_items` VALUES (22317, 'Blessed Scroll: Enchant Weapon (B-Grade)', NULL, 'Increases P. Atk. by 3 for B-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 4 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 6 for bow weapons. Increases M. Atk. by 3 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Increases P. Atk. by 3 for B-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 4 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 6 for bow weapons. Increases M. Atk. by 3 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_b_i03', 21);
INSERT INTO `all_items` VALUES (22318, 'Blessed Scroll: Enchant Armor (A-Grade)', NULL, 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_am_a_i04', 22);
