INSERT INTO `all_items` VALUES (22333, 'Hero\'s Treasure Chest', NULL, 'Chest containing an equipment set pack which can be used for 90 days. Cannot be exchanged or dropped.', 'Chest containing an equipment set pack which can be used for 90 days. Cannot be exchanged or dropped.', 'event_hero_treasure_box_i00', 0);
INSERT INTO `all_items` VALUES (22334, 'Rune of Experience Points 50%', '1 hours limited time', 'Ancient characters that bestow a mysterious ability when possessed in the inventory. Increases acquired Exp. by 50%. The remaining period decreases even while logged off. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'Ancient characters that bestow a mysterious ability when possessed in the inventory. Increases acquired Exp. by 50%. The remaining period decreases even while logged off. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'br_cashtex.item.br_cash_rune_of_exp_i00', 33);
INSERT INTO `all_items` VALUES (22335, 'Essence of Destruction', NULL, 'An item filled with the essence of Shilen\'s followers that you have defeated.', 'An item filled with the essence of Shilen\'s followers that you have defeated.', 'etc_crystal_blue_i00', 0);
INSERT INTO `all_items` VALUES (22336, 'Pathfinder\'s Reward - Relief', NULL, 'A gift for adventurers who have especially provided high contributions in discovering the cause of the plague.', 'A gift for adventurers who have especially provided high contributions in discovering the cause of the plague.', 'etc_bead_silver_i00', 0);
INSERT INTO `all_items` VALUES (22337, 'Extra Entrance Pass - Rim Kamaloka', NULL, 'Entrance pass that allows you five addtional admissions. Can cancel the limit on entry if used while a limit on entry to Rim Kamaloka exists. Can only be used once per day from outside the instant zone. After use, the effect disappears at the corresponding instant dungeon\'s reset time. Cannot be exchanged or dropped.', 'Entrance pass that allows you five addtional admissions. Can cancel the limit on entry if used while a limit on entry to Rim Kamaloka exists. Can only be used once per day from outside the instant zone. After use, the effect disappears at the corresponding instant dungeon\'s reset time. Cannot be exchanged or dropped.', 'ticket_i00', 0);
INSERT INTO `all_items` VALUES (22338, 'Extra Entrance Pass - Rim Kamaloka 1 Sheet Pack', NULL, 'Wrapped pack containing an entrance pass that lets you enter Rim Kamaloka.', 'Wrapped pack containing an entrance pass that lets you enter Rim Kamaloka.', 'etc_pi_gift_box_i00', 0);
INSERT INTO `all_items` VALUES (22339, 'S84 Top-grade Weapon Chest', 'Event', 'The chest contains 1 S84 top-grade weapon. Which one could it be?', 'The chest contains 1 S84 top-grade weapon. Which one could it be?', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (22340, 'Elegia Armor Chest', 'Event', 'The chest contains 1 Elegia armor. Which one could it be?', 'The chest contains 1 Elegia armor. Which one could it be?', 'etc_pi_gift_box_i04', 0);
INSERT INTO `all_items` VALUES (22341, 'Scroll: Enchant Weapon - C Grade', NULL, 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_blessed_scrl_of_ench_wp_c_i02', 21);
INSERT INTO `all_items` VALUES (22342, 'Scroll: Enchant Weapon - C Grade', NULL, 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_weapon_i02', 19);
INSERT INTO `all_items` VALUES (22343, 'Scroll: Enchant Armor - C Grade', NULL, 'When enchanted, P. Def. increases by 1 for C-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'When enchanted, P. Def. increases by 1 for C-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_armor_i02', 20);
INSERT INTO `all_items` VALUES (22344, 'Scroll: Enchant Weapon - D Grade', NULL, 'When enchanted, P. Atk. increases by 2 for D-grade one-handed swords, one-handed blunts, daggers, spears, two-handed swords, two-handed blunts, dualswords, two-handed combat weapons, and other weapons. P. Atk. increases by 4 for bows. M. Atk. increases by 2 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'When enchanted, P. Atk. increases by 2 for D-grade one-handed swords, one-handed blunts, daggers, spears, two-handed swords, two-handed blunts, dualswords, two-handed combat weapons, and other weapons. P. Atk. increases by 4 for bows. M. Atk. increases by 2 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_weapon_i01', 19);
INSERT INTO `all_items` VALUES (22345, 'Scroll: Enchant Armor - D Grade', NULL, 'When enchanted, P. Def. increases by 1 for D-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'When enchanted, P. Def. increases by 1 for D-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_armor_i01', 20);
INSERT INTO `all_items` VALUES (22346, 'Enchantment Tool Box', NULL, 'A box of enchantment-related itmes. Double-click for a chance to receive an item. Cannot be exchanged or dropped.', 'A box of enchantment-related itmes. Double-click for a chance to receive an item. Cannot be exchanged or dropped.', 'etc_treasure_box_i07', 0);
INSERT INTO `all_items` VALUES (22347, 'Rune of Fate', NULL, 'Ancient characters which bestow a mysterious ability if it is possessed in the inventory. It increases acquired XP and SP by 200%. It will be removed from the inventory on June 15, 2011 when the event ends. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'Ancient characters which bestow a mysterious ability if it is possessed in the inventory. It increases acquired XP and SP by 200%. It will', 'br_cashtex.item.br_cash_rune_of_feather_i00', 33);
INSERT INTO `all_items` VALUES (24001, 'Support Power', NULL, 'Используется для добавления скила. Изменяет параметры персонажа. Возможно использовать только на основном классе.', 'Used to add a skill. Modifies character parameters. Can only be used on the main class.', 'br_cashtex.item.br_cash_lucky_box_i00', 0);
INSERT INTO `all_items` VALUES (24002, 'Seven Sing Prize', NULL, 'Используется для получения дополнительной награды за прохождение цепочки квестов.', 'Used to receive an additional reward for completing a quest chain.', 'br_cashtex.item.br_cash_lucky_box_i00', 0);
INSERT INTO `all_items` VALUES (25001, 'Newbie Coupon', NULL, 'Вы можете обменять эти купоны на разные расходные материалы в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'You can exchange these coupons for various consumables in the special shop (to access it, press Alt+B and select the \"Shop\" section).', 'etc_exchange_ticket_i00', 0);
INSERT INTO `all_items` VALUES (25002, 'Bonus Coin', NULL, 'Используйте эту монетку для покупок в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'Use this coin for purchases in the special shop (to access it, press Alt+B and select the \"Shop\" section).', 'etc_coin_of_fair_i00', 0);
INSERT INTO `all_items` VALUES (25003, 'Cooper Coin', 'Event', 'Медная монета. Используется в эвентах.', 'Copper Coin. Used in events.', 'etc_magic_coin_blood_i01', 0);
INSERT INTO `all_items` VALUES (25004, 'Silver Coin', 'Event', 'Серебрянная монета. Используется в эвентах. Равноценна 100 Cooper Coin.', 'Silver Coin. Used in events. Equivalent to 100 Copper Coins.', 'etc_magic_coin_silver_i01', 0);
INSERT INTO `all_items` VALUES (25005, 'Gold Coin', 'Event', 'Золотая монета. Используется в эвентах. Равноценна 100 Silver Coin или 10000 Cooper Coin.', 'Gold Coin. Used in events. Equivalent to 100 Silver Coins or 10,000 Copper Coins.', 'etc_magic_coin_gold_i01', 0);
INSERT INTO `all_items` VALUES (25006, 'Star of Honor', 'Event', 'Звезда за победы в эвенте TvT.', 'Star for victories in the TvT event.', 'etc_belt_deco_i00', 0);
INSERT INTO `all_items` VALUES (25007, 'Star of Honor', 'Event', 'Звезда за победы в эвенте CtF.', 'Star for victories in the CtF event.', 'etc_belt_deco_i01', 0);
INSERT INTO `all_items` VALUES (25008, 'Star of Honor', 'Event', 'Звезда за победы в эвенте Last Hero.', 'Star for victories in the Last Hero event.', 'etc_belt_deco_i02', 0);
INSERT INTO `all_items` VALUES (25009, 'Small Coin of Luck', NULL, 'Мелкая монета, служащая для покупки разных вещей в специальных магазинах. 30 таких монет равны 1 Coin of Luck.', 'Small coin used to purchase various items in special shops. 30 of these coins are equal to 1 Coin of Luck.', 'etc_coins_silver_i00', 0);
