INSERT INTO `all_items` VALUES (25041, 'Mystery Scroll 1', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i00', 0);
INSERT INTO `all_items` VALUES (25042, 'Mystery Scroll 2', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i01', 0);
INSERT INTO `all_items` VALUES (25043, 'Mystery Scroll 3', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i02', 0);
INSERT INTO `all_items` VALUES (25044, 'Mystery Scroll 4', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i03', 0);
INSERT INTO `all_items` VALUES (25045, 'Mystery Scroll 5', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i04', 0);
INSERT INTO `all_items` VALUES (25046, 'Mystery Scroll 6', NULL, 'Загадочный свиток, извлеченный из Demon\'s Gate. Соберите их все, для того чтобы выполнить поручение Alexandri.', 'Mysterious scroll extracted from Demon\'s Gate. Collect them all to complete the task for Alexandri.', 'etc_charm_of_courage_i05', 0);
INSERT INTO `all_items` VALUES (25047, 'Mystery Book', NULL, 'Загадочная книга, в которую превратились свитки, извлеченные из Demon\'s Gate. Отнесите ее Alexandri.', 'Mysterious book that the scrolls extracted from Demon\'s Gate have transformed into. Deliver it to Alexandri.', 'etc_summon_subjob_skillbook_i00', 0);
INSERT INTO `all_items` VALUES (25048, 'Dimensional Stone', NULL, 'Камень, который создала Alexandri. Дает возможность использовать врата рядом с ней для перемещения в цитадели демонов.', 'Stone created by Alexandri. Allows the use of gates near her for transportation in the demon citadel.', 'etc_capture_stone_i00', 0);
INSERT INTO `all_items` VALUES (25049, 'Demon\'s Badge', NULL, 'Знак, снятый с тела демона. Его можно обменять у Alexandri на разные товары.', 'Mark removed from the body of a demon. Can be exchanged with Alexandri for various goods.', 'etc_ketra_badge_grunt_i00', 0);
INSERT INTO `all_items` VALUES (25050, 'Soul Crystal', 'Low Grade', 'Кристалл низкого качества, с заключенной внутри душой. Его можно обменять у Alexandri на редкий товар. Нельзя передать или выбросить.', 'Low-quality crystal containing a soul inside. Can be exchanged with Alexandri for a rare item. Cannot be transferred or discarded.', 'etc_crystal_cave_crystal_i00', 0);
INSERT INTO `all_items` VALUES (25051, 'Soul Crystal', 'Medium Grade', 'Кристалл среднего качества, с заключенной внутри душой. Его можно обменять у Alexandri на редкий товар. Нельзя передать или выбросить.', 'Medium-quality crystal containing a soul inside. Can be exchanged with Alexandri for a rare item. Cannot be transferred or discarded.', 'etc_crystal_cave_crystal_i01', 0);
INSERT INTO `all_items` VALUES (25052, 'Soul Crystal', 'High Grade', 'Кристалл высокого качества, с заключенной внутри душой. Его можно обменять у Alexandri на редкий товар. Нельзя передать или выбросить.', 'High-quality crystal containing a soul inside. Can be exchanged with Alexandri for a rare item. Cannot be transferred or discarded.', 'etc_crystal_cave_crystal_i02', 0);
INSERT INTO `all_items` VALUES (25053, 'Soul Crystal', 'Top Grade', 'Кристалл высочайшего качества, с заключенной внутри душой. Его можно обменять у Alexandri на редкий товар. Нельзя передать или выбросить.', 'Highest-quality crystal containing a soul inside. Can be exchanged with Alexandri for a rare item. Cannot be transferred or discarded.', 'etc_crystal_cave_crystal_i03', 0);
INSERT INTO `all_items` VALUES (25054, 'Treasure Chest Key', NULL, 'Ключ, при помощи которого можно открыть сундук, находящийся где-то в цитадели демонов.', 'Key that can be used to open a chest located somewhere in the demon citadel.', 'etc_skeleton_key_i00', 0);
INSERT INTO `all_items` VALUES (25071, 'Attribute Crystal', 'Event', 'Кристалл, при помощи которого можно вставить в подходящую броню все 6 атрибутов максимального уровня.', 'Crystal that allows you to insert all 6 attributes of maximum level into suitable armor.', 'etc_crystal_cave_crystal_i02', 0);
INSERT INTO `all_items` VALUES (25101, 'Newbie Support Pack', NULL, 'Эта коробка содержит внутри себя разные предметы, которые смогут помочь новичкам.', 'This box contains various items that can help newcomers.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (25102, 'Newbie Support Pack', 'Premium', 'Эта коробка содержит внутри себя разные предметы, которые смогут помочь новичкам.', 'This box contains various items that can help newcomers.', 'etc_exchange_box_i00', 0);
INSERT INTO `all_items` VALUES (25103, 'Newbie Coupon (Weapon)', NULL, 'Вы можете обменять эти купоны на временное оружие разного уровня в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'You can exchange these coupons for temporary weapons of various levels in the special shop (to access it, press Alt+B and select the \"Shop\" section).', 'etc_exchange_ticket_i01', 0);
INSERT INTO `all_items` VALUES (25104, 'Newbie Coupon (Armor)', NULL, 'Вы можете обменять эти купоны на сеты временной брони разного уровня в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'You can exchange these coupons for sets of temporary armor of various levels in the special shop (to access it, press Alt+B and select the \"Shop\" section).', 'etc_exchange_ticket_i02', 0);
INSERT INTO `all_items` VALUES (25105, 'Newbie Coupon (Accessory)', NULL, 'Вы можете обменять эти купоны на временную бижутерию разного уровня в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'You can exchange these coupons for temporary jewelry of various levels in the special shop (to access it, press Alt+B and select the \"Shop\" section).', 'etc_exchange_ticket_i03', 0);
INSERT INTO `all_items` VALUES (25201, 'Cloak of Destruction', 'Shield Master', 'Искусно отделанный плащ. При одевании дает +2% к физической защите и +3% к эффективности лечения. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Phoenix Knight, Hell Knight, Eva\'s Templar, Shillen Templar. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to physical defense and +3% to healing effectiveness. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Phoenix Knight, Hell Knight, Eva\'s Templar, Shillen Templar. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25202, 'Cloak of Destruction', 'Bow Master', 'Искусно отделанный плащ. При одевании дает +2% к скорости атаки луком/арбалетом и +2 к точности. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Sagittarius, Moonlight Sentinel, Ghost Sentinel, Trickster. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to bow/crossbow attack speed and +2 to accuracy. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Sagittarius, Moonlight Sentinel, Ghost Sentinel, Trickster. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25203, 'Cloak of Destruction', 'Enchanter', 'Искусно отделанный плащ. При одевании дает +2% к скорости каста и -3% к потреблению MP магическими умениями. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Hierophant, Judicator, Dominator, Doom Cryer. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to casting speed and -3% to MP consumption for magical skills. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Hierophant, Judicator, Dominator, Doom Cryer. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25204, 'Cloak of Destruction', 'Healer', 'Искусно отделанный плащ. При одевании дает +2% к скорости каста и +3% к эффективности лечащих умений. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Cardinal, Eva\'s Saint, Shillien Saint. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to casting speed and +3% to healing skill effectiveness. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Cardinal, Eva\'s Saint, Shillien Saint. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25205, 'Cloak of Destruction', 'Dagger Master', 'Искусно отделанный плащ. При одевании дает +2% к скорости атаки даггерами/двойными даггерами и +3% к шансу критической атаки. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Adventurer, Wind Rider, Ghost Hunter. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to dagger/double dagger attack speed and +3% to critical hit chance. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Adventurer, Wind Rider, Ghost Hunter. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25206, 'Cloak of Destruction', 'Weapon Master', 'Искусно отделанный плащ. При одевании дает +2% к физической атаке и +3% к силе критической атаки. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Dreadnought, Titan, Fortune Seeker, Doombringer, Soul Hound, Maestro. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to physical attack and +3% to critical hit power. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Dreadnought, Titan, Fortune Seeker, Doombringer, Soul Hound, Maestro. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25207, 'Cloak of Destruction', 'Summoner', 'Искусно отделанный плащ. При одевании дает +2% к скорости каста и +3% к регенерации MP. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Arcana Lord, Elemental Master, Spectral Master. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to casting speed and +3% to MP regeneration. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Arcana Lord, Elemental Master, Spectral Master. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25208, 'Cloak of Destruction', 'Wizard', 'Искусно отделанный плащ. При одевании дает +2% к магической атаке и -3% к потреблению MP магическими умениями. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Archmage, Mystic Muse, Storm Screamer, Soul Taker. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to magical attack and -3% to MP consumption for magical skills. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Archmage, Mystic Muse, Storm Screamer, Soul Taker. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25209, 'Cloak of Destruction', 'Force Master', 'Искусно отделанный плащ. При одевании дает +2% к физической атаке и -3% к потреблению MP физическими умениями. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Duelist, Grand Khavatari. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to physical attack and -3% to MP consumption for physical skills. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Duelist, Grand Khavatari. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25210, 'Cloak of Destruction', 'Bard', 'Искусно отделанный плащ. При одевании дает +2% к физической защите и -3% к потреблению MP песнями и танцами. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Плащ могут одеть только следующие классы: Sword Muse, Spectral Dancer. Нельзя модифицировать, придать стихийные свойства и зачаровать. Нельзя обменять/выбросить.', 'Skillfully crafted cloak. When worn, it gives +2% to physical defense and -3% to MP consumption for songs and dances. The cloak slot opens after equipping a full armor set of at least Dynasty level. Only the following classes can wear it: Sword Muse, Spectral Dancer. Cannot be modified, imbued with elemental properties, or enchanted. Cannot be exchanged/discarded.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25211, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: белый с черным. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: white with black. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25212, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: зеленый с фиолетовым. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: green with purple. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25213, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: розовый с фиолетовым. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: pink with purple. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25214, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: белый с голубым. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: white with blue. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25215, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: красный с черным. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: red with black. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25216, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: черный с красным. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: black with red. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25217, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: белый с темно синим. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: white with dark blue. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25218, 'Cloak of Destruction', NULL, 'Искусно отделанный плащ. Цвет: голубой с черным. Слот для плаща открывается после облачения в полный комплект брони, не ниже Dynasty. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Skillfully crafted cloak. Color: blue with black. The cloak slot opens after equipping a full armor set of at least Dynasty level. Cannot be modified, imbued with elemental properties, or enchanted.', 'vesper_cloack_i00', 0);
INSERT INTO `all_items` VALUES (25219, 'Sealed Cloak of Destruction', NULL, 'Запечатанный плащ для персонажей высоких уровней. Печать можно снять у Ольфа Каноре или у Ольфа Адамса. До снятия печати использовать нельзя. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'Sealed cloak for high-level characters. The seal can be removed by Olfa Kanore or Olfa Adams. Cannot be used until the seal is removed. Cannot be modified, imbued with elemental properties, or enchanted.', 'sealed_vesper_cloack_i01', 0);
INSERT INTO `all_items` VALUES (25220, 'Elemental Crystal', NULL, 'Позволяет изменить тип элементального атрибута в вашем оружии. Для использования сделайте двойной щелчок по кристаллу.', 'Allows you to change the type of elemental attribute in your weapon. To use, double-click on the crystal.', 'change_elemental_crystal', 0);
