INSERT INTO `all_items` VALUES (25310, 'Alternative Moirai Breastplate', NULL, 'Редкий предмет, увеличивает Физ. Атк., Скор. Атк. и сопротивление Огню/Воде/Ветру/Земле и шоку.', 'Rare item that increases Physical Attack, Attack Speed, and resistance to Fire/Water/Wind/Earth and Shock.', 'armor_t501_u_i00', 0);
INSERT INTO `all_items` VALUES (25311, 'Alternative Moirai Gaiter', NULL, 'Редкий предмет, увеличивает Физ. Атк., Скор. Атк., сопротивление шоку и воде.', 'Rare item that increases Physical Attack, Attack Speed, Shock resistance, and Water resistance.', 'armor_t501_l_i00', 0);
