INSERT INTO `all_items` VALUES (25710, 'Sylphen Bow', NULL, 'Дает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot.', 'Grants the ability to gain one of the following special properties: Focus, Critical Slow, Cheap Shot.', 'misceoh.icons.bow0', 7);
INSERT INTO `all_items` VALUES (25711, 'Azerian Rapier', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Narsil BladeДает возможность получить одно из следующих особых свойств: Health, Focus, Haste.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade. Grants the ability to gain one of the following special properties: Health, Focus, Haste. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier0', 7);
INSERT INTO `all_items` VALUES (25712, 'Kuhn Blade', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Mechanic SawДает возможность получить одно из следующих особых свойств:  Health, Focus, Haste.', 'Exclusive weapon of the Kamael: Conversion of Mechanic Saw. Grants the ability to gain one of the following special properties: Health, Focus, Haste.', 'misceoh.icons.ancientsword0', 7);
INSERT INTO `all_items` VALUES (25713, 'Nexium Claw', NULL, 'Эксклюзивное оружие Камаэль: Конверсия Sylphen BowДает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot.', 'Exclusive weapon of the Kamael: Conversion of Sylphen Bow. Grants the ability to gain one of the following special properties: Focus, Critical Slow, Cheap Shot.', 'misceoh.icons.crossbow0', 7);
INSERT INTO `all_items` VALUES (25714, 'Phasian Dual Daggers', NULL, 'Парные кинжалы. При модификации Физ. Атк. усиливается больше, чем у одиночного кинжала. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 85-го уровня и выше. Наносит дополнительный урон в PvP.', 'Twin daggers. When modified, Physical Attack is enhanced more than with a single dagger. When modified to +4 or higher, the chance of Critical Attack increases by 109. Used by Dagger users level 85 and above. Deals additional damage in PvP.', 'misceoh.icons.dualdagger', 7);
INSERT INTO `all_items` VALUES (25715, 'Narsil Blade*Hellblade', NULL, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.,Наносит дополнительный урон в PvP.', 'Twin swords, two-handed swords, two-handed blunt weapons, and fist weapons will have increased attack compared to one-handed swords. When modified to +4 or higher, Critical Attack increases by 109 and Max HP by 10%. Deals additional damage in PvP.', 'misceoh.icons.dualsword', 7);
INSERT INTO `all_items` VALUES (25716, 'Narsil Blade', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Critical Attack Chance +134. Deals additional damage in PvP.', 'misceoh.icons.magicsword1', 7);
INSERT INTO `all_items` VALUES (25717, 'Narsil Blade', 'Haste', '<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Attack Speed +11%. Deals additional damage in PvP.', 'misceoh.icons.magicsword1', 7);
INSERT INTO `all_items` VALUES (25718, 'Narsil Blade', 'Health', '<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Max HP +25%. Deals additional damage in PvP.', 'misceoh.icons.magicsword1', 7);
INSERT INTO `all_items` VALUES (25719, 'Phasian Edge', 'Haste', '<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Attack Speed +11%. Deals additional damage in PvP.', 'misceoh.icons.dagger1', 7);
INSERT INTO `all_items` VALUES (25720, 'Phasian Edge', 'Critical Damage', '<Свойство Кристалла Души>Физ. Атк. при Крит. ударе +1060. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Physical Attack on Critical Hit +1060. Deals additional damage in PvP.', 'misceoh.icons.dagger1', 7);
INSERT INTO `all_items` VALUES (25721, 'Phasian Edge', 'HP Drain', '<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> 4% of the damage dealt is added to your HP. Deals additional damage in PvP.', 'misceoh.icons.dagger1', 7);
