INSERT INTO `all_items` VALUES (25740, 'Herencia Staff', 'Magic Hold', '<Свойство Кристалла Души>Дает шанс 6% колдовства Корня Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Grants a 6% chance of Druid\'s Root Curse when using a harmful skill on the target. Deals additional damage in PvP.', 'misceoh.icons.2hmagicblunt1', 7);
