INSERT INTO `all_items` VALUES (25746, 'Sylphen Bow', 'Critical Slow', '<Свойство Кристалла Души>Существует 44% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> 44% chance to apply Slow on Critical Attack. Deals additional damage in PvP.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25747, 'Sylphen Bow', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1.Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Gives an 8% chance to reduce MP consumption to 1 on a normal attack. Deals additional damage in PvP.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25748, 'Sylphen Bow', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP.', '<Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25749, 'Azerian Rapier', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25750, 'Azerian Rapier', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Скор. Атк. + 11%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Attack Speed +11%. Deals additional damage in PvP. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25751, 'Azerian Rapier', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Max HP +25%. Deals additional damage in PvP. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
