INSERT INTO `all_items` VALUES (25795, 'Twister Cigonia {PvP}', 'Mana Up', '<Свойство Кристалла Души>Макс. МР увеличивается на 30%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> Max MP increased by 30%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25796, 'Twister Cigonia {PvP}', 'Acumen', '<Свойство Кристалла Души>Увеличение Скор. Магии на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> Increases Magic Speed by 15%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25797, 'Twister Cigonia {PvP}', 'MP Regeneration', '<Свойство Кристалла Души>Скорость регенерации МР 2. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> MP regeneration speed 2. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25798, 'Herencia Staff {PvP}', 'Magic Hold', '<Свойство Кристалла Души>Дает шанс 20% колдовства Корня Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> Grants a 20% chance of Druid\'s Root Curse when using a harmful skill on the target. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.2hmagicblunt1', 7);
INSERT INTO `all_items` VALUES (25799, 'Herencia Staff {PvP}', 'Empower', '<Свойство Кристалла Души>Увеличивает Маг. Атк. на 177. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> Increases Magical Attack by 177. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.2hmagicblunt1', 7);
