INSERT INTO `all_items` VALUES (25804, 'Sylphen Bow {PvP}', 'Critical Slow', '<Свойство Кристалла Души>Существует 44% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> 44% chance to apply Slow on Critical Attack. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25805, 'Sylphen Bow {PvP}', 'Cheap Shot', '<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1.', '<Soul Crystal Property> Gives an 8% chance to reduce MP consumption to 1 on a normal attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25806, 'Sylphen Bow {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', '<Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25807, 'Azerian Rapier {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP and gives a chance to restore CP when the character is attacked. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25808, 'Azerian Rapier {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Attack Speed +11%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25809, 'Azerian Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Max HP +25%. Deals additional damage in PvP and gives a chance to restore CP when the character is attacked. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
