INSERT INTO `all_items` VALUES (25837, 'Phasian Edge - Gale', 'HP Drain', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP.', 'Rare item that increases Attack Speed. <Soul Crystal Property> 4% of the damage dealt is added to your HP. Deals additional damage in PvP.', 'misceoh.icons.dagger1', 7);
INSERT INTO `all_items` VALUES (25838, 'Herugrim Mace - Landslide', 'HP Regeneration', 'Редкий предмет, усиливающий эффект оглушения при атаке.<Свойство Кристалла Души>Ускоряет восстановление HP на 5. Наносит дополнительный урон в PvP.', 'Rare item that enhances the stun effect when attacking. <Soul Crystal Property> Accelerates HP recovery by 5. Deals additional damage in PvP.', 'misceoh.icons.1hblunt1', 7);
