INSERT INTO `all_items` VALUES (25855, 'Twister Cigonia - Cleverness', 'MP Regeneration', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Скорость регенерации МР 2. Наносит дополнительный урон в PvP.', 'Rare item that increases MP recovery speed. <Soul Crystal Property> MP regeneration speed 2. Deals additional damage in PvP.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25856, 'Herencia Staff - Hail', 'Magic Hold', 'Редкий предмет, увеличивающий Маг. Атк.<Свойство Кристалла Души>Дает шанс 6% колдовства Корня Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP.', 'Rare item that increases Magical Attack. <Soul Crystal Property> Grants a 6% chance of Druid\'s Root Curse when using a harmful skill on the target. Deals additional damage in PvP.', 'misceoh.icons.2hmagicblunt1', 7);
