INSERT INTO `all_items` VALUES (25894, 'Phasian Edge - Gale {PvP}', 'Critical Damage', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Физ. Атк. при Крит. ударе +1060. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Rare item that increases Attack Speed. <Soul Crystal Property> Physical Attack on Critical Hit +1060. Deals additional damage in PvP. Gives a chance to remove one or more positive effects from the enemy when attacking, as well as reduce their Shield Defense.', 'misceoh.icons.dagger1', 7);
INSERT INTO `all_items` VALUES (25895, 'Phasian Edge - Gale {PvP}', 'HP Drain', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>4% от нанесенного урона прибавляются к вашим HP. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'Rare item that increases Attack Speed. <Soul Crystal Property> 4% of the damage dealt is added to your HP. Deals additional damage in PvP. Gives a chance to remove one or more positive effects from the enemy when attacking, as well as reduce their Shield Defense.', 'misceoh.icons.dagger1', 7);
INSERT INTO `all_items` VALUES (25896, 'Herugrim Mace - Landslide {PvP}', 'HP Regeneration', 'Редкий предмет, усиливающий эффект оглушения при атаке.<Свойство Кристалла Души>Ускоряет восстановление HP на 5. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'Rare item that enhances the stun effect when attacking. <Soul Crystal Property> Accelerates HP recovery by 5. Deals additional damage in PvP and gives a chance to restore CP when the character is attacked.', 'misceoh.icons.1hblunt1', 7);
