INSERT INTO `all_items` VALUES (25909, 'Goddes Callier - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item that increases Critical Attack Chance. <Soul Crystal Property> Max HP +25%. Deals additional damage in PvP. Gives a chance to deal additional damage when attacking.', 'misceoh.icons.pole1', 7);
INSERT INTO `all_items` VALUES (25910, 'Goddes Callier - Thunder {PvP}', 'Guidance', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Точность 8. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item that increases Critical Attack Chance. <Soul Crystal Property> Accuracy +8. Deals additional damage in PvP. Gives a chance to deal additional damage when attacking.', 'misceoh.icons.pole1', 7);
INSERT INTO `all_items` VALUES (25911, 'Twister Cigonia - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Макс. МР увеличивается на 30%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases MP recovery speed. <Soul Crystal Property> Max MP increased by 30%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25912, 'Twister Cigonia - Cleverness {PvP}', 'Acumen', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Увеличение Скор. Магии на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases MP recovery speed. <Soul Crystal Property> Increases Magic Speed by 15%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25913, 'Twister Cigonia - Cleverness {PvP}', 'MP Regeneration', 'Редкий предмет, увеличивает скорость восстановления MP.<Свойство Кристалла Души>Скорость регенерации МР 2. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases MP recovery speed. <Soul Crystal Property> MP regeneration speed 2. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.magicblunt1', 7);
INSERT INTO `all_items` VALUES (25914, 'Herencia Staff - Hail {PvP}', 'Magic Hold', 'Редкий предмет, увеличивающий Маг. Атк.<Свойство Кристалла Души>Дает шанс 20% колдовства Корня Дриады при использовании вредоносного умения на цель. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases Magical Attack. <Soul Crystal Property> Grants a 20% chance of Druid\'s Root Curse when using a harmful skill on the target. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.2hmagicblunt1', 7);
INSERT INTO `all_items` VALUES (25915, 'Herencia Staff - Hail {PvP}', 'Empower', 'Редкий предмет, увеличивающий Маг. Атк.<Свойство Кристалла Души>Увеличивает Маг. Атк. на 177. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases Magical Attack. <Soul Crystal Property> Increases Magical Attack by 177. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.2hmagicblunt1', 7);
