INSERT INTO `all_items` VALUES (25919, 'Terakan Sword - Cleverness {PvP}', 'Acumen', 'Редкий предмет, увеличивает скорость восстановления MP<Свойство Кристалла Души>Увеличение Скор. Магии на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении урона.', 'Rare item that increases MP recovery speed. <Soul Crystal Property> Increases Magic Speed by 15%. Deals additional damage in PvP. Has a certain chance to increase Magic Speed when taking damage.', 'misceoh.icons.1hsword1', 7);
INSERT INTO `all_items` VALUES (25920, 'Sylphen Bow - Clairvoyance {PvP}', 'Critical Slow', 'Редкий предмет, увеличивающий дальность атаки.<Свойство Кристалла Души>Существует 44% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases attack range. <Soul Crystal Property> 44% chance to apply Slow on Critical Attack. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25921, 'Sylphen Bow - Clairvoyance {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивающий дальность атаки.<Свойство Кристалла Души>При обычной атаке дает 8% шанс уменьшить расход MP до 1.', 'Rare item that increases attack range. <Soul Crystal Property> Gives an 8% chance to reduce MP consumption to 1 on a normal attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25922, 'Sylphen Bow - Clairvoyance {PvP}', 'Focus', 'Редкий предмет, увеличивающий дальность атаки.<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'Rare item that increases attack range. <Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP. Has a certain chance to restore CP during an attack.', 'misceoh.icons.bow1', 7);
INSERT INTO `all_items` VALUES (25923, 'Azerian Rapier - Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item that increases Critical Attack Chance. Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Critical Attack Chance +139. Deals additional damage in PvP and gives a chance to restore CP when the character is attacked. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25924, 'Azerian Rapier - Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item that increases Critical Attack Chance. Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Attack Speed +11%. Deals additional damage in PvP. Has a certain chance to restore CP during an attack. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25925, 'Azerian Rapier - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'Rare item that increases Critical Attack Chance. Exclusive weapon of the Kamael: Conversion of Narsil Blade <Soul Crystal Property> Max HP +25%. Deals additional damage in PvP and gives a chance to restore CP when the character is attacked. When modified to +4 or higher, it gives a chance to increase Physical Attack, Magical Attack, healing power on critical hits; reduces MP consumption when using skills for you and your party members.', 'misceoh.icons.rapier1', 7);
INSERT INTO `all_items` VALUES (25926, 'Kuhn Blade - Gale {PvP}', 'Focus', 'Редкий предмет, увеличивающий Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Mechanic Saw<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'Rare item that increases Attack Speed. Exclusive weapon of the Kamael: Conversion of Mechanic Saw <Soul Crystal Property> Critical Attack Chance +134. Deals additional damage in PvP. Gives a chance to deal additional damage when attacking.', 'misceoh.icons.ancientsword1', 7);
