INSERT INTO `all_items` VALUES (30625, 'Talisman - Critical Reduction', NULL, 'При одевании уменьшает величину критических повреждений на 5%. Эффект не суммируется при использовании дополнительного талисмана такого же типа. Временный предмет, нельзя обменять/выбросить.', 'When worn, reduces the amount of critical damage by 5%. The effect does not stack when using an additional talisman of the same type. Temporary item, cannot be traded/discarded.', 'r_talisman_cm_up_passive', 0);
